local P = LoreForeverPacks.Begin("LoreForever_Lang_ptBR")
P.entries["npc:einar-stonegrip"] = {n="Einar Pegapétrea",s="Einar Pegapétrea é um caçador de peles anão estabelecido no cruzamento principal do Pantanal. Em vez de arriscar um reencontro desconfortável com sua esposa afastada no Porto de Menethil, ele conta com aventureiros de passagem para transportar suas peles de crocolisco até a cidade.",h="Einar Pegapétrea é um caçador de peles anão estabelecido no cruzamento principal do Pantanal.",kw={"crocolisco","einar pegapétrea","iago halberque","porto de menethil","cida","peles","caçador de peles","pântanos"},ang={["faction:Alliance"]="Viajantes que se deslocam entre Altaforja e o Porto de Menethil costumam passar pelo posto de beira de estrada de Einar, garantindo trabalho fácil de mensageiro pelas rotas de suprimentos da Aliança.",["race:Dwarf"]="Einar reflete a autossuficiência rústica comum entre os montanheses anões, ainda que seus problemas conjugais o levem a dormir nos pântanos ensopados em vez de uma taverna acolhedora."},sec={{t="Um Caçador de Peles na Encruzilhada",b="Instalado no cruzamento central que conecta Dun Algaz, Dun Modr e o Porto de Menethil, Einar Pegapétrea ganha a vida enfrentando os pântanos encharcados do Pantanal. Ele caça os crocoliscos locais por seus couros resistentes, abastecendo coureiros e mercadores ao longo da costa. Embora rústico o bastante para lutar contra répteis em meio ao lamaçal, ele é totalmente intimidado por conflitos domésticos. Envolvido em um rompimento amargo com sua esposa, Cida, Einar permanece na estrada, contratando viajantes para entregar seus fardos de peles ao seu parceiro comercial Iago Halberque em vez de pisar pessoalmente no Porto de Menethil."}},faq={{q="Quem é Einar Pegapétrea?",a="Einar Pegapétrea é um esfolador e caçador anão estabelecido na encruzilhada do Pantanal. Ele ganha a vida recolhendo couros de crocolisco para vender no Porto de Menethil.",al={"quem é einar","história de einar pegapétrea","anão da encruzilhada dos pântanos"}},{q="Por que Einar não entrega suas próprias mercadorias no Porto de Menethil?",a="Einar está em péssimos termos com sua esposa, Cida, que reside no Porto de Menethil. Para evitar encarar a fúria dela, ele prefere permanecer pelos pântanos e pagar mensageiros de passagem para entregar suas mercadorias.",al={"por que einar não vai para a cidade","esposa de einar pegapétrea","por que contratar aventureiros"}},{q="Com quem Einar trabalha no Porto de Menethil?",a="Einar coleta peles de crocolisco sob contrato para Iago Halberque, um mercador no Porto de Menethil encarregado da distribuição e venda de artigos de couro.",al={"parceiro de negócios de einar","quem compra as peles de einar","conexão com iago halberque"}}},fx={["2e6b6b46"]={q="De que lado está Einar Pegapétrea?",a="Einar é leal a Altaforja e à Aliança. Estacionado ao longo da encruzilhada do Pantanal, ele trabalha ao lado de seus companheiros montanhistas e fornece bens comerciais para o assentamento portuário de Menethil.",al={"facção de einar pegapétrea","a quem einar pegapétrea serve","einar é da aliança ou da horda"}},["61290d18"]={q="O que Einar Pegapétrea quer?",a="Einar quer manter seus negócios fornecendo couros de crocolisco para Iago Halberque no Porto de Menethil sem ter que ir lá pessoalmente. Ele está ansioso para encontrar viajantes de passagem dispostos a entregar os pacotes em seu nome para que ele possa adiar ter que enfrentar sua esposa, Cida.",al={"o que einar quer","objetivo de einar pegapétrea","motivação da missão de einar pegapétrea"}}},fp="15,245,27.596.0,23.165.0,57.206.0,44.147.0"}
P.entries["npc:eitrigg"] = {n="Eitrigg",s="Eitrigg é um veterano experiente da Primeira e Segunda Guerras que permanece ao lado do Chefe de Guerra Thrall como um estimado conselheiro em Orgrimmar. Outrora um guerreiro do clã Blackrock, ele se desiludiu com a antiga Horda demoníaca e viveu no exílio até que uma amizade extraordinária com um paladino humano mudou seu destino. Hoje, ele ajuda a guiar a Nova Horda de volta às suas raízes de honra e xamanismo.",h="Eitrigg é um veterano experiente da Primeira e Segunda Guerras que permanece ao lado do Chefe de Guerra...",kw={"clã rocha negra","sangue e honra","eitrigg","grommash hold","amparo","orgrim martelo da perdição","orgrimmar","stratholme","thrall","tirion fordring"},ang={["class:Paladin"]="A história de Eitrigg e Tirion Fordring é famosa entre os paladinos como o teste definitivo entre o dever e a honra justa.",["class:Warrior"]="Eitrigg representa a honra marcial preservada através de décadas de tragédia, tendo sobrevivido a duas guerras através de pura força e disciplina inabalável.",["faction:Horde"]="Eitrigg serve como a memória institucional viva da Horda, permanecendo ao lado de Thrall para garantir que os erros do passado manchado por demônios nunca mais se repitam.",["race:Orc"]="Para os orcs de Durotar, Eitrigg é um ancião venerado cuja herança Blackrock prova que qualquer orc pode abraçar a honra e redimir o legado de seu povo."},sec={{t="Um Veterano da Antiga Horda",b="Nascido em Draenor no clã Blackrock, Eitrigg lutou pela Horda ao longo da Primeira e Segunda Guerras. As batalhas terríveis e a derrota final da Horda na Segunda Guerra o forçaram a confrontar o quanto seu povo havia caído na sede de sangue e na corrupção demoníaca. Enjoado com o que a Horda havia se tornado, Eitrigg afastou-se dos remanescentes dispersos e refugiou-se em um exílio autoimposto, buscando apenas solidão nas terras selvagens de Lordaeron."},{t="Sangue e Honra",b="Anos após o início de seu exílio na natureza, Eitrigg foi descoberto abrigando-se em uma torre abandonada perto de Amparo pelo paladino humano Tirion Fordring. O confronto inicial entre eles fez ruir as ruínas, mas em vez de acabar com o humano inconsciente, Eitrigg o puxou dos escombros para a segurança. Conmovido por essa demonstração de pura honra marcial, Tirion fez um juramento de amizade e se recusou a trair a localização do eremita. Quando as autoridades locais da Aliança finalmente capturaram Eitrigg e o condenaram à forca em Stratholme, Tirion abriu mão de seu próprio título de cavaleiro, de suas terras e de sua liberdade em um ataque para resgatar o orc condenado. Esse laço lendário provou a ambos os guerreiros que a honra transcendia o ódio amargo entre suas espécies."},{t="Conselheiro do Chefe de Guerra",b="Durante a tentativa desesperada de Tirion de libertar Eitrigg em Stratholme, a Horda recém-unida de Thrall invadiu a cidade e resgatou o guerreiro veterano. Conhecer Thrall convenceu Eitrigg de que os orcs estavam se livrando da mácula demoníaca e redescobrindo sua herança xamânica ancestral. Retornando com Thrall através do Grande Oceano para Kalimdor, Eitrigg assumiu um posto reverenciado no Vale da Sabedoria dentro de Orgrimmar. Ele agora permanece dentro de Grommash Hold como conselheiro do jovem Chefe de Guerra, ajudando a avaliar novos recrutas e transmitindo sua sabedoria duramente conquistada para que a Nova Horda nunca repita as tragédias do passado."}},faq={{q="Quem é Eitrigg?",a="Eitrigg é um guerreiro orc Blackrock idoso e um veterano da Primeira e Segunda Guerras. Hoje, ele reside em Grommash Hold em Orgrimmar como um confiável conselheiro do Chefe de Guerra Thrall.",al={"quem é eitrigg","história de eitrigg","orc ao lado de thrall"}},{q="Por que Eitrigg considera um humano como seu irmão?",a="Enquanto vivia no exílio em Lordaeron, Eitrigg salvou a vida do paladino Tirion Fordring durante um duelo que derrubou uma torre de pedra. Em retribuição, Tirion defendeu a localização de Eitrigg e mais tarde lutou contra seu próprio povo em Stratholme para impedir a execução de Eitrigg, perdendo seu título e terras no processo. Unidos pela honra mútua, Eitrigg vê Tirion como seu irmão.",al={"eitrigg e tirion","amigo humano de eitrigg","sangue e honra"}},{q="A qual clã Eitrigg pertence?",a="Eitrigg pertence ao clã Blackrock. Ele lutou durante as guerras antigas, embora tenha abandonado os remanescentes corruptos da Horda após ver a corrupção demoníaca que os havia guiado.",al={"clã de eitrigg","eitrigg é rocha negra"}},{q="Por que Eitrigg deixou a antiga Horda?",a="Após a derrota da Horda na Segunda Guerra, Eitrigg viu que seu povo havia perdido a honra para a sede de sangue e a corrupção demoníaca. Ele partiu enojado, buscando um lugar tranquilo para morrer em vez de servir a uma máquina de guerra corrupta.",al={"por que eitrigg partiu","exílio de eitrigg"}},{q="Como Eitrigg foi parar em Orgrimmar?",a="Quando forças da Aliança capturaram Eitrigg e se prepararam para executá-lo em Stratholme, Thrall e suas forças atacaram a cidade e o libertaram. Vendo o compromisso de Thrall com a honra e a redescoberta do xamanismo, Eitrigg escolheu seguir o jovem Chefe de Guerra até Kalimdor.",al={"como eitrigg conheceu thrall","eitrigg resgatado"}},{q="Qual papel Eitrigg desempenha em Orgrimmar no momento?",a="Eitrigg aconselha Thrall diretamente dentro de Grommash Hold e auxilia a testar e avaliar novos recrutas que juram lealdade à Nova Horda.",al={"missão de eitrigg","o que eitrigg faz"}}},fx={f3c80f4d={q="O que Eitrigg quer?",a="Eitrigg quer ver a raça orc guiar-se com honra em vez de repetir os erros sombrios de seu passado. Após testemunhar a decepção do Conselho das Sombras e viver no exílio, ele agora dedica seus anos restantes a aconselhar o Chefe Guerreiro Thrall e a preparar uma nova geração disciplinada e ética de guerreiros da Horda para salvaguardar seu lar.",al={"quais são os objetivos de eitrigg","motivo de eitrigg","o que eitrigg espera"}},["53b3cb4d"]={q="De que lado Eitrigg está?",a="Eitrigg é totalmente dedicado à nova Horda de Thrall. Embora outrora tenha lutado pela antiga Horda sanguinária, ele a abandonou após ver a corrupção por trás de sua cruzada demoníaca. Hoje, ele se posiciona ao lado de Thrall em Grommash Hold como um conselheiro e guardião leal, acreditando nessa nova visão xamânica de honra e redenção para o povo órfico.",al={"facção de eitrigg","a quem eitrigg serve","eitrigg é leal a thrall"}},["46467f44"]={q="Por que Eitrigg é famoso?",a="Eitrigg é renomado entre os veteranos como um guerreiro Rocha Negra que lutou tanto na Primeira quanto na Segunda Guerra. Sua sobrevivência, seu dramático resgate da execução em Stratholme e seu profundo laço de honra com o paladino humano Tirion Fordring consolidaram seu lugar na lenda.",al={"por que eitrigg é conhecido","o que tornou eitrigg famoso","história de eitrigg na guerra"}}},fp="7,388,26.445.0,15.714.0,25.608.0,15.190.0,46.363.0,33.177.0,36.219.0,36.259.0,51.139.0"}
P.entries["npc:elanaria"] = {n="Elanaria",s="Elanaria é uma elfa noturna mentora e coordenadora de guerreiros posicionada no Terraço dos Guerreiros em Darnassus. Ela orienta combatentes em desenvolvimento por toda Kalimdor, testando sua coragem contra ameaças perigosas como o sátiro Vorlus Vilehoof e entidades espirituais como a Shade of Elura. Sua orientação serve como uma ponte crucial para soldados da Aliança que aprimoram suas proezas marciais na capital dos elfos noturnos.",h="Elanaria é uma elfa noturna mentora e coordenadora de guerreiros posicionada no Terraço dos Guerreiros em...",kw={"darnassus","elanaria","shade of elura","smith mathiel","teldrassil","vorlus vilehoof","missões de guerreiro","terraço dos guerreiros"},ang={["class:Warrior"]="Elanaria é um contato essencial no Terraço dos Guerreiros, atribuindo provações marciais adequadas ao nível que recompensam com equipamento resistente e refinam habilidades táticas de combate.",["faction:Alliance"]="A partir da capital de Teldrassil, Elanaria ajuda a manter a prontidão militar e arma soldados que defendem os interesses da Aliança por todo o norte de Kalimdor.",["race:NightElf"]="Representando as tradições marciais de Darnassus, Elanaria trabalha para purgar entidades corrompidas, como sátiros e sombras inquietas, das terras ancestrais dos kaldorei."},sec={{t="Uma Sentinel do Terraço",b="Erguendo-se com orgulho no Terraço dos Guerreiros sob os galhos de Darnassus, Elanaria atua como instrutora e ponto de contato para campeões marciais. Em uma era em que os elfos noturnos se alinharam formalmente com a Grande Aliança, seu papel vai além de orientar as Sentinels locais, preparando guerreiros de todas as origens para os duros desafios que suas terras enfrentam."},{t="Provações de Ferro e Espírito",b="Elanaria não oferece elogios fáceis; ela espera disciplina, resiliência e força comprovada. Ela encarrega aventureiros experientes de abater adversários formidáveis que assolam Teldrassil e Costa Negra, incluindo o sátiro corrupto Vorlus Vilehoof e espíritos perturbados como a Shade of Elura. Ela também faz a ligação com artesãos habilidosos como Smith Mathiel para garantir que guerreiros merecedores estejam devidamente armados para a guerra."}},faq={{q="Quem é Elanaria?",a="Elanaria é uma elfa noturna localizada no Terraço dos Guerreiros em Darnassus. Ela atua como uma concedente de missões marciais que encarrega guerreiros em ascensão com provações de combate por todo o norte de Kalimdor.",al={"elanaria darnassus","quem é elanaria","elanaria npc"}},{q="Onde posso encontrar Elanaria?",a="Ela está localizada no Terraço dos Guerreiros, o distrito elevado ao norte de Darnassus dedicado aos campos de treinamento militar e às defesas da cidade.",al={"localização de elanaria","onde fica elanaria","local de elanaria"}},{q="Quais missões Elanaria oferece?",a="Elanaria é uma figura essencial na progressão intermediária de guerreiros, oferecendo tarefas como caçar o sátiro Vorlus Vilehoof, enfrentar a Shade of Elura e coordenar com armeiros locais como Smith Mathiel.",al={"missões de elanaria","missão de guerreiro de elanaria"}},{q="Por que Elanaria envia combatentes contra Vorlus Vilehoof?",a="Vorlus Vilehoof é um sátiro perigoso cuja corrupção demoníaca ameaça as terras selvagens do norte. Elanaria encarrega guerreiros capazes de matá-lo, tanto para proteger as florestas quanto para provar suas proezas no campo de batalha.",al={"elanaria vorlus","missão de vorlus vilehoof","por que matar vorlus vilehoof"}},{q="Quem é Smith Mathiel?",a="Smith Mathiel é um mestre armeiro posicionado em Darnassus. Elanaria direciona guerreiros a Mathiel para que possam criar ou receber equipamento marcial especializado adequado para combate na linha de frente.",al={"conexão com mathiel","smith mathiel guerreiro","elanaria e mathiel"}},{q="Elanaria interage com quem não é elfo noturno?",a="Sim. Como parte da Aliança, Elanaria ajuda todos os guerreiros da Aliança elegíveis que chegam ao Terraço dos Guerreiros em busca de orientação e treinamento especializado.",al={"humanos podem falar com elanaria","guerreiro da aliança elanaria"}}},fx={de8f39db={q="De que lado está Elanaria?",a="Elanaria está firmemente ao lado dos elfos noturnos de Darnassus e da Aliança em geral. Residindo no Terraço dos Guerreiros da capital, ela serve seu povo orientando e direcionando guerreiros capazes para defender suas terras contra ameaças iminentes.",al={"facção de elanaria","a quem elanaria serve","lealdade de elanaria"}},d7c0e558={q="O que Elanaria quer?",a="Elanaria procura lutadores experientes dispostos a proteger Kalimdor e purgar males corruptores. Ela despacha guerreiros bravos para abater inimigos perigosos, incluindo o sátiro Vorlus Vilehoof, e direciona recrutas promissores para artesãos habilidosos como Smith Mathiel para garantir que estejam devidamente equipados para a batalha.",al={"o que elanaria precisa","propósito de elanaria","motivo de elanaria"}},["16a563e6"]={q="Por que Elanaria está em Darnassus?",a="Elanaria está estacionada no Terraço dos Guerreiros em Darnassus para atuar como mentora e coordenadora para combatentes dentro da capital dos elfos noturnos. Deste centro marcial, ela pode avaliar facilmente a força dos aventureiros visitantes e despachá-los para onde suas lâminas são mais necessárias.",al={"por que elanaria está aqui","por que elanaria está no terraço dos guerreiros","razão da localização de elanaria"}}},fp="8,400,25.365.0,25.410.0,16.181.0,26.148.0,32.219.0,56.207.0,21.184.0,44.156.0"}
P.entries["npc:elder-bloodhoof"] = {n="Ancião Casco Sangrento",s="O Ancião Casco Sangrento é um espírito ancestral encontrado descansando logo ao norte da Aldeia Casco Sangrento, em Mulgore. Surgindo com destaque para os viajantes durante o Festival da Lua, ele permanece como um reverenciado espírito guardião da tribo Casco Sangrento.",h="O Ancião Casco Sangrento é um espírito ancestral encontrado descansando logo ao norte da Aldeia Casco...",kw={"ancestral","aldeia casco sangrento","ancião casco sangrento","festival da lua","mulgore","rochedo vermelho","espírito tauren"},ang={["class:Shaman"]="Xamãs reverenciam o Ancião Casco Sangrento como uma manifestação de reverência aos ancestrais, demonstrando como os espíritos ancestrais guiam e protegem seus descendentes no reino físico.",["race:Tauren"]="Para os peregrinos taurens, prestar homenagens ao Ancião Casco Sangrento é uma comunhão direta com a linhagem tribal, honrando o sacrifício daqueles que caminharam por Mulgore muito antes da fundação do Penhasco do Trovão."},sec={{t="Espírito dos Ancestrais",b="O Ancião Casco Sangrento representa o profundo laço espiritual que os taurens compartilham com sua linhagem. Manifestando-se perto da Aldeia Casco Sangrento, este ancião fantasmagórico vela por seu povo e recompensa viajantes respeitosos que buscam sabedoria durante o Festival da Lua. Sua presença reforça a orientação duradoura de antigos chefes e antepassados tribais falecidos, cujos espíritos permanecem intimamente ligados às planícies de Mulgore."}},faq={{q="Quem é o Ancião Casco Sangrento?",a="O Ancião Casco Sangrento é um espírito fantasmagórico de um tauren que surge logo ao norte da Aldeia Casco Sangrento, em Mulgore. Ele representa os honrados ancestrais da tribo Casco Sangrento, concedendo bênçãos e sabedoria antiga aos viajantes que o visitam durante tradições sazonais, como o Festival da Lua.",al={"história do ancião casco sangrento","quem é o fantasma fora da aldeia casco sangrento","identidade do ancião casco sangrento"}},{q="Quando é possível ver o Ancião Casco Sangrento?",a="O Ancião Casco Sangrento manifesta-se principalmente durante o Festival da Lua anual, onde atua como um espírito ancião que oferece bênçãos festivas.",al={"onde fica o ancião casco sangrento","ancião casco sangrento sumido","como encontrar o ancião casco sangrento"}},{q="Qual é a ligação dele com a Aldeia Casco Sangrento?",a="Como um honrado ancestral que carrega o nome do clã, o Ancião Casco Sangrento vela pelo assentamento ancestral da Aldeia Casco Sangrento. A tradição dos taurens atribui grande importância aos espíritos ancestrais que permanecem perto de onde seus descendentes vivem e se reúnem.",al={"por que ele fica perto da aldeia casco sangrento","relação do ancião casco sangrento com cairne"}}},fx={["376494a8"]={q="De que lado está o Ancião Casco Sangrento?",a="O Ancião Casco Sangrento é um ancestral reverenciado dos tauren Casco Sangrento e aliado da Horda. Como um dos espíritos ancestrais honrados durante o Festival da Lua, ele oferece bênçãos e sabedoria aos viajantes que honram sua memória e as tradições sagradas de seu povo.",al={"facção do ancião casco sangrento","o ancião casco sangrento é da horda","a quem o ancião casco sangrento serve"}},f5643df0={q="O que o Ancião Casco Sangrento quer?",a="O Ancião Casco Sangrento deseja ser lembrado e honrado pelos vivos. Quando os viajantes procuram os antigos espíritos de Kalimdor durante o Festival da Lua, ele concede suas bênçãos, moedas ancestrais e palavras de sabedoria em troca de seu respeito e reconhecimento do passado.",al={"objetivo do ancião casco sangrento","o que o bloodhoof the elder quer","por que falar com o ancião casco sangrento"}},["2e395d43"]={q="Por que o Ancião Casco Sangrento está aqui em Mulgore?",a="Seu espírito permanece logo ao norte da Aldeia Casco Sangrento porque estas planícies gramadas são o lar ancestral de sua tribo. Ele vigia seus descendentes de além do véu da morte, retornando a cada ano para a terra onde o povo Casco Sangrento vive e cria gado.",al={"por que o ancião casco sangrento está aqui","por que o ancião casco sangrento está fora da aldeia casco sangrento","razão da localização do ancião casco sangrento"}}},fp="15,221,23.396.0,23.275.0,33.131.0,44.246.0"}
P.entries["npc:elder-bronzebeard"] = {n="Ancião Barbabronze",s="O Ancião Barbabronze é um espírito antigo dos terranos que surge na Ala Mística de Altaforja durante o Festival da Lua. Ostentando o nome do clã que governa a cidade, sua presença espectral serve como uma ponte entre os anões modernos e seus ancestrais esculpidos em pedra.",h="O Ancião Barbabronze é um espírito antigo dos terranos que surge na Ala Mística de Altaforja durante o...",kw={"ancestral","terrano","ancião barbabronze","altaforja","festival da lua","magni","ala mística"},ang={["faction:Alliance"]="Peregrinos da Aliança que visitam Altaforja durante o Festival da Lua encontram um ancião que representa os próprios alicerces do reino dos anões.",["race:Dwarf"]="Para os anões, encontrar o Ancião Barbabronze oferece uma visão rara e direta de sua ancestralidade terrana, validando as descobertas históricas trazidas à tona pela Liga dos Exploradores."},sec={{t="Um Progenitor na Ala Mística",b="Aparecendo perto da piscina na Ala Mística de Altaforja, o Ancião Barbabronze não veste a carne dos anões modernos; em vez disso, sua forma fantasmagórica é a de um terrano, a antiga raça forjada de pedra viva pelos Titãs. Eruditos e exploradores anões estão apenas começando a desvendar suas origens por meio de escavações por Khaz Modan e além, fazendo da presença deste espírito uma impressionante relíquia viva. Seu próprio nome e semblante sugerem que ele é um ancestral direto do clã Barbabronze, testemunhando em silêncio o quanto sua progênie nascida da pedra evoluiu."}},faq={{q="Por que o Ancião Barbabronze parece um terrano em vez de um anão comum?",a="Os anões são descendentes dos terranos, seres antigos moldados em pedra pelos Titãs que com o tempo se tornaram criaturas de carne. Como o Ancião Barbabronze viveu no passado distante, antes que essa transformação se consolidasse, seu espírito preserva a forma rochosa de sua era terrana.",al={"por que o ancião barbabronze é de pedra","o ancião barbabronze é terrano","raça do ancião barbabronze"}},{q="Ele é parente do Rei Magni Barbabronze?",a="Embora os ramos exatos das antigas árvores genealógicas tenham se perdido na história, seu nome e presença na capital dos anões indicam fortemente que ele é um progenitor venerado do clã Barbabronze, a linhagem que atualmente governa Altaforja sob o Rei Magni.",al={"ele é ancestral do magni","parente de magni barbabronze","árvore genealógica dos barbabronze"}},{q="Por que o Ancião Barbabronze está em Altaforja?",a="Durante o Festival da Lua, espíritos dos anciãos se materializam por toda Azeroth para conceder sabedoria e bênçãos aos viajantes. O Ancião Barbabronze se manifesta na Ala Mística de Altaforja, descansando perto da piscina tranquila onde magos e eruditos anões se reúnem.",al={"o que o ancião barbabronze está fazendo aqui","onde fica o ancião barbabronze","fantasma da ala mística"}}},fx={f31842b8={q="Quem é o Ancião Barbabronze?",a="O Ancião Barbabronze é um espírito de barro ancestral que permanece na Ala Mística de Altaforja. Aparecendo na forma pétrea de seus antepassados forjados pelos Titãs em vez de carne e osso, ele representa as raízes profundas e ancestrais do povo anão e sua linhagem duradoura.",al={"quem é o ancião barbabronze","identidade do ancião barbabronze","o que é o ancião barbabronze"}},a81f3e52={q="O que o Ancião Barbabronze quer?",a="O Ancião Barbabronze não busca nada além de compartilhar a comunhão com aqueles que prestam homenagem aos caminhos antigos. Como um espírito errante do passado, ele cumprimenta peregrinos e concede sua presença aos visitantes respeitosos.",al={"o que o ancião barbabronze quer","motivo do ancião barbabronze","por que o ancião barbabronze quer falar"}},["7b1c25c3"]={q="De que lado está o Ancião Barbabronze?",a="Como um honrado ancestral no coração de Altaforja, o Ancião Barbabronze vela pacificamente pela capital dos anões. Como todos os anciãos do Festival da Lua, ele não toma partido nas guerras dos mortais, oferecendo saudações a viajantes e peregrinos de qualquer estandarte que se aproximem dele.",al={"facção do ancião barbabronze","de que lado está o ancião barbabronze","o ancião barbabronze é da aliança"}}},fp="17,276,31.551.0,75.274.0,40.247.0,38.259.0"}
P.entries["npc:elder-darkcore"] = {n="Ancião Negrocerne",s="O Ancião Negrocerne é um espírito antigo que aparece durante o Festival da Lua dentro da sala do trono das Ruínas de Lordaeron, acima da Cidade Baixa. Representando os honrados ancestrais do mundo, ele oferece sua bênção e fichas festivas aos viajantes que o procuram. Sua presença marca um momento pacífico e reflexivo em meio às ruínas de um reino humano caído.",h="O Ancião Negrocerne é um espírito antigo que aparece durante o Festival da Lua dentro da sala do trono das...",kw={"ancestral","moeda dos ancestrais","negrocerne","ancião negrocerne","festival da lua","ruínas de lordaeron","sala do trono","cidade baixa"},ang={["faction:Alliance"]="Visitar o Ancião Negrocerne requer passar furtivamente por sentinelas Renegados de nível alto e guardas reais posicionados ao redor das ruínas de Capital City, tornando-o uma das paradas mais perigosas do festival para a Aliança.",["race:Undead"]="O Ancião Negrocerne permanece a poucos passos dos elevadores da superfície da Cidade Baixa, de pé sobre as mesmas pedras onde o reino de Lordaeron foi derrubado."},sec={{t="Um Espírito na Sala do Trono",b="Durante o Festival da Lua anual, os espíritos de anciãos do passado se manifestam por Azeroth para compartilhar sua sabedoria com aventureiros. O Ancião Negrocerne faz sua vigília em um dos locais mais sombrios do mundo: a sala do trono real nas Ruínas de Lordaeron, diretamente acima da entrada para a Cidade Baixa. Cercado pelo chão manchado de sangue onde o Rei Terenas Menethil II caiu, este ancestral espectral oferece uma Moeda dos Ancestrais e sua bênção àqueles corajosos o bastante para entrar no coração do território dos Renegados para prestar suas homenagens."}},faq={{q="Quem é o Ancião Negrocerne?",a="O Ancião Negrocerne é um dos honrados ancestrais espectrais que se manifestam durante o Festival da Lua sazonal. Ele aparece na sala do trono acima da Cidade Baixa para conceder bênçãos e Moedas dos Ancestrais aos visitantes.",al={"ancião negrocerne","negrocerne","quem é negrocerne"}},{q="Onde posso encontrar o Ancião Negrocerne?",a="Ele está localizado na sala do trono em ruínas de Capital City, nas Ruínas de Lordaeron, bem acima da descida da entrada que leva à Cidade Baixa.",al={"onde fica negrocerne","localização de negrocerne","ancião de cidade baixa"}},{q="O Ancião Negrocerne é hostil à Aliança?",a="O próprio Ancião Negrocerne é neutro e acolhe todos os viajantes que vêm homenageá-lo. No entanto, como ele fica dentro da fortaleza dos Renegados nas Ruínas de Lordaeron, aventureiros da Aliança devem evitar com cuidado os guardas hostis que patrulham os arredores.",al={"aliança pode falar com negrocerne","negrocerne é da horda","festival da lua cidade baixa aliança"}},{q="O que prestar homenagens ao Ancião Negrocerne concede a você?",a="Prestar homenagens a ele completa a missão do festival para honrar sua memória, concedendo uma Moeda dos Ancestrais.",al={"recompensa de negrocerne","missão de negrocerne"}}},fx={["3a0e846b"]={q="De que lado está o Ancião Negrocerne?",a="O Ancião Negrocerne não se alinha com os conflitos modernos da Horda ou da Aliança. Como um espírito ancestral honrado participando do Festival da Lua, ele permanece pacificamente acima das disputas mortais, dando as boas-vindas a qualquer viajante que se aproxime dele com respeito, independentemente de qual estandarte eles defendam.",al={"facção do ancião negrocerne","o ancião negrocerne é da horda ou da aliança","lealdade de negrocerne"}},["32c6e8a4"]={q="O que o Ancião Negrocerne quer?",a="O Ancião Negrocerne busca compartilhar a sabedoria antiga e as bênçãos dos ancestrais durante o Festival da Lua. Ele espera que os viajantes prestem suas homenagens ao passado, oferecendo sua bênção e fichas de herança dos anciãos àqueles que honram sua memória duradoura.",al={"o que o ancião negrocerne quer","propósito do ancião negrocerne","por que visitar o ancião negrocerne"}},e5445cfd={q="Por que o Ancião Negrocerne está nas Ruínas de Lordaeron?",a="O Ancião Negrocerne aparece na sala do trono arruinada acima da Cidade Baixa como parte da observância mundial do Festival da Lua. Os espíritos dos ancestrais se manifestam em lugares marcados por profunda história e tristeza em Azeroth, permitindo que os mortais se comuniquem com memórias ancestrais mesmo em meio a reinos caídos.",al={"por que o ancião negrocerne está na cidade baixa","por que negrocerne está nas ruínas de lordaeron","conhecimento da localização do ancião negrocerne"}}},fp="14,358,27.525.0,22.210.0,32.148.0,42.248.0,43.102.0"}
P.entries["npc:elder-goldwell"] = {n="Ancião Poçodouro",s="O Ancião Poçodouro é um antigo espírito terrano que permanece perto do assentamento anão de Kharanos, em Dun Morogh. Aparecendo durante o Festival da Lua, este reverenciado ancestral representa as origens esquecidas da civilização anã moderna.",h="O Ancião Poçodouro é um antigo espírito terrano que permanece perto do assentamento anão de Kharanos, em Dun...",kw={"ancestral","dun morogh","terrano","ancião poçodouro","poçodouro","kharanos","festival da lua"},ang={["faction:Alliance"]="Viajantes da Aliança que passam por Kharanos frequentemente procuram Poçodouro para prestar suas homenagens e receber bênçãos tradicionais de boa sorte.",["race:Dwarf"]="Para os anões, encontrar o Ancião Poçodouro oferece um vislumbre raro e direto de sua antiga herança forjada em pedra e da linhagem que conecta a Altaforja moderna aos terranos."},sec={{t="Um Espírito dos Terranos",b="O Ancião Poçodouro se manifesta como um espírito terrano translúcido, vigiando as encostas nevadas de Kharanos. Ao contrário dos modernos anões mortais de carne e osso, sua forma pétrea ecoa a antiga raça forjada pelos Titãs da qual o clã Barbabronze descendeu. Sua presença durante as celebrações dos ancestrais oferece aos viajantes a chance de honrar essa antiga herança."}},faq={{q="Quem é o Ancião Poçodouro?",a="O Ancião Poçodouro é um espírito ancestral terrano encontrado em Dun Morogh. Ele visita Kharanos durante as celebrações sazonais dos ancestrais para que os viajantes modernos possam prestar suas homenagens aos ancestrais dos anões.",al={"identidade do ancião poçodouro","quem é poçodouro","história de poçodouro"}},{q="Onde o Ancião Poçodouro está localizado?",a="Ele pode ser encontrado do lado de fora da cidade anã de Kharanos, em Dun Morogh, geralmente perto da estalagem local e das áreas de reunião.",al={"localização do ancião poçodouro","onde encontrar o ancião poçodouro","encontrar poçodouro"}},{q="Por que o Ancião Poçodouro se parece com um terrano em vez de um anão?",a="Os anões traçam sua ancestralidade até os terranos de pele de pedra criados pelos Titãs. Como um dos espíritos mais antigos a honrar as gerações passadas, Poçodouro mantém a aparência terrana original em vez da carne mortal dos anões vivos.",al={"por que poçodouro é um terrano","poçodouro é um terrano","poçodouro anão de pedra"}}},fp="14,232,23.344.0,22.202.0,32.124.0,65.240.0"}
P.entries["npc:elder-graveborn"] = {n="Ancião Nascitumba",s="O Ancião Nascitumba é um espírito ancestral que se manifesta logo a sudeste de Montalvo durante o Festival da Lua. Aparecendo como um ancião terreno espectral, ele homenageia viajantes e guia peregrinos em busca de outros espíritos antigos espalhados pelo norte de Lordaeron.",h="O Ancião Nascitumba é um espírito ancestral que se manifesta logo a sudeste de Montalvo durante o Festival da...",kw={"ancestral","montalvo","terreno","ancião nascitumba","nascitumba","festival da lua","clareiras de tirisfal"},ang={["faction:Alliance"]="Peregrinos da Aliança precisam contornar os arredores de Montalvo com cuidado para prestar suas homenagens a Nascitumba sem atrair a ira dos guardas da cidade e patrulhas Renegadas.",["race:Undead"]="Para os Renegados que percorrem a estrada entre Montalvo e a Cidade Baixa, Nascitumba serve como um lembrete tranquilo do passado antigo de Azeroth, descansando sem ser perturbado pelo Flagelo ou pela peste."},sec={{t="Um Espírito em Tirisfal",b="Aparecendo logo além da cidade Renegada de Montalvo, o Ancião Nascitumba permanece em meio aos bosques assombrados das Clareiras de Tirisfal como parte do Festival da Lua mundial. Apesar dos arredores assolados pela peste e do estado conturbado do reino, o ancião espectral oferece saudações pacíficas aos viajantes que buscam as bênçãos tradicionais do festival. Além de conceder sua própria sabedoria ancestral, Nascitumba compartilha notícias de outros anciãos que permanecem por perto — direcionando peregrinos para espíritos que residem na Cidade Baixa, em O Sepulcro e pelas Plaguelands."}},faq={{q="Quem é o Ancião Nascitumba?",a="O Ancião Nascitumba é um reverenciado fantasma ancestral que surge durante o Festival da Lua. Ele se materializa nas Clareiras de Tirisfal, logo a sudeste de Montalvo, para conceder bênçãos festivas aos aventureiros que passam por lá.",al={"história do ancião nascitumba","quem é nascitumba","ancião fantasma de montalvo"}},{q="Por que ele está nas Clareiras de Tirisfal?",a="Durante o Festival da Lua, espíritos ancestrais surgem por toda Azeroth para celebrar os heróis do passado e o patrimônio comunitário. O Ancião Nascitumba vigia as terras nos arredores de Montalvo, mantendo uma presença antiga em meio ao reino arruinado de Lordaeron.",al={"por que montalvo","onde fica o ancião nascitumba"}},{q="Aventureiros da Aliança podem falar com ele?",a="Sim. Os anciãos do festival acolhem viajantes de ambas as facções, independentemente do território. No entanto, personagens da Aliança devem ter cautela ao se aproximar de seu local de descanso, já que ele fica muito perto do entreposto Renegado de Montalvo.",al={"aliança pode falar com nascitumba","ancião da aliança em montalvo"}},{q="Que informações ele oferece aos viajantes?",a="O Ancião Nascitumba orienta os peregrinos em direção a outros ancestrais locais, compartilhando rumores de espíritos que residem na Cidade Baixa, em O Sepulcro de Floresta de Pinhaprata, na Capela Esperança da Luz, na Caverna das Lágrimas e em Scolomântia.",al={"direções para o ancião nascitumba","falas de nascitumba"}}},fx={a72aed3e={q="O que o Ancião Nascitumba quer?",a="O Ancião Nascitumba deseja compartilhar suas bênçãos antigas e sabedoria ancestral com aqueles que viajam pelas terras durante o Festival da Lua. Como um espírito de barro que retornou para honrar a herança do mundo, ele pede aos viajantes que prestem suas homenagens ao passado, concedendo sua bênção e direcionando-os para outros anciãos honrados espalhados pelo continente.",al={"objetivo do ancião nascitumba","por que visitar o ancião nascitumba","o que o nascitumba quer"}},["066af8bb"]={q="A quem o Ancião Nascitumba está ligado?",a="Nascitumba sabe onde vários outros espíritos ancestrais podem ser encontrados. Ele direciona os viajantes para o Ancião Negrocerne na Cidade Baixa, Obsidiano perto do Sepulcro, Snowcrown na Capela Esperança da Luz, Meadowrun na Caverna das Lágrimas e Moonstrike em Scolomântia.",al={"relações do ancião nascitumba","quem o ancião nascitumba conhece","conexões de nascitumba"}}},fp="15,259,20.543.0,23.194.0,29.240.0,38.230.0,41.194.0"}
P.entries["npc:elder-morningdew"] = {n="Anciã Serenalva",s="A Anciã Serenalva é um antigo espírito de elfo noturno que aparece durante o Festival da Lua em Mil Agulhas. Ela oferece sabedoria e bênçãos ancestrais aos viajantes que a procuram em meio aos desfiladeiros áridos e às salinas secas da Chapada Cintilante.",h="A Anciã Serenalva é um antigo espírito de elfo noturno que aparece durante o Festival da Lua em Mil Agulhas.",kw={"ancestral","ancião","anciã serenalva","fantasma","festival da lua","serenalva","elfo noturno","mil agulhas"},ang={["race:NightElf"]="Para os kaldorei, procurar anciãos antigos como Serenalva é um dever sagrado de reverência, conectando os elfos noturnos modernos aos honrados espíritos que vieram antes deles.",["race:Tauren"]="Os Tauren honram profundamente os espíritos ancestrais, tornando os encontros com anciãos por toda Kalimdor uma extensão natural de sua reverência cultural pela sabedoria do passado."},sec={{t="Um Honrado Espírito do Festival",b="Durante todo o Festival da Lua, os espíritos de ancestrais reverenciados manifestam-se por toda Kalimdor e pelos Reinos do Leste para celebrar a sabedoria, o legado e a paz. A Anciã Serenalva é uma dessas aparições, visitando Mil Agulhas para saudar os peregrinos que prestam homenagens. Sem vínculos com facções ou conflitos mortais, ela concede sua moeda dos ancestrais a qualquer aventureiro respeitoso o suficiente para buscar seus conselhos e receber sua bênção."}},faq={{q="Quem é a Anciã Serenalva?",a="A Anciã Serenalva é um espírito ancestral de elfo noturno que se manifesta durante o Festival da Lua anual. Ela espera em Mil Agulhas para ser homenageada por viajantes tanto da Aliança quanto da Horda.",al={"história da anciã serenalva","quem é serenalva","identidade de serenalva"}},{q="Qual é o propósito de procurá-la?",a="Aventureiros a procuram durante o Festival da Lua para prestar seus respeitos aos ancestrais, recebendo uma Moeda dos Ancestrais e uma bênção de sabedoria em troca de honrar seu espírito.",al={"por que encontrar a anciã serenalva","propósito de serenalva","ancião do festival da lua"}},{q="Ela pertence à Aliança ou à Horda?",a="Como todos os anciãos do Festival da Lua, a Anciã Serenalva permanece neutra em relação à política dos mortais. Tanto aventureiros da Aliança quanto da Horda podem se aproximar dela pacificamente para prestar seus respeitos.",al={"serenalva é hostil","facção da anciã serenalva","a horda pode falar com serenalva"}}},fp="16,246,33.411.0,24.191.0,39.181.0,41.170.0"}
P.entries["npc:elder-obsidian"] = {n="Ancião Obsidiano",s="O Ancião Obsidiano é um espírito ancestral terrano que se manifesta n'O Sepulcro, na Floresta de Pinhaprata, durante o evento anual do Festival da Lua. Aparecendo entre os túmulos reivindicados pelos Renegados, ele oferece a sabedoria e as bênçãos do mundo antigo aos viajantes que homenageiam o festival.",h="O Ancião Obsidiano é um espírito ancestral terrano que se manifesta n'O Sepulcro, na Floresta de Pinhaprata...",kw={"ancestral","moeda dos ancestrais","terrano","ancião obsidiano","festival da lua","o sepulcro","floresta de pinhaprata"},ang={["faction:Alliance"]="Peregrinos da Aliança que buscam o Ancião Obsidiano devem caminhar com cuidado, pois seu local de descanso escolhido fica no coração do assentamento Renegado d'O Sepulcro.",["race:Dwarf"]="Para os anões curiosos sobre sua linhagem forjada pelos titãs, falar com um espírito terrano como o Ancião Obsidiano oferece um vislumbre raro do passado primordial de seus ancestrais talhados em pedra."},sec={{t="Um Espírito n'O Sepulcro",b="Erigindo-se entre as tumbas sombrias d'O Sepulcro, o Ancião Obsidiano oferece um contraste marcante com a extensão lúgubre da Floresta de Pinhaprata. Como um ancião terrano etéreo, seu espírito se manifesta durante o Festival da Lua para celebrar a herança ancestral de Azeroth. Enquanto as criptas ao redor são ocupadas pelos Renegados e ameaçadas por worgens ferozes, Obsidiano cumprimenta viajantes de todas as alianças em paz, concedendo Moeda dos Ancestrais e bênçãos antigas àqueles que dedicam um tempo para buscar sua sabedoria."}},faq={{q="Quem é o Ancião Obsidiano?",a="O Ancião Obsidiano é um antigo fantasma terrano que aparece na Floresta de Pinhaprata. Ele surge exclusivamente durante o Festival da Lua, cumprimentando os viajantes que honram a herança ancestral do mundo.",al={"história do ancião obsidiano","quem é obsidiano","ancião do sepulcro"}},{q="Onde o Ancião Obsidiano pode ser encontrado?",a="Ele pode ser encontrado descansando nos terrenos do cemitério d'O Sepulcro, um vilarejo controlado pelos Renegados situado ao longo da estrada no centro da Floresta de Pinhaprata.",al={"localização do ancião obsidiano","onde fica obsidiano","encontrar ancião obsidiano"}},{q="Por que um ancião terrano aparece na Floresta de Pinhaprata?",a="Durante o Festival da Lua, os espíritos de anciãos do passado manifestam-se em terras por toda Azeroth para compartilhar sua sabedoria ancestral. A presença espiritual de Obsidiano transcende os conflitos territoriais locais, permitindo-lhe comungar pacificamente em meio aos túmulos antigos.",al={"por que obsidiano está em pinhaprata","terrano em pinhaprata"}},{q="Aventureiros da Aliança podem falar com o Ancião Obsidiano?",a="Sim. Os anciãos do festival permanecem neutros em relação a todos os viajantes, independentemente da facção. No entanto, como ele descansa n'O Sepulcro, os aventureiros da Aliança devem navegar com cuidado pelos guardas hostis dos Renegados posicionados nas proximidades para alcançá-lo.",al={"aliança pode visitar o ancião obsidiano","ancião obsidiano amigável com a aliança"}}},fx={cd669d85={q="De que lado está o Ancião Obsidiano?",a="O Ancião Obsidiano mantém-se à parte dos conflitos mortais entre a Aliança e a Horda. Como um espírito de barro ancestral retornando para o Festival da Lua, ele oferece sua sabedoria e bênção ancestral a qualquer aventureiro que venha honrar os anciãos, independentemente da lealdade, embora ele se manifeste perto do assentamento dos Renegados, O Sepulcro.",al={"o ancião obsidiano é da aliança ou da horda","facção do ancião obsidiano","lado do ancião obsidiano"}},["5cd08f2c"]={q="O que o Ancião Obsidiano quer?",a="O Ancião Obsidiano deseja ser lembrado e honrado pelos mortais de Azeroth. Durante a celebração do Festival da Lua, ele dá as boas-vindas aos viajantes que procuram sua presença antiga, concedendo sua bênção e uma ficha de sorte ancestral àqueles que prestam suas homenagens ao passado.",al={"o que o ancião obsidiano precisa","objetivo do ancião obsidiano","por que visitar o ancião obsidiano"}}},fp="14,275,25.494.0,22.188.0,34.153.0,54.251.0,51.227.0"}
P.entries["npc:elder-runetotem"] = {n="Anciã Runa Totem",s="A Anciã Runa Totem é um espírito ancestral tauren que aparece nos arredores de Monte Navalha, em Durotar, durante o Festival da Lua. Como uma das veneradas anciãs homenageadas durante o festival, ela oferece sabedoria e sua bênção aos viajantes que a procuram pelos desfiladeiros vermelhos.",h="A Anciã Runa Totem é um espírito ancestral tauren que aparece nos arredores de Monte Navalha, em Durotar...",kw={"moeda dos ancestrais","durotar","anciã runa totem","festival da lua","monte navalha","runa totem","fantasma tauren"},ang={["faction:Horde"]="De pé nos arredores do assentamento fortemente fortificado de Monte Navalha, sua presença simboliza a aliança espiritual entre os orcs de Durotar e os tauren de Mulgore.",["race:Tauren"]="Encontrar uma venerável ancestral da tribo Runa Totem tão longe de Mulgore é uma lembrança tocante de que os espíritos dos Shu'halo velam por seus aliados em todas as terras."},sec={{t="Um Espírito em Durotar",b="Embora os espíritos ancestrais tauren estejam tipicamente ligados às planícies verdejantes e aos campos de sepultamento sagrados de Mulgore, a Anciã Runa Totem permanece longe das pastagens de seu povo. Ela se manifesta ao lado do povoado empoeirado de Monte Navalha, em Durotar. Para os jovens orcs e aventureiros errantes, sua presença etérea serve como uma ponte entre as antigas tradições dos Shu'halo e o novo e árduo lar que a Horda construiu ao longo do Grande Oceano."},{t="Honras Ancestrais",b="Durante o Festival da Lua, os espíritos de grandes líderes, xamãs e heróis se manifestam por todo o mundo para comungar com os vivos. A Anciã Runa Totem representa a linhagem Runa Totem — uma estirpe conhecida por sua profunda reverência à Mãe Terra e pela comunhão espiritual. Os viajantes que honram sua presença recebem fichas ancestrais e sua bênção espiritual."}},faq={{q="Quem é a Anciã Runa Totem?",a="A Anciã Runa Totem é uma ancestral tauren fantasmagórica que se manifesta perto de Monte Navalha, em Durotar. Ela é uma das honradas anciãs que retornam durante o Festival da Lua para saudar os viajantes e conceder bênçãos ancestrais.",al={"história da anciã runa totem","quem é o fantasma tauren em monte navalha","fantasma runa totem"}},{q="Por que um espírito tauren está localizado em Durotar?",a="Embora a maioria dos espíritos ancestrais tauren tenha suas raízes em Mulgore, os espíritos do Festival da Lua vagam por toda parte em Kalimdor e nos Reinos do Leste. Sua presença em Monte Navalha permite que os viajantes da Horda que passam por Durotar prestem homenagens à sabedoria dos filhos da Mãe Terra.",al={"por que a runa totem está em monte navalha","fantasma tauren durotar"}},{q="Qual é a conexão dela com a tribo Runa Totem?",a="Ela leva o nome do clã Runa Totem, uma das linhagens tauren de destaque, famosa por seus xamãs, guias espirituais e conexões com o mundo natural.",al={"anciã da tribo runa totem","família runa totem"}},{q="O que conversar com ela concede?",a="Falar com a Anciã Runa Totem homenageia sua memória durante o Festival da Lua, recompensando os aventureiros com uma Moeda dos Ancestrais e uma bênção temporária dos espíritos.",al={"o que a anciã runa totem dá","recompensa da runa totem"}}},fx={["021a9c1d"]={q="O que a Anciã Runa Totem quer?",a="Ela busca compartilhar a lembrança e a reverência do povo tauren com os viajantes que passam pelo Monte Navalha. Ao entrar em contato com os vivos, ela lembra aos viajantes dos espíritos ancestrais que vigiam as terras e mantêm vivas as tradições antigas.",al={"o que a anciã runa totem busca","por que falar com a anciã runa totem","objetivo da anciã runa totem"}},c76d680b={q="De que lado está a Anciã Runa Totem?",a="A Anciã Runa Totem não toma partido nas guerras dos vivos. Como um honrado espírito ancestral dos taurens, ela oferece sua sabedoria antiga e bênçãos a qualquer aventureiro, da Horda ou da Aliança, que respeite os costumes dos ancestrais.",al={"a anciã runa totem é da horda","facção da anciã runa totem","lado da anciã runa totem"}}},fp="15,259,19.432.0,16.352.0,23.207.0,42.296.0,53.162.0,34.163.0"}
P.entries["npc:elder-skyseer"] = {n="Ancião Vidente do Céu",s="O Ancião Vidente do Céu é o espírito de um tauren ancestral que reside no topo dos imponentes penhascos da Aldeia Vento Livre, em Mil Agulhas. Como um honrado ancião que retornou do mundo dos espíritos, ele observa as jornadas contínuas da Horda e permanece profundamente ligado aos locais de descanso de seu povo.",h="O Ancião Vidente do Céu é o espírito de um tauren ancestral que reside no topo dos imponentes penhascos da...",kw={"ancestral","ancião vidente do céu","aldeia vento livre","rochedo vermelho","fantasma tauren","mil agulhas"},ang={["class:Shaman"]="Como mediadores espirituais que falam com os elementos e os espíritos, os xamãs reconhecem no Ancião Vidente do Céu a sabedoria duradoura dos ancestrais que continuam a vigiar os vivos.",["race:Tauren"]="Para os taurens, encontrar o Ancião Vidente do Céu é uma comunhão direta com um ancestral, personificando a reverência espiritual ensinada em Rochedo Vermelho e pelas planícies de Mulgore."},sec={{t="Um Espírito da Aldeia Vento Livre",b="Empoleirado bem acima dos desfiladeiros salgados de Mil Agulhas, o Ancião Vidente do Céu permanece no assentamento da meseta açoitada pelo vento da Aldeia Vento Livre. Enquanto os taurens da Aldeia Vento Livre se movimentam pelas pontes perigosas e plataformas de madeira do posto avançado, o Vidente do Céu vigia o reino como um ancestral que cruzou além do véu mortal. Ele serve como um farol ancestral para viajantes em busca da sabedoria das gerações passadas, concedendo suas bênçãos àqueles que honram as velhas tradições."},{t="Laços com as Terras Ancestrais",b="Embora seu espírito comumente se manifeste entre as agulhas esculpidas pelo vento, o Vidente do Céu pertence à longa linhagem de ancestrais taurens cujo povo honra o solo sagrado de Mulgore, onde os espíritos ancestrais de Rochedo Vermelho vigiam as tribos. Espíritos como o Vidente do Céu revelam como o véu entre o reino físico e os espíritos ancestrais permanece tênue para os taurens, guiando as futuras gerações por meio da lembrança e do ritual."}},faq={{q="Quem é o Ancião Vidente do Céu?",a="O Ancião Vidente do Céu é o espírito de um tauren ancestral que aparece na Aldeia Vento Livre, em Mil Agulhas. Ele é um dos reverenciados anciãos cujos espíritos vigiam os viajantes modernos, oferecendo orientação ancestral àqueles que o procuram.",al={"história do ancião vidente do céu","quem é o vidente do céu","pnc vidente do céu"}},{q="Por que o Ancião Vidente do Céu é um fantasma?",a="Ele é um antigo ancestral que partiu do mundo mortal. A cultura tauren mantém uma profunda conexão espiritual com seus antepassados, e certos anciãos proeminentes permanecem ou retornam em forma espiritual para guiar os vivos.",al={"por que o vidente do céu morreu","o ancião vidente do céu está morto","tauren fantasma vento livre"}},{q="Qual é a conexão dele com Mulgore?",a="Como todos os ancestrais taurens, o Vidente do Céu é honrado por um povo cuja terra natal é Mulgore, onde os espíritos ancestrais de Rochedo Vermelho vigiam as tribos. Seu próprio espírito, no entanto, aparece na Aldeia Vento Livre, em Mil Agulhas.",al={"vidente do céu rochedo vermelho","conexão do vidente do céu com mulgore"}},{q="Onde posso encontrar o Ancião Vidente do Céu?",a="O Ancião Vidente do Céu está localizado na Aldeia Vento Livre, em Mil Agulhas, permanecendo no topo do assentamento fortificado da meseta, bem acima do chão do desfiladeiro.",al={"localização do ancião vidente do céu","encontrar o vidente do céu","onde fica o vidente do céu"}}},fp="13,283,25.461.0,27.413.0,21.223.0,29.221.0,34.219.0,31.136.0"}
P.entries["npc:elder-starweave"] = {n="Anciã Tecestrela",s="A Anciã Tecestrela é um espírito ancestral de elfo noturno homenageado durante o Festival da Lua. Encontrada descansando na cidade portuária de Auberdine, ao longo da costa enevoada de Costa Negra, ela compartilha a sabedoria de eras antigas com os peregrinos que passam.",h="A Anciã Tecestrela é um espírito ancestral de elfo noturno homenageado durante o Festival da Lua.",kw={"ancestral","auberdine","moeda dos ancestrais","costa negra","anciã tecestrela","festival da lua","tecestrela"},ang={["class:Druid"]="Druidas que celebram o festival consideram que as reflexões celestiais de Tecestrela estão alinhadas com os ensinamentos cenarianos de renovação, memória e harmonia com o mundo natural.",["race:NightElf"]="Encontrar a Anciã Tecestrela em Costa Negra conecta os aventureiros kaldorei diretamente à sua longa linhagem de antepassados que olhavam para Elune e para as estrelas em meio a cataclismos antigos."},sec={{t="Um Farol em Auberdine",b="Aparecendo como uma sombra etérea entre as habitações costeiras de Auberdine, a Anciã Tecestrela é uma das reverenciadas ancestrais homenageadas pelo Círculo Cenariano e pelos povos de Kalimdor. Enquanto muitos viajantes passam apressados pelo porto a caminho do interior ou através do mar, aqueles que param diante dela recebem uma bênção ancestral. Tecestrela fala sobre movimentos celestiais, observando que as estrelas da era moderna traçam caminhos desconhecidos que servem como faróis de esperança e fortaleza para as futuras gerações."}},faq={{q="Quem é a Anciã Tecestrela?",a="A Anciã Tecestrela é um espírito ancestral de elfo noturno que aparece em Auberdine durante o Festival da Lua para oferecer saudações, sabedoria antiga e Moedas de Ancestralidade aos viajantes.",al={"história da anciã tecestrela","quem é tecestrela","tecestrela, a anciã"}},{q="Onde a Anciã Tecestrela pode ser encontrada?",a="Ela pode ser encontrada perambulando perto do assentamento de Auberdine, ao longo da costa de Costa Negra.",al={"onde fica a anciã tecestrela","localização da anciã tecestrela","ponto da tecestrela"}},{q="Por que ela aparece como um espírito?",a="Ela é uma ancestral reverenciada manifestada durante o Festival da Lua, aparecendo em forma espiritual para que os vivos possam prestar homenagens àqueles que moldaram o passado distante dos elfos noturnos.",al={"por que a tecestrela é um fantasma","a tecestrela está morta","por que fantasma"}},{q="Jogadores da Horda podem falar com ela?",a="Sim. Os anciãos ancestrais homenageados durante o Festival da Lua acolhem viajantes de todas as afiliações, embora os aventureiros da Horda devam navegar pelo porto aliado da Aliança de Auberdine com cautela.",al={"a horda pode visitar tecestrela","anciã tecestrela horda"}}},fx={d8911fea={q="Por que a Anciã Tecestrela está aqui em Costa Negra?",a="A Anciã Tecestrela permanece em Costa Negra como um espírito ancestral para observar o mundo e guiar as gerações mais jovens. Ela observa as constelações em mudança, lendo os sinais dos céus como faróis de esperança e força para as provações das eras por vir.",al={"por que a anciã tecestrela está em costa negra","por que tecestrela está aqui","propósito da anciã tecestrela"}}},fp="15,224,21.495.0,23.170.0,35.93.0,32.177.0,31.187.0"}
P.entries["npc:eleanor-shackleton"] = {n="Eleanor Shackleton",s="Eleanor Shackleton é uma mateira Renegada encontrada acampando a sudoeste de Montalvo, nas Clareiras de Tirisfal. Em vez de permanecer na cidade ou na Cidade Baixa, ela ajuda viajantes a aprender sobre sobrevivência na natureza e técnicas de campo. Ela compartilha seu sobrenome com outros Renegados sobreviventes na região, sugerindo laços remanescentes da vida antes da praga.",h="Eleanor Shackleton é uma mateira Renegada encontrada acampando a sudoeste de Montalvo, nas Clareiras de...",kw={"montalvo","guia básico de acampamento","eleanor shackleton","shackleton","sticks and bones","the adventurer","the great outdoors","clareiras de tirisfal"},ang={["profession:Cooking"]="A instrução de Eleanor abrange a montagem de fogueiras de acampamento e o preparo de refeições longe de lareiras civilizadas, tornando seu acampamento uma parada fundamental para cozinheiros viajantes.",["race:Undead"]="Para os Renegados, aprender a sobreviver na natureza sem os confortos dos vivos é vital, e Eleanor garante que os irmãos recém-erguidos se adaptem rapidamente a enfrentar os rigores de Tirisfal."},sec={{t="Um Guia para as Clareiras",b="Enquanto muitos Renegados recém-despertos seguem direto para Montalvo ou adentram a Cidade Baixa, Eleanor Shackleton monta seu acampamento nos bosques assombrados a sudoeste. Sobreviver em Tirisfal exige autossuficiência pragmática, e Eleanor atua como instrutora para aventureiros novatos que buscam viver da terra assolada. Por meio de suas diversas lições de campo, ela orienta os viajantes a montar acampamentos, coletar lenha e manter seus ofícios enquanto vagueiam longe dos fogos das forjas e das cozinhas da civilização."},{t="Laços de uma Vida Passada",b="Nas ruínas devastadas de Lordaeron, os nomes de família frequentemente servem como o único elo sobrevivente com o passado mortal de um morto-vivo. Eleanor carrega o sobrenome Shackleton, compartilhado por Pierce Shackleton e Samantha Shackleton no Distrito da Magia da Cidade Baixa. Quer os três mantenham laços estreitos ou apenas compartilhem uma ancestralidade comum de seus dias mortais, cada um conquistou um papel distinto a serviço da causa dos Renegados por todo o reino assolado."}},faq={{q="Onde posso encontrar Eleanor Shackleton?",a="Eleanor Shackleton monta seu acampamento a sudoeste de Montalvo, aninhado nos bosques das Clareiras de Tirisfal, longe da estrada pavimentada principal.",al={"localização de eleanor shackleton","onde fica eleanor","local de shackleton"}},{q="O que Eleanor Shackleton ensina aos aventureiros?",a="Eleanor orienta os viajantes pelos princípios básicos de sobrevivência na natureza, oferecendo instrução sobre como acampar, forragear e praticar profissões em meio à vida selvagem.",al={"missões de eleanor","o que eleanor faz","missões de acampamento em tirisfal"}},{q="Eleanor é parente de outros Shackletons em Lordaeron?",a="Ela compartilha seu sobrenome com Pierce Shackleton e Samantha Shackleton, da Cidade Baixa, indicando um possível parentesco de suas vidas antes de o reino cair perante o Flagelo.",al={"parente de pierce shackleton","samantha shackleton","história da família shackleton"}},{q="Por que ela está acampando fora de Montalvo em vez de ficar na cidade?",a="Eleanor se concentra em técnicas de campo e sobrevivência na natureza. Montar seu acampamento na floresta permite que ela encontre viajantes e os treine diretamente onde essas habilidades são necessárias.",al={"por que acampar fora de montalvo","acampamento de eleanor shackleton"}}},fx={a3327cab={q="Quem é Eleanor Shackleton?",a="Eleanor Shackleton é uma sobrevivencialista dos Renegados que montou acampamento na floresta a sudoeste de Montalvo. Em vez de permanecer na cidade, ela abraça a sobrevivência nas áreas selvagens das Clareiras de Tirisfal, guiando mortos-vivos recém-formados nos fundamentos da vida ao ar livre e na prática de ofícios básicos no campo.",al={"quem é eleanor shackleton","identidade de eleanor shackleton","informações sobre eleanor shackleton"}},afc076fe={q="De que lado está Eleanor Shackleton?",a="Eleanor é leal aos Renegados e à Grande Dama. Ela atua logo fora de Montalvo, ajudando membros recém-erguidos de seu povo a se adaptarem à sua não-vida, ensinando-os a sobreviver, coletar materiais e aprimorar ofícios úteis por todas as clareiras assombradas de Lordaeron.",al={"facção de eleanor shackleton","eleanor shackleton é da horda","alianças de eleanor shackleton"}},["48da77ca"]={q="O que Eleanor Shackleton quer?",a="Eleanor quer que aventureiros aprendam habilidades de sobrevivência essenciais e ofícios da vida selvagem. Ao enviar viajantes para praticar profissões como herbologia, esfolamento e culinária sob o céu aberto, ela garante que os Renegados que se aventuram além da segurança dos assentamentos estejam devidamente equipados para se sustentar.",al={"o que eleanor quer","objetivos de eleanor shackleton","motivos de eleanor shackleton"}}},fp="18,356,21.516.0,21.437.0,36.125.0,47.154.0,53.177.0,60.171.0"}
P.entries["npc:electrocutioner-6000"] = {n="Eletrocutor 6000",s="O Eletrocutor 6000 é um tanque aranha mortal e supercarregado mobilizado para defender a Launch Bay dentro dos salões irradiados de Gnomeregan. Ele luta pelo Mecangenheiro Termaplugue e pelos gnomos leprosos que o seguem, mantendo a plataforma superior contra qualquer um que avance mais fundo na cidade caída.",h="O Eletrocutor 6000 é um tanque aranha mortal e supercarregado mobilizado para defender a Launch Bay dentro...",kw={"eletrocutor","gnomeregan","launch bay","tanque aranha","termaplugue","chave da oficina"},ang={["faction:Alliance"]="Invadir a Launch Bay e destruir o tanque é vital para assegurar a Chave da Oficina, contornando corredores frontais perigosos durante os esforços de libertação em Gnomeregan.",["profession:Engineering"]="Engenheiros se maravilham com a potência bruta de alta voltagem contida no chassi, mesmo quando esse poder é voltado contra eles.",["race:Gnome"]="Para os gnomos exilados de Altaforja, o Eletrocutor 6000 é um insulto ao seu ofício: uma máquina de guerra gnômica voltada contra seu próprio povo sob o domínio de Termaplugue."},sec={{t="A Máquina Chocante de Termaplugue",b="A queda de Gnomeregan deixou suas máquinas de guerra nas mãos do Mecangenheiro Termaplugue e dos gnomos leprosos irradiados que ainda o seguem. O Eletrocutor 6000, um enorme tanque aranha crepitando com corrente de alta voltagem, vigia a plataforma superior da Launch Bay de Gnomeregan e atinge invasores com eletricidade."},{t="A Chave da Oficina",b="A máquina também guarda um prêmio: a Chave da Oficina, que abre a porta dos fundos de Gnomeregan para suas oficinas. Aqueles que derrotarem o Eletrocutor podem reivindicar a chave e uma rota mais rápida para as profundezas da cidade."}},faq={{q="Onde o Eletrocutor 6000 pode ser encontrado?",a="O Eletrocutor 6000 está posicionado em uma plataforma de passarela elevada com vista para a Launch Bay dentro da cidade caída de Gnomeregan.",al={"localização do eletrocutor 6000","onde fica o eletrocutor","encontrar eletrocutor 6000"}},{q="Quem pilota o Eletrocutor 6000?",a="Nenhum piloto é citado nos relatos da queda de Gnomeregan. O tanque luta pelo Mecangenheiro Termaplugue e pelos gnomos leprosos que o servem.",al={"quem pilota o eletrocutor 6000","piloto do eletrocutor"}},{q="Por que a máquina é tão volátil?",a="Seu chassi blindado canaliza corrente de alta voltagem, que ele desfere contra qualquer um que se aproxime. Esse poder elétrico bruto faz dele um dos guardiões mais perigosos da Launch Bay.",al={"por que ele dá choque","protótipo do eletrocutor","projeto de termaplugue"}},{q="Por que derrotar o Eletrocutor 6000 é importante para exploradores?",a="A máquina carrega a Chave da Oficina, um dispositivo essencial que destranca a entrada da porta dos fundos para os setores de engenharia mais profundos de Gnomeregan, permitindo que grupos de ataque façam um caminho mais rápido pelas instalações recuperadas.",al={"chave da oficina","por que matar o eletrocutor","saque do eletrocutor 6000"}},{q="O Eletrocutor é um autômato ou um veículo?",a="É um mecanotanque: uma máquina de guerra blindada com pernas de aranha de fabricação gnômica, agora voltada contra os pretensos libertadores de Gnomeregan.",al={"o eletrocutor é um robô","tipo de tanque aranha do eletrocutor"}}},fx={["48c81a6d"]={q="De que lado está o Eletrocutor 6000?",a="A máquina de guerra luta inteiramente a serviço do Mecânico Thermaplugg e de sua facção de gnomos leprosos enlouquecidos. Ele defende zelosamente a reivindicação de Thermaplugg sobre Gnomeregan, aniquilando quaisquer troggs, agentes da Aliança ou intrusos da Horda que se aventurem perto do Launch Bay.",al={"facção do eletrocutor","a quem o eletrocutor serve","aliança do eletrocutor"}},cad4dd7a={q="O que é o Eletrocutor 6000?",a="O Eletrocutor 6000 é um tanque-aranha mecânico sobrecarregado que guarda o Launch Bay em Gnomeregan. Estalando com corrente de alta voltagem, ele luta pelo Mecangenheiro Termaplugue e pelos gnomos leprosos que o seguem.",al={"quem é o eletrocutor 6000","o que é o eletrocutor 6000","história do eletrocutor 6000"}},["5513927c"]={q="O que o Eletrocutor 6000 quer?",a="O tanque serve à megalomania do Mecangenheiro Termaplugue. Seu propósito é eletrocutar e erradicar quaisquer invasores que ousem entrar nos setores mais profundos de Gnomeregan.",al={"objetivo do eletrocutor 6000","o que o eletrocutor quer","motivo do eletrocutor"}},e5de5943={q="Por que o Eletrocutor 6000 está no Launch Bay?",a="Posicionado no alto das passarelas superiores do Launch Bay, o tanque guarda as passagens elevadas e bloqueia o acesso às profundezas do complexo. Ele carrega a Chave da Oficina, servindo como um posto de controle pesadamente armado contra qualquer um que tente penetrar no coração da fortaleza de Termaplugue.",al={"por que o eletrocutor está aqui","por que o eletrocutor está no launch bay","propósito do eletrocutor"}},["06482735"]={q="Por que o Eletrocutor 6000 é temido?",a="A máquina é notória por sua potência letal. Seu chassi blindado canaliza uma corrente de alta voltagem que ela descarrega sobre qualquer um que se aproxime, tornando-a um dos guardiões mais perigosos entre os invasores e o coração da fortaleza de Termaplugue.",al={"por que o eletrocutor é temido","reputação do eletrocutor","por que o eletrocutor é famoso"}}},fp="20,292,30.317.0,16.208.0,44.135.0,36.133.0,31.185.0,66.210.0,49.129.0"}
P.entries["npc:elling-trias"] = {n="Elling Trias",s="Elling Trias administra a Trias' Cheese, uma pequena loja situada no movimentado Distrito Comercial de Ventobravo. Embora se apresente como um jovial e apaixonado vendedor de laticínios, ele opera discretamente como um dos corretores de informações mais bem conectados do reino. Por trás de peças de queijo e conversas cordiais, Trias mantém os ouvidos atentos a tudo, alcançando vários continentes.",h="Elling Trias administra a Trias' Cheese, uma pequena loja situada no movimentado Distrito Comercial de...",kw={"elaine trias","elling trias","mathias shaw","o diplomata desaparecido","avin","ventobravo","distrito comercial","queijo trias","tyrion"},ang={["class:Rogue"]="Qualquer praticante da sutileza reconhece que a queijaria de Elling é um ponto de encontro ideal. Sua proximidade com a Cidade Velha e seus fortes laços com Mathias Shaw fazem dele uma figura constante no submundo de Ventobravo.",["faction:Alliance"]="Elling atua como um pilar anônimo da espionagem da Aliança, filtrando silenciosamente rumores de Theramore a Amparo para proteger o reino da corrupção interna."},sec={{t="O Mestre Queijeiro",b="Para o cliente casual que passeia pelo Distrito Comercial, Elling Trias é apenas um artesão dedicado a finos queijos, trabalhando em sua loja ao lado da esposa Elaine e do filho Ben. Ele apregoa rodas de queijo com entusiasmo e conversa amigavelmente com os cidadãos. No entanto, aqueles que estão por dentro sabem que a Trias' Cheese é uma das fachadas mais confiáveis de Ventobravo. O burburinho constante do comércio da cidade oferece o disfarce perfeito para agentes, cortesãos e aventureiros que precisam trocar palavras discretas sem chamar a atenção da guarda da cidade."},{t="Uma Teia de Sussurros",b="A rede de informantes e aliados de Elling é impressionante para um comerciante. Ele mantém laços com o Mestre Mathias Shaw da AVIN, coordena com contatos da Igreja como o Bispo DeLavey e se corresponde com agentes em locais tão distantes quanto Vila Sombria, Ilha Theramore e as distantes Terras Pestilentas, perto de Amparo. Quando rumores estranhos surgem — sejam sobre bandidos das estradas ou movimentações discretas no campo —, Trias frequentemente junta as peças do quebra-cabeça muito antes de a corte real notar."},{t="The Missing Diplomat",b="Quando um diplomata de alto escalão desaparece em uma viagem para Theramore, Elling Trias torna-se peça fundamental para desvendar a conspiração. Orientando os investigadores até seus contatos — incluindo um agente afastado chamado Jorge e o velho amigo Tyrion —, Trias ajuda a desmascarar o envolvimento da Irmandade Défias no sequestro. Apesar de sua inteligência afiada e comentários cínicos, Elling reconhece que a trama atinge profundamente o coração da aristocracia de Ventobravo."}},faq={{q="Quem é Elling Trias?",a="Elling Trias é ostensivamente um vendedor de queijos que comanda a Trias' Cheese no Distrito Comercial de Ventobravo com sua família. Sob esse disfarce, ele é um experiente corretor de informações com ligações com a AVIN, a Igreja e postos avançados distantes por toda Azeroth.",al={"quem é elling","identidade de elling trias","cara do queijo trias"}},{q="Onde fica a sua queijaria?",a="Você pode encontrar a Trias' Cheese no Distrito Comercial de Ventobravo, acomodada na fileira de lojas ao longo do muro externo do canal, perto da passagem que leva à Cidade Velha.",al={"localização do queijo trias","onde fica elling trias","loja de trias ventobravo"}},{q="Qual é a sua ligação com a Irmandade Défias?",a="Trias não é membro da Irmandade Défias; em vez disso, ele monitora os passos deles por meio de sua rede de informantes. Ele ajuda aventureiros da Aliança a rastrear o envolvimento dos Défias em tramas subversivas, incluindo o sequestro de um diplomata real.",al={"trias défias","trias é dos défias"}},{q="Como ele conhece Mathias Shaw?",a="Shaw conhece Elling de longa data e recorre a ele quando os canais oficiais falham, embora nenhum dos dois goste disso: Shaw detesta pedir sua ajuda, e Elling resmunga sempre que seu trabalho acaba prestando um favor a Shaw e à AVIN. Sua loja funciona como um ponto de escuta informal onde investigações discretas podem ser iniciadas fora dos canais reais oficiais.",al={"trias e shaw","trias avin","trias é da avin"}},{q="Quem administra a loja com ele?",a="Elling administra a Trias' Cheese com sua esposa, Elaine Trias, e seu filho, Ben Trias. Juntos, eles mantêm a aparência de uma loja de comércio familiar comum e movimentada.",al={"família trias","esposa de elling trias"}},{q="Qual é o seu envolvimento na investigação de The Missing Diplomat?",a="Enviados a Trias pelo Bispo DeLavey, os investigadores utilizam a ampla rede de contatos de Elling — incluindo seus antigos associados Jorge e Tyrion — para rastrear os movimentos dos Défias e descobrir quem capturou o diplomata que ia para Theramore.",al={"o diplomata desaparecido trias","por que visitar o queijo trias"}}},fx={f0ad15b5={q="De que lado está Elling Trias?",a="Elling está firmemente ao lado de Ventobravo e da Aliança, apesar de operar nas sombras. Embora muitas vezes mascare suas atividades atrás da humilde fachada de um comerciante de queijos do Distrito Comercial, seus laços secretos conectam-se diretamente ao Mestre Mathias Shaw e ao AVIN. Ele trabalha ativamente contra subversivos como a The Defias Brotherhood para manter o reino seguro.",al={"elling trias é leal a ventobravo","para quem elling trias trabalha","elling trias é da aliança"}},fc385e9b={q="O que Elling Trias quer?",a="Publicamente, Elling não busca nada além de vender queijos finos ao lado de sua família. Na verdade, ele quer manter a segurança de Ventobravo coletando informações e eliminando ameaças à coroa. Quando crises surgem, ele usa sua rede de contatos de longo alcance para desvendar conspirações silenciosamente sem causar pânico público.",al={"motivo de elling trias","qual é o objetivo de elling trias","por que elling trias ajuda"}},e76b2a1d={q="Por que Elling Trias está aqui em Ventobravo?",a="Elling opera a partir do movimentado Distrito Comercial de Ventobravo porque uma popular loja de queijos oferece a cobertura perfeita para espionagem. Atrás de seu balcão, ele pode trocar sussurros, receber mensageiros e coordenar-se com agentes de inteligência por todo o reino sem problemas, enquanto parece ser um comerciante comum cuidando da loja com sua esposa e filho.",al={"por que elling trias está em ventobravo","por que elling fica em ventobravo","propósito de elling trias na cidade"}}},fp="12,377,23.523.0,17.478.0,20.442.1,20.243.0,33.161.0,49.235.1,30.324.0,27.163.0,62.220.1"}
P.entries["npc:elu"] = {n="Elu",s="Elu é um aprendiz de mantícora estabelecido no topo da Aldeia Vento Livre, em Mil Agulhas. Ansioso para iniciar seu treinamento formal e alçar voo pelos céus, ele incumbe viajantes da Horda de recuperar ovos de serpe selvagem em ninhos próximos.",h="Elu é um aprendiz de mantícora estabelecido no topo da Aldeia Vento Livre, em Mil Agulhas.",kw={"elu","aldeia vento livre","alcândora","mil agulhas","mantícora","serpe","ovos de serpe"},ang={["faction:Horde"]="Coletar ovos de serpe para Elu fortalece diretamente a rede de correio e transporte da Horda, mantendo postos remotos por toda Kalimdor conectados por via aérea.",["race:Tauren"]="Para aventureiros taurens, ajudar Elu é apoiar um companheiro de tribo que se esforça para dominar a arte antiga e vital de lidar com serpes, bem acima de suas terras ancestrais no desfiladeiro."},sec={{t="Um Aprendiz Ansioso",b="Empoleirado bem acima das planícies de sal e do fundo do desfiladeiro na Aldeia Vento Livre, Elu passa seus dias cuidando das montarias aéreas do assentamento enquanto sonha com seu próprio voo. Como um jovem aprendiz tauren, ele anseia por se juntar às fileiras dos mestres de mantícora que patrulham as imponentes mesetas de Kalimdor. No entanto, antes de poder começar o verdadeiro treinamento de voo, ele deve provar sua capacidade fornecendo novos espécimes de serpe para o poleiro, enviando aventureiros capazes para coletar ovos intactos das ferozes serpes selvagens que nidificam em Alcândora."}},faq={{q="Quem é Elu?",a="Elu é um aprendiz tauren de mantícora baseado na Aldeia Vento Livre, em Mil Agulhas, responsável por ajudar a obter e criar novas montarias para a rede aérea da Horda.",al={"elu aldeia vento livre","quem e elu","aprendiz tauren elu"}},{q="Por que Elu precisa de ovos de serpe?",a="Elu tem a tarefa de reabastecer o estábulo de serpes para os mestres de mantícora. Criar as feras a partir de ovos recém-coletados garante que elas possam ser devidamente treinadas e criar vínculos como montarias de confiança para a Horda.",al={"por que ovos de serpe","missao da serpe de elu","objetivo da missao de elu"}},{q="Para onde Elu envia aventureiros para encontrar ovos?",a="Ele direciona os aventureiros para Alcândora, uma meseta perigosa no oeste de Mil Agulhas onde colônias de serpes selvagens protegem ferozmente seus ninhos.",al={"onde encontrar ovos de serpe","onde fica alcandora","localizacao dos ovos de elu"}}},fx={["74f15e75"]={q="De que lado está Elu?",a="Elu é leal à Horda e aos seus companheiros tauren. Estacionado no alto das encostas da Aldeia Vento Livre, ele trabalha ao lado dos mestres Wind Rider da Horda para treinar e fornecer as montarias aéreas vitais para viajar por Kalimdor.",al={"facção de elu","elu é da horda","a quem elu serve"}},["3d25520c"]={q="Por que Elu está na Aldeia Vento Livre?",a="Elu serve como aprendiz de Wind Rider na Aldeia Vento Livre. Ele permanece aqui para ajudar os mestres de voo e conquistar seu lugar no céu, encarregado de garantir serpes frescas dos poleiros altos de Mil Agulhas para que possam ser treinadas para os cavaleiros da Horda.",al={"por que elu está em mil agulhas","elu na aldeia vento livre","propósito de elu"}},c552be8c={q="Com quem Elu está ligado?",a="Elu é aprendiz dos mestres Wind Rider da Horda. Ele responde aos treinadores e tratadores de feras que criam as serpes aladas de Kalimdor, trabalhando sob sua orientação na esperança de iniciar seu próprio treinamento formal como um Wind Rider.",al={"mestre de elu","para quem elu trabalha","wind riders de elu"}}},fp="3,217,19.520.0,11.169.0,30.209.0,45.140.0"}
P.entries["npc:eva-sarkhoff"] = {n="Eva Sarkhoff",s="Eva Sarkhoff é o resquício espectral da antiga governanta da Casa Barov, permanecendo ao lado de seu marido Lucien nos arredores dos horrores de Scolomântia. Torturada e morta pelo Açougueiro durante a queda de Castro das Flechas, seu espírito busca mortais corajosos para vingar suas mortes e destruir seus restos amaldiçoados.",h="Eva Sarkhoff é o resquício espectral da antiga governanta da Casa Barov, permanecendo ao lado de seu marido...",kw={"barov","castro das flechas","seita dos malditos","eva sarkhoff","krastinov","lucien sarkhoff","scolomântia","o açougueiro"},ang={["class:Priest"]="Testemunhar o tormento persistente de Eva e Lucien é um lembrete contundente da crueldade do Flagelo, clamando aos praticantes sagrados que concedam paz a suas almas inquietas e purifiquem a magia imunda que as aprisiona.",["race:Human"]="Eva e seu marido representam os criados comuns de Lordaeron que foram traídos por sua própria aristocracia corrupta quando a Casa Barov vendeu Castro das Flechas a Kel'Thuzad."},sec={{t="A Queda da Casa Barov",b="Eva serviu à abastada família Barov por décadas como governanta, cuidando da vasta fortaleza de Castro das Flechas ao lado de seu marido Lucien, o mordomo da família. Conforme os Barov se tornavam cada vez mais paranoicos quanto à sua mortalidade e sua vasta riqueza, eles selaram um pacto catastrófico com Kel'Thuzad. O solar foi gradualmente entregue à recém-formada Seita dos Malditos, deturpando a grandiosa residência até transformá-la em Scolomântia, uma academia secreta de necromancia. Eva e Lucien se esconderam nos corredores da fortaleza por seis meses, vasculhando em busca de comida enquanto viam sectários e monstruosidades tomarem sua casa aos poucos."},{t="O Bisturi do Açougueiro",b="Inevitavelmente descobertos pelo Flagelo, Eva e Lucien foram entregues à custódia do Doutor Theolen Krastinov, conhecido como o Açougueiro. Krastinov submeteu a dupla a semanas de experimentos agonizantes, usando magia sombria para prolongar suas vidas muito além do limiar da resistência mortal. Mesmo após a morte, seus cadáveres foram dados como alimento aos carniçais, enquanto seus espíritos inquietos ficaram acorrentados a Castro das Flechas, onde Eva agora implora aos aventureiros que passam que matem Krastinov e incinerem seus restos mortais."}},faq={{q="Quem era Eva Sarkhoff antes de morrer?",a="Eva Sarkhoff era a governanta da nobre família Barov, residindo e trabalhando na fortaleza de Castro das Flechas por décadas ao lado de seu marido, Lucien, que servia como mordomo.",al={"história de eva sarkhoff","quem é eva sarkhoff","lore de eva"}},{q="Como Eva morreu?",a="Depois de se esconderem por meses da Seita dos Malditos, Eva e Lucien foram descobertos e entregues ao Doutor Theolen Krastinov. Krastinov os torturou implacavelmente por semanas, mantendo-os vivos com magia sombria até que finalmente sucumbiram e tiveram seus cadáveres dados de alimento a carniçais.",al={"como eva sarkhoff morreu","morte de eva sarkhoff","quem matou eva"}},{q="Por que o fantasma de Eva ainda está em Castro das Flechas?",a="O tormento de Eva foi tão horrível e antinatural que seu espírito permaneceu preso ao plano mortal. Ela não pode partir para a eternidade até que o Doutor Krastinov seja morto e seus restos físicos dentro de Scolomântia sejam queimados.",al={"por que eva é um fantasma","espírito de eva","por que eva continua vagando"}}},fp="12,310,23.585.0,21.483.1,37.171.0,16.272.0,40.211.0"}
P.entries["npc:executor-arren"] = {n="Executor Arren",s="O Executor Arren é um oficial de alta patente dos Renegados destacado em Plangemortis. Ele supervisiona a defesa imediata e a consolidação do povoado à medida que mortos-vivos recém-despertados emergem de suas sepulturas. Arren coordena a campanha local contra zumbis irracionais do Flagelo, feras selvagens e os fanáticos invasores da Cruzada Escarlate.",h="O Executor Arren é um oficial de alta patente dos Renegados destacado em Plangemortis.",kw={"plangemortis","executor arren","renegados","vale teia da noite","cruzada escarlate","sylvanas","clareiras de tirisfal"},ang={["faction:Horde"]="O comando de linha de frente de Arren em Plangemortis representa o ponto de apoio inicial da Horda no norte de Lordaeron, garantindo a sobrevivência em meio a um ambiente hostil.",["race:Undead"]="O Executor Arren é um dos primeiros comandantes que cada Renegado conhece ao surgir em Tirisfal, dando-lhes a primeira amostra do dever sob a Dama Sombria."},sec={{t="Comandante de Plangemortis",b="Posicionado resolutamente do lado de fora da capela em Plangemortis, o Executor Arren atua como a principal voz militar para os Renegados recém-criados em suas terras de despertar. Enquanto os zeladores nas criptas orientam os mortos-vivos recém-erguidos em sua desorientação, Arren direciona seu foco para fora, rumo à sobrevivência. Sob o estandarte da Rainha Sylvana Correventos, ele organiza operações locais para varrer os zumbis irracionais que ameaçam as fronteiras do vilarejo, estabelecendo um território seguro à sombra da queda de Lordaeron."},{t="Protegendo as Terras Fronteiriças",b="Plangemortis está cercada por perigos muito mais mortais do que novatos confusos. Sob as ordens de Arren, batedores e iniciados atacam os aracnídeos cruéis que habitam o Vale Teia da Noite e eliminam predadores perigosos que rondam as bordas da floresta. Ao exigir uma ação decisiva de cada mão capaz, Arren testa a coragem dos recém-chegados, garantindo que apenas aqueles capazes de defender sua segunda chance de existência permaneçam a serviço da Dama Sombria."},{t="A Ameaça Carmesim",b="A maior preocupação estratégica de Arren reside na Cruzada Escarlate. Os fanáticos consideram todos os mortos-vivos monstruosidades que exigem erradicação total, falhando ou recusando-se a distinguir entre o Flagelo e os Renegados de livre arbítrio. Arren organiza ataques direcionados contra patrulhas Escarlates acampadas na natureza de Tirisfal, interceptando mensageiros e analisando despachos roubados para proteger Plangemortis de ser expurgada pelo fogo sagrado."}},faq={{q="Quem é o Executor Arren?",a="O Executor Arren é o oficial militar comandante que supervisiona Plangemortis nas Clareiras de Tirisfal. Ele organiza os Renegados recém-erguidos em uma força de combate eficaz para defender o vilarejo e proteger os arredores.",al={"papel de arren","quem é arren","executor de plangemortis"}},{q="Qual é a patente de um Executor entre os Renegados?",a="Os Executores são comandantes militares e administrativos de confiança na hierarquia dos Renegados. Eles governam guarnições locais, lideram operações em campo e impõem a vontade e a lei da Rainha Sylvana Correventos.",al={"título de executor","o que é um executor","patente de executor dos renegados"}},{q="Por que Arren envia recrutas contra os zumbis?",a="Os zumbis que rondam perto de Plangemortis são resquícios irracionais do Flagelo deixados para trás após a praga devastar Lordaeron. Arren ordena que sejam eliminados para que os mortos-vivos recém-despertados não sejam despedaçados ao sair das criptas.",al={"por que matar zumbis","missão the damned","flagelo irracional"}},{q="Por que a Cruzada Escarlate está nas Clareiras de Tirisfal?",a="A Cruzada Escarlate é uma facção humana radical dedicada a exterminar todos os mortos-vivos. Eles mantêm postos avançados pelas ruínas de Lordaeron e buscam ativamente expurgar os Renegados, considerando-os idênticos ao Flagelo.",al={"cruzada escarlate tirisfal","por que a cruzada está aqui","cruzados em plangemortis"}},{q="O que é o Vale Teia da Noite?",a="O Vale Teia da Noite é uma mina de ouro a noroeste de Plangemortis que foi invadida por aranhas. Os Renegados precisam do ouro de lá, então Arren envia recrutas para eliminar os aracnídeos aos poucos.",al={"caverna de aranhas em plangemortis","vale teia da noite","missão das aranhas de arren"}},{q="Para onde Arren envia os recrutas assim que terminam as tarefas dele?",a="Assim que as ameaças imediatas de Plangemortis são neutralizadas, Arren direciona recrutas capazes para Montalvo para se apresentarem ao Executor Zigano e apoiarem o esforço mais amplo dos Renegados nas Clareiras de Tirisfal.",al={"depois de plangemortis","para onde ir depois de arren","the executor in the field"}}},fx={["610ddc26"]={q="De que lado está o Executor Zigano?",a="O Executor Zigano é totalmente leal aos Renegados e à Grande Dama Sylvana Correventos. Como comandante militar local em Plangemortis, seu dever é garantir os campos iniciais para seus irmãos recém-despertados e eliminar quaisquer ameaças à sua jovem nação, sejam zumbis sem mente do Flagelo, feras locais ou os fanáticos da Cruzada Escarlate.",al={"aliança de arren","a quem o executor arren serve","facção de arren"}},["25e599ca"]={q="O que o Executor Zigano quer?",a="Zigano busca estabelecer firmemente o controle dos Renegados sobre Plangemortis e testar a determinação dos recém-erguidos. Ele quer os mortos-vivos sem mente limpos do cemitério, os aracnídeos invasores expurgados e os acampamentos próximos da Cruzada Escarlate destruídos para que novos recrutas possam partir em segurança para Montalvo e juntar-se à defesa mais ampla das Clareiras de Tirisfal.",al={"o que arren quer","objetivos de arren","propósito do executor arren"}},["3c8717b4"]={q="Por que o Executor Zigano está em Plangemortis?",a="Zigano está estacionado em Plangemortis para comandar a defesa inicial onde os Renegados recém-libertos rompem o túmulo pela primeira vez. Sem supervisão militar, recrutas confusos poderiam ser facilmente dominados pelo Flagelo sem mente que vaga pelas colinas ou cair presas dos batedores da Cruzada Escarlate que sondam o perímetro do assentamento.",al={"por que arren está em plangemortis","razão da localização de arren","por que o executor arren está aqui"}}},fp="14,332,23.510.0,24.454.0,18.435.1,22.220.0,44.211.0,49.217.0,46.218.0,27.181.0,58.189.0"}
P.entries["npc:executor-zygand"] = {n="Executor Zigano",s="O Executor Zigano é um comandante Renegado sênior alocado na prefeitura de Montalvo, supervisionando as operações defensivas e militares por toda a região central das Clareiras de Tirisfal. Respondendo diretamente ao alto-comando da Cidade Baixa, ele coordena o expurgo das forças da Cruzada Escarlate que avançam sobre o território Renegado.",h="O Executor Zigano é um comandante Renegado sênior alocado na prefeitura de Montalvo, supervisionando as...",kw={"arren","montalvo","guarda da morte","executor","maggot eye","cruzada escarlate","tirisfal","zigano"},ang={["faction:Horde"]="Viajantes de Kalimdor que visitam as Clareiras de Tirisfal veem em Zigano a liderança militar estruturada e disciplinada que impulsiona a luta dos Renegados para proteger Lordaeron.",["race:Undead"]="Para os Renegados que se aventuram para fora de Plangemortis, o Executor Zigano representa a autoridade militar mais ampla da Cidade Baixa, acolhendo novos cidadãos no serviço ativo contra seus piores inimigos."},sec={{t="Comando em Montalvo",b="Posicionado no coração administrativo de Montalvo, o Executor Zigano coordena a defesa regional para os Renegados após seu despertar inicial em Plangemortis. Servindo como superior direto de oficiais regionais como o Executor Arren e sentinelas de campo como a Necroguarda Lina, Zigano sintetiza as informações dos batedores e despacha recrutas capacitados para proteger as fronteiras de Lordaeron contra invasões."},{t="A Guerra Contra a Cruzada",b="A principal preocupação militar de Zigano é a presença fanática da Cruzada Escarlate, que infesta postos avançados pelas Clareiras de Tirisfal. Sob sua direção, agentes são enviados sistematicamente para golpear batedores, acampamentos e bases avançadas dos Cruzados, garantindo que os fanáticos nunca reúnam forças suficientes para ameaçar os acessos à Cidade Baixa."}},faq={{q="Quem é o Executor Zigano?",a="O Executor Zigano é um oficial Renegado sênior que opera a partir de Montalvo, nas Clareiras de Tirisfal. Ele comanda as guarnições locais da Guarda da Morte, recebe relatórios táticos de oficiais de patentes inferiores e lidera campanhas militares contra ameaças locais.",al={"zigano","quem é o executor zigano","função de zigano"}},{q="Onde posso encontrar o Executor Zigano?",a="Ele fica dentro ou perto da prefeitura de Montalvo, o principal assentamento Renegado nas Clareiras de Tirisfal, localizado logo ao norte da Cidade Baixa.",al={"localização de zigano","onde fica zigano","mapa do executor zigano"}},{q="Qual é o principal objetivo de Zigano nas Clareiras de Tirisfal?",a="Seu foco principal é orquestrar a guerra regional contra a Cruzada Escarlate. Ele monitora a movimentação dos fanáticos por toda Tirisfal e emite ordens para desmantelar seus acampamentos e lideranças antes que marchem rumo à Cidade Baixa.",al={"objetivo da missão de zigano","por que lutar contra a cruzada","propósito de zigano"}},{q="Quem responde ao Executor Zigano?",a="Zigano atua como o oficial superior do Executor Arren, que comanda os recrutas iniciais em Plangemortis, bem como de sentinelas de campo como a Necroguarda Lina, que patrulha as principais encruzilhadas das Clareiras de Tirisfal.",al={"subordinados de zigano","quem serve a zigano","superior de arren"}},{q="O Executor Zigano lida com ameaças de mortos-vivos renegados?",a="Sim. Além de combater a Cruzada Escarlate, Zigano emite recompensas regionais para eliminar mortos-vivos selvagens e saqueadores renegados perigosos, como o gnoll roubador de cadáveres Maggot Eye, que põem em risco as viagens pelas clareiras.",al={"maggot eye","recompensas de zigano","missões de procurado"}},{q="Qual é a patente de um \"Executor\" entre os Renegados?",a="Um Executor atua como governador regional e comandante militar dentro da hierarquia dos Renegados. Eles administram assentamentos, comandam unidades locais da Guarda da Morte e impõem o domínio da Rainha Sylvana pelas regiões disputadas de Lordaeron.",al={"o que é um executor","patente de executor","executor renegado"}}},fx={["1dc7a0d0"]={q="De que lado está o Executor Zigano?",a="O Executor Zigano é totalmente devoto aos Renegados e à Grande Dama Sylvana Correventos. Como oficial militar em Montalvo, ele serve à Cidade Baixa coordenando as defesas locais, dirigindo guardas da morte e organizando ataques estratégicos para garantir as Clareiras de Tirisfal contra os inimigos implacáveis dos Renegados.",al={"facção de zigano","a quem zigano serve","lado do executor zigano"}},["673b7cce"]={q="Por que o Executor Zigano está estacionado em Montalvo?",a="Zigano está estacionado em Montalvo porque o assentamento serve como o principal bastião militar dos Renegados diretamente ao norte da Cidade Baixa. A partir daqui, ele monitora ameaças críticas por todas as Clareiras de Tirisfal, gerenciando patrulhas de linha de frente e implantando combatentes experientes para manter as linhas de suprimentos vitais e as fronteiras seguras.",al={"por que zigano está aqui","propósito de zigano em montalvo","por que o executor zigano está em montalvo"}}},fp="15,297,16.392.0,22.341.0,23.236.0,33.146.0,46.239.0,31.198.0,49.226.0,53.231.0"}
P.entries["npc:falfindel-waywarder"] = {n="Falfindel Waywarder",s="Falfindel Waywarder é um druida elfo noturno posicionado em Thalanaar, o entreposto que vigia a fronteira entre Feralas e as Mil Agulhas. Deste posto de vigia na fronteira, ele trabalha para curar terras corrompidas e proteger a natureza selvagem do sul de Kalimdor. Viajantes que descem da Cordilheira das Torres de Pedra ou dos Sertões frequentemente o encontram buscando ajuda para restaurar o equilíbrio das terras selvagens.",h="Falfindel Waywarder é um druida elfo noturno posicionado em Thalanaar, o entreposto que vigia a fronteira...",kw={"vale carbonizado","falfindel","feralas","cordilheira das torres de pedra","thalanaar","mil agulhas","waywarder","fogo-fátuos"},ang={["class:Druid"]="Seus esforços para enviar espíritos da floresta e fogo-fátuos para curar os solos crestados da Cordilheira das Torres de Pedra refletem a sagrada missão druídica de restauração.",["faction:Alliance"]="Para viajantes da Aliança fazendo a longa jornada para o sul vindo dos Sertões ou da Cordilheira das Torres de Pedra, Falfindel e a vigília em Thalanaar oferecem um refúgio acolhedor.",["race:NightElf"]="Falfindel representa a vigilância do seu povo nas fronteiras de Kalimdor, lutando para curar as cicatrizes da natureza e guardar contra os perigos invasores da vida selvagem."},sec={{t="Vigia na Fronteira Sul",b="Thalanaar marca o portal onde as florestas exuberantes de Feralas descem em direção aos platôs imponentes e às planícies áridas de sal de Mil Agulhas. Falfindel Waywarder vigia este entreposto remoto, cumprimentando viajantes exaustos que se aventuraram de longe pelo continente. Cercado por grandiosidade natural e perigos à espreita, ele serve como ponto de contato para os elfos noturnos que buscam monitorar tanto ameaças locais quanto calamidades ambientais mais amplas por toda Kalimdor."},{t="Curando o Vale Carbonizado",b="Apesar de seu posto ao sul, Falfindel continua profundamente preocupado com a devastação muito ao norte, na Cordilheira das Torres de Pedra. O Vale Carbonizado, arruinado por feitiçaria sombria e destruição flamejante, permanece como uma dolorosa cicatriz na natureza de Kalimdor. Quando aventureiros prestam ajuda a Falfindel para auxiliar em sua recuperação, ele invoca os espíritos da floresta. Evocando enxames de fogo-fátuos, ele os orienta a se apressarem para o norte rumo à Cordilheira das Torres de Pedra para começar a recuperar a terra queimada."},{t="Olhos nos Javatuscos e nas Terras Ermas",b="Além de coordenar esforços de restauração, Falfindel mantém uma vigilância atenta sobre a região circundante, incluindo os covis de javatuscos do Urzal dos Tuscos. Ao analisar diários recuperados e reunir informações sobre a liderança dos javatuscos, Falfindel garante que a Aliança compreenda os perigos crescentes que ameaçam as passagens entre Feralas e os desertos centrais."}},faq={{q="Onde fica Falfindel Waywarder?",a="Falfindel está posicionado em Thalanaar, o entreposto dos elfos noturnos situado na fronteira entre Feralas e Mil Agulhas.",al={"localização de falfindel","onde fica falfindel","mapa de falfindel waywarder"}},{q="Qual é o papel de Falfindel em Thalanaar?",a="Ele atua como druida e guia no entreposto, monitorando ameaças regionais como os javatuscos do Urzal dos Tuscos e coordenando esforços de restauração para terras arruinadas como o Vale Carbonizado.",al={"o que falfindel faz","propósito de falfindel","missões de falfindel"}},{q="Como Falfindel ajuda o Vale Carbonizado?",a="Quando aventureiros ajudam nos esforços de Reclaiming the Charred Vale, Falfindel canaliza um encantamento para evocar fogo-fátuos da floresta, enviando-os ao norte para a Cordilheira das Torres de Pedra a fim de curar a terra assolada.",al={"falfindel cordilheira das torres de pedra","falfindel vale carbonizado","reclaiming the charred vale falfindel"}},{q="Por que Falfindel está interessado no Urzal dos Tuscos?",a="Ele estuda a ameaça representada pelos javatuscos do Urzal e inspeciona itens como o Diário do Monocelha para monitorar a influência dos seus líderes, como The Crone of the Kraul.",al={"the crone of the kraul falfindel","diário do monocelha falfindel","falfindel javatuscos"}},{q="Falfindel é aliado da Aliança ou neutro?",a="Falfindel é um druida elfo noturno aliado a Darnassus e à Aliança. Viajantes da Horda que se aproximarem de Thalanaar acharão o entreposto hostil.",al={"falfindel é da aliança","facção de falfindel"}},{q="O que Falfindel diz aos viajantes?",a="Ele cumprimenta calorosamente visitantes amigáveis reconhecendo sua longa jornada, comentando: \\\"Você parece ter viajado de longe\\\".",al={"falfindel diálogo","falfindel citação"}}},fx={["444437e8"]={q="Quem é Falfindel Waywarder?",a="Falfindel Waywarder é um elfo noturno posicionado no posto avançado de Thalanaar, na fronteira entre Feralas e Mil Agulhas. Sintonizado com a saúde da terra e com os perigos que enfrentam os confins meridionais de Kalimdor, ele vigia os viajantes e trabalha em conjunto com outros elfos noturnos para combater ameaças emergentes à vida selvagem.",al={"quem é falfindel","história de falfindel waywarder","quem é falfindel waywarder"}},e0cb4d91={q="O que Falfindel Waywarder deseja?",a="Falfindel busca proteger a frágil vida selvagem e ajudar na cura de terras devastadas. Ele orienta aliados a invocar espíritos da floresta para revitalizar o Vale Carbonizado, coordena entregas para manter os postos avançados locais abastecidos e busca eliminar a bruxa quilboar corrompida que espreita dentro do Urzal dos Tuscos.",al={"o que falfindel quer","objetivos de falfindel","propósito das missões de falfindel"}},["2bf92e29"]={q="Por que Falfindel Waywarder está aqui?",a="Falfindel serve como druida e guia em Thalanaar, vigiando a passagem entre Mil Agulhas e Feralas. Deste posto avançado remoto, ele monitora a crescente ameaça dos quilboars que se espalham pelos Sertões e coordena esforços para restaurar o equilíbrio nas florestas devastadas por todo o centro e sul de Kalimdor.",al={"por que falfindel está aqui","por que falfindel está em thalanaar","objetivo de falfindel"}}},fp="19,367,28.456.0,24.471.0,35.366.0,37.119.0,38.190.0,41.185.0,46.172.0,50.139.0,37.132.0"}
P.entries["npc:falla-sagewind"] = {n="Falla Vento Sábio",s="Falla Vento Sábio é uma mística tauren reclusa empoleirada no alto de um pico rochoso com vista para a região central dos Sertões. Posicionada entre a Encruzilhada e o Oásis das Águas Claras, ela estuda as anomalias naturais e místicas que perturbam as terras ao redor. Aventureiros que investigam a corrupção distorcida que emana da Caverna Ululante próxima costumam buscar sua orientação.",h="Falla Vento Sábio é uma mística tauren reclusa empoleirada no alto de um pico rochoso com vista para a região...",kw={"sertões","encruzilhada","falla","estilhaço chamejante","oásis das águas claras","pesadelos","vento sábio","tauren","caverna ululante"},ang={["class:Druid"]="Os druidas reconhecerão Falla como uma aliada crucial no rastreamento da trágica decadência de Naralex e dos Druids of the Fang dentro da Caverna Ululante.",["faction:Horde"]="Falla ajuda a Horda interpretando presságios estranhos e relíquias corrompidas trazidas por batedores das savanas disputadas dos Sertões.",["race:Tauren"]="Falla Vento Sábio exemplifica o dever tauren de serena custódia sobre a terra, vigiando a podridão espiritual de lugares altos enquanto seus irmãos defendem as estradas abaixo."},sec={{t="Vigia do Penhasco Alto",b="Falla Vento Sábio monta seu acampamento muito acima da poeira e da agitação das trilhas dos Sertões, situada em um cume isolado logo a sudoeste da Encruzilhada. Desse ponto de observação, ela mantém uma vigília solene sobre as frágeis savanas abaixo, observando as mudanças repentinas no comportamento da vida selvagem e a corrupção invasora que surge das fissuras subterrâneas da Caverna Ululante. Sua vigília solitária a separa do comércio diário da Encruzilhada, posicionando-a como uma eremita observadora sintonizada com os espíritos e as feridas silenciosas da terra."},{t="O Pesadelo Acordado",b="Quando estranhos estilhaços pulsantes são extraídos das feras mutantes da Caverna Ululante, viajantes sábios são instruídos a escalar os penhascos em direção a Falla. Ela ajuda a interpretar as magias distorcidas que desfazem a ordem natural dos oásis. Reconhecendo os sinais sombrios do Sonho Esmeralda se corrompendo sob a terra, ela envia heróis aos sábios druidas do Círculo Cenariano em busca de respostas mais profundas sobre o pesadelo que cria raízes na região."}},faq={{q="Quem é Falla Vento Sábio?",a="Falla Vento Sábio é uma mística tauren solitária que reside em um penhasco alto a sudoeste da Encruzilhada, nos Sertões. Ela vigia a terra e ajuda os viajantes que procuram compreender as estranhas aflições mágicas que se espalham pela região.",al={"quem é falla vento sábio","quem é falla","história de falla vento sábio"}},{q="Onde posso encontrar Falla Vento Sábio?",a="Ela fica no topo de um pico montanhoso íngreme diretamente a sudoeste da Encruzilhada e ao norte do Oásis das Águas Claras. Chegar ao seu acampamento exige subir pelas trilhas rochosas que partem da savana ao redor.",al={"localização de falla vento sábio","onde fica falla","como chegar a falla vento sábio"}},{q="Por que Falla Vento Sábio se interessa pela Caverna Ululante?",a="Falla ajuda a investigar a estranha magia encontrada em um estilhaço chamejante recuperado da Caverna Ululante. Ela direciona os viajantes a druidas experientes para obter mais conselhos.",al={"falla caverna ululante","por que falla se importa com o oásis","falla estilhaço chamejante"}},{q="Falla Vento Sábio é afiliada a algum clã ou família?",a="Ela compartilha o sobrenome Vento Sábio com outros taurens, mas nenhuma ligação familiar está confirmada.",al={"família vento sábio","quem são os vento sábio","falla é parente de tahu"}},{q="Quais missões envolvem Falla Vento Sábio?",a="Falla está envolvida nas investigações ao redor da Caverna Ululante, especialmente ao entregar ou continuar missões como Estilhaço Chamejante e In Nightmares, que se aprofundam no sonho sombrio que corrompe os oásis locais.",al={"missões de falla vento sábio","missões de falla","missão in nightmares"}},{q="Jogadores da Aliança podem interagir com Falla Vento Sábio?",a="Sim. Falla ajuda viajantes de ambas as facções com o Estilhaço Chamejante, enviando aventureiros da Aliança a Mathrengyl Ursivagus em Darnassus e aventureiros da Horda a Hamuul Runetotem no Penhasco do Trovão.",al={"falla vento sábio é hostil","falla amigável com a aliança"}}},fx={["53e3505a"]={q="De que lado está Falla Vento Sábio?",a="Falla Vento Sábio é uma tauren que não segue a bandeira de nenhuma facção. Posicionada nas alturas acidentadas dos Sertões, ela ajuda viajantes tanto da Horda quanto da Aliança que investigam as corrupções não naturais que se espalham a partir da Caverna Ululante, e auxilia aqueles que trabalham para purificar a terra.",al={"facção de falla vento sábio","falla vento sábio é da horda","quem falla vento sábio serve"}},["709098cb"]={q="O que Falla Vento Sábio deseja?",a="Falla Vento Sábio busca entender e enfrentar a corrupção crescente que escoa da Caverna Ululante. Quando aventureiros trazem a ela relíquias curiosas, como estilhaços brilhantes retirados das criaturas lá dentro, ela trabalha para descobrir o pesadelo que está criando raízes dentro das nascentes subterrâneas.",al={"objetivos de falla vento sábio","o que falla quer","propósito de falla vento sábio"}},["26262d64"]={q="Por que Falla Vento Sábio está aqui?",a="Falla Vento Sábio vigia o cume de uma montanha a sudoeste da Encruzilhada, com vista para o Oásis das Águas Claras e a entrada próxima da Caverna Ululante. Desta posição elevada, ela monitora a corrupção da terra e orienta viajantes que descobrem relíquias sombrias ligadas aos sonhadores perturbados abaixo.",al={"por que falla vento sábio está nos sertões","por que falla está na montanha"}}},fp="14,352,24.528.0,20.446.1,22.242.0,32.209.0,56.171.0,53.89.0,35.214.0,50.194.0"}
P.entries["npc:fallen-hero-of-the-horde"] = {n="Herói Caído da Horda",s="O Herói Caído da Horda é o espírito persistente de um guerreiro orc que vigia a estrada ao sul que sai do Pântano das Mágoas. Preso pelo arrependimento e pela desonra, ele alerta os viajantes que passam sobre os horrores à espera deles na Barreira do Inferno e procura campeões dispostos a libertar seus soldados torturados da servidão demoníaca.",h="O Herói Caído da Horda é o espírito persistente de um guerreiro orc que vigia a estrada ao sul que sai do...",kw={"allistarj","herói caído da horda","grol the destroyer","lieutenant kirith","razelikh the defiler","sevine","pedras de aprisionamento","swamp talker"},ang={["class:Warrior"]="Como um guerreiro caído de renome, sua afinidade espectral ressoa fortemente com aventureiros marciais que compreendem a dor de sobreviver quando seus companheiros tombaram.",["faction:Horde"]="O herói personifica a agonia de um guerreiro cuja honra foi arrancada pela crueldade demoníaca, apelando aos aventureiros da Horda para vingar seu esquadrão perdido e limpar a mancha da derrota de seu legado."},sec={{t="Um comando trágico",b="Em vida, este guerreiro foi um célebre campeão enviado com um regimento selecionado de soldados para investigar a Barreira do Inferno e relatar a presença da Legião Ardente. O despacho dele nunca chegou ao destino; o mensageiro enviado ao norte em direção a Pedregal foi emboscado e morto pelo Swamp Talker e seus murlocs. Isolado, sem ordens nem reforços, o comandante acabou marchando com seus soldados rumo ao sul, entrando nos ermos devastados para enfrentar a escuridão crescente. Foi um erro de julgamento fatal. Sobrepujado pelas forças demoníacas, seu exército foi dispersado, capturado e submetido a tormentos horríveis pelas mãos do senhor do medo Razelikh the Defiler."},{t="O preço do fracasso",b="Capturado ao lado de seu tenente, Kirith, o comandante suportou torturas brutais nas Cavernas Serpeantes enquanto seus captores arrancavam as almas de seus homens sobreviventes. Escapando apenas para sucumbir aos ferimentos fatais perto da fronteira do pântano, o espírito do herói permanece atado ao limiar da Barreira do Inferno. Seus soldados sofreram um destino ainda mais sombrio: suas carcaças sem alma foram vinculadas a pedras místicas, servindo como servos imortais divididos entre Razelikh e seus tenentes — Archmage Allistarj, Lady Sevine e Grol the Destroyer. Até que suas pedras de aprisionamento de alma sejam estilhaçadas e seu tormento termine, seu espírito inquieto não terá paz."}},faq={{q="Quem foi o Herói Caído em vida?",a="Ele era um guerreiro orc veterano escolhido para liderar uma força de reconhecimento na Barreira do Inferno a fim de avaliar a ameaça demoníaca. Ele morreu devido a ferimentos graves após escapar da tortura pelas mãos de Razelikh the Defiler, deixando seu espírito retido na estrada que sai do Pântano das Mágoas.",al={"identidade do herói caído","nome do herói caído","quem é o herói caído"}},{q="Por que ele assombra a fronteira da Barreira do Inferno?",a="Ele está preso pela vergonha de ter perdido seu regimento e falhado em sua missão. Ele se recusa a partir até que aventureiros corajosos se aventurem ao sul para destruir as pedras de aprisionamento que mantêm seus soldados em servidão eterna à Legião Ardente.",al={"por que ele é um fantasma","fantasma do herói caído","por que ele está aqui"}},{q="O que aconteceu com as ordens que ele enviou para Pedregal?",a="O batedor que levava seu relatório urgente de volta ao entreposto de Pedregal foi emboscado e morto por murlocs no pântano liderados pelo Swamp Talker. Como o relatório se perdeu, os reforços nunca chegaram, levando o herói a avançar sozinho para a Barreira do Inferno.",al={"ordens perdidas","o que aconteceu com as ordens dele","mensageiro do swamp talker"}},{q="O que aconteceu com o tenente dele, Kirith?",a="O Lieutenant Kirith sofreu experimentos demoníacos dentro das Cavernas Serpeantes. A alma dele foi corrompida e distorcida, transformando sua forma física em um monstruoso caçador vil à espreita nas profundezas da caverna.",al={"lieutenant kirith","quem é kirith","o que aconteceu com kirith"}},{q="Por que os soldados dele são invulneráveis?",a="Razelikh e seus tenentes separaram as almas dos soldados cativos de sua carne. Sem uma alma, seus corpos físicos não podem morrer de verdade. Eles só podem ser libertados se seus corpos forem castigados até quase a desintegração, tornando as pedras de aprisionamento de alma próximas brevemente vulneráveis à destruição.",al={"soldados invulneráveis","pedras de aprisionamento","servos de razelikh"}}},fp="24,325,16.645.0,20.641.1,32.284.0,51.232.0,47.259.0,40.194.1,34.293.1"}
P.entries["npc:fandral-staghelm"] = {n="Fandral Guenelmo",s="O Arquidruida Fandral Guenelmo lidera os druidas do Círculo Cenariano a partir do Enclave Cenariano em Darnassus. Assumindo o poder após Malfurion Tempesfúria desaparecer no Sonho Esmeralda, ele defendeu o plantio da nova Árvore do Mundo, Teldrassil. Orgulhoso, ríspido e incansavelmente ambicioso, Fandral defende um agressivo ressurgimento kaldorei que frequentemente o coloca em conflito com a Alta-sacerdotisa Tyrande Murmuréolo.",h="O Arquidruida Fandral Guenelmo lidera os druidas do Círculo Cenariano a partir do Enclave Cenariano em...",kw={"círculo cenariano","darnassus","fandral","malfurion","rajaxx","areias variáveis","guenelmo","teldrassil","valstann"},ang={["class:Druid"]="Guenelmo comanda os druidas darnassianos, conduzindo o Círculo Cenariano em direção à autoridade mundana direta enquanto entra em conflito com os ensinamentos tradicionais do adormecido Malfurion Tempesfúria.",["faction:Alliance"]="Embora Teldrassil sirva como um bastião da Aliança no norte de Kalimdor, Guenelmo vê as raças mais jovens com um desdém mal disfarçado, tolerando sua presença apenas conforme a conveniência política exige.",["race:NightElf"]="Como um dos principais líderes de Darnassus, Fandral personifica o orgulho e a fúria kaldorei, impulsionando o povoamento de Teldrassil mesmo enquanto os cidadãos comuns sentem a divisão entre seu enclave e o Templo da Lua."},sec={{t="Arquiteto de Teldrassil",b="Após a Terceira Guerra e o sacrifício de Nordrassil no topo do Monte Hyjal, os elfos noturnos perderam sua imortalidade e seu santuário sagrado. Quando Malfurion Tempesfúria desapareceu, Fandral assumiu a liderança dos druidas e convenceu o Círculo dos Anciãos de que era hora de seu povo se reconstruir e recuperar sua imortalidade. Com a aprovação do Círculo, ele liderou os druidas no cultivo de Teldrassil na costa de Kalimdor. Ele imaginou o galho colossal como um monumento à perseverança kaldorei e um receptáculo para restaurar sua supremacia perdida, muito embora os Aspectos Dragônicos tenham deliberadamente recusado suas bênçãos a esse empreendimento não aprovado."},{t="Tragédia nas Areias Variáveis",b="Um milênio antes da Primeira Guerra, Fandral serviu como comandante de campo kaldorei em Silithus durante a Guerra das Areias Variáveis. Renomado entre os insectoides qiraji como \\\"Kar'sis\\\" — a Mão da Terra —, ele manteve as linhas de frente ao lado de seu amado e único filho, Valstann. Explorando a devoção de Fandral, o General qiraji Rajaxx armou um ardil contra a Vila do Vento Sul e capturou Valstann, executando-o impiedosamente diante do horrorizado Arquidruida. A perda despedaçou o espírito de Fandral, precipitando uma retirada devastadora e consolidando um ódio amargo e permanente pelo enxame que permanece gravado em sua postura altiva."},{t="Rivalidade e Soberba",b="Dentro dos galhos de mármore de Darnassus, Fandral governa os assuntos kaldorei com uma mão altiva e inflexível. Ao contrário da Alta-sacerdotisa Tyrande Murmuréolo, que favorece a preservação espiritual e a diplomacia cautelosa, Fandral vê a expansão militar e a força decisiva como primordiais para a sobrevivência de seu povo."}},faq={{q="Quem é Fandral Guenelmo?",a="Fandral Guenelmo é o Arquidruida em exercício do Círculo Cenariano em Darnassus, presidindo os druidas kaldorei na ausência de Malfurion Tempesfúria. Conhecido por seu temperamento explosivo e ambições imperiais, ele é o principal visionário por trás da criação de Teldrassil.",al={"história de fandral","quem é o arquidruida","arquidruida de darnassus"}},{q="Por que Fandral não se dá bem com Tyrande?",a="Fandral defende o ressurgimento militar kaldorei, a expansão agressiva e a recuperação da imortalidade perdida. Tyrande Murmuréolo busca uma orientação espiritual cautelosa por meio de Eluna. Suas visões conflitantes para o futuro dos elfos noturnos pós-Hyjal geram forte atrito político em Darnassus.",al={"fandral e tyrande","por que druidas e sacerdotisas discordam","guenelmo vs murmuréolo"}},{q="Por que Teldrassil foi plantada?",a="Após a Batalha do Monte Hyjal, Nordrassil ficou marcada e os elfos noturnos perderam sua imortalidade. Com o desaparecimento de Malfurion, Fandral convenceu o Círculo dos Anciãos de que era hora de seu povo se reconstruir e recuperar sua imortalidade e, com a aprovação do Círculo, ele e os druidas mais poderosos cultivaram Teldrassil.",al={"quem criou teldrassil","por que fandral plantou teldrassil","origem de teldrassil"}},{q="O que aconteceu com o filho de Fandral?",a="Durante a Guerra das Areias Variáveis em Silithus, o filho de Fandral, Valstann, foi atraído para uma emboscada na Vila do Vento Sul. O General qiraji Rajaxx capturou Valstann e o chacinou na frente de Fandral, deixando o Arquidruida desolado pela dor e permanentemente amargurado.",al={"filho de fandral","quem foi valstann","valstann guenelmo"}},{q="Onde Fandral Guenelmo pode ser encontrado?",a="Fandral fica no topo do Enclave Cenariano em Darnassus, cercado por seus druidas leais e pelos assuntos supervisionáveis da capital kaldorei.",al={"onde está fandral","localização de fandral","líder do enclave cenariano"}}},fx={d5bab569={q="De que lado está Fandral Guenelmo?",a="Fandral é o Arquidruida de Darnassus e um líder dentro do Círculo Cenariano, defendendo os Kaldorei e a Aliança. No entanto, sua lealdade é ferozmente nacionalista. Em vez de se submeter docilmente à cautela tradicional dos anciãos Cenarianos ou ao sacerdócio de Eluna, Fandral age estritamente no que ele percebe ser o interesse militarista e ousado do povo elfo noturno.",al={"facção de fandral guenelmo","quem fandral serve","aliança de fandral"}},adee2909={q="O que Fandral Guenelmo deseja?",a="Fandral deseja a restauração do poder, da imortalidade e do domínio territorial dos elfos noturnos. Frustrado por séculos de isolamento passivo, ele insistiu no plantio da Árvore do Mundo Teldrassil para substituir Nordrassil. Ele vislumbra uma nação Kaldorei agressiva pronta para conquistar suas fronteiras, expandir-se ousadamente por Kalimdor e recuperar a glória perdida e o vigor de seu passado antigo.",al={"qual o objetivo de fandral guenelmo","ambições de fandral","o que o arquidruida guenelmo quer"}},["6d220bca"]={q="Por que Fandral Guenelmo está em Darnassus?",a="Com Malfurion Tempesfúria preso e incapacitado no Sonho Esmeralda, Fandral ocupou o vazio como Arquidruida. Ele governa os druidas do Círculo Cenariano das alturas do Enclave Cenariano em Darnassus, governando ao lado da Alta Sacerdotisa Tyrande Murmuréolo e guiando ativamente o futuro político e mágico de Teldrassil.",al={"por que fandral está em darnassus","por que fandral guenelmo está no local","por que fandral está aqui"}},["53c16312"]={q="Por que Fandral Guenelmo é famoso?",a="Muito antes de liderar o plantio de Teldrassil, Fandral serviu como um brilhante comandante de campo Kaldorei durante a Guerra das Areias Movediças em Silithus. Seu comando tático devastador contra o enxame de insetoides rendeu-lhe o título de Kar'sis — a Mão da Terra — entre os qiraji, que temiam sua fúria no campo de batalha até orquestrarem a trágica execução de seu filho.",al={"fandral famoso","por que fandral é temido","fandral mão da terra"}}},fp="16,417,23.634.0,29.638.0,18.306.0,24.261.0,43.290.0,27.323.0,31.269.0,36.135.0"}
P.entries["npc:farmer-furlbrow"] = {n="Fazendeiro Taturana",s="O Fazendeiro Theodore Furlbrow é um cultivador de abóboras despejado de Cerro Oeste, ilhado ao lado de sua esposa Verna na estrada perto do Sítio dos Jansen. Expulsos de sua casa pela Irmandade Défias, o casal está tentando consertar sua carroça quebrada e fugir para a Floresta de Elwynn.",h="O Fazendeiro Theodore Furlbrow é um cultivador de abóboras despejado de Cerro Oeste, ilhado ao lado de sua...",kw={"blanchy","défias","furlbrow","herança de família","jansen","abóbora","theodore","verna","carroça","relógio"},ang={["faction:Alliance"]="A difícil situação de Theodore Furlbrow representa o colapso total da autoridade civil em Cerro Oeste, onde cidadãos leais do reino precisam abandonar seus lares sem soldados reais para defendê-los."},sec={{t="Uma Vida Empacotada em uma Carroça",b="Theodore Furlbrow outrora cultivava uma plantação de abóboras no norte de Cerro Oeste, mas a crescente onda de crimes forçou ele e sua esposa, Verna, a abandonarem tudo o que possuíam. Reunindo o que puderam salvar, eles partiram em direção à segurança da Floresta de Elwynn, instando vizinhos como o Fazendeiro Saldanha a fazerem o mesmo. O desastre aconteceu ao longo da estrada perto do Sítio dos Jansen quando a carroça quebrou, deixando-os ilhados à vista de bandidos e feras selvagens. Enquanto Verna cuida de sua amada égua Blanchy, Theodore observa a estrada com crescente desespero, desesperado para recuperar pertences estimados — como o relógio de bolso presenteado pelo pai de Verna no dia de seu casamento — e na esperança de alertar o Morro da Sentinela sobre os bandidos que se aproximam."},{t="Evidência de Confisco de Terras",b="Antes de os Furlbrow fugirem, capangas da Irmandade Défias pressionaram Theodore e pegaram a escritura de suas terras cultiváveis, comassinada por Verna, pensando ser útil para forjar suas próprias escrituras. Aventureiros que recuperarem a escritura dos bandidos podem devolvê-la a ele: se Cerro Oeste algum dia voltar a ser adequada para pessoas honestas, ela permitirá que os Furlbrow reivindiquem suas terras."}},faq={{q="Quem é o Fazendeiro Taturana?",a="Theodore Furlbrow é um fazendeiro de abóboras desabrigado do norte de Cerro Oeste. Ele e sua esposa Verna foram forçados a sair de sua propriedade pela Irmandade Défias e atualmente estão ilhados ao lado de sua carroça quebrada perto do Sítio dos Jansen.",al={"fazendeiro taturana","theodore furlbrow","quem é furlbrow"}},{q="Por que o Fazendeiro Taturana está ilhado na estrada?",a="Enquanto fugia de Cerro Oeste rumo à segurança da Floresta de Elwynn, sua carroça quebrou. Até que consiga consertar a carroça ou encontrar ajuda, ele e sua esposa estão presos acampando à beira da estrada com sua velha égua, Blanchy.",al={"por que a carroça dele quebrou","por que furlbrow está na estrada","carroça quebrada cerro oeste"}},{q="Que relíquia de família o Fazendeiro Taturana perdeu?",a="Durante sua fuga apressada da fazenda, Theodore deixou para trás um estimado relógio de bolso presenteado pelo pai de Verna no dia de seu casamento. Ele pede aos viajantes corajosos o bastante para navegar pelas propriedades rurais infestadas de bandidos que o tragam de volta para ele.",al={"relógio de herança esquecido","relógio de furlbrow","relógio de bolso"}},{q="O Fazendeiro Taturana tem família fora de Cerro Oeste?",a="Nenhum parente além de Cerro Oeste está registrado. Sua família é sua esposa, Verna, que está ilhada ao lado da carroça quebrada com ele e a velha égua deles, Blanchy.",al={"família furlbrow","irmão de furlbrow"}}},fx={d2bcffbc={q="De que lado está o Fazendeiro Taturana?",a="O Fazendeiro Taturana é um camponês comum do Cerro Oeste, leal ao Reino de Ventobravo e à Aliança. Ele não tem nenhum amor pela The Defias Brotherhood, que tomou suas terras e o expulsou. Embora amargurado pela falta de proteção real, ele ainda recorre a outros viajantes da Aliança e à The People's Militia em busca de ajuda.",al={"facção do fazendeiro taturana","quem taturana apoia","taturana é da aliança"}},["81475819"]={q="O que o Fazendeiro Taturana deseja?",a="O Fazendeiro Taturana não quer nada além de consertar sua carroça quebrada e escapar do Cerro Oeste com sua esposa, Verna, e seu velho cavalo, Blanchy. Com sua plantação de abóboras invadida por bandidos da Defias, sua prioridade é reunir suprimentos, recuperar sua herança de família perdida e deixar a fronteira sem lei para trás.",al={"o que taturana precisa","objetivo do fazendeiro taturana","intenções de taturana"}}},fp="15,260,24.743.0,24.332.1,23.227.0,44.214.0,39.239.0,54.152.0"}
P.entries["npc:farmer-saldean"] = {n="Fazendeiro Saldanha",s="O Fazendeiro Saldanha é um colono humano resiliente que reside na Fazenda dos Saldanha, no centro de Cerro Oeste, ao lado de sua esposa, Salma. Ao contrário de muitos fazendeiros vizinhos que fugiram ou desistiram, Saldanha cuida obstinadamente de seus campos conturbados diante de golens de colheita rebeldes e do banditismo crescente.",h="O Fazendeiro Saldanha é um colono humano resiliente que reside na Fazenda dos Saldanha, no centro de Cerro...",kw={"racao de galinha","fazendeiro saldanha","harvest watcher","saldean","fazenda dos saldanha","salma","the killing fields","cerro oeste"},ang={["faction:Alliance"]="Saldanha exemplifica a determinação obstinada dos legalistas restantes de Cerro Oeste, apegando-se ao solo do Reino mesmo quando os soldados da coroa não são vistos em parte alguma.",["profession:Cooking"]="Fazendeiros como Saldanha são a espinha dorsal em ruínas do suprimento de comida de Ventobravo; proteger sua colheita mantém o pão básico nas mesas de todo o reino."},sec={{t="Segurando o Arado",b="O Fazendeiro Saldanha se lembra de dias melhores em Cerro Oeste. Aqueles anos prósperos viraram poeira. Cercado por campos cobertos de mato, ceifadores mecânicos descontrolados e bandidos predatórios, Saldanha se recusa a entregar suas terras. Enquanto outros colonos abandonaram seus acres ou se voltaram para o roubo, ele e sua esposa Salma continuam determinados a colher o pouco trigo que conseguem. Levado a um desespero prático, ele recruta aventureiros errantes para destruir os Harvest Watchers rebeldes que tomaram conta de seus campos e dos de seus vizinhos, para que possa limpar seu solo para o plantio."},{t="A Foice de Cerro Oeste",b="A defesa obstinada de Saldanha de sua propriedade faz dele um dos poucos pontos de sustentação sobreviventes da vida civil entre o Morro da Sentinela e a ponte norte. Apesar de suas duras circunstâncias, ele mantém laços com The People's Militia, encaminhando viajantes aptos a Gryan Stoutmantle assim que seus próprios problemas imediatos são resolvidos. Saldanha sabe muito bem que eliminar os ceifadores de colheita selvagens só garantirá um alívio temporário para sua fazenda, a menos que a anarquia mais ampla que sufoca o campo seja contida."}},faq={{q="Quem é o Fazendeiro Saldanha?",a="Saldanha é um experiente fazendeiro humano que reside na Fazenda dos Saldanha em Cerro Oeste com sua esposa, Salma. Ele é um dos poucos colonos locais que se recusam obstinadamente a abandonar sua terra, apesar da fome, dos golens de colheita rebeldes e da espiral de banditismo da região.",al={"saldean","quem e saldean","npc saldean"}},{q="Por que a fazenda do Fazendeiro Saldanha está com problemas?",a="Os golens de colheita automatizados de Cerro Oeste apresentaram defeito e ficaram descontrolados, rondando as plantações e atacando qualquer um à vista. Saldanha precisa de aventureiros para destruir os vigias mecânicos em seus campos e nos vizinhos, a fim de poder recuperar suas terras.",al={"por que os golens de colheita estao atacando","problema na fazenda dos saldanha"}},{q="Onde o Fazendeiro Saldanha pode ser encontrado?",a="Ele fica do lado de fora de sua casa na Fazenda dos Saldanha, situada bem ao lado da estrada principal no centro de Cerro Oeste, logo ao norte do Morro da Sentinela.",al={"localizacao de saldean","onde fica saldean","localizacao da fazenda dos saldanha"}},{q="Saldanha apoia The People's Militia?",a="Sim. Embora Saldanha se concentre inteiramente na defesa de suas plantações e de seu lar, ele orienta aventureiros capazes pela estrada até Gryan Stoutmantle, no Morro da Sentinela, para ajudar The People's Militia a defender a região.",al={"saldean gryan stoutmantle","saldean milicia"}},{q="Quais itens exclusivos Saldanha vende?",a="Saldanha vende pão comum e é o principal fornecedor de Ração Especial de Galinha, um grão curioso procurado por viajantes que esperam fazer amizade com as aves locais que vagam por Cerro Oeste.",al={"vendedor saldean","vendedor de racao especial de galinha"}}},fx={b644bbfd={q="O que o Fazendeiro Saldanha deseja?",a="Saldanha não quer nada além de proteger sua propriedade, colher suas plantações e conseguir tirar o sustento junto com sua esposa, Salma. Com o Cerro Oeste tomado pela falta de lei e negligenciado por Ventobravo, ele conta com aventureiros viajantes para eliminar os ceifeiros mecânicos desonestos que vagam por seus campos e para ajudar a The People's Militia local a restaurar a segurança na região.",al={"o que saldanha quer","objetivo de saldanha","o que o fazendeiro saldanha deseja"}},["4625baa0"]={q="Com quem o Fazendeiro Saldanha tem laços?",a="O Fazendeiro Saldanha administra sua propriedade junto com sua esposa, Salma Saldanha, que cuida de seu lar e da cozinha. Ele também trabalha em cooperação com Gryan Stoutmantle e a The People's Militia no Morro da Sentinela, direcionando campeões aptos para ajudar na luta contra os fora da lei que ameaçam o celeiro do reino.",al={"família do fazendeiro saldanha","com quem saldanha é casado","relação de salma saldanha"}},["340c71f6"]={q="Por que o Fazendeiro Saldanha está aqui?",a="Saldanha se recusa a ser expulso de suas terras. Os ladrões afugentaram quase todos os outros fazendeiros de Cerro Oeste, mas ele permanece na Fazenda dos Saldanha com sua esposa, Salma, para cultivar seu solo e manter seu lar, apesar dos perigos iminentes.",al={"por que saldanha está em cerro oeste","por que saldanha fica","origem do fazendeiro saldanha"}}},fp="14,278,16.570.0,22.511.0,22.249.0,40.250.0,34.137.0,42.207.0,36.175.0"}
P.entries["npc:farthing"] = {n="Farthing",s="O Bispo Palhares é um clérigo humano que reside na Catedral da Luz, na cidade de Ventobravo. Conhecido como um bondoso e sábio servo da Luz Sagrada, ele orienta os paroquianos e direciona ajuda aos assentamentos sitiados por todo o reino.",h="O Bispo Palhares é um clérigo humano que reside na Catedral da Luz, na cidade de Ventobravo.",kw={"benedictus","bispo palhares","catedral da luz","farthing","morbent fel","seeking wisdom","ventobravo"},ang={["class:Priest"]="Para os sacerdotes que visitam a Catedral da Luz, Farthing representa a hierarquia estabelecida e a sabedoria erudita do clero humano em Ventobravo.",["faction:Alliance"]="Aventureiros que lutam contra a corrupção rastejante nos territórios do sul da Aliança, como a Floresta do Crepúsculo, recorrem a Farthing e aos seus companheiros do clero em busca de percepção divina e determinação espiritual."},sec={{t="Um Bispo em Ventobravo",b="Dentro dos serenos salões de mármore da Catedral da Luz, o Bispo Palhares se destaca como uma das figuras proeminentes que atendem às necessidades espirituais de Ventobravo. Ao lado do Arcebispo Benedictus e do clero reunido, ele oferece conselhos a viajantes, auxilia aqueles que buscam as artes sagradas e atende às obrigações cívicas e pastorais da Igreja da Luz Sagrada."},{t="Ajuda às Plagued Lands",b="Apesar de permanecer situado na capital, Farthing direciona viajantes dedicados para os recantos mais sombrios do reino que necessitam desesperadamente de ajuda sagrada. Quando chegam relatos preocupantes sobre o necromante Morbent Fel e a praga de mortos-vivos rastejante que toma conta da Floresta do Crepúsculo, Farthing atua como conselheiro na busca de métodos para superar feitiçarias sombrias e purificar a fronteira flagelada."}},faq={{q="Onde o Bispo Palhares pode ser encontrado?",a="O Bispo Palhares reside dentro da Catedral da Luz, localizada no centro da Praça da Catedral, em Ventobravo.",al={"localização de farthing","onde fica farthing","mapa de farthing"}},{q="Qual é o papel de Farthing na Catedral?",a="Ele serve como um bispo ordenado na Igreja da Luz Sagrada, oferecendo orientação aos fiéis visitantes, sacerdotes em treinamento e aventureiros em busca de sabedoria sagrada em favor de povoados distantes.",al={"o que farthing faz","quem é farthing"}},{q="Como Farthing está envolvido com a Floresta do Crepúsculo?",a="Farthing é procurado por aventureiros que enfrentam a ameaça dos mortos-vivos na Floresta do Crepúsculo, aconselhando sobre as artes sombrias que sustentam o necromante Morbent Fel e encaminhando almas para a purificação.",al={"farthing floresta do crepúsculo","farthing morbent fel"}},{q="Farthing tem parentesco com outros cidadãos que têm o mesmo nome?",a="Vários outros indivíduos pelas terras humanas compartilham o sobrenome Farthing, incluindo Eurico e Ivete Palhares, embora ele não fale ativamente de nenhum laço familiar direto.",al={"parente de eurico palhares","família farthing"}}},fx={["1783acb6"]={q="Por que o Bispo Palhares está na Catedral da Luz?",a="Palhares está posicionado na Catedral da Luz de Ventobravo para cumprir seus deveres clericais como bispo, aconselhando visitantes, apoiando o sacerdócio e ajudando a direcionar os assuntos da igreja em nome do alto clero.",al={"por que palhares está aqui","por que palhares está em ventobravo","propósito de palhares na catedral"}},e622858b={q="Quem é o Bispo Palhares?",a="O Bispo Palhares é um sacerdote humano da Igreja da Luz Sagrada que serve dentro da grandiosa Catedral da Luz de Ventobravo. Bondoso e sábio, ele cuida dos assuntos da catedral e oferece orientação aos fiéis.",al={"quem é palhares","bispo palhares","história de palhares"}},["6481fc58"]={q="De que lado o Bispo Palhares está?",a="Palhares permanece firmemente ao lado da Grande Aliança e da Igreja da Luz Sagrada sob o Arcebispo Benedictus. Ele representa o sacerdócio dentro do santuário sagrado de Ventobravo, orientando requerentes e cuidando de assuntos da fé.",al={"lealdade de palhares","a quem palhares serve","palhares é da aliança"}},e4f9a584={q="O que o Bispo Palhares quer?",a="Palhares quer ajudar viajantes e defender as virtudes da Luz. Ele demonstra preocupação especial por terras ameaçadas pelas trevas, como orientar aventureiros sobre como ajudar o povo aflito da Floresta do Crepúsculo contra a necromancia sombria.",al={"motivo de palhares","o que palhares quer","objetivo de palhares"}}},fp="8,236,21.374.0,24.390.0,35.119.0,46.199.0,39.187.0,60.172.0"}
P.entries["npc:feegly-the-exiled"] = {n="Feegly, o Exilado",s="Feegly, o Exilado é um anão proscrito encontrado à espreita perto da escavação dos anões em Bael Modan, no sul dos Sertões. Outrora elogiado como um dos melhores escavadores da expedição, sua obsessão por uma relíquia desenterrada levou o General Twinbraid a expulsá-lo.",h="Feegly, o Exilado é um anão proscrito encontrado à espreita perto da escavação dos anões em Bael Modan, no...",kw={"bael modan","sertões","escavador","escavação","exilado","feegly","lágrima das luas","trogg"},ang={["faction:Horde"]="O rancor amargo de Feegly contra os escavadores de Bael Modan faz dele um aliado inesperado para os andarilhos da Horda que buscam sabotar a expedição dos anões nos Sertões.",["race:Dwarf"]="Para os anões, Feegly é um aviso trágico e aterrorizante: um escavador talentoso cuja obsessão por uma relíquia desenterrada lhe custou seu lugar entre os seus semelhantes."},sec={{t="A Ruína de um Escavador",b="Antes de seu exílio, Feegly era considerado um dos principais escavadores de Bael Modan. A Lágrima das Luas foi a primeira grande descoberta feita na escavação, e Feegly reivindicou seu poder como sendo seu. O General Twinbraid chamou a gema de amaldiçoada, trancou-a na Bastilha Bael'Dun e expulsou Feegly. Ele agora rumina sozinho, desesperado para recuperar a própria gema que o condena: quando ele finalmente a segura de novo, a Lágrima se estilhaça e ele se transforma em um trogg grotesco e corcunda."}},faq={{q="Quem é Feegly, o Exilado?",a="Feegly é um anão, um escavador exilado da escavação de Bael Modan que cobiça uma relíquia conhecida como A Lágrima das Luas.",al={"quem é feegly","história de feegly","feegly, o exilado"}},{q="Por que Feegly foi exilado de Bael Modan?",a="Feegly ficou obcecado com A Lágrima das Luas, a primeira grande descoberta em Bael Modan. O General Twinbraid chamou a gema de amaldiçoada, trancou-a na Bastilha Bael'Dun e expulsou Feegly.",al={"por que foi exilado","o que feegly fez","banimento de feegly"}},{q="Por que Feegly está disposto a falar com aventureiros da Horda?",a="Traído e expulso por seus companheiros anões, Feegly não tem lealdade alguma à expedição da Aliança. Ele está desesperado o suficiente para buscar a ajuda de viajantes da Horda para recuperar a relíquia que tanto cobiça.",al={"por que feegly é amigável com a horda","feegly amigável com a horda"}},{q="O que é A Lágrima das Luas?",a="A Lágrima das Luas é uma gema que os escavadores descobriram em Bael Modan, sua primeira grande descoberta no local. Feegly afirma que ela lhe concedeu poder, mas o General Twinbraid a considerou amaldiçoada e a trancou na Bastilha Bael'Dun.",al={"lágrima das luas","gema de feegly","artefato de feegly"}}},fx={ed9ce58e={q="O que Feegly the Exiled quer?",a="Feegly busca a The Tear of the Moons, uma relíquia que ele cobiça por seu estranho poder. Ele recruta viajantes dispostos a recuperá-la da Bastilha Bael'Dun para que ele possa possuí-la mais uma vez.",al={"o que feegly quer","motivação de feegly","por que feegly precisa da lágrima"}},["7eaaafaa"]={q="Por que Feegly the Exiled está nos Sertões?",a="Feegly permanece nas colinas fora de Bael Modan porque o General Twinbraid o expulsou e trancou a The Tear of the Moons. Desesperado para recuperar a gema, ele permanece perto de sua antiga escavação.",al={"por que feegly está aqui","onde feegly fica","por que feegly está fora de bael modan"}},["0b854105"]={q="A quem Feegly the Exiled está ligado?",a="Feegly está ligado à expedição anã de Bael Modan, onde ele foi anteriormente um de seus principais escavadores antes de ser banido. Agora afastado de seu povo, ele conta com viajantes da Horda que passam pelo local para atender aos seus desejos contra a escavação.",al={"ligações de feegly","com quem feegly trabalha","conexões de feegly"}},["21513985"]={q="Quem é Feegly, o Exilado?",a="Feegly é um escavador anão exilado da escavação de Bael Modan nos Sertões Meridionais. Ele permanece do lado de fora da escavação, obcecado em recuperar uma relíquia conhecida como The Tear of the Moons.",al={"quem é feegly","identidade de feegly","história de feegly"}}},fp="17,252,15.460.1,25.113.0,38.184.0,51.189.0,30.214.0"}
P.entries["npc:feero-ironhand"] = {n="Firo Maniferro",s="Firo Maniferro é um paladino humano estacionado no Entreposto de Maestra, nos limites ocidentais de Vale Gris. Montando guarda ao longo da fronteira entre Costa Negra e a floresta, ele trabalha em estreita colaboração com Delgren the Purifier para combater o sombrio Cult of the Dark Strand.",h="Firo Maniferro é um paladino humano estacionado no Entreposto de Maestra, nos limites ocidentais de Vale Gris.",kw={"vale gris","auberdine","culto da praia sombria","delgren the purifier","firo maniferro","entreposto de maestra"},ang={["faction:Alliance"]="Firo oferece um ponto de apoio importante para viajantes da Aliança que descem de Costa Negra em direção à perigosa e disputada natureza selvagem de Vale Gris.",["race:Human"]="Ver um companheiro humano montando guarda nos antigos bosques élficos de Vale Gris é um sinal bem-vindo da cooperação de amplo alcance da Aliança."},sec={{t="Um Bastião no Entreposto de Maestra",b="Localizado ao longo da estrada que segue para o sul de Costa Negra em direção a Vale Gris, o Entreposto de Maestra serve como um ponto de vigilância crucial tanto para viajantes quanto para defensores da Aliança. Firo Maniferro opera a partir deste posto avançado, mantendo linhas de comunicação e comércio com Auberdine enquanto vigia atentamente os bosques ao redor. Juntamente com Delgren the Purifier, Firo concentra seus esforços contra o malévolo Cult of the Dark Strand, garantindo que os cultistas e predadores da floresta não cortem o caminho entre as linhas de suprimento de Darnassus e a linha de frente de Vale Gris."}},faq={{q="Quem é Firo Maniferro?",a="Firo Maniferro é um paladino humano da Aliança estacionado no Entreposto de Maestra, no oeste de Vale Gris. Ele ajuda viajantes que transitam entre Costa Negra e Vale Gris e coordena a logística de volta para Auberdine.",al={"firo maniferro","quem é firo","npc firo"}},{q="Qual é o propósito de Firo no Entreposto de Maestra?",a="Firo ajuda a manter o posto avançado contra ameaças locais, apoiando Delgren the Purifier no combate ao Cult of the Dark Strand enquanto mantém rotas vitais de correios e suprimentos funcionando em direção a Costa Negra.",al={"por que firo está aqui","função de firo","humano do entreposto de maestra"}},{q="O que é o Cult of the Dark Strand?",a="O Cult of the Dark Strand é um conluio sinistro que opera no norte de Vale Gris, lidando com magia sombria e rituais vis. As forças da Aliança no Entreposto de Maestra trabalham ativamente para interromper e desmantelar suas operações.",al={"culto da praia sombria","praia sombria"}},{q="Firo tem ligações com a Aurora Argêntea?",a="Nenhum vínculo com a Aurora Argêntea está registrado para ele. O próprio Firo, sendo um paladino, trabalha em estreita harmonia com Delgren the Purifier, um companheiro paladino humano que combate forças sombrias na floresta.",al={"firo aurora argêntea","firo é da aurora argêntea"}}},fx={["996da789"]={q="De que lado está Firo Maniferro?",a="Firo Maniferro está firmemente com a Aliança. Estacionado no Entreposto de Maestra, um posto avançado crucial dos elfos noturnos ao longo da fronteira oeste de Vale Gris, ele ajuda viajantes e forças locais contra as ameaças que pairam sobre a antiga floresta.",al={"facção de firo maniferro","firo é da aliança","lado de firo maniferro"}},bf9a9ed2={q="O que Firo Maniferro quer?",a="Firo visa apoiar os defensores do Entreposto de Maestra e frustrar o sinistro Culto do Varrido Sombrio. Trabalhando ao lado de Delgren the Purifier, ele busca expurgar a presença corruptora deles do norte de Kalimdor e manter as linhas de suprimentos entre Vale Gris e Costa Negra.",al={"objetivo de firo maniferro","o que firo quer","motivação de firo"}}},fp="14,254,27.562.0,22.199.0,42.193.0,36.216.0,47.176.0"}
P.entries["npc:fel-zerul"] = {n="Vil'zerul",s="Vil'zerul é um bruxo orc posicionado em Pedregal, nas profundezas sombrias do Pântano das Mágoas. Agindo sob ordens diretas do Chefe de Guerra Thrall, ele investiga a presença sinistra que espreita dentro do Templo Submerso de Atal'Hakkar.",h="Vil'zerul é um bruxo orc posicionado em Pedregal, nas profundezas sombrias do Pântano das Mágoas.",kw={"atal'hakkar","vil'zerul","pedregal","pântano das mágoas","thrall","bruxo"},ang={["class:Warlock"]="Vil'zerul representa a designação oficial de um bruxo por Thrall, demonstrando que A nova Horda ocasionalmente conta com praticantes das artes das trevas para combater ameaças obscuras e esotéricas.",["faction:Horde"]="Posicionado em Pedregal, Vil'zerul atua como um batedor de alerta prévio, garantindo que qualquer magia sombria que se prolifere no pântano não pegue de surpresa o domínio da Horda na região."},sec={{t="De Olho no Templo Submerso",b="Embora a Horda de Thrall geralmente veja as artes das trevas com desconfiança, o Chefe de Guerra reconhece que compreender poderes sinistros requer aqueles que os estudam. Vil'zerul foi enviado a Pedregal especificamente para desvendar a corrupção que cerca o Poço de Lágrimas e o submerso Templo de Atal'Hakkar. Ao orientar aventureiros a recuperar artefatos e investigar os trolls Atal'ai exilados, o bruxo busca determinar qual mal se agita sob as águas turvas antes que ameace o entreposto ao sul da Horda."}},faq={{q="Quem é Vil'zerul?",a="Vil'zerul é um bruxo orc residente em Pedregal, a fortaleza da Horda no Pântano das Mágoas. Ele atua como um investigador analisando os rituais sombrios que se desenrolam no vizinho Templo de Atal'Hakkar.",al={"vil'zerul","quem é vil'zerul","bruxo de pedregal"}},{q="Por que Thrall enviou um bruxo a Pedregal?",a="O Chefe de Guerra Thrall enviou Vil'zerul porque lidar com maldições antigas e rituais de sangue exige perícia em feitiçarias mais sombrias. O mandato de Vil'zerul é monitorar os acontecimentos perturbadores ao redor do templo submerso e proteger os interesses da Horda no pântano.",al={"thrall vil'zerul","por que vil'zerul está aqui","missão de vil'zerul"}},{q="O que Vil'zerul está investigando?",a="Vil'zerul está investigando os trolls Atal'ai e seus ritos profanos dentro do Templo de Atal'Hakkar, no Poço de Lágrimas. Ele recruta batedores e aventureiros para resgatar artefatos e rastrear sacerdotes exilados que possam ter conhecimentos cruciais.",al={"história das missões de vil'zerul","o que vil'zerul quer","investigação do poço de lágrimas"}}},fp="9,228,25.509.0,17.203.0,41.259.0,32.240.0"}
P.entries["npc:felgur-twocuts"] = {n="Felgur Doiscortes",s="Felgur Doiscortes é um batedor orc rude posicionado no Entreposto do Espírito que Anda em Desolação. Ele coordena os esforços da Horda contra os clãs de centauros da região.",h="Felgur Doiscortes é um batedor orc rude posicionado no Entreposto do Espírito que Anda em Desolação.",kw={"recompensa de centauro","desolação","felgur doiscortes","entreposto do espírito que anda","horda","kolkar","orc"},ang={["faction:Horde"]="Felgur atua como um contato de operações vital no Entreposto do Espírito que Anda, ajudando a Horda a repelir tribos centauras agressivas em Desolação.",["race:Orc"]="Fiel ao pragmatismo orc padrão em terras fronteiriças perigosas, Felgur valoriza força, velocidade e resultados imediatos acima de conversas ociosas."},sec={{t="Um Batedor de Posto Avançado Áspero",b="Vigiando em meio à extensão desolada do Entreposto do Espírito que Anda na região central de Desolação, Felgur Doiscortes tem pouca paciência para amenidades. Como batedor avançado da Horda, ele avalia as ameaças enfrentadas por viajantes e colonos que se aventuram a oeste através das montanhas, particularmente os centauros Kolkar locais."},{t="Guerra contra os Centauros",b="Felgur orienta os campeões da Horda a eliminar os chefes centauros locais e coletar recompensas pelas tribos em guerra que ameaçam dominar a região. Ele é um contato central para qualquer pessoa que queira garantir a posição da Horda em Desolação."}},faq={{q="Quem é Felgur Doiscortes?",a="Felgur Doiscortes é um batedor orc e doador de missões posicionado no Entreposto do Espírito que Anda, o acampamento avançado da Horda em Desolação.",al={"quem é felgur doiscortes","quem é felgur"}},{q="Onde posso encontrar Felgur Doiscortes?",a="Ele está localizado no Entreposto do Espírito que Anda, logo ao norte da estrada central que atravessa Desolação.",al={"localização de felgur doiscortes","onde está felgur","onde está felgur doiscortes"}},{q="Quais tarefas Felgur Doiscortes oferece?",a="Felgur recruta aventureiros da Horda para atacar os centauros Kolkar locais, caçar Khan Dez'hepah e coletar recompensas por centauros hostis.",al={"missões de felgur","o que felgur quer"}},{q="Por que Felgur é tão curto com os visitantes?",a="Desolação é um terreno baldio perigoso e implacável cercado por clãs de centauros hostis. Posicionado em um posto isolado, Felgur não tem tempo para conversas fiadas e prefere focar estritamente na sobrevivência e no dever marcial.",al={"por que felgur é rude","seja breve felgur"}}},fx={f5a09a6e={q="De que lado está Felgur Doiscortes?",a="Felgur é um membro orgulhoso da Horda, estacionado bem longe na fronteira para promover seus interesses e defender seus acampamentos contra ameaças regionais.",al={"facção de felgur doiscortes","felgur é da horda","a quem felgur serve"}},["8c623583"]={q="O que Felgur Doiscortes quer?",a="Felgur busca conter os clãs hostis de centauros que ameaçam a Horda em Desolação. Ele alista campeões capazes para coletar recompensas e enfrentar Khan Dez'hepah.",al={"objetivo de felgur doiscortes","o que felgur está tentando fazer","do que felgur precisa"}},a5d710fc={q="Por que Felgur Doiscortes está estacionado aqui?",a="Felgur está guarnecido no Entreposto do Espírito que Anda para monitorar as tribos de centauros locais e direcionar ações contra ameaças à presença da Horda em Desolação.",al={"por que felgur doiscortes está no entreposto do espírito que anda","propósito de felgur aqui","por que felgur está aqui fora"}}},fp="14,144,21.297.0,18.233.0,22.122.0,32.92.0,36.138.0,36.213.0"}
P.entries["npc:felix-whindlebolt"] = {n="Félix Reclamofuso",s="Félix Reclamofuso é um refugiado gnomo desalojado abrigando-se em Sidermar, no Vale Cristálgida. Em sua pressa para fugir da radiação que inundava Gnomeregan, ele perdeu seus pertences pessoais, e trolls Frostmane hostis os levaram embora.",h="Félix Reclamofuso é um refugiado gnomo desalojado abrigando-se em Sidermar, no Vale Cristálgida.",kw={"sidermar","vale cristálgida","félix reclamofuso","frostmane","gnomeregan","refugiado","acampamento de barbabranca"},ang={["race:Dwarf"]="Os trolls Frostmane locais ficaram mais ousados por todo o Vale Cristálgida, atacando frágeis refugiados gnomos que vagavam perto de Sidermar.",["race:Gnome"]="Félix representa o sofrimento contínuo do seu povo desalojado, forçado a enfrentar o frio impiedoso de Dun Morogh após a catástrofe em Gnomeregan."},sec={{t="Um Viajante Desalojado",b="Após a trágica queda de Gnomeregan, milhares de gnomos se viram vagando pelas extensões congeladas de Dun Morogh em busca de segurança. Félix Reclamofuso fugiu da cidade irradiada com tanta pressa que perdeu todos os seus pertences pessoais e ferramentas. Para piorar a situação, trolls do gelo Frostmane levaram seu baú, sua caixa e seu balde de parafusos para seus acampamentos a sudoeste de Sidermar, deixando-o desamparado, na miséria e dependendo de viajantes solidários para recuperar seus equipamentos roubados."}},faq={{q="Quem é Félix Reclamofuso?",a="Félix Reclamofuso é um refugiado gnomo atualmente abrigado em Sidermar, no Vale Cristálgida. Ele perdeu seus pertences enquanto fugia de Gnomeregan, e os trolls Frostmane locais os pegaram.",al={"quem é félix","história de félix reclamofuso","gnomo no acampamento de barbabranca"}},{q="Para onde Félix estava tentando ir?",a="Félix estava fugindo da radiação que assolou Gnomeregan depois que a tentativa dos gnomos de expulsar os troggs deu terrivelmente errado. Ele acabou indo parar em Sidermar, o entreposto dos anões no Vale Cristálgida, embora considere o lugar pouco adequado para um gnomo.",al={"para onde félix estava indo","destino de félix","por que félix está no vale cristálgida"}},{q="O que aconteceu com os bens dele?",a="Em sua pressa para escapar de Gnomeregan, Félix perdeu seu baú, sua caixa e seu balde de parafusos. Os trolls do gelo Frostmane os levaram para seus acampamentos a sudoeste de Sidermar, deixando-o desamparado e sem suprimentos.",al={"quem roubou as coisas de félix","equipamentos roubados de félix","trolls frostmane félix"}},{q="O que Félix vende para aventureiros?",a="Nada. Félix não é mercador: ele perdeu todos os seus pertences fugindo de Gnomeregan, e tudo o que pode oferecer em Sidermar são seus agradecimentos a quem recuperar seu baú, sua caixa e seu balde de parafusos.",al={"itens de vendedor de félix","o que félix oferece","inventário de félix"}}},fx={b1540142={q="De que lado está Félix Reclamofuso?",a="Félix está alinhado com os Exilados de Gnomeregan e a Grande Aliança. Como muitos gnomos deslocados, ele fugiu das ruínas irradiadas de Gnomeregan e agora se abriga em Sidermar, no Vale Cristálgida, esperando se reunir ao seu povo.",al={"facção de félix","félix é da aliança","para quem félix trabalha"}}},fp="17,232,20.489.0,25.180.0,29.244.0,33.208.0,36.183.0"}
P.entries["npc:fenrus-the-devourer"] = {n="Fenrus, o Devorador",s="Fenrus, o Devorador é um worg enorme que ronda o santuário superior da Bastilha da Presa Negra. Mantido como mascote pessoal e guardião pelo Arquimago Arugal, a fera voraz está inchada de magias não naturais. Qualquer um que ouse invadir o gabinete pessoal do arquimago deve lidar com este horror feroz e com o mestre que vela por ele.",h="Fenrus, o Devorador é um worg enorme que ronda o santuário superior da Bastilha da Presa Negra.",kw={"arugal","fenrus","fenrus, o devorador","bastilha da presa negra","floresta de pinhaprata","worg"},ang={["class:Hunter"]="Não perca tempo tentando encantar Fenrus. A mente da fera foi irrevogavelmente corrompida pelas artes sombrias de Presa Negra e não pode ser dominada pela natureza.",["class:Mage"]="Fenrus serve como uma lembrança sombria da decadência do Arquimago Arugal, que usou artes arcanas para deformar feras selvagens em grotescos guardiões domésticos.",["class:Warlock"]="A capacidade do Arquimago Arugal de invocar emissários do vácuo para socorrer seu cão revela o quão profundamente o antigo mago de Dalaran mergulhou em conjurações sombrias e proibidas."},sec={{t="Uma Fera no Gabinete do Mestre",b="Nas profundezas da Bastilha da Presa Negra, bem em frente aos aposentos pessoais do Arquimago Arugal, espreita o worg monstruoso conhecido como Fenrus, o Devorador. Diferente dos worgens lupinos que rondam as muralhas, Fenrus é um worg autêntico, avolumado a proporções gigantescas. Rondando as estantes, pergaminhos e aparatos arcanos do gabinete privado de Arugal, a fera serve tanto como animal de estimação quanto como uma violenta sentinela de perímetro contra qualquer invasor que busque a cabeça do mago louco."},{t="Poder Corrompido",b="O porte descomunal de Fenrus sugere que ele foi submetido às magias sombrias que saturam a fortaleza desde a queda do Barão Silverlaine. O Arquimago Arugal ou seus worgens libertos claramente deformaram a criatura com experimentos arcanos ou sombrios, transformando um predador nativo em uma força voraz e implacável. Fenrus é tão feroz e vinculado à magia que nenhum caçador consegue encantar ou domar sua mente."},{t="O Olhar Atento de Arugal",b="Perturbar Fenrus é uma sentença de morte imediata para os descuidados. Quando a fera avista um invasor, solta um uivo ensurdecedor que ecoa por toda a fortaleza, atraindo a atenção direta do próprio Arugal. Em vez de deixar seu mascote indefeso, o arquimago projeta sua vontade sombria na câmara, invocando emissários do vácuo para ajudar Fenrus a subjugar e devorar os invasores."}},faq={{q="Que tipo de criatura é Fenrus?",a="Fenrus é um worg excepcionalmente grande, um predador lupino natural e nativo de Lordaeron, e não um worgen bípede. Seu porte anormal e sua ferocidade voraz são resultados diretos da exposição prolongada à magia sombria praticada dentro da Bastilha da Presa Negra.",al={"fenrus é um worgen","tipo de criatura fenrus","lobo fenrus"}},{q="Onde Fenrus pode ser encontrado?",a="Fenrus ronda as câmaras de estudo no alto da Bastilha da Presa Negra, na Floresta de Pinhaprata. Seu covil fica situado diretamente no caminho de acesso ao reduto interior do Arquimago Arugal.",al={"onde fica fenrus","localização de fenrus","sala do fenrus"}},{q="Caçadores podem domar Fenrus como mascote?",a="Não. Apesar de ser classificado como uma fera comum, Fenrus não pode ser domado. Sua mente está completamente despedaçada, selvagem e atrelada à vontade sombria do Arquimago Arugal.",al={"posso domar fenrus","fenrus pode ser domado","domar fenrus"}},{q="Por que Arugal invoca demônios quando Fenrus é atacado?",a="Arugal considera Fenrus seu animal de estimação mais precioso e a última linha de defesa antes de seu santuário. Quando Fenrus ruge ao entrar em combate, Arugal intervém diretamente, conjurando emissários do vácuo na câmara para subjugar quem quer que ameace sua fera.",al={"arugal emissários do vácuo","por que arugal ajuda fenrus","ajudantes emissários do vácuo fenrus"}},{q="Por que Fenrus é muito maior do que os worgs normais?",a="Acredita-se que o tamanho colossal de Fenrus seja consequência dos experimentos de magia sombria do Arquimago Arugal ou dos resíduos mágicos da infestação de worgens que assolou a fortaleza.",al={"por que fenrus é gigante","história tamanho fenrus","worg gigante"}},{q="O que acontece na masmorra quando Fenrus entra em combate?",a="Quando Fenrus entra em combate, ele solta um rugido estrondoso tão alto que pode ser ouvido em qualquer lugar da Bastilha da Presa Negra, alertando a todos sobre a batalha que ocorre do lado de fora da porta de Arugal.",al={"rugido de fenrus","uivo de fenrus na masmorra","rugido alto presa negra"}}},fx={b2b015f0={q="De que lado está Fenrus?",a="Fenrus é ferozmente leal ao Arquimago Arugal. Como a fera pessoal e guardião do feiticeiro, ele serve a qualquer vontade distorcida que guie o mestre da Bastilha da Presa Negra, atacando qualquer intruso que invadir o santuário superior sem hesitação.",al={"facção de fenrus","a quem fenrus serve","lealdades de fenrus"}},["01e73d00"]={q="Por que Fenrus está na Bastilha da Presa Negra?",a="Fenrus ronda o escritório principal diretamente adjacente aos aposentos pessoais de Arugal. Ele atua tanto como um animal de estimação quanto como um cão de guarda monstruoso, colocado lá para despedaçar qualquer um que tente violar o santuário interno do arquimago.",al={"por que fenrus está aqui","propósito da localização de fenrus","por que fenrus guarda o escritório"}}},fp="19,322,29.436.0,15.369.0,21.397.1,32.260.0,26.167.0,33.157.0,54.234.0,47.174.0,55.191.0"}
P.entries["npc:field-marshal-snowfall"] = {n="Marechal-de-campo Nevado",s="O Marechal-de-campo Nevado é um oficial militar anão posicionado no Military Ward de Altaforja para coordenar o esforço de guerra da Aliança contra a crescente ameaça dos silitídeos. Diante de um mal ancestral que desperta nas areias do sul de Silithus, ele supervisiona a enorme mobilização logística necessária para equipar os exércitos aliados. Nevado monitora as doações de matérias-primas e recompensa aqueles que ajudam na preparação do reino para a guerra.",h="O Marechal-de-campo Nevado é um oficial militar anão posicionado no Military Ward de Altaforja para coordenar...",kw={"ahn'qiraj","marechal-de-campo nevado","altaforja","military ward","sinetes","silithus","nevado","esforço de guerra"},ang={["faction:Alliance"]="Nevado representa a vontade industrial e militar unificada da Aliança, conclamando cada raça, de Ventobravo a Darnassus, a esvaziar seus armazéns e se preparar para a batalha à frente.",["race:Dwarf"]="Posicionado no distrito marcial da Grande Forja, Nevado fala com orgulho sobre proteger as criações dos Titãs contra uma depravação antiga e arraigada."},sec={{t="Intendente do Esforço de Ahn'Qiraj",b="Montando guarda no Military Ward de Altaforja, o Marechal-de-campo Nevado atua como o coordenador central da mobilização da Aliança contra Ahn'Qiraj. Ele não vê o conflito iminente como uma mera escaramuça de fronteira, mas como um combate crucial contra um inimigo ancestral hostil a todas as criações dos Titãs. Nevado supervisiona reservas colossais de suprimentos — milhões de bandagens, toneladas de barras de metal, couros, ervas e rações coletadas por aventureiros —, garantindo que as forças da Aliança estejam armadas, protegidas e alimentadas quando a marcha rumo ao sul de Silithus começar."},{t="O Caminho para Silithus",b="Mobilizar uma facção inteira exige coordenação entre ferreiros, coletores, cozinheiros e soldados por todos os territórios da Aliança. Nevado monitora cada etapa dessa imensa operação, aceitando sinetes de comenda e oferecendo requisições de suprimentos a voluntários. Quando os suprimentos de guerra necessários são totalmente acumulados em ambas as facções, os estoques são embalados e transportados para o sul rumo ao Forte Cenariano, preparando o grande ataque contra os enxames insetoides e o Deus Antigo à espreita por trás da Muralha do Escaravelho."}},faq={{q="Quem é o Marechal-de-campo Nevado?",a="O Marechal-de-campo Nevado é um comandante anão de alta patente estabelecido no Military Ward de Altaforja. Ele é encarregado de supervisionar e contabilizar a ampla coleta de suprimentos da Aliança para a guerra iminente contra os qiraji em Silithus.",al={"papel de nevado","quem é nevado","história marechal-de-campo nevado"}},{q="Por que a Aliança está coletando tantos suprimentos?",a="Um poder ancestral ameaça Kalimdor de além dos Portões de Ahn'Qiraj. Para erguer uma campanha bem-sucedida pelos desertos impiedosos de Silithus, a Aliança precisa acumular reservas enormes de armaduras, barras de metal, bandagens médicas, comida e ervas antes que seus exércitos possam marchar.",al={"por que doar tecido","objetivo esforço de guerra","por que suprimentos de guerra"}},{q="Para onde vão os materiais coletados depois de prontos?",a="Assim que a Aliança e a Horda cumprem suas cotas totais de coleta, caravanas e navios de suprimentos transportam os vastos estoques para o Forte Cenariano, em Silithus, onde as forças combinadas estabelecem suas bases operacionais avançadas.",al={"para onde vão os suprimentos","o que acontece com os suprimentos"}},{q="Para que servem os Sinetes de Suprimentos de Guerra?",a="Os sinetes são concedidos a colaboradores que doam armas e materiais solicitados para o esforço de guerra. O Marechal-de-campo Nevado aceita esses sinetes em lotes, recompensando cidadãos dedicados da Aliança com caixotes de suprimentos e equipamentos por seus serviços.",al={"entrega de sinetes","para que servem os sinetes"}}},fx={ec7ab6f1={q="De que lado está o Marechal-de-campo Nevado?",a="O Marechal-de-campo Nevado é um comandante leal da Aliança. Estacionado na Military Ward de Altaforja, ele supervisiona a logística de toda a facção e a coleta de recursos necessária para montar uma ofensiva conjunta em Kalimdor. Embora esta campanha exija uma cooperação paralela incômoda ao lado da Horda para acumular suprimentos suficientes, as lealdades de Nevado estão firmemente com os reinos da Grande Aliança.",al={"marechal-de-campo nevado aliança ou horda","facção de nevado","a quem nevado serve"}},e1b72348={q="O que o Marechal-de-campo Nevado quer?",a="Nevado quer estocar quantidades impressionantes de matérias-primas, bandagens, barras de metal, ervas e suprimentos alimentares de todas as terras da Aliança. Ele visa garantir que, quando os portões de Ahn'Qiraj forem rompidos, o exército permanente que chegar ao deserto inóspito de Silithus tenha todas as armas, poções e rações necessárias para resistir às legiões de C'Thun sem entrar em colapso por exaustão.",al={"objetivo do marechal-de-campo nevado","o que nevado está pedindo","objetivo de nevado"}},a597c3d5={q="Por que o Marechal-de-campo Nevado está em Altaforja?",a="Nevado estabeleceu o comando na Military Ward de Altaforja porque a cidade montanhosa anã serve como um centro central da indústria e comércio da Aliança. A partir daqui, ele pode rastrear manifestos de transporte, coordenar o recebimento de materiais reunidos por cidadãos-soldados e montar a montanha de provisões antes que sejam despachadas pelo mar para os campos de preparação em Silithus.",al={"por que nevado está em altaforja","military ward de nevado","por que o marechal-de-campo nevado está aqui"}}},fp="22,407,37.558.0,20.505.0,30.238.0,48.269.0,49.224.0,47.239.0"}
P.entries["npc:field-marshal-stonebridge"] = {n="Marechal-de-campo Pontepedra",s="A Marechal-de-campo Pontepedra é uma oficial de alta patente da Aliança posicionada perto da entrada de Ventobravo. Postada ao lado dos Portões de Ventobravo no Vale dos Heróis, ela supervisiona as defesas da cidade junto com o General Marcus Jonas e atua como uma autoridade para grandes triunfos marciais.",h="A Marechal-de-campo Pontepedra é uma oficial de alta patente da Aliança posicionada perto da entrada de...",kw={"marechal-de-campo","portões","o senhor dos rocha negra","marcus jonas","nefarian","pontepedra","ventobravo","vale dos heróis"},ang={["class:Warrior"]="Como uma das comandantes militares supremas posicionadas nos portões da cidade, a Marechal-de-campo Pontepedra impõe respeito aos soldados da linha de frente que lutam para alcançar uma alta posição marcial na Aliança.",["faction:Alliance"]="Permanecendo ombro a ombro com o General Marcus Jonas, Pontepedra representa a vigilância inabalável do exército da Aliança protegendo Ventobravo contra invasões externas."},sec={{t="Um Baluarte nos Portões",b="Posicionada logo na imponente entrada do Vale dos Heróis, a Marechal-de-campo Pontepedra vigia sob o arco leste, perto dos portões principais. Sua alta patente no comando militar da Grande Aliança a coloca entre os mais altos escalões da liderança estratégica de Ventobravo, atuando em estreita coordenação com o General Marcus Jonas. Desse ponto de observação de destaque, ela vigia o fluxo de defensores, viajantes e campeões que entram na capital, pronta para organizar a guarnição caso ameaças rompam o perímetro externo."},{t="Portadora de Troféus",b="Além de seus deveres cerimoniais e defensivos no portão da cidade, a Marechal-de-campo Pontepedra recebe relatórios críticos e espólios de campanhas contra os maiores adversários que ameaçam o reino. Comandantes de alto escalão contam com oficiais como Pontepedra para verificar relatórios de inteligência cruciais e celebrar vitórias monumentais conquistadas em campo, incluindo a derrota de senhores da guerra e monstros que se aninham nos penhascos da Montanha Rocha Negra."}},faq={{q="Onde fica a Marechal-de-campo Pontepedra?",a="Ela fica sob um arco na parte nordeste do Vale dos Heróis em Ventobravo, logo à direita do General Marcus Jonas quando você entra pelos portões da cidade.",al={"localização de pontepedra","onde fica a marechal-de-campo pontepedra","encontrar pontepedra"}},{q="Qual é o papel da Marechal-de-campo Pontepedra em Ventobravo?",a="Ela é uma oficial militar de alta patente da Aliança que auxilia o General Marcus Jonas na defesa do portão principal de Ventobravo e atua como a oficial receptora de importantes relatórios de inteligência marcial e grandes troféus de vitória trazidos pelos campeões da Aliança.",al={"o que pontepedra faz","função de pontepedra","quem é a marechal-de-campo pontepedra"}},{q="Qual é a posição de um Marechal-de-campo na Aliança?",a="Marechal-de-campo é uma das mais altas patentes de oficial na estrutura de comando militar da Grande Aliança, ficando logo abaixo de Marechal de Campo. Oficiais dessa patente supervisionam grandes mobilizações táticas, setores de defesa da cidade e guarnições estratégicas.",al={"patente marechal-de-campo aliança","qual a patente de pontepedra"}},{q="Quais missões importantes envolvem a Marechal-de-campo Pontepedra?",a="Ela é a oficial que recebe o relatório e o troféu de 'O senhor dos Rocha Negra', confirmando a queda de Nefarian quando os aventureiros da Aliança trazem a cabeça do dragão de volta aos portões de Ventobravo.",al={"missões de pontepedra","finalizador da missão o senhor dos rocha negra"}}},fx={["63c0e4ac"]={q="Quem é a Marechal-de-campo Pontepedra?",a="A Marechal-de-campo Pontepedra é uma comandante humana de alto escalão do exército da Aliança, estacionada nos portões de Ventobravo. Ao lado da liderança da cidade no Vale dos Heróis, ela supervisiona defesas críticas e serve como uma das autoridades militares seniores do reino.",al={"quem é pontepedra","identidade da marechal-de-campo pontepedra","conhecimento sobre pontepedra"}},["05caa28c"]={q="De que lado está a Marechal-de-campo Pontepedra?",a="A Marechal-de-campo Pontepedra é totalmente leal ao Reino de Ventobravo e à Grande Aliança. Ela serve diretamente sob os comandantes supremos do reino, ajudando a proteger a capital de ameaças externas.",al={"facção de pontepedra","alegância de pontepedra","a quem pontepedra serve"}},d0356b7c={q="Por que a Marechal-de-campo Pontepedra está aqui?",a="Ela está postada no Vale dos Heróis para montar guarda na entrada principal da capital, auxiliando o General Marcus Jonas com a coordenação das forças de Ventobravo e recebendo relatórios militares de alta prioridade e troféus trazidos por campeões da Aliança.",al={"por que pontepedra está em ventobravo","por que pontepedra está nos portões","pontepedra vale dos heróis"}},a46f624c={q="O que a Marechal-de-campo Pontepedra quer?",a="Pontepedra busca a defesa completa de Ventobravo e a derrota dos maiores adversários do reino, verificando ansiosamente a prova de grandes vitórias trazidas por aventureiros para garantir a segurança do reino.",al={"objetivos de pontepedra","o que a marechal-de-campo pontepedra quer","motivações de pontepedra"}},af024441={q="A quem a Marechal-de-campo Pontepedra está ligada?",a="Ela trabalha em estreita colaboração com o General Marcus Jonas, o comandante da defesa da cidade de Ventobravo, e faz parte do aparato militar mais amplo do Grão-lorde Bolvar Fordragon, que protege o reino do jovem Rei Anduin Wrynn.",al={"conexões de pontepedra","com quem pontepedra trabalha","pontepedra marcus jonas"}}},fp="25,285,22.552.0,18.432.0,43.180.0,54.251.0,45.239.0,52.195.1"}
P.entries["npc:first-mate-fitzsimmons"] = {n="Primeiro Oficial Simonez",s="O Primeiro Oficial Simonez é um marinheiro maltrapilho e fedorento que passa os dias bebendo do lado de fora da Taberna Aguafunda, no Porto de Menethil. Outrora o primeiro oficial a bordo do Wave Mistress da Terceira Frota de Kul Tiraz, ele é o único sobrevivente vivo conhecido da destruição da frota durante a Segunda Guerra. Assombrado pela tragédia, ele procura aventureiros dispostos a enfrentar os espíritos inquietos de seus companheiros afogados.",h="O Primeiro Oficial Simonez é um marinheiro maltrapilho e fedorento que passa os dias bebendo do lado de fora...",kw={"taberna aguafunda","olho de paleth","primeiro oficial simonez","simonez","kul tiraz","frota perdida","porto de menethil","terceira frota","wave mistress"},ang={["faction:Alliance"]="Simonez representa um capítulo trágico na história naval da Aliança, lembrando aos heróis as perdas catastróficas sofridas contra a armada de dragões escravizados da Horda.",["race:Human"]="Como um veterano de Kul Tiraz, Simonez compartilha profundos laços culturais com o reino humano de navegantes que tanto sacrificou para defender Lordaeron durante a Segunda Guerra."},sec={{t="Um Marinheiro Arruinado",b="Descansando do lado de fora da Taberna Aguafunda em meio ao ar salgado e úmido do Porto de Menethil, o Primeiro Oficial Simonez é um homem fácil de ignorar — ou de evitar completamente, devido ao seu fedor de falta de banho. Para a maioria dos frequentadores, ele é apenas mais um velho lobo do mar arruinado afogando suas memórias na bebida. No entanto, aqueles dispostos a sentar e ouvir escutarão contos angustiantes de uma frota orgulhosa derrubada por fogo e garras."},{t="A Queda da Terceira Frota",b="Durante a Segunda Guerra, Simonez serviu como primeiro oficial a bordo do Wave Mistress, parte da Terceira Frota de Kul Tiraz enviada para combater a Horda. Na costa de Pantanal, a frota foi emboscada e incinerada por dragões vermelhos escravizados, pilotados por orcs Dragonmaw. Os navios foram despedaçados e afundados, restando a Simonez ser o único homem a se arrastar com vida até a praia."},{t="A Maldição Persistente",b="Sobreviver ao fogo dos dragões não trouxe paz a Simonez. Os restos dos navios, agora lembrados como a Frota Perdida, são assombrados por seus antigos companheiros de tripulação, que se ergueram como mortos-vivos amaldiçoados, incapazes de descansar em suas tumbas aquáticas. Movido pela culpa e pelo terror, Simonez recruta viajantes para abater os marinheiros mortos-vivos e recuperar relíquias antigas que possam finalmente remover o mal que prende suas almas."}},faq={{q="Quem é o Primeiro Oficial Simonez?",a="Ele é um velho marinheiro kultireno e ex-primeiro oficial do Wave Mistress. Ele sobreviveu ao naufrágio catastrófico da Terceira Frota de Kul Tiraz durante a Segunda Guerra e agora passa os dias bebendo do lado de fora da Taberna Aguafunda, no Porto de Menethil.",al={"história de simonez","quem é simonez","primeiro oficial simonez"}},{q="O que aconteceu com o navio dele?",a="O Wave Mistress e o restante da Terceira Frota foram emboscados por dragões vermelhos escravizados montados pelo clã Dragonmaw durante a Segunda Guerra. As embarcações foram queimadas e destroçadas contra os recifes na costa de Pantanal.",al={"o que aconteceu com o wave mistress","destruição da terceira frota","por que o navio dele afundou"}},{q="Onde fica a Frota Perdida?",a="Os cascos despedaçados da frota jazem submersos ao longo da costa rochosa ao norte do Porto de Menethil, em Pantanal, agora guardados por murlocs e pelos espíritos inquietos dos marinheiros afogados.",al={"localização da frota perdida","onde estão os navios naufragados","localização do navio de simonez"}},{q="Por que ele quer que os aventureiros enfrentem sua antiga tripulação?",a="Os marinheiros afogados da Terceira Frota se ergueram como mortos-vivos amaldiçoados e atormentados, em vez de fazerem a passagem. Simonez busca viajantes corajosos para conceder-lhes descanso e recuperar os artefatos que mantêm suas almas acorrentadas.",al={"história da missão da tripulação amaldiçoada","por que matar a tripulação dele"}},{q="O que é o Olho de Paleth?",a="É um artefato antigo e poderoso transportado a bordo da Terceira Frota. Seu poder sombrio está ligado à maldição que aflige os marinheiros afundados, tornando sua recuperação crucial para conceder paz à frota afogada.",al={"olho de paleth","relíquia de paleth"}},{q="Por que Simonez cheira tão mal?",a="Tendo perdido tudo quando sua frota afundou, Simonez vive há anos em negligência alcoólica do lado de fora da Taberna Aguafunda, vestindo trapos encharcados de água do mar e raramente se lavando.",al={"por que simonez cheira mal","fedor de simonez"}}},fx={c1574e2a={q="De que lado está o Primeiro Oficial Simonez?",a="Simonez se alinha com a Aliança através de suas lealdades passadas a Kul Tiraz e The Third Fleet. Hoje, no entanto, ele não serve a nenhuma nação ou senhor. Ele é simplesmente um marinheiro arruinado que passa seus dias bebendo fora da Taberna Aguafunda em Porto de Menethil, contando com aventureiros da Aliança que passam pelo local para limpar os restos amaldiçoados de seu passado.",al={"facção de simonez","a quem simonez serve","simonez é da aliança"}},["468babc7"]={q="Por que o Primeiro Oficial Simonez está no Porto de Menethil?",a="O Primeiro Oficial Simonez acabou no Porto de Menethil por ser o único sobrevivente da The Third Fleet de Kul Tiraz, que foi destruída por cavaleiros de dragão orcs ao longo da costa do Pantanal durante a Segunda Guerra. Assombrado pelo destino terrível de seus companheiros, ele se retirou para os degraus fora da Taberna Aguafunda para afogar seu trauma em bebida.",al={"por que simonez está aqui","simonez porto de menethil por que","por que simonez está fora da taberna"}},["786aa53e"]={q="A quem o Primeiro Oficial Simonez está ligado?",a="Simonez era o primeiro oficial a bordo do Wave Mistress, uma embarcação de Kul Tiraz que serviu na The Third Fleet. Ele permanece intimamente ligado ao seu antigo capitão e companheiros de navio, que agora assombram os destroços na costa como mortos-vivos amaldiçoados, presos por relíquias sombrias como o The Eye of Paleth.",al={"conexões de simonez","navio de simonez","tripulação de simonez"}}},fp="22,397,15.367.0,27.366.0,19.390.1,30.232.0,26.212.0,32.182.0,51.206.0,26.197.0,34.173.0"}
P.entries["npc:fizzle-brassbolts"] = {n="Fizzle Brassbolts",s="Fizzle Brassbolts é um proeminente engenheiro gnomo instalado nas salinas áridas do Circuito da Ilusão em Mil Agulhas. Ao lado de seu rival, o goblin Pozzik, Fizzle cofundou o circuito para colocar a engenharia de precisão dos gnomos contra a engenhosidade imprudente dos goblins em corridas de carros-foguete em alta velocidade. Ele busca constantemente peças, combustível e reagentes estranhos do deserto para manter sua equipe de corrida funcionando.",h="Fizzle Brassbolts é um proeminente engenheiro gnomo instalado nas salinas áridas do Circuito da Ilusão em Mil...",kw={"brassbolts","fizzle","circuito da ilusão","pozzik","carro-foguete","chapada cintilante","mil agulhas"},ang={["faction:Alliance"]="Embora opere em uma zona neutra de velocidade, Fizzle oferece um rosto amigável e serviços mecânicos para viajantes da Aliança que passam para o sul em direção a Tanaris.",["profession:Engineering"]="Colegas engenheiros apreciarão a dedicação de Fizzle em otimizar a propulsão de foguetes e elaborar projetos automotivos de ponta sob as duras condições do deserto.",["race:Gnome"]="Fizzle carrega a honra de toda Gnomeregan para o deserto, determinado a provar que a precisão dos gnomos supera a imprudência dos goblins."},sec={{t="Uma Questão de Princípio e Pistões",b="No calor tremulante da Chapada Cintilante, alianças políticas e rancores antigos cedem ao rugido dos motores motorizados. Fizzle Brassbolts chegou aqui com um objetivo em mente: provar de uma vez por todas que o trabalho artesanal dos gnomos é amplamente superior à engenharia rudimentar dos goblins. Junto com seu equivalente goblin, Pozzik, ele ajudou a projetar o Circuito da Ilusão, trazendo carros de corrida, equipes de apoio e espectadores para uma bacia que, de outro modo, seria desolada."},{t="Engenhocas na Chapada",b="Correr pelos leitos secos de sal a velocidades vertiginosas exige improvisação constante, e Fizzle não foge de experimentos pouco ortodoxos. Seja testando misturas voláteis preparadas a partir do veneno de criaturas locais ou contratando viajantes para buscar peças mecânicas de reposição, Fizzle está determinado a manter as rodas do seu piloto girando mais rápido do que qualquer geringonça explosiva dos goblins."}},faq={{q="Quem é Fizzle Brassbolts?",a="Fizzle Brassbolts é um mestre engenheiro gnomo e o principal organizador da equipe de corrida dos gnomos posicionada no Circuito da Ilusão em Mil Agulhas.",al={"quem é fizzle","história de fizzle brassbolts","gnomo no circuito"}},{q="Por que Fizzle veio para a Chapada Cintilante?",a="Ele veio para resolver um debate técnico com o engenheiro goblin Pozzik sobre qual raça possui engenharia superior. Juntos, eles estabeleceram o Circuito da Ilusão para testar seus carros-foguete lado a lado na bacia plana de sal.",al={"por que fizzle está aqui","propósito do circuito","por que o circuito foi construído"}},{q="Quem são os Brassbolts Brothers?",a="Fizzle e seu irmão Wizzle Brassbolts administram a equipe de corrida dos gnomos no Circuito da Ilusão. Seu novo carro-foguete é tão rápido que seus pilotos continuam batendo, então eles pediram ao seu amigo Piloto Barbalonga em Altaforja capacetes de proteção de máquina de cerco.",al={"brassbolts brothers","wizzle brassbolts","irmão de fizzle"}},{q="Por que Fizzle precisa de veneno de criaturas para os carros de corrida?",a="Fizzle faz experimentos constantes com reagentes locais para formular fluidos de motor, aditivos e aceleradores potentes, capazes de dar aos seus carros-foguete uma vantagem sobre as máquinas de Pozzik.",al={"missão salt flat venom","veneno combustível de corrida","por que ele precisa de veneno"}},{q="Fizzle luta contra os goblins?",a="Não com armas. Embora exista uma profunda rivalidade profissional entre eles, Fizzle e Pozzik mantêm uma trégua neutra e instável no circuito para se concentrarem puramente na competição de alta velocidade.",al={"fizzle é hostil aos goblins","luta fizzle pozzik"}},{q="Quem é o Piloto Barbalonga?",a="O Piloto Barbalonga é um piloto anão de máquinas de cerco da Ironforge Siege Brigade e amigo dos Brassbolts Brothers que compartilha o apreço deles por maquinários perigosos.",al={"conexão com piloto barbalonga","amigo piloto de fizzle"}}},fx={["4ec804ad"]={q="O que Fizzle Brassbolts quer?",a="Fizzle não quer nada mais do que provar a supremacia absoluta da engenharia gnomica sobre a tecnologia goblin. Para esse fim, ele cofundou o Circuito da Ilusão ao lado de seu rival goblin Pozzik. Ele foca inteiramente no desenvolvimento de carros-foguete mais rápidos, na obtenção de ingredientes de combustível exóticos, como o veneno salgado dos escorpiões da Chapada Cintilante, e em vencer a equipe goblin através das salinas.",al={"o que fizzle quer","objetivo de fizzle brassbolts","por que fizzle está competindo"}},["092966e5"]={q="De que lado Fizzle Brassbolts está?",a="Fizzle Brassbolts representa os gnomos e sua equipe de corrida no Circuito da Ilusão. Neutro em relação aos viajantes da Aliança e da Horda, aqui na Chapada Cintilante ele mantém uma relação de trabalho funcional com engenheiros goblins como Pozzik. Embora seja ferozmente leal a provar que a engenharia gnômica é superior à dos goblins, a rivalidade deles é focada no Circuito da Ilusão, e não em uma guerra aberta.",al={"fizzle é da aliança","facção de fizzle brassbolts","para quem fizzle trabalha"}}},fp="17,397,33.444.0,22.375.0,25.146.0,44.222.0,32.242.0,50.179.0,38.181.0,23.169.0"}
P.entries["npc:fleet-master-seahorn"] = {n="Mestre de Frota Chifre do Mar",s="O Mestre de Frota Chifre do Mar é um experiente marinheiro tauren que serve como comandante naval dos Blackwater Raiders em Angra do Butim. Posicionado na sacada superior da Salty Sailor Tavern ao lado do Barão Rezingada, ele supervisiona as defesas marítimas do porto goblin. Seu dever principal é proteger o porto da ameaça iminente representada por seus arqui-inimigos, os Bucaneiros da Vela Sangrenta.",h="O Mestre de Frota Chifre do Mar é um experiente marinheiro tauren que serve como comandante naval dos...",kw={"blackwater raiders","vela sangrenta","angra do butim","enseada de faldir","firallon","mestre de frota chifre do mar","rezingada","salty sailor tavern","chifre do mar","praia selvagem"},ang={["class:Rogue"]="Ladinos que operam em Angra do Butim encontram Chifre do Mar no centro da espionagem costeira, organizando incursões secretas contra navios de guerra da Vela Sangrenta e interceptando ordens inimigas.",["faction:Horde"]="Embora Chifre do Mar seja um tauren, sua lealdade pertence estritamente ao Cartel Bondebico e aos Blackwater Raiders, mantendo uma postura neutra em relação a viajantes tanto da Horda quanto da Aliança.",["race:Tauren"]="Chifre do Mar é um dos raríssimos taurens que abandonaram as planícies interiores de Kalimdor para dominar o mar aberto, servindo como mestre de frota de um porto goblin neutro."},sec={{t="Um touro em alto-mar",b="Embora os taurens sejam famosos por toda Kalimdor como habitantes das planícies, o Mestre de Frota Chifre do Mar escolheu uma vida muito diferente sobre o oceano. Trajado em trajes piratas, ele comanda a frota dos Blackwater Raiders, o braço naval privado da operação do Cartel Bondebico na Selva do Espinhaço. Posicionado no topo da Salty Sailor Tavern, Chifre do Mar trabalha lado a lado com o Barão Rezingada, coordenando rotas marítimas, distribuição de tripulações e defesas costeiras para o porto sem leis, porém rigorosamente gerenciado, de Angra do Butim."},{t="Defendendo a baía",b="A maior preocupação contínua de Chifre do Mar são os Bucaneiros da Vela Sangrenta, que estabeleceram acampamentos fortificados ao longo da Praia Selvagem meridional e ancoraram navios de guerra ao largo da costa. Quando relatórios revelam que o Mestre de Frota Firallon e a liderança da Vela Sangrenta pretendem lançar um ataque direto para saquear Angra do Butim, Chifre do Mar toma medidas agressivas. Ao despachar mercenários para apreender a correspondência inimiga e neutralizar Firallon, Keelhaul e Stillwater a bordo de sua nau capitânia, Chifre do Mar protege com sucesso o porto da devastação total."},{t="Olhos além dos mares",b="Além de repelir ataques piratas, Chifre do Mar gerencia vários empreendimentos comerciais e de resgate pelos Reinos do Leste. Ele coordena esforços de recuperação de tesouros afundados na costa de Arathi, perto da Enseada de Faldir, trabalhando com mergulhadores de resgate para garantir relíquias élficas. Ele também mantém Rezingada informado sobre oportunidades lucrativas que passam pela cidade, como pesca competitiva e comércio local, garantindo que a frota de Blackwater permaneça bem financiada e à frente das operações rivais."}},faq={{q="Onde fica o Mestre de Frota Chifre do Mar?",a="Ele fica no último andar e na sacada da Salty Sailor Tavern em Angra do Butim, bem ao lado do Barão Rezingada, com vista para as docas.",al={"onde fica chifre do mar","localizacao chifre do mar","encontrar chifre do mar"}},{q="Por que um tauren atua como mestre de frota pirata?",a="Embora a maioria dos taurens permaneça intimamente ligada às planícies e tradições espirituais de Mulgore, Chifre do Mar aderiu à vida náutica e mercenária. Sua perícia marinheira e presença de comando lhe renderam a liderança dos Blackwater Raiders sob o comando do Barão Rezingada.",al={"pirata tauren","por que chifre do mar e pirata","tauren em angra do butim"}},{q="Qual é a relação de Chifre do Mar com o Barão Rezingada?",a="Chifre do Mar é o segundo em comando do Barão Rezingada e o comandante naval dos seus Blackwater Raiders. Enquanto Rezingada cuida da política, do comércio e das finanças, Chifre do Mar supervisiona a frota, a inteligência tática e as operações militares defensivas de Angra do Butim.",al={"chifre do mar e rezingada","chifre do mar e guarda costas do rezingada","quem trabalha para rezingada"}},{q="Quem são os Blackwater Raiders?",a="Os Blackwater Raiders são uma frota privada de corsários leais ao Cartel Bondebico, sediada em Angra do Butim. Ao contrário de saqueadores foras da lei que pilham indiscriminadamente, eles agem como a marinha autorizada que protege os interesses comerciais dos goblins e mantém a ordem nos mares do sul.",al={"blackwater raiders","qual e a faccao de chifre do mar","piratas de angra do butim"}},{q="Por que Chifre do Mar quer deter os Bucaneiros da Vela Sangrenta?",a="Os Bucaneiros da Vela Sangrenta são os rivais figadais dos Blackwater Raiders. Liderada pelo Mestre de Frota Firallon, a Vela Sangrenta montou acampamentos ao longo da Praia Selvagem e pretende conquistar a própria Angra do Butim. Chifre do Mar trabalha constantemente para neutralizar os planos de invasão deles.",al={"chifre do mar vs vela sangrenta","conflito vela sangrenta","por que lutar contra a vela sangrenta"}},{q="Chifre do Mar tem negócios fora da Selva do Espinhaço?",a="Sim. Chifre do Mar trabalha com agentes de resgate como Doctor Draxlegauge e Shakes O'Breen para recuperar cargas perdidas e tesouros élficos naufragados perto da Enseada de Faldir, no Planalto Arathi, fazendo com que artefatos valiosos sejam entregues de volta ao seu posto em Angra do Butim.",al={"enseada de faldir chifre do mar","tesouro afundado chifre do mar","missoes de arathi chifre do mar"}}},fp="20,378,23.506.0,17.524.1,20.470.0,38.143.0,49.254.0,51.250.0,31.277.0,55.254.0,57.242.0"}
P.entries["npc:foggy-mackreel"] = {n="Ruço MacKreel",s="Ruço MacKreel é um anão intrépido ilhado precariamente na alvenaria inferior em ruínas da Ponte Thandol. Apesar das pedras despedaçadas sob seus pés e da queda vertiginosa abaixo, sua única preocupação real é concluir sua entrega de aguardente clandestina ao norte, rumo a Costa Sul.",h="Ruço MacKreel é um anão intrépido ilhado precariamente na alvenaria inferior em ruínas da Ponte Thandol.",kw={"arathi","ruço","mackreel","aguardente","costa sul","ponte thandol","pantanal"},ang={["faction:Alliance"]="Mensageiros da Aliança que viajam entre Altaforja e o entreposto nortista de Costa Sul frequentemente cruzam o caminho de Ruço, assumindo sua carga encalhada para ajudar um companheiro da Aliança.",["race:Dwarf"]="MacKreel personifica a determinação obstinada — e as prioridades peculiares — da raça dos anões, valorizando a entrega pontual de bebida forte muito acima de pequenos detalhes, como estar ilhado sobre um abismo mortal."},sec={{t="Ilhado na Ponte",b="Empoleirado nos pilares quebrados sob a arruinada Ponte Thandol, Ruço MacKreel parece totalmente impassível diante de sua situação perigosa. Embora a sabotagem dos Ferro Negro e os danos de guerra tenham deixado fraturada a grande ponte entre os Pantanal e o Planalto Arathi, MacKreel encara seu apoio precário como um mero inconveniente. Seu pensamento principal não é o resgate, mas um lote não entregue de potente aguardente destinado aos clientes de Costa Sul, no Contraforte de Eira dos Montes. Ele prontamente contrata aventureiros que passam por ali, ágeis o suficiente para alcançar sua beirada, a fim de concluir a entrega em seu lugar."}},faq={{q="Quem é Ruço MacKreel?",a="Ruço MacKreel é um excêntrico mensageiro anão ilhado nos pilares de pedra em ruínas sob a ponte quebrada da Ponte Thandol. Apesar do abismo abaixo, ele permanece completamente calmo e focado em fazer com que sua aguardente seja entregue.",al={"ruço mackreel","quem é ruço","npc mackreel"}},{q="Onde posso encontrar Ruço MacKreel?",a="Ele está localizado em uma plataforma de pedra no meio do vão central destruído da Ponte Thandol, acessível pulando com cuidado da estrutura da ponte pelo lado do Planalto Arathi.",al={"onde fica ruço mackreel","localização de ruço mackreel","como encontrar mackreel"}},{q="Por que Ruço MacKreel está lá embaixo?",a="Ruço acabou preso em meio aos destroços da Ponte Thandol durante suas viagens. No entanto, em vez de buscar resgate, sua maior preocupação é encontrar alguém disposto a levar sua carga de aguardente pelo restante do caminho até Costa Sul.",al={"por que ruço está ilhado","como mackreel foi parar lá","por que ele está na ponte"}},{q="Qual missão Ruço MacKreel oferece?",a="Ele oferece 'MacKreel's Moonshine', pedindo aos viajantes que entreguem um jarro de sua bebida potente à taverna em Costa Sul, através do Planalto Arathi.",al={"missão do ruço","missão mackreel moonshine","qual missão ruço dá"}}},fx={["28a25d1f"]={q="De que lado Ruço MacKreel está?",a="Ruço MacKreel é um anão aliado à Aliança. Mesmo preso precariamente ao longo das ruínas danificadas da The Thandol Span, suas lealdades e negócios estão diretamente com seus parentes e outros assentamentos da Aliança, visando, mais notavelmente, levar sua bebida potente para o norte, para as mãos do pessoal que mantém a Costa Sul no Contraforte de Eira dos Montes.",al={"facção de ruço mackreel","ruço mackreel é aliança","lado de ruço mackreel"}},c1253653={q="O que Ruço MacKreel quer?",a="Ruço MacKreel quer que seu lote especial de luar seja levado em segurança para a Costa Sul. Apesar de estar preso em um pilar estilhaçado sob a ponte, ele mostra surpreendentemente pouco cuidado com sua própria situação perigosa, permanecendo inteiramente preocupado em garantir que sua bebida chegue ao seu destino em Eira dos Montes, em vez de planejar um resgate imediato.",al={"motivo de ruço mackreel","o que ruço quer","objetivo de ruço mackreel"}}},fp="14,264,20.583.0,22.226.0,32.183.0,33.217.0,37.143.0"}
P.entries["npc:foreman-oslow"] = {n="Encarregado Oslow",s="O Encarregado Oslow é o sobrecarregado mestre de obras de Vila Plácida, encarregado de consertar a arruinada The Everstill Bridge no coração das Montanhas Cristarrubra. Atormentado pela artilharia dos orcs Rocha Negra e por invasores gnolls, seus esforços de reconstrução foram paralisados devido a remessas perdidas e equipamentos afundados. Ele depende muito de aventureiros viajantes para recuperar seus equipamentos e garantir materiais para que Vila Plácida possa reconectar sua rota comercial vital.",h="O Encarregado Oslow é o sobrecarregado mestre de obras de Vila Plácida, encarregado de consertar a arruinada...",kw={"rocha negra","the everstill bridge","encarregado oslow","vila d'ouro","vila plácida","oslow","montanhas cristarrubra","caixa de ferramentas"},ang={["faction:Alliance"]="A ponte interrompida de Vila Plácida deixa a fronteira leste exposta, tornando os esforços de restauração de Oslow uma necessidade estratégica para proteger a fronteira da Aliança.",["profession:Mining"]="Oslow depende de matérias-primas, peças de metal e remessas de pedreiras para reconstruir a alvenaria quebrada, mantendo-o intimamente ligado às entregas locais de minerais."},sec={{t="Uma Cidade Dividida ao Meio",b="Ao lado da alvenaria fraturada de The Everstill Bridge, o Encarregado Oslow enfrenta uma batalha difícil. A ponte é a tábua de salvação de Vila Plácida, atravessando a extensão do Lago Plácido e ligando as estradas a oeste em direção a Elwynn às margens orientais. Orcs Rocha Negra, descendo dos penhascos do Mirante de Pedra, alvejaram a travessia para prejudicar a logística e a movimentação militar da cidade, deixando o assentamento dividido e vulnerável."},{t="Aço Afundado e Pedra Roubada",b="Cada tentativa que Oslow faz para reconstruir parece assolada pelo infortúnio. Quando a ponte caiu, suas ferramentas de substituição foram enviadas por terra de Vila d'Ouro e carregadas em uma balsa no lago. As tripulações de catapultas orcs avistaram a embarcação, enviando sua pesada caixa de ferramentas de ferro direto para o leito lamacento do Lago Plácido. Para piorar a situação, gnolls locais de Cristarrubra sequestraram a caravana de novos materiais enviada de Ventobravo, fugindo com as estacas de ferro e rebites necessários para erguer os arcos."}},faq={{q="Quem é o Encarregado Oslow?",a="O Encarregado Oslow é um pedreiro e construtor humano instalado em Vila Plácida. Ele é o artesão-chefe responsável pela manutenção e reconstrução de The Everstill Bridge.",al={"encarregado oslow","quem é oslow","construtor de vila plácida"}},{q="Por que The Everstill Bridge está quebrada?",a="The Everstill Bridge foi despedaçada pelos orcs Rocha Negra das Montanhas Cristarrubra. A destruição do vão cortou a principal via de passagem de Vila Plácida, enfraquecendo severamente as defesas da cidade e interrompendo o trânsito fácil entre as margens leste e oeste.",al={"por que a ponte está quebrada","quem quebrou a ponte de vila plácida","the everstill bridge destruída"}},{q="Onde estão as ferramentas perdidas de Oslow?",a="A pesada caixa de ferramentas de Oslow repousa no fundo do Lago Plácido. O barco que as transportava de Vila d'Ouro foi atingido e afundado por uma barragem de catapultas Rocha Negra.",al={"onde estão as ferramentas","localização das ferramentas perdidas","caixa de ferramentas de oslow"}},{q="Por que a ponte ainda não foi consertada?",a="Entre o fogo das catapultas orcs afundando suas ferramentas no lago e gnolls roubando suprimentos de construção de remessas que chegavam, faltam a Oslow os materiais e equipamentos necessários para retomar a construção sem ajuda externa.",al={"por que a ponte não foi consertada","atraso na ponte de vila plácida"}},{q="De onde vieram originalmente os suprimentos de Oslow?",a="Suas ferramentas de reposição foram originalmente transportadas em uma carroça de Vila d'Ouro, na Floresta de Elwynn, antes de serem transferidas para uma balsa no lago para contornar o vão quebrado.",al={"origem da carroça de suprimentos","de onde vieram as ferramentas"}},{q="Com quais ameaças Oslow está lidando?",a="Oslow enfrenta constante hostilidade de duas frentes: os orcs do clã Rocha Negra entrincheirados nas colinas próximas, cujas armas de cerco bombardeiam o lago, e gnolls à espreita que atacam comboios de suprimentos.",al={"inimigos de oslow","quem ataca a ponte"}}},fx={cf681f3e={q="De que lado o Encarregado Oslow está?",a="O Encarregado Oslow serve ao Reino de Ventobravo e ao município local de Vila Plácida. Como construtor-chefe e encarregado da cidade, seu dever é manter a infraestrutura vital de Montanhas Cristarrubra e ajudar seu povo a sobreviver, apesar dos ataques implacáveis dos orcs Rocha Negra ao redor e dos gnolls hostis.",al={"facção de oslow","a quem o encarregado oslow serve","encarregado oslow aliança"}},["1a3f577b"]={q="O que o Encarregado Oslow quer?",a="O objetivo principal de Oslow é reconstruir a arruinada The Everstill Bridge e manter Vila Plácida conectada ao resto do reino. Para realizar isso, ele precisa desesperadamente que sua caixa de ferramentas submersa seja dragada do Lago Plácido e que os suprimentos de construção que foram emboscados e roubados pelos gnolls locais sejam recuperados.",al={"o que oslow quer","objetivo do encarregado oslow","por que oslow precisa de ajuda"}},["765147a2"]={q="Por que o Encarregado Oslow está em Vila Plácida?",a="Oslow está posicionado perto do lago para supervisionar obras públicas e liderar a reconstrução da The Everstill Bridge. A ponte é a força vital de Vila Plácida, mas ataques inimigos implacáveis e perdas devastadoras de suprimentos o mantêm preso bem na beira da água, esperando por ajuda para continuar seu trabalho.",al={"por que oslow está aqui","propósito de oslow em vila plácida","trabalho do encarregado oslow"}}},fp="13,413,17.430.0,29.481.0,21.172.0,35.246.0,29.155.0,40.213.0,48.158.0,35.193.0"}
P.entries["npc:foreman-stonebrow"] = {n="Encarregado Pedracenho",s="O Encarregado Pedracenho é um supervisor anão que representa a Miners' League na Pedreira Gol'Bolar, na parte leste de Dun Morogh. Depois que troggs agressivos irromperam das rochas e invadiram o local de escavação, ele foi forçado a organizar uma defesa e contratar aventureiros para limpar as covas.",h="O Encarregado Pedracenho é um supervisor anão que representa a Miners' League na Pedreira Gol'Bolar, na parte...",kw={"dun morogh","encarregado pedracenho","gol'bolar","pedreira gol'bolar","miners' league","pedracenho","troggs"},ang={["profession:Mining"]="Os mineradores têm um interesse profissional em ajudar Pedracenho, pois recuperar as ricas jazidas de pedra e minério da pedreira é vital para as operações da guilda em Khaz Modan.",["race:Dwarf"]="Para os anões, a invasão dos troggs na Pedreira Gol'Bolar é um golpe direto na indústria de pedra de Altaforja e uma lembrança sombria das antigas ameaças à espreita sob o solo ancestral deles."},sec={{t="A Crise em Gol'Bolar",b="O Encarregado Pedracenho foi encarregado de comandar as operações na Pedreira Gol'Bolar, uma importante escavação anã situada nas montanhas a leste de Kharanos. Quando as escavações profundas abriram caminho para tocas ocultas de troggs, feras subterrâneas invadiram as covas e expulsaram os mineradores de seus equipamentos. Recusando-se a abandonar o local por completo, Pedracenho permanece na borda da pedreira para recrutar quaisquer viajantes capazes dispostos a repelir os troggs."}},faq={{q="Quem é o Encarregado Pedracenho?",a="O Encarregado Pedracenho é um anão ligado à Miners' League que supervisiona o trabalho na Pedreira Gol'Bolar, em Dun Morogh. Ele coordena as operações e tenta manter a pedreira segura.",al={"pedracenho","quem é pedracenho","história do encarregado pedracenho"}},{q="Por que o Encarregado Pedracenho está pedindo ajuda?",a="As escavações na Pedreira Gol'Bolar romperam inadvertidamente cavernas subterrâneas de troggs. Os troggs invadiram os terraços inferiores, matando trabalhadores e forçando os mineradores sobreviventes a recuar para o acampamento na borda.",al={"problema dos troggs de gol'bolar","por que precisa de ajuda","missão da pedreira"}},{q="O que é a Miners' League?",a="A Miners' League é uma guilda e organização comercial anã sediada em Altaforja, que supervisiona expedições de mineração, extração de recursos e operações de pedreiras por toda Khaz Modan.",al={"miners league","o que é miners league"}},{q="Onde o Encarregado Pedracenho pode ser encontrado?",a="Ele está instalado no acampamento na borda da Pedreira Gol'Bolar, situado nas colinas a leste de Dun Morogh, logo ao lado da estrada que leva a Loch Modan.",al={"localização de pedracenho","onde fica o encarregado pedracenho"}}},fx={["2635f3c5"]={q="De que lado o Encarregado Pedracenho está?",a="O Encarregado Pedracenho é leal à Liga dos Mineradores e ao reino anão de Altaforja, colocando-o firmemente na Aliança. Ele supervisiona o trabalho de escavação cívica em Dun Morogh e busca aventureiros da Aliança para eliminar ameaças das operações de mineração de Altaforja.",al={"facção de pedracenho","a quem pedracenho serve","pedracenho aliança"}},c868fd05={q="Por que o Encarregado Pedracenho está na Pedreira Gol'Bolar?",a="O Encarregado Pedracenho foi enviado para a Pedreira Gol'Bolar para supervisionar a escavação e a extração de recursos em nome da Liga dos Mineradores. Ele permanece posicionado perto da cova da pedreira para reunir assistência e coordenar esforços para retomar o local após uma infestação repentina de troggs sobrecarregar a força de trabalho.",al={"por que pedracenho está aqui","pedracenho gol'bolar","o que pedracenho está fazendo aqui"}}},fp="17,269,23.426.0,25.183.0,41.201.0,27.182.0,37.151.0"}
P.entries["npc:foreman-thazz-ril"] = {n="Encarregado Thazz'ril",s="O Encarregado Thazz'ril é um orc supervisor de trabalho situado no Vale das Provações, em Durotar. Encarregado de manter os peões no cronograma e manter a infraestrutura básica para os jovens guerreiros, ele vive perpetuamente frustrado com os trabalhadores preguiçosos e com a atividade dos cultistas nas proximidades.",h="O Encarregado Thazz'ril é um orc supervisor de trabalho situado no Vale das Provações, em Durotar.",kw={"cassetete","lâmina ardente","durotar","encarregado","lazy peons","thazzril","vale das provações"},ang={["profession:Mining"]="Thazz'ril valoriza equipamentos de mineração de qualidade, como demonstrado por seu desespero em recuperar sua picareta encantada dos recessos escuros do Covil da Lâmina Ardente.",["race:Orc"]="Para os jovens orcs que alcançam a maturidade, Thazz'ril oferece uma lição precoce na sociedade da Horda: a força no campo de batalha só é possível quando apoiada por um trabalho árduo, inglório e disciplinado."},sec={{t="Mantendo os peões na linha",b="Construir um novo lar nas duras rochas vermelhas de Durotar exige trabalho físico contínuo. No Vale das Provações, o Encarregado Thazz'ril supervisiona os peões que cortam madeira e recolhem os materiais necessários para sustentar tanto o acampamento quanto o esforço de guerra mais amplo da Horda. Infelizmente para Thazz'ril, os peões têm a infame tendência de relaxar e tirar sonecas sob o sol do deserto. Para manter as obras em andamento, ele recruta regularmente os recém-chegados para darem um bom golpe nos trabalhadores adormecidos com seu fiel cassetete, impondo obediência por meio da persuasão bruta."},{t="Uma picareta perdida em mãos perigosas",b="As responsabilidades de Thazz'ril também envolvem inspecionar os recursos minerais do vale, embora esse dever tenha levado a um deslize embaraçoso. Ao explorar a caverna conhecida como Covil da Lâmina Ardente, ele foi forçado a fugir dos cultistas sombrios à espreita em seu interior, abandonando acidentalmente sua preciosa picareta encantada. Cauteloso demais para resgatá-la por conta própria em meio à aglomeração de bruxos e seus lacaios demoníacos, ele depende de jovens aspirantes da Horda para se aventurarem nas profundezas e recuperarem sua ferramenta."}},faq={{q="Quem é o Encarregado Thazz'ril?",a="O Encarregado Thazz'ril é um orc feitor de trabalho no Vale das Provações, em Durotar. Ele é responsável por gerenciar equipes de trabalho, cortar madeira e inspecionar a região em busca de recursos úteis para ajudar no assentamento da Horda.",al={"quem e thazzril","thazzril vale das provacoes","historia encarregado thazzril"}},{q="Por que Thazz'ril dá um cassetete aos jogadores?",a="Os peões sob sua vigilância frequentemente adormecem sob as árvores em vez de cortar lenha. Thazz'ril fornece um cassetete de madeira encantado para impor alguma disciplina a eles e mandá-los de volta ao trabalho às pressas.",al={"por que bater nos lazy peons","cassetete de thazzril","historia missao lazy peons"}},{q="Por que a picareta de Thazz'ril está dentro da caverna da Lâmina Ardente?",a="Enquanto inspecionava as cavernas locais em busca de veios de minério, Thazz'ril entrou por acaso no Covil da Lâmina Ardente. Assustado com os cultistas escondidos nas sombras, ele bateu em retirada às pressas e deixou para trás sua valiosa picareta encantada.",al={"picareta de thazzril","por que picareta esta no covil","picareta lamina ardente"}},{q="Qual é o papel dele na Horda?",a="Thazz'ril não é um soldado de linha de frente nem um xamã, mas sim um feitor civil. Seus deveres se concentram na base logística de Durotar: supervisionar o trabalho manual, manter os suprimentos de construção e manter os peões produtivos.",al={"thazzril e um soldado","posto de thazzril"}}},fx={["607050fc"]={q="De que lado o Encarregado Thazz'ril está?",a="Thazz'ril é leal à Horda de Thrall. Posicionado no Vale das Provações, ele supervisiona o trabalho fundamental e a coleta de recursos que ajuda a construir Durotar e sustenta os campos de treinamento para os recrutas orcs e trolls que chegam.",al={"lealdade do encarregado thazz'ril","thazz'ril horda","facção de thazz'ril"}},f77b2dd2={q="O que o Encarregado Thazz'ril quer?",a="Thazz'ril quer principalmente que seus trabalhadores realmente trabalhem. Exasperado com peões preguiçosos vadiando pelo vale, ele recruta jovens aventureiros para acordá-los. Ele também busca a recuperação de sua valiosa picareta encantada, que ele infelizmente abandonou perto do coven da Lâmina Ardente.",al={"objetivos de thazz'ril","o que thazz'ril precisa","motivo da missão de thazz'ril"}},ee1167cb={q="Por que o Encarregado Thazz'ril está aqui?",a="Ele está designado para o Vale das Provações para dirigir o trabalho dos peões e gerenciar os esforços locais de mineração e coleta de madeira. Manter o assentamento e manter o fluxo de matérias-primas é essencial para preparar jovens guerreiros antes que se aventurem pelas terras mais amplas de Durotar.",al={"por que thazz'ril está no vale das provações","motivo da localização de thazz'ril"}}},fp="17,260,25.562.0,30.481.0,25.215.0,44.213.0,54.214.0,30.220.0"}
P.entries["npc:foreman-thistlenettle"] = {n="Encarregado Cardurtiga",s="O Encarregado Cardurtiga já foi um supervisor anão representando tanto a Miners' League quanto a Explorers' League nas profundezas de Cerro Oeste. Depois que um desmoronamento catastrófico prendeu sua equipe nos túneis subterrâneos das Minas Mortas, ele pereceu ao lado de seus trabalhadores e se ergueu novamente como um carniçal morto-vivo. Ele agora vaga pelos corredores escuros e desmoronados, irreconhecível para todos, exceto pelo distintivo da guilda que ainda carrega.",h="O Encarregado Cardurtiga já foi um supervisor anão representando tanto a Miners' League quanto a Explorers'...",kw={"distintivo","desmoronamento","minas mortas","encarregado","carniçal","miners' league","cardurtiga","wilder"},ang={["profession:Mining"]="O destino de Cardurtiga é um lembrete sombrio a todos os mineradores sobre o perigo constante de desmoronamentos de túneis e das hostis profundezas subterrâneas.",["race:Dwarf"]="A perda trágica de um encarregado da Explorers' League e de toda uma equipe anã destaca os perigos persistentes que espreitam sob os reinos humanos."},sec={{t="Tragédia nas Minas Mortas",b="Antes de A Irmandade Défias assumir o controle total das Minas Mortas, expedições mineradoras legítimas se aprofundavam em seus ricos veios. O Encarregado Cardurtiga supervisionava uma dessas empreitadas em nome da Miners' League e da Explorers' League. No fundo dos túneis sob Arroio da Lua, uma tragédia aconteceu quando um desmoronamento violento isolou seu grupo da superfície. Os mineradores encurralados morreram na escuridão, mas seu descanso não durou; uma mácula necrótica e sinistra ergueu Cardurtiga e sua equipe como carniçais vorazes para rondar as passagens sombrias."},{t="O Luto de um Irmão",b="Em Ventobravo, seu irmão Wilder Urtigão passou meses inquietos se perguntando sobre o destino da equipe de mineração desaparecida. Sem nenhuma notícia vinda dos túneis ocupados, surgiram boatos de que o falecido supervisor ainda caminhava entre os mortos. Aventureiros que enfrentam os arredores das Minas Mortas são convidados a localizar o encarregado morto-vivo, dar fim ao seu tormento e recuperar seu distintivo para trazer conforto ao seu parente em luto."}},faq={{q="Quem era o Encarregado Cardurtiga antes de morrer?",a="Ele era um encarregado anão associado tanto à Miners' League quanto à Explorers' League. Ele liderou uma equipe de mineradores nas Minas Mortas antes de sua completa fortificação por criminosos, buscando escavar e mapear os veios subterrâneos.",al={"história de cardurtiga","quem é o encarregado cardurtiga","passado de cardurtiga"}},{q="Por que o Encarregado Cardurtiga é um carniçal morto-vivo?",a="Um desmoronamento catastrófico soterrou os túneis ao redor de Cardurtiga e de seu grupo de mineração, matando-os. Energias subterrâneas sombrias ou necromancia residual dentro do labirinto das minas animaram seus restos mortais posteriormente, transformando os anões em carniçais inquietos.",al={"por que ele é um carniçal","como cardurtiga morreu","cardurtiga morto-vivo"}},{q="Onde fica o Encarregado Cardurtiga?",a="Ele assombra um túnel desmoronado e sem saída dentro do labirinto exterior das Minas Mortas, localizado antes do portal para a própria masmorra interna, cercado por seus antigos mineradores reanimados.",al={"onde encontrar cardurtiga","localização de cardurtiga","lugar do encarregado nas minas mortas"}},{q="Quem está procurando pelo Encarregado Cardurtiga?",a="Seu irmão, Wilder Urtigão, que reside no Distrito dos Anões de Ventobravo. Wilder busca provas do destino de seu irmão e pede aos viajantes que tragam de volta o Distintivo de Cardurtiga.",al={"quem quer a morte de cardurtiga","irmão de wilder","quem dá a missão de cardurtiga"}}},fx={["81248170"]={q="De que lado o Encarregado Cardurtiga está?",a="O Encarregado Cardurtiga não pertence a nenhuma facção ou causa mais. Agora um carniçal irracional e voraz, ele e sua equipe reanimada atacam qualquer um tolo o suficiente para se aventurar em seu canto colapsado das Minas Mortas, seja da Defias, da Aliança ou caçadores de tesouros errantes.",al={"facção de cardurtiga","o encarregado cardurtiga é hostil","a quem cardurtiga serve"}},a595eadc={q="O que o Encarregado Cardurtiga quer?",a="Quaisquer ambições anãs que ele possuía em vida morreram no desmoronamento. Na morte-viva, o Encarregado Cardurtiga não tem grandes designs ou esquemas — apenas a fome cega e inquieta compartilhada por todos os carniçais, rondando os escombros escuros em busca de qualquer coisa viva que se aproxime.",al={"o que cardurtiga quer","motivo do encarregado cardurtiga","objetivo de cardurtiga"}},["194368c4"]={q="Por que o Encarregado Cardurtiga está aqui nas Minas Mortas?",a="Ele originalmente se aventurou fundo nas Minas Mortas supervisionando uma expedição em nome da Liga dos Mineradores e da Liga dos Exploradores. Quando o desastre atingiu e um colapso subterrâneo esmagou sua equipe, eles ficaram presos sob a rocha e nunca puderam sair, mesmo após a morte.",al={"por que cardurtiga está nas minas mortas","como cardurtiga chegou aqui","por que o encarregado cardurtiga está aqui"}}},fp="21,416,24.530.0,17.419.1,45.237.0,45.261.0,39.181.0,41.186.0"}
P.entries["npc:frahun-shadewhisper"] = {n="Frahun Umbrurmúrio",s="Frahun Umbrurmúrio é um instrutor de ladinos elfo noturno localizado em Aldrassil, em Umbravale. Ele ensina a batedores e ladinos elfos noturnos recém-iniciados as técnicas fundamentais de furtividade, agilidade e golpes discretos. Ele compartilha o sobrenome com Erion Umbrurmúrio, outro instrutor de seu ofício em Darnassus.",h="Frahun Umbrurmúrio é um instrutor de ladinos elfo noturno localizado em Aldrassil, em Umbravale.",kw={"aldrassil","o selo cifrado","erion","frahun","instrutor de ladinos","umbrurmúrio","umbravale","teldrassil"},ang={["class:Rogue"]="Frahun Umbrurmúrio atua como o primeiríssimo mentor de classe para ladinos elfos noturnos, fornecendo a introdução inicial à furtividade, táticas de emboscada e destreza com armas.",["race:NightElf"]="Frahun demonstra como os elfos noturnos adaptam sua afinidade noturna natural e sua esquiva em habilidades letais e práticas de combate para proteger Teldrassil."},sec={{t="Um Mentor nas Sombras",b="Dentro do refúgio seguro de Aldrassil, no coração de Teldrassil, Frahun Umbrurmúrio instrui ladinos iniciantes nas artes silenciosas da dissimulação e do manejo de lâminas. Embora a sociedade dos elfos noturnos frequentemente honre sacerdotes, sentinelas e druidas, o ofício especializado de batedores e infiltradores continua essencial para proteger os galhos da Árvore do Mundo. Frahun acolhe recrutas que chegam portando um selo cifrado, avaliando seu potencial e orientando seu desenvolvimento inicial."}},faq={{q="Quem é Frahun Umbrurmúrio?",a="Frahun Umbrurmúrio é um instrutor de ladinos elfo noturno localizado em Aldrassil, em Teldrassil. Ele ensina a ladinos novatos os fundamentos da furtividade, do combate de precisão e de táticas secretas.",al={"frahun história","quem é frahun","papel de frahun umbrurmúrio"}},{q="Onde Frahun Umbrurmúrio pode ser encontrado?",a="Ele está localizado em Aldrassil, a fortaleza central da área inicial de Umbravale, em Teldrassil.",al={"localização de frahun","onde fica frahun","encontrar frahun umbrurmúrio"}},{q="Frahun é parente de Erion Umbrurmúrio?",a="Dado o sobrenome compartilhado e a dedicação mútua ao treinamento de ladinos em Teldrassil, acredita-se amplamente que Frahun seja parente de Erion Umbrurmúrio, que treina ladinos em Darnassus.",al={"irmão de erion umbrurmúrio","frahun erion parentesco","família umbrurmúrio"}},{q="Qual é o papel de O selo cifrado com ele?",a="Ladinos elfos noturnos novatos começam sua jornada levando um selo cifrado diretamente a Frahun, marcando-os como candidatos prontos para a instrução formal no ofício de ladino.",al={"entregar o selo cifrado","selo de frahun","missão inicial de ladino"}}},fx={a27f02ba={q="De que lado Frahun Umbrurmúrio está?",a="Frahun está firmemente com Darnassus e a Aliança. Posicionado entre os ramos antigos de Aldrassil em Umbravale, ele serve seus companheiros kaldorei garantindo que aqueles com aptidão para furtividade e subterfúgio possam aprimorar seus ofícios para proteger as terras dos elfos noturnos.",al={"facção de frahun","lealdade de frahun","frahun é aliança"}},["025c0171"]={q="O que Frahun Umbrurmúrio quer?",a="Frahun busca instruir aspirantes a ladinos elfos noturnos nas artes das sombras, arrombamento e combate furtivo. Ele garante que novos batedores e operativos entendam sua disciplina completamente antes de se aventurarem além das fronteiras protegidas de Umbravale para o resto de Teldrassil.",al={"motivo de frahun","objetivo de frahun","o que frahun faz"}},["72dec556"]={q="Por que Frahun Umbrurmúrio está aqui em Aldrassil?",a="Frahun está posicionado em Aldrassil para guiar elfos noturnos recém-despertados ou novatos que seguem o caminho do ladino. No refúgio seguro de Umbravale, ele fornece treinamento fundamental para garantir que praticantes iniciantes não sucumbam aos perigos que espreitam na floresta.",al={"por que frahun está em aldrassil","frahun umbravale por que","propósito da localização de frahun"}}},fp="19,308,23.468.0,27.178.0,39.100.0,40.173.0,49.172.0"}
P.entries["npc:furen-longbeard"] = {n="Furen Barbalonga",s="Furen Barbalonga é um mestre armeiro anão estabelecido no movimentado Distrito dos Anões de Ventobravo. Tendo sido aprendiz do renomado ferreiro Grimand Elmore, ele se especializou na confecção de equipamentos pesados de proteção e malhas resistentes para defensores veteranos da Aliança. Guerreiros de todo o reino buscam sua perícia metalúrgica para forjar armaduras especializadas e prontas para o combate.",h="Furen Barbalonga é um mestre armeiro anão estabelecido no movimentado Distrito dos Anões de Ventobravo.",kw={"armeiro","ferreiro","distrito dos anões","fire hardened mail","furen barbalonga","grimand elmore","ventobravo","guerreiro"},ang={["class:Warrior"]="Para os guerreiros da Aliança que atingem a maioridade, Furen Barbalonga é um contato crucial que transforma determinação marcial pura e reagentes reunidos em uma armadura defensiva vital tratada pelo fogo.",["profession:Blacksmithing"]="Furen representa os altos padrões da ferraria dos anões estabelecidos em Ventobravo, exibindo técnicas avançadas transmitidas por Grimand Elmore.",["race:Dwarf"]="Mesmo longe de Altaforja, Furen Barbalonga mantém vivas as tradições metalúrgicas dos anões no coração da capital humana."},sec={{t="Um Ferreiro Anão na Capital Humana",b="Furen Barbalonga exerce seu ofício longe das grandes forjas de Altaforja, fazendo seu lar entre os paralelepípedos e a fuligem do Distrito dos Anões de Ventobravo. Como muitos de seu povo, Furen trouxe a tradicional metalurgia dos anões para o sul a fim de apoiar a reconstrução e a defesa do reino. Trabalhando em meio a lareiras ardentes e bigornas retinindo, ele mantém laços sólidos com outros artesãos por toda a cidade e além."},{t="Maestria em Fire Hardened Mail",b="Tendo aprendido com o venerável artesão Grimand Elmore, Furen aperfeiçoou técnicas para o tratamento de malha pesada e placas para suportar o rigor extremo dos campos de batalha. Jovens e promissores guerreiros que buscam proteção durável frequentemente recorrem a Furen, que exige minérios raros, componentes especializados e reagentes exóticos de cantos distantes do mundo para confeccionar sua emblemática armadura tratada pelo fogo."}},faq={{q="Quem é Furen Barbalonga?",a="Furen Barbalonga é um armeiro anão que atua no Distrito dos Anões em Ventobravo. Ele atua como um contato essencial e mentor para guerreiros da Aliança que procuram obter armaduras de malha magistralmente trabalhadas.",al={"quem é furen","história de furen barbalonga","armeiro anão ventobravo"}},{q="Onde Furen Barbalonga pode ser encontrado?",a="Ele está localizado no Distrito dos Anões de Ventobravo, junto às movimentadas forjas e oficinas de ferraria que dominam o bairro.",al={"onde fica furen barbalonga","localização de furen barbalonga","furen ventobravo"}},{q="Quem ensinou a Furen o ofício da ferraria?",a="Furen aprendeu a fabricação de armaduras e a metalurgia com Grimand Elmore, um respeitado artesão veterano que também reside no Distrito dos Anões.",al={"professor de furen","mentor de furen","quem treinou furen"}},{q="Qual armadura Furen é famoso por fabricar?",a="Ele é renomado por confeccionar a Fire Hardened Mail, um conjunto resiliente de armadura criado por meio de processos metalúrgicos rigorosos que exigem componentes raros reunidos por todo o continente.",al={"fire hardened mail","missão de armadura do furen","missão de malha de guerreiro ventobravo"}},{q="Furen Barbalonga tem parentesco com outros Barbalongas?",a="Ele compartilha o nome de seu clã com diversos outros anões proeminentes pelos Reinos do Leste, como o piloto de máquinas de cerco Piloto Barbalonga de Altaforja, embora se concentre estritamente na ferraria.",al={"família de furen","clã barbalonga","parente do piloto barbalonga"}},{q="Por que os guerreiros procuram Furen Barbalonga?",a="Guerreiros que demonstraram sua proeza marcial básica são encaminhados a Furen para obter armaduras pesadas e duráveis, capazes de suportar o combate na linha de frente contra ameaças mais letais.",al={"por que guerreiros visitam furen","missão de guerreiro distrito dos anões","furen instrutor de guerreiros"}}},fx={["269e0799"]={q="De que lado está Furen Barbalonga?",a="Furen Barbalonga é um membro leal da Aliança, exercendo seu ofício no movimentado Distrito dos Anões em Ventobravo. Trabalhando em conjunto com seus parentes de Altaforja, colegas ferreiros e o clã Lançatroz, ele dedica seu trabalho artesanal para equipar os defensores da Aliança.",al={"facção de furen barbalonga","furen barbalonga aliança","a quem furen barbalonga serve"}},d8add91c={q="O que Furen Barbalonga quer?",a="Furen busca materiais raros e aliados capazes para criar armaduras excepcionais, especialmente para guerreiros promissores que buscam equipamentos resistentes, como malhas temperadas no fogo. Ele também trabalha para cumprir contratos militares cruciais, incluindo pedidos especializados para a Guarda de Lançatroz.",al={"o que furen quer","motivo de furen barbalonga","objetivos de furen barbalonga"}},["316ead5d"]={q="Por que Furen Barbalonga está em Ventobravo?",a="Furen trabalha no Distrito dos Anões de Ventobravo, servindo como uma conexão vital entre o artesanato anão e as necessidades marciais da capital humana. Aqui, perto das grandes forjas da cidade, ele pode colaborar com aprendizes, mestres ferreiros e engenheiros gnomos enquanto fornece armaduras pesadas para os defensores da linha de frente.",al={"por que furen barbalonga está aqui","por que furen está em ventobravo","conhecimento sobre a localização de furen barbalonga"}}},fp="15,369,36.416.0,29.380.0,23.205.0,35.145.0,36.130.0,40.180.0,47.190.0,41.169.0"}
P.entries["npc:furl-scornbrow"] = {n="Férrano Escarnecenho",s="Férrano Escarnecenho é um vigia orc idoso posicionado na torre de vigia a noroeste de Monte Navalha. Não mais capaz de lutar na linha de frente devido à sua idade avançada, ele vigia os desfiladeiros vermelhos de Durotar e confecciona mochilas resistentes para jovens viajantes que partem pelas terras.",h="Férrano Escarnecenho é um vigia orc idoso posicionado na torre de vigia a noroeste de Monte Navalha.",kw={"carregue suas tralhas","durotar","férrano escarnecenho","vigia","orc","monte navalha","torre de vigia"},ang={["faction:Horde"]="Posicionado ao longo das cristas nos arredores de Monte Navalha, Férrano representa a vigilância necessária para proteger os assentamentos recém-criados de Durotar contra ameaças persistentes.",["race:Orc"]="Férrano personifica a crença órquica de que, mesmo quando a idade rouba a força marcial de um guerreiro, uma vida honrosa significa encontrar outra maneira de servir ao clã e à Horda."},sec={{t="Vigia da Crista",b="Empoleirado no alto da torre de vigia de madeira a noroeste de Monte Navalha, Férrano Escarnecenho mantém uma vigília silenciosa sobre as planícies centrais de Durotar. Nos tensos primeiros dias após a fundação de Orgrimmar, sentinelas como Férrano eram vitais para soar trompas de sinalização contra javatuscos hostis, centauros e invasores de Kul Tiraz. À medida que Durotar se estabilizou e Monte Navalha estabeleceu fronteiras mais firmes, as emergências tornaram-se mais raras, deixando a Férrano muitas horas tranquilas em seu posto."},{t="Um Par de Mãos Úteis",b="Férrano admite abertamente que seus ossos velhos e sua força decadente o tornam inútil em batalha, mas um orc não renuncia facilmente ao seu propósito. Em vez de ficar ocioso, ele põe as mãos para trabalhar confeccionando sacos e mochilas de lona para novos recrutas que precisam carregar seus suprimentos. Em troca de fio grosso e materiais práticos, ele equipa aventureiros novatos que se aventuram para provar seu valor à Horda."}},faq={{q="Quem é Férrano Escarnecenho?",a="Férrano Escarnecenho é um vigia orc idoso posicionado na torre de vigia empoleirada no topo dos penhascos a noroeste de Monte Navalha. Incapaz de servir como guerreiro de linha de frente devido à idade, ele vigia o horizonte em busca de perigos e confecciona bolsas para jovens viajantes.",al={"quem é férrano","história de férrano escarnecenho","férrano em monte navalha"}},{q="Qual é o papel de Férrano em Durotar?",a="Ele opera a torre da trompa de sinalização, vigiando invasores que se aproximam de Monte Navalha. Como Durotar tornou-se cada vez mais segura sob o controle da Horda, ele soa o alarme com muito menos frequência, dedicando seu tempo livre para ajudar os novos recrutas a organizar seus equipamentos.",al={"o que férrano faz","propósito de férrano"}},{q="Por que Férrano pede materiais aos viajantes?",a="Férrano acredita que cada membro da Horda deve carregar suas tralhas, independentemente das circunstâncias. Como não pode mais lutar, ele costura mochilas de viagem práticas para ajudar guerreiros novatos, pedindo apenas materiais básicos como fio grosso para concluir o trabalho.",al={"história da missão carregue suas tralhas","por que férrano quer fio"}}},fx={["1ce1cc0b"]={q="De que lado está Férrano Escarnecenho?",a="Férrano Escarnecenho apoia firmemente a Horda. Posicionado no alto do Monte Navalha, ele vigia Durotar para proteger o jovem reino orc de potenciais invasores e ajuda viajantes que servem ao Chefe Guerreiro.",al={"facção de férrano escarnecenho","férrano escarnecenho horda","férrano é da horda"}}},fp="14,282,21.468.0,22.410.0,22.248.0,31.249.0,42.251.0"}
P.entries["npc:gaerolas-talvethren"] = {n="Garyol Talvethren",s="Garyol Talvethren é um sentinela elfo noturno que vigia as ruínas de Vilarejo Brisastral em Teldrassil. Nomeado protetor dos druidas Adormecidos, ele busca ajuda para enfrentar os agressivos fúrbolgs e a corrupção sombria que perturba os galhos.",h="Garyol Talvethren é um sentinela elfo noturno que vigia as ruínas de Vilarejo Brisastral em Teldrassil.",kw={"uma leve brisa","garyol talvethren","corrupção masca-pinho","vilarejo brisastral","teldrassil","os adormecidos"},ang={["class:Druid"]="O dever de Garyol como guardião dos druidas adormecidos faz com que ajudar em seus esforços seja uma questão pessoal de proteger companheiros praticantes do Círculo Cenariano.",["race:NightElf"]="Para os jovens elfos noturnos que partem de Dolanaar, ajudar Garyol oferece um vislumbre preocupante de quão profundamente a mácula penetrou nos galhos sagrados de Teldrassil."},sec={{t="Guardião dos Adormecidos",b="Posicionado em meio ao conturbado assentamento de Vilarejo Brisastral, Garyol Talvethren carrega o solene fardo de proteger os druidas Adormecidos que descansam em comunhão com o Sonho Esmeralda. Sua vigilância tornou-se tensa à medida que uma corrupção não natural rasteja pela floresta, desestabilizando o equilíbrio de Teldrassil."},{t="A Ameaça Pinheiro Torcido",b="Garyol orienta os viajantes a conterem a tribo de fúrbolgs Gnarlpine, cujas mentes caíram na loucura e na selvageria. Ao investigar a mácula que se espalha a partir de seus xamãs e descobrir as raízes de sua aflição, ele espera preservar a santidade que ainda resta no leste de Teldrassil."}},faq={{q="Quem é Garyol Talvethren?",a="Ele é um defensor elfo noturno posicionado em Vilarejo Brisastral, encarregado de proteger os druidas adormecidos e investigar a estranha corrupção que afeta a região.",al={"garyol","quem é garyol","papel de garyol"}},{q="Onde posso encontrar Garyol Talvethren?",a="Ele está localizado em Vilarejo Brisastral, nos galhos a leste de Teldrassil, a leste de Dolanaar.",al={"localização de garyol","onde fica garyol talvethren","encontrar garyol"}},{q="Quem são 'os Adormecidos' que Garyol protege?",a="Os Adormecidos referem-se aos druidas elfos noturnos que entraram em longos sonos em covis e santuários para percorrer o Sonho Esmeralda, deixando seus corpos vulneráveis a danos físicos.",al={"os adormecidos","quem são os adormecidos","druidas adormecidos"}},{q="Com quais ameaças Garyol está preocupado?",a="Ele está profundamente preocupado com a corrupção que assola a fauna local e com a hostilidade repentina e ensandecida da tribo de fúrbolgs Gnarlpine.",al={"ameaças de vilarejo brisastral","missões de garyol","problemas com gnarlpine"}}},fx={["52ffd6bd"]={q="De que lado está Garyol Talvethren?",a="Garyol Talvethren apoia firmemente os elfos noturnos de Darnassus e a Aliança. Como guardião juramentado dos druidas adormecidos que descansam no Vilarejo Brisastral, sua lealdade pertence ao Círculo Cenariano, a seu povo e à defesa de Teldrassil.",al={"facção de garyol","a quem garyol serve","lealdade de garyol"}},["436c9e7a"]={q="O que Garyol Talvethren quer?",a="Garyol quer proteger os druidas adormecidos das forças corruptoras que invadem o Vilarejo Brisastral. Ele busca sua ajuda para investigar a praga preocupante que se espalha pela área e erradicar a agressão dos furbolgs Gnarlpine corrompidos.",al={"objetivo de garyol","o que garyol está tentando fazer","propósito de garyol"}},["9c3b08f8"]={q="Por que Garyol Talvethren está aqui?",a="Garyol permanece estacionado no Vilarejo Brisastral porque é o protetor designado dos Adormecidos. Enquanto os druidas comungam no Sonho Esmeralda, eles ficam completamente vulneráveis a perigos físicos, deixando Garyol de guarda contra qualquer ameaça externa.",al={"por que garyol está no vilarejo brisastral","motivo de garyol estar aqui","por que garyol talvethren está aqui"}}},fp="19,256,24.310.0,20.292.0,27.169.0,37.91.0,46.185.0,41.136.0"}
P.entries["npc:gakin-the-darkbinder"] = {n="Gakin, o Neromante",s="Gakin, o Neromante é um mestre bruxo que atua clandestinamente nas profundezas sob a taverna O Cordeiro Imolado, no Distrito dos Magos de Ventobravo. Ele instrui aspirantes da Aliança nas artes sombrias, testando a determinação deles antes de iniciar rituais para evocar e vincular demônios de outros mundos ao seu serviço.",h="Gakin, o Neromante é um mestre bruxo que atua clandestinamente nas profundezas sob a taverna O Cordeiro...",kw={"neromante","gakin","distrito dos magos","slaughtered lamb","sucubo","surena caledon","voidwalker","bruxo"},ang={["class:Warlock"]="Gakin é um mentor vital para bruxos humanos e gnomos, oferecendo missões de classe cruciais para dominar os rituais de voidwalker e súcubo nas criptas de Ventobravo.",["faction:Alliance"]="Operando secretamente sob a capital, o coven de Gakin demonstra os compromissos pragmáticos e tomados pelas sombras firmados no coração da Aliança."},sec={{t="Um Ponto de Encontro Secreto",b="Enquanto os magos de Ventobravo praticam abertamente em seus santuários imponentes, os praticantes da sombra e do caos vil devem habitar onde olhares curiosos não alcançam. Escondido sob o salão de O Cordeiro Imolado há um porão úmido semelhante a uma cripta, equipado com círculos de evocação e tomos sombrios. Gakin atua como a âncora deste conclave secreto, garantindo que jovens bruxos aprendam disciplina e contenção antes de libertar horrores que não conseguem controlar."},{t="Mestre dos Demônios",b="A perícia de Gakin reside na demonologia e em rituais de vinculação. Os iniciados que chamam sua atenção são enviados por todo o reino para adquirir relíquias e ingredientes raros — desde talismãs de pedra-sangrenta roubados até madeira corrupta das florestas sombrias. Quando os reagentes são reunidos, Gakin supervisiona rituais no círculo de evocação da cripta, forçando os novatos a subjugar voidwalkers e súcubos em testes de força de vontade de vida ou morte."},{t="Traições e Pontas Soltas",b="Nem todos os alunos de Gakin permanecem obedientes. Uma ex-aprendiz, Surena Caledon, fugiu com uma valiosa Gargantilha de Pedra-sangrenta, escapando para as terras selvagens. Tais traições internas ameaçam expor o círculo de bruxos aos guardas da cidade, levando Gakin a enviar seguidores leais para recuperar artefatos perdidos e eliminar pontas soltas antes que as autoridades percebam."}},faq={{q="Onde posso encontrar Gakin, o Neromante?",a="Gakin fica nas profundezas sob a taverna O Cordeiro Imolado, no Distrito dos Magos de Ventobravo. Entre na taverna, encontre a rampa descendente nos fundos e desça pelos túneis de pedra até chegar ao círculo de evocação na cripta mais baixa.",al={"onde fica gakin","localizacao de gakin","porao do cordeiro imolado"}},{q="O que faz Gakin, o Neromante?",a="Ele atua como um importante mentor e concedente de missões de bruxo para personagens da Aliança. Ele testa novatos enviando-os em provações por toda Azeroth e ensinando-os a evocar e vincular demônios como o Voidwalker e o Succubus.",al={"o que gakin faz","papel de gakin","missoes de gakin"}},{q="Por que bruxos são permitidos sob O Cordeiro Imolado?",a="A magia demoníaca é proibida e vista com extrema desconfiança em Ventobravo. Os praticantes sob O Cordeiro Imolado operam em estrito sigilo, tolerados apenas como um recurso clandestino e perigoso, mantidos ocultos dos guardas e dos cidadãos da cidade.",al={"por que bruxos sao permitidos","bruxos sao legais em ventobravo","historia do cordeiro imolado"}},{q="Quem é Surena Caledon?",a="Surena Caledon foi uma ex-aluna de Gakin que roubou uma poderosa Gargantilha de Pedra-sangrenta dele. Sua traição coloca em risco a ordem secreta, levando Gakin a encarregar bruxos de rastreá-la.",al={"surena caledon","aluno de gakin","quem roubou de gakin"}},{q="Quais demônios Gakin ajuda a evocar?",a="Gakin supervisiona os rituais de vinculação para Voidwalkers e Succubi, orientando os bruxos a atrair as criaturas para o círculo subterrâneo e subjugá-las.",al={"demonios de gakin","gakin voidwalker","gakin sucubo"}},{q="Quem é Strahad e por que Gakin o menciona?",a="Strahad Farsan é um bruxo experiente que reside nas colinas de Vila Catraca, em Kalimdor. Quando um estudante avança além dos rituais fundamentais de vinculação de Gakin, ele o envia pelo mar para continuar seus estudos mais sombrios com Strahad.",al={"strahad","procurando strahad","para onde gakin me envia depois"}}},fx={["5c1d997e"]={q="Quem é Gakin, o Neromante?",a="Gakin, o Neromante é um poderoso Bruxo humano que se esconde nas profundezas das criptas abaixo de The Slaughtered Lamb, no Distrito dos Magos de Ventobravo. Longe dos olhares curiosos da guarda da cidade e do Kirin Tor, ele guia praticantes iniciantes das artes vis, instruindo-os nos ritos perigosos necessários para dobrar demônios de outros mundos à sua vontade.",al={"quem é gakin","identidade de gakin","lore de gakin"}},a5302178={q="De que lado está Gakin, o Neromante?",a="Gakin opera de forma vaga a serviço da Aliança, treinando praticantes Humanos e Gnomos para transformar forças demoníacas em armas para a sua própria sobrevivência. No entanto, como a maioria dos mestres das artes sombrias, suas lealdades finais permanecem protegidas, envoltas em sombras, segredos e na busca por conhecimento proibido, longe do escrutínio dos governantes de Ventobravo.",al={"gakin é da aliança","lealdade de gakin","a quem gakin serve"}},["503bf85b"]={q="O que Gakin, o Neromante quer?",a="Gakin busca expandir seu domínio sobre a magia vil e garantir que aspirantes a Bruxo possuam a determinação necessária para subjugar demônios maiores, em vez de serem consumidos por eles. Ele também trabalha silenciosamente para recuperar artefatos de poder perdidos, como uma Gargantilha de Pedra-sangrenta roubada por seu antigo aluno rebelde.",al={"o que gakin quer","objetivos de gakin","motivações de gakin"}}},fp="20,297,24.429.0,16.411.0,24.365.1,38.247.0,34.223.0,52.230.0,22.201.0,36.153.0,46.232.0"}
P.entries["npc:galgar"] = {n="Galgar",s="Galgar é um cozinheiro orc situado no Vale das Provações, em Durotar. Ele prepara mantimentos para jovens recrutas dando seus primeiros passos a serviço da Horda. Para ensinar aos recém-chegados os princípios básicos de coleta no deserto implacável, ele os encarrega de recolher sabras selvagens para seu prato característico.",h="Galgar é um cozinheiro orc situado no Vale das Provações, em Durotar.",kw={"surpresa de sabra","sabras","cozinheiro","durotar","galgar","recruta da horda","vale das provações"},ang={["profession:Cooking"]="Galgar personifica a culinária prática e rústica da Horda, aproveitando os recursos naturais esparsos de Durotar para manter os recrutas alimentados e prontos para a batalha.",["race:Orc"]="Para os jovens orcs que dão seus primeiros passos no Vale das Provações, cumprir uma tarefa para Galgar é um rito de passagem familiar antes de enfrentar ameaças mais ferozes da natureza."},sec={{t="Um Cozinheiro no Vale",b="Situado perto da fogueira de cozinha do Covil no Vale das Provações, Galgar fornece sustento para jovens orcs e trolls passando por seus ritos iniciais de passagem. Durotar é uma terra devastada vermelha, seca e implacável, onde cada pedaço de alimento precisa ser extraído da paisagem. Ao colocar guerreiros novatos para trabalhar colhendo frutos maduros de cactos, Galgar testa sua atenção e resiliência enquanto mantém sua cozinha abastecida."},{t="Surpresa de Sabra",b="A receita especial de Galgar é conhecida como Surpresa de Sabra. Embora ele reconheça abertamente que colher frutos espinhosos do deserto seja uma tarefa intencionalmente simples, feita para ambientar os recrutas recém-chegados à vida de aventureiros, o produto final permanece como uma ração básica para os aprendizes famintos. Até mesmo o guerreiro mais calejado da Horda precisa começar de algum lugar e, sob o olhar atento de Galgar, essa jornada tem início na coleta pelo deserto."}},faq={{q="Onde posso encontrar Galgar?",a="Galgar fica no Vale das Provações, o cânion inicial de orcs e trolls no sudoeste de Durotar. Ele está perto da fogueira central e da área de cozinha do lado de fora do Covil.",al={"localização de galgar","onde fica galgar","coordenadas de galgar"}},{q="O que Galgar pede para os aventureiros fazerem?",a="Ele pede que novos aventureiros colham sabras maduras dos cactos selvagens espalhados pelo Vale das Provações para poder preparar sua Surpresa de Sabra.",al={"missão de galgar","o que galgar quer"}},{q="Por que Galgar envia novos recrutas para colher frutas?",a="Galgar admite que a tarefa é intencionalmente simples. Ela serve como uma tarefa inicial fácil para combatentes novatos aprenderem o relevo do vale e praticarem a autossuficiência na natureza implacável de Durotar.",al={"por que sabras","teste de galgar"}},{q="O que é Surpresa de Sabra?",a="É a receita tradicional de Galgar, feita com sabras frescas colhidas da flora nativa do deserto de Durotar para alimentar recrutas novatos.",al={"o que é surpresa de sabra","comida de galgar"}}},fx={["115dfff8"]={q="Quem é Galgar?",a="Galgar é um cozinheiro orc estacionado no Vale das Provações em Durotar. Em vez de treinar guerreiros em combate bruto, ele apoia o assentamento preparando provisões saudáveis para os jovens recrutas, mais notavelmente sua conhecida Surpresa de Sabra.",al={"quem é galgar","conhecimento sobre galgar","quem galgar"}},["7f3ad096"]={q="De que lado está Galgar?",a="Galgar é leal à Horda de Thrall. Servindo dentro do Vale das Provações, ele cuida diretamente dos jovens orcs e trolls que estão dando seus primeiros passos a serviço de Durotar.",al={"facção de galgar","galgar é da horda","lealdade de galgar"}},d4d57a6c={q="O que Galgar quer?",a="Galgar quer ingredientes frescos — principalmente as frutas de sabra maduras que crescem por todo o vale árido — para que ele possa preparar porções de sua Surpresa de Sabra característica para manter os jovens recrutas alimentados e energizados.",al={"do que galgar precisa","objetivo de galgar","galgar quer"}},["50f967f0"]={q="Por que Galgar está aqui no Vale das Provações?",a="Galgar está estacionado no Vale das Provações para apoiar a cozinha do acampamento. Enquanto os treinadores instruem os aspirantes na arte da guerra, Galgar garante que o local permaneça abastecido com comida e apresenta aos recém-chegados o trabalho de campo básico.",al={"por que galgar está aqui","motivo de galgar estar no vale das provações","por que galgar está em durotar"}},["2e1d8215"]={q="Por que Galgar é famoso?",a="Galgar é conhecido por todo o Vale das Provações por sua famosa receita, a Surpresa de Sabra. Quase todo jovem recruta que passa por The Den experimenta sua comida enquanto realiza tarefas introdutórias para ele.",al={"galgar é famoso","pelo que galgar é conhecido","fama de galgar"}}},fp="6,294,20.415.0,21.418.0,24.177.0,39.157.0,48.211.0,30.139.0"}
P.entries["npc:gan-rul-bloodeye"] = {n="Gan'rul Bloodeye",s="Gan'rul Bloodeye é um instrutor bruxo orc veterano que reside profundamente na caverna escura da Antro das Sombras em Orgrimmar. Escondido do olhar atento da cidade acima, ele inicia os bruxos da Nova Horda em ritos demoníacos mais sombrios. Sob sua instrução, os iniciantes aprendem a dobrar entidades de outro mundo, como andadores do vazio e súcubos, à sua vontade.",h="Gan'rul Bloodeye é um instrutor bruxo orc veterano que reside profundamente na caverna escura da Antro das...",kw={"bloodeye","antro das sombras","gan'rul","orgrimmar","súcubo","instrutor","andador do vazio","bruxo"},ang={["class:Warlock"]="Para bruxos que buscam conhecimento proibido, Gan'rul é um mentor vital em Kalimdor, fornecendo o conhecimento e os testes necessários para vincular andadores do vazio e súcubos.",["faction:Horde"]="Gan'rul personifica a posição precária da magia vil na Horda de Thrall — utilizada para força militar, mas confinada aos recessos subterrâneos da capital."},sec={{t="Um Mestre nas Sombras",b="Embora o Chefe Guerreiro Thrall tolere a presença de bruxos na Nova Horda, suas artes sombrias não são bem-vindas à luz do sol de Durotar. Gan'rul Bloodeye faz seu lar na Antro das Sombras, um refúgio subterrâneo sob Orgrimmar onde tecelões das sombras, ladinos e conjuradores vis podem estudar sem serem molestados. Deste poleiro subterrâneo, Gan'rul serve como um tutor principal para praticantes em ascensão da magia vil."},{t="Vinculando a Distorção",b="O dever principal de Gan'rul é supervisionar os perigosos rituais de invocação exigidos de bruxos ambiciosos. Praticantes que buscam vincular demônios maiores — como o resiliente andador do vazio ou a sedutora súcubo — devem consultar Gan'rul para obter componentes rituais e aprender os encantamentos precisos necessários para dominar a criatura invocada antes que ela consuma seu mestre."}},faq={{q="Quem é Gan'rul Bloodeye?",a="Gan'rul Bloodeye é um instrutor bruxo orc estacionado em Orgrimmar. Ele orienta bruxos iniciantes e intermediários da Nova Horda, ensinando-os como invocar e vincular demônios da Twisting Nether.",al={"gan'rul bloodeye","quem é ganrul","papel de ganrul bloodeye"}},{q="Onde posso encontrar Gan'rul Bloodeye?",a="Ele está localizado na Antro das Sombras, a rede de cavernas subterrâneas escondida sob Orgrimmar. Ele fica ao lado de outros praticantes das sombras, longe das vias principais da cidade.",al={"localização de ganrul","onde está gan'rul bloodeye","onde está o instrutor da antro das sombras"}},{q="Por que os bruxos estão escondidos na Antro das Sombras?",a="O Chefe Guerreiro Thrall e a sociedade xamânica da Nova Horda desconfiam fortemente da magia vil e da corrupção demoníaca após a escravização passada dos orcs. Bruxos são permitidos dentro da Nova Horda estritamente por sua utilidade, mas sua prática é relegada às sombras para evitar distúrbios cívicos.",al={"por que nas cavernas","por que esconder os bruxos","lore da antro das sombras"}},{q="Quais demônios Gan'rul ajuda a invocar?",a="Gan'rul guia os bruxos através dos rituais necessários para invocar e subjugar tanto o andador do vazio quanto a súcubo. Completar suas tarefas prova que o invocador possui a força de vontade necessária para controlar esses seres vis.",al={"demônios que ganrul ensina","missões de demônios de ganrul","instrutor de andador do vazio e súcubo"}},{q="Gan'rul tem algum parente conhecido?",a="Ele compartilha um sobrenome com Halga Bloodeye, embora seu relacionamento preciso não esteja documentado abertamente.",al={"parentes de gan'rul","parente halga bloodeye"}},{q="Quem é Strahad, a quem Gan'rul menciona?",a="Strahad Farsan é um bruxo realizado que reside nos Sertões, perto das colinas de Vila Catraca. Gan'rul eventualmente envia estudantes promissores a Strahad para instruções mais avançadas e desafios maiores.",al={"seeking strahad","quem é strahad","missão de strahad"}}},fx={["11e29292"]={q="De que lado está Gan'rul Bloodeye?",a="Gan'rul Bloodeye serve à Horda, treinando praticantes de magia sombria sob a capital de Thrall. Embora os bruxos sejam vistos com profunda suspeita pela liderança xamânica, Gan'rul alinha seu ofício arcano à sobrevivência e força da Horda, orientando aqueles dispostos a aproveitar os poderes vis em sua defesa.",al={"facção de gan'rul bloodeye","lealdade de gan'rul","a quem gan'rul serve"}},["67b7b1ae"]={q="O que Gan'rul Bloodeye quer?",a="Gan'rul busca expandir as fileiras de bruxos capazes da Horda, testando iniciantes e ensinando-lhes o domínio sobre o Nether. Ele exige disciplina e foco oculto, guiando aprendizes a conjurar entidades demoníacas perigosas, como andadores do vácuo e súcubos, para que a magia sombria sirva como uma arma obediente em vez de uma ameaça consumidora.",al={"objetivos de gan'rul","o que gan'rul quer","propósito de gan'rul"}}},fp="16,344,23.407.0,18.364.0,24.187.0,34.188.0,47.285.0,37.219.0,35.100.0,38.198.0"}
P.entries["npc:gann-stonespire"] = {n="Gann Agulha de Pedra",s="Gann Agulha de Pedra é um nômade tauren ressentido que vaga pelas estradas dos Sertões Meridionais perto de Bael Modan. Expulso das terras de caça ancestrais de sua tribo por escavadores anões, ele busca retaliação contra o avanço do sítio de escavação.",h="Gann Agulha de Pedra é um nômade tauren ressentido que vaga pelas estradas dos Sertões Meridionais perto de...",kw={"bael modan","bael'dun","gann agulha de pedra","prospector khazgorm","sertões meridionais","agulha de pedra"},ang={["faction:Horde"]="Ajudar Gann oferece à Horda uma oportunidade tática vital para conter o expansionismo da Aliança entrincheirado nos Sertões Meridionais.",["race:Tauren"]="O sofrimento de Gann representa a luta mais ampla dos taurens nômades, cujas terras ancestrais e solos sagrados são repetidamente profanados por expedições estrangeiras da Aliança."},sec={{t="Deslocado de Bael Modan",b="Antes de a expedição anã chegar de Altaforja para erguer a fortaleza de Bael Modan, as terras ao redor serviam como território ancestral e campos de caça para a tribo de Gann Agulha de Pedra. Os mineradores anões expulsaram os taurens nativos de seu solo com picaretas, armas de fogo e maquinário pesado, recusando propostas de paz. Acampando agora ao longo da estrada empoeirada dos Sertões Meridionais, Gann se recusa a entregar sua herança em silêncio, reunindo viajantes para revidar contra os escavadores."},{t="Reconquista e sabotagem",b="Reconhecendo que a diplomacia pacífica falhou por completo, Gann orienta agentes da Horda a quebrar o controle dos anões sobre o sítio de escavação. Sua retaliação tem como alvo os principais líderes da expedição, principalmente o Prospector Khazgorm, antes de reaproveitar a pólvora e os artefatos bélicos dos anões em uma carga explosiva. Ao detonar a engenhoca diretamente sob a máquina voadora dos anões, Gann visa paralisar a vantagem tecnológica deles e recuperar a honra de seu povo deslocado."}},faq={{q="Quem é Gann Agulha de Pedra?",a="Gann Agulha de Pedra é um guerreiro tauren cuja tribo outrora habitava as terras agora ocupadas pela fortaleza anã de Bael Modan. Tendo sido deslocado quando os anões estabeleceram seu sítio de escavação, ele agora espera à beira da estrada nos Sertões Meridionais em busca de vingança e da reconquista da terra natal de seu povo.",al={"quem é gann","história de gann agulha de pedra","tauren perto de bael modan"}},{q="Por que Gann está lutando contra os anões de Bael Modan?",a="A expedição anã de Bael'dun chegou aos Sertões Meridionais e expulsou à força os taurens locais de seus campos de caça ancestrais para construir sua fortaleza de escavação. Depois que os anões rejeitaram todos os esforços diplomáticos, Gann decidiu desmantelar a operação deles pela força.",al={"por que gann odeia anões","por que atacar bael modan","conflito de gann em bael modan"}},{q="Qual é o plano de Gann contra a escavação?",a="Gann primeiro encomenda a morte dos feitores anões, incluindo o Prospector Khazgorm, para confiscar registros da escavação. Usando projéteis e suprimentos de detonação anões roubados, ele então orquestra a montagem de uma bomba para destruir a máquina voadora da expedição e desestabilizar a supremacia tecnológica deles.",al={"plano de vingança de gann","o que gann faz","bomba de bael modan"}},{q="Onde Gann Agulha de Pedra monta seu acampamento?",a="Ele pode ser encontrado vagando pela estrada a oeste de Bael Modan, nos Sertões Meridionais, nos arredores do perímetro do sítio de escavação.",al={"onde fica gann","localização de gann agulha de pedra"}}},fx={["60933082"]={q="De que lado está Gann Agulha de Pedra?",a="Gann apoia a Horda e seus companheiros tauren. Ele busca ajuda de campeões da Horda que passam pelos Sertões Meridionais para contra-atacar os anões de Bael'dun que invadem as terras sagradas de seu povo.",al={"gann agulha de pedra é da horda","facção de gann agulha de pedra","por quem gann luta"}},["59c620b8"]={q="A quem Gann Agulha de Pedra está ligado?",a="Gann pertence a uma tribo tauren cujo lar ancestral abrangia as terras agora tomadas por Bael Modan. Ele age em nome de seu povo deslocado, que foi expulso quando a escavação anã começou.",al={"tribo de gann agulha de pedra","quem é o povo de gann","clã de gann agulha de pedra"}}},fp="15,239,25.485.0,24.466.1,23.308.0,47.289.0,43.297.1,41.134.0"}
P.entries["npc:gar-thok"] = {n="Gar'Thok",s="Gar'Thok é um guerreiro orc veterano e comandante de posto avançado alocado em Monte Navalha, em Durotar. Tendo sobrevivido aos desembarques iniciais de Kul Tiraz na costa de Durotar, ele agora coordena a defesa local contra invasores humanos e ameaças nativas. Ele orienta jovens recrutas da Horda recém-saídos do Vale das Provações a protegerem os ermos vermelhos do novo lar.",h="Gar'Thok é um guerreiro orc veterano e comandante de posto avançado alocado em Monte Navalha, em Durotar.",kw={"daelin","durotar","gar'thok","garthok","kul tiraz","nazgrel","monte navalha","rexxar","tiragarde"},ang={["class:Warrior"]="Como um comandante de linha de frente que sobreviveu a uma brutal emboscada naval, Gar'Thok espera vigor marcial e obediência sem hesitação dos outros guerreiros.",["faction:Horde"]="Gar'Thok garante que novos recrutas de todas as raças da Horda compreendam a precariedade de seu novo território, instruindo-os a repelir invasores remanescentes da Aliança.",["race:Orc"]="Para os jovens orcs que deixam o Vale das Provações, Gar'Thok representa a disciplina rígida e implacável da geração de veteranos que sangrou para conquistar Durotar."},sec={{t="Um Veterano dos Ermos Vermelhos",b="Após a Terceira Guerra, Gar'Thok marchou para Durotar sob o comando do Chefe Guerreiro Thrall e serviu como tenente sob Nazgrel durante os primeiros dias de construção do novo lar. Quando o meio-ogro errante Rexxar chegou pela primeira vez a Durotar, foi Gar'Thok quem o alertou sobre os agressivos quilboars saqueando seu perímetro, recrutando o mestre das feras para proteger o frágil novo assentamento."},{t="Sobrevivendo à Invasão do Almirante",b="A determinação de Gar'Thok foi testada quando a frota de Kul Tiraz do Grande Almirante Daelin Proudmore desembarcou ao longo da costa leste de Durotar. Estacionado em um posto de vigia distante, Gar'Thok viu sua guarnição ser subjugada e brutalmente massacrada por fuzileiros navais. Embora suas forças tenham sido dizimadas, Gar'Thok sobreviveu ao ataque fulminante. A memória daquele ataque surpresa consolidou sua vigilância contra os fuzileiros sobreviventes que ainda ocupam a Bastilha Tiragarde e os naufrágios costeiros."},{t="Defesa de Monte Navalha",b="Hoje, Gar'Thok supervisiona a defesa militar da região central de Durotar a partir do quartel de Monte Navalha. Ele não perde tempo com cordialidades, incumbindo imediatamente novos guerreiros, xamãs e batedores da Horda de eliminar remanescentes hostis de kultirenos, recuperar suprimentos resgatados e reaver ordens militares deixadas nas ruínas costeiras. Para ele, a segurança de Durotar está longe de ser garantida, exigindo pressão constante contra qualquer um que questione o direito da Horda a esta terra."}},faq={{q="Quem é Gar'Thok?",a="Gar'Thok é um oficial orc alocado em Monte Navalha que organiza a resposta militar local contra forças hostis em Durotar. Ele é um veterano da Terceira Guerra que serviu sob Nazgrel durante a fundação de Orgrimmar.",al={"história de garthok","quem é garthok","comandante de monte navalha"}},{q="Onde Gar'Thok lutou antes de vir para Monte Navalha?",a="Ele serviu como tenente de Nazgrel em um posto avançado de fronteira em Durotar, onde trabalhou com Rexxar para conter as primeiras incursões de quilboars, até que marinheiros de Kul Tiraz invadiram o posto e mataram seus homens.",al={"passado de garthok","garthok monte hyjal","história de garthok"}},{q="Por que Gar'Thok odeia tanto os humanos em Durotar?",a="Durante a invasão liderada pelo Grande Almirante Daelin Proudmore, marinheiros de Kul Tiraz emboscaram o posto avançado de Gar'Thok na costa, massacrando seus homens. Ele sobreviveu ao ataque e continua empenhado em erradicar os acampamentos restantes de fuzileiros.",al={"por que garthok odeia kul tiraz","garthok humanos","bastilha tiragarde garthok"}},{q="Quais ameaças Gar'Thok envia aventureiros para combater?",a="Gar'Thok envia recrutas para combater os hostis marinheiros de Kul Tiraz entrincheirados na Bastilha Tiragarde, recuperar suprimentos dos naufrágios costeiros, repelir quilboars invasores e descobrir quaisquer ordens deixadas para trás por comandantes humanos.",al={"missões de garthok","o que garthok quer","missões de monte navalha"}},{q="Qual é a sua relação com Nazgrel e Thrall?",a="Gar'Thok serviu como um tenente de confiança sob Nazgrel durante as expedições de colonização iniciais em Durotar, operando diretamente sob a autoridade do Chefe Guerreiro Thrall para proteger as fronteiras do território recém-reivindicado.",al={"garthok nazgrel","garthok thrall","posto de garthok"}},{q="Onde Gar'Thok pode ser encontrado?",a="Gar'Thok fica do lado de fora da torre de vigia principal e do quartel em Monte Navalha, o assentamento central de Durotar situado ao sul de Orgrimmar.",al={"localização de garthok","onde fica garthok","encontrar garthok"}}},fx={["61b8b646"]={q="De que lado está Gar'Thok?",a="Gar'Thok é totalmente leal à Horda e ao Chefe Guerreiro Thrall. Estacionado em Durotar sob o comando de Nazgrel, ele trabalha incansavelmente para defender a pátria orc nascente e garantir que os guerreiros recém-chegados estejam preparados para proteger as fronteiras da Horda.",al={"facção de gar'thok","gar'thok é da horda","a quem garthok serve"}},["7b499593"]={q="O que Gar'Thok quer?",a="Gar'Thok quer Durotar firmemente assegurada contra todas as ameaças. Tendo visto seu posto avançado ser massacrado por invasores de Kul Tiraz, ele busca vingança contra os marinheiros humanos restantes na costa e exige a supressão dos quilboar invasores que perturbam o assentamento.",al={"objetivo de gar'thok","o que garthok quer","motivos de garthok"}},["007248aa"]={q="Por que Gar'Thok está aqui?",a="Após a devastação de seu posto avançado costeiro pelas forças de Kul Tiraz, Gar'Thok assumiu um posto em Monte Navalha. A partir deste assentamento central, ele organiza a defesa de Durotar e direciona campeões da Horda em ascensão contra incursões hostis.",al={"por que gar'thok está em monte navalha","por que garthok está aqui","dever de garthok em monte navalha"}}},fp="8,352,27.382.0,32.468.0,21.473.0,16.219.0,53.185.0,53.239.0,53.219.0,49.219.0,28.133.0"}
P.entries["npc:gart-mistrunner"] = {n="Gart Corre com a Névoa",s="Gart Corre com a Névoa é o instrutor de druidas residente situado na Aldeia Narache, na Chapada Nuvem Vermelha. Ele acolhe os taurens novatos chamados pela Mãe Terra e os guia através de seus primeiros ritos de magia da natureza.",h="Gart Corre com a Névoa é o instrutor de druidas residente situado na Aldeia Narache, na Chapada Nuvem...",kw={"aldeia narache","instrutor de druidas","gart corre com a névoa","corre com a névoa","mulgore","chapada nuvem vermelha","druida tauren"},ang={["class:Druid"]="Para os druidas taurens, Gart Corre com a Névoa é o primeiríssimo mestre a moldar sua comunhão com a natureza e as dádivas da Mãe Terra.",["race:Tauren"]="Gart representa o ressurgimento das antigas tradições druídicas dos Shu'halo, transmitindo a sabedoria ancestral aos jovens da Aldeia Narache."},sec={{t="Mentor da Chapada Nuvem Vermelha",b="Vigiando a Aldeia Narache, Gart Corre com a Névoa representa a antiga senda druídica reacendida entre os Shu'halo. Novos druidas taurens são direcionados diretamente a Gart ao darem seus primeiros passos na Chapada Nuvem Vermelha, muitas vezes carregando um Bilhete verdejante que os confia aos seus cuidados. Por meio de sua orientação paciente, jovens praticantes aprendem a comungar com o mundo natural, recorrendo aos poderes restauradores da natureza e ao resplendor lunar de Mu'sha para curar seus aliados e abater ameaças à terra."}},faq={{q="Quem é Gart Corre com a Névoa?",a="Gart Corre com a Névoa é um instrutor de druidas tauren localizado na Aldeia Narache, na Chapada Nuvem Vermelha de Mulgore. Ele instrui druidas taurens novatos em seus feitiços e ritos iniciais.",al={"quem é gart","história de gart corre com a névoa","gart corre com a névoa"}},{q="Quais feitiços ele ensina aos druidas recém-despertos?",a="Gart introduz os iniciantes às habilidades essenciais da natureza, ensinando feitiços de cura iniciais, como Toque de Cura, e magia ofensiva da natureza, como Fogo Lunar.",al={"o que gart ensina","treinamento de gart corre com a névoa","feitiços de druida aldeia narache"}},{q="Qual é a ligação dele com o clã Corre com a Névoa?",a="Corre com a Névoa é simplesmente o sobrenome de Gart. Nenhuma história descreve uma tribo Corre com a Névoa ou diz mais sobre seus parentes; ele é conhecido apenas como o instrutor de druidas da Aldeia Narache.",al={"clã corre com a névoa","quem são os corre com a névoa"}}},fx={["4b2be6b9"]={q="Por que Gart Corre com a Névoa está aqui?",a="Gart reside na Aldeia Narache para instruir tauren novatos que ouvem o chamado da natureza. Como instrutor de druidas na Chapada Nuvem Vermelha, ele apresenta aos iniciantes recém-despertos os ensinamentos da natureza, orientando seu crescimento espiritual e marcial inicial antes que se aventurem pelas planícies mais amplas de Mulgore.",al={"por que gart está na aldeia narache","propósito de gart corre com a névoa","o que gart corre com a névoa está fazendo aqui"}},["8def0ffd"]={q="O que Gart Corre com a Névoa quer?",a="Gart busca promover a harmonia entre os tauren e a Mãe Terra ao treinar novos druidas no equilíbrio natural. Ele deseja ver jovens iniciantes dominando ritos iniciais, como a cura rejuvenescedora e encantamentos de equilíbrio, preparando-os para curar a terra e defender sua tribo contra ameaças invasoras.",al={"objetivos de gart corre com a névoa","o que gart quer","motivações de gart corre com a névoa"}},fd7992e7={q="De que lado está Gart Corre com a Névoa?",a="Gart Corre com a Névoa é dedicado às tribos tauren e apoia a Horda. Estacionado no coração da Chapada Nuvem Vermelha, na Aldeia Narache, ele trabalha em sua terra natal ancestral para salvaguardar as tradições tauren, nutrindo jovens praticantes que usam os dons da natureza para proteger a terra e servir ao seu povo.",al={"facção de gart corre com a névoa","a quem gart serve","gart corre com a névoa horda"}}},fp="15,206,28.505.0,23.168.0,48.150.0,46.160.0"}
P.entries["npc:gath-ilzogg"] = {n="Gath'Ilzogg",s="Gath'Ilzogg é o temível senhor da guerra orc da Rocha Negra que comanda a força de invasão que ocupa a Bastilha Mirante de Pedra nas Montanhas Cristarrubra. Sob sua liderança brutal, os orcs tomaram a fortaleza e lançaram ataques devastadores contra a cidade de Vila Plácida, o que lhe rendeu uma recompensa urgente emitida pelo desesperado magistrado local.",h="Gath'Ilzogg é o temível senhor da guerra orc da Rocha Negra que comanda a força de invasão que ocupa a...",kw={"rocha negra","gath'ilzogg","gathilzogg","vila plácida","morganth","singe","salomão","mirante de pedra","bastilha mirante de pedra"},ang={["faction:Alliance"]="Derrotar Gath'Ilzogg quebra a espinha dorsal da ofensiva da Rocha Negra que ameaça Vila Plácida e atende ao apelo desesperado do Magistrado Salomão.",["race:Orc"]="Gath'Ilzogg representa os velhos costumes belicistas do clã Rocha Negra sob a Horda Sombria, totalmente à parte da nova Horda de Thrall em Kalimdor."},sec={{t="O Flagelo de Mirante de Pedra",b="Gath'Ilzogg marchou para o norte a partir das Estepes Ardentes com ordens de garantir Cristarrubra para o clã Rocha Negra. Com o auxílio da vil feitiçaria do bruxo humano renegado Morganth, o bando de guerra de Gath'Ilzogg castigou os defensores da Bastilha Mirante de Pedra e tomou a posição elevada que domina toda a região. A partir deste reduto fortificado, ele supervisiona ataques agressivos aos vales e em direção à ponte de Vila Plácida, sufocando aos poucos o assentamento humano. Ele raramente luta sozinho, mantendo guardas de elite Rocha Negra e um feroz filhote de dragão negro chamado Singe por perto."},{t="Um Domínio Frágil",b="Apesar de sua conquista de Mirante de Pedra, a vitória de Gath'Ilzogg gerou novas complicações. Morganth logo se voltou contra seus antigos aliados orcs, erguendo um exército de gnolls Couro da Sombra sob o comando do Lieutenant Fangore, que atacam tanto patrulhas Rocha Negra quanto viajantes humanos. Ao mesmo tempo, o Magistrado Salomão colocou uma recompensa aberta pela cabeça do senhor da guerra, suplicando a quaisquer mercenários ou aventureiros da Aliança que escalem as muralhas da Bastilha Mirante de Pedra e deem um fim ao terror de Gath'Ilzogg antes que a cidade caia por completo."}},faq={{q="Quem é Gath'Ilzogg?",a="Gath'Ilzogg é um senhor da guerra orc pertencente ao clã Rocha Negra. Ele lidera a vanguarda que invadiu Cristarrubra e capturou com sucesso a Bastilha Mirante de Pedra da Aliança.",al={"história de gath'ilzogg","quem é gathilzogg","chefe rocha negra cristarrubra"}},{q="Onde Gath'Ilzogg pode ser encontrado?",a="Ele está entrincheirado no topo da Bastilha Mirante de Pedra, localizada nos penhascos orientais das Montanhas Cristarrubra.",al={"localização de gath'ilzogg","onde fica gathilzogg","encontrar gathilzogg"}},{q="Por que Gath'Ilzogg tem um filhote de dragão?",a="Gath'Ilzogg é acompanhado por um filhote de dragão negro chamado Singe, amplamente considerado um presente do Lord Victor Nefarius para recompensar o senhor da guerra por tomar com sucesso a Bastilha Mirante de Pedra.",al={"por que filhote ao lado de gathilzogg","dragão singe","filhote de dragão negro gathilzogg"}},{q="Por que há uma recompensa por sua cabeça?",a="O Magistrado Salomão de Vila Plácida emitiu uma recompensa de alta prioridade pela cabeça de Gath'Ilzogg porque os ataques constantes do senhor da guerra e a ocupação de Mirante de Pedra ameaçam diretamente Vila Plácida de destruição total.",al={"procura-se gath'ilzogg","quem quer a morte de gathilzogg","recompensa do magistrado salomão"}},{q="O que aconteceu entre Gath'Ilzogg e Morganth?",a="O bruxo humano Morganth inicialmente ajudou Gath'Ilzogg com magia sombria para conquistar Mirante de Pedra. No entanto, assim que a fortaleza caiu, Morganth traiu os orcs e reuniu um exército de gnolls Couro da Sombra para atacar tanto a humanidade quanto o clã Rocha Negra.",al={"aliança morganth gathilzogg","por que os gnolls atacam orcs","traição de morganth"}}},fx={["9f2c44f6"]={q="De que lado está Gath'Ilzogg?",a="Gath'Ilzogg é um senhor da guerra do clã Rocha Negra, leal à Horda Sombria enraizada na Montanha Rocha Negra. Ele e suas forças travam guerra ativa contra o Reino de Ventobravo, mostrando total hostilidade em relação à Aliança e a qualquer um que invada seu território conquistado.",al={"facção de gath'ilzogg","a quem gath'ilzogg serve","gath'ilzogg é rocha negra"}},["56c8e0ec"]={q="O que Gath'Ilzogg quer?",a="De sua fortaleza na Bastilha Mirante de Pedra, Gath'Ilzogg planeja a destruição de Vila Plácida e a conquista completa de Montanhas Cristarrubra. Ele direciona ataques contra assentamentos humanos e trabalha para expandir o domínio do clã Rocha Negra sobre as terras vizinhas.",al={"qual é o objetivo de gath'ilzogg","plano de gath'ilzogg","por que gath'ilzogg está atacando"}},d3a450f6={q="Por que Gath'Ilzogg está aqui?",a="Gath'Ilzogg liderou o ataque que subjugou os defensores da Aliança na Bastilha Mirante de Pedra. Tendo capturado a fortaleza, ele agora a utiliza como uma base de operações fortificada para atacar mais profundamente em Montanhas Cristarrubra e organizar ataques contra Vila Plácida.",al={"por que gath'ilzogg está em cristarrubra","por que gath'ilzogg está no mirante de pedra","gath'ilzogg mirante de pedra"}},d6829113={q="A quem Gath'Ilzogg está ligado?",a="Além de comandar os orcs Rocha Negra locais, Gath'Ilzogg formou uma vez uma aliança traiçoeira com o bruxo humano renegado Morganth para tomar a Bastilha Mirante de Pedra. Ele também comanda a cria Singe, uma criatura provavelmente concedida a ele pelo Lorde Victor Nefarius como recompensa por sua vitória.",al={"aliados de gath'ilzogg","quem trabalha com gath'ilzogg","conexões de gath'ilzogg"}},b07f2498={q="Por que Gath'Ilzogg é temido?",a="Gath'Ilzogg provou sua letalidade ao orquestrar com sucesso a queda da Bastilha Mirante de Pedra, esmagando a guarnição local da Aliança. O Magistrado Salomão o vê como a principal ameaça militar à sobrevivência de Vila Plácida, provocando uma recompensa severa pela cabeça do senhor da guerra.",al={"por que gath'ilzogg é perigoso","gath'ilzogg é famoso","reputação de gath'ilzogg"}}},fp="11,321,25.571.0,14.490.1,19.167.0,31.108.0,41.182.0,34.205.0,47.241.0"}
P.entries["npc:gaxim-rustfizzle"] = {n="Gaxim Deuxabu",s="Gaxim Deuxabu é um ambicioso estudioso e engenhoqueiro gnomo estabelecido em um pequeno acampamento da Aliança ao longo da Passagem Tramateia, na Cordilheira das Torres de Pedra. Como representante da Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, ele busca provar aos céticos elfos noturnos que o artifício avançado e a alquimia podem preservar seu reino florestal. Sua curiosidade científica é acompanhada por uma feroz vingança contra as operações destrutivas da Empreendimentos S.A.",h="Gaxim Deuxabu é um ambicioso estudioso e engenhoqueiro gnomo estabelecido em um pequeno acampamento da...",kw={"assembly","gaxim","gnomo","kaela","deuxabu","cordilheira das torres de pedra","empreendimentos s.a.","passagem tramateia","rochedo cortavento"},ang={["faction:Alliance"]="Instalado na perigosa Passagem Tramateia, Gaxim fornece missões vitais de reconhecimento, inteligência e sabotagem para conter as agressivas incursões industriais nas Torres de Pedra.",["profession:Engineering"]="Gaxim coloca os princípios da engenharia em prática no campo, planejando operações secretas e dispositivos táticos ajustados especificamente para neutralizar o maquinário rústico da Empreendimentos S.A.",["race:Gnome"]="Gaxim representa o melhor do orgulho acadêmico dos gnomos, demonstrando às culturas ancestrais de Kalimdor que engrenagens e reagentes podem salvar uma floresta tão bem quanto a magia da natureza.",["race:NightElf"]="Embora os tradicionalistas possam zombar de suas engenhocas barulhentas e frascos borbulhantes, Gaxim é um aliado leal que defende ativamente as fronteiras do Vale Gris e das Torres de Pedra contra a indústria dos goblins."},sec={{t="Um Emissário Científico",b="Enquanto os elfos noturnos tradicionalmente dependem do druidismo ancestral e da magia da natureza, Gaxim Deuxabu chegou às passagens escarpadas das Torres de Pedra para demonstrar uma perspectiva radicalmente diferente. Representando a Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, ele acredita genuinamente que mecanismos calculados e soluções químicas podem defender e restaurar a natureza selvagem de Kalimdor com a mesma eficácia que preces a Elune. Acampado ao lado da sentinela Kaela Umbralança na Passagem Tramateia, ele trabalha incansavelmente para convencer seus aliados altos e reclusos sobre os méritos ecológicos da engenharia."},{t="Sabotando as Serras",b="Grande parte da energia de Gaxim é canalizada contra a Empreendimentos S.A., cujo desmatamento predatório e ganância industrial profanam o Rochedo Cortavento nas proximidades. Acreditando que o maquinário rústico dos goblins não merece respeito nem piedade, Gaxim coordena operações secretas e sabotagens químicas voláteis contra as atividades madereiras deles. Para ele, incapacitar seus trituradores e roubar seus esquemas não é mera guerra tática — é uma demonstração prática de que o intelecto superior dos gnomos sempre triunfa sobre a pilhagem corporativa descuidada."}},faq={{q="Quem é Gaxim Deuxabu?",a="Gaxim Deuxabu é um estudioso e inventor gnomo alocado em um posto de vigia da Aliança ao longo da Passagem Tramateia, na Cordilheira das Torres de Pedra. Ele atua como emissário da Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences.",al={"quem é gaxim","história de gaxim deuxabu","gnomo nas torres de pedra"}},{q="O que é a Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences?",a="É uma sociedade acadêmica e científica de gnomos dedicada a unir as disciplinas de magia arcana, misturas alquímicas e engenharia mecânica. Gaxim representa seus ideais em Kalimdor.",al={"enlightened assembly","facção de gaxim","grupo de gaxim"}},{q="Por que Gaxim está trabalhando com os elfos noturnos?",a="Gaxim quer demonstrar aos elfos noturnos que a ciência e a alquimia dos gnomos podem proteger e recuperar florestas naturais de forma ativa, oferecendo uma resposta moderna da Aliança para a preservação florestal ao lado do druidismo tradicional.",al={"por que gaxim está aqui","gaxim elfos noturnos","objetivo de gaxim"}},{q="Por que Gaxim odeia a Empreendimentos S.A.?",a="A Empreendimentos S.A. está desmatando impiedosamente o Rochedo Cortavento com máquinas rústicas e poluição tóxica. Gaxim despreza essa exploração inconsequente e tem prazer em usar produtos químicos voláteis e sabotagens contra as operações deles.",al={"gaxim empreendimentos s.a.","gaxim vs empreendimentos s.a.","por que combater a empreendimentos s.a."}},{q="Quem está acampado com Gaxim na Passagem Tramateia?",a="Ele compartilha seu pequeno posto avançado com Kaela Umbralança, uma sentinela elfa noturna que vigia as trilhas que levam ao Rochedo Cortavento.",al={"companheiro de gaxim","quem está com gaxim","gaxim e kaela"}},{q="Onde Gaxim Deuxabu pode ser encontrado?",a="Ele está localizado em um modesto acampamento da Aliança ao longo da Passagem Tramateia, logo a sudoeste dos poços madereiros industriais do Rochedo Cortavento, na Cordilheira das Torres de Pedra.",al={"localização de gaxim","onde fica gaxim","mapa de gaxim deuxabu"}}},fx={d5f6878f={q="De que lado está Gaxim Deuxabu?",a="Gaxim é leal à Aliança e trabalha diretamente ao lado dos elfos noturnos em Cordilheira das Torres de Pedra. Representando a Assembleia Iluminada de Arcanologia, Alquimia e Ciências da Engenharia, ele atua como um emissário da engenhosidade gnômica, visando provar aos aliados kaldorei céticos que combinar conhecimento arcano, misturas químicas e engenharia mecânica pode preservar a natureza em vez de destruí-la.",al={"facção de gaxim deuxabu","gaxim é da aliança","para quem gaxim trabalha"}}},fp="16,465,21.595.0,19.523.0,24.238.0,81.204.0,42.216.0,40.225.0,43.126.0,36.158.0"}
P.entries["npc:gazin-tenorm"] = {n="Gazin Tenorm",s="Gazin Tenorm é um anão postado perto do altar na Catedral da Luz de Ventobravo. Ao lado de seu camarada Henze Faulk, ele realizou uma perigosa missão de reconhecimento para reunir evidências da atividade da Irmandade Défias para os conselheiros do rei.",h="Gazin Tenorm é um anão postado perto do altar na Catedral da Luz de Ventobravo.",kw={"catedral da luz","défias","benedito brião","gazin tenorm","henze faulk","paladino","tome of divinity"},ang={["class:Paladin"]="Iniciados aprendendo os caminhos da compaixão e redenção encontram Gazin na Catedral da Luz para ajudar seu irmão de armas caído, Henze Faulk.",["race:Dwarf"]="Gazin representa a solidariedade duradoura entre Altaforja e Ventobravo, servindo como um campeão anão disposto a enfrentar os bandidos de Elwynn em nome dos conselheiros do reino."},sec={{t="Um batedor na Catedral",b="Embora Gazin Tenorm passe seus dias dentro dos salões tranquilos da Catedral da Luz, sua mente permanece nas terras selvagens da Floresta de Elwynn. Gazin e seu amigo próximo Henze Faulk partiram para a floresta em uma tarefa urgente: reunir provas concretas dos movimentos da Irmandade Défias para apresentar perante a corte real. A expedição deu errado quando eles foram emboscados pelas forças Défias. Gazin escapou por pouco com vida de volta à segurança de Ventobravo, mas Henze foi deixado para trás em perigo mortal, levando Gazin a procurar um herói vigoroso da Luz para vir em auxílio de seu companheiro."}},faq={{q="Onde posso encontrar Gazin Tenorm?",a="Gazin Tenorm pode ser encontrado dentro da Catedral da Luz em Ventobravo, de pé perto do altar dos fundos ao lado do clero de alto escalão e mentores paladinos.",al={"localização de gazin","onde está gazin tenorm","onde está gazin"}},{q="O que aconteceu com Gazin Tenorm na Floresta de Elwynn?",a="Enquanto investigava a Irmandade Défias com seu companheiro Henze Faulk, Gazin encontrou uma emboscada de forças fora da lei. Ele conseguiu lutar para se libertar e fugir de volta para Ventobravo, mas a provação deixou seu amigo abandonado na floresta.",al={"história de gazin","o que aconteceu com gazin","por que gazin está ferido"}},{q="Por que Gazin estava investigando a Irmandade Défias?",a="Gazin e Henze Faulk aventuraram-se na Floresta de Elwynn para reunir evidências inegáveis das atividades ilícitas da Irmandade Défias, com a intenção de levar provas inegáveis diretamente aos conselheiros do rei em Ventobravo.",al={"por que investigar os défias","missão de gazin","gazin henze défias"}},{q="Como Gazin se conecta às provações dos Paladinos?",a="Benedito Brião encaminha aspirantes a paladinos humanos que buscam o Tome of Divinity para Gazin. Gazin então fornece os meios e a direção para resgatar seu parceiro caído Henze Faulk, testando o valor e a misericórdia do iniciado.",al={"gazin tome of divinity","missão de paladino gazin","missão de henze faulk"}}},fx={d8d56684={q="Quem é Gazin Tenorm?",a="Gazin Tenorm é um investigador anão que atualmente está abrigado dentro da Catedral da Luz em Ventobravo. Trabalhando em coordenação com contatos reais, ele e seu parceiro buscaram evidências para confirmar a crescente ameaça dos Defias que se agita logo fora dos portões da capital.",al={"quem é gazin","quem é gazin tenorm","identidade de gazin tenorm"}},e9ee1d11={q="De que lado está Gazin Tenorm?",a="Gazin é inteiramente leal à Aliança e ao Reino de Ventobravo. Ele trabalha ao lado do sacerdócio e dos paladinos da Catedral da Luz, esforçando-se para reunir informações concretas para a corte do rei sobre a subversão rebelde em Floresta de Elwynn.",al={"facção de gazin tenorm","gazin é da aliança","a quem gazin serve"}},["22d0c57e"]={q="O que Gazin Tenorm quer?",a="Tendo sobrevivido por pouco a uma emboscada de capangas da The Defias Brotherhood, Gazin quer desesperadamente que seu companheiro Henze Faulk seja resgatado da Floresta de Elwynn. Além disso, ele busca expor os planos da The Defias Brotherhood aos conselheiros do rei antes que sua insurreição ganhe mais força.",al={"o que gazin quer","objetivo de gazin tenorm","o que gazin está procurando"}},["6cef862e"]={q="Por que Gazin Tenorm está na Catedral da Luz?",a="Após um confronto violento com os Defias que o deixou abalado e fugindo por sua vida, Gazin buscou o santuário sagrado da Catedral da Luz. Aqui, perto do altar, ele se recupera sob a proteção vigilante de Benedito Brião e da Mão de Prata.",al={"por que gazin está na catedral","por que gazin tenorm está aqui","gazin catedral da luz"}},["2ec8b348"]={q="A quem Gazin Tenorm está ligado?",a="Gazin trabalha em estreita parceria com Henze Faulk, seu colega investigador. Ele também compartilha um forte laço de confiança com Benedito Brião, que direciona jovens paladinos promissores para ajudar Gazin em seu dever compartilhado de salvaguardar o reino.",al={"aliados de gazin tenorm","conexões de gazin","com quem gazin trabalha"}}},fp="12,235,24.580.0,30.154.0,47.242.0,51.213.0,45.212.0"}
P.entries["npc:gazrog"] = {n="Gazrog",s="Gazrog é um guerreiro orc estacionado na Encruzilhada, no coração dos Sertões. Encarregado de manter a logística e a segurança ao longo das estradas perigosas da savana, ele recruta viajantes capazes da Horda para lidar com ameaças regionais e investigar patrulhas desaparecidas.",h="Gazrog é um guerreiro orc estacionado na Encruzilhada, no coração dos Sertões.",kw={"sertões","encruzilhada","dogran","gazrog","posto avançado da horda","raptor thieves","prata roubada"},ang={["faction:Horde"]="Gazrog é um dos primeiros contatos para os aventureiros da Horda que deixam Durotar ou Mulgore, oferecendo trabalho crítico para estabelecer corredores seguros de viagem através de Kalimdor.",["race:Orc"]="Como um veterano orc segurando as pontas na Encruzilhada, Gazrog personifica a determinação firme e prática necessária para domar a fronteira implacável de Kalimdor."},sec={{t="Um Sentinela da Encruzilhada",b="A Encruzilhada serve como a junção vital para todo o trânsito da Horda por Kalimdor, mas seu isolamento deixa as linhas de suprimento vulneráveis tanto a saqueadores quanto a feras. Gazrog vigia ao lado dos defensores do assentamento, trabalhando para garantir que cargas, moedas e mensageiros cheguem a seus destinos. Manter a ordem em uma vastidão selvagem requer vigilância constante, e Gazrog depende muito dos aventureiros que passam para lidar com crises que se formam além das paliçadas do posto avançado."},{t="Perigos da Savana",b="Entre raptores predadores atormentando as trilhas e clãs agressivos de javatuscos emboscando batedores, os deveres de Gazrog nunca têm fim. Ele coordena frequentemente respostas a assaltos em estradas — como recuperar remessas roubadas da Horda — e monitora soldados desaparecidos, como o bruto Dogran, que acabou como um prisioneiro ferido dos javatuscos."}},faq={{q="Onde Gazrog pode ser encontrado?",a="Gazrog está localizado na Encruzilhada, o assentamento central que conecta as rotas do norte, sul e leste dos Sertões.",al={"localização de gazrog","onde fica gazrog","gazrog encruzilhada"}},{q="Qual papel Gazrog desempenha para a Horda?",a="Ele atua como coordenador operacional e guarda na Encruzilhada, distribuindo tarefas para proteger linhas de suprimento regionais, recuperar remessas interceptadas e localizar membros desaparecidos da Horda.",al={"função de gazrog","quem é gazrog","o que gazrog faz"}},{q="O que aconteceu com a prata roubada sobre a qual Gazrog pergunta?",a="Os comboios de moedas da Horda são frequentemente visados por raptores astutos da savana e oportunistas que vagam pelas trilhas dos Sertões, levando Gazrog a enviar campeões para caçar as feras e recuperar a carga.",al={"missão prata roubada","quem roubou a prata","carregamento roubado dos sertões"}},{q="Quem é Dogran?",a="Dogran é um bruto da Horda que foi destacado para a Encruzilhada para trabalhar com Gazrog. Ele nunca retornou do serviço: Gazrog ouviu dizer que ele está vivo, mas ferido e mantido prisioneiro pelos javatuscos, uma notícia que ele preferiria não dar à companheira de Dogran, Zankaja.",al={"news of dogran","onde está dogran","gazrog dogran"}},{q="Gazrog é afiliado a Vila Catraca ou aos goblins?",a="Não. Gazrog serve à Horda diretamente a partir da Encruzilhada, mantendo a segurança dos interesses de orcs, taurens e trolls por todos os Sertões centrais.",al={"gazrog é de vila catraca","facção de gazrog","gazrog goblin"}},{q="Por que os raptores estão roubando suprimentos nos Sertões?",a="Ninguém tem certeza absoluta. Os raptores esconderam a prata roubada em seus ninhos na Terra dos Raptores, ao sul de Vila Catraca, e Gazrog se pergunta se as histórias sobre a inteligência deles estão mais próximas da verdade do que ele imaginava.",al={"por que raptor thieves","raptores roubam coisas","raptores brilhante"}}},fx={fdfa6042={q="O que Gazrog quer?",a="Gazrog busca garantir suprimentos críticos e manter a ordem nos Sertões para a Horda. Ele encarrega aventureiros de recuperar a remessa de prata roubada por raptores locais, enquanto também busca notícias sobre o destino de seu companheiro desaparecido, Dogran.",al={"o que gazrog quer","o que gazrog precisa","objetivos de gazrog"}},d6aec43d={q="Por que Gazrog está aqui na Encruzilhada?",a="Estacionado no posto avançado estratégico da Encruzilhada, Gazrog supervisiona operações vitais para a base da Horda no centro de Kalimdor. Ele está aqui para combater ameaças locais que atacam caravanas de forma disruptiva, rastrear batedores da Horda desaparecidos e recuperar recursos roubados essenciais para a defesa do posto avançado.",al={"por que gazrog está aqui","propósito de gazrog na encruzilhada","por que gazrog está nos sertões"}}},fp="6,258,28.475.0,16.329.0,26.129.0,41.187.0,53.196.0,14.237.0,49.145.0,49.211.0"}
P.entries["npc:gelbin-mekkatorque"] = {n="Gelbin Mekkatorque",s="Gelbin Mekkatorque é o Grão-engenhocas dos gnomos, residindo atualmente no exílio no Beco da Gambiarra, em Altaforja. Renomado como um engenheiro visionário cujas invenções incluem o mecanostruz e o Metrô Correfundo, ele agora carrega o pesado fardo da queda de Gnomeregan e supervisiona os esforços para recuperar o lar ancestral de seu povo.",h="Gelbin Mekkatorque é o Grão-engenhocas dos gnomos, residindo atualmente no exílio no Beco da Gambiarra, em...",kw={"metrô correfundo","gelbin","gnomo","gnomeregan","grão-engenhocas","altaforja","mecanostruz","mekkatorque","termaplugue","beco da gambiarra"},ang={["profession:Engineering"]="Estar diante do Grão-engenhocas é estar diante do criador do mecanostruz e de uma das mentes condutoras por trás do Metrô Correfundo. Sua oficina no Beco da Gambiarra representa a vanguarda da inovação tecnológica.",["race:Gnome"]="Mekkatorque é o coração do seu povo no exílio. Embora a culpa pelo envenenamento de Gnomeregan pese sobre ele, seu brilhantismo e devoção à libertação do seu lar ancestral inspiram lealdade absoluta no Beco da Gambiarra."},sec={{t="O Grão-engenhocas e Mestre Inventor",b="A liderança gnômica é conquistada por meio do intelecto e do mérito, e não por linhagens de sangue, e a ascensão de Gelbin Mekkatorque a Grão-engenhocas foi impulsionada por puro gênio inventivo. Mekkatorque revolucionou o transporte pessoal com a criação do primeiro mecanostruz funcional. Ele também auxiliou os anões Barbabronze no desenvolvimento de seus formidáveis mecanismos de cerco e foi fundamental na criação do subterrâneo Metrô Correfundo, ligando Altaforja a Ventobravo."},{t="Traição e Exílio em Altaforja",b="A maior tragédia de Mekkatorque ocorreu quando troggs invadiram Gnomeregan vindos das profundezas. Instigado por seu amigo de confiança e conselheiro-chefe, o Mecangenheiro Termaplugue, Mekkatorque ordenou a liberação de resíduos radioativos nos corredores inferiores para exterminar os invasores. Em vez disso, o gás tóxico massacrou milhares de gnomos inocentes e causou mutações nos sobreviventes, enquanto Termaplugue tomou posse da cidade arruinada. Arrasado pela culpa, mas determinado a corrigir seu erro, Mekkatorque liderou os refugiados sobreviventes através de Dun Morogh até Altaforja. Operando no Beco da Gambiarra sob a hospitalidade do Rei Magni, o Grão-engenhocas direciona as energias militares e científicas do povo gnômico rumo a um único e inabalável objetivo: libertar Gnomeregan."}},faq={{q="Quem é Gelbin Mekkatorque?",a="Gelbin Mekkatorque é o Grão-engenhocas eleito e líder dos gnomos. Ele é um mestre engenheiro que projetou tecnologias gnômicas essenciais, incluindo o mecanostruz e o Metrô Correfundo.",al={"grão-engenhocas","líder dos gnomos","quem é o rei dos gnomos"}},{q="Por que Mekkatorque está em Altaforja em vez de Gnomeregan?",a="Gnomeregan foi tomada por uma invasão selvagem de troggs, seguida por uma catastrófica chuva radioativa. Mekkatorque liderou a evacuação de seu povo através de Dun Morogh até Altaforja, onde o Rei Magni Barbabronze concedeu-lhes refúgio no Beco da Gambiarra enquanto planos são elaborados para retomar a cidade.",al={"por que mekkatorque está em altaforja","por que os gnomos estão em altaforja","queda de gnomeregan"}},{q="O que causou a catástrofe em Gnomeregan?",a="Enfrentando ondas intermináveis de troggs, Mekkatorque foi persuadido por um conselheiro de confiança a liberar fluido de resfriamento radioativo e tóxico nas câmaras inferiores para deter as feras. Tragicamente, o gás não conseguiu parar os troggs e, em vez disso, irradiou a cidade, matando milhares de gnomos.",al={"o que aconteceu com gnomeregan","por que gnomeregan está irradiada","traição de termaplugue"}},{q="O que Mekkatorque inventou antes de se tornar Grão-engenhocas?",a="Mekkatorque inventou o mecanostruz, dando aos gnomos sua própria montaria ágil. Ele também ajudou a desenvolver o mecanismo de cerco dos anões e foi fundamental na criação do Metrô Correfundo entre Altaforja e Ventobravo.",al={"invenções de mekkatorque","o que gelbin construiu"}},{q="Mekkatorque é um rei de verdade?",a="Os gnomos não têm uma monarquia hereditária; seu líder é um Grão-engenhocas eleito, escolhido por mérito e realizações intelectuais. Seu título e autoridade derivam de sua eleição como Grão-engenhocas.",al={"mekkatorque é um rei","rei dos gnomos"}}},fx={db25d752={q="De que lado está Gelbin Mekkatorque?",a="Gelbin Mekkatorque está firmemente ao lado da Aliança. Como líder dos gnomos, ele mantém um laço inquebrável com o Rei Magni Barbabronze e os anões de Altaforja, que abriram seus portões para abrigar seu povo deslocado. Mekkatorque prometeu a engenharia, engenhosidade e recursos militares dos gnomos para ajudar seus aliados da Aliança em toda Azeroth.",al={"facção de mekkatorque","gelbin aliança","a quem mekkatorque serve"}},["0e3721be"]={q="O que Gelbin Mekkatorque quer?",a="O foco singular de Mekkatorque é retomar Gnomeregan. A perda de seu lar e as mortes trágicas de incontáveis gnomos pesam muito sobre ele, levando-o a encontrar uma maneira de purgar os troggs e a radiação que envenenam seus salões. Do Beco da Gambiarra, ele direciona o reconhecimento e organiza equipes de ataque para preparar o terreno para retomar a cidade.",al={"objetivo de mekkatorque","o que gelbin está tentando fazer","plano de gelbin"}},["39ae11c6"]={q="A quem Gelbin Mekkatorque está ligado?",a="Mekkatorque trabalha em estreita colaboração com o Rei Magni Barbabronze, seu anfitrião gentil em Altaforja, e coordena com a liderança da Aliança em Ventobravo. Em um nível pessoal, ele é assombrado pela perda de Gnomeregan e pelos milhares de gnomos que morreram após o vazamento radioativo que ele ordenou sob o conselho de um assessor de confiança.",al={"aliados de mekkatorque","relacionamentos de gelbin","com quem mekkatorque trabalha"}},["5cf35b41"]={q="Por que Gelbin Mekkatorque é famoso?",a="Mekkatorque é renomado por toda Azeroth como um dos maiores gênios da engenharia da história. Ele inventou o primeiro mecanostruz funcional, ajudou a projetar o motor de cerco dos anões e foi fundamental na criação do Metrô Correfundo, que conecta Altaforja a Ventobravo.",al={"por que mekkatorque é famoso","pelo que gelbin é conhecido","invenções de mekkatorque"}}},fp="18,326,35.467.0,31.710.1,26.189.0,54.282.0,42.264.0,56.208.0,30.191.0"}
P.entries["npc:gelihast"] = {n="Gelihast",s="Gelihast é um feroz chefe murloc empunhando lâminas gêmeas que reside no Pool of Ask'ar dentro de Profundezas Negras. Cercado por seus murlocs Blindlight, ele guarda um estranho altar nas ruínas inundadas do Templo Submerso.",h="Gelihast é um feroz chefe murloc empunhando lâminas gêmeas que reside no Pool of Ask'ar dentro de Profundezas...",kw={"profundezas negras","blindlight","gelihast","murloc","pool of ask'ar","twilight's hammer"},ang={["class:Warrior"]="Gelihast ataca com uma velocidade ofuscante de espada; guerreiros habilidosos que se preparam podem virar seu frenético ataque com armas duplas totalmente contra ele.",["faction:Alliance"]="Para as forças da Aliança que buscam purificar a corrupção que se espalha pelo Vale Gris, eliminar Gelihast é essencial para proteger as passagens do norte do templo submerso.",["faction:Horde"]="Aventureiros da Horda enviados para vasculhar Profundezas Negras devem eliminar Gelihast para abrir caminho mais fundo no Templo Submerso sob a Praia de Zoram."},sec={{t="Um Chamado Mortal",b="Enquanto a maioria dos murlocs permanece perto das águas rasas costeiras, Gelihast reivindicou um covil nas profundezas do Templo Submerso de Profundezas Negras sob a Praia de Zoram. Empunhando espadas gêmeas com velocidade ofuscante, ele abate intrusos antes que possam reagir, e conjuradores que entram em seu alcance raramente sobrevivem."},{t="Mestre dos Blindlight",b="Gelihast governa o Pool of Ask'ar, cercado por sua ninhada Blindlight, que corre para o seu lado ao primeiro sinal de perigo. Além de seu covil, ergue-se um altar; aqueles que o derrotam e o tocam recebem a Blessing of Blackfathom."}},faq={{q="Quem é Gelihast?",a="Gelihast é um cruel chefe murloc que comanda a tribo Blindlight dentro do Pool of Ask'ar, em Profundezas Negras. Ele luta com lâminas gêmeas de velocidade ofuscante.",al={"quem é gelihast","história de gelihast","origem de gelihast"}},{q="Por que Gelihast está dentro de Profundezas Negras?",a="Ninguém sabe o que o atraiu para lá inicialmente. Ele e seus murlocs Blindlight reivindicaram o Pool of Ask'ar nas ruínas inundadas, e ele o defende ferozmente contra todos os intrusos.",al={"por que há um murloc em bfd","por que gelihast está no templo"}},{q="Como o Twilight's Hammer reagiu a ele?",a="Nada foi registrado sobre negociações entre Gelihast e os cultistas do Twilight's Hammer mais ao fundo do templo. Ele governa seu próprio lago com seus murlocs Blindlight.",al={"gelihast e twilight's hammer","os cultistas gostam de gelihast"}},{q="O que é o altar atrás de Gelihast?",a="Um altar ergue-se além de seu lago. Viajantes que o derrotam podem tocá-lo para receber a Blessing of Blackfathom.",al={"altar das profundezas","altar de gelihast","altar da blessing of blackfathom"}},{q="Qual tribo de murlocs ele lidera?",a="Ele lidera os murlocs Blindlight, uma tribo agressiva que infesta o Pool of Ask'ar dentro das cavernas.",al={"tribo de gelihast","quais murlocs estão em bfd"}},{q="O que acontece com Gelihast se ele não for impedido?",a="Ele e seus murlocs Blindlight mantêm o Pool of Ask'ar fechado para qualquer um que tente se aventurar mais fundo no Templo Submerso.",al={"destino de gelihast","quem mata gelihast"}}},fx={["18aa1a09"]={q="O que Gelihast quer?",a="Gelihast quer manter seu domínio sobre a Pool of Ask'ar. Com seus murlocs Blindlight fervilhando ao seu redor, ele trucida selvagemente qualquer um que invada suas águas no templo submerso.",al={"objetivo de gelihast","o que gelihast quer","motivo de gelihast"}}},fp="8,225,16.288.0,24.226.0,16.166.0,41.173.0,43.156.0,34.110.0,35.104.0,49.120.0"}
P.entries["npc:gelkak-gyromast"] = {n="Gelkak Giramastro",s="Gelkak Giramastro é um gnomo que fala como um capitão pirata, encontrado náufrago ao longo da costa enevoada de Beira das Névoas, no norte de Costa Negra. Seu navio foi afundado perto da costa por debulhadores, e ele quer seu primeiro-imediato mecânico, o Threshwackonator 4100, funcionando novamente.",h="Gelkak Giramastro é um gnomo que fala como um capitão pirata, encontrado náufrago ao longo da costa enevoada...",kw={"costa negra","gelkak giramastro","gnomo inventor","mathistra","beira das névoas","threshwackonator 4100"},ang={["profession:Engineering"]="A situação de Gelkak é um clássico conto de um gnomo longe de casa, depositando suas esperanças de vingança em um dispositivo tão impressionante quanto o Threshwackonator 4100.",["race:Gnome"]="Ver outro gnomo náufrago na beirada de Kalimdor é um lembrete vívido de quão longe de casa as aventuras de um gnomo podem levá-lo."},sec={{t="Náufrago em Beira das Névoas",b="Instalado na costa norte desolada de Costa Negra, logo a oeste das antigas Ruínas de Mathistra, Gelkak Giramastro é uma visão peculiar entre as praias sombrias dos elfos noturnos. Falando como um velho lobo do mar, o autoproclamado capitão perdeu seu navio para os debulhadores bem perto da praia. Quando foi parar nas areias enevoadas, a chave de seu primeiro-imediato mecânico, o Threshwackonator 4100, quebrou-se nas pedras, e suas partes foram levadas pelos rastejantes, pernalongas-da-floresta e murlocs que reviravam os destroços."},{t="O mau funcionamento do Threshwackonator",b="Assim que os aventureiros recuperam a chave, Giramastro os envia para ligar seu primeiro-imediato e conduzi-lo de volta até ele, ansioso para soltá-lo contra os murlocs e feras da costa. O Threshwackonator 4100 obedece e segue, apenas para ter um mau funcionamento e se tornar hostil no instante em que alcança seu capitão, cabendo aos aventureiros destruí-lo."}},faq={{q="Quem é Gelkak Giramastro?",a="Gelkak Giramastro é um gnomo excêntrico que fala como um capitão pirata, náufrago na praia ao norte de Costa Negra conhecida como Beira das Névoas, logo a oeste das Ruínas de Mathistra.",al={"gelkak","quem é gelkak","giramastro"}},{q="Por que Gelkak está náufrago em Costa Negra?",a="Seu navio foi afundado perto da praia por debulhadores, e ele foi dar na costa desolada do norte com a chave quebrada de seu primeiro-imediato mecânico.",al={"por que gelkak está aqui","gelkak costa negra"}},{q="O que é o Threshwackonator 4100?",a="O Threshwackonator 4100 é a criação mecânica de Gelkak e seu autoproclamado primeiro-imediato. Ele o quer funcionando novamente para se vingar dos murlocs e das feras da costa.",al={"threshwackonator","máquina do gelkak","robô"}},{q="De que ajuda Gelkak precisa dos viajantes?",a="Gelkak pede a aventureiros capazes que recuperem as três partes de sua chave quebrada dos rastejantes, pernalongas-da-floresta e murlocs da costa, e depois a usem para ativar o Threshwackonator 4100 e trazê-lo de volta até ele.",al={"missões de gelkak","missões de giramastro"}}},fx={["77810e79"]={q="Do lado de quem está Gelkak Giramastro?",a="Gelkak é um gnomo alinhado à Aliança, embora aqui nas praias solitárias de Costa Negra ele aja estritamente em seu próprio benefício. Preso longe de qualquer povoado importante, ele recebe bem qualquer viajante amistoso da Aliança disposto a dar uma mão com seus acidentes mecânicos.",al={"facção de gelkak giramastro","gelkak é da aliança","a quem gelkak serve"}}},fp="15,271,23.509.0,32.325.1,23.173.0,36.145.0,34.186.0,42.209.0"}
P.entries["npc:general-marcus-jonathan"] = {n="General Marcus Jonas",s="O General Marcus Jonas é o Alto Comandante da Defesa de Ventobravo, estacionado diretamente nos portões do Vale dos Heróis. Veterano da Segunda Guerra, ele supervisiona a guarnição que protege a capital e gerencia os pedidos militares dos assentamentos de fronteira do reino.",h="O General Marcus Jonas é o Alto Comandante da Defesa de Ventobravo, estacionado diretamente nos portões do...",kw={"general jonas","vila plácida","magistrado salomão","marcus jonas","reginald windsor","exército de ventobravo","defesa de ventobravo","vale dos heróis"},ang={["class:Warrior"]="Como comandante supremo dos portões de Ventobravo e veterano da Segunda Guerra, Jonas representa o auge do dever marcial padrão dentro das fileiras de infantaria do reino.",["faction:Alliance"]="Marcus Jonas personifica o orgulho marcial de Ventobravo no portão da capital."},sec={{t="Comandante dos Portões",b="Montado em seu corcel no Vale dos Heróis, o General Marcus Jonas posiciona-se como a primeira linha de defesa e o oficial militar de maior patente supervisionando os portões da cidade. Ele lutou na Segunda Guerra ao lado de soldados renomados como Reginald Windsor sob o comando do General Turalyon. Nesta era de tensão crescente, Jonas precisa equilibrar a segurança imediata da capital com os pedidos de ajuda cada vez mais desesperados de cidades fronteiriças como Vila Plácida."},{t="Um Comando Sob Pressão",b="Enquanto cidades como Vila Plácida imploram por soldados de Ventobravo para repelir orcs Rocha Negra e gnolls, Jonas garante aos magistrados locais seu compromisso de ajudar, embora confesse em particular que a corte se tornou distante e que a regência do rei-menino comporta-se de maneira estranha."}},faq={{q="Onde posso encontrar o General Marcus Jonas?",a="Ele está estacionado a cavalo logo dentro dos portões principais de Ventobravo, observando a ponte de entrada no Vale dos Heróis.",al={"localização de marcus jonas","onde está o general jonas","comandante do portão de ventobravo"}},{q="Qual é o histórico militar de Marcus Jonas?",a="Marcus Jonas é um veterano que serviu sob o comando do General Turalyon durante a Segunda Guerra. Ele lutou ao lado de camaradas como Reginald Windsor antes de finalmente ascender ao posto de Alto Comandante da Defesa de Ventobravo.",al={"passado de marcus jonas","história de marcus jonas","marcus lutou na segunda guerra"}}},fx={d649e9ed={q="Quem é o General Marcus Jonas?",a="O General Marcus Jonas é o Alto Comandante da Defesa de Ventobravo. Um veterano experiente que serviu sob o General Turalyon durante a Segunda Guerra, ele agora supervisiona as forças militares que protegem a capital e seus territórios adjacentes.",al={"quem é marcus jonas","identidade de marcus jonas","quem é o general jonas"}},["59fdae30"]={q="Do lado de quem está o General Marcus Jonas?",a="Ele é totalmente devoto ao Reino de Ventobravo e à Grande Aliança. Ele leva seu dever de defender o reino e proteger seus cidadãos com absoluta seriedade, respondendo diretamente à coroa e à alta liderança de Ventobravo.",al={"lealdade de marcus jonas","a quem marcus jonas serve","facção de marcus jonas"}},["5549e5c1"]={q="O que o General Marcus Jonas deseja?",a="Jonas deseja proteger Ventobravo e garantir que seus povoados periféricos, como Vila Plácida, recebam o apoio militar de que necessitam desesperadamente. No entanto, com o desaparecimento do Rei Varian Wrynn e o comportamento estranho da corte real, sua capacidade de mobilizar tropas como deseja está severamente prejudicada.",al={"objetivo de marcus jonas","o que marcus jonas precisa","motivos de marcus jonas"}},b8230eb1={q="Por que o General Marcus Jonas é importante para Montanhas Cristarrubra?",a="O Magistrado Salomão de Vila Plácida direciona os apelos por ajuda militar diretamente ao General Jonas, sabendo que sua palavra tem um peso substancial em Ventobravo. Como comandante do exército, Jonas é a autoridade com poder para pedir reforços à coroa para defender Montanhas Cristarrubra.",al={"por que marcus jonas em cristarrubra","marcus jonas e vila plácida","por que enviar mensagem a marcus jonas"}},ab66a8e6={q="A quem o General Marcus Jonas está ligado?",a="Ele compartilha uma longa história com o Marechal Reginald Windsor, tendo lutado ao lado dele sob o comando do General Turalyon durante a Segunda Guerra. Em Ventobravo, ele coordena regularmente com a coroa e responde a apelos urgentes de líderes regionais, como o Magistrado Salomão.",al={"conexões de marcus jonas","quem conhece marcus jonas","aliados de marcus jonas"}}},fp="23,272,22.465.0,18.256.1,41.132.0,43.215.0"}
P.entries["npc:gerard-tiller"] = {n="Geraldo Amanho",s="Geraldo Amanho é um trabalhador rural humano e sedento que trabalha do lado de fora do celeiro nos Vinhedos dos Madruga, na Floresta de Elwynn. Cuidando dos vinhedos sob o sol quente, ele está sempre ansioso para trocar uma maçã vermelha brilhante e crocante com qualquer viajante disposto a ceder um cantil de água refrescante da fonte.",h="Geraldo Amanho é um trabalhador rural humano e sedento que trabalha do lado de fora do celeiro nos Vinhedos...",kw={"floresta de elwynn","geraldo amanho","dê de beber a geraldo","vinhedos dos madruga","água refrescante da fonte","maçã vermelha brilhante"},ang={["profession:Cooking"]="A disposição de Geraldo em trocar maçãs frescas por simples água da fonte faz dele uma fonte prática de frutas para cozinheiros itinerantes que procuram ingredientes simples."},sec={{t="Um Trabalhador Rural Sedento",b="Geraldo Amanho passa seus dias labutando nos campos e cuidando dos terrenos do lado de fora do celeiro nos Vinhedos dos Madruga. Localizado logo ao sul de Vila d'Ouro, o vinhedo produz algumas das uvas mais conhecidas de Elwynn, mas manter a colheita em andamento é um trabalho árduo. Amanho está constantemente ressecado por causa de suas tarefas, o que o faz negociar rapidamente com aventureiros que passam por ali. Se alguém lhe oferecer um cantil fresco de água fresca de nascente, ele retribui com prazer a cortesia com maçãs vermelhas brilhantes e frescas, colhidas diretamente dos pomares locais."}},faq={{q="Quem é Geraldo Amanho?",a="Geraldo Amanho é um trabalhador rural humano situado do lado de fora do celeiro nos Vinhedos dos Madruga, no sul da Floresta de Elwynn.",al={"identidade de geraldo amanho","quem é geraldo","amanho elwynn"}},{q="Onde posso encontrar Geraldo Amanho?",a="Ele fica bem do lado de fora do grande celeiro de madeira nos Vinhedos dos Madruga, localizado ao sul de Vila d'Ouro e a leste da Fazenda dos Campedra.",al={"localização de geraldo amanho","onde fica geraldo","encontrar geraldo elwynn"}},{q="O que Geraldo Amanho troca?",a="Geraldo troca uma Maçã Vermelha Brilhante com qualquer viajante que lhe trouxer um cantil de Água Refrescante da Fonte para matar sua sede.",al={"troca de maçã de geraldo","geraldo amanho água","o que geraldo quer"}},{q="Geraldo se envolve na rixa entre os Madruga e os Campedra?",a="Não. Embora trabalhe nos Vinhedos dos Madruga, Geraldo se concentra em suas tarefas e em se manter hidratado, em vez de se intrometer na rivalidade familiar entre os Madruga e os Campedra.",al={"rixa de geraldo amanho","rixa dos madruga geraldo"}}},fx={["467277ed"]={q="O que Geraldo Amanho deseja?",a="Trabalhar sob o sol quente nos Vinhedos dos Madruga é um trabalho que dá sede, e Geraldo quer pouco mais do que um simples cantil de Água Refrescante da Fonte para saciar sua sede. Se você levar uma bebida para ele, ele trocará de bom grado por uma Maçã Vermelha Brilhante do pomar.",al={"o que geraldo amanho precisa","troca com geraldo amanho","o que geraldo deseja"}},["9aadf23d"]={q="Por que Geraldo Amanho está aqui?",a="Geraldo Amanho ganha a vida como trabalhador cuidando dos terrenos fora do celeiro nos Vinhedos dos Madruga. Enquanto as terras ao redor de Elwynn enfrentam agitação, Geraldo continua focado no trabalho agrícola diário e em cuidar da colheita.",al={"por que geraldo amanho está nos vinhedos","motivo da localização de geraldo amanho","o que geraldo amanho faz"}},["9f9d4e60"]={q="A quem Geraldo Amanho está ligado?",a="Geraldo está ligado à família Madruga, trabalhando em seus vinhedos ao sul da Cidade de Ventobravo. Embora ele trabalhe diretamente em suas terras ao lado de seus celeiros, ele cuida de sua própria vida e evita a amarga rivalidade que ocorre entre os Madruga e seus vizinhos rivais, os Campos de Pedra.",al={"conexões de geraldo amanho","para quem geraldo amanho trabalha","aliados de geraldo amanho"}}},fp="13,272,18.515.0,21.112.0,31.131.0,30.118.0,60.175.0"}
P.entries["npc:gerrig-bonegrip"] = {n="Gerrig Agarrosso",s="Gerrig Agarrosso é um discreto lojista anão escondido nos corredores sombrios de Forlorn Cavern, em Altaforja. Atrás do balcão da Bonegrip's Runes and Dooms, ele compra e vende discretamente textos esotéricos sobre rituais sombrios e antigos poderes esquecidos.",h="Gerrig Agarrosso é um discreto lojista anão escondido nos corredores sombrios de Forlorn Cavern, em Altaforja.",kw={"profundezas negras","agarrosso","forlorn cavern","gerrig","altaforja","manuscrito de lorgalis","runes and dooms"},ang={["class:Warlock"]="Para os bruxos que frequentam os cantos sombrios de Forlorn Cavern, a coleção de rituais esotéricos e tomos sombrios de Agarrosso oferece uma conveniente fonte de conhecimento perigoso.",["race:Dwarf"]="Para os visitantes anões, o comércio de conhecimento proibido de Agarrosso lança uma sombra perturbadora sobre a vida acadêmica de Altaforja."},sec={{t="Bonegrip's Runes and Dooms",b="Operando nos recessos lúgubres de Forlorn Cavern, Gerrig Agarrosso parece à maioria dos cidadãos apenas um excêntrico comerciante de relíquias bizarras e conhecimento proibido. No entanto, sua humilde loja cumpre uma função muito mais sombria. Agarrosso é um membro ativo do niilista Martelo do Crepúsculo, usando sua fachada comercial para reunir manuscritos perigosos e textos obscuros relacionados aos Deuses Antigos bem debaixo dos narizes do Senado de Altaforja e da Sala do Trono."},{t="Coletando Conhecimento Proibido",b="Gerrig recruta ativamente aventureiros desavisados da Aliança para recuperar artefatos antigos, como o Manuscrito de Lorgalis, perdido nas profundezas de Profundezas Negras. Uma vez que essas relíquias estão em suas mãos, ele transcreve e dissemina o conhecimento profano diretamente para seus irmãos de culto por toda Azeroth. Por meio de conexões sutis com associados sombrios como Rodapeh e figuras que lidam com antigas entidades primordiais como Myzrael, Agarrosso trabalha incansavelmente para avançar os planos apocalípticos do culto."}},faq={{q="Quem é Gerrig Agarrosso?",a="Gerrig Agarrosso é um anão que administra a Bonegrip's Runes and Dooms em Forlorn Cavern, em Altaforja. Ele negocia curiosidades excêntricas e textos obscuros sobre rituais antigos.",al={"quem é agarrosso","história de gerrig agarrosso","agarrosso altaforja"}},{q="O que ele faz com o Manuscrito de Lorgalis?",a="Ele busca o Manuscrito de Lorgalis em Profundezas Negras para sua coleção de textos raros. Investigações mais aprofundadas podem revelar mais sobre o uso que ele faz dele.",al={"por que agarrosso quer o manuscrito de lorgalis","entrega de knowledge in the deeps","uso do manuscrito de lorgalis"}},{q="Como Gerrig opera em Altaforja?",a="Gerrig mantém um perfil discreto como um estudioso excêntrico e comerciante em Forlorn Cavern, onde compra e vende textos obscuros.",al={"altaforja sabe que agarrosso é um cultista","por que agarrosso é permitido em altaforja"}},{q="Qual é a ligação dele com Myzrael?",a="Gerrig é um antigo associado do anão Rodapeh, que investiga o elemental da terra aprisionado Myzrael no Planalto Arathi. Por meio dessas conexões, Gerrig ajuda a orquestrar tarefas ligadas a antigos rituais de vinculação e poderes primordiais.",al={"gerrig agarrosso e myzrael","rodapeh e gerrig"}}},fp="15,264,26.449.1,30.487.1,23.172.2,45.149.1,37.129.2,34.238.0"}
P.entries["npc:gershala-nightwhisper"] = {n="Gershala Umbrurmúrio",s="Gershala Umbrurmúrio é um pesquisador elfo noturno residente no assentamento costeiro de Auberdine, em Costa Negra. Movido por uma grande preocupação com o caminho trilhado pelos elfos superiores de Quel'Thalas, ele estuda espécimes de criaturas aquáticas amaldiçoadas e demoníacas para compreender como a corrupção mágica distorce tanto a mente quanto o corpo.",h="Gershala Umbrurmúrio é um pesquisador elfo noturno residente no assentamento costeiro de Auberdine, em Costa...",kw={"auberdine","profundezas negras","corrupção","costa negra","gershala","naga","umbrurmúrio","sátiro"},ang={["faction:Alliance"]="Gershala atua como um dos principais patrocinadores a enviar expedições da Aliança aos perigos de Profundezas Negras, garantindo que suas incursões rendam valioso conhecimento arcano.",["race:NightElf"]="Para os elfos noturnos, as investigações sombrias de Gershala são uma lembrança pungente da antiga Cisão e do custo terrível do vício mágico, que no passado remodelou seus irmãos em horrores."},sec={{t="Estudo da Transformação",b="Instalado pacificamente em Auberdine, Gershala Umbrurmúrio olha além dos problemas costeiros imediatos de Costa Negra em direção a um perigo mais amplo e insidioso. Observando com consternação os elfos superiores remanescentes adotarem práticas arcanas perigosas e se autodenominarem elfos sangrentos, Gershala busca compreender a decadência biológica e espiritual que se segue à magia descontrolada. Para desvendar esses segredos, ele orienta aventureiros experientes da Aliança a entrarem nos salões submersos de Profundezas Negras a fim de coletar troncos encefálicos corrompidos dos nagas e sátiros que habitam o local."},{t="Um Antídoto para a Ruína",b="O foco sombrio de Gershala em troncos encefálicos de nagas e sátiros tem origem na linhagem compartilhada de ambos: ambas as raças já foram elfos noturnos antes de cederem à Rainha Azshara e a pactos demoníacos. Ao dissecar as marcas físicas deixadas em seus sistemas nervosos por milênios de energias demoníacas e abissais, ele espera descobrir alertas ou salvaguardas que possam impedir que outros parentes élficos caiam em uma deformidade monstruosa semelhante."}},faq={{q="Onde Gershala Umbrurmúrio é encontrado?",a="Gershala Umbrurmúrio pode ser encontrado em Auberdine, a principal cidade portuária da Aliança localizada na costa de Costa Negra.",al={"localização de gershala","onde fica gershala","encontrar gershala umbrurmúrio"}},{q="Por que Gershala quer troncos encefálicos de nagas e sátiros?",a="Gershala estuda troncos encefálicos corrompidos para examinar como uma profunda transformação mágica e demoníaca altera a anatomia de antigos elfos noturnos. Tanto nagas quanto sátiros já foram elfos, e seu objetivo é compreender os mecanismos físicos por trás de sua corrupção.",al={"por que troncos encefálicos","história de pesquisar a corrupção","o que gershala estuda"}},{q="O que Gershala espera alcançar com sua pesquisa?",a="Gershala espera que sua pesquisa forneça percepções cruciais para evitar que os elfos sangrentos degenerem em maldade e deformidades monstruosas devido à sua perigosa dependência da magia vil e do poder arcano descontrolado.",al={"objetivo de gershala","por que ajudar elfos sangrentos","propósito da pesquisa de gershala"}},{q="Onde estão localizados os espécimes de que Gershala precisa?",a="Ele direciona os aventureiros para Profundezas Negras, uma antiga ruína de templo submerso na costa de Vale Gris infestada por nagas e sátiros.",al={"onde estão os troncos encefálicos","troncos encefálicos de profundezas negras","onde encontrar itens de gershala"}}},fx={["19945428"]={q="Quem é Gershala Umbrurmúrio?",a="Gershala Umbrurmúrio é um estudioso elfo noturno que reside no povoado costeiro de Auberdine, em Costa Negra. Movido pela curiosidade acadêmica e preocupação com o mundo mais amplo, ele se dedica a compreender a corrupção mágica e biológica. Ele estuda a anatomia alterada de criaturas distorcidas por poderes sombrios, esperando que um estudo cuidadoso possa evitar quedas semelhantes entre outros povos.",al={"quem é gershala","história de gershala umbrurmúrio","antecedentes de gershala"}},["087b63f5"]={q="Do lado de quem está Gershala Umbrurmúrio?",a="Gershala é aliado dos elfos noturnos de Darnassus e serve como um estudioso amigável para membros da Aliança. Sua pesquisa ocorre em Auberdine, onde ele trabalha para proteger Kalimdor e as raças mortais em geral das ameaças crescentes de degradação demoníaca e mágica.",al={"facção de gershala","gershala é da aliança","lealdade de gershala"}},aee12c2d={q="Por que Gershala Umbrurmúrio está aqui?",a="Gershala faz de Auberdine seu lar porque Costa Negra fica diretamente adjacente a lugares profundamente infestados por males antigos, como as Profundezas Negras. Deste refúgio costeiro, ele pode recrutar viajantes e aventureiros que se aventuram ao sul para coletar espécimes corrompidos para sua pesquisa em andamento.",al={"por que gershala está em auberdine","propósito de gershala em costa negra"}}},fp="21,311,23.550.0,19.411.0,37.111.0,50.251.0,56.201.0,47.138.0"}
P.entries["npc:ghamoo-ra-classic"] = {n="Ghamoo-ra",s="Ghamoo-ra é uma tartaruga marinha gigante e ancestral que habita a Pool of Ask'ar nas Profundezas Negras, o templo submerso de Elune agora dominado pelo culto Twilight's Hammer. Protegido por um casco enorme, ele pisoteia selvagemente quaisquer intrusos que se aproximem de sua ilha.",h="Ghamoo-ra é uma tartaruga marinha gigante e ancestral que habita a Pool of Ask'ar nas Profundezas Negras, o...",kw={"profundezas negras","elune","ghamoo-ra","pool of ask'ar","domar","tartaruga","twilight's hammer"},ang={["class:Druid"]="Os druidas veem em Ghamoo-ra uma criatura ancestral das profundezas, que se tornou selvagem em meio às ruínas do templo profanado.",["class:Hunter"]="Caçadores que se aventuram nas Profundezas Negras podem ter pena de Ghamoo-ra, uma fera nobre e ancestral das profundezas, embora um caçador paciente ainda possa domá-lo.",["race:NightElf"]="Para os elfos noturnos, a presença selvagem de Ghamoo-ra no templo afogado de Elune é um lembrete amargo de quão baixo o local sagrado caiu diante do vil Twilight's Hammer."},sec={{t="Uma Fera do Templo Afogado",b="As Profundezas Negras já foram um templo de elfos noturnos dedicado a Elune, agora inundado e reivindicado por nagas, sátiros e pelo culto niilista Twilight's Hammer. Ghamoo-ra habita entre suas ruínas afogadas, uma tartaruga enorme cujo casco espesso repele todos os golpes, exceto os mais determinados."},{t="Guardião das Profundezas",b="Ghamoo-ra percorre uma pequena ilha na Pool of Ask'ar, cercado por tartarugas menores que deixam os viajantes em paz. Apenas ele ataca, esmagando qualquer um que se aproxime sob sua massa pisoteadora."}},faq={{q="Quem é Ghamoo-ra?",a="Ghamoo-ra é uma tartaruga gigante encontrada na Pool of Ask'ar, nas Profundezas Negras, o templo inundado de Elune agora controlado pelo Twilight's Hammer. Ele ataca qualquer um que se aproxime de sua ilha.",al={"história de ghamoo-ra","tartaruga gigante bfd","quem é ghamoo ra"}},{q="Por que Ghamoo-ra é hostil a estranhos?",a="Não há registros de como ele se tornou tão selvagem. Ele simplesmente ataca qualquer um que invada sua ilha na Pool of Ask'ar, pisoteando todos os que se aproximam.",al={"por que a tartaruga está brava","por que a tartaruga ataca","loucura de ghamoo-ra"}},{q="Um caçador pode domar Ghamoo-ra?",a="Sim. Apesar de seu tamanho e anos de tormento, Ghamoo-ra pode ser domado por um caçador habilidoso.",al={"domar ghamoo-ra","caçador pode domar tartaruga de bfd"}},{q="O que é a Pool of Ask'ar?",a="A Pool of Ask'ar é uma caverna subterrânea inundada nas Profundezas Negras. Ghamoo-ra percorre o centro de uma pequena ilha no local, cercado por tartarugas nativas dóceis.",al={"pool of ask'ar","onde fica ghamoo ra"}},{q="Que ligação ele tem com os Old Gods?",a="Não há registro de nenhuma. Ghamoo-ra é uma fera das profundezas, embora os cultistas do Twilight's Hammer que adoram os Old Gods tenham dominado o templo submerso ao seu redor.",al={"ghamoo-ra old gods","a tartaruga está corrompida"}}},fx={["650cf597"]={q="De que lado Ghamoo-ra está?",a="Ghamoo-ra não serve a ninguém. Ele é uma fera selvagem das profundezas que ataca qualquer um que se aproxime de sua ilha na Pool of Ask'ar, dentro do templo inundado que o Martelo do Crepúsculo agora ocupa.",al={"facção de ghamoora","a quem ghamoo-ra serve","ghamoo-ra é do martelo do crepúsculo"}},ff96574e={q="O que Ghamoo-ra quer?",a="Ghamoo-ra não tem grandes ambições próprias. A tartaruga gigante simplesmente avança para esmagar intrusos que chegam perto de sua ilha na Pool of Ask'ar.",al={"objetivo de ghamoora","o que a tartaruga quer","motivo de ghamoora"}},f3d3c23f={q="Por que Ghamoo-ra está aqui?",a="Ghamoo-ra habita uma pequena ilha na Pool of Ask'ar, nas profundezas de Profundezas Negras, o templo inundado de Elune agora tomado por nagas, sátiros e pelo Martelo do Crepúsculo. Como ele foi parar lá não há registro.",al={"por que ghamoo-ra está em profundezas negras","ghamoo-ra pool of ask'ar por quê","por que há uma tartaruga gigante aqui"}}},fp="9,255,29.275.0,21.180.0,17.189.0,38.155.0,28.87.0,27.161.0,45.157.0"}
P.entries["npc:gilnid"] = {n="Gilnid",s="Gilnid, conhecido como o Fundidor, é o mestre engenheiro goblin que comanda as forjas nas profundezas das Minas Mortas. Ele supervisiona a fundição do minério bruto em metal refinado e munições para o encouraçado oculto de Edwin VanCleef. Sem as suas operações abrasadoras, a Irmandade Défias não teria os canhões pesados necessários para atacar Ventobravo.",h="Gilnid, conhecido como o Fundidor, é o mestre engenheiro goblin que comanda as forjas nas profundezas das...",kw={"canhoes","minas mortas","defias","forja","fundicao","gilnid","goblin","encouracado","fundidor","vancleef"},ang={["faction:Alliance"]="Deter Gilnid interrompe a linha de montagem de armas dos Défias, impedindo que o navio de guerra de VanCleef seja totalmente armado antes de poder ameaçar o Porto de Ventobravo.",["profession:Engineering"]="A fundição de Gilnid é um exemplo primordial da indústria pesada goblin, produzindo canhões navais padronizados, munição e placas estruturais sob condições extremas.",["profession:Mining"]="Os enormes altos-fornos e caldeirões de fundição na oficina de Gilnid mostram como a Irmandade Défias transforma a riqueza mineral bruta de Cerro Oeste em ferro refinado e armamentos."},sec={{t="Mestre da Fundição",b="Nas profundezas das Minas Mortas, a Irmandade Défias depende de perícia industrial para forjar armas de guerra. Gilnid atua como o fundidor-chefe de VanCleef, comandando um pequeno exército de operários, engenhoqueiros e ferreiros goblins na fundição central. Mais alto do que a maioria dos seus semelhantes, ele comanda a sua equipe impiedosamente através de fumaça e escória, gritando ordens e recusando pausas para garantir que o minério de ferro bruto seja transformado em blindagens pesadas e munições letais."},{t="Armando o Encouraçado",b="Os trabalhos de fundição são cruciais para as grandes ambições da Irmandade. Gilnid é diretamente responsável por forjar os canhões pesados e a munição destinados ao colossal navio de guerra encouraçado atracado na enseada subterrânea além de sua oficina. Até que a sua fundição produza cada canhão, cano e bala, o navio Défias continuará despreparado para o ataque planejado contra Ventobravo."}},faq={{q="Quem é Gilnid?",a="Gilnid é um engenheiro goblin e o fundidor-chefe de Edwin VanCleef nas Minas Mortas. Ele supervisiona as forjas da Irmandade e lidera o esforço industrial para fundir canhões e munições para a sua máquina de guerra.",al={"gilnid minas mortas","quem e gilnid","o fundidor"}},{q="Por que Gilnid está nas Minas Mortas?",a="A Irmandade Défias contratou engenheiros mercenários goblins para construir e suprir o seu navio de guerra oculto. Gilnid foi colocado no comando dos trabalhos de fundição, transformando o minério de ferro extraído em peças refinadas, blindagem e artilharia.",al={"por que tem um goblin nas minas mortas","historia de gilnid defias","o que gilnid esta fazendo"}},{q="No que Gilnid está trabalhando?",a="Gilnid é responsável por fabricar os canhões colossais, peças de navio e projéteis necessários para armar o encouraçado escondido nas docas, mais ao fundo das minas.",al={"canhao de gilnid","o que gilnid esta construindo","proposito da forja de minas mortas"}},{q="Por que Gilnid deve ser derrotado?",a="Gilnid controla a fundição industrial que bloqueia o caminho para a enseada. As portas blindadas pesadas que levam até as profundezas em direção ao navio Défias permanecem seladas até que a sala de fundição seja protegida.",al={"por que matar gilnid","porta apos gilnid"}},{q="Gilnid trabalha diretamente para Edwin VanCleef?",a="Sim. Ele não é um membro dos Stonemasons originais, mas sim um especialista goblin contratado que serve diretamente sob o comando de VanCleef para lidar com metalurgia pesada e produção de armas.",al={"vancleef e gilnid","gilnid e lider defias"}},{q="Por que há tantos goblins ao redor dele?",a="Gilnid lidera uma equipe especializada de engenharia goblin na fundição. Eles operam os altos-fornos, despejam ferro derretido e montam munições sob sua supervisão rígida e incansável.",al={"goblins de gilnid","equipe da forja de minas mortas"}}},fx={["1c6d7566"]={q="Do lado de quem está Gilnid?",a="Gilnid está firmemente alinhado com a Irmandade Défias. Embora os goblins sejam tipicamente conhecidos por seus contratos mercenários independentes e neutralidade, Gilnid comprometeu seus formidáveis talentos metalúrgicos à causa rebelde de Edwin VanCleef, servindo como um capataz-chefe nas profundezas da fortaleza subterrânea da irmandade.",al={"facção de gilnid","gilnid e a irmandade défias","por quem gilnid luta"}},["88f08ccf"]={q="O que Gilnid deseja?",a="Gilnid não quer nada além de ver o navio de guerra da Irmandade Défias totalmente equipado e operacional. Como fundidor-chefe, seu objetivo primordial é garantir que cada canhão, cápsula e munição pesada seja forjada com perfeição, forçando seus trabalhadores goblins impiedosamente e sem descanso até que o enorme navio de guerra esteja pronto para navegar.",al={"objetivo de gilnid","o que gilnid está tentando fazer","motivação de gilnid"}}},fp="6,339,21.433.0,21.374.1,14.208.0,31.218.0,26.155.0,28.179.0,45.177.0,41.182.0"}
P.entries["npc:gilshalan-windwalker"] = {n="Gilshalan Andavento",s="Gilshalan Andavento é um pesquisador elfo noturno descansando na base da grande árvore Aldrassil em Umbravale. Preocupado com a súbita corrupção que se enraíza em Teldrassil, ele estuda a fauna local para compreender a agressividade não natural que assola os galhos. Suas investigações sobre as aranhas Lenhateia fornecem as primeiras pistas sobre a podridão que aflige a Árvore do Mundo.",h="Gilshalan Andavento é um pesquisador elfo noturno descansando na base da grande árvore Aldrassil em Umbravale.",kw={"aldrassil","gilshalan","umbravale","aranha","tenaron","peçonha","lenhateia","andavento"},ang={["class:Druid"]="Sua pesquisa apoia diretamente as tentativas do Círculo Cenariano de diagnosticar o desequilíbrio ecológico que se agrava nos galhos de Umbravale.",["race:NightElf"]="Gilshalan representa os esforços iniciais do seu povo para entender por que a recém-cultivada Árvore do Mundo já está gerando uma fauna aflita e violenta."},sec={{t="Um Erudito nas Raízes",b="Sentado calmamente nos degraus de pedra que levam a Aldrassil, Gilshalan Andavento observa o dossel tranquilo de Umbravale com crescente inquietação. Teldrassil foi plantada para restaurar o santuário perdido e a harmonia dos elfos noturnos com a natureza, mas sinais de um profundo mal-estar espiritual surgiram quase imediatamente. Gilshalan se dedica a examinar como essa corrupção se manifesta nas feras locais, a começar pelos aracnídeos peçonhentos que tecem suas teias por perto."},{t="A Ameaça dos Lenhateia",b="O foco principal de Gilshalan centra-se nas aranhas Lenhateia à espreita na Caverna Fionumbra, ao norte. Essas criaturas, outrora uma parte equilibrada do ecossistema da floresta, tornaram-se extraordinariamente hostis e corrompidas. Ao enviar jovens noviços para coletar bolsas de peçonha e ovos intactos de aranha, Gilshalan trabalha para analisar a potência alterada do veneno e discernir se a corrupção é transmitida através de gerações ou disseminada externamente através do solo de Teldrassil."},{t="Palavra ao Arquidruida",b="Com a peçonha e um ovo em mãos, Gilshalan acredita que o veneno das aranhas mostrará propriedades ligadas ao crescimento recente da nova Árvore do Mundo. Ele providencia para que os espécimes sejam enviados a Darnassus, onde continuará seus estudos. Ele também avisa protetores promissores de que Tenaron Fortagarras esteve perguntando por eles na sala mais alta de Aldrassil, onde a liderança druídica vigia a incipiente Árvore do Mundo."}},faq={{q="Quem é Gilshalan Andavento?",a="Gilshalan Andavento é um erudito elfo noturno sentado na base de Aldrassil em Umbravale. Ele investiga a misteriosa corrupção que se espalha pela fauna de Teldrassil.",al={"gilshalan","quem é gilshalan","elfo noturno andavento"}},{q="Por que Gilshalan quer Peçonha de lenhateia?",a="Gilshalan busca estudar as propriedades químicas e espirituais da peçonha para entender por que as aranhas da floresta se tornaram tão agressivas e sofreram mutações.",al={"por que peçonha de lenhateia","missão peçonha de lenhateia","veneno de aranha gilshalan"}},{q="O que ele faz com o Ovo de Lenhateia?",a="Ele quer espécimes vivos para estudar, mas uma aranha gigante adulta é perigosa demais para ser capturada. Um ovo que ainda não eclodiu é muito mais fácil de transportar, então ele o envia para Darnassus junto com a peçonha, onde os filhotes podem ser contidos e estudados.",al={"missão ovo de lenhateia","por que ovos de aranha","ovo de lenhateia"}},{q="Para onde Gilshalan envia os aventureiros em seguida?",a="Após a entrega do ovo, ele diz aos aventureiros que Tenaron Fortagarras esteve perguntando por eles e os envia para a sala mais alta no topo de Aldrassil.",al={"convocação de tenaron","quem procurar depois de gilshalan","depois do ovo de lenhateia"}},{q="Onde Gilshalan Andavento está localizado?",a="Ele fica sentado no caminho de pedra na base norte de Aldrassil, logo do lado de fora da entrada oca da árvore central em Umbravale.",al={"localização de gilshalan","onde fica andavento","encontrar gilshalan"}},{q="Por que a fauna de Teldrassil está agressiva?",a="Uma praga desconhecida começou a se infiltrar pelas raízes e pelo solo de Teldrassil, corrompendo a mente e a natureza de suas criaturas e despertando a preocupação de estudiosos como Gilshalan.",al={"por que as aranhas estão enfurecidas","corrupção de teldrassil","feras corrompidas de umbravale"}}},fx={["4b23360a"]={q="Do lado de quem está Gilshalan Andavento?",a="Gilshalan está firmemente ao lado de seus companheiros elfos noturnos e da Aliança. Postado nas raízes de Aldrassil dentro de Umbravale, ele ajuda jovens aventureiros a compreender e combater as estranhas forças corruptoras que afligem a vida selvagem local de Teldrassil.",al={"facção de gilshalan","a quem gilshalan serve","gilshalan andavento e a aliança"}},["61ec761c"]={q="Por que Gilshalan Andavento está aqui?",a="Ele senta na base de Aldrassil para monitorar a mancha emergente em Umbravale. Ao estudar amostras de veneno e ovos não eclodidos das agitadas aranhas Webwood, Gilshalan busca descobrir o que está envenenando a harmonia natural da grande árvore do mundo.",al={"por que gilshalan está em umbravale","objetivo de gilshalan andavento em aldrassil"}},ba2e5485={q="A quem Gilshalan Andavento está ligado?",a="Gilshalan responde a Tenaron Fortagarras, um dos druidas anciãos estacionados bem acima, nos galhos de Aldrassil. Assim que suas investigações iniciais sobre as aranhas Webwood terminam, ele direciona recrutas promissores a Tenaron para continuar ajudando na defesa de Teldrassil.",al={"a quem gilshalan responde","gilshalan e tenaron","conexões de gilshalan"}}},fp="20,370,22.466.0,18.458.0,21.429.1,28.174.0,38.153.0,37.236.0,43.151.0,38.131.0,45.187.0"}
P.entries["npc:gilthares-firebough"] = {n="Gilthares Galhareda",s="Gilthares Galhareda é um marinheiro de convés élfico mantido em cativeiro no alto de uma torre dentro da Fortaleza da Guardanorte. Anteriormente contratado pelos Thalo'dan Privateers a bordo de um transporte de bebida clandestina entre a Vila Catraca e a Angra do Butim, ele busca qualquer oportunidade para escapar de seus captores de Theramore.",h="Gilthares Galhareda é um marinheiro de convés élfico mantido em cativeiro no alto de uma torre dentro da...",kw={"angra do butim","free from the hold","gilthares galhareda","fortaleza da guardanorte","vila catraca","corsários thalo'dan"},ang={["faction:Alliance"]="Embora inicialmente indiferente aos transeuntes, Gilthares nutre intensa hostilidade em relação aos marinheiros da Aliança que destruíram sua embarcação e o trancafiaram em uma cela.",["faction:Horde"]="Escoltar Gilthares para longe da Guardanorte desfere um golpe fácil contra a agressão de Theramore ao longo da costa dos Sertões."},sec={{t="Um contrabandista atrás das grades",b="Enquanto transportava carga ilícita entre a Vila Catraca e a Angra do Butim, Gilthares Galhareda viu seu navio ser reduzido a estilhaços por forças navais de Theramore. Como único sobrevivente do ataque, o corsário foi arrastado para a costa acorrentado e trancafiado em uma torre dentro da Fortaleza da Guardanorte. Embora vestido de vermelho vivo e nutrindo pouca afeição pelos fanáticos da Aliança que massacraram sua tripulação, Gilthares não é exigente quanto a quem o ajuda em sua fuga — desde que consigam lutar para descer pelas muralhas."}},faq={{q="Quem é Gilthares Galhareda?",a="Gilthares é um marinheiro de convés élfico afiliado aos Thalo'dan Privateers. Ele foi capturado quando forças da Guardanorte interceptaram e afundaram seu navio mercante na costa dos Sertões.",al={"quem é gilthares","história de gilthares","quem é este elfo"}},{q="Por que ele está preso na Fortaleza da Guardanorte?",a="Gilthares estava servindo a bordo de um transporte que carregava bebida clandestina entre a Vila Catraca e a Angra do Butim. Soldados de Theramore afundaram o navio, mataram o restante da tripulação e prenderam Gilthares na Fortaleza da Guardanorte como carga contrabandeada e prisioneiro de guerra.",al={"por que ele está preso","por que em uma gaiola","prisioneiro da guardanorte"}},{q="Gilthares é um elfo caquético ou um elfo sangrento?",a="Gilthares é um elfo que trabalha como marinheiro independente em vez de servir à Aliança ou aos governantes de Luaprata. Embora suas roupas vermelhas sejam frequentemente associadas aos sin'dorei, ele serve a corsários em vez de a qualquer facção nacional.",al={"que tipo de elfo é gilthares","elfo supremo ou elfo sangrento","raça de gilthares"}},{q="Quem são os Thalo'dan Privateers?",a="Os Thalo'dan Privateers são uma organização marítima independente envolvida em operações de contrabando pelo Grande Oceano, incluindo a lucrativa rota de bebida clandestina ligando a Vila Catraca à Angra do Butim.",al={"corsários thalo'dan","para quem ele trabalha","tripulação de gilthares"}}},fx={["4d14e07a"]={q="De que lado está Gilthares Galhareda?",a="Gilthares não se alinha nem à Horda nem à Aliança. Ele é um marinheiro independente afiliado aos Corsários Thalo'dan, um grupo de navegação livre que opera ao longo das rotas comerciais entre Vila Catraca e Angra do Butim. Embora ele não nutra nenhum amor especial pela Horda, sua captura violenta e escravização severa pelas mãos de fanáticos de Theramore o tornaram abertamente hostil às forças da Aliança que ocupam a Fortaleza da Guardanorte.",al={"facção de gilthares galhareda","gilthares é da horda ou da aliança","lealdade de gilthares"}},["84aa2a4b"]={q="O que Gilthares Galhareda quer?",a="Gilthares não quer nada além de se libertar de sua jaula na Fortaleza da Guardanorte e escapar dos fanáticos que o capturaram. Tendo sobrevivido à destruição violenta de seu transporte de luar ilegal apenas para ser trancado em uma torre costeira, ele está desesperado por alguém capaz de abrir um caminho pela guarnição para que ele possa fugir do cativeiro deles.",al={"objetivo de gilthares galhareda","o que gilthares quer"}}},fp="19,254,22.498.0,27.182.0,40.239.0,39.241.0,33.187.0"}
P.entries["npc:glorin-steelbrow"] = {n="Glorin Testaço",s="Glorin Testaço é um operativo anão encontrado bebendo na Taberna Aguafunda, no Porto de Menethil. Atuando como associado do Bispo Palhares da Catedral da Luz de Ventobravo, ele ajuda aventureiros a investigar a perdida terceira frota e a recuperar relíquias e materiais sagrados espalhados pela costa dos Pantanais. Seus esforços conectam a natureza assombrada da Floresta do Crepúsculo diretamente aos destroços naufragados do norte.",h="Glorin Testaço é um operativo anão encontrado bebendo na Taberna Aguafunda, no Porto de Menethil.",kw={"bispo palhares","taberna aguafunda","a esquadra naufragada","floresta do crepúsculo","olho de paleth","glorin testaço","ferro da forja de luz","porto de menethil","pantanais"},ang={["class:Paladin"]="Paladinos sob as ordens de Farthing acharão Glorin indispensável na recuperação do Ferro da Forja de Luz, um metal sagrado essencial para forjar armas abençoadas pela Luz Sagrada.",["faction:Alliance"]="Glorin tem papel fundamental no resgate de relíquias militares cruciais da Aliança e de materiais santificados perdidos durante desastres navais nos Pantanais.",["race:Dwarf"]="Glorin representa a iniciativa e a solidariedade dos anões, coordenando ações a partir do centro marítimo do Porto de Menethil para apoiar aliados por toda Khaz Modan e pelos reinos humanos do sul."},sec={{t="Uma Conexão Portuária",b="Enquanto o Bispo Palhares ajuda o povo da Floresta do Crepúsculo contra seus terrores rastejantes a partir da Catedral da Luz de Ventobravo, ele mantém laços bem ao norte, no Porto de Menethil. Posicionado dentro da movimentada Taberna Aguafunda, Glorin Testaço atua como os olhos e as mãos de Farthing na costa. Ele oferece ajuda e orientação a viajantes enviados ao norte em busca de metais sagrados e relíquias esquecidas, servindo como uma ponte crucial entre os problemas da floresta do sul e os destroços submersos dos Pantanais."},{t="A Esquadra Naufragada e as Relíquias Perdidas",b="Testaço conhece intimamente a tragédia da terceira frota, cujos navios foram castigados e arrastados para sob as ondas ao longo da costa dos Pantanais. Ele guia aventureiros a vasculharem os destroços assombrados em busca de lingotes perdidos de Ferro da Forja de Luz e do poderoso e amaldiçoado artefato conhecido como o Olho de Paleth. Glorin sabe que recuperar esses armamentos sagrados é vital para forjar armas capazes de conter as forças sombrias que ameaçam a Aliança."}},faq={{q="Quem é Glorin Testaço?",a="Glorin Testaço é um anão estabelecido na Taberna Aguafunda, no Porto de Menethil. Ele trabalha em coordenação com o Bispo Palhares de Ventobravo, auxiliando aventureiros que viajam para o norte a resgatar cargas e relíquias naufragadas na costa dos Pantanais.",al={"quem é glorin","história de glorin testaço","o que glorin faz"}},{q="Onde posso encontrar Glorin Testaço?",a="Glorin fica no térreo da Taberna Aguafunda, no Porto de Menethil, localizado na costa oeste dos Pantanais.",al={"localização de glorin","onde fica glorin testaço","glorin taberna aguafunda"}},{q="Por que um anão no Porto de Menethil está envolvido com a Floresta do Crepúsculo?",a="O Bispo Palhares, da Catedral da Luz de Ventobravo, busca relíquias sagradas poderosas e metais consagrados para combater a escuridão que se espalha pela Floresta do Crepúsculo. Ele envia emissários de confiança a Glorin Testaço, que conhece a costa dos Pantanais e pode direcionar exploradores aos restos submersos da terceira frota.",al={"por que missão da floresta do crepúsculo nos pantanais","ligação com farthing","por que enviar aos pantanais"}},{q="O que é a terceira frota mencionada por Glorin?",a="A terceira frota foi uma expedição naval da Aliança que enfrentou uma catástrofe na costa dos Pantanais. Seus cascos despedaçados agora cobrem o fundo do mar, assombrados por marinheiros afogados e escondendo cargas valiosas como Ferro da Forja de Luz e artefatos antigos.",al={"o que é a esquadra naufragada","a terceira frota pantanais","missão a esquadra naufragada"}},{q="O que é o Olho de Paleth?",a="O Olho de Paleth é uma antiga relíquia religiosa transportada a bordo da frota naufragada. Uma vez recuperada do fundo do oceano com a ajuda de Glorin, ela precisa passar por purificação pelo sacerdócio devido à corrupção sombria que paira sobre o naufrágio.",al={"olho de paleth","relíquia de paleth","o que é olho de paleth"}},{q="Para que serve o Ferro da Forja de Luz?",a="O Ferro da Forja de Luz é um metal raro e santificado usado para criar armas abençoadas capazes de abater forças poderosas de mortos-vivos e demônios. Glorin ajuda a recuperar lingotes perdidos dos naufrágios para apoiar os defensores da Floresta do Crepúsculo.",al={"ferro da forja de luz","lingotes perdidos","braço abençoado"}}},fx={["65727266"]={q="De que lado está Glorin Testaço?",a="Glorin está firmemente ao lado da Aliança e da Igreja da Luz Sagrada. Estacionado no Porto de Menethil, ele trabalha em coordenação com líderes como o Bispo Palhares de Ventobravo, buscando ajuda de aventureiros confiáveis da Aliança para recuperar relíquias santificadas e materiais perdidos ao longo das costas traiçoeiras.",al={"facção de glorin testaço","a quem glorin testaço serve","aliança de glorin testaço"}},cbae8fd4={q="O que Glorin Testaço quer?",a="Glorin quer recuperar carga sagrada perdida reivindicada pelo mar, particularmente carregamentos transportados pela Terceira Frota naufragada. Seus esforços concentram-se em recrutar aventureiros para recuperar raros lingotes de Lightforge Iron e relíquias sagradas como o The Eye of Paleth, garantindo que sejam purificados e devolvidos à Igreja.",al={"do que glorin testaço precisa","objetivo de glorin testaço","o que glorin testaço procura"}},["72c86ba2"]={q="A quem Glorin Testaço está ligado?",a="Glorin é um associado do Bispo Palhares da Catedral da Luz de Ventobravo. Ele coordena diretamente com o clero de Ventobravo para garantir relíquias sagradas perdidas, atuando como seu representante no porto do Pantanal para resgatar carregamentos destinados ou perdidos dos esforços da igreja.",al={"conexões de glorin testaço","quem glorin testaço conhece","glorin testaço e bispo palhares"}}},fp="16,405,19.496.0,32.444.1,24.239.0,34.128.0,57.294.0,48.240.0,26.243.0,33.221.0"}
P.entries["npc:gnoarn"] = {n="Gnoarn",s="Gnoarn é um gnomo exilado que reside em Beco da Gambiarra, dentro da cidade montanhosa anã de Altaforja. Deslocado após a queda devastadora de Gnomeregan, ele ajuda seu povo disperso orientando aventureiros a auxiliarem outros sobreviventes e engenheiros gnômicos.",h="Gnoarn é um gnomo exilado que reside em Beco da Gambiarra, dentro da cidade montanhosa anã de Altaforja.",kw={"gomez plosivo","gnoarn","gnomefro","gnomeregan","altaforja","shoni, a shilenchiosa","beco da gambiarra"},ang={["faction:Alliance"]="Heróis da Aliança que passam por Altaforja podem falar com Gnoarn para obter pistas sobre iniciativas críticas de engenharia gnômica em andamento por Dun Morogh, Loch Modan e Ventobravo.",["race:Gnome"]="Para os seus companheiros gnomos, Gnoarn personifica a resiliência da comunidade de refugiados em Beco da Gambiarra, garantindo que os engenheiros deslocados mantenham comunicação pelos Reinos do Leste."},sec={{t="Um Cidadão Deslocado de Gnomeregan",b="Como a maioria de seus irmãos, Gnoarn foi forçado a fugir das profundezas de Gnomeregan quando os troggs invadiram e a radiação catastrófica tornou inabitável a grande metrópole subterrânea. Refugiando-se em Beco da Gambiarra, em Altaforja, sob a hospitalidade dos anões Barbabronze, Gnoarn passa seus dias acompanhando outros sobreviventes. Ele atua como um coordenador informal entre os refugiados, direcionando viajantes capazes a gnomos em terras distantes que precisam urgentemente de ajuda, como o piloto isolado Gomez Plosivo em Loch Modan ou a ambiciosa engenheira Shoni, a Shilenchiosa em Ventobravo."}},faq={{q="Quem é Gnoarn?",a="Gnoarn é um sobrevivente gnômico que vive entre a população de refugiados em Beco da Gambiarra, o bairro gnômico de Altaforja. Ele orienta viajantes a ajudarem outros gnomos exilados que trabalham em vários projetos pelas terras da Aliança.",al={"quem é este gnomo","história de gnoarn","pnj gnoarn"}},{q="Onde Gnoarn pode ser encontrado?",a="Ele pode ser encontrado em Beco da Gambiarra, localizada na seção nordeste de Altaforja, cercado pelas engrenagens, maquinários zumbidores e bancadas de trabalho de seus parentes exilados.",al={"localização de gnoarn","onde fica gnoarn","encontrar gnoarn"}},{q="Quais tarefas Gnoarn oferece?",a="Gnoarn orienta aventureiros a auxiliarem outros gnomos dispersos. Notavelmente, ele envia aventureiros a Loch Modan para verificar o paradeiro do piloto desaparecido Gomez Plosivo e despacha viajantes a Ventobravo para falar com a inventora Shoni, a Shilenchiosa sobre seus Escavacionadores girobrocamáticos.",al={"missões de gnoarn","o que gnoarn quer"}},{q="O que aconteceu com o cabelo de Gnoarn?",a="Antes da queda de Gnomeregan, Gnoarn era conhecido por ostentar um excêntrico penteado 'gnomefro'. Tragicamente, ele perdeu sua cabeleira distinta após a precipitação catastrófica e a ventilação radioativa que devastaram sua cidade natal.",al={"gnomefro de gnoarn","cabelo de gnoarn"}}},fx={["38923b37"]={q="De que lado está Gnoarn?",a="Gnoarn é leal aos seus companheiros gnomos de Gnomeregan e à Grande Aliança. Residindo entre a população gnomica deslocada no Beco da Gambiarra, ele trabalha para manter sua comunidade organizada e conectada com seus aliados em Altaforja.",al={"facção de gnoarn","gnoarn é da aliança","a quem gnoarn serve"}},ce7102b3={q="Por que Gnoarn está em Altaforja?",a="Como milhares de outros gnomos, Gnoarn foi expulso de seu lar após a queda de Gnomeregan. Quando troggs invadiram a maravilha tecnológica subterrânea e a radiação tóxica poluiu seus corredores, os sobreviventes fugiram para cima para buscar santuário entre seus primos anões em Altaforja, construindo um lar no Beco da Gambiarra.",al={"por que gnoarn está aqui","por que gnoarn veio para altaforja","o que trouxe gnoarn para altaforja"}},["82a3a1ba"]={q="O que Gnoarn quer?",a="Gnoarn está preocupado com a segurança e o paradeiro de seus parentes deslocados. Na confusão após a evacuação de Gnomeregan, ele procura por camaradas desaparecidos como Gomez Plosivo e direciona aventureiros capazes para ajudar inventores e especialistas proeminentes como Shoni, a Shilenchiosa.",al={"o que gnoarn está tentando fazer","objetivos de gnoarn","do que gnoarn precisa"}},efead32c={q="A quem Gnoarn está ligado?",a="Gnoarn mantém laços estreitos com outros sobreviventes de Gnomeregan em Altaforja, notavelmente fazendo a ligação com a renomada inventora Shoni, a Shilenchiosa e coordenando esforços para localizar outros refugiados como Gomez Plosivo.",al={"aliados de gnoarn","quem gnoarn conhece","conexões de gnoarn"}}},fp="6,259,33.597.0,14.214.0,26.161.0,32.286.0,31.230.0"}
P.entries["npc:godrick-farsan"] = {n="Godofredo Fasano",s="Godofredo Fasano é um assistente de bruxo morto-vivo localizado na Cidade Baixa, servindo ao lado de Silvério Hidalgo no Distrito da Magia. Apesar de ser totalmente cego, ele diz que enxerga de uma maneira diferente.",h="Godofredo Fasano é um assistente de bruxo morto-vivo localizado na Cidade Baixa, servindo ao lado de Silvério...",kw={"silvério hidalgo","godofredo fasano","hearts of the pure","strahad farsan","súcubo","cidade baixa","bruxo"},ang={["class:Warlock"]="Bruxos Renegados que procuram dominar a arte de evocar uma súcubo devem consultar Godofredo para preparar as iscas necessárias e compreender a natureza devoradora dos servos demoníacos.",["race:Undead"]="Godofredo exemplifica a filosofia dos bruxos Renegados, abraçando a ruína física e a cegueira enquanto aprimora uma percepção mágica sombria para substituir as fragilidades mortais."},sec={{t="Olhos no Escuro",b="Situado em meio aos círculos de evocação do Distrito da Magia, Godofredo Fasano ajuda o Mestre Silvério Hidalgo a guiar aspirantes a bruxos Renegados. Embora não tenha a visão física, Godofredo diz que ainda consegue enxergar de uma maneira diferente, sem explicar os meios. Ele testa praticantes que buscam aprisionar entidades demoníacas maiores, enviando-os para coletar corações puros e essências necessárias para rituais complexos de evocação."}},faq={{q="Quem é Godofredo Fasano?",a="Godofredo Fasano é um bruxo Renegado situado no Distrito da Magia da Cidade Baixa. Ele atua como assistente do Mestre Silvério Hidalgo, auxiliando na instrução e nos rituais de bruxos novatos.",al={"godofredo fasano","quem é godofredo"}},{q="Como Godofredo pode enxergar se é cego?",a="Godofredo diz que enxerga de uma maneira diferente, apesar de sua cegueira. Os meios exatos não são explicados.",al={"godofredo é cego","como godofredo enxerga"}},{q="Godofredo é parente de Strahad Farsan?",a="Eles compartilham um sobrenome, mas nenhum parentesco é confirmado.",al={"relação com strahad farsan","irmão de strahad farsan","godofredo e strahad são parentes"}},{q="Qual papel ele desempenha no treinamento de bruxos?",a="Godofredo ajuda a supervisionar os ritos de aprisionamento para bruxos, guiando-os especificamente em tarefas como a obtenção de corações puros para atrair e aprisionar uma súcubo.",al={"missões de bruxo de godofredo","missão hearts of the pure"}}},fx={["5d2f41c4"]={q="De que lado está Godofredo Fasano?",a="Godofredo é leal aos Renegados e à Dama Sombria, habitando profundamente na Cidade Baixa. Ele serve ao lado de Silvério Hidalgo, ajudando praticantes das artes das trevas e guiando bruxos da Horda que buscam dominar poderes demoníacos.",al={"lealdade de godofredo fasano","a quem godofredo serve","facção de godofredo fasano"}},f8f4201c={q="Por que Godofredo Fasano está aqui?",a="Você encontrará Godofredo espreitando nos bairros sombrios da Cidade Baixa como o devotado assistente de Silvério Hidalgo. Ele permanece estacionado aqui para supervisionar testes para aspirantes a bruxos, ajudando-os a conjurar entidades demoníacas potentes, como a súcubo.",al={"por que godofredo está na cidade baixa","objetivo de godofredo fasano na cidade baixa","o que godofredo fasano está fazendo aqui"}},["57b226ed"]={q="O que Godofredo Fasano quer?",a="Godofredo busca promover os estudos sombrios dos bruxos da Cidade Baixa. Por meio de testes exaustivos envolvendo componentes rituais — como os corações dos puros e dos inocentes — ele testa sua determinação e capacidade de comandar demônios perigosos da Distorção.",al={"objetivo de godofredo fasano","o que godofredo quer","motivos de godofredo fasano"}}},fp="14,198,16.410.0,22.199.0,35.104.0,37.60.0,43.152.0"}
P.entries["npc:golnir-bouldertoe"] = {n="Golnir Topadão",s="Golnir Topadão é um vendedor de mineração anão estacionado ao lado da movimentada A Grande Forja em Altaforja. Ele fornece suprimentos essenciais para mineradores e prospectores enquanto lida com despachos para mensageiros locais e viajantes.",h="Golnir Topadão é um vendedor de mineração anão estacionado ao lado da movimentada A Grande Forja em Altaforja.",kw={"bouldertoe","carvão","fluxo","golnir","a grande forja","altaforja","fornecedor de mineração"},ang={["profession:Mining"]="Mineradores visitando a Grande Forja contam com Golnir para ferramentas vitais do ofício, incluindo picaretas extras e fluxos necessários para fundir veios brutos em barras refinadas.",["race:Dwarf"]="Para anões retornando de suas primeiras jornadas em Coldridge ou Kharanos, Golnir serve como um contato inicial na capital, dando boas-vindas aos viajantes bem ao lado do coração ardente da montanha."},sec={{t="Mercador da Grande Forja",b="Permanecendo dentro do calor intenso da Grande Forja de Altaforja, Golnir Topadão equipa prospectores e artesãos com as necessidades de seu ofício. De picaretas de mineração resistentes a fluxos e carvão, seus produtos alimentam os incansáveis fogos de fundição e forjas que definem a capital anã. Parente de Geofram Bouldertoe, Golnir é um ponto de contato confiável para trabalhadores que chegam à cidade, frequentemente orientando recém-chegados ou recebendo missivas de suprimentos enviadas de postos avançados próximos."}},faq={{q="Onde posso encontrar Golnir Topadão?",a="Golnir Topadão está localizado na Grande Forja em Altaforja, ficando perto das áreas centrais de fundição e ferraria ao lado de outros mercadores.",al={"localização de golnir","onde fica golnir","golnir topadão altaforja"}},{q="Que mercadorias Golnir vende?",a="Ele serve como um fornecedor de mineração, vendendo equipamentos comerciais essenciais, como picaretas de mineração, carvão e fluxos, para ajudar prospectores a cavar e refinar minério bruto.",al={"mercadorias do vendedor golnir","o que golnir vende","inventário de golnir"}},{q="Golnir Topadão está envolvido em alguma missão?",a="Sim. Missões de mensageiro conectando assentamentos anões vizinhos à capital, como tarefas envolvendo Grif Trovino e voos que chegam de postos avançados como Thelsamar, direcionam viajantes a entregar mensagens diretamente nas mãos de Golnir.",al={"missões de golnir","carona para altaforja golnir"}},{q="Golnir tem parentesco com mais alguém em Dun Morogh?",a="Golnir compartilha seu nome de clã com Geofram Bouldertoe, o instrutor de mineração que trabalha ao lado dele na Grande Forja de Altaforja.",al={"família bouldertoe","parente de geofram bouldertoe"}}},fx={["5f6dd933"]={q="Quem é Golnir Topadão?",a="Golnir Topadão é um mercador anão que trabalha como fornecedor de mineração dentro de A Grande Forja de Altaforja. Ele fornece provisões essenciais, picaretas e suprimentos de fundição para os garimpeiros e ferreiros que trabalham no coração derretido da cidade.",al={"quem é golnir","história de golnir topadão","identidade de golnir"}},b602f757={q="De que lado está Golnir Topadão?",a="Golnir é um súdito leal de Altaforja e do clã Barbabronze, estando firmemente ao lado da Grande Aliança. Ele mantém seu comércio situado no centro movimentado do reino, servindo tanto outros anões quanto viajantes da Aliança que o visitam.",al={"facção de golnir","lealdade de golnir","lado de golnir"}},["7131f874"]={q="Por que Golnir Topadão está aqui?",a="Golnir permanece perto de A Grande Forja, onde o calor nunca morre e o minério é constantemente fundido. Como mineradores e ferreiros de Dun Morogh e além trazem suas descobertas diretamente para a fornalha central de Altaforja, Golnir mantém sua loja por perto para equipá-los com o equipamento necessário.",al={"por que golnir está em altaforja","papel de golnir em a grande forja","por que golnir está aqui"}}},fp="17,218,27.473.0,35.154.0,28.154.0,44.236.0,47.125.0"}
P.entries["npc:gorbold-steelhand"] = {n="Gorbold Manácero",s="Gorbold Manácero é um comerciante anão estabelecido em Auberdine, ao longo da costa enevoada de Costa Negra. Operando longe dos salões nevados de Khaz Modan, ele abastece viajantes, artesãos e elfos noturnos locais com suprimentos gerais e materiais de comércio.",h="Gorbold Manácero é um comerciante anão estabelecido em Auberdine, ao longo da costa enevoada de Costa Negra.",kw={"auberdine","costa negra","deep ocean vast sea","gorbold","altaforja","comerciante","manácero","vendedor"},ang={["faction:Alliance"]="Gorbold ilustra a cooperação prática entre as raças orientais da Aliança e os elfos noturnos, mantendo o comércio fluindo através do Grande Oceano.",["race:Dwarf"]="Ver um rosto familiar de Altaforja como Gorbold no ambiente enevoado e noturno de Costa Negra oferece aos viajantes anões uma lembrança acolhedora de seu lar."},sec={{t="Um Comerciante Anão em Kalimdor",b="Embora a maior parte dos confins do norte de Kalimdor seja habitada pelos reservados elfos noturnos, postos avançados da Aliança como Auberdine dependem de comerciantes vindos do outro lado do Grande Oceano para manter o comércio ativo. Gorbold Manácero representa o alcance abrangente do comércio de Altaforja na região. Trabalhando ao lado dos kaldorei, ele vende artigos de comércio, reagentes, miudezas para criação e ferramentas para aventureiros que se preparam para explorar as costas traiçoeiras e as florestas de Costa Negra."},{t="Empreendimentos Marítimos",b="Além de estocar suprimentos diários, Gorbold fica sempre atento às águas costeiras perigosas nas proximidades de Auberdine. As águas repletas de recifes de Costa Negra são famosas por engolir embarcações da Aliança, e comerciantes como Gorbold têm um interesse direto nas cargas perdidas sob as ondas. Viajantes dispostos a mergulhar nas profundezas do oceano costumam encontrar nele alguém interessado em resgates e diários de bordo perdidos espalhados por navios naufragados."}},faq={{q="Quem é Gorbold Manácero?",a="Gorbold Manácero é um comerciante anão de suprimentos gerais estabelecido no porto costeiro de Auberdine, em Costa Negra.",al={"gorbold","quem é gorbold manácero","anão em auberdine"}},{q="O que Gorbold Manácero vende?",a="Ele comercializa suprimentos gerais de comércio, ingredientes de criação, ferramentas de coleta e reagentes, como frascos e linhas usados por artesãos de passagem por Auberdine.",al={"o que gorbold vende","produtos de comércio de gorbold","lista de mercadorias de gorbold"}},{q="Por que um anão de Altaforja está vivendo em Costa Negra?",a="Auberdine funciona como um ponto de trânsito fundamental da Aliança, conectando Kalimdor aos Reinos do Leste. Anões viajam frequentemente para cá em busca de comércio, exploração e para apoiar operações dos elfos noturnos aliados.",al={"por que tem um anão aqui","por que gorbold está em costa negra","altaforja em auberdine"}},{q="Gorbold oferece alguma missão?",a="Sim, ele direciona aventureiros para destroços submersos na costa de Costa Negra na missão 'Deep Ocean, Vast Sea' para recuperar cargas de navios perdidos.",al={"missão de gorbold","quem dá a missão deep ocean vast sea"}}},fx={["59afaf53"]={q="De que lado está Gorbold Manácero?",a="Gorbold Manácero é firmemente aliado à Aliança. Como um anão de Altaforja fazendo negócios no refúgio elfo noturno de Auberdine, ele mantém relações amigáveis com os kaldorei locais e recebe viajantes leais à Aliança que passam por Costa Negra.",al={"facção de gorbold manácero","gorbold manácero é da aliança","lealdade de gorbold"}}},fp="17,242,28.454.0,17.401.0,25.106.0,33.157.0,46.193.0,30.141.0"}
P.entries["npc:gordon-wendham"] = {n="Antônio Nunes",s="Antônio Nunes é um armeiro e comerciante Renegado que atua no movimentado Distrito Comercial em Cidade Baixa. Ele equipa os recém-chegados campeões e defensores locais da Dama Sombria com aço, lâminas e clavas confiáveis. Além de vender armamentos básicos, ele frequentemente atua como um ponto de contato local para mensageiros que chegam da superfície.",h="Antônio Nunes é um armeiro e comerciante Renegado que atua no movimentado Distrito Comercial em Cidade Baixa.",kw={"renegados","antônio nunes","miguel garreta","distrito comercial","cidade baixa","vendedor de armas"},ang={["class:Warrior"]="Antônio oferece lâminas básicas confiáveis e instrumentos contundentes para combatentes da linha de frente que desejam praticar suas proficiências com armas na capital.",["race:Undead"]="Para os Renegados recém-libertos que deixam Plangemortis, comerciantes como Antônio Nunes no Distrito Comercial representam a espinha dorsal prática do esforço de guerra de sua nação nascente."},sec={{t="Armamentos do Distrito Comercial",b="Situado entre a alvenaria úmida e os canais químicos do Distrito Comercial de Cidade Baixa, Antônio Nunes fornece armas essenciais àqueles que pegam em armas pelos Renegados. De adagas básicas e machadinhas a robustas espadas largas e maças, seu estoque atende a combatentes iniciantes que precisam de ferro confiável antes de se aventurarem pelas regiões disputadas de Lordaeron."},{t="O Destino de um Mensageiro",b="Além de seu comércio mercantil, Nunes está integrado à movimentada rede logística da capital. Viajantes enviados em missões por mestres de voo e mensageiros — como os que chegam dos tratadores de morcegos no topo das ruínas — são frequentemente direcionados direto para a sua barraca. Sua localização central no Distrito Comercial faz dele uma figura acessível e reconhecível para a coordenação de suprimentos básicos e despachos por toda a cidade subterrânea."}},faq={{q="Quem é Antônio Nunes?",a="Antônio Nunes é um comerciante morto-vivo instalado no Distrito Comercial de Cidade Baixa. Ele vende armas marciais comuns e serve como contato para mensageiros que chegam à capital.",al={"história de antônio nunes","quem é nunes","antônio de cidade baixa"}},{q="Onde fica Antônio Nunes?",a="Você pode encontrá-lo cuidando de sua barraca de armas no Distrito Comercial, o anel comercial situado dentro dos salões subterrâneos de Cidade Baixa.",al={"localização de antônio nunes","onde fica antônio em cidade baixa","vendedor de armas do distrito comercial"}},{q="O que ele vende?",a="Ele oferece uma ampla variedade de armas básicas de nível comum, incluindo espadas, adagas, maças, cajados, machados e diversos armamentos de arremesso adequados para aventureiros em evolução.",al={"mercadorias de nunes","o que antônio vende","armas de antônio nunes"}},{q="Quais missões envolvem ele?",a="Ele está ligado a missões introdutórias de entrega que conectam os poleiros de morcegos da superfície ao interior da cidade subterrânea, incluindo entregas entre ele e o tratador de morcegos Miguel Garreta.",al={"missões de antônio nunes","carona para a cidade baixa","missão de miguel garreta"}}},fx={["84654bd5"]={q="De que lado está Antônio Nunes?",a="Antônio Nunes é leal à Grande Dama Sylvana Correventos e aos Renegados, mantendo-se alinhado com a Horda em geral. De sua loja na Cidade Baixa, ele apoia seus irmãos mortos-vivos equipando viajantes e soldados que defendem seu reino recuperado sob as Ruínas de Lordaeron.",al={"facção de antônio nunes","a quem antônio nunes serve","antônio nunes é da horda"}},d70aab3f={q="Por que Antônio Nunes está na Cidade Baixa?",a="Antônio Nunes exerce seu ofício como armeiro no agitado Distrito Comercial da Cidade Baixa. Cercado pelos corredores subterrâneos da capital dos Renegados, ele permanece à disposição para fornecer lâminas, machados e clavas a qualquer pessoa que se prepare para se aventurar nas terras hostis acima.",al={"por que antônio nunes está aqui","propósito de antônio nunes na cidade baixa","o que traz antônio nunes aqui"}}},fp="14,351,30.365.0,23.429.0,22.181.0,32.140.0,18.166.0,24.173.0"}
P.entries["npc:gornek"] = {n="Gornek",s="Gornek é um supervisor orc situado no Vale das Provações em Durotar. Ele atua como o principal ponto de acolhimento para novos recrutas orcs e trolls Lançanegra que se preparam para provar seu valor para a The New Horde.",h="Gornek é um supervisor orc situado no Vale das Provações em Durotar.",kw={"the den","durotar","gornek","pergaminho","the new horde","vale das provações"},ang={["race:Orc"]="Para jovens orcs, apresentar-se a Gornek é o primeiro passo para deixar a infância para trás e conquistar um lugar honrado em Durotar.",["race:Troll"]="Como aliados acolhidos por Thrall, os trolls Lançanegra apresentam suas credenciais a Gornek para provar que são iguais e capazes ao lado de seus irmãos orcs."},sec={{t="Dando as Boas-vindas aos Não Provados",b="Posicionado diretamente no coração do Vale das Provações, Gornek representa o teste inicial de disciplina para aspirantes a guerreiros, batedores e conjuradores da Horda. Sob as ordens do Chefe Guerreiro Thrall, todo jovem e recém-chegado deve conquistar seu lugar por meio de determinação e perseverança, e não por privilégio. Gornek avalia aqueles que entram no vale, lendo suas ordens introdutórias e direcionando-os aos instrutores por todo o acampamento. Quer um iniciado carregue um rascunho criptografado, um Glyphic Parchment ou uma Tabuleta Simples, é Gornek quem recebe suas credenciais e os coloca em seu árduo caminho de sobrevivência."},{t="Uma Vida a Serviço de Durotar",b="Os cânions áridos do vale testam mais do que a proeza de batalha; eles incutem o espírito comunitário da The New Horde. Gornek garante que os novatos não fiquem vagueando sem rumo, apontando-os para as provações das tocas de escorpidídeos próximas, os covis de javalis ferozes e os olhos vigilantes de instrutores veteranos. Para aqueles que sobrevivem aos campos de treinamento e abatem as ameaças que espreitam nas ravinas de rocha vermelha, Gornek oferece o reconhecimento final antes de despachá-los para a paisagem mais ampla e perigosa de Durotar."}},faq={{q="Quem é Gornek?",a="Gornek é um recepcionista e feitor orc no Vale das Provações. Ele supervisiona novos recrutas da Horda, lendo seus documentos de admissão e orientando-os aos seus respectivos instrutores de classe.",al={"gornek","quem é este orc","quem é gornek"}},{q="Onde posso encontrar Gornek?",a="Ele fica perto do centro do Vale das Provações, no sudoeste de Durotar, dentro de The Den, onde jovens orcs e trolls Lançanegra começam suas jornadas.",al={"localização de gornek","onde fica gornek","mapa de gornek"}},{q="Por que novos recrutas se apresentam a ele?",a="Os recém-chegados carregam pergaminhos de treinamento e tabuletas que designam a disciplina escolhida. Gornek avalia essas cartas de apresentação, confirma sua elegibilidade e os envia aos mentores apropriados dentro do vale.",al={"por que visitar gornek","missão de pergaminho","missão de tabuleta"}},{q="Qual é o papel dele na The New Horde?",a="Ele atua como um coordenador de entrada para a The New Horde de Thrall. Seu dever é garantir que nenhum recruta entre nas terras mais amplas de Durotar sem antes aprender os princípios básicos de honra, sobrevivência e prontidão marcial.",al={"papel de gornek na horda","o que gornek faz"}}},fx={a3ac85eb={q="De que lado está Gornek?",a="Gornek é ferozmente leal à Nova Horda de Thrall. Estacionado em Durotar, ele serve como um supervisor dentro do Vale das Provações, garantindo que cada orc recém-desperto e recruta troll visitante adote a disciplina, a força e a mentalidade de sobrevivência necessárias para defender sua nação nascente.",al={"facção de gornek","a quem gornek serve","gornek é da horda ou da aliança"}},e623e91b={q="O que Gornek quer?",a="Gornek quer que você prove que é digno da Horda. Durotar é uma terra árida cheia de predadores e infiltrados hostis, e ele se recusa a desperdiçar recursos com recrutas indisciplinados. Ele encarrega jovens guerreiros de caçar feras perigosas e eliminar ameaças locais para forjá-los em combatentes capazes.",al={"objetivo de gornek","do que gornek precisa","motivo da missão de gornek"}},a6376a9f={q="Por que Gornek está no Vale das Provações?",a="O Vale das Provações é o campo de testes designado para o sangue novo da Horda. Gornek está posicionado aqui para orientar os recém-chegados, avaliar suas capacidades iniciais e apresentá-los aos treinadores e provações que os prepararão para os desafios de Durotar e além.",al={"por que gornek está aqui","função de gornek no vale das provações","por que gornek está em durotar"}}},fp="6,204,22.613.0,28.513.0,14.190.0,24.149.0,34.221.0,34.207.0"}
P.entries["npc:gramma-stonefield"] = {n="Vovó Campedra",s="A Vovó Campedra, cujo nome de batismo é Mildred, é a idosa matriarca da família Campedra que reside na fazenda deles na Floresta de Elwynn. Ao contrário de seus parentes briguentos, ela se cansou da amarga rixa de gerações com os vizinhos Madruga. Agindo silenciosamente pelas costas de sua família, ela faz tudo o que pode para ajudar seu neto Tomasino Campedra a levar adiante seu romance proibido com Mabel Madruga.",h="A Vovó Campedra, cujo nome de batismo é Mildred, é a idosa matriarca da família Campedra que reside na...",kw={"elwynn","vovó campedra","madruga","mabel","mildred","fazenda dos campedra","tomasino","durval pilão"},ang={["faction:Alliance"]="A Vovó Campedra é uma suave lembrança de que, mesmo no coração da Aliança, os conflitos locais costumam exigir diplomacia silenciosa e empatia simples em vez de aço."},sec={{t="Uma Pacificadora Secreta",b="Como o membro vivo mais velho do clã Campedra, Mildred Campedra testemunhou décadas de brigas mesquinhas entre sua família e os Madruga do outro lado da estrada. Em vez de alimentar a inimizade, ela vê a rivalidade duradoura como insensata e destrutiva. Quando seu neto Tomasino Campedra se apaixona por Mabel Madruga, a Vovó escolhe a compaixão em vez da lealdade ao clã. Contando com uma velha amizade com Durval Pilão em Vila d'Ouro, ela planeja secretamente ajudar os amantes desafortunados a se encontrarem em segredo, subvertendo a teimosa hostilidade que divide as duas fazendas."}},faq={{q="Quem é a Vovó Campedra?",a="A Vovó Campedra, chamada Mildred, é a idosa matriarca da família Campedra que vive na fazenda deles no centro da Floresta de Elwynn. Ela é a avó de Tomasino Campedra.",al={"quem é a vovó","mildred campedra","vovó campedra"}},{q="O que ela acha da rixa com os Madruga?",a="Mildred não tem interesse em manter a rixa. Diferente da maioria dos membros de ambas as famílias, ela vê o rancor como tolo e prejudicial, preferindo ver harmonia entre os lares em vez de discussões sem fim.",al={"rixa campedra madruga","ela odeia os madruga"}},{q="Por que ela está ajudando Tomasino e Mabel?",a="Ela ama seu neto Tomasino e quer vê-lo feliz. Por rejeitar a rixa familiar, ela ajuda ativamente seu romance proibido com Mabel Madruga, recorrendo ao seu velho amigo Durval Pilão para preparar uma solução para o casal.",al={"por que ajudar tomasino","poção do amor da vovó","ajudar os amantes"}},{q="Quem é Durval Pilão para ela?",a="Durval Pilão, o alquimista que reside na Estalagem do Leão Orgulhoso em Vila d'Ouro, é um amigo antigo e de confiança da Vovó Campedra. Ela entra em contato com ele por meio de mensageiros de confiança para preparar remédios discretos e auxílios para Tomasino.",al={"conexão com durval pilão","durval pilão e vovó"}}},fx={d471da09={q="Por que a Vovó Campedra está aqui?",a="Esta cabana é seu lar de toda a vida. Como matriarca e membro vivo mais velho do clã Campedra, Mildred reside bem aqui, na fazenda da família na Floresta de Elwynn, observando silenciosamente seus parentes enquanto se esforça para evitar que suas pequenas rivalidades destruam vidas jovens.",al={"por que a vovó campedra está na fazenda","localização da vovó na fazenda campedra","por que mildred campedra está aqui"}}},fp="17,404,19.576.0,25.178.0,51.211.0,41.239.0,29.226.0"}
P.entries["npc:grand-mason-marblesten"] = {n="Grão-alvanel Oscarmeyer",s="O Grão-alvanel Oscarmeyer é um estimado pedreiro anão instalado no movimentado Distrito dos Plebeus de Altaforja. Profundamente devotado ao legado real de Khaz Modan, ele foi encarregado pelo Rei Magni Barbabronze de construir um memorial para Sully Balloo, um soldado anão que morreu na tragédia da Ponte Thandol. Os aventureiros costumam encontrá-lo ao ajudar com os materiais necessários para concluir essa solene homenagem.",h="O Grão-alvanel Oscarmeyer é um estimado pedreiro anão instalado no movimentado Distrito dos Plebeus de...",kw={"homenagem real","barbabronze","distrito dos plebeus","grão-alvanel","altaforja","magni","oscarmeyer","pedreiro","sully balloo"},ang={["faction:Alliance"]="Honrar o sacrifício de Sully Balloo lembra a Aliança de cada soldado perdido em suas guerras.",["profession:Mining"]="Mineradores que trabalham de perto com as rochas de Dun Morogh e além apreciarão os padrões rigorosos de Oscarmeyer quanto à qualidade do mineral bruto.",["race:Dwarf"]="Para os anões, o trabalho em pedra é uma herança ancestral; ajudar Oscarmeyer presta homenagem tanto à arte de Khaz Modan quanto à memória do soldado caído Sully Balloo."},sec={{t="Mestre da Pedra",b="A cantaria dos anões não é um mero ofício; é uma forma de arte duradoura que molda a própria alma de Altaforja. O Grão-alvanel Oscarmeyer está entre os principais mestres do cinzel da cidade, representando a tradição secular de esculpir salões, pilares e grandes efígies diretamente da montanha viva. Estabelecido no Distrito dos Plebeus, ele supervisiona projetos cívicos e monumentos comemorativos que imortalizam a história dos Barbabronze."},{t="Homenagem real",b="A tarefa mais comovente de Oscarmeyer é um memorial encomendado pelo Rei Magni para Sully Balloo, um soldado que pereceu na tragédia da Ponte Thandol, como uma homenagem à sua viúva em luto. Desejando uma obra verdadeiramente duradoura, o Grão-alvanel insiste em usar uma das pedras mais refinadas existentes: Granito de Alterac do Monte das Flechas, em Eira dos Montes."}},faq={{q="Quem é o Grão-alvanel Oscarmeyer?",a="O Grão-alvanel Oscarmeyer é um veterano pedreiro anão localizado no Distrito dos Plebeus de Altaforja. Ele é encarregado de projetos esculturais cívicos e reais, principalmente um memorial ao soldado caído Sully Balloo, encomendado pelo Rei Magni Barbabronze.",al={"quem é oscarmeyer","papel de oscarmeyer","npc grão-alvanel"}},{q="Onde posso encontrar o Grão-alvanel Oscarmeyer?",a="Ele pode ser encontrado no Distrito dos Plebeus de Altaforja, cercado por blocos de pedra e obras arquitetônicas não muito longe das movimentadas lojas e bancos da cidade.",al={"localização de oscarmeyer","onde fica oscarmeyer","altaforja oscarmeyer"}},{q="Em qual monumento Oscarmeyer está trabalhando?",a="Ele está construindo um memorial para Sully Balloo, um soldado anão que morreu na tragédia da Ponte Thandol. O Rei Magni Barbabronze o encomendou em homenagem a Balloo e à sua viúva enlutada.",al={"o que ele está construindo","missão homenagem real","estátua de oscarmeyer"}},{q="Por que Oscarmeyer precisa que aventureiros coletem materiais?",a="Oscarmeyer quer uma obra verdadeiramente épica e duradoura, por isso ele só trabalha com uma das pedras mais nobres existentes. Ele envia viajantes ao Monte das Flechas, em Eira dos Montes, para obter Granito de Alterac.",al={"missões de oscarmeyer","por que precisa de pedras","materiais para monumento"}},{q="O que significa o título \"Grão-alvanel\" na sociedade dos anões?",a="Entre os anões, o trabalho com pedras é reverenciado tanto quanto a ferraria. Um \"Grão-alvanel\" é um mestre consumado da arte em cantaria, encarregado de grandes projetos de estado, projetos arquitetônicos reais e memoriais cerimoniais.",al={"o que é um grão-alvanel","posto de pedreiro anão"}},{q="Oscarmeyer é um funcionário da Aliança ou um prestador de serviços particular?",a="Oscarmeyer atua diretamente em Altaforja e serve ao reino de Altaforja e à Aliança, coordenando-se de perto com a corte do Rei Magni Barbabronze para encomendas reais.",al={"para quem oscarmeyer trabalha","facção de oscarmeyer"}}},fx={a77cb24b={q="De que lado está o Grão-alvanel Oscarmeyer?",a="Oscarmeyer é totalmente leal a Altaforja e à Aliança. Posicionado bem no coração das Áreas Comuns da cidade, ele serve ao Rei Magni Barbabronze e ao reino anão, dedicando seu ofício e alvenaria para honrar a herança anã e o trono.",al={"facção de oscarmeyer","a quem oscarmeyer serve","oscarmeyer aliança"}},["1dc5a337"]={q="O que o Grão-alvanel Oscarmeyer quer?",a="Oscarmeyer está supervisionando um monumento real e precisa de materiais refinados para vê-lo concluído. Por meio de seu trabalho em 'Um Tributo ao Rei', ele busca aventureiros capazes para ajudar a obter os recursos essenciais necessários para o memorial ao soldado caído Sully Balloo, encomendado pelo Rei Magni.",al={"o que oscarmeyer quer","objetivo de oscarmeyer","por que oscarmeyer precisa de ajuda"}},["98aae54f"]={q="Por que o Grão-alvanel Oscarmeyer está nas Áreas Comuns?",a="Oscarmeyer mantém sua oficina nas movimentadas Áreas Comuns de Altaforja para supervisionar o trabalho em pedra da grande fortaleza montanhosa e organizar os esforços de construção para o trono. A praça aberta permite que ele coordene projetos e recrute viajantes que passam pela cidade.",al={"por que oscarmeyer está em altaforja","por que oscarmeyer está aqui","oscarmeyer áreas comuns altaforja"}}},fp="22,395,19.426.0,16.312.0,30.247.0,40.154.0,39.182.0,57.184.0,58.210.0,59.176.0"}
P.entries["npc:granis-swiftaxe"] = {n="Granis Celeraxa",s="Granis Celeraxa é um instrutor de guerreiros anão posicionado dentro da Destilaria Cervaforte em Kharanos. Conhecido por sua postura direta e regime de treinamento rigoroso, ele orienta combatentes novatos da Aliança que saem do Caminho de Cristálgida antes de direcionar guerreiros experientes para a cidade de Altaforja.",h="Granis Celeraxa é um instrutor de guerreiros anão posicionado dentro da Destilaria Cervaforte em Kharanos.",kw={"dun morogh","granis celeraxa","kharanos","muren stormpike","destilaria cervaforte","instrutor de guerreiros"},ang={["class:Warrior"]="Para combatentes anões e gnomos que deixam o Vale Cristálgida, Granis fornece instruções essenciais de combate inicial logo ao lado de uma caneca fresca na destilaria.",["race:Dwarf"]="Personificando o espírito robusto e obstinado dos soldados de infantaria de Altaforja, Granis combina disciplina marcial com o conforto da cerveja local."},sec={{t="Um Mentor Ríspido em Kharanos",b="Encontrado se aquecendo entre os barris da Destilaria Cervaforte, Granis Celeraxa serve como o principal instrutor de combate para jovens guerreiros que viajam por Dun Morogh. Ele possui o orgulho inflexível típico dos combatentes anões, demonstrando clara diversão e desdém para com aqueles que não são guerreiros e tentam chamar sua atenção. Quando um aluno demonstra perícia suficiente em combate, Granis o envia pela trilha da montanha para procurar o mestre instrutor Muren Stormpike no Military Ward de Altaforja."}},faq={{q="Quem é Granis Celeraxa?",a="Granis Celeraxa é um instrutor de guerreiros anão localizado no piso térreo da Destilaria Cervaforte em Kharanos. Ele ensina técnicas marciais básicas para jovens guerreiros anões e gnomos que se aventuram por Dun Morogh.",al={"granis celeraxa","quem é granis","instrutor de guerreiros de kharanos"}},{q="Por que Granis zomba do meu personagem?",a="Granis não tem paciência com aqueles que não trilham o caminho do guerreiro. Se um aventureiro de outra classe falar com ele, ele zomba da ideia de tal pessoa sobreviver a um único dia sob seu intenso regime de treinamento.",al={"fala rude de granis","por que granis está rindo de mim","texto de granis para não guerreiros"}},{q="Para onde Granis envia guerreiros avançados?",a="Assim que um guerreiro ganha experiência suficiente em Dun Morogh, Granis o instrui a procurar Muren Stormpike, um instrutor de guerreiros sênior localizado no Military Ward de Altaforja.",al={"missão de muren stormpike","linha de missões de granis","para quem granis envia você"}},{q="Granis é parente de outros Celeraxa em Khaz Modan?",a="Ele compartilha o sobrenome Celeraxa com outros anões, mas nenhum parentesco é confirmado.",al={"família celeraxa","parentes de granis celeraxa"}}},fx={b8e95117={q="De que lado está Granis Celeraxa?",a="Granis está firmemente ao lado dos anões de Altaforja e da Aliança em geral. Posicionado em Kharanos, ele dedica sua experiência marcial ao treinamento da próxima geração de defensores contra os troggs, trolls do gelo e outras ameaças ao redor de Dun Morogh.",al={"facção de granis celeraxa","por quem granis luta","granis aliança"}},["760b1803"]={q="Por que Granis Celeraxa está em Kharanos?",a="Granis está posicionado dentro da Destilaria Cervaforte em Kharanos para treinar jovens guerreiros da Aliança que partem do Caminho de Cristálgida. Dun Morogh enfrenta uma pressão crescente de troggs nativos e Wendigos, tornando seus rigorosos exercícios de combate vitais para a defesa local.",al={"por que granis está aqui","motivo da localização de granis celeraxa","o que trouxe granis a kharanos"}},cf3183bb={q="O que Granis Celeraxa quer?",a="Granis não quer nada menos que guerreiros disciplinados e endurecidos, capazes de manter a linha de frente por Khaz Modan. Ele tem pouca paciência com os fracos ou destreinados, exigindo dedicação implacável dos recrutas antes de direcionar veteranos promissores a mestres como Muren Stormpike em Altaforja.",al={"objetivos de granis celeraxa","o que granis quer","propósito de granis"}}},fp="15,285,26.485.0,23.216.0,34.218.0,42.170.0,51.91.0"}
P.entries["npc:great-father-winter"] = {n="Papai Inverno",s="Papai Inverno é um orc idoso contratado pela companhia mercantil Smokywood Pastures para se passar pela lendária figura festiva em Orgrimmar. Posicionado perto de Grommash Hold no Vale da Força durante o Feast of Winter Veil, ele ouve os desejos das crianças enquanto fica visivelmente farto da alegria comercial das festas. Em troca de presentes festivos e tarefas sazonais, ele frequentemente pede biscoitos de gengibre e Leite Gelado aos transeuntes.",h="Papai Inverno é um orc idoso contratado pela companhia mercantil Smokywood Pastures para se passar pela...",kw={"biscoitos de gengibre","papai inverno","orgrimmar","smokywood pastures","vale da força","winter veil"},ang={["faction:Horde"]="Ele atua como a principal figura sazonal da Horda em Orgrimmar, oferecendo presentes e tarefas festivas em nome da Smokywood Pastures.",["profession:Cooking"]="Culinários podem assar biscoitos de gengibre usando receitas festivas e entregá-los junto com leite diretamente a Papai Inverno para restaurar seus ânimos.",["race:Orc"]="Embora os orcs reverenciem as mudanças de estações e os elementos, ver um de seus semelhantes reduzido a um mascote fantasiado vendendo descontos de mercadores testa a paciência dos tradicionalistas."},sec={{t="Um Mito Contratado",b="Embora a lenda antiga fale de Papai Inverno como um espírito elemental majestoso vagando pelas terras trazendo neve e renovação sazonal, a figura sentada no Vale da Força é bem mais mundana. Ele é um artista orc na folha de pagamento da Smokywood Pastures, contratado especificamente para impulsionar o comércio, promover os produtos da empresa e entreter os jovens da Horda. Os críticos resmungam que esse mascote comercial desvaloriza as tradições sazonais genuínas, mas poucos podem negar o agito festivo que ele traz às ruas da cidade."},{t="Trabalho em Turnos no Vale da Força",b="Posicionado bem em frente a Grommash Hold sob os galhos de coníferas decoradas, esse substituto suporta um turno exaustivo de crianças subindo em seu colo para exigir presentes. Entre inserções corporativas promovendo descontos da Smokywood Pastures e saudações natalinas sem entusiasmo, sua resistência frequentemente se esgota. Ele admite abertamente manter uma garrafa de bebidas festivas escondida em sua mochila para abafar o barulho assim que o seu turno terminar, dependendo fortemente de aventureiros visitantes para trazerem lanches e mantê-lo de pé."}},faq={{q="Este é o verdadeiro Papai Inverno?",a="Não. Ele é um orc comum contratado pela Smokywood Pastures para se fantasiar, fingir ser a lendária figura do Winter Veil e distribuir promoções natalinas em Orgrimmar.",al={"ele é de verdade","quem é papai inverno","ele é um ator"}},{q="Onde posso encontrar Papai Inverno em Orgrimmar?",a="Ele pode ser encontrado no Vale da Força, posicionado logo do lado de fora da entrada de Grommash Hold, junto à árvore do Feast of Winter Veil e às barracas do festival.",al={"localização de papai inverno","onde fica o papai inverno","onde encontrar o orc do inverno"}},{q="O que ele faz durante o Feast of Winter Veil?",a="Ele entretém os frequentadores do festival, ouve os pedidos de presentes das crianças, passa tarefas promocionais da Smokywood Pastures e distribui presentes festivos embaixo da árvore quando a celebração chega ao seu ápice.",al={"o que ele faz","propósito de papai inverno","missões de winter veil"}},{q="Por que ele quer biscoitos de gengibre e leite?",a="Suportar multidões barulhentas e uma criança após a outra em seu colo o dia todo o deixa completamente exausto. Ele pede aos aventureiros que lhe tragam biscoitos de gengibre frescos e leite para manter as energias durante o turno.",al={"guloseimas para papai inverno","por que leite e biscoitos","missão de biscoito de gengibre"}},{q="O que ele acha do seu trabalho?",a="Ele considera a apresentação tediosa e cansativa. Ele resmunga abertamente sobre crianças eufóricas, recita slogans corporativos com pressa e conta ansiosamente os minutos para poder beber de uma garrafa de alegria escondida em sua bolsa.",al={"ele gosta do trabalho dele","falas de papai inverno","ele está bêbado"}},{q="A Aliança tem uma figura equivalente?",a="Sim. A Aliança tem Papai Inverno, um anão idoso contratado pela Smokywood Pastures que se senta perto da árvore de Natal nos Commons de Altaforja.",al={"papai inverno da aliança","papai noel de altaforja","equivalente da aliança"}}},fx={["1d43ce2e"]={q="De que lado está o Papai Inverno?",a="Este Papai Inverno é um orc que trabalha estritamente dentro de Orgrimmar para a Horda, embora seu empregador final seja a Smokywood Pastures. A empresa goblínica o contratou para trazer alegria festiva — e impulsionar os gastos festivos dos consumidores — ao Vale da Força. Embora ele use o traje vermelho festivo da lenda, sua verdadeira lealdade reside em seu salário e em sobreviver ao seu turno exaustivo.",al={"o papai inverno é da horda","facção do papai inverno","para quem o papai inverno trabalha"}},["796ea74c"]={q="Por que o Papai Inverno está aqui?",a="Ele está posicionado fora de Grommash Hold porque a Smokywood Pastures o contratou para ancorar suas celebrações do Banquete do Véu de Inverno na capital da Horda. Os goblins mercantis o colocaram lá para entreter os jovens da cidade, ouvir seus desejos de presentes e direcionar famílias ansiosas para mercadorias de fim de ano e guloseimas festivas.",al={"por que o papai inverno está em orgrimmar","o que trouxe o papai inverno para cá","motivo do papai inverno estar aqui"}},f14772a5={q="A quem o Papai Inverno está ligado?",a="Ele é contratado diretamente pela Smokywood Pastures, o empreendimento goblínico responsável por comercializar o Banquete do Véu de Inverno por todo o reino. Eles fornecem seu traje festivo, definem seus roteiros promocionais e organizam os presentes e guloseimas que ele distribui em torno de Grommash Hold.",al={"quem contratou o papai inverno","conexões do papai inverno","smokywood pastures papai inverno"}},["826ac72e"]={q="Por que o Papai Inverno é famoso?",a="Ele reivindica o nome e o disfarce do Papai Inverno, uma antiga figura sobrenatural celebrada em toda Azeroth por anunciar a mudança das estações. Embora estudiosos argumentem que este orc fantasiado seja apenas um mascote comercial, crianças e foliões festivos ainda se reúnem em torno dele como a face viva da alegria do Véu de Inverno.",al={"por que as pessoas conhecem o papai inverno","o papai inverno é lendário","reputação do papai inverno"}}},fp="19,438,12.510.0,36.525.0,36.154.0,50.145.0,48.183.0,46.205.0,30.223.0,44.149.0"}
P.entries["npc:greatfather-winter"] = {n="Papai Inverno",s="Papai Inverno é a lendária personificação da estação do inverno e a figura central do Festival do Véu de Inverno. Enquanto lendas antigas o reverenciam como um ser mítico que cobre Azeroth de neve para permitir que a terra descanse e se renove, os habitantes modernos das cidades o conhecem principalmente pelo espetáculo comercial promovido pelos goblins da Fazenda Bosque Fumegante.",h="Papai Inverno é a lendária personificação da estação do inverno e a figura central do Festival do Véu de...",kw={"dun morogh","biscoitos de gengibre","papai inverno","altaforja","orgrimmar","fazenda bosque fumegante","veu de inverno"},ang={["profession:Cooking"]="A celebração depende de cozinheiros habilidosos para preparar biscoitos de gengibre e outros quitutes festivos para a Fazenda Bosque Fumegante e para o próprio Papai Inverno.",["race:Dwarf"]="Os anões veem o Papai Inverno como um aspecto dos titãs que moldaram o mundo, contemplando os picos nevados de Dun Morogh como testemunho vivo de seu toque."},sec={{t="Mito e Renovação",b="Segundo lendas antigas, Papai Inverno é um andarilho etéreo que percorre o mundo no fim do ano, estendendo seu manto esvoaçante de neve sobre a terra para que a natureza possa adormecer e renascer. Os anões o veem como uma personificação ou arauto dos titãs, apontando os penhascos congelados de Dun Morogh como prova viva de seu favor. Outras tradições, como as dos taurens, respeitam seu papel na mudança das estações enquanto atribuem o frio e as tempestades ao trabalho elemental do Sol e da Lua, concedendo tempo de descanso à Mãe Terra. Onde quer que a lenda chegasse, as comunidades aprenderam a se reunir e festejar juntas contra o frio, celebrando a promessa do retorno da vida."},{t="Fazenda Bosque Fumegante e Festividades Urbanas",b="Em grandes povoados como Altaforja e Orgrimmar, o antigo espírito foi profundamente transformado pelos goblins empreendedores da Fazenda Bosque Fumegante. O cartel comercial popularizou a representação de Papai Inverno como um ancião alegre de trajes vermelhos e barba branca que viaja em um trenó voador, distribuindo guloseimas festivas e brinquedos. A Fazenda Bosque Fumegante contrata atores locais — um anão em Altaforja e um orc em Orgrimmar — para ouvir os desejos das crianças, receber oferendas de leite e biscoitos de gengibre e divulgar mercadorias da estação sob árvores ricamente decoradas."}},faq={{q="O Papai Inverno em Altaforja é o espírito verdadeiro?",a="Não, o Papai Inverno sentado ao lado da árvore festiva em Altaforja é um ator contratado pela companhia de mercadores goblins da Fazenda Bosque Fumegante. A empresa organiza aparições para alegrar as crianças e vender doces sazonais, embora as lendas reais falem de um ser etéreo autêntico que caminha pelo mundo no inverno.",al={"papai inverno e real","quem e o cara em altaforja","ele e um ator"}},{q="Por que os anões reverenciam Papai Inverno?",a="Os anões associam Papai Inverno aos seus criadores, os titãs. Eles consideram o manto de neve que ele estende sobre a terra como uma bênção, apontando sua terra natal perpetuamente gélida de Dun Morogh como a maior evidência de seu favor.",al={"veu de inverno dos anoes","papai inverno dos anoes","altaforja papai inverno"}},{q="O que Papai Inverno faz com os biscoitos e o leite levados até ele?",a="De acordo com o folclore festivo popularizado pela Fazenda Bosque Fumegante, Papai Inverno adora lanchar biscoitos de gengibre festivos e Leite Gelado enquanto avalia as listas de pedidos e espalha a alegria natalina.",al={"um agrado para o papai inverno","por que leite e biscoitos","missao biscoitos de gengibre"}},{q="Como a Horda vê Papai Inverno?",a="A Horda participa das festividades em grande parte por meio da promoção urbana da Fazenda Bosque Fumegante em Orgrimmar, onde o Papai Inverno é retratado como um orc. Culturalmente, os taurens reconhecem o inverno como um período vital de repouso e renovação elemental para a Mãe Terra, respeitando o papel do Papai Inverno no ciclo das estações sem aderir à adoração literal aos titãs.",al={"papai inverno da horda","orgrimmar papai inverno","taurens veu de inverno"}}},fx={["66677a0e"]={q="De que lado está o Papai Inverno?",a="Ele não pertence a nenhuma das facções. Na lenda, o Papai Inverno é uma força antiga e sobrenatural da natureza que concede renovação sazonal e fartura por todo o mundo, independentemente das lealdades mortais. A figura que você vê sentada em Altaforja é patrocinada pela companhia comercial goblínica Smokywood Pastures, que mantém uma operação estritamente neutra e voltada para o lucro. Na verdade, a Smokywood Pastures contrata uma contraparte orc para sentar em Orgrimmar e espalhar alegria festiva entre a Horda simultaneamente.",al={"papai inverno aliança ou horda","o papai inverno é da aliança","facção do papai inverno"}},a8f1de98={q="O que o Papai Inverno quer?",a="O antigo espírito do mito busca apenas cobrir o mundo com o inverno, dando à terra o tempo necessário para descanso, renascimento e eventual renovação, enquanto concede fartura àqueles que o acolhem. O imitador mortal que você encontra em Altaforja, no entanto, é empregado pela Smokywood Pastures. O objetivo deles é inteiramente festivo e comercial: trazer alegria, distribuir guloseimas para as crianças bem-comportadas e impulsionar as vendas entusiasmadas de seus produtos e brinquedos de fim de ano.",al={"motivações do papai inverno","o que o papai inverno quer","por que o papai inverno dá presentes"}},daa32740={q="Por que o Papai Inverno está em Altaforja?",a="A Smokywood Pastures o posicionou ao lado da árvore do Véu de Inverno para ancorar suas festividades sazonais. Durante as semanas que antecedem o feriado, a figura alegre se encontra com cidadãos e crianças para ouvir seus desejos de fim de ano, coletar cartas e espalhar boa vontade ao lado de seus ajudantes goblins — tudo isso enquanto ajuda a Smokywood Pastures a promover seus produtos sazonais.",al={"por que o papai inverno está em altaforja","por que o papai inverno está aqui","localização do papai inverno em altaforja"}},["8b922b4d"]={q="A quem o Papai Inverno está ligado?",a="A tradição anã liga o antigo espírito aos titãs, acreditando que ele personifica seu poder de moldar as estações de Azeroth. Na prática cotidiana, o festivo Papai Inverno visto na cidade é parceiro da Smokywood Pastures, cercado por seus diminutos Ajudantes e bonecos de neve festivos.",al={"com quem o papai inverno está associado","conexões do papai inverno","quem trabalha com o papai inverno"}}},fp="18,362,16.674.0,39.571.0,55.303.0,41.228.0,73.202.0,43.359.0"}
P.entries["npc:greatmother-hawkwind"] = {n="Grande Mãe Vento do Falcão",s="A Grande Mãe Vento do Falcão é uma reverenciada anciã tauren descansando junto ao poço de água na Chapada Nuvem Vermelha. Como mãe do líder da Aldeia Narache, o Chefe Vento do Falcão, ela personifica o espírito duradouro e a responsabilidade comunitária da tribo, apesar de sua idade avançada.",h="A Grande Mãe Vento do Falcão é uma reverenciada anciã tauren descansando junto ao poço de água na Chapada...",kw={"a humble task","aldeia narache","chefe vento do falcão","grande mãe vento do falcão","mulgore","chapada nuvem vermelha","anciã tauren"},ang={["race:Tauren"]="Para os jovens tauren que iniciam sua jornada na Chapada Nuvem Vermelha, a Grande Mãe Vento do Falcão personifica os valores fundamentais da Mãe Terra: respeito aos mais velhos, solidariedade comunitária e humildade no serviço."},sec={{t="Anciã da Chapada",b="A Grande Mãe Vento do Falcão passa os seus dias ao lado do poço de água fresca na Aldeia Narache, servindo como a matriarca espiritual para os jovens tauren que iniciam seus ritos de passagem. Embora os anos tenham diminuído o ritmo de seus passos, ela se recusa a deixar que a idade afaste seu dever para com a aldeia. Ela acredita que cada membro da tribo, jovem ou velho, tem um papel ativo na sustentação da comunidade, frequentemente pedindo aos jovens novatos que ajudem em tarefas domésticas simples, como buscar água fresca."},{t="A Orientação de uma Mãe",b="Como mãe do Chefe Vento do Falcão, o líder tribal da Aldeia Narache, a Grande Mãe Vento do Falcão oferece conselhos firmes e dignidade serena em meio às ameaças que a Chapada Nuvem Vermelha enfrenta. Enquanto seu filho organiza caçadores e guerreiros contra o avanço dos javatuscos Bristleback e predadores locais, ela cuida do coração moral do assentamento, lembrando aos recém-despertados que a força começa com a humildade e o serviço aos seus semelhantes."}},faq={{q="Quem é a Grande Mãe Vento do Falcão?",a="A Grande Mãe Vento do Falcão é uma idosa matriarca tauren que reside na Aldeia Narache, na Chapada Nuvem Vermelha. Ela é mãe do líder tribal do acampamento, o Chefe Vento do Falcão, e atua como uma guia anciã para jovens aventureiros.",al={"história da grande mãe vento do falcão","quem é a grande mãe vento do falcão","anciã da aldeia narache"}},{q="Onde ela pode ser encontrada?",a="Ela senta-se junto ao poço de água a sudeste da Aldeia Narache, na Chapada Nuvem Vermelha, no sudoeste de Mulgore.",al={"localização da grande mãe vento do falcão","onde fica a grande mãe vento do falcão"}},{q="Quais tarefas ela pede aos jovens tauren?",a="Ela encarrega os jovens tauren com 'A Humble Task', pedindo-lhes que recolham água do poço da aldeia e a entreguem a outros no acampamento. A tarefa ensina que nenhum trabalho é humilde demais para um verdadeiro servo da tribo.",al={"missão da grande mãe vento do falcão","a humble task"}},{q="Qual é o parentesco dela com o Chefe Vento do Falcão?",a="Ela é mãe do Chefe Vento do Falcão, que supervisiona a defesa e o treinamento dos jovens bravos na Aldeia Narache.",al={"mãe do chefe vento do falcão","ela é parente do chefe vento do falcão"}}},fx={f701fe56={q="De que lado está a Grande Mãe Vento do Falcão?",a="A Grande Mãe Vento do Falcão é devotada ao seu povo, os tauren da Horda. Como matriarca anciã da Aldeia Narache, sua lealdade reside inteiramente com sua tribo, sua família e os jovens bravos que partem para servir aos ancestrais e à Mãe Terra.",al={"facção da grande mãe vento do falcão","a quem a grande mãe vento do falcão serve","lealdade da grande mãe vento do falcão"}},["8d52ad78"]={q="O que a Grande Mãe Vento do Falcão quer?",a="Apesar de sua idade avançada, a Grande Mãe Vento do Falcão insiste em fazer sua parte para cuidar da Aldeia Narache. Ela cuida das necessidades do assentamento, ocupando-se de tarefas domésticas simples, como buscar água fresca do poço da vila, e pede aos jovens tauren que ofereçam uma mão amiga nessas humildes tarefas cotidianas.",al={"o que a grande mãe vento do falcão precisa","objetivo da grande mãe vento do falcão","por que falar com a grande mãe vento do falcão"}},["2db356dc"]={q="Por que a Grande Mãe Vento do Falcão está aqui?",a="A Grande Mãe Vento do Falcão reside na Aldeia Narache como a anciã da vila e mãe do Chefe Vento do Falcão. Você a encontrará perto do poço central de água do assentamento, trabalhando diligentemente para apoiar sua tribo e observando os jovens caçadores e xamãs que começam suas jornadas na Chapada Nuvem Vermelha.",al={"por que a grande mãe vento do falcão está na aldeia narache","por que da localização da grande mãe vento do falcão","por que ela está no poço"}}},fp="20,247,17.476.0,19.413.0,28.203.0,23.96.0,40.205.0,39.107.0"}
P.entries["npc:grelin-whitebeard"] = {n="Grolin Barbabranca",s="Grolin Barbabranca é um batedor anão posicionado no Vale Cristálgida por decreto real para avaliar a ameaça dos trolls Frostmane. Operando a partir de um acampamento isolado, ele depende de aventureiros em ascensão para manter os trolls contidos enquanto a atenção de Altaforja permanece consumida pela crise dos troggs.",h="Grolin Barbabranca é um batedor anão posicionado no Vale Cristálgida por decreto real para avaliar a ameaça...",kw={"vale cristálgida","dun morogh","frostmane","grolin barbabranca","grik'nir","senado de altaforja","senir barbabranca","the stolen journal"},ang={["faction:Alliance"]="A situação difícil de Grolin revela o quanto os exércitos da Aliança e de Altaforja estão sobrecarregados em Dun Morogh, forçando batedores solitários a travar guerras silenciosas contra enclaves de trolls.",["race:Dwarf"]="Servindo diretamente ao Rei Magni, Grolin representa a perseverança silenciosa e obstinada dos batedores de Altaforja que mantêm as fronteiras de Dun Morogh unidas contra as crescentes ameaças internas.",["race:Gnome"]="Recém-saídos da tragédia de Gnomeregan, recrutas gnomos no Vale Cristálgida encontram em Grolin um anão grato por qualquer ajuda capaz contra os Frostmane."},sec={{t="Um Mandato Real",b="Grolin Barbabranca e seu irmão Senir foram despachados para o Vale Cristálgida sob ordens diretas do Senado de Altaforja e do próprio Rei Magni Barbabronze. A missão deles era clara: avaliar e neutralizar a ameaça representada pelos trolls nativos Frostmane. Com as forças militares oficiais de Altaforja totalmente atoladas no combate às invasões de troggs por toda Dun Morogh, os irmãos receberam pouquíssimos recursos para cumprir sua tarefa. Grolin teve que estabelecer um entreposto nas colinas nevadas e recorrer a recrutas locais e iniciados de passagem para realizar o trabalho necessário."},{t="Problemas no Sul",b="De seu acampamento, Grolin monitora o avanço da tribo Frostmane ao sul do Vale Cristálgida. Os trolls tornaram-se cada vez mais agressivos, realizando incursões mais ousadas fora de suas cavernas montanhosas. Durante um desses ataques, um brutamontes fortemente pintado chamado Grik'nir the Cold entrou sorrateiramente no acampamento desacompanhado e fugiu com o diário de campo de Grolin, contendo suas observações essenciais. Não querendo falhar com o Rei, Grolin recorre a viajantes intrépidos para adentrar profundamente as cavernas dos Frostmane, recuperar seus escritos roubados e garantir que seus relatórios finais cheguem a Senir em Kharanos."}},faq={{q="Por que Grolin Barbabranca está aqui no meio da neve?",a="Grolin foi oficialmente comissionado pelo Senado de Altaforja e pelo Rei Magni Barbabronze para investigar e conter a ameaça dos trolls Frostmane no Vale Cristálgida. Como os militares anões estão ocupados combatendo a ameaça trogg em outros lugares, Grolin precisa recorrer a voluntários independentes.",al={"por que grolin está aqui","propósito de grolin barbabranca","quem é grolin barbabranca"}},{q="Quem roubou o diário de Grolin?",a="Um troll Frostmane chamado Grik'nir the Cold saqueou o acampamento de Grolin enquanto ele estava desacompanhado. Grolin apenas viu de relance um brutamontes com muitas marcas fugindo para as cavernas de trolls ao sul com suas anotações de campo.",al={"quem roubou o diário","ladrão do diário roubado","diário de grolin"}},{q="Quem é o irmão de Grolin?",a="Seu irmão é Senir Barbabranca, um operativo posicionado mais abaixo na montanha, na vila de Kharanos. Grolin compila suas descobertas sobre os movimentos dos trolls em relatórios e envia mensageiros de confiança para entregá-los diretamente a Senir.",al={"irmão de grolin","senir barbabranca","quem é senir"}},{q="Quem está com Grolin em seu acampamento?",a="Não há registro de nenhum companheiro dele. Ele e seu irmão Senir foram enviados para lidar com os trolls por conta própria, portanto Grolin tem pouca ajuda até que recrutas capazes cheguem, e seu acampamento estava desacompanhado quando os trolls o saquearam.",al={"npcs do acampamento barbabranca","quem está com grolin","companheiros de grolin"}},{q="Por que Altaforja não envia soldados regulares para ajudá-lo?",a="Os defensores de Altaforja e as forças do Senado estão quase inteiramente consumidos pelas infestações generalizadas de troggs que eclodiram por toda Dun Morogh. Isso deixa batedores como Grolin para resolver ameaças regionais usando recrutas locais.",al={"por que nenhum exército de anões","onde está a guarda de altaforja","por que nenhum soldado"}}},fx={d217c46a={q="De que lado está Grolin Barbabranca?",a="Grolin Barbabranca é inteiramente leal ao Reino de Altaforja e à Grande Aliança. Ele responde diretamente ao Senado de Altaforja e transporta despachos com o selo do próprio Rei Magni, trabalhando incansavelmente para proteger as terras anãs contra ameaças externas.",al={"facção de grolin barbabranca","para quem grolin trabalha","grolin é da aliança"}},["6d2fc414"]={q="O que Grolin Barbabranca quer?",a="Grolin quer uma resolução rápida para o problema dos trolls Presagélida no sul do Vale Cristálgida. Como a guarda anã está ocupada lutando contra incursões de troggs, ele precisa de aventureiros capazes para eliminar os trolls agressivos, recuperar seu diário roubado do líder troll Grik'nir e entregar seu relatório de reconhecimento finalizado ao irmão dele em Kharanos.",al={"o que grolin está tentando fazer","objetivo de grolin barbabranca","o que grolin precisa"}},bc052fbe={q="Quem é Grolin Barbabranca?",a="Grolin Barbabranca é um investigador enviado ao Vale Cristálgida em nome do Senado de Altaforja e do Rei Magni Barbabronze. Encarregado de avaliar os movimentos agressivos dos trolls Presa-de-gelo, ele mantém um acampamento remoto no vale nevado, contando com recrutas montanheses novatos para repelir os trolls enquanto o exército anão principal está ocupado em outro lugar.",al={"quem é grolin","história de grolin barbabranca","quem é barbabranca"}}},fp="17,282,15.563.0,20.567.0,46.284.0,27.207.0,24.228.0,31.221.0,56.221.0"}
P.entries["npc:greta-mosshoof"] = {n="Greta Musgo no Casco",s="Greta Musgo no Casco é uma druida tauren aliada ao Círculo Esmeraldino no Santuário Esmeralda, no sul de Selva Maleva. Ao lado de elfos noturnos e de outros guardiões da natureza, ela investiga a mácula fétida que se espalha pela floresta ancestral e orienta batedores até Jaedenar, a fortaleza do Conselho das Sombras.",h="Greta Musgo no Casco é uma druida tauren aliada ao Círculo Esmeraldino no Santuário Esmeralda, no sul de...",kw={"água corrompida","círculo esmeraldino","santuário esmeralda","selva maleva","greta musgo no casco","islen vidente da água","jaedenar"},ang={["class:Druid"]="Para os druidas que trabalham para expurgar as cicatrizes da Legião Ardente, Greta Musgo no Casco representa o espírito cooperativo do Círculo Cenariano, deixando de lado as lealdades de facção para restaurar a natureza selvagem de Kalimdor.",["race:Tauren"]="Greta demonstra a dedicação dos taurens em curar as feridas da Mãe Terra, mesmo muito ao norte, em terras antes protegidas unicamente pelos elfos noturnos."},sec={{t="Guardiã da Floresta",b="Alocada no Santuário Esmeralda, no limite sul de Selva Maleva, Greta Musgo no Casco trabalha ao lado do Círculo Esmeraldino para combater a corrupção generalizada que consome os bosques ancestrais. Em vez de entregar as terras devastadas à mácula demoníaca deixada na esteira da Terceira Guerra, ela coordena esforços para compreender e repelir a podridão que avança. Suas investigações focam nas águas envenenadas de Selva Maleva e nos cultistas asquerosos entrincheirados em Jaedenar."},{t="Golpeando o Conselho das Sombras",b="Greta Musgo no Casco é fundamental para desvendar as maquinações do Conselho das Sombras que opera nas profundezas de Jaedenar. Reconhecendo que as fontes corrompidas e as proteções vis no abismo alimentam diretamente a enfermidade que sufoca a terra, ela recruta viajantes para coletar amostras das águas maculadas, buscar a ajuda de xamãs como Islen Vidente da Água na costa distante e destruir os braseiros rituais que protegem a cabala demoníaca de intrusões."}},faq={{q="Quem é Greta Musgo no Casco?",a="Greta Musgo no Casco é uma tauren membro do Círculo Esmeraldino alocada no Santuário Esmeralda, em Selva Maleva. Ela ajuda viajantes e druidas a investigar e desfazer a praga demoníaca que envenena a floresta.",al={"história de greta musgo no casco","quem é greta musgo no casco","greta selva maleva"}},{q="A qual facção Greta Musgo no Casco pertence?",a="Greta Musgo no Casco é membro do Círculo Esmeraldino, uma organização neutra dedicada a curar a natureza. Como tal, ela oferece orientação e missões para aventureiros tanto da Aliança quanto da Horda.",al={"greta musgo no casco é horda ou aliança","reputação greta musgo no casco","facção de greta"}},{q="Por que Greta envia aventureiros para Jaedenar?",a="Jaedenar é a fortaleza do Conselho das Sombras em Selva Maleva, responsável por bombear bile demoníaca nos cursos de água da região e manter proteções que abrigam demônios. Greta direciona ataques contra Jaedenar para interromper seus rituais e purificar as fontes maculadas.",al={"por que missão de jaedenar","greta musgo no casco jaedenar","motivo de forças de jaedenar"}},{q="Qual é a ligação de Greta Musgo no Casco com Islen Vidente da Água?",a="Greta é amiga de Islen Vidente da Água, uma sábia xamã que reside ao longo da costa dos Sertões. Quando Greta descobre amostras de água corrompida de Selva Maleva, ela orienta os aventureiros a buscarem o domínio espiritual de Islen para purificar o fluido, permitindo que ele limpe as fontes envenenadas.",al={"greta e islen","ligação com islen vidente da água"}}},fp="14,297,22.465.0,30.441.1,22.202.0,43.181.0,47.265.0,55.268.0"}
P.entries["npc:grif-wildheart"] = {n="Grif Selvacuore",s="Grif Selvacuore é um experiente instrutor de caçadores anão posicionado do lado de fora da Destilaria Cervaforte em Kharanos. Famoso entre os montanhistas locais por sua profunda afinidade com a vida selvagem, ele instrui atiradores novatos em rastreamento, pontaria e nos ritos de adestramento de feras. Para os jovens caçadores que saem do Vale Cristálgida, Grif oferece a ponte vital entre disparar um rifle e caminhar ao lado de um companheiro animal leal.",h="Grif Selvacuore é um experiente instrutor de caçadores anão posicionado do lado de fora da Destilaria...",kw={"adestramento de feras","dun morogh","grif selvacuore","instrutor de caçadores","kharanos","montanhista","taming the beast","destilaria cervaforte"},ang={["class:Hunter"]="Grif é o mentor essencial que inicia os caçadores da Aliança no adestramento de feras, oferecendo as missões vitais que permitem a você criar laços com predadores selvagens por toda Dun Morogh.",["faction:Alliance"]="Posicionado em Kharanos, Grif prepara batedores e atiradores de elite da Aliança para sobreviver aos ermos implacáveis que cercam o reino montanhoso de Altaforja.",["race:Dwarf"]="Personificando a tradição dos montanhistas anões, Grif mostra como a resistência rústica de um anão o torna excepcionalmente adequado para viver lado a lado com feras selvagens das montanhas."},sec={{t="Uma Vida nos Ermos",b="Enquanto muitos anões de Altaforja preferem o calor ardente de uma forja ou o tinir constante das picaretas, Grif Selvacuore dedicou sua vida inteiramente à vastidão congelada de Dun Morogh. Os montanhistas locais dizem em tom de brincadeira que ele passa tempo demais com feras de quatro patas, mas ninguém contesta seu domínio da natureza. Tendo passado anos rastreando através de cumes cobertos de neve ao lado de companheiros de caça experientes, Grif possui uma compreensão íntima dos predadores naturais que vagam pelos penhascos."},{t="O Caminho da Fera",b="Quando os jovens caçadores anões terminam suas provações preliminares no Vale Cristálgida, eles são orientados a ir direto a Kharanos para buscar a orientação de Grif. Enquanto aprimora a pontaria deles e ensina truques essenciais de sobrevivência nos ermos, sua verdadeira especialidade está em forjar laços entre caçador e fera. Por meio de uma série de provações rigorosas, Grif envia seus pupilos para as terras devastadas e congelantes com um Bastão de Adestramento para testar sua coragem contra os predadores emblemáticos de Dun Morogh: Large Crag Boars, Snow Leopards e Ice Claw Bears."},{t="Jornada ao Hall of Arms",b="Assim que um caçador demonstra a determinação e a serenidade necessárias para acalmar três feras selvagens distintas, a tutela de Grif em Kharanos chega ao fim. Reconhecendo que um caçador também deve aprender a alimentar, disciplinar e treinar seu novo aliado, ele envia seus formandos montanha acima para Altaforja. Lá, sob os grandes tetos abobadados da capital dos anões, os caçadores novatos se apresentam a mestres instrutores de feras para aprender a arte mais profunda de cuidar de seu companheiro permanente para a vida toda."}},faq={{q="Quem é Grif Selvacuore?",a="Grif Selvacuore é um instrutor de caçadores anão localizado em Kharanos, em Dun Morogh. Ele atua como o principal mentor para os caçadores novatos da Aliança que aprendem seu ofício fora do Vale Cristálgida.",al={"quem é grif","identidade de grif selvacuore","sobre grif"}},{q="Onde posso encontrar Grif Selvacuore?",a="Ele fica do lado de fora, perto da Destilaria Cervaforte, no vilarejo de Kharanos, ao longo da estrada nevada que liga o Caminho de Cristálgida a Altaforja.",al={"localização de grif selvacuore","onde fica grif","grif em kharanos"}},{q="O que Grif ensina aos caçadores novatos?",a="Além de oferecer habilidades gerais de caçador e técnicas de combate à distância, Grif orienta os jovens caçadores nas provações de adestramento de feras, ensinando-os a acalmar e dominar javalis, leopardos e ursos selvagens.",al={"o que grif ensina","treinamento de caçador de grif","habilidades de grif"}},{q="Quais feras Grif envia os caçadores para adestrar?",a="Grif incumbe seus alunos de rastrear e adestrar três criaturas específicas de Dun Morogh: um Large Crag Boar, um Snow Leopard e um Ice Claw Bear.",al={"missões de adestramento de grif","quais animais adestrar dun morogh","alvos de taming the beast"}},{q="Para onde Grif envia os caçadores após completarem suas provações de adestramento?",a="Após provarem sua capacidade de adestrar animais selvagens, Grif orienta os caçadores a viajarem até a cidade de Altaforja para consultar instrutores avançados de feras sobre como alimentar e comandar seus mascotes.",al={"onde ir depois de grif","próximo passo de training the beast","missão seguinte de grif"}},{q="O que os montanhistas de Altaforja acham de Grif?",a="Os Montanhistas de Altaforja locais comentam, em tom de brincadeira, que Grif passa tempo demais na companhia de animais em vez de pessoas, mas admitem prontamente que ele conhece o ofício de caçador melhor do que quase qualquer um.",al={"opinião dos montanhistas sobre grif","grif é respeitado","reputação de grif"}}},fx={["5a030de6"]={q="De que lado está Grif Selvacuore?",a="Grif Selvacuore é firmemente leal a Altaforja e à Grande Aliança. Ele serve seu povo mentorando jovens caçadores anões em Kharanos, garantindo que eles tenham a disciplina e as habilidades de sobrevivência necessárias para proteger o reino montanhês e seus territórios.",al={"facção de grif selvacuore","grif é da aliança","lealdade de grif selvacuore"}},a3b5e7f5={q="O que Grif Selvacuore quer?",a="Grif dedica-se a transmitir o ofício da natureza. Ele quer que aspirantes a caçador dominem a domesticação de feras e a sobrevivência na natureza, enviando noviços para as neves de Dun Morogh para aprenderem respeito, paciência e como forjar laços duradouros com as criaturas das escarpas.",al={"objetivo de grif selvacuore","o que grif quer","motivação de grif selvacuore"}},["20183458"]={q="Por que Grif Selvacuore está em Kharanos?",a="Grif está estacionado em Kharanos para treinar recrutas recém-chegados que se aventuram descendo do Vale Cristálgida. Como um cruzamento central em Dun Morogh, Kharanos é o campo de provas ideal para jovens caçadores prontos para testar sua astúcia contra javalis, leopardos e ursos da montanha.",al={"por que grif está aqui","por que grif selvacuore está em dun morogh","por que grif está em kharanos"}}},fp="14,424,19.495.0,20.507.0,27.472.0,22.187.0,32.138.0,36.200.0,43.152.0,66.188.0,49.198.0"}
P.entries["npc:grimbooze-thunderbrew"] = {n="Canabraba Cervaforte",s="Canabraba Cervaforte é um excêntrico cervejeiro anão do clã Cervaforte, acampado nos Obeliscos de Cerro Oeste. Ele passa os dias preparando destilados potentes e falando quase inteiramente em versos.",h="Canabraba Cervaforte é um excêntrico cervejeiro anão do clã Cervaforte, acampado nos Obeliscos de Cerro Oeste.",kw={"cerveja","cervejeiro","os obeliscos","destilaria","canabraba","kharanos","thunderbrew","cerro oeste"},ang={["profession:Cooking"]="Aventureiros culinários e artesãos de destilados reverenciam o legado dos Cervaforte, tornando o encontro com Canabraba uma lição de fabricação artesanal.",["race:Dwarf"]="Todo anão conhece o nome Cervaforte, e encontrar um dos irmãos Cervaforte preparando receitas selvagens nas colinas de Cerro Oeste é um gostinho bem-vindo de Dun Morogh."},sec={{t="Um Cervejeiro no Exílio",b="Vindo da renomada família de cervejeiros Cervaforte de Kharanos, Canabraba deixou os picos montanhosos e nevados de Dun Morogh pelas colinas açoitadas pelo vento de Cerro Oeste. Conhecido por sua disposição jovial e uma paixão inabalável por destilados potentes, ele tem o hábito peculiar de falar estritamente em rimas e responde às perguntas dos viajantes apenas quando eles realizam uma tarefa simples para ele. Os viajantes que passam pelos perigosos Obeliscos podem encontrá-lo cuidando de seus barris particulares, sempre ansioso para testar o paladar de um viajante sedento."}},faq={{q="Onde posso encontrar Canabraba Cervaforte?",a="Canabraba Cervaforte está instalado nos Obeliscos, situados no sul de Cerro Oeste, mantendo acampamento entre as colinas com seu equipamento de fermentação.",al={"localização de canabraba","onde fica canabraba","onde encontrar canabraba cervaforte"}},{q="Por que Canabraba fala em rimas?",a="Ninguém sabe ao certo. Canabraba simplesmente se deleita com versos e insiste que qualquer pessoa com uma pergunta para ele deve primeiro completar uma tarefa simples.",al={"por que canabraba rima","canabraba rimando","por que ele fala em versos"}},{q="Qual é a ligação dele com a Destilaria Cervaforte?",a="Canabraba é membro do famoso clã Cervaforte de Kharanos, em Dun Morogh. Enquanto parentes como Ragnar Cervaforte cuidam da destilaria da família em sua terra natal, Canabraba produz por conta própria nas colinas de Cerro Oeste.",al={"destilaria de canabraba","canabraba é parente de ragnar","família cervaforte"}}},fx={["21ebedd0"]={q="Quem é Canabraba Cervaforte?",a="Canabraba é um cervejeiro anão peculiar e jovial, vindo do famoso clã Cervaforte de Dun Morogh. Conhecido por seu amor lendário pela cerveja e sua inclinação a falar em enigmas e versos, ele deixou o lar da família em Kharanos para produzir cerveja por conta própria nas colinas de Cerro Oeste.",al={"quem é canabraba","canabraba cervaforte","sobre canabraba"}},["182004c2"]={q="De que lado está Canabraba Cervaforte?",a="Canabraba é leal a Altaforja e à Aliança, como o resto do clã Cervaforte. No entanto, sua verdadeira paixão reside inteiramente na fabricação de cerveja e bebidas finas, e não em política ou guerras de facções, tornando-o um rosto amigável para qualquer um que aprecie uma boa cerveja preta.",al={"facção de canabraba","canabraba é da aliança","lado de canabraba"}},["9bf66a40"]={q="O que Canabraba Cervaforte quer?",a="Canabraba está sempre procurando produzir suas cervejas exclusivas e compartilhá-las com outros viajantes. Em troca de ingredientes ou um pouco de ajuda, ele fica mais do que feliz em oferecer a você amostras da potente lager Cervaforte para manter seu ânimo elevado.",al={"o que canabraba quer","objetivo de canabraba","por que canabraba precisa de lúpulo"}},d50f3d5e={q="Por que Canabraba Cervaforte está em Cerro Oeste?",a="Canabraba deixou os picos frios de Dun Morogh para trás, indo para Os Obeliscos, onde ele agora passa seus dias fabricando cerveja e meditando em versos, longe da destilaria da família em Kharanos.",al={"por que canabraba está em cerro oeste","canabraba em cerro oeste por quê","o que canabraba está fazendo em cerro oeste"}}},fp="21,205,17.528.0,39.144.0,36.149.0,53.204.0"}
P.entries["npc:grish-longrunner"] = {n="Grish Pisa Léguas",s="Grish Pisa Léguas é um batedor e mensageiro tauren posicionado perto do Grande Elevador, a travessia mecânica vital que conecta os Sertões Meridionais aos desfiladeiros de Mil Agulhas. Servindo aos interesses da Horda ao longo dessa fronteira movimentada, ele vigia os viajantes e coordena os movimentos militares através da divisa.",h="Grish Pisa Léguas é um batedor e mensageiro tauren posicionado perto do Grande Elevador, a travessia mecânica...",kw={"sertões","chamando as reservas","o grande elevador","grish","pisa léguas","tauren","mil agulhas"},ang={["faction:Horde"]="Para mensageiros e guerreiros da Horda que viajam para o sul em direção a Mil Agulhas ou retornam para o norte rumo aos Sertões, Grish serve como uma sentinela e ponto de contato importante junto ao elevador.",["race:Tauren"]="Carregando o orgulhoso sobrenome Pisa Léguas, Grish representa a resistência e a vigilância dos shu'halo enquanto protegem rotas vitais através de suas terras ancestrais."},sec={{t="Vigia no Elevador",b="Posicionado bem ao lado do imponente maquinário do Grande Elevador, Grish Pisa Léguas vigia uma das passagens de fronteira mais precárias da região central de Kalimdor. A plataforma do elevador é uma linha de vida que conecta os ermos áridos dos Sertões Meridionais às mesas açoitadas pelo vento de Mil Agulhas, abaixo. Entre bandos errantes de javatuscos e ameaças territoriais concorrentes, viajar ao longo desta fronteira vertical é perigoso, tornando batedores como Grish essenciais para manter a Horda informada e convocar reforços onde são desesperadamente necessários."}},faq={{q="Quem é Grish Pisa Léguas?",a="Grish Pisa Léguas é um batedor tauren aliado à Horda que está posicionado na borda do Grande Elevador, o qual desce dos Sertões até Mil Agulhas.",al={"quem é grish","identidade de grish pisa léguas","o que grish faz"}},{q="Onde posso encontrar Grish Pisa Léguas?",a="Ele está localizado nos confins ao sul dos Sertões, bem perto da entrada mecânica do Grande Elevador que desce para Mil Agulhas.",al={"localização de grish pisa léguas","onde fica grish","encontrar grish"}},{q="Qual é o papel dele na região?",a="Grish atua como um ponto de contato para mensageiros e viajantes da Horda, ajudando principalmente a reunir e direcionar reforços locais por meio de pedidos como Chamando as reservas.",al={"propósito de grish","missões de grish","chamando as reservas grish"}}},fx={["0053ed11"]={q="De que lado está Grish Pisa Léguas?",a="Grish é um membro orgulhoso das tribos tauren e é leal à Horda. Operando em torno das fronteiras dos Sertões e a descida para Mil Agulhas, ele serve como um ponto de contato para viajantes da Horda que navegam pelas perigosas passagens entre as regiões.",al={"facção de grish pisa léguas","grish é da horda","lealdade de grish pisa léguas"}}},fp="16,329,19.537.0,24.164.0,34.140.0,35.180.0"}
P.entries["npc:grub"] = {n="Grude",s="Grude é um orc empreendedor que vive em uma cabana à beira da estrada a leste da Encruzilhada, nos Sertões. Administrando um modesto restaurante de fronteira ao lado de um cozinheiro e de um padeiro, ele é famoso — ou talvez notório — por apresentar aos viajantes os usos culinários de pragas locais.",h="Grude é um orc empreendedor que vive em uma cabana à beira da estrada a leste da Encruzilhada, nos Sertões.",kw={"sertões","a encruzilhada","ensopado de ratoupeira","duhng","grude","tarban hearthgrain"},ang={["faction:Horde"]="Situada nos arredores da Encruzilhada, a cozinha de beira de estrada de Grude fornece sustento substancial e uma lição de engenhosidade para os viajantes da Horda que sobrevivem às planícies implacáveis.",["profession:Cooking"]="Grude é uma parada essencial para aspirantes a cozinheiros da fronteira, disposto a compartilhar a receita do Ensopado de ratoupeira com qualquer um com coragem suficiente para reunir os ingredientes."},sec={{t="Um apetite da fronteira",b="Aninhado junto aos penhascos a leste da Encruzilhada, Grude supervisiona uma morada rústica compartilhada com Duhng, seu cozinheiro, e Tarban Hearthgrain, um padeiro. Embora a vida nas planícies exija um estômago forte, Grude leva a autossuficiência da fronteira ao extremo. Em vez de deixar as abundantes ratoupeiras dos Sertões serem desperdiçadas, ele as transformou em um ingrediente básico, oferecendo-se para ensinar aos viajantes que passam por ali como cozinhar os roedores subterrâneos em um ensopado saboroso, ainda que pouco glamouroso."}},faq={{q="Quem é Grude?",a="Grude é um orc que reside em uma cabana a leste da Encruzilhada, nos Sertões. Ele administra um pequeno estabelecimento ao lado de seu cozinheiro, Duhng, e de um padeiro chamado Tarban Hearthgrain, atendendo a viajantes que passam pela fronteira empoeirada.",al={"grude","quem é grude","orc a leste da encruzilhada"}},{q="Onde posso encontrar Grude?",a="Grude pode ser encontrado a leste da Encruzilhada, ao longo do pé das montanhas nos Sertões, situado dentro de uma pequena moradia fora do caminho principal.",al={"localização de grude","onde fica grude","cabana de grude"}},{q="Com o que Grude precisa de ajuda?",a="Grude encarrega os viajantes de coletar ratoupeiras dos Sertões, que são usadas para preparar seu famoso Ensopado de ratoupeira. Em troca, ele compartilha a receita com cozinheiros dispostos a prepará-la.",al={"missão de grude","missão ensopado de ratoupeira"}}},fx={["1dd1f89b"]={q="De que lado está Grude?",a="Grude é um orc aliado à Horda, operando pacificamente logo fora da Encruzilhada, nos Sertões. Ele recebe viajantes da Horda em sua pequena propriedade, fazendo negócios com colegas cozinheiros, padeiros e aventureiros de passagem sem se envolver em conflitos militares.",al={"facção de grude","grude é da horda","grude é aliança ou horda"}},bef281f8={q="Por que Grude está aqui?",a="Grude montou um pequeno assentamento doméstico a leste da Encruzilhada, na base das montanhas. Em vez de servir nas linhas de frente, ele administra uma habitação culinária junto com seu cozinheiro Duhng e o padeiro Tarban Hearthgrain, obtendo e preparando comida local da fronteira.",al={"por que grude está nos sertões","cabana de grude encruzilhada","o que grude está fazendo aqui"}},c7807b4d={q="A quem Grude está ligado?",a="Grude compartilha sua cabana à beira da estrada com Duhng, que cuida da cozinha, e Tarban Hearthgrain, que gerencia a panificação. Juntos, esse grupo improvável de companheiros administra seu pequeno lar nas planícies acidentadas dos Sertões.",al={"com quem grude trabalha","companheiros de grude","associados de grude"}}},fp="4,263,19.477.0,12.229.0,22.144.0,30.181.0"}
P.entries["npc:grull-hawkwind"] = {n="Grull Vento do Falcão",s="Grull Vento do Falcão é um jovem bravo tauren situado na Aldeia Narache, na Chapada Nuvem Vermelha, em Mulgore. Como filho do Chefe Vento do Falcão, ele ajuda a guiar os taurens novatos que estão dando seus primeiros passos no mundo. Ele orienta jovens caçadores e guerreiros em suas primeiras provações para testar sua determinação e honrar seus ancestrais.",h="Grull Vento do Falcão é um jovem bravo tauren situado na Aldeia Narache, na Chapada Nuvem Vermelha, em...",kw={"aldeia narache","chefe vento do falcão","grull vento do falcão","mulgore","chapada nuvem vermelha","rito de força","tauren"},ang={["class:Hunter"]="Grull oferece tarefas iniciais fundamentais a caçadores novatos, testando sua paciência e habilidade contra a fauna de Mulgore.",["race:Tauren"]="Para os jovens taurens que chegam à Chapada Nuvem Vermelha, Grull Vento do Falcão costuma ser o primeiro bravo a testar sua coragem e apresentá-los às tradições dos Shu'halo."},sec={{t="O Filho de um Chefe",b="Erguendo-se com orgulho ao lado dos bravos e anciãos da Aldeia Narache, Grull Vento do Falcão carrega tanto a linhagem nobre do Chefe Vento do Falcão quanto a responsabilidade de preparar a juventude da tribo. Ele atua como mentor inicial para os recém-chegados à Chapada Nuvem Vermelha, avaliando sua prontidão para servir aos Shu'halo. Ao designar provações que testam vigor, rastreamento e sobrevivência contra feras locais, como pisaplanícies e pumas-da-montanha, Grull garante que os jovens taurens compreendam que o equilíbrio e o respeito pela natureza são fundamentais para a vida em Mulgore."}},faq={{q="Quem é Grull Vento do Falcão?",a="Grull Vento do Falcão é um tauren concedente de missões que reside na Aldeia Narache, na Chapada Nuvem Vermelha. Ele é filho do Chefe Vento do Falcão, o líder do assentamento, e atua como um dos principais mentores dos jovens taurens que estão iniciando sua jornada.",al={"papel de grull vento do falcão","quem é grull","história de grull vento do falcão"}},{q="Qual papel Grull Vento do Falcão desempenha para jovens aventureiros?",a="Grull avalia o treinamento básico dos taurens novatos, recebendo notas introdutórias dos anciãos tribais e incumbindo os jovens de suas provações iniciais de caça e sobrevivência nas planícies ao redor.",al={"missões de grull","o que grull faz","propósito de grull vento do falcão"}},{q="Grull tem parentesco com a liderança do acampamento?",a="Sim, Grull é filho do Chefe Vento do Falcão, o chefe da Aldeia Narache. Ele mantém as tradições de seu pai e ajuda a preparar os defensores do acampamento.",al={"filho do chefe vento do falcão","família de grull vento do falcão","grull é parente do chefe"}}},fx={["36d17655"]={q="De que lado está Grull Vento do Falcão?",a="Grull Vento do Falcão apoia orgulhosamente as tribos tauren e a Horda. Residindo na Aldeia Narache, ele serve seu povo sob a liderança de seu pai e Alto Chefe Caerne Casco Sangrento, dedicado a ajudar jovens tauren a crescerem como defensores capazes de sua pátria ancestral em Mulgore.",al={"facção de grull vento do falcão","a quem grull serve","lealdade de grull vento do falcão"}},["56962b2d"]={q="O que Grull Vento do Falcão quer?",a="Grull quer ver jovens tauren provarem sua força e devoção à tribo. Ele testa os jovens que chegam para garantir que possuam a força, a disciplina e as habilidades de caça necessárias para sobreviver na natureza e proteger a Aldeia Narache de ameaças próximas.",al={"o que grull quer","objetivos de grull vento do falcão","por que grull dá missões"}},["379dd378"]={q="Por que Grull Vento do Falcão está aqui na Aldeia Narache?",a="A Aldeia Narache é o campo de testes ancestral para jovens em Coming of Age na Chapada Nuvem Vermelha, e é governada pelo pai de Grull, o Chefe Vento do Falcão. Grull permanece aqui para ajudar a guiar novos iniciados através de seus ritos de abertura e apoiar a liderança de sua família sobre o acampamento.",al={"por que grull está aqui","papel de grull na aldeia narache","por que grull está na chapada nuvem vermelha"}}},fp="14,320,17.542.0,22.230.0,57.194.0,42.146.0"}
P.entries["npc:grunt-dogran"] = {n="Bruto Dogran",s="O Bruto Dogran é um soldado orc da Horda mantido prisioneiro nas profundezas do território dos javatuscos nos Sertões Meridionais. Originalmente designado para a Encruzilhada e mais tarde para o Acampamento Taurajo, sua patrulha encontrou o desastre durante um ataque a Agama'gor.",h="O Bruto Dogran é um soldado orc da Horda mantido prisioneiro nas profundezas do território dos javatuscos nos...",kw={"agama'gor","sertões","acampamento taurajo","encruzilhada","dogran","dorgran","bruto dogran","quilboar"},ang={["faction:Horde"]="Sua captura ilustra o alto preço que as guarnições da Horda pagam para proteger as rotas comerciais e fronteiras pelos Sertões contra tribos agressivas de javatuscos.",["race:Orc"]="Dogran exemplifica o ideal tradicional orc de que morrer em combate traz mais honra do que sobreviver como um inválido indefeso."},sec={{t="O Dever de um Bruto",b="Após sua promoção nas forças militares da Horda, o Bruto Dogran foi enviado da Encruzilhada para reforçar o Acampamento Taurajo. Enquanto liderava um destacamento de brutos no território eriçado de Agama'gor, sua unidade entrou em confronto feroz contra os javatuscos Bristleback. Gravemente ferido e incapacitado durante o combate, Dogran não pôde ser carregado por seus camaradas em retirada e foi arrastado para o cativeiro."},{t="Um Destino Honrado",b="Apesar de encurralado atrás das linhas inimigas e incapacitado por seus ferimentos, Dogran mantém o orgulho obstinado típico dos guerreiros orcs. Em vez de voltar para casa debilitado e forçar sua companheira a cuidar de um inválido, ele escolheu fazer uma última resistência contra os javatuscos, pedindo apenas que uma lembrança de sua eterna devoção seja devolvida àquela a quem ama."}},faq={{q="Onde fica o Bruto Dogran?",a="Dogran é mantido cativo em Agama'gor, um denso acampamento de javatuscos situado nos Sertões Meridionais, logo ao norte do Acampamento Taurajo.",al={"localização de dogran","onde fica dogran","encontrar dogran sertões"}},{q="Por que Dogran foi capturado pelos javatuscos?",a="Ao liderar uma patrulha do Acampamento Taurajo para atacar os javatuscos, Dogran sofreu ferimentos incapacitantes durante o combate. Seus companheiros não conseguiram transportá-lo a tempo, deixando-o à mercê das feras.",al={"por que dogran foi capturado","como dogran foi pego"}},{q="Por que Dogran se recusa a ser resgatado?",a="Dogran ficou permanentemente incapacitado em batalha e se recusa a voltar para casa como um fardo para sua companheira. No verdadeiro estilo orc, ele prefere morrer em seus próprios termos contra os javatuscos a viver seus dias como um inválido.",al={"por que dogran não quer ir embora","resgate de dogran"}},{q="Quem está procurando por Dogran?",a="Sua companheira Zankaja em Orgrimmar, que não tem notícias dele desde que ele partiu para o serviço. Sua preocupação faz com que viajantes sejam enviados a Gazrog na Encruzilhada e, em seguida, ao Bruto Logmar no Acampamento Taurajo, onde os soldados reconstituem o destino de sua patrulha desaparecida.",al={"quem me enviou atrás de dogran","quem dá a missão de dogran"}}},fx={["3efd280a"]={q="Quem é o Bruto Dogran?",a="O Bruto Dogran é um soldado orc da Horda. Após ganhar uma promoção, ele foi destacado para a Encruzilhada antes de ser transferido para o Acampamento Taurajo. Enquanto liderava um destacamento de brutos para os Sertões Meridionais para confrontar os quilboar, ele ficou gravemente ferido em combate e capturado pelas feras, que agora o mantêm preso em seu acampamento em Agama'gor.",al={"quem é dogran","identidade do bruto dogran","história de dogran"}},["30754355"]={q="De que lado o Bruto Dogran está?",a="Dogran é um soldado leal da Horda. Ele serve com orgulho como um bruto sob o comando do Chefe Guerreiro, destacado nos Sertões para defender entrepostos e assentamentos da Horda contra forças hostis como os javatuscos Ventrancada e Cerda-espinho.",al={"dogran é da horda","lealdade de dogran","facção de dogran"}}},fp="12,236,14.400.0,17.335.1,30.126.0,40.210.0,37.209.1,26.243.0"}
P.entries["npc:grunt-logmar"] = {n="Bruto Logmar",s="O Bruto Logmar é um guerreiro orc da Horda destacado no sul dos Sertões, no Acampamento Taurajo. Cumpridor do dever e vigilante, ele monitora as ameaças ao redor do acampamento e coordena esforços para localizar e ajudar batedores da Horda desaparecidos na região.",h="O Bruto Logmar é um guerreiro orc da Horda destacado no sul dos Sertões, no Acampamento Taurajo.",kw={"acampamento taurajo","dogran","bruto logmar","trago do ken'zigla","bruto orc","taurajo","sertões"},ang={["faction:Horde"]="Logmar representa a presença militar da linha de frente que apoia os taurens nos Sertões, contando com campeões da Horda para cuidar de batedores caídos e capturados.",["race:Orc"]="Como um bruto orc destacado longe de Orgrimmar, Logmar demonstra o compromisso da Horda em permanecer ombro a ombro com seus aliados taurens."},sec={{t="Dever no Acampamento Taurajo",b="Estacionado entre os taurens no Acampamento Taurajo, o Bruto Logmar atua como um guarda orc atento na fronteira sul dos Sertões. O assentamento fica perto de territórios hostis de javatuscos e das passagens montanhosas que levam a Cordilheira das Torres de Pedra e Mulgore, exigindo vigilância constante. Logmar coordena relatórios de batedores e busca a ajuda de viajantes capazes da Horda quando seus camaradas são emboscados ou capturados por inimigos locais."}},faq={{q="Quem é o Bruto Logmar?",a="O Bruto Logmar é um soldado orc destacado no Acampamento Taurajo, nos Sertões Meridionais, servindo à Horda ao proteger o assentamento e supervisionar tarefas de resgate e reconhecimento.",al={"bruto logmar","quem é logmar","logmar sertões"}},{q="Onde o Bruto Logmar pode ser encontrado?",a="Ele está localizado no Acampamento Taurajo, um entreposto situado nas planícies do sul dos Sertões, ao longo da estrada que leva em direção ao Grande Elevador e a Mil Agulhas.",al={"onde fica logmar","localização de logmar","encontrar bruto logmar"}},{q="Quais assuntos Logmar supervisiona?",a="Logmar cuida da segurança de batedores da Horda desaparecidos, encarregando viajantes principalmente de investigar o desaparecimento e o cativeiro de seu companheiro, o Bruto Dogran, além de obter suprimentos vitais, como o Trago do Ken'zigla.",al={"missões de logmar","o que logmar quer","resgate de dogran"}}},fx={ce116068={q="De que lado está o Bruto Logmar?",a="O Bruto Logmar é um soldado leal da Horda. Estacionado entre os assentamentos tauren, ele serve ao Chefe Guerreiro vigiando as fronteiras do sul e apoiando as operações da Horda por todas as planícies.",al={"logmar é da horda","facção do bruto logmar","lado do bruto logmar"}},["1f3f5c49"]={q="Por que o Bruto Logmar está aqui?",a="Logmar está posicionado como um guarda de vanguarda para reforçar a defesa e manter a comunicação militar. A natureza ao redor apresenta ameaças constantes de vida selvagem hostil, saqueadores centauros e quilboar próximos, exigindo soldados firmes para proteger os viajantes e garantir os Sertões Meridionais.",al={"por que o bruto logmar está aqui","por que logmar está em taurajo","posto de logmar"}},e7dd0701={q="O que o Bruto Logmar quer?",a="Logmar busca ajuda para resolver emergências militares urgentes na região, particularmente o resgate e a recuperação de camaradas capturados como Dogran, e a obtenção de poções restauradoras necessárias para sustentar seus colegas combatentes no campo.",al={"o que o logmar quer","objetivo do bruto logmar","o que o bruto logmar precisa"}}},fp="12,235,20.419.0,20.174.0,32.155.0,33.201.0"}
P.entries["npc:grunth"] = {n="Grunth",s="Grunth é um jovem órfão orc enérgico que vive sob os cuidados do orfanato de Orgrimmar no Arranco. Durante a Semana das Crianças, ele acompanha ansiosamente os campeões da Horda em grandes jornadas por Kalimdor e pelos Reinos do Leste para aprender o que significa ser um herói.",h="Grunth é um jovem órfão orc enérgico que vive sob os cuidados do orfanato de Orgrimmar no Arranco.",kw={"semana das crianças","grunth","órfão orc","orgrimmar","matriarca uivadora","apito de órfão","o arranco"},ang={["faction:Horde"]="Ser o mentor de Grunth durante a Semana das Crianças lembra aos campeões da Horda o que sua facção se esforça para proteger: uma nova geração nascida em liberdade, e não na servidão demoníaca.",["race:Orc"]="Grunth personifica a juventude de Durotar, crescendo conhecendo a honra tribal e a sobrevivência em vez da escura letargia dos campos de confinamento."},sec={{t="Uma Criança Curiosa da Horda",b="Residindo no Arranco de Orgrimmar sob o olhar atento da Matriarca Uivadora, Grunth representa a próxima geração da recém-estabelecida Horda. Como muitos jovens peles-verdes criados nos ermos vermelhos e implacáveis de Durotar, ele olha para os aventureiros de armadura com admiração e um fluxo inesgotável de perguntas — perguntando-se se guerreiros de armadura são realmente aterrorizantes, por que raios na água não matam todos os peixes, e se algum dia verá alguém lutar contra um dragão de verdade."},{t="Jornadas da Semana das Crianças",b="Quando a temporada de festivais chega, os aventureiros tocam um Apito de Órfão Orc para evocar Grunth e levá-lo em uma extensa excursão pelo mundo. Sua lista de desejos abrange toda a extensão do domínio da Horda: buscar uma audiência com o Grande Chefe Caerne Casco Sangrento em Mulgore, aventurar-se na sala do trono em ruínas de Lordaeron e visitar as fronteiras acidentadas onde seu povo luta pelo seu futuro."}},faq={{q="Quem é Grunth?",a="Grunth é uma criança orc que reside no orfanato de Orgrimmar, no Arranco. Ele é cuidado pela Matriarca Uivadora e sonha em se tornar um herói lendário da Horda.",al={"pnc grunth","órfão orc","órfão de orgrimmar"}},{q="Onde Grunth pode ser encontrado?",a="Ele fica no Arranco em Orgrimmar com os outros órfãos, mas durante a Semana das Crianças, um aventureiro pode evocá-lo em qualquer lugar usando um Apito de Órfão Orc obtido com a Matriarca Uivadora.",al={"localização de grunth","onde fica grunth","encontrar grunth"}},{q="Quais lugares Grunth quer visitar?",a="Grunth anseia ver os maiores ícones da Horda. Seus pedidos incluem visitar o Grande Chefe Caerne Casco Sangrento no Penhasco do Trovão, passear pelas docas de Vila Catraca e viajar até a sala do trono em ruínas de Lordaeron.",al={"missões de grunth","o que o órfão quer","turnê de grunth"}},{q="Que tipo de personalidade Grunth tem?",a="Grunth é barulhento, curioso e intensamente imaginativo. Ele dispara constantemente charadas absurdas e perguntas infantis aos aventureiros que o guiam, como perguntar o que 'zug zug' realmente significa, se uma mosca sem asas é chamada de andorinha, e mencionando casualmente que enfiou uma pedra no nariz.",al={"falas de grunth","diálogo de grunth","o que grunth diz"}}},fx={ec5570c7={q="De que lado o Grunth está?",a="Grunth pertence inteiramente à Horda. Criado em Orgrimmar sob os cuidados da Matriarca Uivadora, ele admira os campeões da Horda e sonha em testemunhar grandes feitos, como ver um herói lutando contra um dragão feroz.",al={"grunth horda ou aliança","grunth é da horda","facção de grunth"}},["06889c57"]={q="Por que o Grunth está em Orgrimmar?",a="Grunth é um órfão orc que vive sob os cuidados do orfanato de Orgrimmar no Arrastão. Durante a Semana das Crianças, ele tem permissão para sair e explorar o mundo ao lado de um aventureiro experiente da Horda, que responde às suas perguntas ansiosas e lhe mostra o reino mais amplo.",al={"por que o grunth está aqui","por que o grunth está em orgrimmar","por que a localização de grunth"}},["0a265be0"]={q="A quem o Grunth está ligado?",a="Grunth é cuidado pela Matriarca Uivadora no orfanato em Orgrimmar. Ela cuida do jovem orc e o confia a aventureiros da Horda dispostos a orientá-lo e levá-lo em viagens por Kalimdor e além.",al={"quem cuida de grunth","ligações de grunth","grunth matriarca uivadora"}}},fp="6,260,28.483.0,24.393.0,14.169.0,26.194.0,38.226.0,42.291.0"}
P.entries["npc:gryan-stoutmantle"] = {n="Gryan Stoutmantle",s="Gryan Stoutmantle é um paladino da Silver Hand e o comandante da People's Militia, operando a partir do Morro da Sentinela em Cerro Oeste. Nascido em Cerro Oeste, ele retornou do devastado reino do norte de Lordaeron para proteger sua terra natal depois que a coroa de Ventobravo abandonou a região ao banditismo.",h="Gryan Stoutmantle é um paladino da Silver Hand e o comandante da People's Militia, operando a partir do Morro...",kw={"minas mortas","gryan","people's militia","morro da sentinela","silver hand","stoutmantle","vancleef","cerro oeste","wiley"},ang={["class:Paladin"]="Stoutmantle é um exemplo vivo do dever da Silver Hand: quando os altos conselhos da igreja e da coroa ignoraram os pobres, ele levou a proteção da Luz diretamente aos humildes fazendeiros que mais precisavam dela.",["faction:Alliance"]="A dependência de Gryan de voluntários independentes expõe as duras rachaduras no coração da Aliança, onde a inação política em Ventobravo força cidadãos leais a pegar em suas próprias armas.",["race:Human"]="Nascido em Cerro Oeste, Gryan representa a resiliência do povo rural de Ventobravo, mantendo-se firme tanto contra os salteadores regionais quanto contra o abandono burocrático por parte da capital."},sec={{t="Um Cavaleiro que Retornou ao Lar",b="Gryan Stoutmantle começou seu serviço longe dos campos tranquilos do sul de Azeroth. Viajando para o norte rumo a Lordaeron quando jovem, ele fez os votos de Cavaleiro da Silver Hand e suportou os horrores da Third War. Quando chegaram notícias de que sua província natal de Cerro Oeste estava entrando em colapso na anarquia, tomada por bandidos organizados e abandonada pela coroa, Gryan deixou as frentes do norte para trás. Ele trocou campos de batalha imperiais pela defesa de fazendeiros honestos, jurando que seu lar não sucumbiria como o norte sucumbira."},{t="A People's Militia",b="Ao retornar, Gryan encontrou Cerro Oeste praticamente indefeso. Devido ao descaso real e à paralisia política dentro da House of Nobles, Ventobravo recusou-se a enviar tropas de guarnição. Em resposta, Stoutmantle estabeleceu a People's Militia no Morro da Sentinela, reunindo fazendeiros locais, sentinelas e mercenários viajantes em um corpo de defesa voluntário. Suas forças mantêm uma linha precária contra a Irmandade Défias, gnolls Riverpaw e mecanoides hostis, incapazes até mesmo de liberar reforços quando assentamentos vizinhos como Vila Plácida suplicam por ajuda."},{t="Desmascarando o Chefão",b="Recusando-se a lutar às cegas, Stoutmantle recorreu a uma extensa rede de informações para descobrir quem estava orquestrando a ruína de Cerro Oeste. Cobrando uma antiga dívida do ladino suspeito Wiley, o Negro, nas Montanhas Cristarrubra e conferenciando com Mathias Shaw da AVIN, Gryan rompeu o véu: os bandidos eram liderados por Edwin VanCleef, o ultrajado mestre arquiteto da Stonemasons' Guild. Depois que a milícia capturou um bandido que tentava saquear uma carroça local, Gryan usou o traidor para localizar com precisão o quartel-general da Irmandade escondido sob Arroio da Lua, dentro das Minas Mortas, encarregando campeões veteranos de abater VanCleef diretamente."}},faq={{q="Quem é Gryan Stoutmantle?",a="Gryan Stoutmantle é um paladino da Silver Hand e o fundador e comandante da People's Militia, a guarnição voluntária sediada no Morro da Sentinela que defende Cerro Oeste.",al={"quem é gryan","história de stoutmantle","líder de cerro oeste"}},{q="Por que a People's Militia é necessária se Cerro Oeste pertence a Ventobravo?",a="A House of Nobles de Ventobravo recusou-se a enviar soldados da coroa ou fundos do tesouro para proteger a província periférica. Deixados à própria sorte contra saqueadores e gnolls, os camponeses locais, sob a liderança de Gryan, formaram sua própria força de defesa independente.",al={"por que a milícia","onde está o exército de ventobravo","por que ventobravo abandonou cerro oeste"}},{q="Qual é a história de Gryan com a Silver Hand?",a="Gryan viajou para Lordaeron em sua juventude para se tornar um sagrado paladino da Silver Hand. Ele serviu em campos de batalha do norte durante a Third War antes de partir para o sul para resgatar sua terra natal ameaçada.",al={"gryan é um paladino","gryan silver hand","gryan em lordaeron"}},{q="Por que Gryan se recusa a enviar ajuda para Vila Plácida?",a="Quando o Magistrado Salomão de Vila Plácida solicitou reforços contra os gnolls e orcs das Montanhas Cristarrubra, Gryan foi forçado a recusar. A People's Militia está sobrecarregada até seu limite absoluto mantendo o Morro da Sentinela; enviar mesmo um pequeno destacamento faria com que Cerro Oeste caísse nas mãos dos Défias.",al={"pedido do magistrado salomão","ajudar as montanhas cristarrubra","por que não enviar tropas para vila plácida"}},{q="Como Gryan descobriu onde os Défias estavam se escondendo?",a="Gryan recorre a Wiley, o Negro e a Mathias Shaw em busca de informações, e depois pede a aventureiros que investiguem a Irmandade. As descobertas seguintes estão descritas na seção de spoilers.",al={"encontrar as minas mortas","quem encontrou vancleef","história do traidor défias"}},{q="Quem é Wiley, o Negro para Gryan?",a="Wiley, o Negro é um contato que vive na estalagem em Vila Plácida e devia sua vida a Gryan. Embora Stoutmantle tenha pouco apreço pela natureza desagradável do ladino, ele aproveitou essa dívida de vida para obter informações cruciais sobre as operações dos Défias.",al={"wiley e gryan","dívida de wiley, o negro"}}},fx={["7558c158"]={q="De que lado o Gryan Stoutmantle está?",a="Gryan é leal à Aliança, ao Reino de Ventobravo e, acima de tudo, ao povo comum do Cerro Oeste. Enquanto a corte real de Ventobravo fechou os olhos para a situação da província, Gryan tomou as rédeas da situação ao liderar a The People's Militia. Ele permanece um cavaleiro fiel lutando para recuperar o reino para seus cidadãos legítimos.",al={"facção de gryan stoutmantle","a quem gryan serve","de qual facção é gryan"}},c0a0d15a={q="O que o Gryan Stoutmantle quer?",a="Gryan busca erradicar a The Defias Brotherhood e restaurar a paz, a lei e a ordem no Cerro Oeste. Ele quer recuperar as fazendas invadidas da província, expurgar os bandidos e ladrões que aterrorizam os colonos honestos e garantir a segurança dos fazendeiros que foram abandonados pela Coroa.",al={"objetivo de gryan stoutmantle","o que gryan quer","motivação de gryan"}},d2149791={q="Por que o Gryan Stoutmantle está no Cerro Oeste?",a="O Cerro Oeste é a terra natal de Gryan. Quando ele recebeu a notícia, durante a Terceira Guerra em Lordaeron, de que bandidos criminosos estavam invadindo suas terras natais e expulsando fazendeiros de suas propriedades, ele retornou para o sul para defender a província. Estacionado no Morro da Sentinela, ele lidera a The People's Militia do coração do território disputado.",al={"por que gryan está no cerro oeste","por que gryan veio para o cerro oeste","por que gryan está no morro da sentinela"}},["9073fb6b"]={q="A quem o Gryan Stoutmantle está ligado?",a="Gryan mantém laços com Mathias Shaw, o chefe do serviço de inteligência de Ventobravo, a AVIN, que lhe fornece reconhecimento vital sobre os Defias. Ele também está conectado a Wiley, o Negro, nas Montanhas Cristarrubra, um antigo associado cuja vida ele salvou uma vez, e coordena com defensores locais nas terras vizinhas.",al={"aliados de gryan stoutmantle","com quem gryan trabalha","conexões de gryan"}}},fp="17,298,22.525.0,20.546.0,21.617.1,25.178.0,68.259.0,45.198.0,47.290.0,52.185.1,32.245.0"}
P.entries["npc:guard-berton"] = {n="Guarda Berto",s="O Guarda Berto é um guarda municipal humano posicionado do lado de fora da Estalagem da Vila Plácida, nas Montanhas Cristarrubra. Frustrado com as demoras burocráticas do sistema legal de Ventobravo, ele busca justiça rápida contra Targorr, o Horror, um líder orc aprisionado.",h="O Guarda Berto é um guarda municipal humano posicionado do lado de fora da Estalagem da Vila Plácida, nas...",kw={"berto","guarda berto","vila plácida","cristarrubra","targorr","targorr, o horror","o cárcere","what comes around"},ang={["faction:Alliance"]="Berto representa a crescente frustração entre os assentamentos rurais da Aliança, onde os defensores locais assistem à burocracia central de Ventobravo atrasar a justiça enquanto as cidades fronteiriças lutam pela sobrevivência."},sec={{t="Um Guarda em Busca de Justiça",b="Enquanto as Montanhas Cristarrubra sucumbem sob a ameaça da invasão dos orcs Blackrock, o Guarda Berto permanece a postos do lado de fora da Estalagem da Vila Plácida. Apesar de as defesas locais estarem no limite, a atenção de Berto está voltada para um inimigo cativo: Targorr, o Horror. Targorr foi capturado e trancafiado nas profundezas do Cárcere de Ventobravo, condenado à morte por seus crimes contra o reino. No entanto, com a execução adiada indefinidamente por Ventobravo, Berto se recusa a deixar o saqueador brutal definhando em uma cela enquanto Vila Plácida sangra. Tomando as rédeas da situação, ele contrata aventureiros dispostos a contornar a lentidão real e executar o orc diretamente."}},faq={{q="Quem é o Guarda Berto?",a="O Guarda Berto é um guarda da Aliança posicionado do lado de fora da Estalagem da Vila Plácida, nas Montanhas Cristarrubra. Ele é conhecido principalmente por contratar aventureiros para fazer cumprir a justiça contra um infame prisioneiro orc.",al={"berto vila plácida","quem é berto"}},{q="Por que o Guarda Berto quer a morte de Targorr, o Horror?",a="Targorr, o Horror, foi condenado à execução por seus crimes, mas a liderança de Ventobravo suspendeu a sentença. Frustrado com essa estagnação enquanto Cristarrubra continua sob cerco, Berto planeja a eliminação de Targorr dentro d'O Cárcere.",al={"por que matar targorr","execução de targorr","história da missão what comes around"}},{q="Onde Targorr, o Horror, está detido?",a="Targorr está confinado dentro d'O Cárcere, a masmorra de segurança máxima localizada no distrito dos Canais de Ventobravo.",al={"localização de targorr","onde fica targorr"}},{q="Onde o Guarda Berto pode ser encontrado?",a="Ele fica de guarda bem em frente à entrada da Estalagem da Vila Plácida, vigiando o centro de Vila Plácida em Cristarrubra.",al={"onde fica berto","localização de berto"}}},fx={["352370f6"]={q="De que lado o Guarda Berto está?",a="O Guarda Berto é um defensor leal do Reino de Ventobravo e da Aliança. Estacionado nas Montanhas Cristarrubra, seu dever é proteger a sitiada cidade de Vila Plácida e seu povo dos perigos circundantes da natureza, incluindo os orcs rocha negra saqueadores.",al={"facção de berto","a quem o guarda berto serve","berto é da aliança"}},bd53caa6={q="A quem o Guarda Berto está ligado?",a="Berto serve entre a guarda da cidade das Montanhas Cristarrubra estacionada em Vila Plácida, ficando ao lado de seus companheiros protetores fora da estalagem local. Além de sua guarnição local, suas queixas o ligam diretamente a Targorr, o Horror, um notório prisioneiro mantido na Stormwind Stockade.",al={"conexões do guarda berto","guarda da cidade de berto","com quem berto trabalha"}}},fp="12,240,23.633.0,20.196.0,52.246.0,32.119.0,32.117.0"}
P.entries["npc:guard-howe"] = {n="Guarda Howe",s="O Guarda Howe é um guarda da cidade posicionado perto do pé sul da ponte de Vila Plácida, nas Montanhas Cristarrubra. Movido por uma vingança pessoal contra os orcs Rocha Negra que invadem o vale, ele oferece recompensas a qualquer aventureiro disposto a abater os invasores.",h="O Guarda Howe é um guarda da cidade posicionado perto do pé sul da ponte de Vila Plácida, nas Montanhas...",kw={"recompensa pelos rocha negra","orcs rocha negra","guarda howe","howe","vila plácida","cristarrubra"},ang={["faction:Alliance"]="Vila Plácida recebe pouca ajuda direta de Ventobravo, deixando guardas da linha de frente como Howe na dependência de campeões visitantes da Aliança para impedir que os orcs Rocha Negra invadam a cidade."},sec={{t="Um Rancor na Ponte",b="Posicionado logo ao sul da grande ponte de pedra sobre o Lago Plácido, o Guarda Howe vigia o coração de Vila Plácida. Como muitos na cidade assolada, ele vê o avanço dos orcs Rocha Negra como uma ameaça existencial a Cristarrubra. Nutindo um amargo desejo de vingança contra o clã, Howe recruta ativamente mercenários que passam pelo local para caçar orcs nas colinas a leste, oferecendo pagamento em troca de provas tangíveis de sua derrota."}},faq={{q="Quem é o Guarda Howe?",a="O Guarda Howe é um guarda humano posicionado logo ao sul da ponte em Vila Plácida, nas Montanhas Cristarrubra. Ele ajuda a proteger o assentamento e direciona combatentes capazes a contra-atacar os orcs Rocha Negra invasores.",al={"guarda howe","howe vila plácida","quem é howe"}},{q="Por que o Guarda Howe quer que os orcs Rocha Negra sejam mortos?",a="Howe nutre uma vingança pessoal contra o clã Rocha Negra, que avançou profundamente nas Montanhas Cristarrubra e colocou Vila Plácida sob pressão implacável. Ele busca vingança e oferece recompensas a quem diminuir as fileiras inimigas.",al={"por que recompensa pelos rocha negra","howe orcs","por que howe odeia orcs"}},{q="O Guarda Howe é parente de mais alguém na região?",a="Ele compartilha o sobrenome com Soloman Howe, o que sugere que possam ser parentes, embora ele mantenha o foco estritamente em seus deveres de proteger a cidade e combater os orcs.",al={"parentes de howe","relação com soloman howe"}}},fx={["59b92c48"]={q="De que lado o Guarda Howe está?",a="O Guarda Howe serve ao Reino de Ventobravo e apoia a guarda da cidade de Vila Plácida. Estacionado nas linhas de frente das Montanhas Cristarrubra, ele luta para defender a população humana local contra as incursões implacáveis que ameaçam suas fronteiras.",al={"facção do guarda howe","o guarda howe é da aliança","a quem o guarda howe serve"}},d5289960={q="Por que o Guarda Howe está aqui?",a="O Guarda Howe está estacionado logo ao sul da ponte de Vila Plácida para vigiar o perímetro da cidade. As Montanhas Cristarrubra estão sendo sitiadas por gnolls e orcs rocha negra invasores, tornando a ponte uma travessia vital e um ponto de estrangulamento essencial para defender de ataques repentinos.",al={"por que o guarda howe está em vila plácida","posto do guarda howe","por que a ponte do guarda howe"}}},fp="10,269,22.433.0,18.224.0,47.229.0,51.156.0"}
P.entries["npc:guard-thomas"] = {n="Guarda Tomás",s="O Guarda Tomás é um soldado dedicado do Exército de Ventobravo destacado na ponte a oeste da Madeireira Vale do Leste. Isolado na fronteira leste da Floresta de Elwynn, ele supervisiona a defesa dos colonos locais contra a fauna predatória e o avanço dos murlocs.",h="O Guarda Tomás é um soldado dedicado do Exército de Ventobravo destacado na ponte a oeste da Madeireira Vale...",kw={"vale do leste","madeireira vale do leste","floresta de elwynn","guarda tomás","guardas perdidos","murloc","exército de ventobravo","tomás"},ang={["class:Warrior"]="Para os jovens guerreiros da Aliança, Tomás representa a disciplina da linha de frente e a realidade desprovida de glamour da defesa das fronteiras regionais.",["faction:Alliance"]="O Guarda Tomás personifica o estado sobrecarregado do Exército de Ventobravo, mantendo um posto avançado vital na fronteira com suporte mínimo da coroa."},sec={{t="Na fronteira leste",b="Enquanto grande parte da atenção do reino está voltada para o interior, em direção à capital, ou a oeste, rumo a Cerro Oeste, o Guarda Tomás mantém um dos postos mais tranquilos, porém mais precários, da Floresta de Elwynn. Posicionado na ponte de pedra que cruza o rio em direção à Madeireira Vale do Leste, Tomás atua como a linha de defesa entre os trabalhadores florestais comuns e as criaturas agressivas que rondam os bosques. Com as forças armadas de Ventobravo sobrecarregadas, guardas como Tomás dependem fortemente de aventureiros que passam pelo local para manter a ordem e levar mensagens de volta ao comando central."},{t="Problemas na fronteira",b="Os limites orientais de Elwynn enfrentam pressões constantes. Ursos e rondantes agressivos espreitam a linha das árvores, ameaçando lenhadores e viajantes, enquanto tribos estranhas de murlocs estabeleceram acampamentos ao longo dos cursos d'água. Tomás monitora os movimentos desses predadores aquáticos e emite recompensas para reduzir seu número. Para piorar, patrulhas de reconhecimento ao longo do rio ocasionalmente desaparecem sem deixar vestígios, deixando Tomás na tarefa de desvendar o destino de seus companheiros guardas em meio à crescente instabilidade regional."}},faq={{q="Onde posso encontrar o Guarda Tomás?",a="O Guarda Tomás está posicionado na ponte de pedra que cruza o rio logo a oeste da Madeireira Vale do Leste, ao longo da estrada leste na Floresta de Elwynn.",al={"localização do guarda tomás","onde fica tomás","ponte do guarda tomás"}},{q="Qual é a função do Guarda Tomás na Floresta de Elwynn?",a="Ele é um oficial do Exército de Ventobravo designado para proteger a fronteira leste de Elwynn. Suas responsabilidades incluem proteger a ponte comercial, defender os trabalhadores das redondezas contra predadores selvagens e monitorar as incursões hostis de murlocs ao longo das margens do rio.",al={"o que tomás faz","função do guarda tomás","tomás vale do leste"}},{q="Por que o Guarda Tomás está pedindo ajuda com guardas desaparecidos?",a="Patrulhas de rotina enviadas às bacias dos rios não retornaram para prestar relatório. Sem reforços suficientes para deixar seu posto desprotegido, Tomás recruta aventureiros que passam pelo local para vasculhar as hidrovias e descobrir o que aconteceu com seus companheiros desaparecidos.",al={"guardas perdidos de elwynn","batedores desaparecidos guarda tomás","o que aconteceu com os guardas"}},{q="Por que os murlocs são um problema para o Guarda Tomás?",a="Tribos de murlocs têm subido cada vez mais os sistemas fluviais do leste de Elwynn. Sua presença crescente ameaça tanto as operações madeireiras locais quanto as rotas de abastecimento terrestres, levando Tomás a colocar recompensas abertas por suas barbatanas para manter as hidrovias desimpedidas.",al={"murlocs vale do leste","por que matar murlocs","recompensa de murlocs guarda tomás"}},{q="A quem o Guarda Tomás responde?",a="Tomás serve no Exército de Ventobravo, respondendo através da hierarquia militar ao comando regional em Vila d'Ouro e na capital. Conforme a situação se deteriora pelas fronteiras, seus despachos também se articulam com lideranças fronteiriças como Miguel Mantoforte, em Cerro Oeste.",al={"superior de tomás","cadeia de comando do exército de ventobravo","para quem tomás trabalha"}},{q="Para onde o Guarda Tomás envia os aventureiros quando o trabalho deles em Elwynn termina?",a="Assim que as ameaças imediatas ao redor do Vale do Leste e do rio oriental são resolvidas, Tomás fornece relatórios direcionando viajantes experientes para Cerro Oeste, a fim de ajudar Miguel Mantoforte e a combalida People's Militia.",al={"após o guarda tomás","para onde ir após vale do leste","relatório de cerro oeste"}}},fx={["2ef4fdb3"]={q="Quem é o Guarda Tomás?",a="O Guarda Tomás é um oficial do Exército de Ventobravo estacionado na fronteira leste da Floresta de Elwynn. Enquanto as forças de Ventobravo estão sobrecarregadas por todo o reino, Tomás mantém o posto perto da Madeireira Vale do Leste, protegendo viajantes e trabalhadores ao longo da ponte contra gnolls e murlocs invasores.",al={"quem é tomás","identidade do guarda tomás","quem é o guarda tomás"}},["26bccfb6"]={q="De que lado o Guarda Tomás está?",a="Tomás serve ao Reino de Ventobravo e à Aliança. Como um soldado leal do Exército de Ventobravo, ele age sob a autoridade do trono e trabalha diretamente para proteger as fronteiras do reino para seus cidadãos e trabalhadores.",al={"facção do guarda tomás","a quem o guarda tomás serve","guarda tomás aliança"}},["8313e011"]={q="O que o Guarda Tomás quer?",a="Tomás precisa de mãos capazes para proteger a borda leste de Elwynn. Entre murlocs agressivos do rio e gnolls hostis ameaçando os madeireiros da Madeireira Vale do Leste, ele quer a natureza selvagem ao redor protegida, o destino dos patrulheiros desaparecidos descoberto e informações regulares enviadas ao alto comando em Ventobravo e no Cerro Oeste.",al={"o que tomás quer","objetivos do guarda tomás","o que o guarda tomás precisa"}},c7700b23={q="Por que o Guarda Tomás está aqui?",a="Tomás está postado na ponte leste para guardar a travessia principal para a Madeireira Vale do Leste e as terras fronteiriças além. Com a Madeireira Vale do Leste sendo vital para o suprimento de madeira de Ventobravo e as bestas locais pressionando a partir dos rios e colinas, uma presença militar é necessária para manter a estrada aberta.",al={"por que o guarda tomás está na ponte","por que tomás está aqui","motivo da localização do guarda tomás"}}},fp="12,261,21.542.0,17.495.1,30.142.0,45.258.0,53.251.0,43.251.0,32.275.0,75.208.0"}
P.entries["npc:gubber-blump"] = {n="Gubber Blump",s="Gubber Blump é um pescador e instrutor anão estabelecido ao longo da costa de Auberdine, em Costa Negra. Posicionado nas areias entre as docas e o mestre de voo, ele é um amante entusiasmado da arte da pesca e de frutos do mar, principalmente carne fresca de caranguejo.",h="Gubber Blump é um pescador e instrutor anão estabelecido ao longo da costa de Auberdine, em Costa Negra.",kw={"auberdine","blump","costa negra","pescaria","graun blump","gubber","rastejador do recife","bugiganga brilhante"},ang={["profession:Cooking"]="Gubber é apaixonado pela culinária costeira, especialmente carne fresca de rastejante dos recifes, tornando-se uma alma gêmea para cozinheiros em busca de ingredientes das águas de Costa Negra.",["race:Dwarf"]="Ver um anão felizmente estabelecido em um litoral enevoado de Kalimdor em vez de Khaz Modan é uma visão incomum, embora sua conversa franca sobre parentes prove que ele não perdeu suas raízes de Altaforja."},sec={{t="O Pescador de Auberdine",b="Enquanto a maioria dos anões encontra conforto sob a rocha ou ao lado de uma forja ardente, Gubber Blump prefere o litoral enevoado de Costa Negra. Estabelecido ao longo da praia em Auberdine, entre o mestre de voo e o píer da balsa, Gubber ensina a arte da pescaria e vende equipamentos básicos de pesca para viajantes que passam por ali. Ele tem um profundo apreço culinário por carne de caranguejo, embora frequentemente dependa de aventureiros para ajudar a garantir suas capturas ao longo da costa perigosa, além de recuperar itens sentimentais de pesca da família."},{t="Laços de Família e Favores Oceânicos",b="Gubber é conhecido por compartilhar histórias sinceras sobre sua família, principalmente sobre sua prima Graun Blump, de quem ele insiste que tem tanto barba quanto um odor incomum. Viajantes que dão uma mãozinha em suas tarefas costeiras — seja trazendo pernas de rastejador ou recuperando sua vara da família — costumam receber uma atenciosa carta de agradecimento escrita à mão por Gubber, geralmente acompanhada por uma isca brilhante para incentivar seus futuros arremessos."}},faq={{q="Quem é Gubber Blump?",a="Gubber Blump é um instrutor de pescaria e vendedor anão localizado na praia de Auberdine, situado exatamente entre as docas da vila e o mestre de hipogrifos.",al={"quem é gubber blump","npc gubber blump","onde fica gubber blump"}},{q="O que Gubber Blump ensina ou vende?",a="Ele treina novatos na profissão de pescaria e estoca equipamentos básicos para futuros pescadores, incluindo Vara de Pescar padrão e bugigangas brilhantes.",al={"o que gubber vende","instrutor gubber blump","instrutor de pescaria de costa negra"}},{q="Quais tarefas Gubber Blump oferece?",a="Gubber pede que viajantes recuperem sua Vara de Pescar de família perdida e coletem carne de caranguejo de primeira na costa em missões como 'The Family and the Fishing Pole' e 'Fruit of the Sea'.",al={"missões de gubber blump","frutos do mar","vara de canoeiro, prefere pescar"}},{q="Quem é Graun Blump?",a="Graun Blump é a prima anã de Gubber. Gubber comenta com franqueza que ela ostenta uma barba notável e tem um cheiro bastante incomum.",al={"graun blump","prima de gubber blump"}}},fx={["0ab58c9b"]={q="De que lado o Gubber Blump está?",a="Gubber Blump é um anão alinhado à Aliança, estacionado pacificamente ao lado dos elfos noturnos de Auberdine. Embora ele cuide principalmente de seus próprios negócios e se concentre em seu ofício, ele recebe abertamente viajantes da Aliança para negociar, treinar e compartilhar as capturas costeiras.",al={"gubber blump é da aliança","facção de gubber blump","a quem gubber blump serve"}},["09bb4e46"]={q="O que o Gubber Blump quer?",a="Gubber é apaixonado por pesca e delícias culinárias, mantendo uma predileção particular por carne de caranguejo fresca colhida nas águas locais. Acima de tudo, ele quer desfrutar das dádivas do mar, recuperar o equipamento de pesca perdido de sua família e ensinar aos outros pescadores os pontos mais refinados do ofício.",al={"qual é o objetivo de gubber blump","o que gubber blump precisa","motivações de gubber blump"}},["77301056"]={q="Por que o Gubber Blump está em Costa Negra?",a="Gubber fez sua casa ao longo da costa de Auberdine, aninhado entre as docas e o mestre de voo. A costa enevoada oferece amplos campos de pesca e uma colheita constante de caranguejos de recife, tornando-o um posto ideal para um pescador anão que deseja pescar em paz.",al={"por que gubber blump está aqui","por que um anão está em costa negra","por que gubber está em auberdine"}}},fp="12,256,23.502.0,28.409.0,20.153.0,37.142.0,38.178.0,19.127.0"}
P.entries["npc:gunther-arcanus"] = {n="Tertuliano Arcanus",s="Tertuliano Arcanus é um necromante excepcionalmente poderoso que habita uma ilha isolada no Lago Águas Claras. Morto durante a Terceira Guerra e erguido na morte-vida, ele conseguiu quebrar o controle mental do Lich Rei inteiramente por conta própria. Acreditando por muito tempo que era o único morto-vivo com livre-arbítrio, ele defendeu seu refúgio contra todos os invasores até ser descoberto pelos Renegados.",h="Tertuliano Arcanus é um necromante excepcionalmente poderoso que habita uma ilha isolada no Lago Águas Claras.",kw={"arcanus","boanerges","águas claras","dalaran","tertuliano","stalactus","kirin tor","lich","necromante","thule","tirisfal"},ang={["class:Mage"]="Treinado em Dalaran, Tertuliano representa os magos do Kirin Tor que praticavam clandestinamente feitiços necromânticos proibidos antes de o Flagelo invadir Lordaeron.",["class:Warlock"]="O domínio imponente de Tertuliano sobre as artes sombrias e a reanimação demonstra até que ponto os estudos proibidos podiam florescer longe dos olhos vigilantes da liderança de Dalaran.",["race:Undead"]="A autolibertação de Tertuliano o torna uma anomalia entre os Renegados, provando que o treinamento arcano intenso e uma vontade de ferro por si sós podiam, por vezes, quebrar o domínio mental do Lich Rei."},sec={{t="Um Estudante de Dalaran",b="Antes da queda de Lordaeron, Tertuliano era um aprendiz promissor entre o Kirin Tor em Dalaran. Ao lado dos amigos próximos Boanerges Stalactus e Thule Corvinalle, ele estudava as artes arcanas, aprofundando-se secretamente na necromancia, a despeito das proibições severas do Kirin Tor contra a magia sombria. Para celebrar sua irmandade, o trio certa vez uniu suas varinhas de aprendiz em uma única relíquia."},{t="Quebrando os Grilhões",b="Quando o Flagelo varreu o norte durante a Terceira Guerra, Tertuliano pereceu para a Peste da Morte-vida e foi reanimado para a servidão. Ao contrário da maioria, que precisou do enfraquecimento do poder do Lich Rei ou da intervenção de Lady Sylvana para quebrar suas correntes, o domínio arcano bruto e a pura força de vontade de Tertuliano permitiram que ele se libertasse da dominação mental do Lich Rei inteiramente sozinho. Convencido de que todos os outros cadáveres ambulantes continuavam sendo servos irracionais do Flagelo, ele se retirou para uma ilha nas Clareiras de Tirisfal, cercando-se de guardiões cambaleantes e cortando todo contato tanto com os vivos quanto com os mortos."},{t="O Lich pródigo",b="Buscando aliados poderosos contra o Flagelo, os Renegados enviaram emissários para resgatar o livro de feitiços do misterioso necromante. Ao examinar o tomo arcano na Cidade Baixa, Boanerges Stalactus reconheceu a caligrafia singular de seu antigo colega. Ao encantar o grimório devolvido e exigir a destruição de comandantes locais do Flagelo, Tertuliano finalmente percebeu que não estava sozinho em sua liberdade. Convencido de que a facção de Sylvana representa uma verdadeira rebelião contra o Flagelo, ele forjou um pacto com seu antigo colega para ajudar os Renegados."}},faq={{q="Quem é Tertuliano Arcanus?",a="Ele é um antigo mago do Kirin Tor de Dalaran que pereceu durante a Terceira Guerra. Erguido na morte-vida, libertou-se do domínio do Lich Rei por conta própria e refugiou-se em uma ilha no Lago Águas Claras, nas Clareiras de Tirisfal.",al={"quem é tertuliano","história de tertuliano","história de tertuliano arcanus"}},{q="Por que Tertuliano se parece com um Renegado comum em vez de um lich esquelético?",a="Enquanto os liches tradicionais transferem seus espíritos para filactérias e geram formas esqueléticas flutuantes e monstruosas, Tertuliano alcançou seu status necromântico de lich sem abandonar seu cadáver reanimado original, preservando sua aparência física mortal.",al={"por que tertuliano parece humano","tertuliano não é esqueleto","por que tertuliano é um lich"}},{q="Por que Tertuliano vivia sozinho em uma ilha?",a="Após quebrar o controle mental do Lich Rei, Tertuliano acreditava ser o único morto-vivo existente com livre-arbítrio. Presumindo que todos os outros mortos-vivos ainda eram escravos irracionais do Flagelo, ele se isolou e ordenou que seus lacaios abatessem qualquer um que se aproximasse.",al={"por que tertuliano está sozinho","isolamento da ilha de tertuliano","por que tertuliano se esconde"}},{q="Como Tertuliano conhece Boanerges Stalactus?",a="Eles foram colegas de classe e amigos próximos em Dalaran, estudando sob o Kirin Tor, juntamente com um terceiro mago chamado Thule Corvinalle. Os três amigos chegaram a entrelaçar suas varinhas de aprendiz como símbolo de seu vínculo.",al={"boanerges e tertuliano","como tertuliano conhece boanerges","história de boanerges stalactus"}},{q="Tertuliano se junta aos Renegados?",a="Sim. Assim que aventureiros devolvem seu livro de feitiços encantado e executam a agente local do Flagelo, Lillith Nefara, para provar sua independência do Lich Rei, Tertuliano jura lealdade a Boanerges e à causa dos Renegados.",al={"tertuliano entra na horda","facção de tertuliano","tertuliano é um renegado"}},{q="Quem é Lillith Nefara?",a="Lillith Nefara é uma agente do Flagelo posicionada nas Clareiras de Tirisfal. Tertuliano exige a morte dela como prova de que o aventureiro realmente serve a um inimigo do Lich Rei, e não ao próprio Flagelo.",al={"lillith nefara","nefara","alvo de tertuliano"}}},fx={["3744b38d"]={q="O que o Tertuliano Arcanus quer?",a="Acima de tudo, Tertuliano valoriza sua independência do Lich Rei. Tendo se libertado através de pura força de vontade, ele passou anos isolado, protegendo-se contra o que presumia serem escravos do Flagelo. Ele deseja a solidão longe do Flagelo e busca provas antes de confiar em qualquer um que afirme compartilhar de sua liberdade, querendo a garantia de que você realmente se opõe ao domínio do Lich Rei.",al={"o que tertuliano quer","objetivo de tertuliano arcanus","motivação de tertuliano arcanus"}},["2466094b"]={q="Por que Tertuliano Arcanus é famoso ou temido?",a="Mesmo como um mago mortal de Dalaran, Tertuliano dominou a arte proibida da necromancia. Na morte-viva, ele alcançou o raro status de um lich enquanto mantinha sua forma mortal original. O mais aterrorizante de tudo é que ele quebrou o controle psíquico do Lich Rei completamente por conta própria, comandando lacaios mortos-vivos sob sua própria vontade absoluta.",al={"tertuliano arcanus é poderoso","por que tertuliano arcanus é temido","reputação de tertuliano arcanus"}}},fp="15,371,20.392.0,21.596.0,17.549.1,23.229.0,73.258.0,42.272.0,38.213.0,31.216.1,22.198.1"}
P.entries["npc:gurda-ragescar"] = {n="Gurda Marcafúria",s="Gurda Marcafúria era uma orquisa posicionada em um pequeno entreposto da Horda a sudoeste do Posto Machadada em Vale Gris. Ao lado de Feran Strongwind, ela tombou defendendo o acampamento contra os perigos locais na floresta sombria.",h="Gurda Marcafúria era uma orquisa posicionada em um pequeno entreposto da Horda a sudoeste do Posto Machadada...",kw={"vale gris","feran strongwind","gurda","orc","marcafúria","posto machadada","as páginas perdidas"},ang={["faction:Horde"]="O acampamento destruído serve como um lembrete sombrio do alto preço que a Horda paga para garantir uma posição nas florestas sagradas de Vale Gris."},sec={{t="Um Entreposto Chacinado",b="Ficando logo a sudoeste das muralhas fortificadas do Posto Machadada, Gurda Marcafúria mantinha um modesto acampamento da Horda sob a densa copa de Vale Gris. Em pleno território disputado por defensores elfos noturnos e feras selvagens, manter posições tão isoladas é uma tarefa perigosa. Gurda, junto com Feran Strongwind e seu destacamento de guardas, acabou sendo subjugada e morta em seu posto, restando apenas os vestígios de sua resistência final para aliados que passam pelo local encontrarem."},{t="Os Batedores Caídos",b="Viajantes que andam perto da trilha podem se deparar com a cena trágica da derrota de Gurda. Mesmo na morte, os pertences e tarefas de seu acampamento oferecem pistas sobre os esforços da Horda pela floresta, incluindo documentos e ordens perdidos que foram interrompidos pela emboscada."}},faq={{q="Quem é Gurda Marcafúria?",a="Gurda Marcafúria é uma batedora orquisa e concedente de missões situada em um pequeno acampamento logo a sudoeste do Posto Machadada em Vale Gris, que teve um fim violento ao lado de seus companheiros de posto.",al={"quem é gurda","história de gurda marcafúria"}},{q="Onde Gurda Marcafúria pode ser encontrada?",a="O corpo dela jaz em um acampamento devastado a sudoeste do Posto Machadada, fora da estrada que corta a região central de Vale Gris.",al={"localização de gurda","onde fica gurda marcafúria"}},{q="Quem foi morto ao lado dela?",a="Ela pereceu ao lado de Feran Strongwind e da comitiva de guardas durante um ataque ao pequeno acampamento deles.",al={"quem morreu com gurda","feran strongwind"}},{q="Qual missão envolve Gurda Marcafúria?",a="Gurda está ligada à missão As páginas perdidas, que envolve a recuperação de documentos dispersos pelas terras selvagens de Vale Gris.",al={"missões de gurda","as páginas perdidas"}}},fx={["28561f13"]={q="A qual facção pertence Gurda Marcafúria?",a="Gurda Marcafúria era leal à Horda. Baseada em um pequeno posto avançado logo a sudoeste do Posto Machadada, ela e seus companheiros representavam a presença fortificada da Horda nas profundezas das fronteiras disputadas de Vale Gris.",al={"facção de gurda marcafúria","gurda é da horda ou da aliança","por quem gurda luta"}},e9ae8f07={q="Por que Gurda Marcafúria estava baseada a sudoeste do Posto Machadada?",a="Gurda Marcafúria mantinha um acampamento avançado da Horda a sudoeste do Posto Machadada ao lado de Feran Strongwind e um contingente de guardas. Localizado ao longo das polêmicas trilhas na floresta, seu posto servia para apoiar as operações da Horda e recuperar ativos perdidos nas florestas hostis de Vale Gris.",al={"por que gurda marcafúria está aqui","objetivo do acampamento de gurda","por que gurda estava em vale gris"}}},fp="14,208,15.473.0,17.266.0,22.179.0,34.115.0,29.108.0,35.117.0"}
P.entries["npc:gwennyth-bly-leggonde"] = {n="Gwennyth Bly'Leggonde",s="Gwennyth Bly'Leggonde é uma elfa noturna que reside no porto costeiro de Auberdine. Posicionada ao longo da costa enevoada de Costa Negra, ela observa as marés e orienta os viajantes a investigar os estranhos restos trazidos pelas ondas. Suas preocupações se concentram nas misteriosas criaturas marinhas e tartarugas gigantescas cujas carcaças começaram a se acumular pelas praias do norte.",h="Gwennyth Bly'Leggonde é uma elfa noturna que reside no porto costeiro de Auberdine.",kw={"auberdine","criatura marinha encalhada","tartaruga marinha encalhada","blyleggonde","costa negra","gwennyth","kaldorei","veiled sea","deixa a água me levar"},ang={["class:Druid"]="Druidas empenhados em preservar a harmonia natural de Kalimdor acharão os relatos de Gwennyth sobre a vida marinha encalhada um indicador alarmante de perturbação no ecossistema costeiro.",["faction:Alliance"]="Auberdine serve como o principal porto costeiro da Aliança no norte de Kalimdor; manter suas hidrovias e praias a salvo de ameaças ocultas é vital para todas as raças aliadas que viajam por ali.",["race:NightElf"]="Para os kaldorei, a morte não natural de grandes bestas marinhas nas águas de Costa Negra é um sinal preocupante de desequilíbrio em suas terras ancestrais, tornando a vigília litorânea de Gwennyth especialmente urgente."},sec={{t="Vigia das Areias Movediças",b="Gwennyth Bly'Leggonde vive em Auberdine, o agitado refúgio litorâneo de Costa Negra. Enquanto muitos na cidade se preocupam com a floresta ou com a navegação pelo Veiled Sea, Gwennyth mantém seu olhar fixo na linha costeira. As marés tornaram-se sombrias recentemente, depositando os restos de vida marinha colossal sobre a arrebentação. Para entender o que está acontecendo nas águas próximas à costa, ela conta com aventureiros dispostos a vasculhar as areias, recuperar amostras de esqueletos e trazer respostas."},{t="Os Gigantes Encalhados",b="As praias ao norte e ao sul de Auberdine viram um afluxo alarmante de criaturas marinhas e tartarugas-marinhas ancestrais encalhadas. Em vez de deixar suas mortes passarem despercebidas, Gwennyth incumbe viajantes de inspecionar esses titãs caídos. Ao estudar os ossos e descobrir o que levou essas feras à costa ou ceifou suas vidas, ela espera desvendar os perigos ocultos que espreitam na costa norte de Kalimdor."}},faq={{q="Quem é Gwennyth Bly'Leggonde?",a="Ela é uma elfa noturna habitante de Auberdine em Costa Negra que estuda os recentes distúrbios ecológicos ao longo da costa. Ela recruta viajantes para vistoriar a praia e investigar estranhos despojos trazidos pelo mar.",al={"quem é gwennyth","gwennyth auberdine","história de gwennyth"}},{q="Onde posso encontrar Gwennyth Bly'Leggonde?",a="Ela pode ser encontrada no povoado costeiro de Auberdine, situada perto da praia e das docas ao longo da costa envolta em névoa de Costa Negra.",al={"onde fica gwennyth","localização de gwennyth","encontrar gwennyth"}},{q="Por que ela se interessa por criaturas encalhadas?",a="As mortes e encalhes repentinos de tartarugas-marinhas gigantescas e misteriosos leviatãs marinhos indicam um desequilíbrio ou um predador invisível nas águas de Costa Negra. Gwennyth busca entender a causa examinando os restos recuperados ao longo da costa.",al={"por que tartarugas encalhadas","por que ela quer ossos","missão deixa a água me levar"}},{q="Quais missões Gwennyth oferece?",a="Ela envia aventureiros em 'Deixa a água me levar' e serve como o ponto de entrega para várias descobertas relacionadas a criaturas marinhas e tartarugas-marinhas encalhadas encontradas ao longo da costa de Costa Negra.",al={"missões de gwennyth","o que ela dá"}},{q="Ela faz parte do Círculo Cenariano ou das Sentinelas?",a="Nenhum dos dois. Ela é uma Sacerdotisa da Lua a serviço das Irmãs de Elune em Auberdine, em vez de uma druidesa cenariana ou comandante das Sentinelas, mas compartilha a profunda preocupação de seu povo com a saúde e o equilíbrio do ambiente natural de Costa Negra.",al={"facção de gwennyth","gwennyth é druida"}},{q="O que significa o nome dela?",a="Embora se encaixe no estilo rítmico de nomenclatura dos kaldorei, seu incomum sobrenome 'Bly'Leggonde' é um anagrama de 'Leggy Blonde', um toque bem-humorado dos criadores do mundo.",al={"significado bly leggonde","easter egg nome gwennyth"}}},fx={["9c9d3ff5"]={q="Por que Gwennyth Bly'Leggonde está em Costa Negra?",a="Gwennyth faz do porto costeiro de Auberdine seu lar, vigiando as praias cobertas de névoa de Costa Negra. Incomodada pela praga antinatural que chega à costa, ela monitora a linha costeira em busca de vida marinha encalhada e recruta viajantes de passagem para investigar criaturas marinhas e tartarugas que deram à costa sofrendo com a estranha corrupção que aflige as águas.",al={"por que gwennyth está aqui","por que gwennyth bly'leggonde está em auberdine","por que gwennyth está em costa negra"}}},fp="21,348,29.489.0,19.409.0,29.212.0,39.134.0,43.248.0,32.196.0,52.234.0,24.167.0"}
P.entries["npc:hagar-lightninghoof"] = {n="Hagar Lightninghoof",s="Hagar Lightninghoof é um batedor tauren posicionado no alto da Aldeia Vento Livre, em Mil Agulhas. Movido por rumores de uma ninhada estranha escondida nas profundezas do cânion, ele investiga relatos de um Ovo Alienígena guardado ferozmente por serpentes aladas locais.",h="Hagar Lightninghoof é um batedor tauren posicionado no alto da Aldeia Vento Livre, em Mil Agulhas.",kw={"ovo alienígena","arikara","aldeia vento livre","hagar","lightninghoof","motega firemane","mil agulhas","serpente alada"},ang={["faction:Horde"]="Posicionado bem acima do chão do cânion na Aldeia Vento Livre, Hagar conta com guerreiros capazes da Horda para desbravar covis perigosos que os batedores comuns não conseguem invadir em segurança.",["race:Tauren"]="Para viajantes taurens, ajudar Hagar leva à emocionante percepção de que antigas lendas de Arikara, a manifestação alada da vingança, são uma realidade viva nos cânions abaixo."},sec={{t="A Ninhada Estranha",b="Enquanto estava posicionado entre os penhascos imponentes da Aldeia Vento Livre, Hagar Lightninghoof ouviu rumores sobre um ovo não natural aninhado nas profundezas de uma caverna abaixo. As serpentes aladas locais guardavam o ninho com uma ferocidade incomum, mantendo batedores curiosos afastados. Em busca de um aventureiro ousado o suficiente para desafiar o covil das serpentes, Hagar espera estudar o espécime em primeira mão e discernir que tipo de fera poderia justificar tais instintos defensivos dos predadores naturais do cânion."},{t="Um Mito Chocado",b="Quando um aventureiro finalmente recupera o ovo e o traz para a Aldeia Vento Livre, ele choca bem na frente de Hagar, revelando uma jovem serpente alada semelhante à lendária Arikara — um espírito reverenciado conhecido no folclore dos taurens como a personificação da vingança. Percebendo o grave significado cultural e espiritual do retorno da criatura, Hagar não perde tempo e envia o viajante para consultar o ancião Motega Firemane."}},faq={{q="Quem é Hagar Lightninghoof?",a="Hagar Lightninghoof é um concessor de missões tauren que reside na Aldeia Vento Livre, em Mil Agulhas. Ele investiga a fauna anômala nos cânions, particularmente um ovo incomum de serpente alada relatado nas profundezas de uma caverna próxima.",al={"quem é hagar","função de hagar lightninghoof","história de hagar"}},{q="Onde Hagar Lightninghoof pode ser encontrado?",a="Ele está localizado no topo da Aldeia Vento Livre, o posto avançado central da Horda situado sobre as imensas agulhas de rocha no centro de Mil Agulhas.",al={"onde fica hagar","localização de hagar lightninghoof","aldeia vento livre hagar"}},{q="O que é o 'Ovo Alienígena' que Hagar está procurando?",a="O Ovo Alienígena é um ovo incomum guardado por serpentes aladas em um covil subterrâneo. Hagar pede aos aventureiros que o recuperem para que ele possa investigar sua natureza.",al={"ovo alienígena","o que é o ovo","ovo de serpente alada"}},{q="Com quem Hagar se consulta sobre o ovo?",a="Hagar envia o aventureiro para falar com Motega Firemane, um ancião na Aldeia Vento Livre que possui uma sabedoria mais profunda sobre as tradições dos taurens.",al={"para quem entrego serpent wild","missão seguinte de hagar","para onde ir depois de hagar"}}},fx={d173f224={q="De que lado está Hagar Lightninghoof?",a="Hagar Lightninghoof é leal à Horda e aos seus companheiros tauren. Baseado no topo das torres imponentes da Aldeia Vento Livre, ele confia suas tarefas apenas aos campeões da Horda que se mostram capazes de enfrentar os desfiladeiros perigosos abaixo.",al={"facção de hagar lightninghoof","hagar é da horda"}},c809f2c7={q="Por que Hagar Lightninghoof está aqui na Aldeia Vento Livre?",a="Hagar viajou para Mil Agulhas após ouvir rumores de um ovo alienígena peculiar avistado nos ninhos de serpentes aladas. Intrigado com a descoberta estranha, ele montou seu acampamento na Aldeia Vento Livre para encontrar alguém corajoso o suficiente para recuperá-lo passando pelos guardas serpentes.",al={"por que hagar está aqui","por que hagar veio para mil agulhas"}},a74332ba={q="A quem Hagar Lightninghoof está ligado?",a="Hagar trabalha ao lado dos defensores tauren da Aldeia Vento Livre e consulta Motega Firemane de perto. Quando suas investigações revelam assuntos enraizados em antigas lendas tauren e presságios sagrados, é a Motega que ele recorre para obter orientação.",al={"laços de hagar","com quem hagar trabalha"}}},fp="19,239,18.474.0,14.425.1,27.220.0,39.126.0,45.151.1,37.140.1"}
P.entries["npc:halaan-hawk-eye"] = {n="Halaan Hawk-Eye",s="Halaan Hawk-Eye é um vigia Skyborne posicionado no topo da torre de vigia de Aldeia Thendal, na Ilha de Zefras. Sem sensibilidade mágica nem a visão celeste mística de seus pares, ele depende de uma visão aguçada e comum para monitorar os arredores da ilha. De seu posto elevado, ele vigia os pilares de ancoragem distantes e alerta os visitantes sobre a instabilidade arcana vacilante deles.",h="Halaan Hawk-Eye é um vigia Skyborne posicionado no topo da torre de vigia de Aldeia Thendal, na Ilha de...",kw={"pilar de ancoragem","halaan","hawk-eye","skyborne","visão celeste","aldeia thendal","ilha de zefras"},ang={["race:Skyborne"]="Halaan representa aqueles entre os Skyborne que não possuem afinidade natural com a manipulação de linhas de força ou com a visão celeste, servindo à comunidade por meio de vigilância constante e dever marcial."},sec={{t="Um Vigia Sem Magia",b="Empoleirado bem acima de Aldeia Thendal, Halaan Hawk-Eye serve ao seu povo sem as dádivas comuns a muitos Skyborne. Ele não consegue canalizar o poder arcano que flui pelas linhas de força sob a Ilha de Zefras, tampouco enxergar entre mundos por meio da visão celeste mística. Em vez disso, Halaan depende inteiramente de seus sentidos naturais aguçados. De seu ponto de observação na torre de vigia, ele perscruta o horizonte para monitorar os pilares de ancoragem da ilha, chamando a atenção para suas energias arcanas cada vez mais voláteis e instáveis."}},faq={{q="Quem é Halaan Hawk-Eye?",a="Halaan Hawk-Eye é um sentinela Skyborne posicionado no alto da torre de vigia com vista para Aldeia Thendal, na Ilha de Zefras. Ele observa as terras ao redor e alerta aventureiros sobre a magia errática que afeta os pilares de ancoragem da ilha.",al={"halaan hawkeye","quem é halaan","pnj da torre de vigia de thendal"}},{q="O que torna Halaan diferente de outros Skyborne?",a="Ao contrário de muitos entre seu povo, Halaan não possui a visão celeste mística que perfura o véu entre mundos nem a habilidade inata de manipular as linhas de força subterrâneas da Ilha de Zefras. Em vez disso, ele depende de sua visão física aguçada e de sua capacidade natural de observação.",al={"habilidades de halaan","halaan pode usar magia","visão celeste de halaan"}},{q="Por que Halaan está preocupado com os pilares de ancoragem?",a="Halaan vigia os pilares de ancoragem distantes e notou que a emanação mágica deles se tornou errática e inconsistente, representando um risco desconhecido para a estabilidade da Ilha de Zefras.",al={"o que há de errado com os pilares","problema das ancoras de zephras"}},{q="Onde posso encontrar Halaan Hawk-Eye?",a="Ele pode ser encontrado no topo da torre de vigia de madeira em Aldeia Thendal, na Ilha de Zefras, observando o horizonte.",al={"onde fica halaan","localização de halaan"}}},fx={d6a0f6c4={q="De que lado está Halaan Hawk-Eye?",a="Halaan é um dos Skyborne, permanecendo com seus parentes na Ilha de Zefras. Sem a feitiçaria inata das linhas ley e a visão aérea de outro mundo de seus pares, ele ainda serve fielmente seu povo vigiando a Aldeia Thendal e alertando os viajantes sobre a instabilidade crescente que ameaça sua terra natal.",al={"facção de halaan","lado de halaan hawk-eye","a quem halaan serve"}},e8313a77={q="Por que Halaan Hawk-Eye está baseada na torre de vigia?",a="Halaan vigia do alto da torre da Aldeia Thendal porque ele não pode utilizar as linhas ley locais ou usar a visão aérea mágica como outros Skyborne. Em vez disso, ele usa sua visão natural aguçada para pesquisar a Ilha de Zefras, monitorando os pilones de ancoragem distantes à medida que sua estabilidade mágica começa a falhar.",al={"por que halaan hawk-eye está aqui","por que halaan está na torre de vigia","motivo da localização de halaan"}}},fp="15,358,24.509.0,23.227.0,48.260.0,46.185.0,33.117.0"}
P.entries["npc:hamhock"] = {n="Ramoque",s="Ramoque é um enorme ogro de duas cabeças confinado nas profundezas de Stormwind Stockade. Trancafiado sob a capital ao lado de insurgentes e degoladores endurecidos da Irmandade Défias, ele desponta como um detento particularmente brutal e inesperado em meio à rebelião prisional.",h="Ramoque é um enorme ogro de duas cabeças confinado nas profundezas de Stormwind Stockade.",kw={"floresta do crepúsculo","ramoque","ogro","prisão","punho rachado","cárcere","ventobravo","de duas cabeças"},ang={["class:Warrior"]="Subjugar Ramoque exige enfrentar sua força colossal e brutal frente a frente dentro dos confins apertados dos corredores da prisão.",["faction:Alliance"]="Encontrar um ogro de duas cabeças solto diretamente sob as ruas da capital ressalta o quão catastroficamente os guardas da cidade perderam o controle de O Cárcere."},sec={{t="Um Bruto Atrás das Grades",b="A Stormwind Stockade foi construída para deter ladrões de pequenos furtos, assassinos e dissidentes políticos, tornando um imponente ogro de duas cabeças uma visão impressionante entre as celas. Quando os prisioneiros se rebelaram e assumiram o controle da instalação, Ramoque permaneceu entrincheirado no caos, esmagando qualquer um tolo o bastante para invadir seu bloco de celas."},{t="Origens Obscuras",b="Nenhum registro explica como Ramoque foi capturado ou por que um ogro de duas cabeças foi trancafiado entre os ladrões e dissidentes de Ventobravo. Seja o que for que o tenha levado a O Cárcere, ele agora é um de seus detentos mais perigosos."}},faq={{q="Quem é Ramoque?",a="Ramoque é um prisioneiro ogro de duas cabeças de elite mantido dentro de Stormwind Stockade. Em meio à revolta liderada pelos condenados da Irmandade Défias, ele atua como um obstáculo perigoso no fundo dos corredores da prisão.",al={"ramoque","quem é o ogro no cárcere","chefe ogro cárcere"}},{q="Como um ogro foi parar em Stormwind Stockade?",a="Nenhum registro explica como ele foi capturado ou trazido para Ventobravo.",al={"por que ramoque está preso","como ramoque foi capturado","por que há um ogro no cárcere"}},{q="Ramoque é aliado dos rebeldes da Irmandade Défias?",a="Embora toda a instalação tenha entrado em rebelião sob a liderança dos líderes da Irmandade Défias, não está claro se Ramoque realmente se coordena com eles ou se simplesmente se deleita com o caos desenfreado das celas arrombadas.",al={"ramoque é défias","ramoque irmandade défias","ramoque trabalha para bazil"}},{q="Ramoque tem algum parentesco com os ogros da Floresta do Crepúsculo?",a="Nada o liga a eles. Os ogros Splinter Fist da Gruta de Vul'Gol na Floresta do Crepúsculo são o clã de ogros mais próximo de Ventobravo, mas nenhum registro diz de onde Ramoque veio.",al={"ramoque é punho rachado","ramoque vul'gol","ogros de vul'gol cárcere"}},{q="Ramoque está ligado a alguma recompensa ou missão específica?",a="Nenhuma recompensa oficial ou mandado da cidade é oferecido especificamente pela cabeça de Ramoque. Ele é uma ameaça incidental que os aventureiros encontram ao limpar a fortaleza rebelada.",al={"missão de ramoque","existe uma missão para ramoque","recompensa de ramoque"}},{q="Por que os ogros de duas cabeças são significativos?",a="Ogros de duas cabeças possuem personalidades distintas entre suas cabeças e costumam ser mais astutos ou magicais do que seus parentes de uma cabeça só, tornando Ramoque excepcionalmente perigoso para guardas prisionais comuns.",al={"história do ogro de duas cabeças","por que duas cabeças"}}},fp="7,255,19.324.0,13.209.0,15.192.0,49.63.0,42.197.0,44.166.0,48.179.0,37.209.0"}
P.entries["npc:hana-zua"] = {n="Hana'zua",s="Hana'zua é um batedor troll Lançanegra alocado no Vale das Provações que foi vítima das feras venenosas que rondam as cristas do desfiladeiro. Atingido e ferido pelo escorpídeo monstruoso Sarkoth, ele jaz à espera de ajuda de jovens iniciados da Horda que buscam provar seu valor.",h="Hana'zua é um batedor troll Lançanegra alocado no Vale das Provações que foi vítima das feras venenosas que...",kw={"lanca negra","durotar","hana'zua","hanazua","sarkoth","escorpideo","vale das provações"},ang={["faction:Horde"]="A sobrevivência e a vingança de Hana'zua servem como um dos primeiros testes de lealdade e prontidão para o combate para os aspirantes a campeões da Horda.",["race:Troll"]="Para os iniciados Lança Negra que estão apenas começando sua jornada em Durotar, encontrar um companheiro ferido ressalta a natureza letal da fauna local e a necessidade de proteger seus novos aliados."},sec={{t="Um Batedor Derrubado pelo Veneno",b="Enquanto atravessava as alturas áridas com vista para o Vale das Provações, Hana'zua encontrou Sarkoth, um escorpídeo excepcionalmente feroz e venenoso que espreita os penhascos. Sobrecarregado e ferroado pela fera, o troll mal sobreviveu ao confronto. Incapaz de se mover ou retornar ao acampamento por conta própria, ele definha em meio à poeira, contando com recrutas que passam para dar um fim à criatura e levar notícias de sua situação de volta ao Covil."}},faq={{q="Quem é Hana'zua?",a="Hana'zua é um troll Lançanegra encontrado ferido no Vale das Provações, em Durotar. Ele foi emboscado e envenenado enquanto rastreava feras nas cristas.",al={"hanazua","quem e hanazua","troll ferido vale das provacoes"}},{q="O que aconteceu com Hana'zua?",a="Ele foi atacado por Sarkoth, um escorpídeo grande e mortal que espreita nos rochedos acima dos campos de treinamento. Seu veneno potente o deixou incapacitado e sem conseguir retornar à segurança.",al={"por que hanazua esta ferido","quem envenenou hanazua","ferimento de hanazua"}},{q="O que ele pede para os viajantes fazerem?",a="Hana'zua pede a aventureiros capazes que vinguem seus ferimentos derrotando Sarkoth, coletando a garra da fera como prova e levando notícias sobre sua condição de volta aos instrutores em O Covil.",al={"missao de hanazua","o que hanazua quer"}}},fx={eb2d80d7={q="De que lado está Hana'zua?",a="Hana'zua é leal à Horda e aos seus companheiros Trolls Lançanegra. Como outros jovens orcs e trolls que passam pelo Vale das Provações, ele se aventurou nos Proving Grounds para demonstrar sua força e prontidão para servir à nova nação de Thrall.",al={"facção de hana'zua","a quem hana'zua serve","hana'zua é da horda"}}},fp="8,277,23.422.0,16.145.0,26.178.0,33.182.0"}
P.entries["npc:hands-springsprocket"] = {n="Mãos Rodamola",s="Mãos Rodamola é um gnomo trabalhador posicionado na entrada do Caminho de Cristálgida, em Dun Morogh. Ele coordena carregamentos entre os campos de treinamento isolados do Vale Cristálgida e a cidade de Kharanos, embora recentes incursões de troggs tenham prejudicado gravemente seus esforços.",h="Mãos Rodamola é um gnomo trabalhador posicionado na entrada do Caminho de Cristálgida, em Dun Morogh.",kw={"caminho de cristálgida","vale cristálgida","dun morogh","mãos rodamola","kharanos","rodamola","suprimentos para tannok"},ang={["faction:Alliance"]="Mãos mantém ativas linhas vitais de suprimento interno entre os recrutas militares anões no Vale Cristálgida e os povoados no interior de Dun Morogh.",["race:Gnome"]="Para os refugiados gnomos deslocados de Gnomeregan, Mãos representa a determinação silenciosa dos gnomos em se integrar ao comércio local e à logística de Dun Morogh ao lado de seus aliados anões."},sec={{t="Um gargalo no caminho",b="Posicionado na entrada do Caminho de Cristálgida, Mãos Rodamola vê suas remessas regulares de suprimentos completamente interrompidas. Ele costuma entregar provisões à Destilaria Cervaforte e à estalagem de Kharanos, mas troggs Queixorrente hostis invadiram o túnel subterrâneo que sai do vale. Com o comércio e o trânsito a pé bloqueados pelas feras, Mãos é forçado a contar com viajantes capazes para transportar caixotes essenciais pelo perigoso corredor montanhoso."}},faq={{q="Quem é Mãos Rodamola?",a="Ele é um gnomo leal à Aliança posicionado no Vale Cristálgida, logo na entrada do Caminho de Cristálgida, responsável por transportar suprimentos para as áreas mais baixas de Dun Morogh.",al={"quem é mãos rodamola","história de mãos rodamola","quem é este gnomo"}},{q="Por que ele precisa de ajuda para transportar mantimentos?",a="O caminho que liga o Vale Cristálgida ao restante de Dun Morogh foi infestado por perversos troggs Queixorrente, tornando o transporte rotineiro perigoso demais sem escoltas armadas ou aventureiros capazes.",al={"por que mãos precisa de ajuda","suprimentos do caminho de cristálgida","por que os mantimentos estão parados"}},{q="Para onde vão os suprimentos dele?",a="Ele organiza carregamentos regulares para Kharanos, incluindo mercadorias destinadas a Tannok Marrãogélido e aos estalajadeiros locais que dependem de provisões constantes vindas do outro lado dos picos nevados.",al={"para onde vão os mantimentos","rota de suprimentos de mãos","quem recebe o caixote"}}},fx={d7333ab8={q="De que lado está Mãos Rodamola?",a="Mãos é um membro leal da Aliança e amigo do povo anão de Dun Morogh. Como muitos gnomos deslocados pela tragédia em Gnomeregan, ele trabalha em estreita colaboração com seus aliados de Altaforja, cuidando da logística e entregas para apoiar comunidades locais como Kharanos.",al={"facção de mãos rodamola","mãos rodamola é da aliança"}},["8576a218"]={q="O que Mãos Rodamola quer?",a="Mãos quer que suas entregas sejam transportadas com segurança através do Caminho de Cristálgida para Tannok Marrãogélido na Destilaria Cervaforte em Kharanos. O recente aumento de troggs Queixorochosos hostis por todo o túnel paralisou completamente suas remessas, deixando-o desesperado por um aventureiro disposto a carregar o caixote através do perigo.",al={"o que mãos quer","objetivo de mãos rodamola"}},d21580a2={q="A quem Mãos Rodamola está ligado?",a="Mãos regularmente faz negócios com Tannok Marrãogélido, o taberneiro da Destilaria Cervaforte em Kharanos. Sempre que suprimentos são necessários nas terras baixas, Mãos coordena as remessas através do caminho, contando com viajantes para ajudar a preencher a lacuna quando a estrada se torna perigosa.",al={"com quem mãos trabalha","laços de mãos rodamola"}}},fp="20,279,24.453.0,28.176.0,38.192.0,32.175.0"}
P.entries["npc:hansel-heavyhands"] = {n="Hansel Mão-pesada",s="Hansel Mão-pesada é um anão Ferro Negro invulgarmente colossal a serviço da Irmandade do Tório no topo do Posto de Tório, na Garganta Abrasadora. Incumbido de perigosos trabalhos de campo pelos feitores do entreposto, ele costuma delegar tarefas arriscadas a aventureiros que passam pelo local, recorrendo a uma variedade curiosa de queixas físicas insignificantes. Seu porte gigantesco destoa de seus semelhantes, embora seu entusiasmo pelo trabalho em campo não acompanhe seu tamanho.",h="Hansel Mão-pesada é um anão Ferro Negro invulgarmente colossal a serviço da Irmandade do Tório no topo do...",kw={"o caldeirão","ferro negro","hansel mão-pesada","incendosaur","aranha de lava","garganta abrasadora","irmandade do tório","posto de tório"},ang={["faction:Alliance"]="Embora a Aliança geralmente entre em conflito com os lealistas Ferro Negro, a Irmandade do Tório acolhe qualquer um de braço forte, tornando Hansel uma fonte conveniente de trabalhos de recompensa locais.",["faction:Horde"]="Viajantes da Horda acharão que a compleição maciça de Hansel lembra a de um orc ou tauren, embora a sua relutância em entrar em combate honrado certamente cause estranheza.",["race:Dwarf"]="Anões Barbabronze e Martelo Feroz podem se maravilhar — ou desdenhar — do porte colossal de Hansel, indagando-se como um Ferro Negro atingiu proporções tão imponentes passando os dias esquivando-se do trabalho pesado."},sec={{t="Um Gigante entre Anões",b="Mesmo para os padrões de ombros largos do clã Ferro Negro, Hansel Mão-pesada é uma anomalia. Imponente sobre seus irmãos com uma estrutura maciça que beira a de um orc em largura e altura, sua presença física por si só sugere um guerreiro forjado para o massacre na linha de frente. No entanto, apesar de seu porte imponente e de sua alcunha formidável, Hansel parece completamente desinteressado em esforços físicos desnecessários, preferindo a relativa segurança do acampamento da Irmandade do Tório, bem acima das cinzas vulcânicas."},{t="Mestre das Desculpas",b="Taskmaster Scrange e Master Smith Burninate frequentemente encarregam Hansel da inglória tarefa de abater as feras ígneas que espreitam nos poços de escória abaixo. Quando mandado eliminar os predadores Incendosaurs que rastejam pelo Caldeirão, Hansel se esquiva queixando-se de dores nos pés. Quando ordenado a exterminar as Greater Lava Spiders que infestam os ermos calcinantes, ele afirma que a cordilheira vulcânica devastada padece de um 'clima gélido' que lhe causou um terrível resfriado. Consequentemente, qualquer mercenário disposto a desafiar os fluxos de magma encontra Hansel pronto para oferecer um contrato aberto."}},faq={{q="Quem é Hansel Mão-pesada?",a="Hansel Mão-pesada é um anão Ferro Negro aliado à Irmandade do Tório. Alocado no Posto de Tório, na Garganta Abrasadora, ele é conhecido por seu porte físico assustadoramente enorme e por sua incrível habilidade de se esquivar de trabalhos de campo perigosos.",al={"quem é hansel","história de hansel mão-pesada","hansel anão"}},{q="Por que Hansel é muito maior do que os outros anões?",a="Não há uma explicação clara para a sua compleição avantajada. Hansel é simplesmente um anão Ferro Negro anormalmente gigantesco, dotado de ombros largos, membros grossos e uma estatura geral que se aproxima da de um orc.",al={"por que hansel é tão grande","anão enorme garganta abrasadora","anão do tamanho de um orc"}},{q="Quais tarefas Hansel confere aos aventureiros?",a="Hansel recruta viajantes que passam pelo local para lidar com as ordens dadas por seus superiores. Especificamente, ele paga mercenários para exterminar Greater Lava Spiders por toda a Garganta Abrasadora e caçar Incendosaurs nas profundezas d'O Caldeirão.",al={"missões de hansel mão-pesada","quais missões hansel oferece"}},{q="Por que Hansel não faz as próprias tarefas?",a="Hansel inventa desculpas sempre que o perigo surge. Ele culpa os pés doloridos para evitar descer até O Caldeirão e lutar contra os Incendosaurs, e queixa-se de que a escaldante Garganta Abrasadora está fria a ponto de deixá-lo resfriado quando recebe ordens para caçar aranhas de lava.",al={"por que hansel não luta","desculpas de hansel"}},{q="Hansel é leal ao imperador Ferro Negro?",a="Hansel pertence à Irmandade do Tório, uma facção renegada de anões Ferro Negro que rompeu com o Imperador Dagran Thaurissan e Ragnaros. Ele é neutro em relação aos viajantes da Aliança e da Horda que visitam o Posto de Tório.",al={"hansel é leal a forja sombria","hansel é um inimigo"}},{q="Onde Hansel Mão-pesada pode ser encontrado?",a="Ele fica no Posto de Tório, o entreposto rochoso empoleirado na crista norte com vista para a Garganta Abrasadora.",al={"localização de hansel","onde fica hansel"}}},fp="17,420,21.485.0,17.557.0,25.235.0,48.192.0,43.232.0,37.254.0,41.227.0,37.110.0"}
P.entries["npc:harb-clawhoof"] = {n="Harb Casco Afiado",s="Harb Casco Afiado é um criador de montarias tauren estacionado logo fora da Aldeia Casco Sangrento, em Mulgore. Ele cuida dos robustos kodos da tribo, oferecendo-os a cavaleiros tauren dignos e campeões de confiança do Penhasco do Trovão.",h="Harb Casco Afiado é um criador de montarias tauren estacionado logo fora da Aldeia Casco Sangrento, em...",kw={"aldeia casco sangrento","harb casco afiado","treinador de kodos","vendedor de kodos","vendedor de montarias","kodo de mulgore","montarias do penhasco do trovão"},ang={["faction:Horde"]="Para orcs, trolls e Renegados, ganhar um kodo de Harb é o símbolo máximo de honra e amizade reconhecido pelos anciãos do Penhasco do Trovão.",["race:Tauren"]="Harb Casco Afiado fornece a montaria por excelência da sua herança, oferecendo tanto um transporte prático por Mulgore quanto um símbolo das suas tradições nômades."},sec={{t="Criador do Grande Kodo",b="Situado perto dos currais da Aldeia Casco Sangrento, Harb Casco Afiado passa seus dias cuidando das enormes bestas kodo que servem como a espinha dorsal das viagens e do trabalho tauren. Construídos para carregar um peso imenso por grandes distâncias, esses animais robustos são essenciais para a vida nas planícies. Harb garante que cada besta seja bem cuidada, disciplinada e combinada apenas com cavaleiros que comandam o respeito do povo tauren."},{t="Montarias das Planícies",b="Embora os tauren naturalmente ganhem a confiança necessária para montar nos kodos de Harb, os estrangeiros enfrentam um escrutínio mais rigoroso. Devido ao seu tamanho imenso e temperamento, os kodos não são facilmente guiados por aqueles que não estão familiarizados com sua natureza. Aliados não-tauren que desejam cavalgar uma das montarias premiadas de Harb devem primeiro provar sua lealdade e conquistar status exaltado com o Penhasco do Trovão."}},faq={{q="Onde posso encontrar Harb Casco Afiado?",a="Harb Casco Afiado está estacionado ao lado do curral de kodos nos arredores da Aldeia Casco Sangrento, no centro de Mulgore, logo ao sul do Penhasco do Trovão.",al={"localização de harb casco afiado","onde fica harb casco afiado","localização do vendedor de kodos"}},{q="O que Harb Casco Afiado vende?",a="Harb vende vários tipos de montarias kodo, incluindo kodos marrons e cinzas padrão, bem como grandes kodos fortemente blindados para cavaleiros experientes.",al={"o que harb vende","montarias de harb","itens do vendedor de kodos"}},{q="Não-tauren podem comprar kodos de Harb?",a="Sim, mas apenas se tiverem alcançado status exaltado com o Penhasco do Trovão. Os tauren podem comprá-los diretamente, mas outras raças da Horda devem provar seu valor para a tribo antes que Harb confie um kodo a eles.",al={"orcs podem comprar kodos","trolls podem montar kodos","requisito de reputação para kodo"}},{q="Por que os kodos são tão importantes para os tauren?",a="Os kodos são criaturas poderosas e resilientes, perfeitamente adequadas para o estilo de vida nômade e as planícies abertas do centro de Kalimdor. Eles servem como bestas de carga confiáveis, montarias de guerra e transporte comercial pela paisagem acidentada.",al={"lore dos kodos tauren","por que kodos"}}},fx={["2e2e2604"]={q="Quem é Harb Casco Afiado?",a="Harb Casco Afiado é um criador de kodos tauren e mercador de montarias baseado na Aldeia Casco Sangrento. Respeitado entre seu povo por criar e cuidar das poderosas feras de Mulgore, ele garante que campeões capazes tenham montarias firmes adequadas para os rigores de viagens e batalhas por Kalimdor.",al={"quem é harb","história de harb casco afiado","quem é harb casco afiado"}},ceacb5fa={q="De que lado está Harb Casco Afiado?",a="Harb é ferozmente leal ao Penhasco do Trovão e à Horda. Embora ele forneça alegremente montarias para seus companheiros tauren, estranhos de outras raças da Horda devem provar sua dedicação e conquistar grande reputação com o Penhasco do Trovão antes que ele confie a eles um de seus kodos premiados.",al={"facção de harb casco afiado","harb casco afiado é da horda","lealdade de harb casco afiado"}},["0020906d"]={q="O que Harb Casco Afiado quer?",a="Harb quer criar kodos fortes e confiáveis e vê-los confiados apenas a cavaleiros que realmente os respeitam. Para os tauren, o kodo não é apenas uma besta de carga, mas a espinha dorsal de sua civilização, e Harb trabalha para preservar essa parceria sagrada.",al={"o que harb quer","objetivo de harb casco afiado","propósito de harb casco afiado"}},efcee9d4={q="Por que Harb Casco Afiado está na Aldeia Casco Sangrento?",a="A Aldeia Casco Sangrento é um local de encontro central para jovens tauren e viajantes que viajam para fora da Aldeia Narache em direção às planícies mais amplas de Mulgore. Harb mantém seus estábulos aqui, onde há amplo pasto aberto para pastar e criar fortes rebanhos de kodo para a defesa e prosperidade das tribos.",al={"por que harb está na aldeia casco sangrento","por que harb está aqui","harb aldeia casco sangrento"}}},fp="13,208,25.403.0,20.360.0,31.139.0,29.141.0,35.205.0,41.221.0"}
P.entries["npc:harken-windtotem"] = {n="Harken Totem do Vento",s="Harken Totem do Vento é um caçador tauren que reside na Aldeia Casco Sangrento, em Mulgore. Dedicado às tradições do seu povo, ele incumbe jovens caçadores e viajantes de provar suas habilidades de rastreamento e forrageamento pelas planícies douradas.",h="Harken Totem do Vento é um caçador tauren que reside na Aldeia Casco Sangrento, em Mulgore.",kw={"aldeia casco sangrento","harken totem do vento","mulgore","caçada ao rapineiro","tauren","totem do vento"},ang={["class:Hunter"]="Para os rastreadores da vida selvagem que passam pela Aldeia Casco Sangrento, a tarefa de Harken de abater rapineiros em pleno voo oferece um teste inicial essencial de pontaria e coleta de presas.",["race:Tauren"]="Harken Totem do Vento personifica a filosofia de caça ancestral dos taurens: provar disciplina e autossuficiência nas planícies, enquanto honra as feras da Mãe Terra."},sec={{t="Caçador de Casco Sangrento",b="Situado próximo ao coração da Aldeia Casco Sangrento, Harken Totem do Vento atua como instrutor e guia para aqueles que aprendem as artes de caça dos taurens. A vida nas planícies de Mulgore exige respeito pelo mundo natural, juntamente com a habilidade prática de sustentar a própria tribo. Harken avalia jovens aventureiros instruindo-os a caçar os rapineiros nativos que sobrevoam os platôs, recolhendo suas penas para medir a paciência, a pontaria e a capacidade do caçador de colher sem desperdício."}},faq={{q="Quem é Harken Totem do Vento?",a="Harken é um caçador tauren que vive na Aldeia Casco Sangrento, no centro de Mulgore. Ele guia viajantes e aventureiros iniciantes no aprendizado das tradições fundamentais de caça e rastreamento dos taurens.",al={"história de harken totem do vento","quem é harken"}},{q="Onde Harken Totem do Vento pode ser encontrado?",a="Harken está instalado na Aldeia Casco Sangrento, um assentamento situado ao sul do Penhasco do Trovão, no centro de Mulgore.",al={"localização de harken","onde fica harken totem do vento"}},{q="Quais tarefas Harken concede aos aventureiros?",a="Ele oferece a missão Caçada ao rapineiro, pedindo aos caçadores que se aventurem pelas pradarias de Mulgore para abater rapineiros selvagens e recolher suas robustas penas de voo.",al={"missões de harken totem do vento","missão caçada ao rapineiro"}},{q="Harken tem parentesco com Bovan Windtotem?",a="Eles compartilham o nome de clã Windtotem, sugerindo um parentesco tribal ou ligação familiar, embora Harken permaneça concentrado nas caçadas da aldeia local em Mulgore.",al={"harken é parente de bovan","relação com bovan windtotem"}}},fx={b6c1a716={q="De que lado está Harken Totem do Vento?",a="Harken Totem do Vento permanece lealmente com as tribos tauren e a Horda. Baseado na Aldeia Casco Sangrento, seu foco está inteiramente em apoiar o assentamento local e orientar jovens caçadores enquanto eles trabalham para sustentar seu povo em Mulgore.",al={"facção de harken totem do vento","a quem harken serve","harken é da horda"}},fffafcb2={q="O que Harken Totem do Vento quer?",a="Harken busca caçadores capazes para reduzir a população local de swoops e coletar suas penas. As planícies de Mulgore exigem autossuficiência, e ao colocar os novatos à prova contra os swoops, ele ajuda a fornecer materiais úteis enquanto aprimora as habilidades de jovens viajantes.",al={"o que harken quer","objetivo de harken totem do vento","por que harken dá missões"}},["4b75134c"]={q="Por que Harken Totem do Vento está na Aldeia Casco Sangrento?",a="Como um membro da tribo Totem do Vento residindo na Aldeia Casco Sangrento, Harken supervisiona os esforços de caça pelas planícies centrais. Ele permanece na aldeia para direcionar os caçadores de passagem, garantindo que a vida selvagem permaneça equilibrada e que o assentamento tenha os recursos de que precisa.",al={"por que harken está aqui","propósito de harken totem do vento","por que harken está na aldeia casco sangrento"}}},fp="16,233,21.468.0,24.194.0,36.106.0,43.155.0,37.150.0"}
P.entries["npc:harlan-bagley"] = {n="Timóteo Fialho",s="Timóteo Fialho é um armadilheiro e comerciante humano que opera na Lionheart Armory, no movimentado Distrito Comercial de Ventobravo. Ele cuida de sua loja no lado norte do centro do distrito, cuidando de armas e equipamentos tanto para cidadãos quanto para aventureiros que visitam a cidade.",h="Timóteo Fialho é um armadilheiro e comerciante humano que opera na Lionheart Armory, no movimentado Distrito...",kw={"armadilheiro","timóteo fialho","lionheart armory","comerciante","ventobravo","distrito comercial"},ang={["faction:Alliance"]="Comerciantes como Timóteo Fialho mantêm a principal capital da Aliança abastecida com equipamentos e mercadorias enquanto as linhas de suprimento regulares são ameaçadas pelos territórios vizinhos."},sec={{t="A Lionheart Armory",b="Situada ao longo do lado norte do Distrito Comercial, a Lionheart Armory serve como um ponto comercial constante no coração de Ventobravo. De trás de seu balcão, Timóteo Fialho gerencia o estoque e negocia equipamentos defensivos, dependendo do comércio e de mensageiros regionais para manter suas prateleiras abastecidas enquanto a capital lida com conflitos de fronteira distantes e restrições de suprimentos."}},faq={{q="Quem é Timóteo Fialho?",a="Timóteo Fialho é um lojista e comerciante humano que administra a Lionheart Armory, uma loja de equipamentos localizada no Distrito Comercial de Ventobravo.",al={"quem é timóteo","história de timóteo fialho","vendedor lionheart armory"}},{q="Onde posso encontrar Timóteo Fialho?",a="Ele está localizado dentro da Lionheart Armory, no lado norte da praça central no Distrito Comercial de Ventobravo.",al={"localização de timóteo fialho","onde fica timóteo","localização de lionheart armory"}},{q="Qual é o papel dele no comércio de Ventobravo?",a="Como um comerciante local na capital do reino, Timóteo Fialho fornece armaduras e equipamentos, ocasionalmente contratando aventureiros para realizar entregas e garantir remessas de suprimentos essenciais para manter sua armaria aberta.",al={"o que timóteo vende","negócio de timóteo fialho"}}},fx={["13bd1b18"]={q="De que lado está Timóteo Fialho?",a="Timóteo Fialho é um cidadão comum e comerciante da Aliança, leal ao Reino de Ventobravo. Ele conduz seus negócios abertamente dentro do Distrito Comercial, servindo aos aventureiros, guardas e defensores que passam pela capital.",al={"facção de timóteo fialho","timóteo fialho é da aliança"}},d342d373={q="O que Timóteo Fialho quer?",a="Administrar o Lionheart Armory requer um fluxo confiável de matérias-primas e mão de obra. Timóteo está focado em manter seu arsenal totalmente abastecido e pronto para atender aos clientes, frequentemente buscando a ajuda de viajantes para conseguir mercadorias e reabastecer suas prateleiras.",al={"o que timóteo quer","motivo de timóteo fialho","por que timóteo precisa de reabastecimento"}},["0eb71712"]={q="Por que Timóteo Fialho está aqui?",a="Timóteo opera o Lionheart Armory, situado no lado norte do movimentado Distrito Comercial de Ventobravo. Ele permanece aqui para atender ao intenso fluxo de compradores, ferreiros e soldados que se equipam para viajar por toda Azeroth.",al={"por que timóteo fialho está em ventobravo","por que timóteo está no distrito comercial"}}},fp="13,269,20.388.0,21.147.0,31.120.0,47.199.0"}
P.entries["npc:harlo-barnaby"] = {n="Lépore Barnabé",s="Lépore Barnabé é um refugiado anão ferido que reside no Porto de Menethil. Tendo escapado por pouco do massacre quando o clã Ferro Negro tomou Dun Modr, ele agora alerta os viajantes sobre a tragédia que se desenrolou nos pântanos do norte.",h="Lépore Barnabé é um refugiado anão ferido que reside no Porto de Menethil.",kw={"ferro negro","dun modr","lépore barnabé","porto de menethil","ponte thandol","os pântanos"},ang={["faction:Alliance"]="A Queda de Dun Modr ameaça a ponte de terra crucial entre Os Pântanos e Arathi, tornando os avisos de Lépore essenciais para as forças da Aliança.",["race:Dwarf"]="Lépore representa uma lembrança viva da guerra de clãs persistente e sangrenta contra os traiçoeiros Ferro Negro, que buscam separar Khaz Modan do norte."},sec={{t="Fuga de Dun Modr",b="Lépore Barnabé viveu em Dun Modr até que a fortaleza do norte caiu diante de um ataque repentino e selvagem dos anões Ferro Negro. No caos da emboscada, Lépore fugiu para o sul em busca de segurança, apenas para ser atingido em cheio nas costas por um machado perdido. Desmaiado pelo golpe, ele de alguma forma sobreviveu à jornada pelo pântano e acordou enfaixado no Porto de Menethil. Embora vivo, seus ferimentos e as lembranças do massacre o impedem de retornar, levando-o a incentivar os aventureiros da Aliança a investigarem as ruínas fumegantes de seu antigo lar."}},faq={{q="Quem é Lépore Barnabé?",a="Lépore Barnabé é um anão de Altaforja que vive no Porto de Menethil e sobreviveu ao ataque brutal do Ferro Negro ao posto avançado de Dun Modr.",al={"lépore barnabé","quem é lépore","anão do porto de menethil"}},{q="Como Lépore Barnabé foi parar no Porto de Menethil?",a="Enquanto fugia da invasão de Dun Modr, ele foi atingido nas costas por um machado arremessado. Ele perdeu a consciência durante sua retirada e acordou em segurança no Porto de Menethil, sob os cuidados de curandeiros locais.",al={"como lépore veio parar aqui","lépore barnabé ferimento nas costas"}},{q="O que aconteceu com Dun Modr?",a="Dun Modr foi invadida e devastada por anões Ferro Negro hostis que avançavam para o sul a partir da Ponte Thandol, aniquilando os defensores anões locais e empurrando os sobreviventes para os pântanos.",al={"queda de dun modr","o que aconteceu em dun modr"}}},fx={["2ef93137"]={q="De que lado está Lépore Barnabé?",a="Lépore Barnabé é leal a Altaforja e a Aliança. Como um sobrevivente do ataque catastrófico ao posto avançado ao norte de Dun Modr, ele permanece ao lado de seus companheiros anões do clã Barbabronze e busca bravos aventureiros da Aliança para ajudar a lidar com os invasores Ferro Negro que sobrecarregam o caminho ao norte.",al={"facção de lépore barnabé","a quem lépore barnabé serve","lépore barnabé é da aliança"}},["4a6adfe0"]={q="O que Lépore Barnabé quer?",a="Ainda tratando de seus ferimentos, Lépore quer que você leve notícias e assistência a respeito da queda de Dun Modr. Ele escapou por pouco com vida quando os anões Ferro Negro romperam o reduto ao norte, e ele busca combatentes capazes para trazer retribuição aos traidores e recuperar o que foi perdido.",al={"motivo de lépore barnabé","o que lépore quer que você faça","objetivo da missão de lépore barnabé"}}},fp="13,226,20.526.0,21.131.0,48.192.0,26.181.0"}
P.entries["npc:hegnar-rumbleshot"] = {n="Hegnar Estremetiro",s="Hegnar Estremetiro é um armeiro anão instalado ao longo da estrada nevada que leva do Caminho de Cristálgida em direção a Kharanos. Ele mantém um movimentado estande de tiro e equipa caçadores e montanhistas locais com armas de fogo e munição.",h="Hegnar Estremetiro é um armeiro anão instalado ao longo da estrada nevada que leva do Caminho de Cristálgida...",kw={"munição","caminho de cristálgida","dun morogh","armeiro","hegnar estremetiro","kharanos","estande de tiro"},ang={["class:Hunter"]="Para os atiradores que partem do Vale Cristálgida em direção aos picos nevados mais amplos de Dun Morogh, Hegnar fornece chumbo essencial, bolsas de munição e armas de fogo sobressalentes.",["race:Dwarf"]="Os anões se orgulham de seu artesanato e de sua pontaria, tornando o estande de prática à beira da estrada de Hegnar um ponto de encontro natural para viajantes que desejam testar seus gatilhos."},sec={{t="Um Armeiro na Estrada",b="Instalado em um pequeno acampamento entre o Caminho de Cristálgida e Kharanos, Hegnar Estremetiro atende a atiradores anões, viajantes e à milícia local. Seu acampamento conta com um popular estande de tiro onde o povo da montanha aprimora sua pontaria contra as feras selvagens que rondam Dun Morogh. Abastecer tantos atiradores ávidos faz com que Hegnar queime munição em um ritmo acelerado, deixando-o perpetuamente dependente de novas remessas de munição de seu fornecedor, o engenheiro anão Loslor Rudge."}},faq={{q="Quem é Hegnar Estremetiro?",a="Hegnar Estremetiro é um armeiro anão que administra um estande de tiro ao ar livre e um acampamento ao longo do caminho principal entre o Caminho de Cristálgida e Kharanos.",al={"quem é hegnar","pnc hegnar estremetiro","armeiro em dun morogh"}},{q="De onde Hegnar consegue sua munição?",a="Hegnar depende de Loslor Rudge, um fornecedor de engenharia anão de outra parte de Dun Morogh, para fabricar e fornecer a munição necessária para manter seu estande de tiro funcionando.",al={"fornecedor de hegnar","quem abastece estremetiro","missão sem munição não tem negócio"}},{q="O que Hegnar faz pelos anões locais?",a="Ele equipa caçadores locais e membros da milícia com armas de fogo e chumbo, além de fornecer um estande de tiro para atiradores que viajam por Dun Morogh.",al={"por que hegnar está aqui","estande de tiro de hegnar","função de estremetiro"}}},fx={f158c8ab={q="De que lado está Hegnar Estremetiro?",a="Hegnar é firmemente leal a Altaforja e a Aliança. Estacionado ao longo da estrada da montanha, ele equipa a milícia local, os defensores e os caçadores de Dun Morogh com armas de fogo confiáveis para manter as passagens nevadas do reino seguras contra ameaças invasoras.",al={"facção de hegnar estremetiro","hegnar é da aliança","a quem hegnar serve"}},["932ff4bf"]={q="O que Hegnar Estremetiro quer?",a="Hegnar precisa de um suprimento constante de munição para manter sua oficina e seu campo de treinamento funcionando. Como os atiradores e a milícia local treinam e reabastecem constantemente em seu acampamento, seus suprimentos diminuem rapidamente, exigindo entregas regulares de seu parceiro engenheiro, Loslor Rudge.",al={"do que hegnar precisa","objetivo de hegnar estremetiro","missão de hegnar"}},["3c40a283"]={q="Por que Hegnar Estremetiro está aqui ao longo da estrada?",a="Ele montou seu acampamento e campo de tiro ao longo da estrada muito movimentada entre o Caminho de Cristálgida e Kharanos. Esta localização ideal permite que ele forneça equipamentos para os recrutas que saem do vale, bem como para os patrulheiros que defendem as neves centrais de Dun Morogh.",al={"por que hegnar está aqui fora","localização do acampamento de hegnar","por que hegnar montou um acampamento"}}},fp="17,225,22.470.0,25.142.0,37.168.0,42.144.0"}
P.entries["npc:henze-faulk"] = {n="Henze Faulk",s="Henze Faulk é um anão aventureiro encontrado agonizando no círculo de pedras do lado de fora da Vigia dos Heróis, na Floresta de Elwynn. Derrubado pela Irmandade Défias enquanto protegia seu companheiro, ele serve como um teste crucial para aspirantes a paladino que aprendem a usar o dom da ressurreição.",h="Henze Faulk é um anão aventureiro encontrado agonizando no círculo de pedras do lado de fora da Vigia dos...",kw={"défias","floresta de elwynn","gazin tenorm","henze faulk","vigia dos heróis","ressurreição","símbolo da vida","tomo de divindade"},ang={["class:Paladin"]="Henze Faulk representa seu primeiro teste verdadeiro de misericórdia divina. Trazê-lo de volta à beira da morte com um Símbolo da Vida ensina ao paladino que a Luz não é apenas uma arma para a batalha, mas um poder solene para desafiar a morte.",["race:Dwarf"]="Ver um irmão anão abatido em terras humanas é um lembrete austero de que os bandidos Défias representam uma ameaça mortal para viajantes de todas as raças, e não apenas para os habitantes de Ventobravo."},sec={{t="Um sacrifício na Vigia dos Heróis",b="Perto do antigo anel de pedras a leste de Ventobravo fica a Vigia dos Heróis, um local frequentemente assombrado por bandidos Défias que rondam os bosques de Elwynn. Henze Faulk e seu amigo Gazin Tenorm foram emboscados aqui por saqueadores Défias. Colocando-se em perigo para garantir a sobrevivência de Gazin, Henze sucumbiu às lâminas dos bandidos. Enquanto seu companheiro sobreviveu para pedir ajuda à Catedral da Luz, o corpo de Henze permanece no limiar entre a vida e a morte, aguardando a intervenção divina de um paladino portando um Símbolo da Vida."}},faq={{q="Quem é Henze Faulk?",a="Henze Faulk é um anão de Altaforja encontrado mortalmente ferido no círculo de pedras perto da Vigia dos Heróis, na Floresta de Elwynn. Ele foi emboscado e derrubado por bandidos Défias enquanto salvava seu amigo Gazin Tenorm.",al={"henze faulk","anão na vigia dos heróis","anão agonizando elwynn"}},{q="Por que Henze Faulk está caído no chão?",a="Henze foi emboscado pela Irmandade Défias enquanto viajava com Gazin Tenorm. Ele recebeu o impacto do ataque para que Gazin pudesse escapar, ficando mortalmente ferido e aguardando a ressurreição por um iniciado da Luz Sagrada.",al={"por que henze está morrendo","henze está morto","henze faulk morto"}},{q="Qual é a ligação de Henze com os paladinos?",a="Henze é a figura central em um rito de passagem para jovens paladinos que realizam as provações do Tomo de Divindade. Os iniciados a paladino recebem um Símbolo da Vida e são enviados a Elwynn para resgatar Henze da morte, provando seu domínio sobre a mais sagrada bênção de redenção da Luz.",al={"missão de paladino henze","anão tomo de divindade"}},{q="Quem é Gazin Tenorm?",a="Gazin Tenorm é o companheiro de Henze Faulk. Quando os dois foram encurralados por bandidos Défias, Henze protegeu Gazin, permitindo que ele sobrevivesse e buscasse ajuda na Igreja da Luz Sagrada.",al={"quem é gazin","amigo de gazin tenorm"}}},fx={["162be787"]={q="De que lado está Henze Faulk?",a="Henze Faulk é firmemente aliado a Aliança e a Sagrada Luz. Um amigo leal e companheiro anão de Gazin Tenorm, ele caiu enquanto defendia bravamente seu amigo dos implacáveis fora da lei da The Defias Brotherhood na Floresta de Elwynn.",al={"facção de henze faulk","henze é da aliança","lealdade de henze faulk"}},["47ed07eb"]={q="O que Henze Faulk quer?",a="Tendo caído em uma emboscada cruel da The Defias Brotherhood, a necessidade imediata de Henze Faulk é o milagre da Luz para restaurar sua vida. Além da sobrevivência, sua intenção altruísta era simplesmente proteger seu companheiro, Gazin Tenorm, de danos.",al={"o que henze quer","objetivo de henze faulk"}}},fp="11,281,28.507.0,19.206.0,39.223.0,39.292.0,20.184.0"}
P.entries["npc:heralath-fallowbrook"] = {n="Heralath Corregofulvo",s="Heralath Corregofulvo é um druida Elfo Noturno moribundo, aprisionado nas profundezas do Urzal dos Tuscos. Enviado para investigar a corrupção espinhosa que cerca os restos do Ancião Agamaggan, ele foi capturado e brutalizado pela tribo dos Tuscos. Com seus últimos suspiros, ele tenta enviar notícias de seu destino e um estimado pingente de volta para sua esposa em Darnassus.",h="Heralath Corregofulvo é um druida Elfo Noturno moribundo, aprisionado nas profundezas do Urzal dos Tuscos.",kw={"agamaggan","corregofulvo","henrig lonebrow","heralath","a mortalidade se esvanece","javatusco","urzal dos tuscos","treshala"},ang={["class:Druid"]="Ver um irmão druida abatido pelas sarças selvagens do Urzal dos Tuscos é um lembrete austero da corrupção selvagem e implacável que se espalha descontrolada pelos Sertões Meridionais.",["race:NightElf"]="Levar o pingente de Heralath de volta a Darnassus honra um irmão caído que deu a vida tentando compreender e curar as terras feridas de Kalimdor."},sec={{t="Uma Missão Trágica",b="Enviado por seu povo para investigar o antigo deus javali Agamaggan e as sarças que se espalham sufocando o sul dos Sertões, Heralath Corregofulvo buscou a raiz da corrupção do Urzal dos Tuscos. Em vez de desenterrar respostas, o Elfo Noturno foi feito prisioneiro pelos javatuscos. Trancado em um cercado esquálido e espancado implacavelmente, Heralath sucumbiu a ferimentos graves e a uma febre violenta. Antes de se apagar por completo, compartilhou o que sabia com outro cativo, o anão Henrig Lonebrow, instando-o a avisar o posto das sentinelas em Thalanaar sobre a agressão incitada pela megera javatusco Charlga Talhaflanco."},{t="Um Último Desejo",b="Embora Lonebrow tenha conseguido escapar, Heralath estava fraco demais para fugir. Permanecendo às portas da morte dentro dos cercados emaranhados do Urzal, o druida se agarra à consciência apenas o suficiente para implorar aos aventureiros que passam. Ele não pede resgate, mas sim que o pingente de sua esposa Treshala seja recuperado de seus captores e levado de volta a Darnassus, garantindo que ela saiba do seu destino e que ele guardou sua lembrança até o fim."}},faq={{q="Quem é Heralath Corregofulvo?",a="Heralath Corregofulvo é um druida Elfo Noturno mantido em cativeiro dentro do Urzal dos Tuscos. Ele viajou para os Sertões para estudar a corrupção das sarças e o legado do falecido Ancião javali Agamaggan, mas foi capturado e fatalmente torturado pelos javatuscos.",al={"quem é heralath","heralath corregofulvo","elfo noturno no urzal dos tuscos"}},{q="O que aconteceu com Heralath dentro do Urzal dos Tuscos?",a="Após ser feito prisioneiro pelos javatuscos dos Tuscos, Heralath foi espancado e trancado em uma cabana. Entre abusos implacáveis e doenças, seu corpo sucumbiu, deixando-o à beira da morte no momento em que os socorristas puderam alcançá-lo.",al={"por que heralath está morrendo","o que aconteceu com heralath corregofulvo"}},{q="O que Heralath pede que os viajantes façam?",a="Sabendo que não sobreviverá, Heralath implora aos aventureiros que recuperem o pingente de sua esposa com os javatuscos e o levem até ela em Darnassus, levando a trágica notícia de sua morte.",al={"missão do heralath","missão a mortalidade se esvanece"}},{q="Quem era Henrig Lonebrow para Heralath?",a="Henrig Lonebrow era um cativo anão mantido no mesmo cercado que Heralath. Antes de Henrig conseguir escapar, Heralath compartilhou com ele informações vitais sobre Agamaggan e implorou que uma mensagem fosse entregue ao posto avançado de Thalanaar sobre as movimentações de Charlga Talhaflanco.",al={"henrig lonebrow heralath","anão cativo no urzal dos tuscos"}}},fx={["4cf4e465"]={q="De que lado está Heralath Corregofulvo?",a="Heralath é um elfo noturno leal a Darnassus e a Aliança. Como um druida de seu povo, ele se aventurou profundamente nos Sertões Meridionais em nome deles, buscando entender a estranha corrupção que se enraíza entre os javatuscos e salvaguardar Kalimdor de qualquer escuridão que se agite dentro do Urzal dos Tuscos.",al={"facção de heralath corregofulvo","heralath é da aliança","lealdade de heralath"}},["6e64ea11"]={q="Por que Heralath Corregofulvo está no Urzal dos Tuscos?",a="Ele viajou para cá para investigar rumores persistentes sobre o Ancestral Agamaggan caído e descobrir a raiz da praga que corrompe o Urzal dos Tuscos. Infelizmente, sua expedição terminou em desastre quando os ferozes javatuscos do Urzal dos Tuscos o capturaram, submetendo-o a um cativeiro brutal e a ferimentos fatais.",al={"por que heralath está aqui","propósito de heralath no urzal dos tuscos","por que heralath veio ao urzal dos tuscos"}}},fp="20,351,16.596.0,12.413.1,28.252.0,48.213.0,39.174.0,36.262.0"}
P.entries["npc:herod"] = {n="Herodes",s="Herodes é um renomado campeão e berserker da Cruzada Escarlate, comandando o Arsenal dentro do Monastério Escarlate. Conhecido por sua feroz perícia marcial e zelo implacável, ele treina recrutas no brutal combate corpo a corpo necessário para travar uma guerra santa. Sua morte é buscada tanto por dissidentes da Aliança quanto pelos líderes da Horda na Cidade Baixa para enfraquecer o núcleo militar da Cruzada.",h="Herodes é um renomado campeão e berserker da Cruzada Escarlate, comandando o Arsenal dentro do Monastério...",kw={"arsenal","berserker","herodes","raleigh o devoto","ravager","cruzada escarlate","monastério escarlate","varimatras"},ang={["class:Warrior"]="Herodes é um exemplo primoroso de guerreiro enfurecido cujos golpes furiosos de redemoinho e agressividade imprudente fazem dele um temido modelo marcial entre os recrutas da Cruzada Escarlate.",["faction:Alliance"]="Heróis da Aliança que atendem ao apelo de Raleigh, o Devoto, podem testemunhar em primeira mão como os antes nobres defensores de Lordaeron caíram em uma sede de sangue desvairada e fanática sob o comando de líderes como Herodes.",["faction:Horde"]="Para a Horda e os Renegados em particular, eliminar Herodes cumpre diretamente as ordens de Varimatras para quebrar a liderança que ameaça as fronteiras de Clareiras de Tirisfal."},sec={{t="O Campeão do Arsenal",b="Dentro dos salões fortificados do Arsenal do Monastério Escarlate, Herodes ergue-se como a personificação da agressividade marcial da Cruzada. Ao contrário dos conjuradores e paladinos que canalizam magia sagrada na Catedral, Herodes confia em um poder físico bruto e sanguinário. Vestido em cota de malha e empunhando um enorme machado de duas mãos, ele treina pessoalmente coortes de Recrutas Escarlates, incutindo uma devoção furiosa para exterminar qualquer um que não esteja aliado à sua causa fanática."},{t="Um Alvo de Alta Prioridade",b="Como Herodes supervisiona os armamentos e o treinamento marcial dos guerreiros de linha de frente da Cruzada, derrotá-lo é essencial para qualquer um que busque desmantelar a ordem. Raleigh, o Devoto, um ex-cruzado desiludido com a loucura da ordem e residente em Costa Sul, pede a morte de Herodes para despedaçar a liderança militar deles. Do outro lado de Lordaeron, o senhor do terror Varimatras na Cidade Baixa busca de forma semelhante a execução dele para eliminar um perigoso bastião humano na fronteira com o território dos Renegados."}},faq={{q="Quem é Herodes?",a="Herodes é um guerreiro humano de elite e comandante do Arsenal no Monastério Escarlate. Ele atua como um dos quatro principais líderes do Monastério, responsável por equipar e treinar os fanáticos combatentes corpo a corpo da Cruzada.",al={"história de herodes","quem é herodes","herodes monastério escarlate"}},{q="Onde Herodes fica localizado?",a="Herodes pode ser encontrado no coração da ala do Arsenal no Monastério Escarlate, situado no nordeste de Clareiras de Tirisfal. Ele aguarda desafiantes em um ringue central de treinamento cercado por galerias de observação.",al={"onde fica herodes","localização de herodes","encontrar herodes"}},{q="Por que a Horda quer a morte de Herodes?",a="O senhor do terror Varimatras, agindo em nome dos Renegados na Cidade Baixa, busca a eliminação dos comandantes-chave do Monastério — incluindo Herodes — para erradicar a ameaça persistente da Cruzada bem às portas da capital dos Renegados.",al={"missão de herodes varimatras","por que horda mata herodes","into the scarlet monastery"}},{q="Por que a Aliança quer a morte de Herodes?",a="Raleigh, o Devoto, um antigo membro da Cruzada Escarlate instalado em Contraforte de Eira dos Montes, reconhece que a ordem descambou para o zelo fanático. Ele pede aos campeões da Aliança que expurguem Herodes para despojar a Cruzada de sua liderança guerreira brutal.",al={"in the name of the light","raleigh o devoto herodes","por que aliança mata herodes"}},{q="O que acontece quando Herodes é derrotado?",a="Após a derrota de Herodes, uma turba de jovens Recrutas Escarlates surge dos quartéis ao redor invadindo o ringue para vingar seu mestre, ilustrando a imensa profundidade da devoção que ele despertava em seus alunos.",al={"recrutas escarlates","investida de recrutas de herodes","evento de morte de herodes"}},{q="Que tipo de combatente é Herodes?",a="Herodes é um berserker e guerreiro, e não um paladino sagrado tradicional. Ele usa investidas impiedosas e golpes devastadores de redemoinho para esmagar os inimigos, dependendo de puro frenesi físico em vez de feitiços da Luz Sagrada.",al={"estilo de luta de herodes","herodes é um paladino"}}},fx={["3c3e6bcb"]={q="De que lado está Herodes?",a="Herodes é um comandante de alto escalão da The Scarlet Crusade, servindo como um dos quatro líderes principais estacionados dentro do Monastério Escarlate. Fanaticamente leal à missão zelosa da Cruzada, ele direciona seu treinamento militar e arsenal contra todos aqueles que a Cruzada considera impuros ou hostis.",al={"facção de herodes","a quem herodes serve","de que lado está herodes"}},["78320a40"]={q="O que Herodes quer?",a="Herodes dedica-se a preparar a próxima geração de guerreiros da The Scarlet Crusade para erradicar seus inimigos. Supervisionando o Arsenal, ele treina recrutas para igualar seu próprio fervor marcial implacável, procurando esmagar qualquer um tolo o suficiente para invadir os terrenos sagrados do Monastério.",al={"objetivo de herodes","propósito de herodes","o que herodes está tentando fazer"}},["60fea3ae"]={q="Por que Herodes está aqui?",a="Herodes comanda a ala do Arsenal do Monastério Escarlate. Como campeão e instrutor dos recrutas Escarlates, ele supervisiona o arsenal da Cruzada e testa pessoalmente qualquer um que ouse desafiar o coração da Cruzada.",al={"por que herodes está no arsenal","por que herodes está no monastério escarlate","função de herodes no arsenal"}},f73350c1={q="A quem Herodes está ligado?",a="Herodes está ao lado da liderança interna do Monastério Escarlate, que inclui a Alta Inquisidora Whitemane, o Comandante Escarlate Mograine e o Mestre de Matilha Lobato. Juntos, eles governam o bastião da Cruzada nas Clareiras de Tirisfal.",al={"quem lidera herodes","aliados de herodes","com quem herodes trabalha"}},["9c060a47"]={q="Por que Herodes é famoso ou temido?",a="Conhecido como o Campeão Escarlate, Herodes é famoso por seu estilo de luta feroz e de berserker. Empunhando um machado de batalha maciço, ele é infame por girar em um turbilhão de aço devastador e imparável que despedaça todos os inimigos próximos.",al={"por que herodes é temido","reputação de herodes","o que torna herodes perigoso"}}},fp="5,373,26.452.0,22.488.0,13.228.0,23.200.0,35.239.0,38.254.0,36.201.1,30.210.0"}
P.entries["npc:high-executor-darthalia"] = {n="Alta-executora Darthalia",s="A Alta-executora Darthalia é uma comandante militar Renegada de alto escalão posicionada na Serraria Tarren, no Contraforte de Eira dos Montes. Atuando sob a autoridade direta de Grande Dama Sylvana Correventos e Varimatras, ela lidera as operações dos Renegados contra o bastião humano de Costa Sul e os bandidos locais da Camarilha. Sua liderança é essencial para proteger o flanco sul da Horda em Lordaeron.",h="A Alta-executora Darthalia é uma comandante militar Renegada de alto escalão posicionada na Serraria Tarren...",kw={"darthalia","alta-executora","eira dos montes","contraforte de eira dos montes","costa sul","sylvanas","camarilha","serraria tarren","varimatras"},ang={["faction:Alliance"]="Para os humanos de Costa Sul e seus aliados, Darthalia é a arquiteta implacável por trás dos ataques incessantes que ameaçam seu último ponto de apoio em Lordaeron.",["faction:Horde"]="Aventureiros da Horda se reportam a Darthalia para conter a agressão da Aliança e manter a fronteira disputada do Contraforte de Eira dos Montes.",["race:Undead"]="Para os Renegados, Darthalia representa a vontade de ferro da Cidade Baixa, assegurando que Lordaeron permaneça sob o controle dos mortos-vivos de livre-arbítrio."},sec={{t="Comandante da Serraria Tarren",b="Operando a partir da Serraria Tarren, a Alta-executora Darthalia atua como comandante operacional das forças dos Renegados por todo o Contraforte de Eira dos Montes. Sua principal preocupação estratégica é frear a expansão da resistência humana, mantendo as forças da Aliança contidas em Costa Sul e caçando os criminosos renegados da Camarilha que infestam os arredores. Qualquer investida ofensiva no sul de Eira dos Montes passa diretamente por seu comando."},{t="A Guerra por Eira dos Montes",b="Sob ordens diretas vindas da liderança máxima da Cidade Baixa — a Rainha Banshee e seu tenente senhor do medo, Varimatras —, Darthalia supervisiona a implacável guerra de desgaste em Eira dos Montes. Ela coordena missões de reconhecimento, ataques estratégicos contra líderes humanos e recompensas por criminosos perigosos que ameaçam o domínio dos Renegados no norte de Lordaeron."}},faq={{q="Quem é a Alta-executora Darthalia?",a="A Alta-executora Darthalia é uma líder militar dos Renegados posicionada no Contraforte de Eira dos Montes. Ela é responsável por coordenar os esforços militares da Horda e dos Renegados contra a vila humana de Costa Sul e por eliminar ameaças regionais hostis.",al={"quem é darthalia","identidade de darthalia","executora darthalia"}},{q="Onde Darthalia pode ser encontrada?",a="Ela comanda as forças dos Renegados a partir da Serraria Tarren, organizando tropas e coordenando ataques pela região central de Lordaeron.",al={"localização de darthalia","onde fica darthalia","mapa da executora darthalia"}},{q="A quem Darthalia responde?",a="Darthalia opera sob a hierarquia militar direta da Cidade Baixa, respondendo a Grande Dama Sylvana Correventos e ao senhor do medo Varimatras enquanto coordenam a defesa e a expansão do território dos Renegados.",al={"chefe de darthalia","facção de darthalia","quem comanda darthalia"}},{q="Quais tarefas Darthalia concede aos aventureiros?",a="Darthalia encarrega os campeões da Horda de atacar diretamente os assentamentos humanos, executar criminosos perigosos e caçar membros da Camarilha que atuam por todo o Contraforte de Eira dos Montes.",al={"missões de darthalia","missões com darthalia","o que darthalia quer"}},{q="Por que Darthalia luta contra os humanos de Costa Sul?",a="Costa Sul representa o principal ponto de apoio militar da Aliança em Lordaeron. A missão de Darthalia é reprimir a presença humana, proteger a Serraria Tarren e impedir que a Aliança avance para o norte, em direção à Cidade Baixa.",al={"por que atacar costa sul","guerra de costa sul","conflito de eira dos montes"}},{q="Qual é a patente de Darthalia no exército dos Renegados?",a="Como Alta-executora, Darthalia ocupa uma das mais altas patentes de comando de campo na hierarquia militar dos Renegados, tendo autoridade operacional sobre as forças regionais, postos avançados e estratégias de guerra na área.",al={"patente alta-executora","título de darthalia"}}},fx={c2c985e7={q="De que lado está a Alta-executora Darthalia?",a="A Alta-executora Darthalia serve aos Renegados e a Horda. Ela opera como uma comandante militar de alto escalão sob a autoridade da Grande Dama Sylvana Correventos e de Varimatras, direcionando as operações da Horda no Contraforte de Eira dos Montes para garantir a região contra a invasão da Aliança.",al={"facção de darthalia","por quem darthalia luta","darthalia é da horda"}},["77f4a495"]={q="O que a Alta-executora Darthalia quer?",a="Darthalia busca impedir a disseminação da humanidade e erradicar a influência da Aliança por todo o Contraforte de Eira dos Montes. Ela coordena ataques contra fortalezas humanas próximas, como Costa Sul, e elimina ameaças rivais, como a Camarilha, para garantir o controle inquestionável dos Renegados sobre o território.",al={"objetivos de darthalia","o que darthalia está tentando fazer","propósito de darthalia"}},f4963853={q="Por que a Alta-executora Darthalia está aqui?",a="Ela está estacionada na Serraria Tarren para supervisionar a campanha dos Renegados no Contraforte de Eira dos Montes. Desta vanguarda central, ela organiza esforços de guerra contra os assentamentos humanos hostis ao sul e garante as abordagens sul às Clareiras de Tirisfal e a Cidade Baixa.",al={"por que darthalia está na serraria tarren","por que darthalia está no contraforte de eira dos montes","motivo de darthalia estar aqui"}}},fp="23,385,24.440.0,21.364.0,31.235.0,29.129.0,29.208.0,46.198.0,51.216.0,50.207.0"}
P.entries["npc:high-executor-derrington"] = {n="Alto-executor Arcabuz",s="O Alto-executor Arcabuz comanda a vanguarda dos Renegados posicionada no Baluarte, na fronteira leste das Clareiras de Tirisfal. Um oficial militar pragmático, ele supervisiona a defesa de linha de frente da Horda contra as ameaças do Flagelo e da Cruzada Escarlate vindas das Terras Pestilentas Ocidentais. A partir dessa barricada fortificada, ele orienta campeões experientes em direção a ruínas disputadas como Andorhal e Scolomântia.",h="O Alto-executor Arcabuz comanda a vanguarda dos Renegados posicionada no Baluarte, na fronteira leste das...",kw={"andorhal","o baluarte","arcabuz","renegados","alto-executor arcabuz","flagelo","clareiras de tirisfal","terras pestilentas ocidentais"},ang={["class:Warrior"]="Arcabuz personifica a determinação sombria e prática de um soldado da linha de frente que valoriza a competência marcial e os resultados em combate mais do que intrigas da Corte.",["faction:Horde"]="Para os viajantes da Horda que chegam a Tirisfal, Arcabuz é o principal comandante militar que direciona tropas para os conflitos perigosos das Terras Pestilentas Ocidentais.",["race:Undead"]="Arcabuz representa a espinha dorsal marcial das forças militares dos Renegados, focado diretamente em proteger suas terras reconquistadas contra a retomada do Flagelo e o fanatismo Escarlate."},sec={{t="Comandante no Limiar",b="Posicionado diretamente diante das barricadas fortificadas do Baluarte, o Alto-executor Arcabuz atua como o guardião entre a segurança assombrada das Clareiras de Tirisfal e os horrores putrefatos das Terras Pestilentas Ocidentais. Arcabuz tem pouca paciência para as maquinações políticas da Cidade Baixa, encarando as linhas de frente como um crisol de pura sobrevivência. Para os soldados da Horda e mercenários que buscam testar sua coragem, Arcabuz fornece ordens militares diretas, enviando batedores e equipes de ataque para o coração do território assolado pela peste a fim de conter incursões inimigas antes que invadam Tirisfal."},{t="Uma Guerra em Duas Frentes",b="A posição defensiva de Arcabuz é cercada por múltiplos eixos. A leste jaz o Flagelo, entrincheirado na cidade destruída de Andorhal e espalhando-se pelos campos por meio de caldeirões corruptores. Simultaneamente, os fanáticos zelosos da Cruzada Escarlate disputam fortificações ao norte e combatem implacavelmente as patrulhas dos Renegados. Arcabuz coordena contra-ataques cirúrgicos, sabotagens contra as linhas Escarlates e a neutralização sistemática dos campos de caldeirões do Flagelo para proteger a fronteira leste."}},faq={{q="Quem é o Alto-executor Arcabuz?",a="O Alto-executor Arcabuz é o comandante veterano dos Renegados no Baluarte, o entreposto militar que separa as Clareiras de Tirisfal das Terras Pestilentas Ocidentais. Ele coordena o avanço estratégico da Horda para o leste contra o Flagelo e a Cruzada Escarlate.",al={"arcabuz","quem é arcabuz","história do alto-executor arcabuz"}},{q="Onde Arcabuz está localizado?",a="Ele está posicionado no Baluarte, o ponto de estrangulamento fortificado localizado no extremo leste das Clareiras de Tirisfal, ao longo da estrada que leva às Terras Pestilentas Ocidentais.",al={"onde fica arcabuz","localização de arcabuz","encontrar alto-executor arcabuz"}},{q="Qual é o objetivo de Arcabuz no Baluarte?",a="O objetivo de Arcabuz é garantir a sobrevivência dos Renegados, mantendo um forte perímetro defensivo contra o Flagelo e atacando em direção ao leste, nas Terras Pestilentas Ocidentais. Ele encarrega aventureiros de explorar Andorhal, desativar caldeirões da peste e neutralizar as operações da Cruzada Escarlate.",al={"o que arcabuz quer","propósito do baluarte","missão de arcabuz"}},{q="Arcabuz se importa com a política da Cidade Baixa?",a="Não. Arcabuz expressa desdém declarado por conspiradores e políticos da corte, destacando que tais luxos não existem nas linhas de frente, onde a sobrevivência precisa ser conquistada a cada dia.",al={"personalidade de arcabuz","arcabuz é político"}},{q="Contra quais ameaças principais Arcabuz envia soldados?",a="Arcabuz visa principalmente o Flagelo que domina as ruínas de Andorhal, os necromantes sombrios dentro de Scolomântia e as guarnições próximas da Cruzada Escarlate que ameaçam as rotas de suprimento orientais da Horda.",al={"missões de arcabuz","contra o que arcabuz luta"}},{q="Por que o Baluarte é tão fortemente fortificado?",a="O Baluarte é o principal ponto de estrangulamento entre a relativa segurança das Clareiras de Tirisfal e as zonas de combate ativas das Terras Pestilentas. As forças de Arcabuz defendem a passagem para evitar que hordas massivas do Flagelo ou investidas da Cruzada Escarlate avancem diretamente em direção à Cidade Baixa.",al={"por que o baluarte fica aqui","história do baluarte"}}},fx={["895ac470"]={q="De que lado está o Alto-executor Arcabuz?",a="O Alto-executor Arcabuz está firmemente ao lado dos Renegados e da Horda. Como um comandante militar de alto escalão sob o comando da Dama Sombria, ele se dedica a defender o reino deles e garantir seu lugar em Lordaeron contra todos que desejam vê-los erradicados.",al={"facção de arcabuz","a quem arcabuz serve","arcabuz é horda"}},e8355a95={q="Por que o Alto-executor Arcabuz está posicionado no Baluarte?",a="Arcabuz comanda a defesa da linha de frente das Clareiras de Tirisfal. Posicionado na fronteira entre as Clareiras de Tirisfal e as Terras Pestilentas Ocidentais, ele supervisiona a fortificação que impede as incursões do Flagelo e prepara o avanço dos Renegados para o leste, em direção ao coração das terras devastadas.",al={"por que arcabuz está aqui","arcabuz no o baluarte","por que arcabuz está na fronteira"}}},fp="24,400,26.575.0,19.517.0,32.252.0,28.161.0,46.293.0,46.176.0,57.199.0,40.282.0"}
P.entries["npc:high-executor-hadrec"] = {n="Alto-executor Hadrec",s="O Alto-executor Hadrec é o comandante militar da guarnição dos Renegados estacionada n'O Sepulcro, na Floresta de Pinhaprata. A partir desta cripta central, ele supervisiona a defesa contra ameaças regionais, incluindo os gnolls do clã Rot Hide, e investiga o desaparecimento de batedores pela zona. Ele atua como o principal oficial na direção das operações da Horda por toda Pinhaprata.",h="O Alto-executor Hadrec é o comandante militar da guarnição dos Renegados estacionada n'O Sepulcro, na...",kw={"os sicários","ilha de fenris","hadrec","alto-executor","rot hide","o sepulcro","bastilha da presa negra","floresta de pinhaprata"},ang={["class:Rogue"]="Hadrec depende fortemente d'Os Sicários para obter inteligência, frequentemente empregando operativos furtivos para resgatar camaradas desaparecidos e coletar o sangue viscoso e documentos do inimigo.",["faction:Horde"]="Aliados dos Renegados vindos de Kalimdor apresentam-se a Hadrec para ajudar a estabilizar Pinhaprata, aprendendo em primeira mão o quanto o domínio da Horda no norte de Lordaeron permanece frágil.",["race:Undead"]="Para os Renegados que viajam para o sul a partir de Plangemortis, Hadrec representa a voz do alto comando da Cidade Baixa, transformando mortos-vivos recém-despertos em defensores organizados de Lordaeron."},sec={{t="Comandante n'O Sepulcro",b="Estacionado na escuridão d'O Sepulcro, o Alto-executor Hadrec comanda as operações militares dos Renegados por toda a Floresta de Pinhaprata. Enquanto as Clareiras de Tirisfal estão firmemente protegidas pelas forças da Dama Sombria, Pinhaprata continua repleta de perigos, cercada por magos hostis de Dalaran, worgens ferozes e a invasão de gnolls. Hadrec carrega a sombria responsabilidade de consolidar o território dos Renegados e erradicar qualquer coisa que desafie a autoridade da Cidade Baixa ao sul da capital."},{t="O Flagelo dos Rot Hide",b="Grande parte da preocupação imediata de Hadrec gira em torno dos gnolls Rot Hide e da Ilha de Fenris. Essas feras corrompidas pelos mortos-vivos infestaram Os Campos Estéreis e as margens do Espelho de Lordaeron, representando uma ameaça imprevisível e feroz às patrulhas dos Renegados. Hadrec envia agentes para vasculhar as balsas decrépitas e fazendas apodrecidas em busca de pistas, determinar o que fortalece as feras e preparar um ataque direto contra a fortaleza insular deles."},{t="Olhos na Presa Negra",b="Além da infestação de gnolls, Hadrec monitora de perto as informações coletadas pel'Os Sicários, o braço secreto de espionagem dos Renegados. Quando agentes secretos desaparecem perto das torres sombrias da Bastilha da Presa Negra, Hadrec encarrega aventureiros de descobrir seu destino, garantindo que a Dama Sombria permaneça informada sobre o arquimago sombrio Arugal e seus worgens amaldiçoados."}},faq={{q="Quem é o Alto-executor Hadrec?",a="Hadrec é um oficial militar dos Renegados que detém o posto de Alto-executor. Ele comanda a guarnição sediada n'O Sepulcro, sendo a autoridade máxima dos Renegados sobre as operações na Floresta de Pinhaprata.",al={"história de hadrec","quem é hadrec","comandante d'o sepulcro"}},{q="Onde o Alto-executor Hadrec pode ser encontrado?",a="Ele está localizado dentro d'O Sepulcro, o assentamento dos Renegados situado no centro da Floresta de Pinhaprata, ao longo da estrada principal norte-sul.",al={"localização de hadrec","onde fica hadrec","encontrar hadrec"}},{q="Contra quais ameaças Hadrec direciona os jogadores?",a="Hadrec direciona soldados e aventureiros contra os gnolls Rot Hide que assolam Os Campos Estéreis e a Ilha de Fenris. Ele também supervisiona missões para localizar espiões d'Os Sicários desaparecidos e descobrir o que está acontecendo dentro da Bastilha da Presa Negra.",al={"missões de hadrec","o que hadrec faz","missões de pinhaprata"}},{q="O que um Alto-executor faz na estrutura militar dos Renegados?",a="Um Alto-executor é um comandante de campo de alta patente no exército dos Renegados, encarregado da supervisão estratégica total de um entreposto regional inteiro ou de uma linha de frente sob a autoridade de Grande Dama Sylvana Correventos.",al={"alto-executor renegado","posto de alto-executor","posto de hadrec"}},{q="Por que Hadrec está interessado na Ilha de Fenris?",a="A Ilha de Fenris tornou-se o covil principal dos gnolls Rot Hide. Para proteger o Espelho de Lordaeron e as vias fluviais ao redor para as linhas de suprimento dos Renegados, Hadrec coordena o reconhecimento e um eventual ataque para derrotar a liderança dos gnolls.",al={"hadrec ilha de fenris","por que atacar a ilha de fenris","rot hide fenris"}},{q="Qual é a conexão de Hadrec com a Bastilha da Presa Negra?",a="Hadrec se coordena com Os Sicários, a ordem de espionagem dos Renegados. Quando batedores enviados em direção à Bastilha da Presa Negra não retornam, Hadrec encarrega agentes de confiança de investigar a bastilha e descobrir o que aconteceu com eles.",al={"hadrec bastilha da presa negra","hadrec arugal","sicários na presa negra"}}},fx={["82ec3fb8"]={q="De que lado está o Alto-executor Hadrec?",a="O Alto-executor Hadrec serve aos Renegados e à Dama Sombria, a Rainha Sylvana Correventos, como parte da Horda. De seu posto no Sepulcro, ele comanda as operações militares dos Renegados por toda a Floresta de Pinhaprata, agindo diretamente em prol dos interesses da Cidade Baixa.",al={"facção de hadrec","a quem hadrec serve","hadrec horda"}},["3524c842"]={q="O que o Alto-executor Hadrec deseja?",a="Hadrec visa garantir a Floresta de Pinhaprata para os Renegados e proteger o flanco sul da Cidade Baixa. Ele coordena esforços para reunir inteligência sobre os movimentos inimigos, erradicar a praga dos gnolls Pata-podre que infestam a região e eliminar ameaças rivais que espreitam pela floresta, da Ilha de Fenris até os arredores da Bastilha da Presa Negra.",al={"qual é o objetivo de hadrec","motivos de hadrec","objetivos de hadrec em pinhaprata"}},ed357496={q="Por que o Alto-executor Hadrec está aqui no Sepulcro?",a="Hadrec está posicionado no Sepulcro porque ele serve como a fortaleza militar e operacional central dos Renegados na Floresta de Pinhaprata. Como Alto-executor, ele supervisiona as operações regionais, coordena os relatórios de campo dos The Deathstalkers e despacha campeões para neutralizar ameaças iminentes a fim de garantir o domínio dos Renegados sobre o território.",al={"por que hadrec está no o sepulcro","localização de hadrec em pinhaprata","por que hadrec está em pinhaprata"}},["4117c6ac"]={q="A quem o Alto-executor Hadrec está ligado?",a="Hadrec trabalha em estreita colaboração com a ala de inteligência secreta dos Renegados, os The Deathstalkers, recebendo relatórios de campo e enviando reforços para descobrir perigos ocultos. Ele também colabora com especialistas locais como o Boticário Renferrel para estudar ameaças regionais, como os gnolls Pata-podre.",al={"aliados de hadrec","conexões de hadrec","com quem hadrec trabalha"}}},fp="20,377,26.464.0,20.432.0,17.369.1,28.201.0,40.130.0,48.229.0,60.208.0,40.233.0,47.226.0"}
P.entries["npc:high-inquisitor-fairbanks"] = {n="Alto-inquisidor Fairbanks",s="O Alto-inquisidor Fairbanks já foi um reverenciado sacerdote dos Cavaleiros do Punho de Prata e um conselheiro de confiança do Grão-senhor Alexandros Mograine. Outrora um proeminente líder espiritual entre os defensores sobreviventes de Lordaeron, seu destino ficou atrelado à sombria decadência da Cruzada Escarlate.",h="O Alto-inquisidor Fairbanks já foi um reverenciado sacerdote dos Cavaleiros do Punho de Prata e um...",kw={"a crematória","catedral","fairbanks","inquisidor","mograine","renault","monastério escarlate","punho de prata","stratholme"},ang={["class:Paladin"]="Fairbanks testemunhou a hora mais sombria do Punho de Prata: o dia em que um honrado paladino voltou uma lendária lâmina sagrada contra o próprio pai.",["class:Priest"]="Antes de sua queda, Fairbanks era um sacerdote da Luz e o conselheiro mais próximo do Grão-senhor Mograine, A Crematória.",["faction:Alliance"]="A tragédia de Fairbanks remonta ao reino caído de Lordaeron, onde os remanescentes da Grande Aliança se dividiram entre zelotes e párias.",["race:Undead"]="Fairbanks comprova a suprema hipocrisia da Cruzada Escarlate: esconder um de seus próprios mortos atrás de um altar enquanto queima Renegados inocentes."},sec={{t="Conselheiro d'A Crematória",b="Antes da queda de Lordaeron, Fairbanks era um respeitado homem sagrado entre os Cavaleiros do Punho de Prata e o conselheiro de maior confiança do Grão-senhor Alexandros Mograine, o portador da lendária A Crematória. Ele esteve ao lado do Grão-senhor quando Mograine, o Alto-general Abbendis e o Grão-inquisidor Isillien fundaram a Cruzada Escarlate, a princípio uma nobre ordem que jurou destruir o Flagelo."},{t="Traição em Stratholme",b="Fairbanks acompanhou Alexandros Mograine quando o filho mais velho do Grão-senhor, Renault, os levou a uma terrível emboscada do Flagelo nos arredores de Stratholme. Fairbanks caiu cedo sob a pressão de garras de mortos-vivos, soterrado sob pilhas de cadáveres em decomposição. Desse ponto de vista estarrecedor, ele testemunhou em silêncio Renault pegar a caída Crematória e cravá-la no coração do próprio pai, corrompendo a lâmina sagrada com um parricídio. Sobrevivendo ao massacre, Fairbanks rastejou para fora de debaixo dos mortos e retornou ao Monastério Escarlate para expor a traição de Renault."},{t="Execução e Exílio",b="Os alertas desesperados de Fairbanks despedaçaram os defensores restantes de Lordaeron. Aqueles que acreditaram em seu relato estarrecedor abandonaram a ordem fanática para formar a Aurora Argêntea. Aqueles que permaneceram leais a Renault e Saidan Dathrohan rotularam Fairbanks de blasfemo e lunático. Fairbanks foi executado silenciosamente pela Cruzada Escarlate. Em vez de lhe concederem um sepultamento sagrado, os cruzados descartaram seu corpo em uma câmara oculta atrás do altar da Catedral, onde com o tempo ele se ergueu como a própria monstruosidade que juraram expurgar."}},faq={{q="Onde posso encontrar o Alto-inquisidor Fairbanks?",a="Fairbanks está escondido dentro da ala da Catedral do Monastério Escarlate. Para alcançá-lo, entre na capela lateral à direita do altar principal e puxe uma tocha de parede oculta, que abre uma porta de pedra secreta levando a uma cripta isolada.",al={"onde fica fairbanks","como encontrar fairbanks","sala secreta de fairbanks","porta secreta do monastério"}},{q="Por que Fairbanks é uma criatura morta-viva?",a="Ninguém explicou exatamente como ele se ergueu. Durante a emboscada em Stratholme, Fairbanks ficou soterrado sob pilhas de cadáveres do Flagelo e, depois que a Cruzada Escarlate o executou por suas acusações contra seus líderes, seu corpo descartado foi deixado escondido em uma câmara secreta, onde com o tempo se ergueu como um dos mortos-vivos.",al={"por que fairbanks é um zumbi","fairbanks é do flagelo","por que fairbanks é um morto-vivo"}},{q="Quem era Fairbanks antes de ser executado?",a="Fairbanks era um devoto sacerdote dos Cavaleiros do Punho de Prata e o principal conselheiro do Grão-senhor Alexandros Mograine, A Crematória. Ele era um dos líderes espirituais originais dos defensores sobreviventes de Lordaeron.",al={"história de fairbanks","quem é o alto-inquisidor fairbanks","lore de fairbanks"}},{q="O que causou a divisão entre a Cruzada Escarlate e a Aurora Argêntea?",a="Quando Fairbanks retornou de Stratholme e relatou o que tinha testemunhado lá, a ordem se fraturou. Aqueles que acreditaram em Fairbanks e rejeitaram o fanatismo de Renault se afastaram para fundar a Aurora Argêntea, enquanto os zelotes de Renault permaneceram com a Cruzada Escarlate.",al={"origem da aurora argêntea","por que a aurora argêntea se separou","fairbanks aurora argêntea"}},{q="Por que a Cruzada Escarlate matou Fairbanks?",a="A liderança da Cruzada Escarlate rotulou o testemunho dele sobre o que aconteceu em Stratholme como blasfêmia maliciosa. Os cruzados o executaram para silenciar a verdade.",al={"por que a cruzada matou fairbanks","quem matou fairbanks","execução de fairbanks"}},{q="Quem substituiu Fairbanks como Alto-inquisidor?",a="Após a execução e o aprisionamento secreto de Fairbanks, Whitemane ascendeu ao papel de Alta-inquisidora, presidindo os interrogatórios inquisitoriais do Monastério Escarlate ao lado do Comandante Renault Mograine.",al={"quem é o alto-inquisidor agora","substituto de fairbanks","quem sucedeu fairbanks"}}},fx={["14cc9219"]={q="De que lado está o Alto-inquisidor Fairbanks agora?",a="Fairbanks não pertence a nenhuma facção agora. Embora ele já tenha sido um reverenciado sacerdote da Mão de Prata e o confidente mais próximo do Grão-Lorde Alexandros Mograine, seu assassinato e subsequente ascensão na morte-viva o despojaram de sua mente e de suas antigas lealdades. Consumido pela praga da morte-viva e trancado pelos próprios fanáticos que ele um dia guiou, ele é totalmente hostil a qualquer ser vivo que entre em sua tumba escondida, atacando em agonia e loucura irracionais.",al={"facção de fairbanks","fairbanks é hostil","lado de fairbanks"}},d7d74c1e={q="Por que Fairbanks está escondido no Monastério Escarlate?",a="Depois de sobreviver à emboscada em Stratholme, Fairbanks retornou ao Monastério Escarlate e se manifestou contra os líderes da Cruzada, Renault Mograine e Saidan Dathrohan. Rotulado como herege e mentiroso, ele foi executado para que fosse silenciado. Os cruzados então descartaram seu corpo em uma câmara oculta atrás do altar da Catedral, deixando seu cadáver reanimado selado em segredo.",al={"por que fairbanks está no monastério","por que sala oculta de fairbanks","câmara secreta de fairbanks"}},edd0ed20={q="A quem o Alto-inquisidor Fairbanks estava ligado?",a="Fairbanks era o conselheiro mais próximo e companheiro do Grão-senhor Alexandros Mograine, o lendário A Crematória, e esteve ao lado dele quando Mograine, a Alta-general Abbendis e o Grão-inquisidor Isillien fundaram a Cruzada Escarlate. Ele cavalgou com Alexandros até Stratholme, e o que presenciou lá o levou a alertar os outros cavaleiros, um aviso que inspirou o cisma que fundou a Aurora Argêntea.",al={"conexões de fairbanks","fairbanks mograine","a quem fairbanks serviu"}}},fp="25,278,25.381.0,22.551.1,19.526.2,43.243.0,36.317.2,41.222.0,70.264.2,43.163.2,42.213.0"}
P.entries["npc:high-priest-rohan"] = {n="Sumo Sacerdote Rohan",s="O Sumo Sacerdote Rohan é o líder proeminente da Church of the Holy Light em Altaforja, encontrado andando pelo Salão dos Mistérios. Ele supervisiona o desenvolvimento espiritual dos sacerdotes novatos de toda a Aliança e auxilia aqueles que buscam dominar a Luz Sagrada. Por meio de sua orientação e de relíquias sagradas, ele mantém laços espirituais entre o reino da montanha, Ventobravo e aliados distantes.",h="O Sumo Sacerdote Rohan é o líder proeminente da Church of the Holy Light em Altaforja, encontrado andando...",kw={"church of the holy light","incensório de exorcismo","grayson quebrassombra","salão dos mistérios","sumo sacerdote rohan","altaforja","ala mística","instrutor de sacerdotes","rohan"},ang={["class:Paladin"]="Cavaleiros sagrados enviados pelo Lorde Grayson Quebrassombra devem visitar Rohan para obter seu famoso Incensório de Exorcismo em troca de ajuda aos necessitados de Altaforja.",["class:Priest"]="O Sumo Sacerdote Rohan oferece orientação essencial e treinamento inicial de habilidades, eventualmente direcionando você a mentores renomados em Ventobravo ou Darnassus para desbloquear devoções raciais únicas.",["faction:Alliance"]="Por meio de sua estreita cooperação com a Catedral da Luz, o Templo da Lua e o Círculo Cenariano, Rohan mantém o clero de Altaforja profundamente integrado ao restante da Aliança.",["race:Dwarf"]="Rohan personifica a devoção dos anões à Luz Sagrada, demonstrando que o povo robusto de Khaz Modan possui uma profunda convicção espiritual ao lado de sua herança dos titãs."},sec={{t="Pastor do Salão dos Mistérios",b="Percorrendo as lajes silenciosas do Salão dos Mistérios no Ala Mística, o Sumo Sacerdote Rohan atua como o representante de mais alto escalão da Church of the Holy Light em Altaforja. Embora os anões historicamente honrassem os titãs, os sacerdotes anões abraçaram profundamente as virtudes de sabedoria, compaixão e justiça da Luz. Rohan atua como um mestre paciente para jovens acólitos, ensinando-lhes a disciplina necessária para canalizar magia sagrada e fortalecer suas mentes contra o desespero."},{t="Pontes Através da Aliança",b="Rohan reconhece que a percepção espiritual assume muitas formas por toda a Aliança. Assim que os sacerdotes sob sua tutela compreendem os fundamentos, ele os direciona para fora — enviando estudantes humanos e anões para a Alta-sacerdotisa Laurena em Ventobravo, ou despachando discípulos elfos noturnos para a Sacerdotisa Alathea no Templo da Lua em Darnassus para dominar mistérios elusivos como A graça de Eluna. Além das capitais, ele exorta os devotos a prestar socorro onde quer que a adversidade se instale, chegando a encaminhar curadores para ajudar os druidas do Círculo Cenariano na distante Azshara."},{t="O Incensório de Exorcismo",b="Além de seus ensinamentos, Rohan mantém a custódia de relíquias sagradas essenciais para o sacerdócio e as irmandades de paladinos de toda a Aliança. Entre seus pertences está um abençoado Incensório de Exorcismo, forjado por anos de purificação de espíritos vis. Quando a Ordem do Punho de Prata e o Lorde Grayson Quebrassombra necessitam do receptáculo para aprimorar o chamado sagrado de seus cavaleiros, Rohan o entrega livremente — pedindo apenas esmolas de caridade para reabastecer as escassas reservas de mantimentos de Altaforja para os necessitados da cidade."}},faq={{q="Onde posso encontrar o Sumo Sacerdote Rohan?",a="O Sumo Sacerdote Rohan está localizado dentro do Salão dos Mistérios, situado no Ala Mística, na parte norte de Altaforja. Ele anda de um lado para o outro entre a biblioteca sagrada e o altar.",al={"localização de rohan","onde fica o instrutor de sacerdotes de altaforja","mapa de rohan","instrutor de sacerdotes do salão dos mistérios"}},{q="Qual é a função de Rohan em Altaforja?",a="Ele é o instrutor sênior de sacerdotes em Altaforja e o principal representante anão da Church of the Holy Light em Khaz Modan. Ele treina novos sacerdotes, oferece aconselhamento espiritual e encaminha praticantes para estudos mais avançados por toda Azeroth.",al={"quem é rohan","o que rohan faz","história de rohan"}},{q="Por que Rohan envia sacerdotes para Darnassus ou Ventobravo?",a="Rohan acredita que o crescimento espiritual requer o aprendizado com diversas tradições. Ele envia iniciados humanos e anões para a Catedral da Luz em Ventobravo para aprender preces especializadas, como Prece desesperada, e encaminha elfos noturnos de volta ao Templo da Lua de Darnassus para que possam se sintonizar com A graça de Eluna.",al={"missões de classe de rohan","prece desesperada rohan","missão do templo da lua"}},{q="Por que os paladinos procuram Rohan?",a="Paladinos enviados pelo Lorde Grayson Quebrassombra visitam Rohan para obter seu abençoado Incensório de Exorcismo. Rohan doa a relíquia para ajudar a Ordem do Punho de Prata a completar seus ritos, pedindo em troca uma doação modesta de suprimentos para alimentar os empobrecidos de Altaforja.",al={"missão de paladino rohan","incensório de exorcismo","ênfase no sacrifício"}},{q="Por que Rohan envia sacerdotes para Azshara?",a="Guiado pelos princípios de caridade e serviço da Luz, Rohan envia curadores para ajudar os druidas elfos noturnos do Círculo Cenariano que atuam nas terras selvagens e acidentadas de Azshara.",al={"ajuda cenariana rohan","rohan círculo cenariano"}},{q="Rohan treina apenas anões?",a="Rohan orienta qualquer devoto da Aliança que trilhe o caminho do sacerdócio, incluindo anões, humanos e elfos noturnos, oferecendo instrução inicial antes de encaminhá-los a mentores adequados às suas tradições específicas.",al={"humanos podem treinar com rohan","quem rohan treina"}}},fx={["077c3151"]={q="Quem é o Sumo Sacerdote Rohan?",a="O Sumo Sacerdote Rohan é o membro de mais alto escalão da Igreja da Luz Sagrada residindo em Altaforja. Um anão venerável e devoto, ele serve como o principal mentor espiritual para sacerdotes dentro do reino das montanhas, guiando noviços nos caminhos da devoção, cura e ira sagrada.",al={"quem é rohan","sumo sacerdote rohan","lore de rohan"}},["940e11c6"]={q="De que lado está o Sumo Sacerdote Rohan?",a="Rohan está firmemente ao lado do Reino de Altaforja, da Grande Aliança e da Igreja da Luz Sagrada. Ele trabalha em estreita colaboração com o clero humano em Ventobravo, os elfos noturnos de Darnassus, e até envia ajuda a grupos neutros como o Círculo Cenariano quando vidas precisam ser salvas.",al={"facção de rohan","rohan é aliança","lealdade de rohan"}},["90c6beb0"]={q="O que o Sumo Sacerdote Rohan deseja?",a="Rohan dedica-se a espalhar as virtudes da Luz Sagrada e cuidar daqueles que precisam. Ele busca cultivar sabedoria e resiliência em jovens sacerdotes, cuidar dos residentes empobrecidos de Altaforja e enviar ajuda onde quer que o sofrimento ameace vidas inocentes em toda Azeroth.",al={"o que rohan quer","objetivos de rohan","motivações de rohan"}},["88d280c0"]={q="Por que o Sumo Sacerdote Rohan está aqui no Salão dos Mistérios?",a="O Salão dos Mistérios serve como o santuário de Altaforja para estudo divino e contemplação arcana. Rohan percorre seus salões sagrados para supervisionar o bem-estar espiritual da cidade, ministrar aos suplicantes visitantes e instruir pessoalmente os sacerdotes em ascensão antes de enviá-los para o mundo.",al={"por que rohan está em altaforja","por que rohan está aqui","rohan salão dos mistérios"}}},fp="17,395,33.472.0,27.561.0,19.496.0,35.189.0,40.249.0,54.304.0,31.267.0,39.182.0,30.217.0"}
P.entries["npc:high-priestess-laurena"] = {n="Alta-sacerdotisa Laurena",s="A Alta-sacerdotisa Laurena é uma respeitada instrutora de sacerdotes humanos posicionada atrás do grande altar dentro da Catedral da Luz de Ventobravo. Ela instrui sacerdotes iniciantes da Aliança em devoção espiritual e proteções arcanas.",h="A Alta-sacerdotisa Laurena é uma respeitada instrutora de sacerdotes humanos posicionada atrás do grande...",kw={"arcane feedback","benedictus","catedral da luz","desperate prayer","alta-sacerdotisa","luz sagrada","laurena","instrutora de sacerdotes","ventobravo"},ang={["class:Priest"]="A Alta-sacerdotisa Laurena atua como uma das principais mentoras de sacerdotes de Ventobravo, guiando acólitos humanos através de provações sagradas, abençoando-os com Desperate Prayer e ensinando métodos para perturbar conjuradores inimigos.",["faction:Alliance"]="De dentro da Catedral da Luz, Laurena ajuda a fortalecer a base espiritual da Aliança, garantindo que seus campeões possam resistir à magia sombria e aos horrores mortos-vivos.",["race:Human"]="Para os humanos de Ventobravo, Laurena é um pilar espiritual da Catedral da Luz, guiando os fiéis através de tempos difíceis."},sec={{t="Uma Alta-sacerdotisa da Catedral",b="Como Alta-sacerdotisa da Igreja da Luz Sagrada, Laurena ocupa um dos cargos mais altos nos imponentes salões da Catedral da Luz, o coração da fé em Ventobravo, onde o Arcebispo Benedictus lidera a Igreja."},{t="Cuidando dos Fiéis",b="Posicionada diretamente atrás do altar central dentro do santuário da catedral, a Alta-sacerdotisa Laurena dedica-se a orientar aspirantes a sacerdote. Quando acólitos promissores demonstram dedicação e piedade suficientes, são direcionados a ela para aprofundar seus estudos. Laurena os guia na invocação de dádivas sagradas como Desperate Prayer e os instrui em artes defensivas, incluindo feitiços criados para voltar a magia arcana inimiga contra aqueles que a usam. Assim que um iniciado aprende tudo o que ela tem a oferecer, ela o envia adiante para outros mestres sacerdotes por toda a Aliança."}},faq={{q="Onde posso encontrar a Alta-sacerdotisa Laurena?",a="Ela fica atrás do altar principal dentro da Catedral da Luz, que está localizada na Praça da Catedral em Ventobravo.",al={"localização de laurena","onde fica a sacerdotisa laurena","encontrar laurena"}},{q="O que a Alta-sacerdotisa Laurena ensina?",a="Laurena é uma instrutora de sacerdotes. Ela fornece instrução fundamental para sacerdotes humanos e ensina preces raciais especializadas como Desperate Prayer, bem como proteções como Arcane Feedback para proteger contra conjuradores hostis.",al={"feitiços de laurena","instrutora de sacerdotes laurena","o que laurena ensina"}},{q="De onde veio Laurena antes de Ventobravo?",a="Nada consta sobre a vida dela antes de assumir seu posto na Catedral da Luz em Ventobravo.",al={"história de laurena","laurena é de ventobravo","laurena lordaeron"}},{q="Ela serve sob o Arcebispo Benedictus?",a="Sim. O Arcebispo Benedictus é o líder espiritual da Igreja da Luz Sagrada e preside a Catedral da Luz, onde Laurena atua como Alta-sacerdotisa.",al={"laurena e benedictus","quem é o chefe de laurena","benedictus laurena"}},{q="Por que ela me direciona para outros instrutores de sacerdotes?",a="Diferentes culturas e raças dentro da Aliança comungam com o divino de maneiras únicas. Quando Laurena ensina a seus alunos as preces fundamentais da Luz Sagrada, ela os envia para mestres sacerdotes de outras disciplinas — como mestres anões em Altaforja ou sacerdotisas elfas noturnas em Darnassus — para expandir seus horizontes espirituais.",al={"laurena me manda embora","missão a lack of fear","missão elunes grace"}},{q="Laurena perdeu sua família para os mortos-vivos?",a="Nada consta sobre a família dela.",al={"família de laurena morta","o que aconteceu com a família de laurena"}}},fx={f0ff80a5={q="De que lado está a Alta-sacerdotisa Laurena?",a="Ela é devotada inteiramente à Igreja da Luz Sagrada e à Aliança. Posicionada dentro da Catedral da Luz de Ventobravo, ela trabalha para ministrar aos fiéis do reino, nutrir novos sacerdotes e apoiar os povos sobreviventes que buscaram refúgio da devastação em toda Azeroth.",al={"lealdade de laurena","de qual facção é laurena","a quem laurena serve"}},["7a5d626d"]={q="Quem é a Alta-sacerdotisa Laurena?",a="A Alta-sacerdotisa Laurena é uma sacerdotisa veterana de destaque na Igreja da Luz Sagrada. Ela atua atrás do altar principal na Catedral da Luz em Ventobravo, orientando acólitos promissores em seus deveres sagrados.",al={"quem é laurena","identidade da alta-sacerdotisa laurena","quem é a alta-sacerdotisa laurena"}},["15a925ad"]={q="O que a Alta-sacerdotisa Laurena quer?",a="Laurena se esforça para pastorear os fiéis e preparar sacerdotes recém-dedicados para resistir à magia sombria e às ameaças que assolam Azeroth.",al={"objetivos de laurena","o que laurena está tentando fazer","motivação de laurena"}},["8a1c100b"]={q="Por que a Alta-sacerdotisa Laurena está na Catedral da Luz?",a="Como Alta-sacerdotisa da Igreja da Luz Sagrada, Laurena serve na Catedral da Luz, o coração da fé em Ventobravo, onde ela instrui iniciados promissores e ajuda a Igreja a proteger o reino.",al={"por que laurena está aqui","por que laurena está em ventobravo","por que catedral da luz laurena"}}},fp="22,214,33.231.0,20.585.0,40.123.0,39.227.0,45.104.0,43.166.0,48.338.0,42.34.0"}
P.entries["npc:highlord-demitrian"] = {n="Grão-lorde Dimitriano",s="O Grão-lorde Dimitriano é um eremita humano solitário que habita em meio aos estranhos cristais do noroeste de Silithus. Descrevendo a si mesmo como um leal servo do Príncipe Thunderaan, ele possui o conhecimento esotérico necessário para despertar o senhor elemental adormecido. Aventureiros que portam antigos grilhões elementais o procuram para liberar o poder do Perseguidor dos Ventos.",h="O Grão-lorde Dimitriano é um eremita humano solitário que habita em meio aos estranhos cristais do noroeste...",kw={"vale de cristal","dimitriano","grão-lorde dimitriano","silithus","thunderaan","fúria dos ventos","casulo de renascimento","perseguidor dos ventos"},ang={["class:Rogue"]="Ladinos em busca da lâmina lendária do Perseguidor dos Ventos devem negociar com Dimitriano em Silithus para restaurar o príncipe despedaçado.",["class:Warrior"]="Guerreiros em busca da lâmina lendária Fúria dos Ventos devem procurar Dimitriano para iniciar a provação de desatar e despertar o Perseguidor dos Ventos.",["profession:Blacksmithing"]="As exigências de Dimitriano para o renascimento de Thunderaan requerem vasta maestria em ferraria para forjar Barras de Elemêntio Encantado a partir de minério bruto e essências ígneas."},sec={{t="Eremita do Vale de Cristal",b="Encontrado vagando por um acampamento abandonado no Vale de Cristal, Dimitriano parece fora de lugar nos ermos desolados de Silithus. Embora esteja ligado ao Martelo do Crepúsculo, cujo acampamento arrasado ele assombra, Dimitriano atua acima de tudo como um arauto do Príncipe Thunderaan, o Perseguidor dos Ventos. Ele trata os visitantes com indiferença distante, a menos que tragam uma prova da essência despedaçada do Perseguidor dos Ventos."},{t="O Casulo de Renascimento",b="O propósito de Dimitriano está inteiramente atrelado à ressurreição de Thunderaan. Se um aventureiro lhe apresentar os Grilhões do Perseguidor dos Ventos — relíquias arrancadas de elementais do fogo dentro do Núcleo Derretido —, Dimitriano fornece o Casulo de Renascimento. Ele exige reagentes elementais raros, incluindo vastas quantidades de elemêntio encantado e a essência do Senhor do Fogo, para reconstituir a forma física de seu príncipe."},{t="A Traição do Perseguidor dos Ventos",b="O ritual de Dimitriano traz o Príncipe Thunderaan ao Vale de Cristal, onde os aventureiros devem enfrentar o Perseguidor dos Ventos restaurado em combate. Uma vez que derrotam o senhor elemental, eles recuperam a Lâmina Latente Beijada pelo Vento e a levam ao aterrorizado Dimitriano, que desperta Fúria dos Ventos em troca."}},faq={{q="Onde posso encontrar o Grão-lorde Dimitriano?",a="Ele fica no extremo noroeste de Silithus, perto do Acampamento Arrasado do Crepúsculo, dentro do Vale de Cristal.",al={"localização de dimitriano","onde fica dimitriano","local de dimitriano em silithus"}},{q="Por que Dimitriano só dá uma resposta genérica?",a="Dimitriano não oferecerá sua série lendária de missões a menos que você esteja carregando ao menos uma metade dos Grilhões do Perseguidor dos Ventos, que são tesouros raros mantidos pelo Barão Geddon e Garr no Núcleo Derretido.",al={"dimitriano não fala comigo","como pegar a missão de dimitriano","diálogo de dimitriano"}},{q="Qual é a relação de Dimitriano com o Príncipe Thunderaan?",a="Dimitriano é o servo mortal jurado do Príncipe Thunderaan. Ele se dedicou a encontrar os grilhões rompidos do príncipe e a restaurar o senhor elemental ao plano físico.",al={"a quem dimitriano serve","relação entre dimitriano e thunderaan","dimitriano é do martelo do crepúsculo"}},{q="O que acontece quando você leva todos os materiais para o casulo a ele?",a="Dimitriano realiza um ritual que invoca o Príncipe Thunderaan no Vale de Cristal, restaurando o Perseguidor dos Ventos ao plano físico.",al={"invocando thunderaan","o que dimitriano faz com o casulo","invocação no vale de cristal"}},{q="Dimitriano é afiliado ao culto do Martelo do Crepúsculo?",a="Ele tem laços com o Martelo do Crepúsculo e habita no acampamento arrasado deles, além de falar dos Deuses Antigos com reverência. Ainda assim, sua devoção jurada é ao seu mestre, o Príncipe Thunderaan.",al={"dimitriano é um cultista","acampamento do crepúsculo de dimitriano","facção de dimitriano"}},{q="Como você obtém Fúria dos Ventos dele?",a="Leve a ele ambas as metades dos Grilhões do Perseguidor dos Ventos, obtidas com o Barão Geddon e Garr no Núcleo Derretido, e então reúna os materiais raros que ele exige para o Casulo de Renascimento. O que o ritual dele desencadeia, e como a lâmina é finalmente despertada, é narrado nas seções de spoiler.",al={"como conseguir fúria dos ventos","conclusão da missão de fúria dos ventos","lâmina de dimitriano"}}},fp="18,351,26.385.0,21.400.1,26.289.1,36.122.0,48.202.0,54.181.0,65.133.1,56.178.0,36.277.1"}
P.entries["npc:hogger"] = {n="Hogger",s="Hogger é o cruel chefe dos gnolls Riverpaw que espreitam o sudoeste da Floresta de Elwynn. Muito mais alto que seus semelhantes e extremamente agressivo, ele se tornou notório por saquear fazendas locais e massacrar viajantes desavisados. Seus ataques violentos lhe renderam uma recompensa oficial dos oficiais de Ventobravo.",h="Hogger é o cruel chefe dos gnolls Riverpaw que espreitam o sudoeste da Floresta de Elwynn.",kw={"recompensa","défias","durão","elwynn","gnoll","vila d'ouro","hogger","riverpaw"},ang={["faction:Alliance"]="As incursões de Hogger demonstram como o exército de Ventobravo está sobrecarregado, forçando os oficiais a depender de aventureiros itinerantes para manter a ordem perto da capital.",["race:Human"]="Para os jovens defensores de Ventobravo, confrontar Hogger é uma prova de fogo inicial e uma resposta direta às ameaças que desestabilizam o coração de Elwynn."},sec={{t="Terror dos Riverpaw",b="Espreitando no topo de Hogger Hill, no sudoeste da Floresta de Elwynn, Hogger comanda a matilha local dos Riverpaw com uma selvageria sem igual. Nos anos que se seguiram à Terceira Guerra, as incursões dos gnolls pelas propriedades locais tornaram-se cada vez mais ousadas e coordenadas. Por trás desse aumento da violência reside uma aliança inquietante: os Riverpaw começaram a conspirar com a Irmandade Défias, trocando ferocidade pura por armas, direcionamento tático e apoio mágico. Para proteger as fronteiras de Elwynn e resguardar as rotas comerciais de novos derramamentos de sangue, o Delegado Durão colocou uma recompensa generosa pela cabeça de Hogger."}},faq={{q="Quem é Hogger?",a="Hogger é um gnoll enorme e excepcionalmente perigoso que lidera a matilha Riverpaw no sudoeste da Floresta de Elwynn. Conhecido por saquear fazendas próximas, ele é procurado morto pelas autoridades de Ventobravo devido aos seus ataques brutais a assentamentos humanos.",al={"história de hogger","quem é hogger","líder riverpaw"}},{q="Por que há uma recompensa por Hogger?",a="O Delegado Durão e a guarda de Ventobravo emitiram uma recompensa oficial por Hogger devido às suas crescentes incursões contra fazendas rurais e viajantes. Qualquer um com coragem suficiente para pôr fim à sua fúria deve levar sua garra enorme de volta a Vila d'Ouro como prova do feito.",al={"procura-se hogger","por que matar hogger","recompensa de hogger"}},{q="Os gnolls Riverpaw estão trabalhando com a Irmandade Défias?",a="Sim. A Irmandade Défias tem conspirado com a matilha Riverpaw, fornecendo aos gnolls brutais armamento refinado, orientação tática e apoio místico para desestabilizar ainda mais o controle de Ventobravo sobre a região.",al={"hogger défias","conexão gnoll défias","riverpaw défias"}},{q="Onde Hogger monta seu acampamento?",a="Hogger reside no topo de Hogger Hill, nos confins do sudoeste da Floresta de Elwynn, cercado por seus leais companheiros de matilha Riverpaw perto da fronteira de Cerro Oeste.",al={"localização de hogger","onde fica hogger","hogger hill"}}},fx={cd1f1084={q="De que lado está Hogger?",a="Hogger lidera os gnolls Pata-podre do sul da Floresta de Elwynn, mas sua matilha não age sozinha. Eles estão conspirando com a The Defias Brotherhood, trocando caos na floresta por armas, liderança tática e assistência arcana. Embora os gnolls lutem principalmente por saques e território, a aliança de Hogger com a The Defias Brotherhood alinha sua matilha diretamente contra o reino de Ventobravo e seu povo.",al={"lado de hogger","para quem hogger trabalha","com quem hogger está aliado"}},["3ddc17ac"]={q="Por que Hogger está na Floresta de Elwynn?",a="Hogger estabeleceu sua fortaleza em uma colina no sudoeste da Floresta de Elwynn para supervisionar a expansão agressiva de sua matilha. Deste acampamento, os gnolls Pata-podre atacam fazendas e assentamentos humanos próximos, capitalizando sobre as defesas esticadas do reino enquanto coordenam sob a influência e o apoio da The Defias Brotherhood.",al={"por que hogger está aqui","razão de hogger na floresta de elwynn","por que hogger veio aqui"}},d88533c5={q="Por que Hogger é tão temido?",a="Hogger é temido por toda a Floresta de Elwynn por sua força cruel e liderança astuta. Diferente dos gnolls errantes comuns, ele é um chefe excepcionalmente formidável que facilmente domina viajantes solitários e aventureiros inexperientes. Seus ataques contra propriedades locais mostraram-se tão destrutivos que os Marechais de Ventobravo o consideram uma ameaça prioritária ao reino.",al={"por que hogger é famoso","por que hogger é temido","por que hogger é notório"}}},fp="6,312,22.569.0,14.234.0,32.237.0,60.218.0,32.149.0"}
P.entries["npc:holt-thunderhorn"] = {n="Holto Chifre Troante",s="Holto Chifre Troante é um instrutor de caçadores tauren posicionado no Platô dos Caçadores na cidade elevada de Penhasco do Trovão. Ele instrui caçadores novatos e experientes em seu ofício, oferecendo orientação marcial básica e encaminhando atiradores em desenvolvimento para testes especializados em Mulgore e além.",h="Holto Chifre Troante é um instrutor de caçadores tauren posicionado no Platô dos Caçadores na cidade elevada...",kw={"holto chifre troante","platô dos caçadores","instrutor de caçadores","mulgore","penhasco do trovão"},ang={["class:Hunter"]="Holto Chifre Troante serve como um mentor central em Penhasco do Trovão, oferecendo técnicas de armas, treinamento de rastreamento e encaminhamentos para a domesticação de feras.",["race:Tauren"]="Posicionado no Platô dos Caçadores, Holto personifica a cultura tradicional de caça dos tauren que alimentou e protegeu as tribos nômades muito antes de estabelecerem um lar permanente no topo dos penhascos."},sec={{t="Mestre do Platô",b="Empoleirado no Platô dos Caçadores acima das vastas planícies de Mulgore, Holto Chifre Troante serve a Horda como um instrutor experiente em combate à distância, rastreamento e sobrevivência. Como muitos anciãos de seu ofício, ele guia jovens tauren conforme fazem a transição de caçadores nômades para defensores disciplinados de sua nova capital."}},faq={{q="Onde Holto Chifre Troante pode ser encontrado?",a="Holto Chifre Troante fica no Platô dos Caçadores, o planalto elevado no sudeste dentro da capital tauren de Penhasco do Trovão em Mulgore.",al={"localização de holto chifre troante","onde está holto","instrutor de caçadores penhasco do trovão"}},{q="O que Holto Chifre Troante ensina?",a="Ele é um instrutor de caçadores que instrui jogadores em técnicas essenciais de pontaria, sobrevivência na natureza e domesticação de feras, além de direcionar novatos para testes especializados de domínio das feras.",al={"o que holto ensina","instrutor holto chifre troante","quais habilidades holto"}},{q="Qual o papel dos caçadores em Penhasco do Trovão?",a="Os caçadores formam a espinha dorsal tradicional da sociedade tauren, provendo sustento, patrulhando as fronteiras territoriais contra grupos de ataque centauros e honrando a Mãe Terra por meio de um rastreamento equilibrado e reverente.",al={"propósito do platô dos caçadores","história dos caçadores tauren"}}},fx={c3f17fe5={q="Quem é Holto Chifre Troante?",a="Holto Chifre Troante é um respeitado treinador de caçadores tauren, estacionado no Platô dos Caçadores no Penhasco do Trovão. Dedicado a transmitir as artes selvagens dos shu'halo, ele instrui jovens caçadores em pontaria, sobrevivência e o antigo vínculo entre caçador e fera.",al={"quem é holto","história de holto chifre troante","quem é holto chifre troante"}},d59405da={q="De que lado está Holto Chifre Troante?",a="Holto serve as tribos tauren do Penhasco do Trovão e a Horda maior sob a liderança de Caerne Casco Sangrento. Ele ajuda qualquer caçador leal à Horda que busque aguçar seus instintos e honrar as planícies.",al={"facção de holto chifre troante","a quem holto serve","holto é da horda"}},["03eb281d"]={q="Por que Holto Chifre Troante está aqui?",a="Holto permanece no topo do Platô dos Caçadores para orientar novas gerações de rastreadores, atiradores e mestres das feras. Com os tauren agora estabelecidos em Mulgore, caçadores habilidosos são essenciais para sustentar a cidade e proteger as mesas da vida selvagem hostil e dos invasores.",al={"por que holto está no penhasco do trovão","o que holto está fazendo aqui","propósito de holto chifre troante"}}},fp="16,288,18.313.0,36.128.0,33.187.0,43.209.0"}
P.entries["npc:houndmaster-loksey"] = {n="Mestre de Matilha Lobato",s="O Mestre de Matilha Lobato é o oficial encarregado de criar e treinar os temíveis cães de guerra da Cruzada Escarlate. Posicionado na ala da Library do Monastério Escarlate, ele comanda matilhas de cães de caça para perseguir mortos-vivos, invasores e supostos hereges. Sua disciplina implacável tornou as feras do Monastério infames por todas as Clareiras de Tirisfal.",h="O Mestre de Matilha Lobato é o oficial encarregado de criar e treinar os temíveis cães de guerra da Cruzada...",kw={"library","mestre de matilha lobato","cães de caça","huntsman leopold","canis","lobato","cruzada escarlate","monastério escarlate"},ang={["class:Hunter"]="Lobato exemplifica uma abordagem brutal e agressiva no treinamento de feras, dobrando cães ferozes à obediência ao fanatismo em vez de forjar um laço de respeito mútuo.",["race:Undead"]="Invasores Renegados devem ter cuidado com os cães de caça de Lobato, que são treinados especificamente para captar o cheiro de carne morta e alertar as guarnições da Cruzada."},sec={{t="Mestre dos Canis",b="Dentro das muralhas pesadamente fortificadas do Monastério Escarlate, o Mestre de Matilha Lobato comanda o treinamento de cães ferozes de ataque e rastreamento. A Cruzada Escarlate depende desses cães de caça treinados para farejar cadáveres infectados pela praga, descobrir infiltradores ocultos e abater quaisquer sobreviventes que fujam da ira dos fanáticos. Lobato detém autoridade absoluta sobre os cães de caça que guardam a ala da Library, garantindo que seus subordinados estejam preparados para despedaçar invasores membro por membro."},{t="Rivalidade Familiar",b="Lobato não é o único tratador de feras de sua família servindo à causa. Seu irmão, Huntsman Leopold, atua como o emissário da Cruzada Escarlate junto à Aurora Argêntea na Capela Esperança da Luz. Leopold tem uma opinião desfavorável a respeito de seu irmão, afirmando em particular que Lobato mal consegue controlar os próprios cães de caça, quanto mais representar a ordem em assuntos diplomáticos de alto risco. Apesar do desdém de Leopold, Lobato continua sendo um oficial fundamental dentro da hierarquia interna do Monastério."}},faq={{q="Onde o Mestre de Matilha Lobato pode ser encontrado?",a="O Mestre de Matilha Lobato localiza-se dentro da ala da Library do Monastério Escarlate, no nordeste das Clareiras de Tirisfal, cercado por seus cães de ataque.",al={"localização de lobato","onde fica lobato","localização do mestre de matilha lobato"}},{q="Qual função Lobato desempenha na Cruzada Escarlate?",a="Ele é o chefe dos tratadores de animais e mestre de matilha da Cruzada Escarlate no Monastério, responsável pela criação, condicionamento e comando dos cães de guerra usados para farejar mortos-vivos e caçar invasores.",al={"o que faz lobato","função de lobato","dever do mestre de matilha"}},{q="Quem é Huntsman Leopold para Lobato?",a="Huntsman Leopold é irmão de Lobato. Leopold representa a Cruzada Escarlate na Capela Esperança da Luz e menospreza Lobato, afirmando que Lobato não consegue controlar adequadamente os próprios cães de caça nem lidar com responsabilidades diplomáticas.",al={"irmão de leopold lobato","quem é leopold","irmão de lobato"}},{q="Por que a Cruzada Escarlate usa cães de caça?",a="A Cruzada treina cães de caça ferozes para rastrear o Flagelo e os Renegados pelo faro, bem como para guardar os terrenos do Monastério e despedaçar inimigos em fuga.",al={"por que cães","propósito dos cães de caça escarlates","cães da cruzada"}},{q="Lobato é considerado um líder do Monastério Escarlate?",a="Sim, Lobato é reconhecido como uma das figuras de comando fundamentais na estrutura militar do Monastério Escarlate, supervisionando os cães de guerra da Cruzada na ala da Library.",al={"lobato é um chefe","posto de lobato","quão importante é lobato"}},{q="Os cães de caça são perigosos por conta própria?",a="Sim. Criados para a agressividade e condicionados por Lobato, os cães de guerra do Monastério são predadores ferozes capazes de despedaçar um invasor de armadura em instantes.",al={"os cães são fortes","perigo dos cães de caça escarlates","mascotes de lobato"}}},fx={["92e01b8b"]={q="Quem é Mestre de Matilha Lobato?",a="Mestre de Matilha Lobato é um capitão humano e um dos quatro comandantes que residem no Monastério Escarlate. Renomado por sua disciplina brutal, ele serve como o mestre de canil responsável por criar, condicionar e soltar os cães cruéis da The Scarlet Crusade contra intrusos e supostos portadores da corrupção dos mortos-vivos.",al={"quem é lobato","identidade do mestre de matilha lobato","quem é mestre de matilha lobato"}},["6cbd929d"]={q="De que lado está Mestre de Matilha Lobato?",a="Lobato é estritamente devoto à The Scarlet Crusade, servindo como um comandante de linha de frente dentro de sua fortaleza no monastério. Ele compartilha o ódio fanático da Cruzada pelos mortos-vivos e qualquer pessoa fora de sua ordem zelota, vendo qualquer um que invada seus corredores como intrusos aptos apenas para alimentar seu canil.",al={"facção de lobato","mestre de matilha lobato é da aliança","a quem lobato serve"}},["1361b0af"]={q="O que Mestre de Matilha Lobato quer?",a="Lobato visa defender o Monastério Escarlate treinando matilhas de caça impiedosas capazes de despedaçar qualquer inimigo membro por membro. Ele quer eliminar cada vestígio dos mortos-vivos e proteger o território da Cruzada contra forasteiros, usando suas feras para caçar intrusos sem hesitação ou misericórdia.",al={"objetivo de lobato","o que lobato está tentando fazer","motivo do mestre de matilha lobato"}},["58572016"]={q="Por que Mestre de Matilha Lobato está aqui?",a="Lobato está estacionado na ala da Library do Monastério para supervisionar os canis da Cruzada. Como mestre de matilha, ele deve garantir que os cães permaneçam afiados, agressivamente condicionados e prontos para serem soltos a qualquer momento para patrulhar os terrenos e massacrar intrusos.",al={"por que lobato está no monastério","por que o mestre de matilha lobato está aqui","propósito de lobato"}},["264719ea"]={q="Por que Mestre de Matilha Lobato é famoso ou temido?",a="Lobato é temido por sua matilha de cães treinados, feras conhecidas por dominar e despedaçar vítimas em minutos. Qualquer pessoa que se aventure no monastério teme encontrar seu canil, sabendo que o comando cruel de Lobato transforma seus animais em máquinas implacáveis de carnificina.",al={"por que lobato é temido","reputação de lobato","por que mestre de matilha lobato é perigoso"}}},fp="18,342,21.455.0,14.441.0,38.142.0,51.205.0,34.214.0,40.167.0,55.170.0,38.165.0"}
P.entries["npc:huldar"] = {n="Huldar",s="Huldar é um carroceiro anão posicionado ao longo da estrada sul de Loch Modan, perto das margens do lago. Encarregado de transportar pólvora vital para o sítio de escavação no sul, sua caravana de suprimentos enfrenta o assédio constante de ameaças locais e sabotadores Ferro Negro.",h="Huldar é um carroceiro anão posicionado ao longo da estrada sul de Loch Modan, perto das margens do lago.",kw={"pólvora","caravana","ferro negro","escavação","huldar","loch modan","carroça"},ang={["profession:Engineering"]="Qualquer engenheiro conhece o valor — e a volatilidade — da pólvora pura deixada exposta em barris de madeira encalhados.",["race:Dwarf"]="Ajudar Huldar apoia diretamente o sítio de escavação da Liga dos Exploradores, garantindo que o seu povo tenha a pólvora necessária para desenterrar antigos segredos titânicos."},sec={{t="Um Transporte de Pólvora em Perigo",b="Transportar explosivos por Loch Modan não é uma rota comercial simples. Huldar foi incumbido de conduzir carroças cheias de pólvora de mineração em direção ao sítio de escavação ao sul, onde arqueólogos e garimpeiros anões precisam desesperadamente de suprimentos. No entanto, as estradas ermas tornaram-se cada vez mais perigosas. Com a fauna local, troggs e infiltrados Ferro Negro à espreita perto da curva sul do lago, Huldar encontra-se encalhado junto à sua carroça danificada, dependendo de viajantes para proteger os barris de pólvora restantes e garantir que a remessa chegue à escavação."}},faq={{q="Quem é Huldar?",a="Huldar é um carroceiro anão encalhado junto à sua carroça na margem sul do lago em Loch Modan. Ele foi incumbido de transportar pólvora para o sítio de escavação próximo antes que sua viagem de suprimentos enfrentasse problemas.",al={"quem é huldar","huldar loch modan","anão da carroça"}},{q="O que há na carroça de Huldar?",a="Sua carroça carrega barris de pólvora. Os explosivos são desesperadamente necessários para garimpeiros e arqueólogos anões trabalhando no sítio de escavação ao sul.",al={"o que huldar está transportando","carga da carroça de huldar","o que são os barris"}},{q="Por que Huldar está preso na estrada?",a="As estradas pelo sul de Loch Modan tornaram-se perigosas devido a feras hostis, troggs e sabotadores anões Ferro Negro. A remessa de Huldar foi emboscada, forçando-o a parar e buscar ajuda para proteger e entregar os suprimentos restantes.",al={"por que huldar está encalhado","emboscada a huldar"}},{q="Por que os anões Ferro Negro se importam com a carga dele?",a="O clã Ferro Negro busca ativamente minar a presença de Altaforja e a pesquisa histórica por toda Loch Modan. Cortar a pólvora interrompe os esforços de escavação e priva as operações dos anões de suprimentos defensivos e industriais.",al={"pólvora ferro negro","por que os ferro negro atacam huldar"}}},fx={ff7033f4={q="De que lado está Huldar?",a="Huldar é leal a Altaforja e à Aliança. Ele trabalha diretamente a serviço dos prospectores e mineiros anões operando em Loch Modan, transportando munições essenciais pelo território enquanto se mantém firme contra o clã hostil Dark Iron que se infiltra na região.",al={"huldar é da aliança","a quem huldar serve","facção de huldar"}},["9f03f8e3"]={q="O que Huldar quer?",a="Huldar quer entregar sua carga de pólvora explosiva em segurança no local de escavação anão. Anões Dark Iron emboscaram sua caravana ao longo da estrada sul de Loch, deixando-o precisando de viajantes valentes para proteger a carga e repelir os sabotadores.",al={"o que huldar está tentando fazer","objetivo de huldar","o que huldar precisa"}},["577cb64e"]={q="A quem Huldar está ligado?",a="Huldar está ligado aos escavadores anões estacionados em Loch Modan. Sua equipe tem a tarefa de transportar suprimentos vitais e pólvora explosiva diretamente para seus locais de escavação, garantindo que suas operações possam continuar apesar da crescente ameaça de incursões dos Dark Iron.",al={"para quem huldar trabalha","conexões de huldar","a quem huldar está fornecendo"}}},fp="6,268,21.566.0,14.208.0,26.167.0,32.232.0,50.234.0"}
P.entries["npc:illiyana"] = {n="Iliana",s="Iliana é uma dríade anciã posicionada no sudoeste de Vale Gris, dedicada a proteger a floresta da corrupção ancestral. Vagando perto do Altar de Aessina, ela reúne campeões da Aliança para repelir os sátiros cruéis que assolam os bosques antigos. Sua vigilância representa o vínculo duradouro entre as filhas de Cenarius e a natureza selvagem dos elfos noturnos.",h="Iliana é uma dríade anciã posicionada no sudoeste de Vale Gris, dedicada a proteger a floresta da corrupção...",kw={"vale gris","ramo de cenarius","cenarius","dríade","iliana","sátiro","altar de aessina"},ang={["class:Druid"]="Druidas têm grande apreço pelas dríades como personificações do estado selvagem, e ajudar Iliana a preservar as clareiras santificadas alinha-se diretamente ao dever cenariano de curar a terra.",["faction:Alliance"]="Iliana representa uma aliada florestal vital no sudoeste de Vale Gris, oferecendo abrigo e orientação às forças da Aliança que protegem a natureza contra os males invasores.",["race:NightElf"]="Para os Kaldorei, dríades como Iliana são parentes sagradas de Cenarius, protetoras reverenciadas cujo chamado às armas contra os sátiros demoníacos é atendido sem hesitação."},sec={{t="Filha da Floresta",b="Como todas as dríades, Iliana é uma das filhas do semideus Cenarius. Pacífica, mas ferozmente protetora das terras selvagens, ela patrulha os bosques do sudoeste de Vale Gris. À medida que forças sombrias se agitam e as florestas sofrem sob uma corrupção rastejante, Iliana vigia relíquias e bosques sagrados, atuando como guardiã da santidade primordial da natureza."},{t="A Ameaça dos Sátiros",b="A principal preocupação de Iliana na região é a praga persistente dos sátiros. Essas criaturas demoníacas e retorcidas buscam continuamente corromper as clareiras e colocar em perigo suas irmãs dríades. Iliana frequentemente recruta viajantes que passam por ali para abater essas abominações vis e recuperar artefatos perdidos, incluindo o Ramo de Cenarius, para garantir que os bosques permaneçam protegidos da mácula demoníaca."}},faq={{q="Quem é Iliana?",a="Iliana é uma dríade encontrada perambulando pelo sudoeste de Vale Gris, perto do Altar de Aessina. Como filha de Cenarius, ela dedica sua existência a vigiar as terras selvagens e a proteger suas irmãs de forças demoníacas.",al={"quem é esta dríade","iliana vale gris","o que é iliana"}},{q="Por que Iliana continua andando enquanto falo com ela?",a="Iliana mantém uma rota de patrulha ativa pela floresta. Ao contrário de concedentes de missões estacionários, ela continua seu passo vigilante pelo bosque mesmo ao conversar com viajantes.",al={"iliana em movimento","por que ela se afasta","missão iliana andando"}},{q="Quais tarefas Iliana oferece?",a="Ela conclama aventureiros a caçar sátiros vis que ameaçam a região e a recuperar relíquias sagradas como o Ramo de Cenarius para proteger suas companheiras dríades.",al={"missões de iliana","missões de cantilenda"}},{q="Onde Iliana está localizada?",a="Ela patrulha perto do Altar de Aessina, no sudoeste de Vale Gris, vigiando os caminhos e os bosques próximos.",al={"localização de iliana","onde encontrar iliana","localização da dríade de cantilenda"}},{q="Por que as dríades estão em perigo por causa dos sátiros?",a="Sátiros são antigos elfos noturnos deformados pela corrupção demoníaca que têm prazer em profanar a natureza e subjugar os filhos de Cenarius. As dríades representam a beleza pura e imaculada da floresta, tornando-se alvos primordiais para a malícia dos sátiros.",al={"por que os sátiros odeiam dríades","história de dríades e sátiros"}},{q="Iliana ajuda a Horda?",a="Não. Iliana é aliada dos Elfos Noturnos e da Aliança como um todo. Integrantes da Horda que se aventurarem em sua clareira encontrarão ela e seus aliados hostis.",al={"iliana é hostil à horda","a horda pode falar com iliana"}}},fx={f493742a={q="O que Iliana quer?",a="Iliana é dedicada a proteger o Vale Gris e suas companheiras dríades da influência corruptora dos sátiros. Ela busca bravos campeões da Aliança para caçar os sátiros perversos escondidos nas proximidades, defender os bosques sagrados e ajudar a recuperar o The Branch of Cenarius para purificar a floresta.",al={"objetivo de iliana","o que iliana quer","propósito de iliana"}},["925d87c3"]={q="Por que Iliana está no Altar de Aessina?",a="Iliana vigia o Altar de Aessina no sudoeste do Vale Gris, um santuário querido pelos espíritos da floresta e pelas filhas de Cenarius. Deste solo sagrado, ela monitora a corrupção crescente dos sátiros e coordena esforços de defesa com aliados elfos noturnos e da Aliança.",al={"por que iliana está aqui","iliana altar de aessina","por que iliana está no vale gris"}},abbc4abe={q="A quem Iliana está ligada?",a="Como dríade, Iliana é uma das filhas do semideus Cenarius, compartilhando um profundo parentesco espiritual e familiar com suas irmãs dríades, como Shael'dryn, e os guardiões do bosque. Ela também compartilha fortes laços com os elfos noturnos que veneram Aessina e Cenarius.",al={"laços de iliana","iliana cenarius","com quem iliana é relacionada"}}},fp="8,384,22.345.0,23.388.0,16.218.0,51.198.0,31.163.0,26.114.0,41.230.0,29.146.0"}
P.entries["npc:illiyana-moonblaze"] = {n="Iliana Fulgiluna",s="Iliana Fulgiluna é uma oficial de suprimentos elfa noturna destacada no Bosque Asa de Prata, em Vale Gris. Atuando ao lado das Sentinelas da Asa de Prata, ela abastece os campeões da Aliança que travam guerra contra os Pioneiros do Brado Guerreiro.",h="Iliana Fulgiluna é uma oficial de suprimentos elfa noturna destacada no Bosque Asa de Prata, em Vale Gris.",kw={"vale gris","pacote de suprimentos","iliana fulgiluna","sentinela","bosque asa de prata","ravina brado guerreiro"},ang={["faction:Alliance"]="Para os combatentes da Aliança que marcham para o sul em direção à fronteira disputada da Ravina Brado Guerreiro, Iliana é a principal intendente que fornece armas, armaduras e rações.",["race:NightElf"]="Iliana mantém as Sentinelas da Asa de Prata abastecidas, mostrando como os kaldorei mobilizam todas as forças para proteger Vale Gris."},sec={{t="Oficial de Suprimentos de Silverwing",b="Iliana Fulgiluna atua como oficial de suprimentos das Sentinelas da Asa de Prata instaladas no Bosque Asa de Prata. De seu posto perto do caminho para a Ravina Brado Guerreiro, ela equipa os defensores que defendem os bosques do sul de Vale Gris contra o clã Warsong."},{t="Suprimentos para a Linha de Frente",b="Além de manter os estoques do bosque, Iliana equipa voluntários da Aliança que se preparam para enfrentar o clã Warsong na Ravina Brado Guerreiro. Conforme os campeões conquistam prestígio com as Sentinelas da Asa de Prata, ela recompensa o serviço deles com rações personalizadas, poções especializadas e armamentos de obra-prima projetados especificamente para escaramuças na floresta. Ela também realiza a manutenção de armas e armaduras para os combatentes cansados que retornam da linha de frente, mantendo o esforço de guerra das Sentinelas abastecido e funcional."}},faq={{q="Onde posso encontrar Iliana Fulgiluna?",a="Ela está localizada no Bosque Asa de Prata, no sudeste de Vale Gris, perto da área de preparação e do portal que leva à Ravina Brado Guerreiro.",al={"localização de iliana fulgiluna","onde fica iliana","localização do intendente de silverwing"}},{q="Iliana Fulgiluna é membro das Sentinelas?",a="Ela atua como Oficial de Suprimentos de Silverwing, trabalhando ao lado das Sentinelas da Asa de Prata para equipar e abastecer os campeões da Aliança que lutam ao lado delas.",al={"iliana é uma sentinela","posto de iliana","facção de iliana"}},{q="O que Iliana oferece aos campeões da Aliança?",a="Ela atua como intendente das Sentinelas da Asa de Prata, oferecendo pacotes de suprimentos, armamentos de campo de batalha, anéis, tabardos e consumíveis adaptados para a luta na Ravina Brado Guerreiro àqueles que obtêm reputação com a facção.",al={"o que iliana vende","recompensas da ravina brado guerreiro vale gris","vendedora iliana"}},{q="Ela oferece reparo de equipamentos?",a="Sim, além de fornecer equipamentos militares especializados, ela oferece serviços padrão de reparo de armas e armaduras para os defensores da Aliança que descansam no bosque.",al={"iliana faz reparos","vendedor de reparos de silverwing","reparo no bosque asa de prata"}},{q="Quais pacotes de suprimentos ela distribui?",a="Ela ajuda os combatentes da Aliança por meio de missões logísticas envolvendo Sentinel Basic, Standard, and Advanced Care Packages, abastecendo os defensores da linha de frente com provisões essenciais de campo de batalha.",al={"pacote de suprimentos de sentinela","missões de iliana","pacotes da ravina brado guerreiro"}}},fx={["4fdd1f70"]={q="Quem é Iliana Fulgiluna?",a="Iliana Fulgiluna é uma oficial de suprimentos elfa noturna destacada no Bosque Asa de Prata no Vale Gris. Atuando ao lado das Sentinelas da Asa de Prata como sua fornecedora, ela equipa e abastece os campeões da Aliança que lutam na Ravina Brado Guerreiro.",al={"quem é iliana","história de iliana fulgiluna","quem é iliana fulgiluna"}},ebeca23e={q="De que lado Iliana Fulgiluna está?",a="Iliana é firmemente alinhada com a Aliança e com as Sentinelas da Asa de Prata. Ela se dedica a suprir os defensores do Vale Gris contra as incursões da Horda na Ravina Brado Guerreiro.",al={"facção de iliana fulgiluna","iliana é da aliança","de qual facção é iliana"}},["4e149737"]={q="Por que Iliana Fulgiluna está no Vale Gris?",a="Iliana está destacada no Bosque Asa de Prata para apoiar a guerra em andamento contra os Pioneiros do Brado Guerreiro. Ela serve como a principal fornecedora das Sentinelas da Asa de Prata, equipando e abastecendo os campeões da Aliança que assumem a luta pela Ravina Brado Guerreiro.",al={"por que iliana fulgiluna está aqui","iliana fulgiluna bosque asa de prata","por que iliana está no vale gris"}},e94ef362={q="O que Iliana Fulgiluna quer?",a="Iliana busca fortalecer as Sentinelas da Asa de Prata contra a Horda. Ela quer combatentes dedicados da Aliança para expulsar o clã Brado Guerreiro dos antigos bosques do Vale Gris, e ela recompensa aqueles que provam seu valor na Ravina Brado Guerreiro com armamentos especializados, rações e equipamentos de seus depósitos.",al={"o que iliana quer","objetivos de iliana fulgiluna","propósito de iliana"}},["0bec8647"]={q="A quem Iliana Fulgiluna está ligada?",a="Iliana trabalha em estreita colaboração com as Sentinelas da Asa de Prata que defendem o Vale Gris, equipando os campeões que lutam por elas na Ravina Brado Guerreiro a partir de seu posto no Bosque Asa de Prata.",al={"laços de iliana fulgiluna","a quem iliana está conectada","iliana sentinelas da asa de prata"}}},fp="18,212,25.246.0,28.470.0,36.125.0,48.154.0,47.221.0,35.148.0,37.188.0"}
P.entries["npc:ilthalaine"] = {n="Ilthalaine",s="Ilthalaine é um guardião elfo noturno que vigia a clareira sagrada de Umbravale em Teldrassil. Ele atua como o principal recepcionista e mentor dos jovens elfos noturnos que dão seus primeiros passos no mundo. Vigilante e em sintonia com a natureza selvagem, ele orienta aventureiros novatos a manterem o delicado equilíbrio da natureza pelos galhos da Árvore do Mundo.",h="Ilthalaine é um guardião elfo noturno que vigia a clareira sagrada de Umbravale em Teldrassil.",kw={"aldrassil","equilíbrio da natureza","ilthalaine","kaldorei","dador de missões","umbravale","signo","teldrassil"},ang={["class:Druid"]="Para druidas iniciantes, os ensinamentos de Ilthalaine sobre o abate e o equilíbrio natural oferecem suas primeiras lições práticas nos princípios Cenarianos.",["faction:Alliance"]="Ele representa a vigilância serena e duradoura dos Kaldorei, acolhendo novos campeões a serviço de Darnassus e da Aliança como um todo.",["race:NightElf"]="Ilthalaine é o primeiro mentor que todo jovem elfo noturno encontra, oferecendo sabedoria fundamental sobre tutela e o equilíbrio sagrado de seu novo lar em Teldrassil."},sec={{t="Guardião do Vale",b="Posicionado nos arredores do coração de Umbravale, Ilthalaine é frequentemente o primeiro rosto que um jovem elfo noturno vê ao iniciar sua jornada. Ele observa as trilhas da floresta e nota as sutis mudanças na mata que passam despercebidas por olhos comuns. Seu dever é acolher os parentes que retornam e garantir que todos os defensores recém-despertos estejam fundamentados nas tradições de seu povo, prontos para enfrentar as responsabilidades que vêm com o cuidado de Teldrassil."},{t="The Balance of Nature",b="As fortes chuvas de primavera permitiram que as populações de sabres-da-noite e javalis-do-cardo em Umbravale crescessem além do que a clareira pode alimentar. Ilthalaine pede aos jovens defensores que reduzam seus números para que as outras criaturas do bosque possam prosperar e o equilíbrio da natureza seja preservado."},{t="Um Guia para a Disciplina",b="Além de testar a proeza marcial de um aventureiro contra a fauna local, Ilthalaine direciona os jovens elfos para suas vocações escolhidas. Confiando a cada viajante um signo de classe, ele os encaminha diretamente aos seus mentores dentro do santuário de Aldrassil — quer sigam o caminho do guerreiro, druida, ladino, sacerdote ou caçador. Por meio dele, cada novato descobre onde começa seu serviço aos Kaldorei."}},faq={{q="Quem é Ilthalaine?",a="Ilthalaine é um supervisor Kaldorei localizado em Umbravale, o bosque inicial protegido de Teldrassil. Ele atua como o primeiro dador de missões para aventureiros elfos noturnos recém-criados, apresentando-lhes seus deveres e o estado da floresta.",al={"história de ilthalaine","quem é este elfo noturno","dador de missões de umbravale"}},{q="Qual é o papel de Ilthalaine em Umbravale?",a="Ele vigia a vida selvagem em Umbravale e garante que os novos elfos noturnos compreendam a importância do equilíbrio da natureza. Ele envia jovens iniciados em caçadas básicas e os encaminha aos seus respectivos treinadores de classe dentro da grande árvore de Aldrassil.",al={"o que ilthalaine faz","por que ele está aqui","propósito de ilthalaine"}},{q="Por que Ilthalaine quer o abate dos jovens sabres-da-noite e javalis?",a="As fortes chuvas de primavera aumentaram as populações de sabres-da-noite e javalis-do-cardo além do que Umbravale pode sustentar. Ilthalaine pede um abate para preservar o equilíbrio da natureza.",al={"missão the balance of nature","por que matar sabres-da-noite","por que matar javalis"}},{q="Quais são os signos que ele entrega?",a="Ilthalaine entrega signos gravados específicos de cada classe aos novatos, instruindo-os a procurar seus treinadores — como sacerdotisas, druidas, guerreiros e ladinos — abrigados dentro das raízes de Aldrassil.",al={"etched sigil","simple sigil","verdant sigil","encrypted sigil","hallowed sigil"}},{q="Onde Ilthalaine pode ser encontrado?",a="Ele fica bem no caminho central de Umbravale, logo ao sul do enorme galho oco de Aldrassil em Teldrassil.",al={"localização de ilthalaine","onde fica ilthalaine","coordenadas de ilthalaine"}},{q="Ilthalaine é afiliado aos druidas ou às sentinelas?",a="Ilthalaine atua como um zelador geral e representante dos Kaldorei em Umbravale. Embora profundamente sintonizado com a natureza e o espírito druídico de harmonia, ele trabalha em nome de toda a liderança de Darnassus para orientar novatos de todas as disciplinas.",al={"ele é um druida","qual é a facção de ilthalaine"}}},fx={e95b9493={q="Por que Ilthalaine está em Umbravale?",a="Ilthalaine monta guarda em Umbravale para dar as boas-vindas aos defensores elfos noturnos nascentes e preservar o delicado equilíbrio do berçário sagrado de Teldrassil. À medida que a vida selvagem local fica inquieta e sinais de corrupção se infiltram nos galhos, ele permanece estacionado perto de Aldrassil para orientar os recém-chegados e direcionar os esforços iniciais para curar e proteger a Grande Árvore.",al={"por que ilthalaine está aqui","propósito de ilthalaine em umbravale","por que ilthalaine está em teldrassil"}}},fp="10,368,20.455.0,21.274.0,21.405.0,18.238.0,40.249.0,64.170.0,33.199.0,30.117.0,58.239.0"}
P.entries["npc:innkeeper-allison"] = {n="Estalajadeira Cristine",s="A Estalajadeira Cristine administra a Rosa Dourada, uma das estalagens mais movimentadas e centrais de Ventobravo. Localizada no coração do Distrito Comercial, bem entre o banco e a casa de leilões, ela oferece aos viajantes cansados e aos comerciantes locais vínculos de pedra de regresso, bebidas refrescantes e abrigo.",h="A Estalajadeira Cristine administra a Rosa Dourada, uma das estalagens mais movimentadas e centrais de...",kw={"cristine","rosa dourada","pedra de regresso","estalajadeira cristine","ventobravo","distrito comercial"},ang={["faction:Alliance"]="Como proprietária da estalagem mais acessível do centro comercial de Ventobravo, Cristine é um dos rostos mais familiares para os campeões da Aliança que retornam de campanhas na linha de frente para descansar e guardar seus despojos."},sec={{t="Hospitalidade no Distrito Comercial",b="Posicionada exatamente entre a movimentada casa de leilões e os principais cofres da cidade, a Rosa Dourada serve como um epicentro para aventureiros que chegam a Ventobravo. A Estalajadeira Cristine fica atrás do balcão principal no térreo, mantendo a ordem em meio a um fluxo constante de mascates, mercenários e diplomatas visitantes. Além de oferecer hospedagem e serviços de pedra de regresso, ela frequentemente participa de festividades sazonais locais e coordena pequenas tarefas para heróis viajantes que buscam descanso na capital."}},faq={{q="Onde posso encontrar a Estalajadeira Cristine?",a="A Estalajadeira Cristine fica atrás do balcão no térreo da Rosa Dourada. A estalagem fica diretamente no Distrito Comercial de Ventobravo, situada entre o banco central e a casa de leilões.",al={"localização de cristine","onde fica a estalajadeira cristine","estalajadeira da rosa dourada"}},{q="Quais serviços a Estalajadeira Cristine oferece?",a="Ela oferece os serviços padrão de estalajadeiro: os jogadores podem vincular sua pedra de regresso à Rosa Dourada, comprar comida e bebida para descansar e interagir com ela periodicamente durante eventos sazonais e feriados da cidade.",al={"o que cristine faz","serviços de cristine","posso vincular pedra de regresso aqui"}},{q="A Estalajadeira Cristine oferece missões?",a="Sim, Cristine participa de várias festividades sazonais ao longo do ano, como celebrações de feriados, e ocasionalmente pode estar envolvida em tarefas na cidade para viajantes em busca de auxílio pelo reino.",al={"missões de cristine","missão da estalajadeira cristine"}}},fx={["681a398f"]={q="Quem é a Estalajadeira Cristine?",a="Cristine é a proprietária e estalajadeira da Gilded Rose, um dos locais de descanso mais proeminentes em Ventobravo. Operando bem no coração do movimentado Distrito Comercial, ela recebe aventureiros, mercadores e viajantes cansados em busca de conforto e lareira em meio à movimentada capital.",al={"quem é cristine","lore da estalajadeira cristine","quem é a estalajadeira cristine"}},["4fce5435"]={q="De que lado a Estalajadeira Cristine está?",a="Cristine é uma súdita leal do Reino de Ventobravo e é devotada à Aliança. Sua estalagem serve como um refúgio seguro e base para campeões da Aliança e cidadãos que passam pela cidade.",al={"facção da estalajadeira cristine","cristine é da aliança","a quem a estalajadeira cristine serve"}},["3063ebee"]={q="Por que a Estalajadeira Cristine está aqui?",a="Cristine gerencia a Gilded Rose, situada diretamente entre o movimentado banco e a casa de leilões de Ventobravo. Ela permanece em seu posto no piso térreo para fornecer quartos, vincular Pedras de Regresso e atender ao fluxo interminável de viajantes negociando e fazendo negócios no distrito.",al={"por que a estalajadeira cristine está no distrito comercial","propósito da estalajadeira cristine aqui","por que cristine está aqui"}},["735a1673"]={q="O que a Estalajadeira Cristine deseja?",a="Cristine não deseja nada além de administrar um estabelecimento bem-sucedido e hospitaleiro e manter a Gilded Rose funcionando sem problemas. Além de atender aos seus clientes diários, ela participa alegremente de festividades cívicas e celebrações sazonais por toda a capital.",al={"motivações da estalajadeira cristine","o que cristine deseja","quais são os objetivos da estalajadeira cristine"}}},fp="17,295,33.512.0,35.204.0,43.210.0,40.201.0"}
P.entries["npc:innkeeper-farley"] = {n="Estalajadeiro Fábio",s="O Estalajadeiro Fábio administra a Estalagem do Leão Orgulhoso em Vila d'Ouro, fornecendo comida, hospedagem e pedras de regresso aos viajantes que passam pela Floresta de Elwynn. Muito querido e observador, ele frequentemente guarda correspondências extraviadas e escuta os problemas dos aventureiros na estrada.",h="O Estalajadeiro Fábio administra a Estalagem do Leão Orgulhoso em Vila d'Ouro, fornecendo comida, hospedagem...",kw={"floresta de elwynn","fredrik farley","vila d'ouro","estalajadeiro fábio","estalagem do leão orgulhoso","galvão"},ang={["faction:Alliance"]="Para novos recrutas saindo do Vale de Vila Norte, o balcão de Fábio no Leão Orgulhoso costuma ser o primeiríssimo lugar onde vinculam sua pedra de regresso e compram mantimentos."},sec={{t="Uma Presença Constante em Vila d'Ouro",b="O Estalajadeiro Fábio comanda a Estalagem do Leão Orgulhoso com hospitalidade e um olhar atento. Viajantes a caminho de Ventobravo, Cerro Oeste e Floresta do Crepúsculo param em seu balcão para uma refeição quente, uma caneca de cerveja e uma cama, e Fábio mantém a ordem em uma das paradas mais movimentadas do reino, servindo cerveja e queijo a todos que passam por Vila d'Ouro."},{t="O Baú Abandonado do Mensageiro",b="Como Vila d'Ouro fica na encruzilhada entre Ventobravo, Cerro Oeste e a Floresta do Crepúsculo, Fábio ouve muitos boatos e lida com viajantes estranhos. Notavelmente, certa vez ele acolheu um mensageiro que fugiu noite adentro em pânico, abandonando sua bolsa para trás. Fábio guardou em segurança as cartas restantes em um baú no andar de cima — incluindo uma carta não entregue endereçada ao antigo professor Galvão Brumanto, que mais tarde serve como uma pista crucial para os investigadores que seguem os rastros do tutor decaído."}},faq={{q="Quem é o Estalajadeiro Fábio?",a="O Estalajadeiro Fábio é o proprietário da Estalagem do Leão Orgulhoso em Vila d'Ouro, oferecendo descanso e suprimentos aos viajantes que atravessam a Floresta de Elwynn.",al={"estalajadeiro fábio","fredrik farley","quem é o estalajadeiro de vila d'ouro"}},{q="O que Fábio sabe sobre Galvão Brumanto?",a="Fábio se lembra de um mensageiro aterrorizado que fugiu da Estalagem do Leão Orgulhoso no meio da noite, deixando para trás várias entregas. Fábio guardou as cartas abandonadas em um baú no andar de cima, entre as quais está uma carta não entregue endereçada a Galvão Brumanto que os investigadores podem recuperar.",al={"fábio galvão","carta de galvão vila d'ouro","a lenda de galvão fábio"}},{q="Quais serviços Fábio oferece na estalagem?",a="Fábio vincula pedras de regresso para viajantes, aluga quartos e vende uma grande variedade de bebidas, sucos e queijos de toda a Aliança, variando do Queijo Furado de Alterac e Queijo Azedo de Dalaran ao Brie de Ventobravo local.",al={"serviços do leão orgulhoso","fábio comida e bebida","pedra de regresso de vila d'ouro"}}},fx={bf81c39e={q="De que lado o Estalajadeiro Fábio está?",a="O Estalajadeiro Fábio é um súdito leal do Reino de Ventobravo e um membro orgulhoso da Aliança. Da Estalagem do Leão Orgulhoso, ele oferece abrigo, comida e hospitalidade a cidadãos da Aliança, viajantes e soldados que atravessam as terras centrais de Elwynn.",al={"facção do estalajadeiro fábio","a quem fábio serve","fábio aliança"}},f8150ed8={q="O que o Estalajadeiro Fábio quer?",a="A principal preocupação de Fábio é manter a Estalagem do Leão Orgulhoso funcionando perfeitamente. Entre apartar brigas de taberna e servir cerveja, ele quer oferecer um refúgio acolhedor para viajantes cansados.",al={"o que fábio quer","objetivos de fábio","motivação do estalajadeiro fábio"}},["5df540c8"]={q="Por que o Estalajadeiro Fábio está aqui?",a="Fábio administra a Estalagem do Leão Orgulhoso em Vila d'Ouro. Como Vila d'Ouro fica no cruzamento da Floresta de Elwynn, Fábio permanece cuidando da lareira e administrando uma das tabernas mais movimentadas do reino.",al={"por que fábio está na estalagem","por que o estalajadeiro fábio está aqui"}},a88a382c={q="A quem o Estalajadeiro Fábio está ligado?",a="Fábio é uma figura conhecida de Vila d'Ouro, muito famoso entre os viajantes que passam pela Floresta de Elwynn. O bardo itinerante Falkhaan Isenstrider envia jovens aventureiros até ele para descansar no Leão Orgulhoso.",al={"família de fábio","com quem o estalajadeiro fábio tem parentesco","conexões de fábio"}}},fp="16,257,19.327.0,29.508.1,24.138.0,47.282.0,45.209.0"}
P.entries["npc:innkeeper-firebrew"] = {n="Estalajadeiro Aguardente",s="O Estalajadeiro Aguardente gerencia a Stonefire Tavern na movimentada área dos Comuns de Altaforja. Um anfitrião cordial tanto para montanhistas cansados quanto para dignitários visitantes, ele serve pratos típicos dos anões e mantém os viajantes descansados sob a montanha.",h="O Estalajadeiro Aguardente gerencia a Stonefire Tavern na movimentada área dos Comuns de Altaforja.",kw={"comuns","anão","aguardente","pedra de regresso","estalajadeiro","altaforja","stonefire tavern"},ang={["faction:Alliance"]="Como o principal estalajadeiro próximo aos portões da frente, Aguardente oferece aos viajantes estrangeiros da Aliança um refúgio central e seguro para descansar ao visitar a capital do Rei Magni Barbabronze.",["race:Dwarf"]="Para os anões que retornam de patrulhas por Khaz Modan, a estalagem de Aguardente oferece o calor reconfortante do lar e uma caneca confiável de stout anã."},sec={{t="Guardião da Stonefire",b="Situado no anel central dos Comuns, o estabelecimento do Estalajadeiro Aguardente é frequentemente o primeiro santuário encontrado pelos viajantes que entram pelos Portões de Altaforja. Atrás de um balcão carregado de canecas de cerveja, odres de stout e pedaços de carne assada, Aguardente oferece hospitalidade aos aventureiros que partem para as passagens nevadas de Dun Morogh ou para as profundezas do reino montanhoso. Sua estalagem continua sendo uma encruzilhada animada onde mineradores, fuzileiros e emissários se reúnem para escapar dos túneis frios e trocar histórias ao redor da lareira."}},faq={{q="Onde posso encontrar o Estalajadeiro Aguardente?",a="O Estalajadeiro Aguardente encontra-se dentro da Stonefire Tavern, localizada ao longo da borda sul dos Comuns em Altaforja.",al={"localização de aguardente","onde fica o estalajadeiro aguardente","estalajadeiro de altaforja"}},{q="Que tipo de mercadorias Aguardente vende?",a="Ele oferece provisões padrão de estalajadeiro, especializando-se em rações robustas dos anões. Os viajantes podem comprar bebidas que variam de Dwarven Stout e hidromel locais a vinhos importados, além de carnes e refeições reforçadas adequadas para longas jornadas.",al={"o que aguardente vende","bebidas de aguardente","comida da stonefire tavern"}},{q="Aguardente faz parte de alguma família de cervejeiros anões?",a="Ele carrega o sobrenome Aguardente, mas suas relações familiares não foram confirmadas.",al={"família de aguardente","de quem aguardente é parente"}},{q="Quais serviços ele presta aos viajantes?",a="Como um estalajadeiro, Aguardente permite que os viajantes da Aliança vinculem suas Pedras de Regresso à Stonefire Tavern e oferece uma cama quente para descansar e se recuperar sob a montanha.",al={"posso vincular pedra de regresso aqui","estalagem da pedra de regresso em altaforja"}}},fx={["9fc434fc"]={q="Quem é o Estalajadeiro Aguardente?",a="O Estalajadeiro Aguardente é o proprietário anão da Stonefire Tavern, localizada no movimentado Comum de Altaforja. Uma figura acolhedora dentro da cidade montanhosa, ele cuida da lareira, serve cerveja e fornece comida e alojamento para moradores e viajantes cansados.",al={"quem é aguardente","estalajadeiro aguardente","estalajadeiro da stonefire tavern"}},["3dd110f9"]={q="De que lado o Estalajadeiro Aguardente está?",a="Aguardente é leal ao Reino de Altaforja e apoia firmemente a Aliança. Ele mantém sua taberna aberta para todos os aventureiros aliados que procuram refúgio dos ventos frios de Dun Morogh ou descanso após longas jornadas por Azeroth.",al={"facção de aguardente","aguardente aliança","aguardente é da aliança"}},e30bdb86={q="O que o Estalajadeiro Aguardente deseja?",a="Aguardente está focado em administrar uma taberna animada e hospitaleira. Ele quer manter a lareira da Stonefire Tavern acesa, encher as canecas dos clientes com forte bebida anã e garantir que os visitantes da grande cidade da forja tenham um lugar quente para descansar e vincular suas Pedras de Regresso.",al={"o que aguardente deseja","motivo de aguardente","objetivos de aguardente"}},b21a7171={q="Por que o Estalajadeiro Aguardente está aqui?",a="Aguardente gerencia a Stonefire Tavern no Comum, tornando-o o anfitrião central para viajantes que entram no coração de Altaforja. Ele permanece bem ao lado da lareira para oferecer alojamento, vender rações e bebidas, e fornecer uma âncora acolhedora para aventureiros que chegam à capital.",al={"por que aguardente está em altaforja","por que aguardente está na stonefire tavern"}}},fp="18,235,23.540.0,36.117.0,38.230.0,47.78.0,43.178.0"}
P.entries["npc:innkeeper-grosk"] = {n="Estalajadeiro Grosk",s="O Estalajadeiro Grosk administra a estalagem em Monte Navalha, oferecendo a viajantes cansados comida, bebida e um lugar para descansar na região central de Durotar. Situado na movimentada estrada entre o Vale das Provações e Orgrimmar, seu estabelecimento serve como o principal ponto de descanso para jovens aventureiros da Horda que partem rumo ao mundo afora.",h="O Estalajadeiro Grosk administra a estalagem em Monte Navalha, oferecendo a viajantes cansados comida, bebida...",kw={"durotar","grosk","estalajadeiro","estalajadeiro grosk","orgrimmar","peon's burden","monte navalha"},ang={["faction:Horde"]="Para orcs e trolls recém-iniciados, bem como taurens visitantes viajando para o norte a partir do Vale das Provações ou da Aldeia Sen'jin, a estalagem de Grosk marca a primeira cidade de verdade e local de pedra de regresso no caminho para Orgrimmar."},sec={{t="Hospitalidade nos Ermos Vermelhos",b="Monte Navalha serve como o assentamento de encruzilhada vital que liga as áreas de treinamento do sul de Durotar às altas muralhas de Orgrimmar. No centro deste entreposto está o Estalajadeiro Grosk, um orc encarregado de abrigar guerreiros, batedores e peões. Sua estalagem oferece um refúgio contra o calor escaldante do deserto, abastecida com provisões básicas, carnes substanciosas e água fresca para qualquer viajante que passe sob suas vigas resistentes."},{t="O Descanso de um Peão",b="Além de atender viajantes de passagem, Grosk ajuda a mão de obra local que mantém Durotar funcionando. Na missão 'A Peon's Burden', o tímido peão Ukor, que transportou comida até o Vale das Provações apenas para descobrir que ela não era necessária, pede aos viajantes que levem a carga de volta à estalagem de Grosk em Monte Navalha."}},faq={{q="Onde fica o Estalajadeiro Grosk?",a="O Estalajadeiro Grosk fica dentro da estalagem em Monte Navalha, situada bem no centro de Durotar, ao longo da estrada principal que segue para o norte em direção a Orgrimmar.",al={"localização do estalajadeiro grosk","onde fica o grosk","estalajadeiro de monte navalha"}},{q="Quais serviços o Estalajadeiro Grosk oferece?",a="Grosk atua como um estalajadeiro onde aventureiros da Horda podem vincular sua Pedra de Regresso a Monte Navalha. Ele também vende comida básica, água e carne para recuperar vida e mana entre as viagens.",al={"o que o grosk faz","vendedor grosk","posso vincular pedra de regresso em monte navalha"}},{q="O Estalajadeiro Grosk oferece alguma missão?",a="Ele está envolvido na missão 'A Peon's Burden', recebendo o carregamento de comida que o peão Ukor estava com medo demais das feras de Durotar para levar de volta a Monte Navalha por conta própria.",al={"missões do estalajadeiro grosk","onde entregar a peons burden"}}},fx={["490d29ee"]={q="Quem é o Estalajadeiro Grosk?",a="O Estalajadeiro Grosk é o proprietário orc da taberna em Monte Navalha. À medida que viajantes, recrutas e aventureiros errantes passam por Durotar a caminho de ou saindo de Orgrimmar, Grosk oferece a eles abrigo, provisões e uma lareira para descansar seus ossos cansados.",al={"quem é grosk","estalajadeiro grosk","quem é o estalajadeiro grosk"}},["10a7c15b"]={q="De que lado o Estalajadeiro Grosk está?",a="Grosk é um membro firme da Horda, recebendo orcs, trolls, tauren e Renegados em seu estabelecimento. Ele garante que aqueles que lutam pelo novo reino do Chefe Guerreiro Thrall tenham uma base confiável de descanso e reabastecimento em Durotar.",al={"grosk é da horda","lealdade do estalajadeiro grosk","facção do estalajadeiro grosk"}},["29305f72"]={q="O que o Estalajadeiro Grosk deseja?",a="Grosk quer manter sua estalagem funcionando sem problemas, atendendo a viajantes pelas planícies áridas de Durotar. Ele troca comida e bebida revigorantes, vincula aventureiros errantes à sua Pedra de Regresso e, ocasionalmente, cuida das necessidades dos trabalhadores e guardas da cidade.",al={"o que grosk deseja","motivo de grosk","objetivos do estalajadeiro grosk"}},["7fe37467"]={q="Por que o Estalajadeiro Grosk está em Monte Navalha?",a="Monte Navalha serve como a principal encruzilhada e cidade guarnição entre o Vale das Provações, Aldeia Sen'jin e a capital de Orgrimmar. Grosk estabeleceu sua taberna aqui para fornecer alojamento e suprimentos essenciais no coração da vida na fronteira de Durotar.",al={"por que grosk está aqui","por que estalajadeiro de monte navalha","papel de grosk em monte navalha"}}},fp="15,319,29.423.0,16.302.0,33.147.0,43.180.0,38.168.0"}
P.entries["npc:innkeeper-gryshka"] = {n="Estalajadeira Gryshka",s="A Estalajadeira Gryshka é uma anfitriã orca que administra a estalagem Broken Tusk no Vale da Força de Orgrimmar. Servindo como o principal contato de hospitalidade para viajantes que chegam pelos portões da cidade, ela vincula pedras de regresso e fornece comida e bebida aos aventureiros visitantes da Horda. Ela mantém laços estreitos com caçadores e batedores por Durotar e Sertões para manter sua taverna abastecida com cortes nobres de carne.",h="A Estalajadeira Gryshka é uma anfitriã orca que administra a estalagem Broken Tusk no Vale da Força de...",kw={"broken tusk","doraso","gryshka","pedra de regresso","estalajadeira","orgrimmar","vale da força","zargh"},ang={["faction:Horde"]="Para qualquer viajante da Horda que chega a Durotar, a estalagem de Gryshka no Vale da Força costuma ser o ponto principal para vincular pedras de regresso e reabastecer suprimentos antes de se aventurar mais a fundo em Kalimdor.",["profession:Cooking"]="Cozinheiros apreciarão o paladar refinado de Gryshka, já que ela se esforça para obter cortes nobres de caçadores situados em regiões tão distantes quanto os Sertões."},sec={{t="O Lar do Vale da Força",b="Atrás do balcão da Broken Tusk, Gryshka administra uma das estalagens mais movimentadas da Horda. Localizado logo após os portões principais de Orgrimmar, no Vale da Força, seu estabelecimento serve como o primeiro ponto de descanso para guerreiros, mensageiros e campeões recém-chegados em busca de abrigo sob o estandarte de Thrall."},{t="Gosto por Carne Fresca",b="Administrar uma taverna movimentada em um cânion árido requer rotas de suprimentos estáveis. Gryshka mantém uma famosa afinidade por carne fresca, contando com caçadores de confiança por todos os territórios da Horda para abastecer sua cozinha. Companheiros como Zargh na Encruzilhada e Grimtak em Durotar enviam rotineiramente seus melhores cortes de caça para a Broken Tusk a fim de satisfazer seus exigentes padrões culinários."}},faq={{q="Quem é a Estalajadeira Gryshka?",a="A Estalajadeira Gryshka é a estalajadeira orca que administra a taverna Broken Tusk dentro do Vale da Força de Orgrimmar. Ela acolhe viajantes da Horda, vincula pedras de regresso e vende comida e bebida para aventureiros cansados.",al={"quem é gryshka","gryshka orgrimmar","estalajadeira broken tusk"}},{q="Onde a Estalajadeira Gryshka pode ser encontrada?",a="Ela fica dentro da taverna Broken Tusk no Vale da Força, o primeiro distrito principal em que você entra após passar pelos portões sul principais de Orgrimmar.",al={"onde fica gryshka","localização da estalagem broken tusk","estalajadeira do vale da força"}},{q="De onde Gryshka obtém seus suprimentos de carne?",a="Gryshka conta com amigos e batedores por todas as terras da Horda para abastecer sua despensa, incluindo Zargh, estabelecido na Encruzilhada nos Sertões, e Grimtak em Durotar, que lhe enviam cortes seletos de caça.",al={"fontes de comida de gryshka","quem abastece a broken tusk","entrega de carne de zargh"}},{q="Quais serviços Gryshka oferece?",a="Gryshka pode vincular sua pedra de regresso à Broken Tusk para que você possa se teletransportar diretamente para Orgrimmar. Ela também vende diversas comidas, pães e bebidas para restaurar vida e mana.",al={"posso vincular minha pedra de regresso aqui","pedra de regresso broken tusk","itens de vendedor de gryshka"}},{q="Gryshka tem alguma ligação com o poleiro das mantícoras?",a="Viajantes enviados em missões de voo a partir dos Sertões frequentemente entregam pacotes diretamente a Gryshka antes de serem direcionados a Doraso, o mestre de mantícoras situado no alto do platô sobre a cidade.",al={"missão de doraso","mestre de mantícoras broken tusk","carona para orgrimmar estalagem"}},{q="Que tipo de personalidade Gryshka tem?",a="Gryshka é uma anfitriã orca prática e vigorosa, que aprecia boa carne, conversa franca e manter sua taverna bem abastecida e organizada para o fluxo constante de guerreiros da Horda que passam pela capital.",al={"gryshka é amigável","como é a personalidade de gryshka"}}},fx={ad24947b={q="De que lado a Estalajadeira Gryshka está?",a="Gryshka é uma filha leal da Horda. Operando dentro do Vale da Força em Orgrimmar, ela atende diretamente aos guerreiros, caçadores e viajantes que servem o Chefe Guerreiro Thrall, garantindo que eles encontrem descanso e sustento revigorante sob o estandarte da Horda.",al={"facção de gryshka","a quem gryshka serve","gryshka é da horda"}},f36e4eb0={q="O que a Estalajadeira Gryshka deseja?",a="Acima de tudo, Gryshka quer manter a Presa Partida bem abastecida e animada. Ela possui um apetite lendário por carne de qualidade, contando constantemente com amigos em toda Durotar e nos Sertões para entregar cortes frescos e selecionados para satisfazer a si mesma e a seus clientes famintos.",al={"o que gryshka deseja","objetivos de gryshka","o que gryshka está procurando"}},edbe4e1f={q="Por que a Estalajadeira Gryshka está aqui?",a="Gryshka gerencia a Presa Partida, a estalagem movimentada bem no coração do Vale da Força de Orgrimmar. Ela permanece aqui para oferecer hospitalidade, comida, bebida forte e abrigo aos viajantes que passam pela capital ou retornam da natureza selvagem implacável.",al={"por que gryshka está em orgrimmar","por que gryshka está na presa partida","propósito de gryshka"}}},fp="17,404,32.337.0,22.381.0,25.213.0,37.166.0,41.195.0,35.172.0,57.190.0,43.196.0"}
P.entries["npc:innkeeper-keldamyr"] = {n="Estalajadeiro Keldamyr",s="O Estalajadeiro Keldamyr gerencia a lareira e os aposentos da estalagem central em Dolanaar, Teldrassil. Ele oferece comida, bebida e um local de descanso para jovens elfos noturnos que se aventuram para fora de Umbravale em direção aos galhos mais amplos da Árvore do Mundo.",h="O Estalajadeiro Keldamyr gerencia a lareira e os aposentos da estalagem central em Dolanaar, Teldrassil.",kw={"dolanaar","pedra de regresso","estalagem","estalajadeiro","keldamyr","elfo noturno","teldrassil"},ang={["race:NightElf"]="Para os elfos noturnos que acabaram de deixar os campos de treinamento de Umbravale, a estalagem de Keldamyr costuma ser o primeiro lar longe de casa onde vinculam suas pedras de regresso."},sec={{t="O Lar de Dolanaar",b="Dolanaar é o principal vilarejo que os recém-chegados alcançam após partirem da clareira protegida de Aldrassil. O Estalajadeiro Keldamyr mantém o refúgio central da comunidade, fornecendo pão, água de nascente e camas macias sob a copa de Teldrassil. Viajantes, sentinelas e jovens noviços a caminho de Darnassus costumam parar em seu balcão para descansar seus espíritos, fixar suas pedras de regresso e estocar rações para a jornada pelos galhos."},{t="Entregas do Vilarejo",b="Administrar uma estalagem no alto dos galhos exige linhas de suprimento estáveis vindas de assentamentos e comerciantes próximos. Mensageiros locais frequentemente se veem direcionados diretamente ao balcão de Keldamyr para entregar mercadorias, conectando-o diretamente ao comércio e à logística diária que mantêm o povoado de Dolanaar funcionando perfeitamente."}},faq={{q="Onde posso encontrar o Estalajadeiro Keldamyr?",a="Keldamyr fica dentro do prédio principal da estalagem, no coração de Dolanaar, o primeiro grande assentamento ao sul de Umbravale nos galhos de Teldrassil.",al={"localização de keldamyr","onde fica keldamyr","localização do estalajadeiro de dolanaar"}},{q="Quais serviços o Estalajadeiro Keldamyr oferece?",a="Ele atua como o estalajadeiro local, o que significa que você pode vincular sua Pedra de Regresso à lareira dele, comprar provisões básicas como água, leite, suco e pão, ou desconectar-se descansado sob o teto dele.",al={"mercadorias de keldamyr","o que keldamyr vende","comida da estalagem de dolanaar"}},{q="Quais missões envolvem o Estalajadeiro Keldamyr?",a="Ele é o destinatário da tarefa de mensageiro local 'Entrega para Dolanaar', recebendo encomendas destinadas à manutenção e ao abastecimento da estalagem do assentamento.",al={"missões de keldamyr","onde entregar entrega para dolanaar"}}},fx={cc228f0e={q="Quem é o Estalajadeiro Keldamyr?",a="O Estalajadeiro Keldamyr é um anfitrião elfo noturno que gerencia a estalagem em Dolanaar. À medida que viajantes viajam entre as clareiras sombreadas de Umbravale e as extensões mais amplas de Teldrassil, Keldamyr fornece uma lareira silenciosa, bebida refrescante e provisões para aventureiros cansados que se aventuram pelos grandes galhos.",al={"quem é keldamyr","lore do estalajadeiro keldamyr"}},["1430db47"]={q="De que lado está o Estalajadeiro Keldamyr?",a="O Estalajadeiro Keldamyr é leal a Darnassus e à Aliança. Ele serve a comunidade de elfos noturnos de Dolanaar, abrindo suas portas para outros elfos e aliados da Aliança que buscam descanso sob a copa de Teldrassil.",al={"facção de keldamyr","keldamyr é da aliança"}},ff7bce47={q="O que o Estalajadeiro Keldamyr deseja?",a="Keldamyr tem como objetivo manter a estalagem de Dolanaar bem abastecida e acolhedora. Ele cuida dos suprimentos que chegam, coordena as entregas locais e garante que todo viajante tenha comida, água e um lugar seguro para vincular sua pedra de regresso antes de partir para a natureza selvagem.",al={"objetivos de keldamyr","o que keldamyr deseja"}},dbe1a8c8={q="Por que o Estalajadeiro Keldamyr está aqui em Dolanaar?",a="Dolanaar é a principal encruzilhada e assentamento para jovens elfos noturnos que terminam seu treinamento em Umbravale. Keldamyr mantém a estalagem do vilarejo ao longo da estrada para oferecer abrigo e sustento nesta junção crucial em Teldrassil.",al={"por que keldamyr está aqui","keldamyr dolanaar"}}},fp="18,232,18.432.0,15.310.0,36.150.0,44.187.0,39.141.0"}
P.entries["npc:innkeeper-norman"] = {n="Estalajadeiro Ronan",s="O Estalajadeiro Ronan cuida da lareira na taverna principal do Distrito Comercial da Cidade Baixa. Um Renegado quieto e diligente, ele oferece aos viajantes da Horda descanso, vinculação de pedra de regresso e comida adequada aos gostos variados tanto dos vivos quanto dos mortos.",h="O Estalajadeiro Ronan cuida da lareira na taverna principal do Distrito Comercial da Cidade Baixa.",kw={"bates","noturnália","pedra de regresso","estalajadeiro","ronan","distrito comercial","cidade baixa"},ang={["faction:Horde"]="Para aliados vivos da Horda que visitam a Cidade Baixa, a taverna de Ronan é um dos poucos lugares que oferece um local seguro para descansar e se recuperar em meio a uma fortaleza subterrânea de outra forma inóspita.",["race:Undead"]="Ronan oferece aos seus companheiros Renegados um ponto de encontro central no coração do Distrito Comercial para descansarem seus ossos entre as missões da Dama Sombria."},sec={{t="Hospitalidade nos Esgotos",b="Localizado no movimentado Distrito Comercial, sob as ruínas de Capital City de Lordaeron, o Estalajadeiro Ronan oferece hospedagem para emissários, mercenários e aventureiros que passam pela fortaleza dos Renegados. Apesar do frio úmido e dos odores alquímicos da Cidade Baixa, a taverna de Ronan continua sendo um ponto de encontro movimentado para viajantes que desejam ancorar suas pedras de regresso, compartilhar notícias de toda Azeroth ou se preparar para expedições nas Plaguelands."},{t="Excentricidades Festivas",b="Embora Ronan geralmente se atenha às suas funções vendendo provisões e gerenciando quartos, a chegada sazonal de Noturnália revela um lado mais peculiar. Durante o evento, Ronan participa da folia sazonal, exigindo demonstrações peculiares — como cacarejar feito uma galinha — de clientes aventureiros ansiosos por ganhar guloseimas festivas, como as balas de hortelã da Cidade Baixa."}},faq={{q="Onde posso encontrar o Estalajadeiro Ronan?",a="O Estalajadeiro Ronan é encontrado dentro da taverna principal no Distrito Comercial da Cidade Baixa, situado ao longo da curva sul do anel interno.",al={"localização de ronan","localização do estalajadeiro da cidade baixa","onde fica ronan"}},{q="Quais serviços o Estalajadeiro Ronan oferece?",a="Ele atua como um estalajadeiro principal da Cidade Baixa. Os jogadores podem vincular suas pedras de regresso à sua taverna, comprar comida e bebida adequadas tanto para vivos quanto para mortos-vivos, ou desconectar-se em segurança para acumular bônus de descanso.",al={"serviços de ronan","pedra de regresso da cidade baixa"}},{q="Por que Ronan pede aos clientes que cacarejem feito uma galinha?",a="Durante o festival de Noturnália, Ronan participa das travessuras tradicionais do feriado. Os aventureiros que buscam balas de hortelã festivas especiais devem engolir o orgulho e cacarejar feito uma galinha para conquistar seu favor.",al={"cacarejar feito galinha balas de hortelã","missão galinha ronan"}},{q="Ronan tem parentesco com o Estalajadeiro Bates?",a="Embora eles não mencionem um ao outro diretamente em vida ou na morte-vida, nenhum parentesco entre eles é conhecido. Seus nomes juntos são uma referência bem-humorada dos criadores do jogo ao estalajadeiro Norman Bates, do filme Psicose.",al={"conexão norman bates","estalajadeiro bates ronan"}}},fx={["543a0ebc"]={q="Quem é o Estalajadeiro Ronan?",a="O Estalajadeiro Ronan é um estalajadeiro dos Renegados que cuida da movimentada taverna no Distrito Comercial da Cidade Baixa. Embora muitos mortos-vivos tenham abandonado os confortos de suas vidas mortais, Ronan atende aos viajantes exaustos, soldados e emissários que passam pela fortaleza subterrânea da Lady Sylvanas, oferecendo comida, bebida e um lugar para descansar.",al={"quem é ronan","história do estalajadeiro ronan","ronan cidade baixa"}},bc99de77={q="De que lado está o Estalajadeiro Ronan?",a="Ronan é leal aos Renegados e à Dama Sombria e, por extensão, serve à Horda em geral. Localizado no coração do Distrito Comercial, ele abre suas portas para orcs, trolls e tauren visitantes, oferecendo-lhes abrigo sob as Ruínas de Lordaeron, enquanto permanece ferozmente devoto aos seus parentes mortos-vivos.",al={"facção de ronan","lealdade de ronan","ronan é da horda"}},["58ea57aa"]={q="Por que o Estalajadeiro Ronan está aqui?",a="Ronan administra a estalagem principal da Cidade Baixa, posicionada diretamente no Distrito Comercial, onde comércio, viagens e política se cruzam. Mesmo na morte, visitantes e cidadãos precisam de um local de encontro para trocar rumores, vincular Pedras de Regresso e estocar provisões, e Ronan mantém a taverna funcionando sem problemas em meio à escuridão.",al={"por que ronan está na cidade baixa","ronan distrito comercial","o que ronan está fazendo aqui"}}},fp="16,256,25.440.0,22.353.0,34.140.0,44.201.0,52.197.0,37.216.0"}
P.entries["npc:innkeeper-pala"] = {n="Estalajadeira Pala",s="A Estalajadeira Pala administra o Cat and the Xamã, a movimentada taverna situada no nível inferior de Penhasco do Trovão. Ela oferece aos aventureiros visitantes a vinculação da pedra de regresso, bebidas geladas e um lugar para descansar entre viagens por Mulgore e além.",h="A Estalajadeira Pala administra o Cat and the Xamã, a movimentada taverna situada no nível inferior de...",kw={"cat and the xamã","pedra de regresso","estalajadeira","estalajadeira pala","mulgore","pala","penhasco do trovão"},ang={["faction:Horde"]="Orcs, trolls e Renegados que visitam Mulgore encontram na estalagem de Pala uma base de operações confortável, bem perto dos elevadores.",["race:Tauren"]="Para os taurens que voltam para casa vindos das fronteiras de Kalimdor, Pala oferece um rosto familiar e acolhedor sob os imponentes totens das mesas centrais."},sec={{t="Hospitalidade no Terraço Inferior",b="Situada no platô inferior das vastas mesas de Penhasco do Trovão, a Estalajadeira Pala cuida da lareira no Cat and the Xamã. O estabelecimento serve como um dos principais pontos de encontro para viajantes que descem dos elevadores centrais ou chegam das extensas planícies de Mulgore. Mantendo uma vigília constante sobre seu salão comunal, Pala garante que guerreiros cansados, druidas errantes e aliados visitantes da Horda encontrem um abrigo confiável, uma bebida quente e um lar acolhedor longe de casa."}},faq={{q="Onde posso encontrar a Estalajadeira Pala?",a="Pala fica dentro da taverna Cat and the Xamã, localizada no platô inferior de Penhasco do Trovão, perto dos elevadores principais da cidade.",al={"localização de pala","onde fica pala","mapa da estalajadeira pala"}},{q="Quais serviços ela oferece aos viajantes?",a="Assim como outros estalajadeiros em Kalimdor, Pala pode vincular sua pedra de regresso ao Cat and the Xamã para que você possa retornar instantaneamente. Ela também vende comidas e bebidas simples para recuperar vida e mana.",al={"serviços de pala","vincular pedra de regresso em penhasco do trovão","o que pala vende"}},{q="Qual é o nome da taverna dela?",a="Sua taverna chama-se Cat and the Xamã, um estabelecimento que atende ao fluxo constante de viajantes da Horda que passam pelo nível inferior da cidade.",al={"cat and the xamã","nome da estalagem inferior de penhasco do trovão","nome da estalagem de pala"}}},fx={["18c94984"]={q="Quem é a Estalajadeira Pala?",a="A Estalajadeira Pala é uma anfitriã tauren que cuida dos viajantes e andarilhos cansados no Gato e o Xamã, localizado na elevação inferior do Penhasco do Trovão. Ela mantém a lareira acesa, varre o chão e oferece comida, bebida e um lugar de descanso para aqueles que visitam as altas mesas da capital tauren.",al={"quem é pala","estalajadeira pala","quem é a estalajadeira pala"}},["3afadd2e"]={q="De que lado está a Estalajadeira Pala?",a="A Estalajadeira Pala é leal às tribos tauren e à Horda sob o comando do Grão-Chefe Caerne Casco Sangrento. Postada de forma acolhedora no coração do Penhasco do Trovão, ela atende com alegria aos seus parentes tauren, orcs, trolls e aos Renegados visitantes que buscam hospitalidade dentro da cidade.",al={"facção da estalajadeira pala","lealdade da estalajadeira pala","pala é da horda"}},["0c2271e0"]={q="O que a Estalajadeira Pala deseja?",a="Pala quer apenas manter o Gato e o Xamã funcionando sem problemas. Seu foco permanece em oferecer uma hospitalidade calorosa, servir provisões e fornecer um santuário limpo e pacífico onde viajantes cansados possam vincular seus espíritos e descansar entre jornadas árduas por Kalimdor.",al={"o que pala deseja","objetivo de pala","propósito da estalajadeira pala"}},["1c871847"]={q="Por que a Estalajadeira Pala está aqui?",a="As elevações espalhadas do Penhasco do Trovão veem um tráfego constante de caçadores, xamãs e emissários pelas planícies de Mulgore. A Estalajadeira Pala permanece estacionada na elevação inferior para administrar a taverna, garantindo que aventureiros e comerciantes que chegam sempre tenham uma lareira acolhedora e provisões à mão.",al={"por que pala está aqui","por que pala está no penhasco do trovão","papel da estalajadeira pala"}}},fp="14,243,29.485.0,32.134.0,44.192.0,31.146.0"}
P.entries["npc:interrogator-vishas"] = {n="Interrogador Vishas",s="O Interrogador James Vishas é o mestre de tormento da Cruzada Escarlate, posicionado nas profundezas da ala do Cemitério do Monastério Escarlate. Infame por sua voz estridente e pura crueldade, ele sente um prazer distorcido em quebrar prisioneiros e testar os limites da carne mortal. Poucos que entram em suas câmaras de tortura saem com suas mentes ou corpos intactos.",h="O Interrogador James Vishas é o mestre de tormento da Cruzada Escarlate, posicionado nas profundezas da ala...",kw={"cemitério","interrogador vishas","james vishas","espelho de lordaeron","nancy vishas","monastério escarlate","tortura","vorrel sengutz"},ang={["class:Priest"]="Ver Vishas invocar o fanatismo para santificar mutilações horríveis oferece uma demonstração arrepiante de como um propósito sagrado pode se transformar em uma loucura distorcida.",["faction:Alliance"]="Heróis da Aliança que descobrem o trabalho de Vishas rapidamente percebem que a Cruzada Escarlate não distingue mais entre monstros do Flagelo e viajantes vivos inocentes.",["race:Undead"]="Para os Renegados, Vishas incorpora a malícia hipócrita dos fanáticos vivos, torturando mortos-vivos capturados por puro desprezo enquanto alega servir à Luz Sagrada."},sec={{t="Bisturi do Grande Inquisidor",b="Dentro das criptas sombrias e cemitérios do Monastério Escarlate, o Interrogador Vishas cuida dos inimigos capturados da Crusade. Enquanto os fanáticos lá fora marcham em armaduras reluzentes sob estandartes de pureza, Vishas representa a realidade sombria por trás de sua cruzada: sadismo desenfreado disfarçado de fúria religiosa justa. Ele aborda o interrogatório não meramente como um dever de inteligência, mas como um ofício valorizado, deleitando-se com a agonia de prisioneiros Renegados, do Flagelo capturados e de quaisquer viajantes vivos com azar suficiente para serem marcados como hereges."},{t="Uma vida de tranquilidade doméstica",b="Por trás dos aventais ensanguentados e dos gritos da câmara de tortura, Vishas leva uma vida dupla bizarramente doméstica. Fora das muralhas do monastério, sua família — incluindo sua esposa, Nancy Vishas, e seu parente mais velho, Vovô Vishas — reside pacificamente em uma cabana isolada nas margens orientais do Espelho de Lordaeron, nas Montanhas de Alterac. Vishas até leva símbolos macabros de suas vítimas para sua vida pessoal, tendo retirado de um Renegado capturado chamado Vorrel Sengutz sua estimada aliança de casamento para presenteá-la a Nancy."}},faq={{q="Onde o Interrogador Vishas pode ser encontrado?",a="O Interrogador Vishas está localizado nas profundezas da ala do Cemitério do Monastério Escarlate, nas Clareiras de Tirisfal. Ele supervisiona uma câmara de tortura sombria forrada com jaulas de ferro e prateleiras ensanguentadas.",al={"localização de vishas","onde está o interrogador vishas","sala de vishas"}},{q="Por que Vishas tortura seus prisioneiros?",a="Embora a Cruzada Escarlate justifique atormentar prisioneiros para erradicar a corrupção do Flagelo e extrair informações, Vishas se deleita pessoalmente com a dor que causa. Ele sente um enorme orgulho pessoal de sua crueldade, vendo a tortura como seu ofício artístico.",al={"por que vishas tortura pessoas","motivação de vishas"}},{q="Quem é Vorrel Sengutz?",a="Vorrel Sengutz é um prisioneiro encarcerado e brutalmente torturado por Vishas dentro do Cemitério do Monastério. Vishas submeteu Vorrel a semanas de dor e roubou sua aliança de casamento, pretendendo usá-la como um presente para sua esposa.",al={"prisioneiro vorrel sengutz","quem é o prisioneiro na jaula"}},{q="Onde a família de Vishas mora?",a="Sua família mora longe do Monastério, em uma cabana modesta situada ao longo da margem oriental do Espelho de Lordaeron, nas Montanhas de Alterac. Sua esposa Nancy e o Vovô Vishas vivem lá tranquilamente, aparentemente distantes de suas atrocidades.",al={"localização de nancy vishas","vovô vishas","casa da família vishas"}},{q="Quem Vishas mantém prisioneiro?",a="A Cruzada Escarlate considera os mortos-vivos como inimigos. Entre os prisioneiros de Vishas está o Renegado Vorrel Sengutz, a quem ele tortura há semanas.",al={"prisioneiros de vishas","quem vishas tortura","vishas prisioneiro vorrel"}},{q="Como é a voz e o comportamento de Vishas?",a="Vishas é infame entre aqueles que o enfrentam por sua voz estridente e irritante, risadas histéricas e uma empolgação perturbadora sempre que surge uma oportunidade de arrancar segredos de uma vítima relutante.",al={"voz de vishas","personalidade de vishas"}}},fx={["518fe48c"]={q="Quem é o Interrogador Vishas?",a="James Vishas é o interrogador-chefe da Cruzada Escarlate, posicionado nas profundezas do Scarlet Monastery Graveyard. Fanático e notoriamente cruel, ele se orgulha imensamente de quebrar os prisioneiros trazidos diante dele. Armado com instrumentos de tortura e um zelo desequilibrado, ele extrai confissões e tormento na mesma medida de qualquer um que tenha a infelicidade de cair em suas mãos.",al={"quem é vishas","história do interrogador vishas","quem é james vishas"}},cadee917={q="De que lado está o Interrogador Vishas?",a="Vishas é totalmente devoto à Cruzada Escarlate. Ele serve à cruzada zelosa deles torturando suspeitos de serem agentes do Flagelo, prisioneiros Renegados e qualquer outro considerado contaminado ou hostil à pureza fanática da ordem.",al={"facção de vishas","para quem vishas trabalha","vishas cruzada escarlate"}},e1510cf6={q="Por que o Interrogador Vishas está aqui?",a="Vishas está posicionado nas câmaras de tortura do Scarlet Monastery Graveyard para lidar com prisioneiros capturados pelas Clareiras de Tirisfal. Ele passa seus dias e noites extraindo informações, desabafando impulsos sádicos e quebrando o espírito de cativos como Vorrel Sengutz em nome da Cruzada.",al={"por que vishas está no cemitério","papel de vishas no monastério","o que vishas está fazendo aqui"}}},fp="19,348,30.526.0,27.533.1,39.184.0,38.249.0,22.210.0,31.236.0,30.139.0,40.206.0"}
P.entries["npc:islen-waterseer"] = {n="Islen Vidente da Água",s="Islen Vidente da Água é uma respeitada xamã tauren que vive ao lado de uma cabana de pesca tranquila na Escadaria de Tidus, com vista para o mar oriental dos Sertões. Possuindo uma comunhão íntima com os espíritos da água, ela guia os iniciados nas provações necessárias para se sintonizarem com o elemento. Xamãs novatos de toda a Horda buscam sua sabedoria para obter seu Totem da Água.",h="Islen Vidente da Água é uma respeitada xamã tauren que vive ao lado de uma cabana de pesca tranquila na...",kw={"sertões","call of water","greta musgo no casco","islen","xamã","escadaria de tidus","water sapta","vidente da água"},ang={["class:Shaman"]="Islen é uma mentora essencial em sua jornada, guiando você através dos ritos elementais necessários para vincular e comungar com os espíritos da água para obter seu Totem da Água.",["faction:Horde"]="Situada ao longo da costa dos Sertões, Islen serve como um sereno ponto de ancoragem espiritual da Horda, acolhendo viajantes tanto de Orgrimmar quanto de Penhasco do Trovão.",["race:Tauren"]="Islen personifica a tradicional reverência tauren pelas dádivas da Mãe Terra, escolhendo uma vida solitária à beira-mar para permanecer em sintonia com as correntes sutis da natureza."},sec={{t="The Hermit da Escadaria de Tidus",b="Longe da movimentada Encruzilhada e dos acampamentos dos Sertões, Islen Vidente da Água vive ao longo do litoral escarpado conhecido como Escadaria de Tidus. Aqui, onde as planícies áridas se chocam contra O Grande Oceano, a presença dos espíritos da água é pura e dominante. Em vez de viver em salões estrondosos ou cidades movimentadas, Islen prefere este entreposto tranquilo, dedicando seus dias a ouvir as marés e a ajudar xamãs que buscam comunhão com o elemento fluido."},{t="Mestra do Water Sapta",b="Compreender a água requer mais do que simples estudo; exige harmonia interior e percepção espiritual. Islen orienta os buscadores na preparação do Water Sapta, uma beberagem sagrada que rompe o véu entre os sentidos mortais e as manifestações elementais. Seus ensinamentos lembram aos xamãs que a água é tão inflexível e profunda quanto fluida e restauradora, exigindo imenso respeito de qualquer um que espere recorrer à sua ajuda."},{t="Laços Através das Selvas",b="Embora Islen mantenha uma vida tranquila na costa, seu alcance espiritual e suas conexões se estendem por Kalimdor. Ela mantém uma amizade próxima e duradoura com Greta Musgo no Casco, outra sábia tauren versada nas artes restauradoras. Por meio dessas conexões, o conhecimento de Islen sobre a essência purificadora da água toca assuntos muito além dos Sertões, oferecendo inclusive ajuda espiritual a terras afligidas por profunda corrupção."}},faq={{q="Quem é Islen Vidente da Água?",a="Islen Vidente da Água é uma sábia xamã tauren que reside ao longo da costa dos Sertões, na Escadaria de Tidus. Ela possui um vínculo raro e profundo com os espíritos elementais da água e atua como mentora espiritual para xamãs que viajam para obter seu Totem da Água.",al={"história de islen vidente da água","quem é islen","tauren da escadaria de tidus"}},{q="Por que os xamãs viajam para vê-la?",a="Xamãs da Horda são direcionados a Islen por seus instrutores em Durotar, Orgrimmar e Penhasco do Trovão durante as provações de Call of Water. Ela testa a compreensão que eles têm do elemento e os instrui na criação do Water Sapta para perceberem os elementais da água diretamente.",al={"por que visitar islen","npc de call of water","missão de xamã na costa dos sertões"}},{q="Onde Islen Vidente da Água está localizada?",a="Ela pode ser encontrada sentada do lado de fora de uma pequena cabana de pesca na Escadaria de Tidus, situada na costa leste dos Sertões, ao sul da Costa dos Mercadores.",al={"localização de islen","onde fica islen vidente da água","encontrar islen"}},{q="O que é o Water Sapta de que ela fala?",a="O Water Sapta é uma beberagem espiritual especialmente preparada, criada a partir de componentes elementais. Consumi-la permite que a visão de um xamã penetre o plano físico e testemunhe os espíritos ocultos da água que habitam em fontes e marés sagradas.",al={"significado do water sapta","o que o sapta faz"}},{q="Quem é a amiga de Islen, Greta Musgo no Casco?",a="Greta Musgo no Casco é uma antiga companheira tauren e colega praticante das artes espirituais. As duas compartilham uma amizade duradoura, consultando-se mutuamente sobre purificação espiritual e a natureza restauradora da água.",al={"conexão com greta musgo no casco","amiga de islen"}},{q="Islen pertence a uma facção ou tribo específica?",a="Nenhuma tribo é mencionada para ela. Islen vive isolada ao longo da costa e é amigável com viajantes tanto da Horda quanto da Aliança, até mesmo ajudando a purificar as águas corrompidas da Selva Maleva, embora sejam os instrutores de xamã da Horda que enviam seus alunos orcs, trolls e taurens até ela.",al={"facção de islen","islen é da horda"}}},fx={["6d5841da"]={q="Por que Islen Vidente da Água está aqui?",a="Islen habita junto ao Grande Oceano ao longo da Escadaria de Tidus, vivendo tranquilamente em solidão perto do mar aberto. Aqui, sintonizada diretamente com as marés e os fluxos naturais, ela atua como um esteio espiritual para jovens xamãs de toda a Horda que precisam aprender a se sintonizar com os esquivos espíritos da água.",al={"por que islen está aqui","por que islen está perto do oceano","islen vidente da água escadaria de tidus"}}},fp="15,354,25.454.0,27.423.0,22.406.0,23.251.0,33.258.0,33.151.0,38.240.0,37.207.0,49.277.0"}
P.entries["npc:iverron"] = {n="Iverron",s="Iverron é um jovem elfo noturno encontrado em Umbravale, o ramo inicial protegido de Teldrassil. Atingido pelo veneno dos aracnídeos cada vez mais agitados do bosque, sua situação serve como um aviso precoce da crescente corrupção no interior da Árvore do Mundo.",h="Iverron é um jovem elfo noturno encontrado em Umbravale, o ramo inicial protegido de Teldrassil.",kw={"antídoto","dentaria","iverron","kaldorei","umbravale","aranha","teldrassil","veneno"},ang={["class:Druid"]="Druidas que estudam em Umbravale veem o envenenamento de Iverron como um sintoma de uma aflição mais profunda que aflige a natureza, exigindo remédios preparados diretamente da flora e fauna da clareira.",["profession:Herbalism"]="A sobrevivência de Iverron depende da coleta rápida da flora local de Umbravale, enfatizando o valor crítico do conhecimento de herborismo na preservação da vida.",["race:NightElf"]="Para jovens elfos noturnos que dão seus primeiros passos fora de Aldrassil, o infortúnio de Iverron é uma lição precoce sobre a rapidez com que a vida selvagem de Teldrassil está caindo em desequilíbrio."},sec={{t="Uma Picada Amarga",b="Enquanto vagava pelas copas tranquilas de Umbravale, Iverron deu de cara com as aranhas de Lenhateia que faziam ninhos no vale. Sucumbindo rapidamente à sua picada tóxica, o jovem elfo ficou incapacitado, incapaz de retornar em segurança por conta própria. Sua condição indefesa destaca a agressão repentina que se espalha pelas criaturas que antes compartilhavam a clareira em paz."},{t="Remédios Desesperados",b="A sobrevivência de Iverron recai sobre a rapidez de pensamento de seus companheiros e curadores locais, que necessitam de ingredientes potentes da floresta — como cogumelos jacinto, lírios pétala-da-lua e linfa de Lenhateia — para preparar um antídoto. Seu quase encontro com a morte é um lembrete sóbrio a todos os jovens kaldorei em Umbravale de que os ramos de Teldrassil estão longe de ser um santuário imaculado."}},faq={{q="Quem é Iverron?",a="Iverron é um jovem elfo noturno que habita em Umbravale, em Teldrassil. Durante suas viagens pela floresta, ele foi vítima da fauna venenosa que assombra os ramos e precisou de ajuda urgente para sobreviver.",al={"história de iverron","quem é iverron","iverron elfo noturno"}},{q="O que envenenou Iverron?",a="Ele foi picado pelas agressivas aranhas de Lenhateia que habitam os matagais de Umbravale, sofrendo de um veneno debilitante que o descanso comum não conseguia curar.",al={"por que iverron está doente","o que picou iverron","veneno de iverron"}},{q="Como Iverron é curado?",a="Ele é curado por meio de uma concoctura feita com matéria vegetal local de Teldrassil, incluindo cogumelos jacinto e lírios pétala-da-lua, misturada com linfa de Lenhateia das aranhas para criar um antídoto direcionado.",al={"curar iverron","antídoto de iverron","salvando iverron"}},{q="Onde Iverron pode ser encontrado?",a="Ele está localizado em Umbravale, a clareira inicial isolada na copa de Teldrassil onde elfos noturnos noviços iniciam seu treinamento.",al={"localização de iverron","onde fica iverron","encontrar iverron"}},{q="Quem está ajudando Iverron?",a="Iverron envia aventureiros à sua amiga Dirânia Pratafulge, que lhes pede para coletar os ingredientes de um antídoto e depois levá-lo rapidamente de volta a ele antes que perca a potência.",al={"quem salva iverron","amigos de iverron","dentaria silverglade iverron"}},{q="Por que as aranhas em Umbravale são tão hostis?",a="A agressão repentina das aranhas de Umbravale faz parte de um mal não natural que se alastra por Teldrassil, transformando feras normalmente reclusas em predadores violentos.",al={"por que aranhas atacam","corrupção das aranhas de teldrassil"}}},fx={["7be6aac6"]={q="De que lado está Iverron?",a="Iverron é um elfo noturno comum leal ao seu povo e à Aliança. Ele vive pacificamente dentro dos ramos abrigados de Umbravale em Teldrassil, contando com a ajuda de colegas kaldorei como sua amiga próxima Dirânia Pratafulge para cuidar dele quando o infortúnio acontece.",al={"facção de iverron","iverron é da aliança","a quem iverron serve"}},["9c5ce7fc"]={q="O que Iverron deseja?",a="Neste momento, Iverron simplesmente quer sobreviver. Derrubado por um veneno de aranha mortal enquanto se aventurava por Umbravale, ele está incapacitado e precisa desesperadamente de um contraveneno potente antes que o veneno tire sua vida.",al={"objetivo de iverron","o que iverron precisa","motivo de iverron"}},b06694b4={q="Por que Iverron está em Umbravale?",a="Iverron reside em Umbravale, o vale inicial abrigado de Teldrassil. Ele se aventurou nos bosques ao redor, apenas para entrar em conflito com as agressivas aranhas-da-teia do bosque. Dominado pelo veneno delas, ele desabou e agora está prostrado no chão da floresta.",al={"por que iverron está aqui","motivo de iverron em umbravale","o que aconteceu com iverron"}},["61549ef7"]={q="A quem Iverron está ligado?",a="Iverron é amigo próximo de Dirânia Pratafulge, que vive em Umbravale. Quando ele não foi visitá-la como de costume, ela enviou um aventureiro que passava para procurá-lo e, depois de saber que ele havia sido envenenado, reuniu os ingredientes para um antídoto a fim de salvar sua vida.",al={"conexões de iverron","quem são os amigos de iverron","iverron dirânia"}}},fp="7,253,13.356.0,18.356.1,15.205.0,22.159.0,21.195.0,27.130.0,23.174.0,45.160.0"}
P.entries["npc:jahan-hawkwing"] = {n="Jahan Asa de Falcão",s="Jahan Asa de Falcão é um armeiro tauren situado na Encruzilhada nos Sertões. Ele fornece equipamentos essenciais de couro e cota de malha para viajantes que enfrentam as planícies severas e cheias de predadores.",h="Jahan Asa de Falcão é um armeiro tauren situado na Encruzilhada nos Sertões.",kw={"armeiro","pacote de peles","cota de malha","encruzilhada","jahan asa de falcão","armadura de couro","tauren","sertões"},ang={["faction:Horde"]="Posicionado na interseção das principais trilhas de Kalimdor, Jahan garante que guerreiros e batedores da Horda permaneçam protegidos contra os ataques implacáveis de centauros e a vida selvagem local.",["race:Tauren"]="Jahan representa a natureza prática e autossuficiente dos shu'halo, usando o trabalho em couro e materiais resistentes para proteger viajantes nas terras ancestrais dos Sertões."},sec={{t="Armeiro da Encruzilhada",b="Situado no movimentado entreposto da Encruzilhada, Jahan Asa de Falcão atende às necessidades de equipamento dos andarilhos e defensores da Horda. Os Sertões são uma extensão brutal onde equipamentos de proteção duráveis costumam fazer a diferença entre a sobrevivência e a morte para centauros, javatuscos ou feras selvagens. Jahan trabalha ao lado de coureiros locais, lidando com entregas de peles curtidas para manter sua loja abastecida com couro curtido confiável e cota de malha resistente."}},faq={{q="Quem é Jahan Asa de Falcão?",a="Jahan Asa de Falcão é um comerciante e armeiro tauren que reside na Encruzilhada nos Sertões. Ele fornece equipamentos de proteção de couro e cota de malha para aventureiros que passam e guardas da Horda.",al={"história de jahan asa de falcão","quem é jahan","vendedor de armaduras da encruzilhada"}},{q="Quais mercadorias ele vende?",a="Jahan vende conjuntos básicos de armadura de couro curtido e cota de malha, incluindo gibões, botas, cintos, braçadeiras e luvas adequadas para guerreiros novatos, caçadores e batedores.",al={"o que jahan vende","estoque de jahan asa de falcão","armadura de jahan"}},{q="Quais tarefas ele oferece aos viajantes?",a="Jahan conta com artesãos próximos para fornecer suas mercadorias. Ele pede a viajantes prestativos que façam remessas de materiais brutos ou preparados, enviando pacotes de peles para curtidores locais e aguardando mercadorias finalizadas em troca.",al={"missões de jahan","missão pacote de peles","entrega de peles da encruzilhada"}}},fx={f61d6720={q="Por que Jahan Asa de Falcão está na Encruzilhada?",a="Jahan Asa de Falcão ganha a vida como um comerciante de armaduras de couro e malha na Encruzilhada. Como o posto avançado vê inúmeros batedores, caçadores e viajantes passando pelos Sertões todos os dias, seu ofício fornece a eles o equipamento durável necessário para sobreviver à natureza selvagem e inóspita.",al={"por que jahan asa de falcão está aqui","localização de jahan asa de falcão","jahan asa de falcão encruzilhada"}},["34a83622"]={q="De que lado Jahan Asa de Falcão está?",a="Jahan Asa de Falcão permanece firmemente ao lado da Horda e de seus companheiros taurens. Destacado na Encruzilhada, um entreposto vital que conecta os territórios da Horda pelo centro de Kalimdor, ele fornece suprimentos essenciais e armaduras resistentes àqueles que defendem essas terras contra centauros, javatuscos e facções rivais.",al={"facção de jahan asa de falcão","jahan asa de falcão é da horda","jahan asa de falcão aliança ou horda"}}},fp="14,183,25.436.0,22.183.0,24.165.0,38.206.0"}
P.entries["npc:jaina-proudmoore"] = {n="Jaina Proudmore",s="A Grã-senhora Jaina Proudmore é a governante da Ilha Theramore e a feiticeira humana viva mais poderosa. Anteriormente uma aluna exemplar do Kirin Tor de Dalaran, ela liderou os sobreviventes de Lordaeron através do Grande Oceano e agora luta para manter uma frágil paz entre a Aliança e a Nova Horda.",h="A Grã-senhora Jaina Proudmore é a governante da Ilha Theramore e a feiticeira humana viva mais poderosa.",kw={"antonidas","arthas","pântano vadeoso","jaina","kirin tor","proudmore","theramore","thrall"},ang={["class:Mage"]="Treinada pelo próprio Arquimago Antonidas, a Grã-senhora Jaina é amplamente considerada a feiticeira humana viva mais poderosa, demonstrando o ápice do domínio arcano de Dalaran.",["faction:Alliance"]="Jaina fornece à Aliança seu ponto de apoio crítico no sul de Kalimdor, equilibrando a lealdade à regência do Grão-senhor Bolvar em Ventobravo com seu desejo de evitar uma guerra com a Horda vizinha."},sec={{t="Fuga para Kalimdor",b="Filha do Grande Almirante Daelin Proudmore de Kul Tiraz, Jaina demonstrou notável aptidão para o arcano desde cedo e estudou com o Arquimago Antonidas em Dalaran. Durante a Terceira Guerra, ela investigou a misteriosa Praga da Não-morte ao lado do Príncipe Arthas Menethil, testemunhando em primeira mão a trágica queda de Lordaeron. Guiada pelos avisos do Profeta Medivh, ela reuniu uma expedição de sobreviventes humanos e navegou para o oeste rumo ao continente esquecido de Kalimdor. Lá, suas forças forjaram uma aliança sem precedentes com a Horda de Thrall e os elfos noturnos, permanecendo unidos no topo do Monte Hyjal para derrotar Archimonde e destruir a invasão da Legião Ardente."},{t="A Senhora de Theramore",b="Após a derrota da Legion, Jaina fundou a cidadela insular de Theramore na costa do Pântano Vadeoso, estabelecendo o principal bastião da Aliança no sul de Kalimdor. Seu compromisso com a diplomacia foi testado ao limite quando seu pai chegou em busca de vingança contra os orcs; Jaina recusou-se a apoiar sua guerra, dando um passo para o lado enquanto as forças de Thrall abatiam o Grande Almirante para evitar que Kalimdor mergulhasse em outro conflito devastador. Hoje, ela governa Theramore como uma defensora inabalável da coexistência, trabalhando em estreita colaboração com o Chefe de Guerra Thrall enquanto ancora a presença da Aliança contra as crescentes tensões locais."}},faq={{q="Quem é a Grã-senhora Jaina Proudmore?",a="Jaina é a governante da Ilha Theramore e indiscutivelmente a maga humana viva mais talentosa. Ela é filha do falecido Grande Almirante Daelin Proudmore de Kul Tiraz e ex-aprendiz do Arquimago Antonidas em Dalaran.",al={"quem é jaina","história de jaina proudmore","líder de theramore"}},{q="Por que Jaina está em Kalimdor em vez dos Reinos do Leste?",a="Antes da queda de Lordaeron na Terceira Guerra, o Profeta Medivh alertou Jaina para liderar o máximo de pessoas possível através do mar até Kalimdor. Sua expedição sobreviveu à jornada, lutou no Monte Hyjal e estabeleceu a fortaleza portuária de Theramore no Pântano Vadeoso.",al={"por que jaina deixou lordaeron","jaina kalimdor","por que theramore fica aqui"}},{q="Qual é a relação de Jaina com a Horda?",a="Jaina mantém uma amizade incomum e cautelosa com o Chefe de Guerra Thrall. Depois de lutarem juntos contra a Legião Ardente no Monte Hyjal, ambos os líderes têm se esforçado para manter a paz entre seus povos, apesar da forte oposição de linhas-duras em ambos os lados.",al={"jaina é amiga de thrall","jaina e horda","jaina odeia orcs"}},{q="O que aconteceu entre Jaina e o Príncipe Arthas Menethil?",a="Jaina e Arthas eram companheiros próximos que compartilharam um romance. Eles investigaram conjuntamente a praga que se espalhava por Lordaeron, mas Jaina ficou horrorizada com a queda de Arthas na crueldade — culminando no expurgo de Stratholme, onde ela se recusou a participar do massacre de cidadãos infectados.",al={"jaina e arthas","jaina amava arthas"}}},fp="16,283,18.679.0,21.631.0,29.218.0,57.265.0,44.259.0,55.303.0"}
P.entries["npc:james-halloran"] = {n="Iago Halberque",s="Iago Halberque é um curtidor humano que trabalha nos Pantanal para fornecer couros finos pelos continentes orientais. Sediado no Porto de Menethil, ele ganha a vida colhendo as peles resistentes e valiosas dos crocoliscos nativos da região. Ele depende de viajantes de passagem e de canais comerciais próximos para reunir matérias-primas e transportar seus couros acabados para o mercado.",h="Iago Halberque é um curtidor humano que trabalha nos Pantanal para fornecer couros finos pelos continentes...",kw={"crocolisco","halberque","iago halberque","trabalho em couro","porto de menethil","curtidor","pantanal"},ang={["class:Hunter"]="Caçadores navegando pelos pântanos encharcados encontrarão um terreno comum com Halberque, cujo sustento depende de perseguir e colher os predadores répteis agressivos dos Pantanal.",["faction:Alliance"]="O comércio de Halberque ajuda a sustentar a presença comercial da Aliança nos Pantanal acidentados, fornecendo couro trabalhado valioso para cidades por todo o reino."},sec={{t="Um Curtidor nos Pântanos",b="De sua casa no Porto de Menethil, Iago Halberque ganha a vida com o pântano logo fora da cidade. Como um curtidor empreendedor, Halberque reconheceu que os pântanos perigosos oferecem uma mercadoria lucrativa: peles de crocolisco. Transformar a pele áspera dos répteis do pântano em couro de alta qualidade requer um artesanato raro, e os produtos acabados de Halberque são enviados através de canais comerciais locais para compradores por toda Azeroth."},{t="Couros, Aprendizes e Comércio Diário",b="Operar tão perto do pântano traz perigo constante. Halberque não pode caçar facilmente cada fera sozinho enquanto cuida dos tanques de cura e da logística comercial. Ele frequentemente contrata viajantes resistentes para lidar com as tarefas mais difíceis de esfolar feras jovens do pântano e gerenciar entregas rotineiras entre seu local de trabalho e os assentamentos vizinhos, garantindo que seu movimentado comércio de couro permaneça totalmente abastecido."}},faq={{q="Quem é Iago Halberque?",a="Iago Halberque é um curtidor humano sediado no Porto de Menethil, nos Pantanal. Ele se especializa em caçar e esfolar os crocoliscos indígenas da região, curando suas peles resistentes em artigos de couro que são exportados para todo o mundo.",al={"iago halberque","halberque","quem é halberque","curtidor dos pantanal"}},{q="Onde Iago Halberque vende seu couro?",a="Halberque processa peles cruas de crocolisco em couros finos e os envia por toda Azeroth. Ele depende fortemente do comércio marítimo que passa pelo Porto de Menethil para distribuir suas mercadorias pelos mares.",al={"comércio de couro de halberque","para onde vão as peles de crocolisco","negócios de halberque"}},{q="Por que Halberque precisa de aventureiros para coletar Young Crocolisk Skins?",a="Curar e curtir couro é um trabalho demorado e trabalhoso. Halberque emprega aventureiros viajantes para abater os crocoliscos locais do pântano e tirar suas peles para que ele tenha um fornecimento constante de matéria-prima sem abandonar sua oficina.",al={"por que matar crocoliscos jovens","missão young crocolisk skins","peles de crocolisco de halberque"}},{q="Qual é a conexão de Halberque com o Porto de Menethil?",a="O Porto de Menethil serve como o principal centro comercial e de suprimentos da região. Halberque depende do porto e de suas rotas de navegação para exportar suas peles curtidas para mercados distantes e manter seu negócio de curtume viável.",al={"halberque porto de menethil","conexão de halberque com o porto","halberque mora em porto de menethil"}},{q="Onde Iago Halberque pode ser encontrado?",a="Halberque vive e trabalha no Porto de Menethil, o movimentado porto na costa oeste dos Pantanal, com os pântanos de crocoliscos logo fora da cidade.",al={"localização de halberque","onde está iago halberque","encontrar halberque"}},{q="Halberque tem um aprendiz?",a="Sim. Halberque enviou seu aprendiz, a quem considera como um filho, para os pântanos para esfolar crocoliscos gigantes, mas o jovem foi atacado e perdeu uma perna. Enquanto o aprendiz se recupera, Halberque depende de viajantes resistentes para coletar as peles das quais seu comércio depende.",al={"aprendiz de halberque","deveres do aprendiz de halberque","quem trabalha para halberque"}}},fx={["21c95e2f"]={q="De que lado está Iago Halberque?",a="Iago Halberque está alinhado com a Aliança. Um artesão humano trabalhando fora do Pantanal, ele mantém laços com a cidade portuária de Porto de Menethil para fornecer seus produtos por todas as terras da Aliança.",al={"halberque é da aliança","facção de iago halberque","a quem halberque serve"}},b76d5522={q="Por que Iago Halberque está aqui no Pantanal?",a="Halberque ganha a vida como curtidor e caçador. Os pântanos e canais do Pantanal estão repletos de crocoliscos, fornecendo a ele um suprimento constante de peles que ele cura e exporta para todos os lugares.",al={"por que halberque está no pantanal","propósito de iago halberque","por que halberque está aqui"}}},fp="14,354,23.426.0,35.394.0,22.229.0,43.205.0,68.243.0,49.210.0,34.143.0,33.260.0"}
P.entries["npc:jannok-breezesong"] = {n="Jannok Brisacanto",s="Jannok Brisacanto é um instrutor de ladinos elfo noturno localizado na vila de Dolanaar, em Teldrassil. Ele oferece treinamento em furtividade, astúcia e manejo de lâminas para jovens ladinos kaldorei que se aventuram pelos galhos da Árvore do Mundo.",h="Jannok Brisacanto é um instrutor de ladinos elfo noturno localizado na vila de Dolanaar, em Teldrassil.",kw={"brisacanto","dolanaar","erion umbrurmúrio","jannok","elfo noturno","instrutor de ladinos","teldrassil"},ang={["class:Rogue"]="Para jovens ladinos elfos noturnos começando em Teldrassil, Jannok é seu principal mentor em Dolanaar antes de você seguir para a capital.",["race:NightElf"]="Embora a cultura kaldorei frequentemente enfatize sentinelas e o druidismo, instrutores como Jannok preparam aqueles que preferem furtividade, venenos e adagas."},sec={{t="Um Guia nas Sombras",b="Encontrado descansando sob os galhos de Dolanaar, Jannok Brisacanto atua como o principal instrutor para ladinos elfos noturnos novatos. Ao contrário das sentinelas formais ou dos druidas reclusos de Teldrassil, Jannok orienta aqueles que agem silenciosamente à margem da sociedade, ensinando-os a espreitar nas sombras, atacar por trás e sobreviver sem serem vistos entre os galhos. Assim que o ladino avança além das lições iniciais em Dolanaar, Jannok o encaminha a mestres mais experientes na capital, Darnassus."}},faq={{q="Quem é Jannok Brisacanto?",a="Jannok Brisacanto é um instrutor de ladinos elfo noturno que reside em Dolanaar, em Teldrassil. Ele ensina habilidades e técnicas fundamentais de ladino a jovens kaldorei.",al={"quem é jannok","papel de jannok brisacanto","instrutor de ladinos de dolanaar"}},{q="Para onde Jannok envia os ladinos que avançam?",a="Assim que o ladino conclui seu treinamento inicial em Dolanaar, Jannok o orienta a viajar até Darnassus para buscar instruções mais avançadas com Erion Umbrurmúrio, um experiente instrutor de ladinos localizado no Enclave Cenariano da cidade.",al={"missão de jannok","missão de erion umbrurmúrio","próximo passo ladino dolanaar"}},{q="Onde posso encontrar Jannok em Dolanaar?",a="Jannok está localizado em Dolanaar, o assentamento central de Teldrassil fora de Umbravale, posicionado entre os pavilhões de instrutores da vila.",al={"localização de jannok","onde fica jannok","encontrar jannok brisacanto"}}},fx={b07dd258={q="Por que Jannok Brisacanto está aqui?",a="Jannok está posicionado em Dolanaar para instruir ladinos elfos noturnos novatos que emergem de Umbravale. Ele oferece treinamento em furtividade e astúcia, eventualmente encaminhando batedores promissores para mentores como Erion Shadewhisper em Darnassus.",al={"por que jannok está em dolanaar","propósito de jannok brisacanto","por que jannok está aqui"}},f606b9db={q="De que lado está Jannok Brisacanto?",a="Jannok serve a Darnassus e à Aliança. Como instrutor de ladinos elfo noturno estacionado dentro do vilarejo de Dolanaar, sua lealdade reside na nação kaldorei e na defesa de Teldrassil.",al={"facção de jannok brisacanto","a quem jannok serve","lealdade de jannok"}}},fp="17,230,22.506.0,25.156.0,40.221.0,36.137.0"}
P.entries["npc:jasper-fel"] = {n="Jasper Fel",s="Jasper Fel é um fornecedor discreto que opera no quartel-general da AVIN, na Cidade Velha de Ventobravo. Fornecendo adagas e frascos variados a agentes, ele mantém um olhar atento sobre os visitantes e os avisa para cuidarem do que falam. Seu comércio silencioso apoia o braço secreto do reino a portas fechadas.",h="Jasper Fel é um fornecedor discreto que opera no quartel-general da AVIN, na Cidade Velha de Ventobravo.",kw={"adagas","jasper fel","morbídio vil","cidade velha","suprimentos de ladino","avin","ventobravo","frascos"},ang={["class:Rogue"]="Jasper Fel fornece os frascos essenciais e lâminas reservas necessárias para agentes secretos praticarem seu ofício em Ventobravo.",["faction:Alliance"]="Servindo a partir do quartel-general da AVIN, Fel garante que os agentes que defendem o reino das sombras tenham suprimentos confiáveis."},sec={{t="Suprimentos para as Sombras",b="Escondido dentro do quartel da AVIN, na Cidade Velha, Jasper Fel atende a uma clientela muito específica. Em vez de vender armas comuns para a guarda da cidade, ele fornece ferramentas essenciais de espionagem: adagas simples e os frascos delicados necessários para preparar e aplicar venenos. Fel opera sob a rígida disciplina da divisão de inteligência de Mathias Shaw, aconselhando rispidamente quem se aproxima a cuidar do que fala. Em uma fortaleza dedicada à espionagem e à letalidade sutil, conversas casuais são um jeito fácil de encontrar um fim prematuro."}},faq={{q="Onde posso encontrar Jasper Fel?",a="Jasper Fel fica dentro do quartel-general da AVIN, localizado na parte leste de Cidade Velha, em Ventobravo.",al={"localização de jasper fel","onde fica jasper fel","jasper fel ventobravo"}},{q="O que Jasper Fel vende?",a="Ele fornece adagas básicas e vários tipos de frascos vazios, tornando-se uma parada útil para agentes que precisam estocar componentes de veneno.",al={"vendedor jasper fel","o que fel vende","mercadorias de jasper fel"}},{q="Jasper Fel é parente de Morbídio Vil?",a="Eles compartilham o mesmo sobrenome, o que gerou especulações sobre uma ligação familiar com o necromante Morbídio Vil, na Floresta do Crepúsculo, embora o próprio Jasper mantenha silêncio sobre assuntos pessoais.",al={"jasper fel morbidio vil","jasper fel e parente de morbidio","familia vil floresta do crepusculo"}},{q="Por que Jasper Fel avisa as pessoas para falarem baixo?",a="Ele trabalha diretamente dentro da AVIN, o coração do aparato de espionagem de Ventobravo. Falar demais em uma organização cheia de assassinos e espiões é considerado perigoso, e Fel garante que os visitantes tratem o quartel-general com a devida cautela.",al={"por que falar baixo","aviso de jasper fel","palavra errada garganta cortada"}}},fx={["4d6e97a5"]={q="Quem é Jasper Fel?",a="Jasper Fel é um mercador humano discreto que opera a partir de Ventobravo. Infiltrado nas confinadas e secretas vielas da Cidade Velha e mantendo contato próximo com agentes da AVIN, ele fornece suprimentos secretos, frascos e armamentos simples para ladinos e agentes clandestinos que navegam pelo submundo sombrio da cidade.",al={"história de jasper fel","quem é jasper fel","identidade de jasper fel"}},["0dbc34cf"]={q="De que lado está Jasper Fel?",a="Jasper Fel é leal a Ventobravo e à Aliança, operando em estreita coordenação com a rede de inteligência secreta da AVIN. Embora sua persona sombria e avisos perigosos possam sugerir um elemento rebelde, seu comércio apoia diretamente os agentes que servem aos interesses do reino a partir da Cidade Velha.",al={"aliança de jasper fel","a quem jasper fel serve","facção de jasper fel"}},["50a88541"]={q="Por que Jasper Fel está aqui?",a="Posicionado dentro do território da AVIN na Cidade Velha, Jasper Fel serve como um fornecedor discreto para agentes que precisam de Tools of the Trade. Seja fornecendo frascos vazios para a fabricação de venenos ou lâminas básicas para trabalhos silenciosos, ele permanece à disposição para apoiar atividades secretas longe de olhares curiosos.",al={"por que jasper fel está na cidade velha","propósito de jasper fel","por que jasper fel está aqui"}}},fp="10,297,24.536.0,28.115.0,26.134.0,37.178.0,49.240.0"}
P.entries["npc:je-neu-sancrea"] = {n="Je'neu Sancrea",s="Je'neu Sancrea é um troll Lançanegra e membro da Harmonia Telúrica posicionado no Assentamento Zoram'gar, ao longo da costa de Vale Gris. Pressentindo perturbações sombrias nas profundezas sob a costa, ele orienta aventureiros da Horda a investigarem a corrupção que infesta o antigo templo submerso de Profundezas Negras.",h="Je'neu Sancrea é um troll Lançanegra e membro da Harmonia Telúrica posicionado no Assentamento Zoram'gar, ao...",kw={"aku'mai","profundezas negras","harmonia telúrica","je'neu sancrea","jeneu","martelo do crepúsculo","praia de zoram","assentamento zoram'gar"},ang={["class:Shaman"]="Como um proeminente membro Lançanegra da Harmonia Telúrica, Je'neu representa o dever xamânico de pacificar elementais corrompidos e restaurar o equilíbrio das águas de Kalimdor.",["faction:Horde"]="Je'neu serve como o principal centro de missões e guia de história da Horda para adentrar as profundezas de Profundezas Negras a partir de Vale Gris.",["race:Troll"]="Je'neu demonstra como os trolls Lançanegra abraçaram os caminhos espirituais da Harmonia Telúrica ao lado de seus aliados taurens e orcs."},sec={{t="Um Xamã na Praia",b="Enquanto a maior parte da Harmonia Telúrica se concentra na harmonia elemental por toda Kalimdor, Je'neu Sancrea vigia a isolada e perigosa Praia de Zoram. Postado no Assentamento Zoram'gar, ele observa os tremores sombrios e as marés não naturais que se agitam perto do templo em ruínas de Profundezas Negras. Embora vinculado aos deveres xamânicos de seu círculo, sua forte lealdade à tribo Lançanegra e à Horda de Thrall faz com que ele trabalhe exclusivamente ao lado dos campeões da Horda."},{t="Sombras das Profundezas",b="Je'neu busca descobrir a verdadeira causa por trás da corrupção rastejante ao redor da costa. Por meio de aventureiros corajosos, ele coleta núcleos de safira corrompidos, investiga os vestígios vis de elementais da água como O Barão Aquanis e desvenda a influência traiçoeira do Martelo do Crepúsculo. Os rituais sombrios realizados sob as ondas não apenas ameaçam o equilíbrio dos elementos locais, mas também prenunciam o retorno sombrio de forças juradas aos Deuses Antigos."}},faq={{q="Quem é Je'neu Sancrea?",a="Je'neu Sancrea é um xamã troll Lançanegra afiliado à Harmonia Telúrica. Ele está instalado no Assentamento Zoram'gar, na costa de Vale Gris, onde monitora a crescente corrupção que transborda de Profundezas Negras.",al={"quem é jeneu","história de jeneu sancrea","o que é jeneu"}},{q="Por que Je'neu só lida com aventureiros da Horda se ele pertence à Harmonia Telúrica?",a="Embora a Harmonia Telúrica como organização busque o equilíbrio elemental em vez da guerra de facções, os laços pessoais de Je'neu continuam firmemente enraizados na tribo Lançanegra e na Horda. Por residir em um posto militar avançado da Horda em Vale Gris, ele não acolhe viajantes da Aliança.",al={"por que apenas horda","aliança pode falar com jeneu","jeneu é neutro"}},{q="O que Je'neu está investigando em Profundezas Negras?",a="Je'neu investiga a agitação elemental não natural e a magia sombria que emanam de Profundezas Negras. Ele encarrega campeões de recuperar núcleos de água corrompidos, abater cultistas do Martelo do Crepúsculo e confirmar boatos de que uma antiga hidra, Aku'mai, serve a mestres malévolos ancestrais sob o mar.",al={"objetivos de missões de jeneu","o que jeneu quer","por que mandar jogadores para profundezas negras"}},{q="Onde Je'neu Sancrea está localizado?",a="Je'neu está localizado no Assentamento Zoram'gar, um assentamento fortificado da Horda no extremo noroeste da costa de Vale Gris, bem ao longo da Praia de Zoram, logo ao sul de Profundezas Negras.",al={"onde fica jeneu","localização de jeneu sancrea","encontrar jeneu"}},{q="O que é a Harmonia Telúrica?",a="A Harmonia Telúrica é um antigo círculo de xamãs dedicado a compreender e acalmar os espíritos elementais do mundo, intervindo sempre que forças sombrias ou entidades caóticas perturbam a harmonia elemental natural.",al={"história da harmonia telúrica","o que é a harmonia telúrica","organização de xamãs"}},{q="Qual é a ameaça do Martelo do Crepúsculo nas Profundezas?",a="O Martelo do Crepúsculo infiltrou-se em Profundezas Negras para venerar a besta Aku'mai e realizar rituais dedicados aos Deuses Antigos. Je'neu incumbe os aventureiros da Horda de abater seus líderes para conter seu trabalho sombrio.",al={"martelo do crepúsculo profundezas negras","culto do crepúsculo vale gris","quem são os cultistas em profundezas negras"}}},fx={["1670a3c0"]={q="Por que Je'neu Sancrea está aqui?",a="Je'neu posicionou-se no Assentamento Zoram'gar ao longo da costa de Vale Gris para observar a corrupção sinistra que se agita nas ruínas próximas das Profundezas Negras. A Harmonia Telúrica sentiu distúrbios malignos no equilíbrio natural das águas, atraindo-o para esta fronteira para monitorar os cultistas que se reúnem e alistar campeões experientes da Horda para vasculhar as profundezas.",al={"por que je'neu está em vale gris","por que je'neu sancrea está em zoramgar","o que traz je'neu sancrea aqui"}}},fp="14,300,22.452.0,19.449.1,22.215.0,71.296.0,50.299.0,32.174.0,25.212.0,57.225.0"}
P.entries["npc:jen-shan"] = {n="Jen'shan",s="Jen'shan é uma troll da selva Lançanegra e instrutora de caçadores posicionada no Vale das Provações, em Durotar. Ela orienta atiradores orcs e trolls novatos enquanto dão seus primeiros passos nos ermos da Horda. Jovens caçadores são direcionados a ela para aprender o básico sobre rastreamento, combate à distância e sobrevivência.",h="Jen'shan é uma troll da selva Lançanegra e instrutora de caçadores posicionada no Vale das Provações, em...",kw={"lançanegra","durotar","pergaminho cinzelado","tabuleta cinzelada","instrutor de caçadores","jen'shan","jenshan","troll","vale das provações"},ang={["class:Hunter"]="Para jovens caçadores orcs e trolls, Jen'shan é a primeiríssima mentora que você encontra, ensinando técnicas fundamentais de combate à distância antes de você se aventurar além dos desfiladeiros vermelhos d'O Covil.",["race:Troll"]="Jen'shan representa a renomada destreza da tribo Lançanegra em rastreamento e exploração, garantindo que os jovens trolls preservem suas tradições ancestrais de caça em seu novo lar continental."},sec={{t="Mentora das Areias Vermelhas",b="Instalada entre os acampamentos desgastados pelo tempo no Vale das Provações, Jen'shan atua como a principal mentora de caçadores para os novos recrutas que provam seu valor à Horda. Juntos, jovens orcs e Trolls Lançanegra chegam segurando tabuletas e pergaminhos gravados que os guiam direto ao lado dela. Com olhos atentos e afiados por anos na selva indomada, ela transmite técnicas fundamentais de arqueria, pontaria e sobrevivência na natureza, garantindo que nenhum novato seja vítima dos escorpídeos e javalis que rondam o chão do desfiladeiro."}},faq={{q="Quem é Jen'shan?",a="Jen'shan é uma troll da selva Lançanegra e instrutora de caçadores localizada no Vale das Provações, em Durotar. Ela ensina aos caçadores novatos da Horda os conhecimentos básicos da vida selvagem, rastreamento e armas de longo alcance.",al={"história de jenshan","quem é jenshan","instrutor de caçadores do vale"}},{q="Quais missões envolvem Jen'shan?",a="Caçadores novatos são enviados a ela por meio de missões de treinamento introdutórias. Jovens caçadores orcs são direcionados a ela ao entregar uma Tabuleta cinzelada, enquanto jovens caçadores trolls a procuram com um Pergaminho cinzelado.",al={"missões de jenshan","tabuleta cinzelada jenshan","pergaminho cinzelado jenshan"}},{q="Por que há uma troll treinando caçadores em um campo de provas orc?",a="O Vale das Provações serve como campo de provas comum tanto para recrutas orcs quanto para os Trolls Lançanegra desalojados que compartilham Durotar. Como batedores e perseguidores mestres, trolls como Jen'shan desempenham um papel vital na preparação de novos guerreiros e caçadores de ambas as raças para o serviço à Horda.",al={"por que tem um troll no vale das provações","instrutor troll em durotar"}}},fx={["9968b478"]={q="De que lado está Jen'shan?",a="Jen'shan é leal à Horda e ao seu povo, a tribo Lançanegra. Posicionada no Vale das Provações, ela serve ao lado dos orcs para garantir que os novos recrutas, sejam trolls ou orcs, estejam devidamente preparados para as duras realidades de sobreviver em Durotar e lutar pelo Chefe Guerreiro.",al={"facção de jen'shan","jen'shan é da horda","lealdade de jen'shan"}},f50adc74={q="O que Jen'shan quer?",a="Jen'shan busca treinar caçadores iniciantes em pontaria, sobrevivência e nos instintos selvagens necessários para resistir. Ela quer que jovens batedores promissores aprimorem seu ofício rapidamente para que possam lidar com as feras ferozes que vagam pelas terras vermelhas e proteger a nascente Horda de seus inimigos.",al={"motivo de jen'shan","objetivo de jen'shan","do que jen'shan precisa"}},ece1555d={q="A quem Jen'shan está ligada?",a="Jen'shan pertence aos trolls Lançanegra liderados pelo filho de Sen'jin, Vol'jin. Como os Lançanegra compartilham Durotar com os orcs de Thrall, ela trabalha em estreita colaboração com os treinadores do Vale das Provações para orientar os novos recrutas de ambas as raças nas fileiras da Horda.",al={"conexões de jen'shan","laços de jen'shan com os lançanegra","a quem jen'shan serve"}}},fp="8,301,23.520.0,16.198.0,29.199.0,57.280.0"}
P.entries["npc:jennea-cannon"] = {n="Jana Catão",s="Jana Catão é uma respeitada instrutora de magos humana que reside no Sacrário dos Teurgos, no Distrito dos Magos de Ventobravo. Ela supervisiona a educação de feiticeiros novatos, guiando-os através de estudos fundamentais e investigando perturbações no fluxo das energias arcanas locais. Por meio de suas tarefas, ela testa se os aprendizes têm a disciplina necessária para controlar a magia sem serem consumidos por ela.",h="Jana Catão é uma respeitada instrutora de magos humana que reside no Sacrário dos Teurgos, no Distrito dos...",kw={"andromath","blue recluse","jana catão","distrito dos magos","instrutor de magos","lago espelhado","ventobravo","sacrário dos teurgos"},ang={["class:Mage"]="Jana é uma mentora inicial essencial para magos da Aliança, guiando suas primeiras investigações de campo e direcionando você para a confecção de seus trajes e cajado formais de teurgo.",["faction:Alliance"]="Operando a partir do coração do Distrito dos Magos de Ventobravo, Jana garante que os novos feiticeiros do reino sejam disciplinados e capazes de servir à Aliança com segurança."},sec={{t="Um Guia no Sacrário",b="Posicionada no topo da passarela em espiral do Sacrário dos Teurgos, Jana Catão atua como uma das principais mentoras para praticantes arcanos que chegam a Ventobravo. Em vez de simplesmente treinar feitiços exaustivamente com os alunos, ela enfatiza a cautela e o autocontrole. Aos não magos que passam pela torre, ela oferece um aviso incisivo: a magia descontrolada queima os destreinados, uma verdade que os conjuradores novatos aprendem rapidamente sob sua tutela."},{t="Trabalho de Campo e Fundamentos",b="Jana acredita que a teoria mágica deve ser testada pela observação no mundo real. Ela frequentemente envia aprendizes promissores para fora das muralhas da cidade, mandando-os examinar locais como o Lago Espelhado, na Floresta de Elwynn, para entender como as fontes naturais de água interagem com a ressonância arcana. Conforme os alunos avançam, ela testa sua determinação ordenando que investiguem perturbações no Blue Recluse ou coletem reagentes voláteis para criar seus primeiros instrumentos de teurgo autênticos."},{t="Laços com Mestres Maiores",b="Embora Jana cuide da instrução inicial e dos assuntos locais, ela sabe quando um aprendiz superou seu programa de estudos. Quando um iniciado demonstra verdadeiro potencial, ela o encaminha na hierarquia do Sacrário para o High Sorcerer Andromath ou até mesmo além das fronteiras do reino para praticantes reclusos como Tabetha, nas profundezas do Pântano Vadeoso."}},faq={{q="Quem é Jana Catão?",a="Ela é uma instrutora de magos humana situada dentro do Sacrário dos Teurgos, no Distrito dos Magos de Ventobravo, responsável por instruir novos magos e orientar pesquisas mágicas iniciais.",al={"jana catão","quem é jana","instrutor de magos de ventobravo"}},{q="Onde posso encontrar Jana Catão?",a="Ela está localizada dentro do Sacrário dos Teurgos, a torre arcana em espiral situada no centro do Distrito dos Magos em Ventobravo.",al={"localização de jana catão","onde fica jana","encontrar jana"}},{q="Quais missões Jana Catão oferece?",a="Ela oferece missões de classe para magos da Aliança, incluindo investigar o Lago Espelhado na Floresta de Elwynn, averiguar acontecimentos estranhos na taverna Blue Recluse e reunir materiais para confeccionar equipamentos de mago novato.",al={"missões de jana","série de missões de jana catão"}},{q="Por que ela envia magos para o Lago Espelhado?",a="Ela incumbe os aprendizes de buscar uma amostra na base da cachoeira no Lago Espelhado, em Elwynn, para que possa testá-la em busca de máculas mágicas. Ela teme que o fluxo alterado de magia ao redor de Ventobravo e de Elwynn possa estar se infiltrando na água.",al={"por que lago espelhado","missão do lago espelhado jana"}},{q="Jana Catão interage com classes que não sejam magos?",a="Aqueles que não são magos podem falar com ela, mas ela simplesmente dará um conselho severo para terem cautela com a magia, alertando que ela queima quem não possui o treinamento adequado.",al={"não magos podem falar com jana","jana para outras classes"}},{q="A quem Jana Catão responde?",a="Ela trabalha na hierarquia do Sacrário dos Teurgos, orientando estudantes até que estejam prontos para estudar sob a tutela de figuras seniores, como o High Sorcerer Andromath.",al={"superior de jana","líderes do sacrário dos teurgos"}}},fx={b57d5dda={q="De que lado Jana Catão está?",a="Jana serve ao Reino de Ventobravo e à Aliança. Estacionada dentro do Sacrário dos Teurgos, ela trabalha ao lado do círculo de magos de Ventobravo para fortalecer as defesas mágicas da cidade e treinar magos iniciantes leais ao reino.",al={"facção de jana catão","a quem jana catão serve","lealdade de jana catão"}},d154dff8={q="O que Jana Catão deseja?",a="Jana dedica-se a orientar e preparar conjuradores emergentes. Ela busca garantir que os noviços compreendam a natureza perigosa e volátil do arcano, alertando os viajantes de que a magia bruta queimará os destreinados, enquanto direciona estudantes promissores para estudos vitais em todo o reino.",al={"objetivo de jana catão","o que jana quer","propósito de jana catão"}},d5352518={q="Por que Jana Catão está aqui?",a="Ela reside no Sacrário dos Teurgos, no Distrito dos Magos de Ventobravo, para atuar como mentora dos magos da Aliança. Desta torre, ela supervisiona a instrução arcana inicial, examina distúrbios próximos e encaminha praticantes para autoridades superiores, como o High Sorcerer Andromath ou tutores no exterior.",al={"por que jana catão está em ventobravo","jana catão sacrário dos teurgos","por que jana está no distrito dos magos"}}},fp="13,395,22.415.0,24.475.0,23.342.0,21.174.0,31.132.0,37.210.0,39.234.0,50.162.0,33.156.0"}
P.entries["npc:jergosh-the-invoker"] = {n="Jergosh, o Invocador",s="Jergosh, o Invocador é um traiçoeiro orc bruxo escondido nas profundezas de Cavernas Ígneas, sob Orgrimmar. Como um líder de alto escalão entre os cultistas da Searing Blade, ele pratica artes demoníacas bem debaixo do nariz do Chefe de Guerra e conspira contra a Horda.",h="Jergosh, o Invocador é um traiçoeiro orc bruxo escondido nas profundezas de Cavernas Ígneas, sob Orgrimmar.",kw={"invocador","jergosh","orgrimmar","cavernas ígneas","searing blade","shadow council","bruxo"},ang={["class:Warlock"]="Para os bruxos, Jergosh é um poderoso praticante das artes demoníacas cujos esquemas ameaçam a Horda.",["faction:Horde"]="Ter uma célula do Shadow Council prosperando sob a sala do trono do chefe tribal é uma ameaça à segurança intolerável que a Horda não pode se dar ao luxo de ignorar.",["race:Orc"]="Jergosh representa o veneno persistente da antiga Horda — a tentação do sangue demoníaco e da feitiçaria que Thrall se esforça para expurgar da cultura orca."},sec={{t="Um Culto Sob a Cidade",b="Enquanto Thrall trabalha incansavelmente para liderar os orcs por um caminho de honra e xamanismo, Jergosh rejeitou esses ideais em favor do poder demoníaco bruto. Ocultando-se no labirinto subterrâneo de Cavernas Ígneas, sob Orgrimmar, ele reuniu seguidores na Searing Blade, uma seita insidiosa alinhada com os remanescentes do Shadow Council. Operando nas sombras diretamente abaixo da capital da Horda, Jergosh trabalha para desfazer tudo o que Nova Horda representa."},{t="Ambições Demoníacas",b="A presença de Jergosh no abismo está longe de ser um mero perambular sem rumo. Seus rituais sombrios e esquemas perigosos acabaram ficando ousados o suficiente para atrair a atenção direta do próprio Thrall. Jergosh representa uma infecção existencial dentro de Durotar, lembrando à Horda os pactos sombrios que eles lutaram tão desesperadamente para deixar para trás."}},faq={{q="Quem é Jergosh, o Invocador?",a="Jergosh, o Invocador é um poderoso orc bruxo e um líder dos cultistas da Searing Blade que operam dentro de Cavernas Ígneas. Em vez de seguir o caminho honrado de Thrall, ele escolheu abraçar a feitiçaria demoníaca.",al={"quem é jergosh","história de jergosh","jergosh cavernas ígneas"}},{q="Por que Jergosh está escondido em Cavernas Ígneas?",a="Cavernas Ígneas oferece à Searing Blade uma rede isolada de cavernas ardentes diretamente abaixo de Orgrimmar. De lá, Jergosh e seus cultistas podem praticar magia negra proibida e conspirar contra a Horda sem serem detectados.",al={"por que jergosh está sob orgrimmar","história da localização de jergosh"}},{q="A qual facção Jergosh pertence?",a="Jergosh é um líder dentro da Searing Blade, um culto ligado ao Shadow Council e dedicado a servir a interesses demoníacos, como a Legião Ardente.",al={"facção de jergosh","jergosh é do shadow council","líder da searing blade"}},{q="Thrall sabe que Jergosh está sob Orgrimmar?",a="Sim. Os planos de Jergosh tornaram-se perigosos o suficiente para que rumores chegassem a Thrall, levando o Chefe de Guerra a enviar aventureiros de confiança para o abismo a fim de eliminar a ameaça dos cultistas.",al={"thrall jergosh","thrall sabe sobre as cavernas ígneas"}},{q="Por que Jergosh pratica magia vil em vez de xamanismo?",a="Jergosh voluntariamente deu as costas ao ressurgimento espiritual de seu povo, rejeitando a harmonia xamânica para buscar o poder inebriante prometido pela Legião Ardente e pelas artes das trevas.",al={"por que bruxo","jergosh magia vil"}}},fx={["3ff8bf73"]={q="O que Jergosh, o Invocador quer?",a="Jergosh visa minar a Horda dentro de sua própria capital. Rejeitando os ideais xamânicos renovados de Thrall, ele busca reviver práticas demoníacas sombrias e promover as ambições nefastas do Conselho das Sombras. Espreitando no abismo, ele arquiteta planos subversivos perigosos o suficiente para ameaçar a estabilidade da própria Orgrimmar.",al={"objetivo de jergosh","o que jergosh quer","motivo de jergosh"}},["752417a2"]={q="A quem Jergosh, o Invocador está ligado?",a="Jergosh é um líder proeminente entre os cultistas da Lâmina Ardente, um coven subterrâneo operando logo abaixo de Orgrimmar. O culto é secretamente um braço do Conselho das Sombras, vinculando Jergosh diretamente à rede sombria de bruxos e adoradores de demônios que buscam arrastar o povo orc de volta à corrupção.",al={"aliados de jergosh","para quem jergosh trabalha","jergosh conselho das sombras"}},baae249b={q="Por que Jergosh, o Invocador é temido?",a="Jergosh é temido porque exerce magia vil proibida logo abaixo dos pés da liderança da Horda. Seus rituais sombrios, invocações demoníacas e rejeição radical ao caminho da The New Horde representam uma ameaça interna existencial, atraindo a atenção e a preocupação direta do próprio Chefe Guerreiro Thrall.",al={"por que jergosh é temido","jergosh é perigoso","reputação de jergosh"}}},fp="19,250,23.465.0,17.321.1,27.205.0,40.224.0,36.147.0,46.171.0,57.184.0"}
P.entries["npc:jern-hornhelm"] = {n="Jern Elmocorno",s="Jern Elmocorno é um minerador anão afiliado à Explorers' League, estacionado na cidade de Thelsamar. Ele coordena a logística e a comunicação vitais entre o assentamento, Altaforja e o sítio de escavação arqueológica mais adentro em Loch Modan. Aventureiros frequentemente o ajudam a transportar suprimentos de mineração e relatórios de progresso pela região.",h="Jern Elmocorno é um minerador anão afiliado à Explorers' League, estacionado na cidade de Thelsamar.",kw={"pólvora de detonação","escavação","explorers' league","ironband","jern elmocorno","loch modan","minerador","thelsamar"},ang={["faction:Alliance"]="Viajantes da Aliança que passam por Loch Modan consideram Jern um ponto de contato essencial para proteger a região e manter a infraestrutura dos anões.",["profession:Mining"]="Mineradores vão apreciar a experiência profissional de Jern e sua compreensão prática de logística subterrânea, detonações e transporte de recursos.",["race:Dwarf"]="Para os anões, ajudar Jern avança diretamente a missão sagrada de descobrir a antiga herança Titan da raça, enterrada nas profundezas das montanhas."},sec={{t="Logística em Thelsamar",b="Estacionado na rústica cidade de Thelsamar, Jern Elmocorno desempenha um papel logístico fundamental para as operações dos anões por toda Loch Modan. Enquanto estudiosos anões e equipes de campo se aventuram pela natureza selvagem para desenterrar seu passado ancestral, manter cadeias de suprimentos consistentes continua sendo essencial. Jern garante que recursos, ferramentas e comunicações vitais cheguem com segurança aos sítios de escavação ativos."},{t="Servindo à Explorers' League",b="Como membro da Explorers' League, Jern faz a ponte entre os arqueólogos de campo e a liderança da Liga no Hall of Explorers em Altaforja. Locais como Ironband's Excavation dependem fortemente de pólvora de detonação, equipamentos e despachos regulares para manter o trabalho avançando. Jern recruta viajantes confiáveis para navegar pelas estradas infestadas de troggs e manter a escavação totalmente operacional."}},faq={{q="Quem é Jern Elmocorno?",a="Jern Elmocorno é um minerador anão e coordenador de logística baseado em Thelsamar, em Loch Modan. Ele trabalha em nome da Explorers' League para manter os esforços de escavação locais funcionando perfeitamente.",al={"quem é jern","identidade de jern elmocorno","anão de thelsamar jern"}},{q="Onde posso encontrar Jern Elmocorno?",a="Ele pode ser encontrado ao ar livre na cidade de Thelsamar, situada centralmente em Loch Modan ao longo da estrada principal.",al={"localização de jern elmocorno","onde está jern","mapa de jern elmocorno"}},{q="A qual facção Jern Elmocorno pertence?",a="Jern é alinhado com a Aliança e representa especificamente a Explorers' League dos anões, gerenciando a movimentação de pessoal e suprimentos de mineração.",al={"facção de jern elmocorno","para quem jern trabalha","jern é da explorers league"}},{q="Por que Jern precisa que pólvora de detonação seja enviada para a escavação?",a="Escavações arqueológicas no terreno montanhoso exigem demolições controladas para romper paredões de rocha difíceis. Jern coordena a entrega de pólvora de detonação especializada para o sítio de escavação do Prospector Bandaferro para que a equipe possa desenterrar as ruínas antigas a leste do lago.",al={"lore de powder to ironband","por que a escavação precisa de pólvora","pólvora de detonação loch modan"}},{q="Qual é a conexão de Jern Elmocorno com Altaforja?",a="Jern serve como um elo de comunicação vital entre as escavações remotas em Loch Modan e a alta liderança da Explorers' League localizada no Hall of Explorers de Altaforja, enviando frequentemente relatórios de progresso de campo de volta à capital.",al={"jern elmocorno altaforja","report to ironforge jern"}},{q="Quais problemas os sítios de escavação estão enfrentando em Loch Modan?",a="Troggs têm atormentado a Ironband's Excavation e atrasado seu progresso, e as rotas de suprimentos também estão em perigo: uma remessa de pólvora com destino ao local foi emboscada por anões Dark Iron, então Jern depende de aventureiros armados para garantir as entregas.",al={"problemas na ironband's excavation","perigos da escavação em loch modan","por que jern precisa de ajuda"}}},fx={["1cf890d8"]={q="Por que Jern Elmocorno está em Thelsamar?",a="Jern Elmocorno está posicionado em Thelsamar para gerenciar a logística de escavações arqueológicas locais por todo Loch Modan. Trabalhando em apoio à Liga dos Exploradores, ele coordena suprimentos críticos, relatórios e materiais de explosão entre Altaforja e escavações remotas como Ironband's Excavation, garantindo que as operações da Liga permaneçam financiadas e equipadas.",al={"por que jern elmocorno está aqui","propósito de jern elmocorno em loch modan","por que jern está em thelsamar"}}},fp="13,350,22.390.0,29.391.0,21.187.0,31.113.0,42.148.0,58.270.0,48.234.0,53.252.0"}
P.entries["npc:jitters"] = {n="Medrisco",s="Medrisco é um humano trêmulo e recluso que se esconde entre as ruínas de Monte Corvo, no oeste da Floresta do Crepúsculo. Consumido por paranoia e medo constantes, ele sobrevive sozinho na perigosa extremidade oeste da Floresta do Crepúsculo, contando com aventureiros de passagem para obter assistência enquanto observa as sombras invasoras.",h="Medrisco é um humano trêmulo e recluso que se esconde entre as ruínas de Monte Corvo, no oeste da Floresta do...",kw={"tabelião azambuja","cavaleiros das trevas","floresta do crepúsculo","medrisco","monte corvo","o descanso de rolando","foice de elune","noel figueira","worgen"},ang={["class:Rogue"]="Medrisco tem instintos rápidos para evitar perigos, mas eles não o pouparam do terror e do isolamento na Floresta do Crepúsculo.",["faction:Alliance"]="Medrisco representa a face humana da tragédia da Floresta do Crepúsculo, vivendo com medo enquanto a The Night Watch luta para proteger seu povo."},sec={{t="Um Eremita Assombrado",b="Encontrado tremendo em meio às casas dilapidadas de Monte Corvo, Medrisco vive em constante terror dos predadores que espreitam as trilhas do oeste da Floresta do Crepúsculo. Ele depende de aventureiros que passam pelo local para obter sustento simples, desesperado por comida enquanto mantém um olhar frenético sobre as sombras invasoras. Seus maneirismos assustadiços e seu reflexo estranho para saltar para longe de perigos repentinos lhe renderam seu apelido há muito tempo, mas sua paranoia frenética nasceu de encontros diretos com horrores aterrorizantes."},{t="O Despertar em O Descanso de Rolando",b="Medrisco era originalmente afiliado à Irmandade Défias enquanto eles se moviam para a Floresta do Crepúsculo. Enquanto cavava na mina conhecida como O Descanso de Rolando, ele descobriu a Foice de Eluna saindo da rocha. O artefato libertou worgens ferozes e sanguinários na floresta. Medrisco observou horrorizado enquanto seus camaradas eram despedaçados, escapando por pouco do massacre com sua própria pele intacta."},{t="Fuga e a Fazenda",b="Fugindo da mina, Medrisco recuou para Vila Sombria, comprando um tomo em branco do Tabelião Azambuja e narrando febrilmente o pesadelo enquanto se escondia na Scarlet Raven Tavern. Em pânico, ele se refugiou em um celeiro na Fazenda dos Figueira. Lá, ele testemunhou Cavaleiros das Trevas vestidos de negro massacrando a família de Noel Figueira em busca da foice. Aterrorizado por ser culpado ou encontrado, Medrisco enterrou páginas de seu diário no solo e fugiu para Monte Corvo, perseguido por uma culpa paralisante e um pavor incessante."}},faq={{q="Quem é Medrisco?",a="Medrisco é um humano assustado que vive nas ruínas de Monte Corvo. Ele está com fome, isolado e assombrado por suas experiências na Floresta do Crepúsculo.",al={"quem é esse cara","lore de medrisco","histórico de medrisco"}},{q="Por que ele é chamado de Medrisco?",a="Seu apelido originou-se de sua natureza cautelosa, especificamente seu hábito instintivo de se encolher diante de ataques e saltar para longe de armadilhas repentinas. Seu isolamento prolongado e terror absoluto na Floresta do Crepúsculo apenas pioraram seu nervosismo.",al={"por que medrisco","de onde veio o nome dele","origem do nome medrisco"}},{q="Que perigo os worgens representam na Floresta do Crepúsculo?",a="Worgens espreitam as florestas e estradas da Floresta do Crepúsculo, ameaçando viajantes e assentamentos isolados.",al={"ameaça worgen na floresta do crepúsculo","feras perto de medrisco","perigo dos worgens na floresta do crepúsculo"}},{q="O que aconteceu com a família de Noel Figueira?",a="A família de Noel Figueira foi assassinada em sua fazenda, deixando-o determinado a descobrir quem era o responsável.",al={"massacre na fazenda dos figueira","quem matou a família de noel","assassinato na fazenda dos figueira"}},{q="Como Medrisco pode ajudar na investigação de Noel Figueira?",a="O diário de Medrisco registra suas experiências na Floresta do Crepúsculo e pode ajudar Noel a investigar o que aconteceu com sua família.",al={"medrisco e a investigação de noel","como medrisco pode ajudar noel","relato de medrisco sobre a floresta do crepúsculo"}},{q="O que é o diário de Medrisco?",a="Seu diário registra suas experiências na Floresta do Crepúsculo e faz parte da investigação em torno de Monte Corvo e da família de Noel Figueira.",al={"diário de medrisco","diário completo de medrisco","livro do azambuja"}}},fx={["9934be9b"]={q="De que lado está Medrisco?",a="Medrisco é um sobrevivente assustado e faminto que se esconde em Monte Corvo, cujas experiências perturbadoras o deixaram isolado e profundamente abalado.",al={"facção de medrisco","medrisco é mau","para quem medrisco trabalha","lealdade de medrisco"}},["3395ed32"]={q="O que Medrisco quer?",a="Medrisco quer comida e segurança. Sua fome o coloca em contato com aventureiros que investigam os problemas ao redor de Monte Corvo.",al={"do que medrisco precisa","motivo de medrisco","por que medrisco envia você"}},af0d9be3={q="Por que Medrisco está aqui em Monte Corvo?",a="Monte Corvo oferece a Medrisco um esconderijo entre os edifícios abandonados da Floresta do Crepúsculo, embora lhe ofereça pouco conforto ou proteção.",al={"por que medrisco está em monte corvo","como medrisco foi parar aqui","por que medrisco se esconde aqui"}},b49992e9={q="A quem Medrisco está ligado?",a="Sua história se cruza com a investigação de Noel Figueira e os relatos preservados em seu diário.",al={"conexões de medrisco","com quem medrisco é afiliado","medrisco defias"}}},fp="7,282,16.468.0,30.388.1,24.493.1,15.132.1,25.244.0,43.88.1,38.108.1,49.111.1,25.132.1"}
P.entries["npc:jocaste"] = {n="Jocasta",s="Jocasta é uma instrutora de caçadores elfa noturna que reside no verdejante Enclave Cenariano, em Darnassus. Trabalhando ao lado do Círculo Cenariano, ela orienta jovens atiradores e mestres das feras elfos noturnos que chegam das selvas de Teldrassil.",h="Jocasta é uma instrutora de caçadores elfa noturna que reside no verdejante Enclave Cenariano, em Darnassus.",kw={"enclave cenariano","darnassus","instrutor de caçadores","jocasta","caçador elfo noturno","teldrassil"},ang={["class:Hunter"]="Para caçadores elfos noturnos que entram em Darnassus pela primeira vez, Jocasta é uma mentora fundamental que aprimora suas técnicas de combate e ajuda a consolidar o vínculo com seus companheiros animais.",["race:NightElf"]="Enraizada no Enclave Cenariano, Jocasta reflete a estreita harmonia entre os viajantes elfos noturnos, as feras selvagens de Teldrassil e os ensinamentos do Círculo Cenariano."},sec={{t="Uma Mentora no Enclave",b="Instalada entre os bosques tranquilos do Enclave Cenariano em Darnassus, Jocasta atua como instrutora de caçadores elfos noturnos. Quando rastreadores novatos terminam seu treinamento inicial em Umbravale e se aventuram na capital, Jocasta guia sua transição para sobreviventes experientes. Ela ensina as artes da pontaria, da sobrevivência na vida selvagem e o vínculo sagrado entre um caçador e as feras selvagens de Kalimdor."}},faq={{q="Quem é Jocasta?",a="Jocasta é uma instrutora de caçadores elfa noturna localizada dentro do Enclave Cenariano na capital Darnassus, oferecendo instrução e orientação aos praticantes da caça.",al={"história de jocasta","quem é jocasta","jocasta darnassus"}},{q="Onde posso encontrar Jocasta?",a="Ela pode ser encontrada entre as árvores e pavilhões do Enclave Cenariano, no distrito noroeste de Darnassus, nos galhos de Teldrassil.",al={"localização de jocasta","onde fica jocasta","lugar de jocasta"}},{q="Qual papel ela desempenha para os jovens caçadores?",a="Os caçadores direcionados a Darnassus a procuram para aprimorar sua disciplina por meio de tarefas como O caminho do caçador e aprender a treinar e dominar feras selvagens adequadamente.",al={"missões de jocasta","o caminho do caçador jocasta","treinando a fera"}},{q="Jocasta é afiliada ao Círculo Cenariano?",a="Sim. Embora treine caçadores em vez de druidas, ela atua dentro do Enclave Cenariano e acolhe explicitamente os caçadores visitantes na presença do Círculo Cenariano.",al={"jocasta é do círculo cenariano","facção de jocasta"}}},fx={["42c501de"]={q="De que lado está Jocasta?",a="Jocasta está firmemente ao lado de Darnassus, dos Elfos Noturnos e da Aliança como um todo. Posicionada entre o Círculo Cenariano em seu enclave, ela compartilha a dedicação deles em proteger a natureza e guiar aqueles que vivem em harmonia com a vida selvagem.",al={"facção de jocasta","a quem jocasta serve","fidelidade de jocasta"}},["05567dfb"]={q="O que Jocasta quer?",a="Jocasta dedica-se a transmitir as tradições da caça. Ela busca nutrir aspirantes a caçadores em Darnassus, garantindo que eles aprendam a disciplina, a pontaria e o vínculo espiritual necessários para domar e comandar feras a serviço da natureza e de seu povo.",al={"motivo de jocasta","qual é o objetivo de jocasta","propósito de jocasta"}},["1febd3fe"]={q="Por que Jocasta está aqui em Darnassus?",a="Jocasta reside no Enclave Cenariano para oferecer sua sabedoria e treinamento aos caçadores que visitam a capital. Entre as árvores ancestrais de Teldrassil, ela fornece instruções vitais tanto para batedores novatos quanto para rastreadores experientes da vida selvagem.",al={"por que jocasta está em darnassus","por que jocasta está no enclave cenariano"}}},fp="7,230,23.420.0,15.171.0,25.139.0,42.163.0,47.171.0"}
P.entries["npc:john-j-keeshan"] = {n="John J. Keeshan",s="O Cabo John J. Keeshan é um soldado humano do exército de Ventobravo que lutou contra os orcs Rocha Negra nas Montanhas Cristarrubra. Após ser capturado durante os combates ao redor da Bastilha Mirante de Pedra, ele foi arrastado para as profundezas da Rocha dos Laceradores como prisioneiro de guerra.",h="O Cabo John J.",kw={"john j keeshan","keeshan","missing in action","rocha dos laceradores","mirante de pedra"},ang={["class:Warrior"]="Para os guerreiros, Keeshan é um testemunho sombrio dos perigos da frente de Cristarrubra, onde até mesmo soldados experientes podem ser sobrepujados e levados pelo clã Rocha Negra.",["faction:Alliance"]="Keeshan representa o alto custo humano da guerra da Aliança contra os orcs Rocha Negra em Cristarrubra: um soldado feito cativo enquanto mantinha a linha de frente por Ventobravo."},sec={{t="Um Soldado de Cristarrubra",b="John J. Keeshan é um cabo a serviço de Ventobravo, designado para as Montanhas Cristarrubra enquanto os orcs Rocha Negra pressionavam Vila Plácida e seus defensores. Quando a luta se intensificou ao redor da Bastilha Mirante de Pedra, Keeshan estava no meio do conflito ao lado dos outros soldados que mantinham a linha de frente pelo reino."},{t="Cativeiro na Rocha dos Laceradores",b="Quando o clã Rocha Negra avançou para o norte, saindo dos Estepes Ardentes em direção às Montanhas Cristarrubra, Keeshan estava entre os defensores que lutavam pela Bastilha Mirante de Pedra. Sobrepujado pelo ataque orc, ele foi capturado vivo em vez de morto no campo de batalha. Os invasores Rocha Negra levaram-no cativo para as profundezas da Rocha dos Laceradores, deixando o veterano aprisionado atrás das linhas inimigas até que grupos de resgate da Aliança pudessem abrir caminho para libertá-lo."}},faq={{q="Quem é John J. Keeshan?",a="John J. Keeshan é um cabo do exército de Ventobravo que lutou contra os orcs Rocha Negra nas Montanhas Cristarrubra. Durante a batalha ao redor da Bastilha Mirante de Pedra, ele foi capturado e arrastado para a Rocha dos Laceradores.",al={"história de keeshan","quem é keeshan","cabo keeshan"}},{q="Por que Keeshan está aprisionado na Rocha dos Laceradores?",a="Durante a batalha contra o clã Rocha Negra ao redor da Bastilha Mirante de Pedra, Keeshan foi sobrepujado, capturado vivo pelos orcs e levado de volta ao acampamento deles dentro das cavernas da Rocha dos Laceradores.",al={"por que keeshan foi capturado","prisioneiro da rocha dos laceradores","como keeshan foi capturado"}}},fp="15,241,21.304.0,26.444.1,23.198.0,43.192.0"}
P.entries["npc:jonathan-carevin"] = {n="João Carevino",s="João Carevino é um determinado caçador humano que reside em Vila Sombria, dedicado a erradicar a escuridão que assola a Floresta do Crepúsculo. Ao contrário da defensiva Vigília Noturna, ele e sua família caçam ativamente os mortos-vivos, worgens e quaisquer ameaças heréticas que espreitam sob as copas sombrias.",h="João Carevino é um determinado caçador humano que reside em Vila Sombria, dedicado a erradicar a escuridão...",kw={"petrônio","familia carevino","vila sombria","floresta do crepúsculo","joão carevino","a vigilia noturna","mortos-vivos","worgen"},ang={["class:Hunter"]="Caçadores encontram afinidade com o rastreamento proativo de Carevino e seu abate metódico dos predadores noturnos da Floresta do Crepúsculo.",["class:Paladin"]="O zelo de Carevino e sua invocação da Luz contra a corrupção demoníaca e dos mortos-vivos ressoam profundamente com os votos sagrados de um paladino.",["faction:Alliance"]="Para os campeões da Aliança que tentam estabilizar a Floresta do Crepúsculo, João Carevino oferece ataques direcionados contra as ameaças sobrenaturais que a negligência de Ventobravo deixou sem controle."},sec={{t="A Cruzada dos Carevino",b="Enquanto Vila Sombria depende da Vigília Noturna para patrulhar as estradas e proteger o vilarejo, João Carevino acredita que um mero perímetro defensivo é insuficiente. Ao lado de sua família e de aliados como Petrônio, João toma a ofensiva. Ele visa ativamente os seres profanos que vagam pela Floresta do Crepúsculo, conduzindo uma cruzada pessoal para expurgar todos os demônios, mortos-vivos e hereges da região sob a graça da Luz."},{t="A Sombra dos Worgens",b="A vigilância de João se estende além de esqueletos e carniçais cambaleantes. Ele presta muita atenção às feras selvagens e lupinas conhecidas como worgens que espreitam nas profundezas da floresta. Ciente do perigo que representam para um povoado já sitiado, João coordena investigações sobre sua presença misteriosa, buscando descobrir de onde esses predadores ímpios se originaram e pôr fim às suas rondas noturnas."}},faq={{q="Quem é João Carevino?",a="João Carevino é um caçador sombrio que vive em Vila Sombria, na Floresta do Crepúsculo. Ele lidera a família Carevino em uma luta ativa contra os monstros vis que assombram a floresta.",al={"quem e carevino","historia de joao carevino","carevino vila sombria"}},{q="Como ele difere da Vigília Noturna?",a="Enquanto a Vigília Noturna se concentra principalmente em guardar o perímetro de Vila Sombria e manter as estradas transitáveis, João e seus apoiadores rastreiam e caçam ativamente mortos-vivos e outras abominações para erradicá-los em sua origem.",al={"ele e da vigilia noturna","carevino vs vigilia noturna"}},{q="Quais ameaças ele combate?",a="João caça ativamente mortos-vivos, alcateias vorazes de worgens, demônios e qualquer um que ofereça abrigo ou ajuda a tais abominações profanas.",al={"o que carevino caca","alvos de carevino"}},{q="João é afiliado à Cruzada Escarlate?",a="Sua retórica dura, devoção fervorosa à Luz e abordagem rigorosa de tolerância zero contra a corrupção refletem os ideais escarlates, mas oficialmente ele opera de forma independente ao lado de sua família em Vila Sombria.",al={"carevino cruzada escarlate","carevino e escarlate"}},{q="Quem ajuda João em sua missão?",a="Além de sua família imediata, João recebe assistência direta de combatentes solidários, como Petrônio, que o ajuda a rastrear incursões monstruosas pela floresta.",al={"aliados de carevino","quem ajuda carevino"}},{q="Qual é a ligação dele com os worgens?",a="João vê os worgens como uma ameaça antinatural que aterroriza o povo da Floresta do Crepúsculo e incumbe viajantes de descobrir a origem de seu repentino surgimento na natureza selvagem.",al={"carevino worgen","por que carevino odeia worgens"}}},fx={["24497d50"]={q="Por que João Carevino está em Vila Sombria?",a="Vila Sombria é a linha de frente de uma terra mergulhada em sombras, tomada por carniçais, esqueletos e horrores ainda mais sombrios. João Carevino e sua família fizeram de sua permanência aqui uma cruzada pessoal, coordenando ataques contra os mortos-vivos e reunindo quaisquer aventureiros capazes dispostos a pegar em armas contra os terrores que espreitam sob os galhos escurecidos da Floresta do Crepúsculo.",al={"por que carevino está em vila sombria","por que joão carevino está aqui","motivo de carevino na floresta do crepúsculo"}},["8aa9d9d7"]={q="O que João Carevino quer?",a="João Carevino não busca nada menos do que a erradicação completa do mal, da heresia e dos mortos-vivos que assolam a Floresta do Crepúsculo. Diferente da Patrulha Noturna local, que se concentra em manter Vila Sombria segura atrás de linhas defensivas, João acredita em partir para a ofensiva. Ele quer caçar ativamente forças demoníacas e mortas-vivas, purificando a região da corrupção sob o poder justo da Luz.",al={"objetivos de joão carevino","qual é o objetivo de carevino","missão de carevino"}}},fp="16,277,19.410.0,24.412.1,24.160.0,40.231.0,27.137.0,48.203.0,36.171.0,37.170.0"}
P.entries["npc:jorah-annison"] = {n="Jonas Anísio",s="Jonas Anísio é um cartógrafo Renegado estabelecido no Distrito da Magia da Cidade Baixa. Embora sua profissão gire em torno de mapas e geografia, sua experiência se mostra inestimável para conjuradores viajantes em busca de conhecimentos obscuros e dispersos por toda Azeroth.",h="Jonas Anísio é um cartógrafo Renegado estabelecido no Distrito da Magia da Cidade Baixa.",kw={"anísio","cartógrafo","jonas","distrito da magia","mapas","tome of the cabal","cidade baixa","bruxo"},ang={["class:Warlock"]="Jonas é um contato essencial para bruxos da Horda que reúnem o Tome of the Cabal, fornecendo coordenadas vitais para recuperar páginas perdidas pelo mundo.",["faction:Horde"]="Por meio de sua perícia em cartografia, Jonas ajuda aventureiros da Horda a navegar por continentes desconhecidos e a recuperar relíquias valiosas.",["race:Undead"]="Cidadão da Cidade Baixa, Jonas demonstra como as atividades intelectuais dos Renegados, como a cartografia, servem para a sobrevivência mais ampla de seu povo."},sec={{t="Um Erudito de Terras Sombrias",b="Vivendo em meio aos vapores alquímicos e ecos arcanos do Distrito da Magia da Cidade Baixa, Jonas Anísio exerce o ofício da cartografia. No entanto, os mapas o entediam: Jonas trocaria cada um da loja por um único bom livro, e ele sabe mais sobre textos antigos do que quase qualquer pessoa, um gosto erudito que ele compartilha com os bruxos que o procuram."},{t="O Rastro do Cabal",b="O conhecimento que Jonas tem da região se estende muito além das Ruínas de Lordaeron. Bruxos em busca do esquivo Tome of the Cabal são frequentemente direcionados a ele para descobrir onde textos antigos e vestígios de seitas sombrias podem ser resgatados, unindo o conhecimento histórico à geografia distante."}},faq={{q="Quem é Jonas Anísio?",a="Jonas Anísio é um cartógrafo morto-vivo que reside no Distrito da Magia da Cidade Baixa, prestando auxílio a viajantes da Horda com conhecimento geográfico e localizações históricas.",al={"jonas anísio quem","quem é jonas","cartógrafo da cidade baixa"}},{q="Onde posso encontrar Jonas Anísio?",a="Ele fica no Distrito da Magia da Cidade Baixa, a capital subterrânea dos Renegados situada sob as Ruínas de Lordaeron.",al={"localização de jonas anísio","onde fica jonas anísio","encontrar jonas"}},{q="Por que os bruxos precisam falar com ele?",a="Strahad Farsan envia os bruxos que buscam o antigo Tome of the Cabal a Jonas porque ele sabe mais sobre textos antigos do que qualquer um que Strahad conheça. Jonas os orienta em direção às metades perdidas do tomo, que dizem estar com os centauros de Mil Agulhas e perdidas em trânsito na costa a oeste de Costa Sul.",al={"missão de bruxo jonas","tome of the cabal jonas","por que falar com jonas"}},{q="A qual facção Jonas Anísio pertence?",a="Ele é um membro dos Renegados e leal à Horda, servindo a seus irmãos de dentro de sua capital.",al={"jonas é da horda","facção de jonas anísio"}},{q="Jonas Anísio vende mapas diretamente aos jogadores?",a="Jonas atua principalmente como conselheiro e contato de missões relacionadas a marcos esquecidos, e não como um vendedor ativo de mercadorias.",al={"jonas vende mapas","jonas comerciante"}},{q="Jonas Anísio é encontrado alguma vez fora da Cidade Baixa?",a="Embora sua elaboração de mapas e suas orientações de missões envolvam locais distantes, como os Sertões, o próprio Jonas permanece estabelecido no Distrito da Magia da Cidade Baixa.",al={"jonas nos sertões","jonas fora da cidade baixa"}}},fp="13,263,27.341.0,17.292.0,21.169.0,31.134.0,39.296.0,42.107.0,49.123.0,50.157.0"}
P.entries["npc:jordan-stilwell"] = {n="Jardel Calmafonte",s="Jardel Calmafonte é um habilidoso armeiro humano instalado do lado de fora dos nevados Portões de Altaforja, em Dun Morogh. Embora originalmente devesse se tornar um paladino da Luz Sagrada, ele seguiu o ofício de seu pai para se tornar um artesão cujo trabalho serve a paladinos de toda a Aliança. Ele é mais conhecido por forjar o Punho de Verigan em homenagem ao seu velho amigo, Bosch Verigan.",h="Jardel Calmafonte é um habilidoso armeiro humano instalado do lado de fora dos nevados Portões de Altaforja...",kw={"bailor manopedra","bosch verigan","dafne calmafonte","dun morogh","altaforja","jardel calmafonte","bastilha da presa negra","tomo de valor","punho de verigan"},ang={["class:Paladin"]="Jardel Calmafonte é uma figura crucial nas primeiras provações de um paladino, incumbindo-o de vasculhar Azeroth em busca de componentes raros para forjar seu emblemático martelo de guerra, o Punho de Verigan.",["faction:Alliance"]="Tendo fugido dos horrores dos worgens de Arugal na Floresta de Pinhaprata, Jardel encontrou santuário com os anões de Dun Morogh e agora dedica sua arte diretamente aos campeões da Aliança.",["profession:Blacksmithing"]="Treinado pelo anão Bailor Manopedra e empunhando um martelo encantado herdado de seu pai, Jardel representa o ápice da metalurgia sagrada mortal."},sec={{t="Um Chamado na Bigorna",b="Embora se esperasse que Jardel Calmafonte fizesse os votos sagrados e se tornasse um paladino da Igreja da Luz Sagrada, ele acabou escolhendo o caminho da forja. Ele seguiu os passos de seu pai, empunhando o martelo de ferraria encantado dele. Jardel refinou seu ofício sob a tutela do ferreiro anão Bailor Manopedra. Apesar de ter deixado de lado o manto de guerreiro sagrado ungido, Jardel permanece profundamente fiel à Luz, dedicando sua extraordinária habilidade a equipar campeões que lutam em seu nome."},{t="Fuga de Pinhaprata",b="Muito antes de montar sua oficina no frio cortante de Dun Morogh, Jardel serviu como ferreiro na fortaleza do Barão Silverlaine, na Floresta de Pinhaprata. Quando o Arquimago Arugal lançou os worgens ferozes contra a fortaleza, transformando-a no bastião amaldiçoado conhecido como Bastilha da Presa Negra, Jardel conseguiu escapar do massacre. Forçado a abandonar sua forja e seu antigo lar, ele acabou encontrando refúgio entre os anões de Dun Morogh."},{t="A Forja do Punho de Verigan",b="Jardel mantém sua forja ao ar livre, perto dos portões de Altaforja, preferindo o ar alpino revigorante ao calor sufocante da Grande Forja dentro da montanha. Quando a Igreja da Luz Sagrada envia paladinos valorosos até ele, Jardel lhes incumbe de recuperar materiais raros por todo o mundo para forjar um lendário martelo de guerra de duas mãos. Chamada de Punho de Verigan em homenagem ao seu velho amigo Bosch Verigan, a arma é um testemunho do vínculo duradouro entre a fé devotada e o aço magistral."}},faq={{q="Quem é Jardel Calmafonte?",a="Jardel Calmafonte é um mestre ferreiro humano encontrado trabalhando do lado de fora dos Portões de Altaforja, em Dun Morogh. Ele cria armamentos sagrados para paladinos da Igreja da Luz Sagrada, com destaque para o lendário martelo de guerra Punho de Verigan.",al={"quem é jardel calmafonte","história de jardel calmafonte","quem é o ferreiro do lado de fora de altaforja"}},{q="Por que Jardel Calmafonte trabalha do lado de fora na neve em vez de ficar dentro de Altaforja?",a="De acordo com Benedito Brião em Ventobravo, Jardel prefere trabalhar no ar fresco e revigorante da montanha de Dun Morogh em vez do interior sufocante da Grande Forja dentro de Altaforja.",al={"por que jardel fica fora de altaforja","por que trabalhar em dun morogh","por que ele fica na neve"}},{q="Qual é a ligação de Jardel Calmafonte com a Bastilha da Presa Negra?",a="Jardel foi ferreiro e armeiro na propriedade do Barão Silverlaine, na Floresta de Pinhaprata. Ele conseguiu fugir da fortaleza antes ou durante a terrível revolta em que o Arquimago Arugal e seus worgens ferozes massacraram a guarnição e tomaram o local.",al={"jardel calmafonte bastilha da presa negra","jardel calmafonte pinhaprata","ele morava em pyrewood"}},{q="O que é o Punho de Verigan?",a="O Punho de Verigan é um poderoso martelo sagrado de duas mãos forjado por Jardel Calmafonte para os paladinos da Aliança. Ele leva esse nome em homenagem ao velho amigo de Jardel, Bosch Verigan.",al={"punho de verigan","martelo de verigan","quem é verigan"}},{q="Quem treinou Jardel Calmafonte na ferraria?",a="Jardel herdou seu ofício e um martelo de ferraria encantado de seu pai, vindo mais tarde a aprimorar seus conhecimentos sob a instrução do ferreiro anão Bailor Manopedra.",al={"quem treinou jardel calmafonte","mestre de jardel calmafonte","onde ele aprendeu ferraria"}},{q="Quem é a esposa de Jardel Calmafonte?",a="Jardel é casado com Dafne Calmafonte. Juntos, o casal prestou imensa ajuda à Igreja da Luz Sagrada ao longo dos anos, e ambos são reverenciados como servos profundamente devotos da fé.",al={"esposa de jardel calmafonte","marido de dafne calmafonte","dafne calmafonte"}}},fx={["49deb919"]={q="De que lado está Jardel Calmafonte?",a="Jardel é leal inabalavelmente à Aliança e à Igreja da Luz Sagrada. Embora viva entre os anões em Dun Morogh e exerça seu ofício fora de Altaforja, ele permanece profundamente conectado aos paladinos de Ventobravo, dedicando seu trabalho a armar os fiéis contra a escuridão que ameaça o reino.",al={"facção de jardel calmafonte","jardel calmafonte é aliança","lealdade de jardel calmafonte"}}},fp="15,358,22.527.0,22.418.0,22.491.1,23.230.0,78.181.0,56.266.0,23.160.0,45.178.0,30.192.0"}
P.entries["npc:jorgen"] = {n="Jorge",s="Jorge é um informante humano discreto que reside em Ventobravo, escondido perto da água logo na entrada do Vale dos Heróis. Apesar de seu refúgio modesto e afastado, ele está envolvido em assuntos delicados com figuras proeminentes da capital, incluindo Elling Trias e o Bispo DeLavey.",h="Jorge é um informante humano discreto que reside em Ventobravo, escondido perto da água logo na entrada do...",kw={"bispo delavey","elling trias","informante","jorge","diplomata desaparecido","ventobravo","vale dos heróis"},ang={["class:Rogue"]="Jorge representa a rede de sussurros das ruas que prospera sob o mármore imaculado de Ventobravo, intimamente ligada às operações clandestinas conduzidas por meio da Trias' Cheese.",["faction:Alliance"]="Quando os canais oficiais em Ventobravo encontram barreiras burocráticas, informantes de rua confiáveis como Jorge são fundamentais para rastrear ameaças ao reino."},sec={{t="Olhos Perto da Água",b="Posicionado perto da água, imediatamente à direita da entrada monumental de Ventobravo, Jorge mantém a discrição longe das vias movimentadas da cidade. Enquanto as imponentes estátuas de heróis vigiam a ponte acima, Jorge monitora as idas e vindas a partir das sombras abaixo, servindo como um contato silencioso para aqueles que precisam de informações confidenciais."},{t="Uma História Conturbada",b="A presença discreta de Jorge não é por acaso. Ele compartilha um passado conturbado com o mestre queijeiro e coletor de informações Elling Trias, bem como com o Bispo DeLavey da Catedral da Luz. Quando surgem investigações delicadas — como desvendar o desaparecimento de um diplomata enviado a Theramore —, Jorge é um dos poucos contatos locais capazes de apontar a direção certa aos investigadores, desde que saibam como abordá-lo."}},faq={{q="Onde posso encontrar Jorge?",a="Jorge está localizado em Ventobravo, dentro do Vale dos Heróis. Assim que você cruzar os portões da cidade vindo da Floresta de Elwynn, desça em direção à água, à direita da ponte principal.",al={"localização de jorge","onde fica jorge","encontrar jorge"}},{q="A quem Jorge está conectado em Ventobravo?",a="Jorge tem um longo histórico com Elling Trias, o renomado queijeiro do Distrito Comercial com conexões secretas, bem como com o Bispo DeLavey da Catedral da Luz.",al={"conexões de jorge","laços de jorge","quem jorge conhece"}},{q="Qual é o papel de Jorge na investigação do diplomata desaparecido?",a="Durante a busca pelo enviado desaparecido, o Bispo DeLavey envia os investigadores até Jorge, seu velho amigo, com uma carta. Relutante, Jorge concorda em ajudar, faz com que jurem segredo e os encaminha com uma carta selada para Elling Trias na Trias' Cheese.",al={"jorge the missing diplomat","missão de jorge"}},{q="Jorge é afiliado à Guarda de Ventobravo?",a="Não. Jorge atua de forma independente, espreitando longe das patrulhas oficiais da guarda, próximo às margens dos canais, onde conversas discretas podem acontecer longe de ouvidos atentos.",al={"jorge é um guarda","facção de jorge"}}},fx={["536f8488"]={q="Quem é Jorge?",a="Jorge é uma figura sombria que permanece discretamente perto da água no Vale dos Heróis, logo após os grandes portões da frente de Ventobravo. Em vez de servir em qualquer capacidade cívica oficial, ele opera nas margens dos assuntos da capital, possuindo conexões profundas e um passado não revelado ligado estreitamente ao Mestre Elling Trias e ao Bispo DeLavey.",al={"quem é jorge","jorge ventobravo","identidade de jorge"}},["846a3fb1"]={q="Por que Jorge está aqui?",a="Jorge mantém-se nos arredores do Vale dos Heróis para atuar como um ponto de contato discreto dentro de Ventobravo. Posicionado bem perto dos portões da cidade e longe de olhares curiosos, ele permanece disponível para ajudar contatos de confiança como Elling Trias sempre que investigações delicadas e secretas precisarem ser tratadas discretamente.",al={"por que jorge está aqui","motivo da localização de jorge","por que jorge está em ventobravo"}}},fp="6,292,17.374.0,17.434.1,24.180.0,40.174.0,72.247.0,51.161.0"}
P.entries["npc:josef-gregorian"] = {n="Josefo Gregório",s="Josefo Gregório é um instrutor de alfaiataria Renegado encontrado trabalhando no Distrito da Magia de Cidade Baixa. Ele orienta alfaiates ambiciosos da Horda que buscam tecer tecidos encantados, oferecendo conhecimento especializado e direcionando-os para vestimentas especializadas.",h="Josefo Gregório é um instrutor de alfaiataria Renegado encontrado trabalhando no Distrito da Magia de Cidade...",kw={"em busca de materiais","josefo gregório","distrito da magia","vestes de fogo místico","instrutor de alfaiataria","cidade baixa"},ang={["profession:Tailoring"]="Para os alfaiates da Horda, Josefo Gregório é um contato essencial em Lordaeron, oferecendo treinamento a alfaiates e costurando vestes para jovens magos que lhe trazem os materiais.",["race:Undead"]="Gregório demonstra que, apesar da morte e do desmorto, as artes delicadas da alfaiataria humana sobreviveram à queda de Lordaeron para servir à nova sociedade dos Renegados."},sec={{t="Tecelão do Distrito da Magia",b="Em meio às lanternas alquímicas fracas e aos cofres úmidos do Distrito da Magia, Josefo Gregório mantém o nobre ofício da alfaiataria para os Renegados e seus aliados da Horda. Embora a vida no reino subterrâneo tenha se tornado fria, o trabalho com tecidos permanece vital para bruxos, magos e sacerdotes que canalizam energias puras através de fibras tecidas. Gregório atua como um instrutor confiável na capital, pronto para ensinar moldes fundamentais e costurar os primeiros trajes de jovens magos que lhe trazem os materiais adequados."}},faq={{q="Onde posso encontrar Josefo Gregório?",a="Josefo Gregório está localizado no Distrito da Magia de Cidade Baixa, praticando e ensinando o ofício da alfaiataria entre os conjuradores e estudiosos da cidade.",al={"localização de josefo gregório","onde fica gregório","instrutor de alfaiataria de cidade baixa"}},{q="Qual é a função de Josefo Gregório em Cidade Baixa?",a="Ele é um instrutor de alfaiataria que ensina receitas e técnicas de costura aos artífices da Horda. Ele também costura as primeiras vestes de jovens magos enviados a ele por Anastácia Cordato.",al={"o que faz josefo gregório","instrutor josefo gregório","alfaiataria em cidade baixa"}},{q="Quais missões Josefo Gregório oferece?",a="Gregório participa de uma série de missões de mago: Anastácia Cordato envia jovens magos até ele com pano de linho e gemas de mana de Dalaran obtidas em Floresta de Pinhaprata (Em busca de materiais), e ele costura para eles um conjunto de Vestes de Fogo Místico Inferior (Vestes de fogo místico).",al={"missões de josefo gregório","missões de vestes em cidade baixa"}}},fx={d179720d={q="Quem é Josefo Gregório?",a="Josefo Gregório é um artesão morto-vivo que serve como instrutor de alfaiataria dentro do Distrito da Magia da Cidade Baixa. Como muitos artesãos Renegados, ele manteve as habilidades refinadas de sua vida anterior, colocando seu conhecimento de linhas, tecidos e vestimentas encantadas a serviço do povo da Rainha Sylvanas e de seus aliados da Horda.",al={"quem é josefo gregório","lore de josefo gregório","quem é o alfaiate josefo gregório"}},["057f78ac"]={q="De que lado está Josefo Gregório?",a="Ele é leal aos Renegados e à Horda. Estacionado nas profundezas da Cidade Baixa, ele oferece seu conhecimento de alfaiataria, moldes e sabedoria comercial exclusivamente para aqueles que servem à Dama Sombria e à Horda.",al={"facção de josefo gregório","josefo gregório é horda","a quem josefo gregório serve"}},["3b87a245"]={q="Por que Josefo Gregório está na Cidade Baixa?",a="Josefo permanece na Cidade Baixa para praticar e instruir outros no ofício da alfaiataria. Montar sua oficina entre os conjuradores e estudiosos do Distrito da Magia permite que ele teça mantos, vestimentas encantadas e armaduras de tecido para aventureiros que se aventuram nas Terras Pestilentas e além.",al={"por que josefo gregório está aqui","o que trouxe josefo gregório para cidade baixa","por que josefo está no distrito da magia"}}},fp="15,238,27.506.0,33.148.0,54.169.0,39.241.0"}
P.entries["npc:kaal-soulreaper"] = {n="Kaal Ceifalma",s="Kaal Ceifalma é um instrutor de bruxos orc localizado nas profundezas do Distrito da Magia da Cidade Baixa. Apesar de habitar entre os Renegados, ele mantém laços estreitos com outros praticantes das artes sombrias por toda a Horda, frequentemente guiando aprendizes a mentores em terras distantes.",h="Kaal Ceifalma é um instrutor de bruxos orc localizado nas profundezas do Distrito da Magia da Cidade Baixa.",kw={"demonologia","corcel vil","kaal ceifalma","distrito da magia","menara nihila","cidade baixa","instrutor de bruxos"},ang={["class:Warlock"]="Kaal Ceifalma fornece treinamento essencial em artes demoníacas e coloca bruxos ambiciosos nos caminhos necessários para criar o Orb of Orahil e aprisionar um Corcel Vil.",["race:Orc"]="Ao contrário do conciliábulo oculto na A Fenda das Sombras, Kaal opera abertamente dentro da capital dos Renegados, longe dos olhos vigilantes da liderança xamânica de Orgrimmar."},sec={{t="Um Praticante nas Sombras",b="Enquanto a Horda de Thrall regula e monitora rigorosamente a magia vil dentro de Orgrimmar, praticantes como Kaal Ceifalma encontram amplo refúgio nos santuários subterrâneos de Lordaeron. Residindo no Distrito da Magia da Cidade Baixa, Kaal compartilha seu domínio sobre entidades demoníacas e maldições com bruxos da Horda dispostos a aprender. Além da instrução básica, ele atua como um contato essencial para praticantes que buscam maior poder, direcionando estudantes ambiciosos através do oceano para mentores como Menara Nihila nos Sertões."}},faq={{q="Quem é Kaal Ceifalma?",a="Kaal Ceifalma é um instrutor de bruxos orc que reside no Distrito da Magia da Cidade Baixa. Ele ensina feitiços de bruxo e oferece orientação a praticantes que buscam rituais e artefatos sombrios especializados.",al={"quem é kaal","história de kaal ceifalma","kaal cidade baixa"}},{q="Por que um bruxo orc está vivendo na Cidade Baixa?",a="Os bruxos enfrentam forte suspeita e escrutínio na sociedade orca sob o comando do Chefe Guerreiro Thrall. A Cidade Baixa oferece um ambiente muito mais tolerante para estudar Shadow Magic e demonologia ao lado dos Renegados.",al={"por que um orc está na cidade baixa","por que kaal está na cidade baixa"}},{q="Para onde Kaal Ceifalma envia seus aprendizes?",a="Quando seus estudantes alcançam maestria suficiente, Kaal os direciona através d'O Grande Oceano para os Sertões para estudar com Menara Nihila, ou os apresenta a outros bruxos proeminentes da Horda.",al={"missões de kaal","para quem kaal envia você"}}},fx={["17865f78"]={q="De que lado está Kaal Ceifalma?",a="Kaal Ceifalma está firmemente ao lado da Horda. Embora seja um orc residindo na Cidade Baixa ao lado dos Renegados, ele treina bruxos que juram lealdade à causa da Horda. Ele mantém laços diretos com outros praticantes da Horda por toda Kalimdor e os Reinos do Leste, incluindo bruxos nos Sertões e em Vila Catraca, garantindo que aqueles que praticam artes das sombras continuem direcionando seu poder vil para ajudar seus aliados.",al={"facção de kaal ceifalma","a quem kaal ceifalma serve","kaal ceifalma é horda"}},["78b7a2d4"]={q="O que Kaal Ceifalma deseja?",a="Kaal busca guiar aspirantes a bruxos pelo caminho perigoso da maestria demoníaca. Em vez de deixar praticantes inexperientes sucumbirem aos poderes corruptores da Espiral Etérea, ele garante que eles aprendam os rituais necessários para invocar e subjugar demônios, como o corcel vil, e direciona estudantes promissores para mestres habilidosos como Menara Nihila para aprofundar seu ofício.",al={"motivo de kaal ceifalma","objetivo de kaal ceifalma","o que kaal ceifalma está fazendo"}},["0c3c6935"]={q="A quem Kaal Ceifalma está ligado?",a="Kaal mantém laços estreitos com outros mentores bruxos pelos continentes. Ele frequentemente orienta praticantes capazes a procurar Menara Nihila nos Sertões para treinamento especializado, rituais avançados e a obtenção de artefatos como o Orbe de Orahil.",al={"conexões de kaal ceifalma","com quem kaal ceifalma trabalha","aliados de kaal ceifalma"}}},fp="15,279,29.516.0,23.195.0,46.201.0,48.185.0"}
P.entries["npc:kadrak"] = {n="Kadrak",s="Kadrak é um comandante orc experiente destacado na Paliçada Mor'shan, na fronteira entre os Sertões e Vale Gris. Encarregado de proteger a fronteira norte, ele coordena o fluxo de despachos e reforços para a floresta disputada. Para os aventureiros da Horda que avançam além das planícies áridas, Kadrak serve como a porta de entrada para a luta contínua contra os elfos noturnos.",h="Kadrak é um comandante orc experiente destacado na Paliçada Mor'shan, na fronteira entre os Sertões e Vale...",kw={"vale gris","sertões","kadrak","paliçada mor'shan","orc","paliçada","posto machadada","warsong"},ang={["class:Warrior"]="Kadrak personifica a disciplina da linha de frente, contando com aço bruto e força marcial para manter um ponto de estrangulamento fortificado contra táticas hostis da floresta e ataques de guerrilha.",["faction:Alliance"]="Para as forças da Aliança que tentam atacar os Sertões a partir de Vale Gris, Kadrak e sua paliçada representam um bloqueio fortificado que protege o coração da Horda.",["faction:Horde"]="Kadrak é o seu ponto de entrada para as campanhas de Vale Gris, direcionando o fluxo de guerreiros para o norte a fim de defender operações madeireiras e conquistar território para a Horda.",["race:Orc"]="Como um veterano obstinado que mantém o legado dos esforços territoriais do Warsong Clan, Kadrak representa a determinação inabalável dos orcs na fronteira de Vale Gris."},sec={{t="Guardião da Paliçada",b="Do alto das barricadas de madeira fortificadas da Paliçada Mor'shan, Kadrak vigia a rota principal que liga os Sertões a Vale Gris. A fronteira é um limite precário: ao sul ficam as planícies calcinadas pelo sol reivindicadas pela Horda, enquanto ao norte erguem-se os bosques ancestrais ferozmente guardados pelos elfos noturnos. Kadrak garante que o perímetro defensivo permaneça intacto contra Sentinels invasoras e criaturas hostis da floresta."},{t="Logística da Linha de Frente",b="Além de manter a linha, Kadrak gerencia informações militares essenciais entre os Sertões e os acampamentos madeireiros avançados no interior da floresta. Ele recebe mensageiros com relatórios de combate cruciais dos Pioneiros do Brado Guerreiro e coordena a movimentação de suprimentos e sangue novo para entrepostos como o Posto Machadada. Aqueles que se reportam a ele são prontamente direcionados para o coração da guerra territorial."}},faq={{q="Quem é Kadrak?",a="Kadrak é um oficial orc destacado na Paliçada Mor'shan. Ele supervisiona a segurança da fronteira e direciona as forças da Horda que viajam entre os Sertões e as zonas de guerra de Vale Gris.",al={"identidade de kadrak","quem é o orc na muralha","comandante da paliçada mor'shan"}},{q="Onde Kadrak pode ser encontrado?",a="Kadrak fica na Paliçada Mor'shan, a barricada de madeira fortificada no extremo norte dos Sertões, marcando o limite que leva a Vale Gris.",al={"localização de kadrak","encontrar kadrak","onde fica kadrak"}},{q="Qual é o papel de Kadrak na Horda?",a="Ele comanda o perímetro defensivo na fronteira, reúne informações militares de batedores e orienta os viajantes da Horda que seguem para o norte a fim de reforçar postos avançados como o Posto Machadada.",al={"deveres de kadrak","o que kadrak faz","papel de kadrak"}},{q="Por que a Paliçada Mor'shan é fortemente defendida?",a="A Paliçada protege os acessos ao norte dos Sertões e de Durotar contra incursões retaliatórias de elfos noturnos provocadas pelas operações madeireiras da Horda em Vale Gris.",al={"por que a paliçada mor'shan é fortificada","propósito da paliçada","por que proteger a fronteira de vale gris"}},{q="Quais missões Kadrak oferece ou conclui?",a="Kadrak recebe relatórios trazidos dos Sertões e despacha aventureiros em missões referentes a relatórios de reconhecimento de Warsong e ao estabelecimento de uma Horde Presence mais firme ao longo da fronteira da floresta.",al={"missões de kadrak","report to kadrak","the warsong reports"}},{q="Kadrak tem ligações com outras figuras notáveis da Horda?",a="Kadrak mantém comunicação regular com os Pioneiros do Brado Guerreiro que operam em Vale Gris, recebendo seus relatórios de reconhecimento na Paliçada.",al={"conexões de kadrak"}}},fx={e1636f20={q="De que lado está Kadrak?",a="Kadrak é um guerreiro leal da Horda. Estacionado na fronteira acidentada entre os Sertões e as florestas disputadas do Vale Gris, ele serve sob o estandarte do Chefe Guerreiro, dedicado a garantir os interesses dos orcs e defender os postos avançados da Horda contra incursões dos elfos noturnos.",al={"facção de kadrak","kadrak é horda","a quem kadrak serve"}},["4dfee007"]={q="O que Kadrak deseja?",a="Kadrak visa manter a fronteira norte dos Sertões e expandir a presença da Horda mais profundamente no Vale Gris. Enfrentando uma resistência feroz dos elfos noturnos, ele busca recrutar campeões capazes da Horda para levar relatórios, aliviar batedores sitiados e proteger linhas de suprimentos vitais através da Paliçada Mor'shan.",al={"qual o objetivo de kadrak","motivo de kadrak","o que kadrak precisa"}},["86a4d862"]={q="Por que Kadrak está aqui na Paliçada Mor'shan?",a="Kadrak faz guarda na Paliçada Mor'shan porque é o ponto de estrangulamento vital que protege os Sertões das florestas hostis do Vale Gris. À medida que as hostilidades com os elfos noturnos aumentam, ele coordena defesas, monitora a atividade inimiga e direciona batedores para reforçar os postos avançados do Cantoguerra ao norte.",al={"por que kadrak está na paliçada","motivo da localização de kadrak","por que kadrak está estacionado aqui"}}},fp="6,379,23.447.0,19.406.0,14.173.0,26.155.0,35.187.0,45.165.0,44.190.0,53.142.0"}
P.entries["npc:kaela-shadowspear"] = {n="Kaela Umbralança",s="Kaela Umbralança é uma sentinela elfa noturna posicionada a sudoeste do Rochedo Cortavento, na Cordilheira das Torres de Pedra. De seu pequeno entreposto, ela se coordena com outras sentinelas para monitorar a escalada de tensões e perturbações regionais na natureza. Ela conta com viajantes corajosos para patrulhar territórios perigosos e descobrir o que corrompeu os antigos defensores da terra.",h="Kaela Umbralança é uma sentinela elfa noturna posicionada a sudoeste do Rochedo Cortavento, na Cordilheira...",kw={"ancestrais","kaela","deuxabu","sentinela","umbralança","espíritos","cordilheira das torres de pedra","thenysil","cortavento"},ang={["class:Druid"]="Os druidas encontrarão um propósito em comum com os esforços de Kaela para descobrir o que corrompeu os ancestrais do Vale e silenciar a agonia dos espíritos perturbados da natureza.",["faction:Alliance"]="Kaela Umbralança atua como um ponto de contato crucial para aventureiros da Aliança que se aventuram pelos confins disputados da Cordilheira das Torres de Pedra, coordenando informações entre postos avançados distantes.",["race:NightElf"]="Para os elfos noturnos, Kaela representa a defesa inabalável do solo sagrado, empenhando-se para acalmar espíritos enfurecidos e proteger os reverenciados ancestrais de Kalimdor."},sec={{t="Uma Batedora na Fronteira",b="Posicionada logo a sudoeste da devastação industrial do Rochedo Cortavento, Kaela Umbralança mantém uma vigília atenta sobre as passagens ao redor. A Cordilheira das Torres de Pedra é repleta de perigos à medida que a Horda invade e as operações dos goblins exploram as riquezas naturais da terra. Operando ao lado do gnomo Gaxim Deuxabu, Kaela atua como uma ligação avançada essencial para os elfos noturnos, rastreando ameaças que avançam ainda mais pelo território ancestral."},{t="Curando a Terra",b="A agitação na Cordilheira das Torres de Pedra vai muito além de escaramuças territoriais. A violenta perturbação da natureza enfureceu os elementais e feriu antigos guardiões da floresta. Kaela trabalha incansavelmente para enviar aventureiros contra espíritos elementais enfurecidos e descobrir o que corrompeu os ancestrais feridos, os arvorescentes que outrora protegiam o Vale, lutando para restaurar a paz antes que a terra seja irrevogavelmente marcada."}},faq={{q="Quem é Kaela Umbralança?",a="Kaela Umbralança é uma elfa noturna concedente de missões posicionada em um acampamento de fronteira a sudoeste do Rochedo Cortavento, na Cordilheira das Torres de Pedra. Ela supervisiona o reconhecimento regional e ajuda a proteger a fauna e os espíritos locais.",al={"quem é kaela","identidade de kaela umbralança","pds kaela"}},{q="Onde Kaela Umbralança pode ser encontrada?",a="Ela está localizada em um pequeno acampamento da Aliança situado a sudoeste do Rochedo Cortavento, ao longo da estrada na Cordilheira das Torres de Pedra, dividindo o acampamento com o engenheiro gnomo Gaxim Deuxabu.",al={"localização de kaela umbralança","onde fica kaela","acampamento de kaela na cordilheira das torres de pedra"}},{q="A quem Kaela se reporta?",a="Kaela se coordena de perto com a Sentinela Tenysil, enviando e recebendo relatórios regulares de inteligência sobre movimentações inimigas e ameaças locais por toda a Cordilheira das Torres de Pedra.",al={"a quem kaela se reporta","kaela thenysil","comandante de kaela"}},{q="Por que Kaela está preocupada com os elementais?",a="Quando a Empreendimentos S.A. incendiou o Vale Carbonizado e o devastou com suas máquinas, eles libertaram espíritos ardentes — elementais de chamas, pedra e fúria — que agora vagam pelo Vale. Kaela quer que seus números sejam reduzidos para que a terra possa se recuperar.",al={"missão enraged spirits","por que os espíritos estão zangados","kaela espíritos elementais"}},{q="O que está acontecendo com os ancestrais perto do Rochedo Cortavento?",a="Os arvorescentes que protegem o Vale Carbonizado ajudaram a repelir a Empreendimentos S.A., mas desde então foram corrompidos. Gaxim suspeita que as armas dos goblins sejam as culpadas, então Kaela pede que os viajantes tragam um pedaço de estilhaços corroídos de um arvorescente ferido para que ele possa estudar.",al={"missão wounded ancients","kaela ancestrais","cordilheira das torres de pedra wounded ancients"}},{q="Por que há um gnomo estacionado com Kaela?",a="Kaela divide seu acampamento com Gaxim Deuxabu, um gnomo da Aliança. Enquanto Kaela se concentra no equilíbrio espiritual e tático da natureza, Gaxim está empenhado em combater o maquinário e as operações hostis dos goblins nas proximidades.",al={"gaxim deuxabu kaela","por que gaxim está com kaela","acampamento de gnomo e elfo noturno"}}},fx={e879ebe3={q="De que lado está Kaela Umbralança?",a="Kaela está firmemente ao lado dos elfos noturnos e da Aliança. Estacionada na Cordilheira das Torres de Pedra, ela serve a Darnassus e ao comando das sentinelas, coordenando-se de perto com outros batedores da Aliança para defender a terra contra adversários invasores.",al={"facção de kaela umbralança","kaela é aliança","lealdade de kaela umbralança"}},bb8cec73={q="Por que Kaela Umbralança está aqui?",a="Kaela está posicionada a sudoeste do Rochedo Cortavento como uma batedora sentinela. Deste posto, ela monitora perturbações por toda a Cordilheira das Torres de Pedra, particularmente a situação dos espíritos locais corrompidos e o sofrimento dos anciões próximos.",al={"por que kaela umbralança está na cordilheira das torres de pedra","missão de kaela umbralança","por que kaela está aqui"}},["6c46a0c6"]={q="O que Kaela Umbralança quer?",a="Kaela visa proteger a Cordilheira das Torres de Pedra da devastação. Ela busca reduzir os espíritos elementais enfurecidos que a Empreendimentos S.A. libertou, descobrir o que corrompeu os Wounded Ancients do Vale Carbonizado e manter seus comandantes informados sobre as ameaças da região.",al={"objetivo de kaela umbralança","o que kaela quer","objetivos de kaela"}}},fp="17,363,23.446.0,16.417.0,25.216.0,37.179.0,25.158.0,44.235.0,54.268.0,36.230.0"}
P.entries["npc:kali-remik"] = {n="Kali Remik",s="Kali Remik é uma caçadora troll Lançanegra que dedica seu tempo a orientar viajantes pelo coração da Horda. Familiarizada com os métodos de rastreamento e sobrevivência em Durotar, ela direciona jovens caçadores a Thotar, no Monte Navalha, para aprenderem a domar feras.",h="Kali Remik é uma caçadora troll Lançanegra que dedica seu tempo a orientar viajantes pelo coração da Horda.",kw={"lançanegra","durotar","kali remik","aldeia sen'jin","the hunter's path","rastreador","vale dos espíritos"},ang={["class:Hunter"]="Para jovens atiradores orcs e trolls, Kali atua como um degrau, reconhecendo quando suas habilidades superam os exercícios da aldeia e enviando você adiante para Thotar no Monte Navalha.",["race:Troll"]="Como um membro da tribo Lançanegra, Kali vigia seus parentes enquanto eles reconstroem suas vidas ao longo da costa de Durotar e se estabelecem no Vale dos Espíritos de Orgrimmar."},sec={{t="Um Guia para a Caçada",b="Kali Remik é uma rastreadora troll da selva experiente, bem familiarizada com os ermos áridos de Durotar e os movimentados centros da Horda. Em assentamentos costeiros como a Aldeia Sen'jin, ela supervisiona jovens batedores que estão dando seus primeiros passos fora do Vale das Provações. Sabendo quando um novato supera os campos de treinamento locais, ela intervém para direcionar atiradores promissores a Thotar, no Monte Navalha, para começarem seu caminho como mestres das feras, garantindo que as fileiras de fronteira da Horda permaneçam afiadas e disciplinadas."}},faq={{q="Quem é Kali Remik?",a="Kali Remik é uma batedora troll Lançanegra e doadora de missões. Ela ajuda a guiar aventureiros iniciantes da Horda, especialmente caçadores prontos para avançar seu treinamento além dos postos avançados locais.",al={"lore de kali remik","quem é kali remik","npc kali remik"}},{q="Onde Kali Remik pode ser encontrada?",a="Ela pode ser encontrada ajudando seu povo em Durotar, notavelmente ao redor da Aldeia Sen'jin.",al={"onde está kali remik","localização de kali remik","encontrar kali remik"}},{q="Que orientação ela oferece aos caçadores?",a="Por meio de 'O Caminho do Caçador', Kali direciona jovens caçadores orcs e trolls que provaram suas habilidades básicas a viajar para o Monte Navalha, onde Thotar os coloca no caminho para domar sua própria fera companheira.",al={"missão o caminho do caçador","missão de caçador de kali remik","o que kali ensina"}}},fx={f072d80b={q="De que lado está Kali Remik?",a="Kali Remik é leal à tribo Lançanegra e está firmemente ao lado da Horda de Thrall. Ela ajuda seu povo e seus aliados guiando jovens batedores e atiradores da selva em direção ao treinamento adequado e ao serviço para sua nova terra natal.",al={"facção de kali remik","a quem kali remik serve","kali remik horda"}},bd47d9e0={q="Por que Kali Remik está na Aldeia Sen'jin?",a="Kali Remik permanece na Aldeia Sen'jin para zelar pelos defensores emergentes da tribo Lançanegra. Nestes baixios costeiros, ela ajuda a identificar jovens caçadores promissores entre os orcs e trolls que passam por lá, direcionando-os aos mentores que podem aprimorar suas habilidades de sobrevivência.",al={"por que kali remik está aqui","papel de kali remik na aldeia sen'jin","o que trouxe kali remik para cá"}},a3912784={q="O que a Kali Remik quer?",a="Kali Remik quer ver Durotar protegida por batedores e rastreadores capazes. Ela procura caçadores aspirantes para garantir que não vaguem despreparados, indicando-lhes os caminhos certos para encontrar os treinadores que podem ensinar-lhes os modos da vida selvagem.",al={"o que kali remik quer","motivo de kali remik","qual é o objetivo de kali remik"}},["528bbb7d"]={q="A quem Kali Remik está ligada?",a="Ela está estreitamente ligada aos Trolls Lançanegra da Aldeia Sen'jin e trabalha em conjunto com os treinadores de caçadores de Durotar. Seus deveres a ligam à rede de sobrevivência mais ampla da Horda, garantindo que os novos recrutas se conectem com mentores estabelecidos por todo o território.",al={"a quem kali remik está ligada","conexões de kali remik","aliados de kali remik"}}},fp="10,259,20.489.0,18.173.0,30.78.0,40.206.0"}
P.entries["npc:kaltunk"] = {n="Kaltunk",s="Kaltunk é um feitor orc posicionado no coração do Vale das Provações em Durotar. Ele serve como o primeiríssimo ponto de contato para jovens orcs dando seus passos iniciais no mundo. É seu dever receber esses aspirantes a campeões e direcioná-los aos seus primeiros deveres a serviço da Horda.",h="Kaltunk é um feitor orc posicionado no coração do Vale das Provações em Durotar.",kw={"durotar","gornek","kaltunk","início orc","vale das provações","your place in the world"},ang={["faction:Horde"]="Kaltunk ajuda a manter a disciplina prática necessária para preservar a ordem no rigoroso campo de testes de Durotar.",["race:Orc"]="Para cada orc adentrando Kalimdor, as instruções ríspidas de Kaltunk são as primeiras palavras ouvidas ao começarem a conquistar sua honra."},sec={{t="O Primeiro Passo",b="Sob o sol implacável do Vale das Provações, Kaltunk vigia os recém-chegados que buscam provar que são dignos da Horda. Enquanto outros instrutores e anciãos determinam provações extenuantes e ritos de caça, Kaltunk garante que nenhum recruta vagueie sem rumo pela poeira vermelha. Ele dá ordens diretas, apontando os novatos diretamente para Gornek e o caminho da disciplina."},{t="Guardião do Vale",b="O Vale das Provações não é um campo de testes fácil; ele foi escolhido especificamente para forjar força e resiliência em cada jovem que caminha pelo chão de seus desfiladeiros. Kaltunk personifica essa praticidade rústica. Ele não oferece discursos grandiosos nem bajulação, esperando que cada orc encontre rapidamente seu lugar no mundo e cumpra seu papel para com o chefe de guerra."}},faq={{q="Quem é Kaltunk?",a="Kaltunk é um feitor orc posicionado no Vale das Provações. Ele é a primeiríssima pessoa que aventureiros orcs recém-despertos encontram, incumbido de apontá-los para seus mentores e iniciar seu treinamento.",al={"papel de kaltunk","quem é este orc","pnc kaltunk"}},{q="O que Kaltunk faz por novos aventureiros?",a="Ele dá aos novos recrutas sua tarefa inicial, orientando-os a falar com Gornek em outra parte do vale para que seu verdadeiro treinamento possa começar.",al={"missão de kaltunk","o que kaltunk quer","primeira missão vale das provações"}},{q="Onde posso encontrar Kaltunk?",a="Ele fica bem próximo à tenda de treinamento central e à fogueira dentro do Vale das Provações, a área inicial isolada no sul de Durotar.",al={"localização de kaltunk","encontrar kaltunk","onde fica kaltunk"}},{q="Por que ele está posicionado no Vale das Provações?",a="Ele atua como um feitor de recepção para garantir que os recrutas orcs que chegam sejam organizados e prontamente encaminhados para o serviço à Horda de Thrall.",al={"por que kaltunk está aqui","propósito de kaltunk"}}},fx={["7b0fd1f8"]={q="De que lado Kaltunk está?",a="Kaltunk serve a Horda e permanece firmemente sob a autoridade do Chefe Guerreiro Thrall. Ele está posicionado no Vale das Provações especificamente para dar as boas-vindas aos novos recrutas orcs e guiar seus primeiros passos no serviço à nova nação de Durotar.",al={"facção de kaltunk","a quem kaltunk serve","kaltunk é da horda"}},["5cbb3fad"]={q="O que Kaltunk quer?",a="Kaltunk quer que você prove seu valor à Horda. Ele garante que os recém-chegados não testados não fiquem ociosos, direcionando você imediatamente a Gornek e aos supervisores no Vale das Provações para que seu treinamento e serviço a Durotar possam começar sem demora.",al={"do que kaltunk precisa","objetivo de kaltunk","motivo de kaltunk"}}},fp="7,304,14.402.0,20.339.0,15.207.0,41.135.0,25.139.0,44.142.0"}
P.entries["npc:kam-deepfury"] = {n="Kam Fundafúria",s="Kam Fundafúria é um infame sabotador Ferro Negro encarcerado nas profundezas do Cárcere de Ventobravo. Ao contrário da maioria dos detentos da prisão, ele não tem lealdade à Irmandade Défias, tendo sido capturado por planejar uma explosão devastadora na Ponte Thandol, bem mais ao norte.",h="Kam Fundafúria é um infame sabotador Ferro Negro encarcerado nas profundezas do Cárcere de Ventobravo.",kw={"ferro negro","fundafuria","dun modr","garmason","kam fundafúria","trancalonga","carcere","ventobravo","ponte thandol"},ang={["faction:Alliance"]="Enquanto a maioria dos olhares em Ventobravo está voltada para a revolta dos Défias, Fundafúria é um lembrete da ameaça mais ampla dos Ferro Negro assombrando as fronteiras ao norte da Aliança.",["race:Dwarf"]="Para os anões de Altaforja, Kam Fundafúria é um inimigo implacável cuja sabotagem rompeu a Ponte Thandol e assassinou o parente de Trançalonga, o Austero. Vingar essa perda é uma questão de honra pessoal."},sec={{t="Um Sabotador Longe de Casa",b="Embora o Cárcere esteja amplamente repleto de pedreiros descontentes e rebeldes Défias, Kam Fundafúria se destaca. Um anão Ferro Negro astuto e violento, Fundafúria foi capturado e levado para Ventobravo após arquitetar uma operação que paralisou uma infraestrutura vital do norte. Ele está trancafiado nas profundezas das celas da prisão, isolado de seus semelhantes sob a Montanha Rocha Negra, mas tão hostil à Aliança quanto qualquer rebelde amotinado dividindo os corredores."},{t="A Sabotagem da Ponte Thandol",b="A inteligência da Aliança estacionada em Dun Modr, perto da fronteira norte do Pantanal, identificou Fundafúria como o principal arquiteto por trás da explosão que destruiu a Ponte Thandol. A detonação rompeu uma das imensas pontes de pedra que ligavam o Pantanal ao Planalto Arathi. Além de paralisar uma rota comercial e militar crucial para Altaforja e a Aliança, a sabotagem tirou a vida de um parente do comandante anão Trançalonga, o Austero."},{t="Um Acerto de Contas",b="O insurgente Ferro Negro não conseguiu escapar da retaliação por muito tempo, embora a prisão em Ventobravo tenha lhe oferecido proteção temporária contra os parentes de suas vítimas. De volta ao Pantanal, Rocio Garmason e o enlutado Trançalonga, o Austero, buscaram mercenários dispostos a se infiltrar na prisão assolada por motins para decepar a cabeça de Fundafúria, encerrando uma rixa sangrenta iniciada a centenas de quilômetros ao norte."}},faq={{q="Quem é Kam Fundafúria?",a="Kam Fundafúria é um prisioneiro anão Ferro Negro de elite trancafiado dentro do Cárcere de Ventobravo. Ele é conhecido por articular a sabotagem da Ponte Thandol no norte e não possui laços com os rebeldes Défias encarcerados ao seu lado.",al={"quem e fundafuria","lore de kam fundafuria","quem e o anao no carcere"}},{q="Por que há um anão Ferro Negro trancafiado no Cárcere de Ventobravo?",a="Fundafúria foi capturado após coordenar um ataque que explodiu uma das pontes na Ponte Thandol, matando defensores anões e cortando uma travessia terrestre vital entre o Pantanal e Arathi. Ele foi enviado para a prisão de segurança máxima de Ventobravo para aguardar a justiça.",al={"por que ele esta no carcere","o que kam fundafuria fez","por que ele esta preso"}},{q="Kam Fundafúria faz parte da Irmandade Défias?",a="Não. Embora esteja aprisionado ao lado da Irmandade Défias durante a rebelião deles dentro do Cárcere, Fundafúria pertence ao clã hostil dos Ferro Negro. Ele age inteiramente de acordo com os interesses agressivos de seu próprio clã contra a Aliança e Altaforja.",al={"ele e defias","kam fundafuria defias","fundafuria trabalha com vancleef"}},{q="Quem quer Kam Fundafúria morto?",a="Rocio Garmason e as forças anãs de Altaforja estacionadas em Dun Modr o querem morto. Trançalonga, o Austero, perdeu um parente no bombardeio perpetrado por Fundafúria na Ponte Thandol, o que os levou a enviar ordens a aventureiros em Ventobravo para reivindicar sua cabeça.",al={"quem deu a missao do fundafuria","quem quer a morte de fundafuria"}},{q="Onde Kam Fundafúria cometeu seu crime?",a="Fundafúria organizou a sabotagem na Ponte Thandol, o colossal complexo de pontes que conecta o Pantanal ao Planalto Arathi, bem ao norte de Ventobravo.",al={"onde a ponte foi explodida","bombardeio da ponte por fundafuria","ataque a ponte thandol"}},{q="Onde Kam Fundafúria pode ser encontrado dentro do Cárcere?",a="Kam Fundafúria é mantido dentro dos blocos de celas do Cárcere de Ventobravo, situado sob o distrito dos canais de Ventobravo.",al={"onde fica fundafuria no carcere","localizacao de kam fundafuria"}}},fx={["1bde1b20"]={q="Com quem Kam Fundafúria é aliado?",a="Kam Fundafúria pertence ao clã hostil de anões Ferro Negro. Embora ele esteja detido junto com batedores de carteira rebeldes e prisioneiros em Stormwind Stockade, ele não tem laços com a The Defias Brotherhood. Sua lealdade reside inteiramente em seu próprio clã sombrio, operando muito ao norte de sua terra natal para atacar profundamente o território mantido pela Aliança.",al={"laços de kam fundafúria","para quem kam fundafúria trabalha","facção de kam fundafúria"}},["45416a5d"]={q="Por que Kam Fundafúria é infame?",a="Kam Fundafúria ganhou sua notoriedade sombria ao orquestrar a explosão catastrófica que destruiu uma das enormes pontes de pedra através de The Thandol Span. A sabotagem violenta não apenas comprometeu uma artéria crítica entre o Pantanal e o Planalto Arathi, mas também ceifou a vida de um parente anão de Trançalonga, o Austero.",al={"reputação de kam fundafúria","por que kam fundafúria é temido","o que kam fundafúria fez"}}},fp="12,301,24.459.0,25.447.0,17.404.1,20.226.0,58.266.0,47.242.0,28.238.0,40.154.0,52.125.0"}
P.entries["npc:kanati-greycloud"] = {n="Kanati Greycloud",s="Kanati Greycloud é um caçador tauren situado no Posto Confinalvo em Mil Agulhas. Ao lado de seus companheiros de caça, ele reúne a defesa que pode enquanto suporta a constante hostilidade dos centauros Galak locais.",h="Kanati Greycloud é um caçador tauren situado no Posto Confinalvo em Mil Agulhas.",kw={"assassination plot","centauro","galak","greycloud","kanati","mil agulhas","posto confinalvo"},ang={["faction:Horde"]="O Posto Confinalvo serve como um ponto de observação crítico sobre os desfiladeiros das agulhas; manter Kanati vivo garante que os batedores da Horda continuem de olho nas movimentações das tropas dos centauros.",["race:Tauren"]="Para os taurens que atravessam Mil Agulhas, ajudar Kanati no Posto Confinalvo é uma defesa vital de seus parentes tribais contra seus antigos e amargos inimigos, os centauros."},sec={{t="Um Pouso Precário",b="Kanati Greycloud acampa no Posto Confinalvo, no alto dos pináculos de arenito do oeste de Mil Agulhas. Embora o desfiladeiro ofereça caça abundante e amplas vistas, ele é cercado pelos centauros Galak, cujos bandos de guerra disputam cada palmo das planícies áridas abaixo. Junto com outros caçadores taurens, Kanati vigia o fundo do desfiladeiro, esforçando-se para proteger o posto contra as brutais depredações dos saqueadores ao redor."},{t="Emboscada de Centauros",b="Os centauros Galak não buscam apenas isolar o Posto Confinalvo; eles pretendem aniquilar seus defensores por completo. Mensageiros enviados entre os acampamentos dos centauros carregam ordens explícitas visando o assassinato de Kanati e seus companheiros. Cabe aos viajantes visitantes interceptar essas ordens de marcha e lutar ombro a ombro com Kanati quando os grupos de ataque Galak descerem sobre o platô para abater os caçadores do entreposto."}},faq={{q="Quem é Kanati Greycloud?",a="Kanati Greycloud é um caçador tauren baseado no Posto Confinalvo, no oeste de Mil Agulhas, onde mantém um acampamento e defende contra ameaças predatórias locais.",al={"quem é kanati","história de kanati greycloud","tauren do posto confinalvo"}},{q="Onde posso encontrar Kanati Greycloud?",a="Kanati está localizado no Posto Confinalvo, um acampamento tauren elevado situado ao longo dos penhascos do norte, na porção oeste de Mil Agulhas.",al={"localização de kanati","onde fica kanati","onde fica greycloud"}},{q="Por que os centauros Galak estão tentando matá-lo?",a="Os centauros Galak buscam domínio total sobre os desfiladeiros de Mil Agulhas e visam ativamente os postos avançados da Horda. Ordens interceptadas revelam uma conspiração coordenada pelos centauros para assassinar Kanati e quebrar as defesas do posto.",al={"por que centauros atacam kanati","assassination plot galak","por que proteger kanati"}}},fx={["35c73e38"]={q="De que lado Kanati Greycloud está?",a="Kanati Greycloud é um caçador tauren leal à Horda. Ele recebe viajantes da Horda que visitam o Posto Confinalvo e conta com eles para ajudar a defender seu acampamento contra ameaças hostis no cânion.",al={"facção de kanati","kanati é da horda","kanati é da aliança ou da horda"}},cf857b32={q="O que Kanati Greycloud quer?",a="Kanati simplesmente quer manter seu acampamento de caça em paz e garantir que seus companheiros sobrevivam. Como os centauros Galak locais procuram expulsar ou massacrar todos os intrusos, sua principal preocupação é defender-se de suas tentativas de assassinato.",al={"do que kanati precisa","objetivos de kanati greycloud","por que ajudar kanati"}},["10a1bee5"]={q="Por que Kanati Greycloud está aqui?",a="Kanati estabeleceu um acampamento de caça no Posto Confinalvo ao lado de seus companheiros para caçar a fauna de Mil Agulhas. Infelizmente, montar um acampamento no cânion o colocou diretamente no território disputado pelos hostis centauros Galak.",al={"por que kanati está no posto confinalvo","o que kanati está fazendo aqui","propósito de kanati greycloud"}}},fp="16,218,18.433.0,14.426.1,24.160.0,34.146.0,45.224.0"}
P.entries["npc:kaplak"] = {n="Kaplak",s="Kaplak é um instrutor de ladinos orc localizado em Monte Navalha, na região central de Durotar. Ele ensina jovens orcs e trolls nas artes do furto, subterfúgio e manejo de lâminas, preparando-os para servir à Horda antes de enviá-los para Orgrimmar.",h="Kaplak é um instrutor de ladinos orc localizado em Monte Navalha, na região central de Durotar.",kw={"durotar","kaplak","orc","orgrimmar","monte navalha","instrutor de ladinos","furtividade","therzok"},ang={["class:Rogue"]="Para jovens ladinos orcs e trolls que deixam o Vale das Provações, Kaplak fornece o treinamento profissional inicial e os encaminha para as redes clandestinas que operam em Orgrimmar.",["faction:Horde"]="Kaplak garante silenciosamente que a Horda mantenha batedores, espiões e assassinos habilidosos capazes de proteger Durotar e operar além das linhas de batalha convencionais."},sec={{t="Um Mentor nas Sombras",b="Abrigado no assentamento de Monte Navalha, Kaplak atua como instrutor fundamental para ladinos novatos da Horda que emergem do Vale das Provações. Enquanto a cultura tradicional dos orcs glorifica o combate aberto e investidas estrondosas, Kaplak ensina as disciplinas mais frias e silenciosas necessárias para a sobrevivência: espreitar sem ser visto, arrombar fechaduras e desferir golpes letais pelas costas. Uma vez que seus alunos superam sua tutela nas ravinas vermelhas e empoeiradas de Durotar, ele os encaminha ao norte para a capital de Orgrimmar a fim de aprofundarem suas habilidades com operativos mais experientes da guilda."}},faq={{q="Quem é Kaplak?",a="Kaplak é um instrutor de ladinos orc situado em Monte Navalha, em Durotar. Ele treina ladinos orcs e trolls novatos que deixaram o Vale das Provações, ensinando-lhes as primeiras habilidades de ladino antes de enviá-los a instrutores mais avançados em Orgrimmar.",al={"quem é kaplak","história de kaplak","kaplak monte navalha"}},{q="Onde encontrar Kaplak?",a="Kaplak pode ser encontrado em Monte Navalha, o assentamento central de Durotar, normalmente descansando dentro ou nos arredores da área do quartel local, ao lado de outros instrutores de classe.",al={"onde fica kaplak","localização de kaplak","encontrar kaplak"}},{q="Quais missões Kaplak oferece?",a="Kaplak auxilia aventureiros ladinos à medida que progridem, direcionando-os a instrutores avançados e tarefas, como enviá-los para procurar Therzok em Orgrimmar.",al={"missões de kaplak","missões com kaplak"}}},fx={c5a92913={q="De que lado Kaplak está?",a="Kaplak é leal à Horda e serve aos orcs de Durotar. Posicionado em Monte Navalha, ele guia os jovens rastreadores e batedores do reino de Thrall, aprimorando suas habilidades para que possam defender as terras orquidianas contra ataques de centauros, infiltrados de Kul Tiraz e quaisquer outras ameaças à nação em crescimento.",al={"facção de kaplak","kaplak é da aliança ou da horda","a quem kaplak serve"}},d6e62700={q="Por que Kaplak está em Monte Navalha?",a="Kaplak está posicionado em Monte Navalha para treinar jovens orcs e trolls que praticam as artes sutis de furtividade, veneno e emboscada. À medida que os recrutas se aventuram para fora do Vale das Provações, ele aguça seus ofícios de ladino antes de enviar batedores capazes para a cidade capital de Orgrimmar.",al={"por que kaplak está aqui","propósito de kaplak em durotar","o que kaplak está fazendo em monte navalha"}},["044206c1"]={q="O que Kaplak quer?",a="Kaplak busca fortalecer as fileiras dos ladinos da Horda. Ele procura astúcia, disciplina e lâminas velozes entre os recrutas recém-chegados, direcionando batedores promissores para mentores seniores como Therzok em Orgrimmar assim que seu treinamento preliminar estiver completo.",al={"motivos de kaplak","objetivos de kaplak","do que kaplak precisa"}}},fp="6,241,23.544.0,14.236.0,26.156.0,30.161.0"}
P.entries["npc:karang-amakkar"] = {n="Karang Amakkar",s="Karang Amakkar é um batedor orc estacionado no Assentamento Zoram'gar ao longo da costa rochosa do Vale Gris. Operando na periferia do território da Horda, ele se concentra em conter as violentas tribos de furbolgs que ameaçam as rotas de suprimentos e as fronteiras do assentamento. Aventureiros que viajam pelo assentamento dependem de suas informações locais para navegar pelas tensões perigosas da floresta.",h="Karang Amakkar é um batedor orc estacionado no Assentamento Zoram'gar ao longo da costa rochosa do Vale Gris.",kw={"vale gris","foulweald","furbolg","karang amakkar","praia de zoram","assentamento zoram'gar"},ang={["faction:Horde"]="Karang Amakkar oferece ajuda vital aos viajantes da Horda que enfrentam as regiões ocidentais do Vale Gris, oferecendo trabalho para repelir as criaturas hostis que cercam o Assentamento Zoram'gar.",["race:Orc"]="Estacionado em um posto avançado remoto, longe de Durotar, Karang personifica a determinação corajosa das sentinelas orcs que mantêm as perigosas fronteiras do território."},sec={{t="Na Costa do Vale Gris",b="Situado no Assentamento Zoram'gar, na Praia de Zoram, Karang Amakkar serve a Horda em um de seus postos avançados de fronteira mais vulneráveis. O acampamento enfrenta pressão constante do mar, dos elfos noturnos e de feras selvagens do interior. Karang mantém um olhar atento sobre as populações nativas hostis que cercam a estrada para o leste, garantindo que os correios e grupos de reconhecimento da Horda não sejam emboscados por tribos indígenas territoriais."},{t="Lidando com os Furbolgs",b="Karang concentra grande parte de sua atenção nas populações de furbolgs nativas das florestas antigas, notavelmente a tribo Foulweald. Com a corrupção e a hostilidade primal levando esses homens-urso ao frenesi, Karang encarrega guerreiros capazes de eliminar seu líder e limpar os covis antes que as tribos possam reunir ataques organizados contra Zoram'gar."}},faq={{q="Quem é Karang Amakkar?",a="Karang Amakkar é um orc que distribui missões, estacionado no Assentamento Zoram'gar ao longo da costa do Vale Gris. Ele trabalha em nome da Horda para gerenciar ameaças regionais, especialmente clãs de furbolgs hostis.",al={"karang","quem é karang","história de karang amakkar"}},{q="Onde posso encontrar Karang Amakkar?",a="Ele está localizado no Assentamento Zoram'gar, na costa noroeste do Vale Gris, ao longo da Praia de Zoram.",al={"localização de karang","onde está karang amakkar","ponto de karang amakkar"}},{q="Quais tarefas Karang Amakkar oferece?",a="Karang encarrega os aventureiros da Horda de confrontar tribos de furbolgs agressivas nas proximidades, direcionando um ataque contra o King of the Foulweald.",al={"missões de karang","tarefas de karang","o que karang quer"}},{q="Por que Karang está preocupado com os furbolgs?",a="Os furbolgs no Vale Gris tornaram-se cada vez mais selvagens e corrompidos, atacando viajantes e ameaçando isolar o Assentamento Zoram'gar do restante das fortalezas da Horda na região.",al={"por que matar furbolgs","ameaça dos furbolgs no vale gris","ameaça dos foulweald"}},{q="Karang Amakkar é parente do Iniciado Amakkar?",a="Embora compartilhem um nome de clã ou sobrenome familiar, qualquer relação familiar exata entre Karang e o Iniciado Amakkar permanece não confirmada.",al={"família amakkar","parente do iniciado amakkar","família de karang"}},{q="Karang luta diretamente contra os elfos noturnos?",a="Os deveres de Karang em Zoram'gar concentram-se principalmente na defesa territorial e em lidar com ameaças selvagens como os furbolgs Foulweald, deixando manobras militares ostensivas contra os elfos noturnos para outros comandantes da Horda.",al={"karang vs elfos noturnos","aliança de karang"}}},fx={b0298d21={q="De que lado Karang Amakkar está?",a="Karang Amakkar é leal à Horda, servindo aos seus interesses diretamente nas densas florestas de Vale Gris. Operando ao lado de outros orcs a partir do Assentamento Zoram'gar ao longo da costa, seus esforços estão focados em proteger os postos avançados da Horda e subjugar ameaças regionais, como os hostis furbolgs.",al={"facção de karang amakkar","karang é da horda","lealdade de karang"}},["481f1d87"]={q="O que Karang Amakkar quer?",a="Karang quer subjugar as perigosas tribos nativas de Vale Gris que ameaçam a posição da Horda. Ele procura ativamente aventureiros capazes para derrotar as populações agressivas de furbolgs, especificamente a tribo Foulweald e seu rei, antes que eles possam invadir os acampamentos próximos.",al={"objetivo de karang amakkar","o que karang quer","motivo de karang"}},["7b1509e6"]={q="Por que Karang Amakkar está aqui em Vale Gris?",a="Karang está posicionado em Vale Gris para apoiar a expansão e defesa da Horda em um território intensamente hostil. Situado no Assentamento Zoram'gar, ele monitora a vida selvagem e direciona os guerreiros para neutralizar as tribos de feras hostis que ameaçam a presença da Horda ao longo de The Zoram Strand.",al={"por que karang está aqui","propósito de karang amakkar em vale gris","por que karang está em zoramgar"}}},fp="14,367,25.418.0,25.342.0,22.190.0,32.102.0,37.135.0,41.190.0,46.136.0,43.210.0"}
P.entries["npc:kargal-battlescar"] = {n="Kargal Chaga de Guerra",s="Kargal Chaga de Guerra é um guerreiro orc veterano alocado no Posto Remoto, ao longo da fronteira leste dos Sertões. Encarregado de vigiar a travessia a partir de Durotar, ele avalia os novos recrutas e direciona combatentes capazes para o interior do território para reforçar as defesas da Horda.",h="Kargal Chaga de Guerra é um guerreiro orc veterano alocado no Posto Remoto, ao longo da fronteira leste dos...",kw={"sertões","chaga de guerra","recruta","a encruzilhada","durotar","posto remoto","kargal"},ang={["class:Warrior"]="Um veterano calejado de batalha que carrega as marcas de combate intenso, Kargal exemplifica a resiliência rústica esperada dos combatentes de linha de frente da Horda em terras de fronteira indomadas.",["faction:Horde"]="Para novos aventureiros da Horda que deixam Durotar, Kargal Chaga de Guerra serve como introdução às lutas militares mais amplas de Kalimdor, mobilizando recrutas para os conflitos que despontam pelos Sertões."},sec={{t="Sentinela da Fronteira",b="Montando guarda no Posto Remoto, Kargal Chaga de Guerra supervisiona o limiar estratégico que separa as duras planícies vermelhas de Durotar da vasta savana dos Sertões. Conforme viajantes e novos aventureiros cruzam a ponte sobre o Rio Furiaustral, Kargal garante que compreendam que os dias pacíficos de treinamento no Vale das Provações ficaram para trás. Os Sertões são uma extensão disputada e perigosa, assolada por vida selvagem agressiva, grupos de incursão de centauros e tribos de javatuscos. Kargal inspeciona aqueles que passam, reunindo recrutas dispostos a servir à Horda e enviando-os adiante para a Encruzilhada a fim de ajudar os comandantes locais a proteger a fronteira."}},faq={{q="Quem é Kargal Chaga de Guerra?",a="Kargal Chaga de Guerra é um guerreiro orc e comandante de posto avançado alocado no Posto Remoto, situado ao longo da estrada leste que entra nos Sertões a partir de Durotar.",al={"kargal chaga de guerra","kargal","quem é kargal"}},{q="Qual é o propósito do Posto Remoto?",a="O Posto Remoto serve como posto de alerta precoce e defesa de linha de frente para os Sertões contra ameaças que surgem perto da fronteira de Durotar e ao longo do Rio Furiaustral.",al={"propósito do posto remoto","por que o posto remoto","o que é este posto avançado"}},{q="Para onde Kargal envia os novos recrutas?",a="Kargal recruta viajantes que passam pelo posto avançado e os direciona para o oeste ao longo da estrada principal até a Encruzilhada, o centro militar nevrálgico dos Sertões.",al={"destino da missão de kargal","para onde ir após kargal","para onde kargal te envia"}}},fx={["81d05e56"]={q="De que lado Kargal Chaga de Guerra está?",a="Kargal Chaga de Guerra está firmemente com a Horda. Guardando a fronteira leste dos Sertões, onde Durotar encontra as planícies abertas, ele garante que os recrutas e viajantes que chegam façam a travessia com segurança sob a bandeira do Chefe Guerreiro.",al={"facção de kargal chaga de guerra","kargal é da horda"}},ffbc81ca={q="O que Kargal Chaga de Guerra quer?",a="Kargal quer guerreiros capazes para proteger a fronteira e ajudar o assentamento em crescimento na Encruzilhada. Ele direciona os novos recrutas que chegam de Durotar para reforçar as defesas dos Sertões contra as ameaças que permanecem ao longo das planícies.",al={"objetivo de kargal chaga de guerra","o que kargal quer"}},e589e5e9={q="Por que Kargal Chaga de Guerra está posicionado aqui?",a="Kargal supervisiona o Posto Remoto, a entrada fortificada que conecta Durotar e os Sertões através do Rio Furiaustral. Ele está posicionado aqui para receber novos recrutas que viajam para o oeste e direcioná-los para onde a Horda mais precisa deles.",al={"por que kargal está no posto remoto","propósito da localização de kargal chaga de guerra"}}},fp="17,276,22.656.0,25.157.0,42.171.0,36.161.0"}
P.entries["npc:karos-razok"] = {n="Carlos Razok",s="Carlos Razok é o mestre de morcegos Renegado posicionado em O Sepulcro, na Floresta de Pinhaprata. Ele supervisiona o poleiro de voadores mortos-vivos que conecta este posto avançado de fronteira disputado diretamente à Cidade Baixa e a outras fortalezas da Horda.",h="Carlos Razok é o mestre de morcegos Renegado posicionado em O Sepulcro, na Floresta de Pinhaprata.",kw={"mestre de morcegos","mestre de voo","carlos razok","o sepulcro","floresta de pinhaprata","cidade baixa"},ang={["faction:Horde"]="Para viajantes da Horda que avançam para o sul em direção ao Contraforte de Eira dos Montes, o poleiro de morcegos de Razok é um ponto de parada indispensável na borda oeste de Lordaeron.",["race:Undead"]="Carlos Razok representa a sua salvação de volta à Cidade Baixa, garantindo que os esforços da linha de frente em Pinhaprata permaneçam firmemente ligados à capital de Lady Sylvana."},sec={{t="Guardião das Asas d'O Sepulcro",b="Empoleirado na plataforma de madeira acima das criptas de O Sepulcro, Carlos Razok cuida dos morcegos esqueléticos vitais para as comunicações dos Renegados. Com a Floresta de Pinhaprata infestada por worgens Moonrage, magos renegados de Dalaran e os remanescentes humanos de Lenhâmbar, a viagem terrestre pela estrada do norte é traiçoeira. Razok garante que mensageiros, novos recrutas e suprimentos vitais possam cruzar acima da copa assombrada, mantendo a linha de frente ligada diretamente à capital nas Clareiras de Tirisfal."}},faq={{q="Quem é Carlos Razok?",a="Carlos Razok é o mestre de voo Renegado posicionado em O Sepulcro, na Floresta de Pinhaprata. Ele gerencia o poleiro de morcegos vampíricos treinados usados por aventureiros e mensageiros da Horda para viajar por Lordaeron.",al={"função de carlos razok","quem é o mestre de voo em o sepulcro","mestre de morcegos de o sepulcro"}},{q="Para onde Carlos Razok pode enviar viajantes?",a="Razok conecta O Sepulcro diretamente à Cidade Baixa, nas Clareiras de Tirisfal, e à Serraria Tarren, no Contraforte de Eira dos Montes, facilitando o trânsito rápido pelo norte de Lordaeron.",al={"rotas de voo de o sepulcro","para onde voa o morcego de o sepulcro","rotas de voo a partir de o sepulcro"}},{q="De quais criaturas Carlos cuida?",a="Ele cuida de grandes morcegos de voo esqueléticos. Essas feras mortas-vivas são voadoras resistentes e incansáveis, adaptadas aos céus flagelados de Lordaeron, e são as preferidas dos Renegados por seu silêncio e vigor.",al={"quais montarias razok tem","feras voadoras dos renegados","quais são as montarias voadoras em o sepulcro"}},{q="Por que um mestre de voo é importante em O Sepulcro?",a="As estradas de Pinhaprata estão tomadas por forças hostis, desde a maldição dos worgens de Pyrewood até os magos humanos em Lenhâmbar. Razok fornece uma rota de escape aérea que permite aos Renegados abastecer esta base avançada sem sofrer emboscadas na estrada principal.",al={"por que o mestre de morcegos de o sepulcro é necessário","importância das viagens em o sepulcro"}}},fx={db08745b={q="De que lado Carlos Razok está?",a="Carlos Razok serve aos Renegados e à Horda. Posicionado na Floresta de Pinhaprata, ele promete sua lealdade à Grande Dama Sylvana Correventos e à Cidade Baixa, auxiliando correios dos Renegados, batedores e aventureiros que viajam pela região.",al={"facção de carlos razok","a quem carlos razok serve","carlos razok é da horda"}},["6a9fc34a"]={q="O que Carlos Razok quer?",a="Carlos simplesmente quer manter os céus abertos e o trânsito aéreo funcionando sem problemas para os Renegados. Gerenciar o poleiro no Sepulcro garante que suprimentos, mensagens e reforços possam fluir de forma confiável entre Floresta de Pinhaprata e outros baluartes da Horda.",al={"objetivo de carlos razok","o que carlos razok faz","motivos de carlos razok"}}},fp="11,227,31.485.0,19.205.0,37.171.0,33.190.0,50.245.0"}
P.entries["npc:katie-hunter"] = {n="Carina Caçador",s="Carina Caçador é uma criadora de cavalos localizada nos estábulos da Madeireira Vale do Leste, na parte leste da Floresta de Elwynn. Ela fornece cavalos de montaria e corcéis treinados a cidadãos de Ventobravo e a campeões de confiança da Aliança. Ao lado de Randal Caçador, ela garante que viajantes e soldados tenham montarias confiáveis para percorrer as estradas do reino.",h="Carina Caçador é uma criadora de cavalos localizada nos estábulos da Madeireira Vale do Leste, na parte leste...",kw={"vale do leste","floresta de elwynn","vendedora de cavalos","carina caçador","madeireira","montarias","estábulos","ventobravo"},ang={["faction:Alliance"]="Raças aliadas que alcançam grande prestígio e respeito perante a corte de Ventobravo podem conquistar o privilégio de cavalgar os corcéis premiados de Carina em batalha.",["race:Human"]="Para os viajantes humanos, os estábulos de Carina representam um rito de passagem natural, oferecendo os cavalos clássicos de Ventobravo assim que você dominar os princípios básicos da equitação."},sec={{t="Estábulos do Vale do Leste",b="Escondida nas clareiras arborizadas e tranquilas da Madeireira Vale do Leste, Carina Caçador administra a principal criação de cavalos do reino para os aspirantes a cavaleiros da Floresta de Elwynn. Enquanto os lenhadores extraem madeira para a reconstrução de Ventobravo, Carina cuida dos estábulos, criando diversas raças confiáveis, incluindo cavalos malhados, éguas e corcéis velozes. Seus animais representam a tradição equestre clássica do reino, oferecendo companheiros fiéis capazes de desbravar as estradas perigosas do sul de Azeroth."}},faq={{q="Quem é Carina Caçador?",a="Carina Caçador é a criadora de cavalos e vendedora de montarias do Reino de Ventobravo, localizada nos estábulos da Madeireira Vale do Leste, na Floresta de Elwynn.",al={"carina caçador elwynn","quem é carina caçador","carina caçador vendedora de cavalos"}},{q="Onde posso encontrar Carina Caçador?",a="Ela fica na parte norte da Madeireira Vale do Leste, cuidando do curral e dos estábulos perto do instrutor de montaria Randal Caçador, na região leste da Floresta de Elwynn.",al={"localização de carina caçador","onde fica carina caçador","encontrar carina caçador"}},{q="Personagens que não são humanos podem comprar cavalos com ela?",a="Sim, mas apenas se tiverem alcançado reputação exaltada com o Reino de Ventobravo. Aventureiros humanos podem comprar os cavalos dela sem nenhuma reputação especial.",al={"anão comprar cavalo","elfo noturno montaria cavalo","montaria de reputação ventobravo"}},{q="Quais cavalos ela vende?",a="Carina fornece cavalos de montaria comuns — incluindo variedades malhadas, castanhas e alazãs —, bem como corcéis velozes e protegidos por armadura, como o Baio Veloz, o Corcel Castanho Veloz e o Corcel Branco Veloz.",al={"quais montarias carina vende","tipos de cavalos de carina caçador"}}},fx={d7735dfa={q="De que lado está Carina Caçador?",a="Carina Caçador é uma súdita leal do Reino de Ventobravo e um membro da Aliança. Operando a partir da Madeireira Vale do Leste, ela atende diretamente aos cidadãos de Ventobravo, fornecendo montarias confiáveis a viajantes e campeões que provaram sua dedicação à coroa.",al={"facção de carina caçador","carina caçador é da aliança","a quem carina caçador serve"}},d5257f59={q="O que Carina Caçador quer?",a="Carina Caçador concentra-se em cuidar e vender os renomados cavalos da Madeireira Vale do Leste. Ela busca fornecer montarias capazes a aventureiros de confiança, garantindo que apenas aliados de confiança de Ventobravo adquiram seu estoque premiado para ajudar em suas viagens pelo reino.",al={"o que carina caçador quer","propósito de carina caçador","objetivo de carina caçador"}},["5cab52df"]={q="Por que Carina Caçador está aqui na Madeireira Vale do Leste?",a="Carina Caçador estabeleceu sua residência na Madeireira Vale do Leste, na parte leste da Floresta de Elwynn, para administrar os estábulos do acampamento. Trabalhando ao lado de Randal Caçador, ela gerencia a criação e o cuidado de cavalos de montaria longe da agitação de Ventobravo, usando a pastagem aberta do acampamento.",al={"por que carina caçador está em madeireira vale do leste","por que carina caçador está aqui","o que carina caçador está fazendo em elwynn"}},["85933b18"]={q="A quem Carina Caçador está ligada?",a="Carina Caçador trabalha em estreita colaboração com Randal Caçador, que também supervisiona os estábulos na Madeireira Vale do Leste. Juntos, eles gerenciam o comércio equino do acampamento e servem como a principal fonte de cavalos para os aliados de Ventobravo.",al={"conexões de carina caçador","parentesco de carina caçador","carina caçador e randal caçador"}}},fp="12,339,19.503.0,20.150.0,30.159.0,35.158.0,26.191.0"}
P.entries["npc:katrana-prestor"] = {n="Lady Katrana Prestor",s="Lady Katrana Prestor é uma nobre de Ventobravo e uma das vozes mais influentes da corte. Com o Rei Varian desaparecido, ela permanece ao lado do jovem rei Anduin e do Grão-lorde Bolvar Fordragon em Bastilha Ventobravo como uma conselheira de confiança.",h="Lady Katrana Prestor é uma nobre de Ventobravo e uma das vozes mais influentes da corte.",kw={"katrana","prestor","katrana prestor","lady prestor","conselheira","bastilha ventobravo","corte"},sec={{t="Voz da Corte",b="Lady Prestor chegou à corte há alguns anos e rapidamente ascendeu até se tornar uma de suas figuras mais confiáveis. Os nobres de Ventobravo buscam seu favor, e seus conselhos moldam muitas das decisões tomadas em nome do jovem rei enquanto o Grão-lorde Bolvar Fordragon governa como regente. Peticionários que vão a Bastilha Ventobravo pedir soldados ou ajuda frequentemente descobrem que a opinião dela tem tanto peso quanto a do regente."}},faq={{q="Quem é Lady Katrana Prestor?",a="Lady Katrana Prestor é uma nobre de Ventobravo e uma conselheira de confiança na corte. Com o Rei Varian desaparecido, ela permanece ao lado do jovem rei Anduin e do Grão-lorde Bolvar Fordragon em Bastilha Ventobravo, e sua voz tem grande peso entre os nobres.",al={"quem é katrana prestor","quem é lady prestor","história de katrana prestor"}},{q="Por que ela está aconselhando o rei?",a="O desaparecimento do Rei Varian deixou seu jovem filho Anduin no trono, com o Grão-lorde Bolvar Fordragon governando como regente. Lady Prestor fica ao lado deles como conselheira. Muitas das decisões da corte, incluindo como Ventobravo responde aos pedidos de ajuda de suas terras periféricas, passam pelos conselhos dela.",al={"por que prestor está na corte","o que katrana faz"}},{q="Onde posso encontrar Lady Prestor?",a="Ela costuma ser encontrada na sala do trono de Bastilha Ventobravo, perto do Grão-lorde Bolvar Fordragon e do jovem Rei Anduin.",al={"onde fica katrana prestor","localização de katrana prestor"}}},fp="20,232,18.402.0,28.243.0,29.296.0,30.125.0"}
P.entries["npc:kaymard-copperpinch"] = {n="Polyxopo Pechisbeque",s="Polyxopo Pechisbeque é um mercador goblin que representa a Smokywood Pastures em Orgrimmar durante o Feast of Winter Veil. Posicionado no Vale da Força, ele apregoa produtos festivos e direciona os viajantes para a alegria das festas e suprimentos natalinos desaparecidos. Seu comércio movimentado traz alegria sazonal — e o espírito comercial dos goblins — para a capital da Horda.",h="Polyxopo Pechisbeque é um mercador goblin que representa a Smokywood Pastures em Orgrimmar durante o Feast of...",kw={"pechisbeque","goblin","polyxopo","metzen","orgrimmar","smokywood pastures","vale da força","winter veil"},ang={["faction:Horde"]="Para a Horda, Polyxopo representa o lado comercial do Winter Veil em Orgrimmar, equilibrando as tradicionais celebrações de inverno com o empreendedorismo goblin.",["profession:Cooking"]="Polyxopo e seus colegas da Smokywood Pastures fornecem receitas sazonais e ingredientes especiais essenciais para assar guloseimas tradicionais de fim de ano."},sec={{t="O Winter Veil de um Goblin",b="Quando o Feast of Winter Veil chega, a Smokywood Pastures monta sua loja bem no movimentado Vale da Força, em Orgrimmar, sob o comando do empreendedor Polyxopo Pechisbeque. Enquanto o Papai Inverno recebe visitantes por perto, Polyxopo garante que a estação continue lucrativa. Vendendo guloseimas sofisticadas, papel de presente festivo e itens essenciais para as festas, ele personifica a visão goblin de que nenhum grande festival cultural está completo sem uma animada troca de moedas."},{t="Complicações das Festas",b="Além de mascatear artigos festivos, Polyxopo frequentemente atua como ponto de contato para os contratempos sazonais que assolam a Smokywood Pastures. De carregamentos roubados de doces natalinos ao misterioso desaparecimento de Metzen the Reindeer, Polyxopo recruta avidamente aventureiros da Horda para resolver os problemas na neve e manter o festival funcionando sem problemas."}},faq={{q="Quem é Polyxopo Pechisbeque?",a="Polyxopo Pechisbeque é um mercador goblin afiliado à Smokywood Pastures. Durante o Feast of Winter Veil, ele opera no Vale da Força em Orgrimmar, vendendo produtos sazonais de primeira linha e oferecendo tarefas festivas aos transeuntes.",al={"quem é polyxopo","história de polyxopo pechisbeque","o que polyxopo faz"}},{q="O que é a Smokywood Pastures?",a="A Smokywood Pastures é um consórcio de comerciantes que cuida da comida, dos doces e das mercadorias sazonais do Feast of Winter Veil por toda Azeroth. Eles abastecem tanto a Horda quanto a Aliança com produtos festivos, ao mesmo tempo em que garantem um belo lucro.",al={"o que é smokywood pastures","para quem ele trabalha","história da smokywood pastures"}},{q="Onde posso encontrar Polyxopo Pechisbeque?",a="Ele pode ser encontrado no Vale da Força, em Orgrimmar, posicionado próximo à exibição central do festival, onde o Papai Inverno fica durante o Feast of Winter Veil.",al={"localização de polyxopo","onde fica polyxopo pechisbeque","onde ele está em orgrimmar"}},{q="Por que ele pede ajuda aos aventureiros durante as festas?",a="A Smokywood Pastures frequentemente enfrenta desastres logísticos durante o Winter Veil, incluindo o roubo de doces festivos e o sequestro de sua preciosa rena, Metzen. Polyxopo contrata aventureiros dispostos a recuperar seus bens e proteger os lucros da temporada.",al={"missões de polyxopo","missão de doces de winter veil","missão de metzen horda"}}},fx={["10a0163d"]={q="De que lado está Polyxopo Pechisbeque?",a="Polyxopo trabalha exclusivamente para a Smokywood Pastures, um empreendimento comercial goblin. Embora ele monte sua loja de feriado no coração de Orgrimmar para atender aos clientes da Horda e suprir o Festim do Véu de Inverno, sua verdadeira lealdade está com a empresa e a busca por lucro honesto, em vez da política da Horda.",al={"facção de polyxopo pechisbeque","polyxopo é da horda","para quem polyxopo trabalha"}},["699a38fb"]={q="Por que Polyxopo Pechisbeque está aqui?",a="Polyxopo montou uma loja no Vale da Força de Orgrimmar para celebrar o Festim do Véu de Inverno. A Smokywood Pastures envia mercadores para as principais capitais a cada temporada de feriado para vender guloseimas, papéis de presente, receitas e produtos especiais sazonais para os cidadãos festivos.",al={"por que polyxopo está em orgrimmar","o que polyxopo está fazendo aqui","propósito de polyxopo em orgrimmar"}}},fp="19,352,22.459.0,21.345.0,27.228.0,27.234.0,37.172.0,57.259.0"}
P.entries["npc:keeper-albagorm"] = {n="Guardião Albagorm",s="O Guardião Albagorm é um guardião do bosque estabelecido no santuário idílico do Morro das Torres de Pedra. Profundamente preocupado com a devastação que corrompe os trechos ao sul das montanhas, ele recruta viajantes para ajudar a curar as terras selvagens calcinadas do Vale Carbonizado.",h="O Guardião Albagorm é um guardião do bosque estabelecido no santuário idílico do Morro das Torres de Pedra.",kw={"cenarius","vale carbonizado","guardião albagorm","guardião do bosque","torres de pedra","morro das torres de pedra"},ang={["class:Druid"]="Como um guardião do bosque, Albagorm compartilha uma ligação direta com a linhagem cenariana, tornando seus esforços para purificar o Vale Carbonizado profundamente pessoais para os druidas.",["faction:Alliance"]="Albagorm oferece abrigo e orientação às forças da Aliança que passam pelo santuário dos elfos noturnos no Morro das Torres de Pedra."},sec={{t="Um Guardião no Morro",b="Aninhado nos ramos tranquilos do Morro das Torres de Pedra, o Guardião Albagorm vigia um dos refúgios élficos sagrados de Kalimdor. Como muitos filhos de Cenarius, ele sente a dor do mundo natural com intensidade. Sua atenção está voltada para o sul, em direção às ruínas fumegantes do Vale Carbonizado, incendiadas por um exército mecanizado de industrialistas gananciosos e agora dominadas pelas harpias Bloodfury, que impedem qualquer novo crescimento. De seu santuário, Albagorm trabalha incansavelmente para deter a propagação da corrupção e restaurar o equilíbrio da floresta ferida."}},faq={{q="Quem é o Guardião Albagorm?",a="Ele é um guardião do bosque — um dos descendentes semideuses de Cenarius — situado no Morro das Torres de Pedra, na Cordilheira das Torres de Pedra. Ele atua como um aliado dos elfos noturnos e dos guardiões naturais de Kalimdor.",al={"guardião albagorm","quem é albagorm","albagorm torres de pedra"}},{q="Onde posso encontrar o Guardião Albagorm?",a="Ele reside no Morro das Torres de Pedra, um refúgio druídico alinhado à Aliança, aninhado no alto do canto noroeste da Cordilheira das Torres de Pedra.",al={"localização do guardião albagorm","onde fica albagorm","albagorm coordenadas"}},{q="Com o que o Guardião Albagorm precisa de ajuda?",a="Albagorm busca reparar a devastação do Vale Carbonizado. Ele envia aventureiros capazes à bacia sufocada por cinzas para purificar a paisagem corrompida e expulsar as harpias Bloodfury que impedem a regeneração natural.",al={"missões do guardião albagorm","o que albagorm quer","reivindicando o vale carbonizado"}}},fx={["23205c35"]={q="De que lado está o Guardião Albagorm?",a="O Guardião Albagorm está alinhado com os elfos noturnos e os druidas Cenarianos do Morro das Torres de Pedra, oferecendo seus conselhos e orientação aos campeões da Aliança. Como todos os filhos de Cenarius, sua lealdade mais profunda está com o \"The Balance of Nature\", buscando aliados dispostos a ajudar a curar as paisagens marcadas de Kalimdor.",al={"facção do guardião albagorm","albagorm aliança ou horda","albagorm é amigável"}},["28024e4a"]={q="Por que o Guardião Albagorm está aqui no Morro das Torres de Pedra?",a="O Guardião Albagorm vigia o santuário do Morro das Torres de Pedra, um bastião vital da natureza escondido no alto das montanhas. Deste refúgio, ele observa a corrupção e a destruição se espalhando pela região, direcionando viajantes confiáveis para combater a praga e reparar a devastação que ameaça o Vale Carbonizado nas proximidades.",al={"por que albagorm está no morro das torres de pedra","propósito de albagorm nas torres de pedra","papel do guardião albagorm"}},["7aa8d5e1"]={q="A quem o Guardião Albagorm está ligado?",a="Como guardião do bosque, Albagorm é um dos reverenciados filhos de Cenarius, ligando-o por linhagem sagrada diretamente ao Semideus da Lua e à ordem natural. Na Cordilheira das Torres de Pedra, ele se posiciona ao lado das sentinelas élficas noturnas locais e dos protetores Cenarianos estacionados no topo da montanha.",al={"vínculos do guardião albagorm","conexões de albagorm","a quem albagorm responde"}}},fp="15,260,22.526.0,23.205.0,33.134.0,41.213.0"}
P.entries["npc:keeper-bel-dugur"] = {n="Guardião Bel'dugur",s="O Guardião Bel'dugur é um Renegado erudito que reside nas profundezas do Boticarium de Cidade Baixa. Ele serve ao seu povo encomendando expedições para recuperar tomos sombrios e artefatos mágicos de toda Azeroth.",h="O Guardião Bel'dugur é um Renegado erudito que reside nas profundezas do Boticarium de Cidade Baixa.",kw={"boticarium","bel'dugur","guardião beldugur","presa negra","o livro de ur","cidade baixa"},ang={["class:Warlock"]="Bruxos frequentemente cruzam com os pedidos de Bel'dugur, já que seus interesses se alinham fortemente com grimórios perigosos, invocações extraplanares e ocultismo sombrio.",["race:Undead"]="Bel'dugur parece qualquer outro Renegado erudito em busca de conhecimento proibido para fortalecer o seu reino, mas suas verdadeiras ambições estão fora da causa de sobrevivência da Rainha Banshee."},sec={{t="Um Colecionador de Relíquias Sombrias",b="Situado entre os tanques e pesquisadores do Boticarium, o Guardião Bel'dugur encarrega aventureiros de recuperar perigosas relíquias arcanas e ocultas de toda Azeroth. Entre os seus interesses mais proeminentes está O Livro de Ur, um tratado lendário sobre seres extradimensionais trancado dentro da Bastilha da Presa Negra. Enquanto muitos em Cidade Baixa buscam conhecimento mágico para curar ou transformar em arma a condição dos mortos-vivos, as aquisições selecionadas de Bel'dugur parecem voltadas para desenterrar poderes antigos e proibidos."},{t="Lealdades Ocultas",b="Sob sua postura calma como pesquisador de Cidade Baixa esconde-se uma lealdade secreta ao culto apocalíptico do Martelo do Crepúsculo. As missões e tarefas de pesquisa que Bel'dugur atribui promovem silenciosamente a agenda esotérica do culto, adquirindo grimórios fundamentais de invocação e magia do Caos bem debaixo do nariz desavisado da Real Sociedade de Boticários e de Lady Sylvanas."}},faq={{q="Onde posso encontrar o Guardião Bel'dugur?",a="O Guardião Bel'dugur está localizado no Boticarium, o distrito alquímico situado no anel inferior sul de Cidade Baixa.",al={"localização do guardião bel'dugur","onde fica beldugur","mapa de beldugur"}},{q="Por que Bel'dugur quer O Livro de Ur?",a="O Livro de Ur contém a pesquisa fundamental do mago Ur de Dalaran a respeito de outras dimensões e dos worgens ferozes. Bel'dugur busca utilizar esses princípios proibidos de invocação para os planos sombrios de seus verdadeiros mestres.",al={"por que o livro de ur","o que beldugur faz com o livro de ur"}},{q="O Guardião Bel'dugur é leal a Lady Sylvanas?",a="Aparentemente, ele atua como arquivista e pesquisador dos Renegados, embora indícios sutis em suas investigações sugiram que suas lealdades possam estar em outro lugar.",al={"beldugur é mau","facção de beldugur","a quem beldugur serve"}},{q="Que outras tarefas ele dá aos aventureiros?",a="Além d'O Livro de Ur da Bastilha da Presa Negra, Bel'dugur direciona viajantes para conhecimentos esquecidos e tomos proibidos, incluindo tratados sombrios ligados a rituais antigos e saberes proibidos.",al={"missões de beldugur","missões do guardião beldugur"}}},fx={f8b2616f={q="Quem é o Guardião Bel'dugur?",a="O Guardião Bel'dugur é um estudioso Renegado estacionado no Boticarium dentro da Cidade Baixa. Embora ele se apresente como um arquivista silencioso que coleciona tomos obscuros e saberes esquecidos para a Real Sociedade de Boticários, ele busca conhecimentos esotéricos perigosos muito além do ofício comum de boticário.",al={"quem é bel'dugur","história do guardião bel'dugur","quem é o guardião bel'dugur"}},["3453eee6"]={q="O que o Guardião Bel'dugur quer?",a="Bel'dugur busca textos arcanos proibidos, segredos ocultos e relíquias de poder sombrio. Ele incumbe aventureiros de recuperar tomos perigosos, como O Livro de Ur, da Bastilha da Presa Negra e outros compêndios ocultos para desbloquear magia antiga perigosa.",al={"o que bel'dugur quer","motivos do guardião bel'dugur","objetivo de bel'dugur"}},["43763d0f"]={q="Por que o Guardião Bel'dugur está na Cidade Baixa?",a="Bel'dugur reside no Boticarium da Cidade Baixa, um santuário ideal para aqueles que buscam estudos sombrios longe de olhares curiosos. Da segurança da capital dos Renegados, ele direciona andarilhos para cantos perigosos do mundo para recuperar escritos perdidos para sua coleção.",al={"por que bel'dugur está na cidade baixa","por que o guardião bel'dugur está aqui","por que bel'dugur está neste local"}},["5a26a87f"]={q="A quem o Guardião Bel'dugur está ligado?",a="Abaixo de seu papel entre os Renegados no Boticarium, pistas sutis e diálogos em torno de sua pesquisa proibida sugerem ligações com o secreto culto do Martelo do Crepúsculo, que cobiça um poder capaz de abalar o mundo e saberes apocalípticos.",al={"conexões do guardião bel'dugur","para quem bel'dugur trabalha","bel'dugur e o martelo do crepúsculo"}}},fp="16,211,26.501.0,16.349.2,34.129.0,39.227.1,43.155.2,42.181.0"}
P.entries["npc:keeper-bel-varil"] = {n="Guardião Bel'varão",s="O Guardião Bel'varão é um zelador e pesquisador Renegado situado na Serraria Tarren, no Contraforte de Eira dos Montes. Trabalhando em estreita colaboração com Wordeen Voidglare, ele orienta os aventureiros da Horda a reunir relíquias mágicas e materiais de vinculação das terras vizinhas para aprofundar seus estudos ocultistas.",h="O Guardião Bel'varão é um zelador e pesquisador Renegado situado na Serraria Tarren, no Contraforte de Eira...",kw={"bel'varão","braçadeiras de vinculação","contraforte de eira dos montes","guardião bel'varão","fichas de pedra","serraria tarren","wordeen voidglare"},ang={["faction:Horde"]="Para os campeões da Horda que lutam no Contraforte de Eira dos Montes, Bel'varão oferece recompensas práticas em troca de subjugar ameaças elementais e recuperar amuletos de vinculação.",["race:Undead"]="O trabalho de Bel'varão reflete a busca dos Renegados pelo domínio arcano e pela desenvoltura, garantindo uma vantagem em Lordaeron por meio do estudo cuidadoso de relíquias regionais."},sec={{t="Estudo na Serraria Tarren",b="Em meio à vila sitiada da Serraria Tarren, o Guardião Bel'varão apoia silenciosamente as pesquisas mágicas e alquímicas dos Renegados. Enquanto os boticários reais e soldados se ocupam com a guarnição da Aliança logo adiante na Costa Sul, Bel'varão se concentra na feitiçaria prática, enviando viajantes para recuperar Fichas de pedra e braçadeiras de vinculação de ameaças elementais e encantadas próximas."}},faq={{q="Quem é o Guardião Bel'varão?",a="O Guardião Bel'varão é um estudioso Renegado situado na Serraria Tarren, no Contraforte de Eira dos Montes. Ele ajuda o colega pesquisador Wordeen Voidglare a examinar artefatos mágicos e reagentes encontrados por todo o território disputado.",al={"guardião bel'varão","quem é bel'varão","bel'varão serraria tarren"}},{q="Onde posso encontrar o Guardião Bel'varão?",a="Ele pode ser encontrado no assentamento Renegado da Serraria Tarren, situado ao norte do Contraforte de Eira dos Montes.",al={"localização de bel'varão","onde fica o guardião bel'varão","encontrar o guardião bel'varão"}},{q="Quais tarefas o Guardião Bel'varão oferece?",a="Ele recruta aventureiros da Horda para coletar vestígios mágicos, como Fichas de pedra e braçadeiras de vinculação, ajudando seu círculo a compreender e manipular forças elementais.",al={"missões de bel'varão","tarefas do guardião bel'varão"}}},fx={["07ee922c"]={q="De que lado está o Guardião Bel'varão?",a="O Guardião Bel'varão é leal aos Renegados e à Horda em geral. Estacionado na Serraria Tarren, ele trabalha ao lado de seus irmãos mortos-vivos para proteger o Contraforte de Eira dos Montes contra a agressão da Aliança e auxiliar na pesquisa estratégica que está sendo realizada por seus companheiros Renegados.",al={"facção de bel'varão","bel'varão é da horda","lealdade de bel'varão"}},["19ba277e"]={q="O que o Guardião Bel'varão quer?",a="Bel'varão busca componentes místicos e artefatos para auxiliar em pesquisas arcanas especializadas. Para ajudar no trabalho de Wordeen Voidglare na Serraria Tarren, ele recruta viajantes para recuperar remanescentes encantados, como Stone Tokens e braceletes de ligação, dos elementais e ruínas nas regiões vizinhas.",al={"objetivo de bel'varão","o que bel'varão precisa","por que ajudar bel'varão"}},["4541a85d"]={q="Por que o Guardião Bel'varão está aqui na Serraria Tarren?",a="O Guardião Bel'varão permanece estacionado na Serraria Tarren para apoiar os interesses territoriais e arcanos dos Renegados no Contraforte de Eira dos Montes. Trabalhando em conjunto com pesquisadores como Wordeen Voidglare, ele coordena a coleta de suprimentos mágicos necessários para fortalecer seu domínio contra inimigos próximos.",al={"por que bel'varão está na serraria tarren","propósito de bel'varão em eira dos montes","por que o guardião bel'varão está aqui"}},b0435467={q="A quem o Guardião Bel'varão está ligado?",a="O Guardião Bel'varão trabalha em estreita colaboração com Wordeen Voidglare, outro estudioso Renegado estacionado na Serraria Tarren. Bel'varão atua como assistente e coordenador, organizando aventureiros para coletar os materiais e tokens específicos que Wordeen requer para seus estudos em andamento.",al={"associados de bel'varão","para quem bel'varão trabalha","conexões de bel'varão"}}},fp="16,289,20.386.0,24.217.0,34.109.0,39.164.0"}
P.entries["npc:keldran"] = {n="Keldran",s="Keldran é um agente orc posicionado ao norte do Vale dos Espíritos em Orgrimmar. Dedicado a abrir caminho para uma eventual diplomacia com a Aliança, ele coordena ataques secretos contra remanescentes demoníacos para provar que a moderna Horda realmente abandonou a Legião Ardente.",h="Keldran é um agente orc posicionado ao norte do Vale dos Espíritos em Orgrimmar.",kw={"relações da aliança","lâmina ardente","desolação","keldran","maurin rachaosso","orgrimmar","takta laminaço","vale dos espíritos"},ang={["class:Warlock"]="A guerra secreta de Keldran contra a Lâmina Ardente reforça o quanto a liderança da Horda deseja desesperadamente se distanciar da corrupção demoníaca descontrolada.",["faction:Horde"]="Keldran representa o segmento progressista da Horda que reconhece a extrema necessidade de se desvencilhar de sua reputação demoníaca para garantir uma paz duradoura em Kalimdor."},sec={{t="Uma Cruzada Diplomática",b="Enquanto Thrall governa a partir do Valley of Wisdom, Keldran trabalha nos terraços de rocha vermelha da cidade para resolver um persistente desastre diplomático. A Aliança ainda vê todos os orcs como marionetes sanguinárias de mestres demoníacos, uma reputação consolidada durante as primeiras guerras. Convencido de que até Thrall está cansado do conflito sem fim, Keldran acredita que negociações de paz reais nunca poderão acontecer enquanto cultos adoradores de demônios persistirem em Kalimdor. Sem a sanção formal do Chefe Guerreiro, ele toma a iniciativa para si, orientando agentes de confiança contra ameaças distantes a fim de erradicar de vez a mácula demoníaca."},{t="A Guerra em Desolação",b="Para defender sua causa perante a Aliança, Keldran mira os ermos sombrios de Desolação. Ele enviou Takta Laminaço e Maurin Rachaosso para liderar operações contra as infestações demoníacas locais, dando ênfase especial à aniquilação dos cultistas da Lâmina Ardente. Ao erradicar esses praticantes demoníacos e trazer provas tangíveis de volta a Orgrimmar, Keldran espera demonstrar de forma inequívoca que a nova Horda é tão inimiga da Legião quanto os humanos e os elfos noturnos."}},faq={{q="Quem é Keldran?",a="Keldran é um orc localizado ao norte do Vale dos Espíritos em Orgrimmar que organiza esforços para expurgar a influência demoníaca e abrir caminho para relações diplomáticas com a Aliança.",al={"quem é keldran","história de keldran","npc keldran"}},{q="Por que Keldran se importa com as relações com a Aliança?",a="Keldran acredita que Thrall está se cansando da guerra contínua com a Aliança. Ele sabe que negociações de paz permanecerão impossíveis enquanto a Aliança presumir que a Horda ainda está aliada à Legião Ardente.",al={"por que relações com a aliança","motivos de keldran","por que ele quer paz"}},{q="Keldran está agindo sob ordens oficiais de Thrall?",a="Não. Keldran não possui autorização oficial do Chefe Guerreiro Thrall para sua operação, optando por agir de forma independente a fim de limpar o nome da Horda e estabelecer as bases para uma paz futura.",al={"thrall enviou keldran","ordens de thrall para keldran","keldran é autorizado"}},{q="O que Keldran está fazendo em Desolação?",a="Ele enviou Takta Laminaço e Maurin Rachaosso a Desolação para expurgar as forças demoníacas locais e erradicar decisivamente a presença do culto da Lâmina Ardente.",al={"operação em desolação","por que desolação","keldran lâmina ardente"}}},fx={b49902f3={q="A quem Keldran está ligado?",a="Keldran trabalha ao lado de agentes leais da Horda que compartilham sua visão de paz. Para executar sua estratégia contra adoradores de demônios em Desolação, ele confia em Takta Laminaço e Maurin Rachaosso, direcionando-os a atacar a ameaça demoníaca e eliminar a Lâmina Ardente da região.",al={"aliados de keldran","com quem keldran trabalha","associados de keldran"}}},fp="7,277,20.591.0,19.487.1,15.181.0,56.212.0,49.177.0,34.166.0"}
P.entries["npc:kelm-hargunth"] = {n="Kelm Hargunth",s="Kelm Hargunth é o principal oficial de suprimentos e intendente dos Pioneiros do Brado Guerreiro, destacado no Campo-base Mor'shan, na fronteira norte dos Sertões. Ele equipa os campeões da Horda que lutam contra os elfos sangrentos e noctíferos nas florestas disputadas da Ravina Brado Guerreiro. Por meio de seus pacotes de suprimentos e provisões, ele garante que o esforço de guerra na linha de frente permaneça totalmente abastecido.",h="Kelm Hargunth é o principal oficial de suprimentos e intendente dos Pioneiros do Brado Guerreiro, destacado...",kw={"sertões","pacote de suprimentos","kelm hargunth","campo-base mor'shan","vendedor de jxj","intendente","ravina brado guerreiro","pioneiros do brado guerreiro"},ang={["class:Warrior"]="Os guerreiros da linha de frente dependem muito das perneiras de placas resistentes, lâminas pesadas e rações de combate de Hargunth para manter a linha contra a Aliança.",["faction:Horde"]="Kelm Hargunth fornece as ferramentas de guerra para qualquer soldado da Horda disposto a pegar em armas contra os elfos da noite na Ravina Brado Guerreiro.",["race:Orc"]="Para os orcs, Hargunth assegura que o legado de Grom Hellscream no Vale Gris perdure, mantendo o clã Brado Guerreiro armado e alimentado."},sec={{t="Intendente de Mor'shan",b="Posicionado nas muralhas de terra com vista para o Vale Gris, Kelm Hargunth supervisiona as operações logísticas dos Pioneiros do Brado Guerreiro no Campo-base Mor'shan. Enquanto batedores e saqueadores combatem além da paliçada, Hargunth gerencia o fluxo de armas, armaduras e rações necessárias para sustentar uma guerra de fronteira prolongada. Para ele, a vitória contra as Sentinelas da Asa de Prata depende tanto de provisões constantes quanto da pura fúria de batalha."},{t="Suprimentos para o front",b="Hargunth distribui suprimentos especializados a guerreiros que provaram seu valor na ravina. De pacotes de suprimentos personalizados repletos de curativos de campanha e rações de ferro a armamentos magistrais com a insígnia carmesim do clã Brado Guerreiro, seus estoques são reservados estritamente àqueles que sangram pelas ambições territoriais da Horda nas florestas ricas em madeira ao norte."}},faq={{q="Quem é Kelm Hargunth?",a="Kelm Hargunth é um orc oficial de suprimentos que representa os Pioneiros do Brado Guerreiro. Destacado no Campo-base Mor'shan, no norte dos Sertões, ele distribui armas, armaduras e provisões de combate aos soldados da Horda que lutam na Ravina Brado Guerreiro.",al={"kelm hargunth","quem é kelm","vendedor de mor'shan","vendedor brado guerreiro"}},{q="Onde fica Kelm Hargunth?",a="Ele está destacado no Campo-base Mor'shan, situado no extremo norte dos Sertões, bem junto à muralha divisória que leva ao Vale Gris.",al={"localização de kelm","onde fica kelm hargunth","localização do oficial de suprimentos de mor shan"}},{q="A qual facção Kelm Hargunth serve?",a="Ele serve aos Pioneiros do Brado Guerreiro, a vanguarda da Horda dedicada a obter madeira e reivindicar território no sul do Vale Gris contra os elfos da noite.",al={"facção de kelm","intendente dos pioneiros do brado guerreiro","para quem kelm trabalha"}},{q="O que são os pacotes de suprimentos que Kelm oferece?",a="Hargunth distribui Pacotes de Suprimentos Básicos, Padrão e Avançados para os combatentes da linha de frente. Esses fardos de suprimentos contêm miudezas essenciais de campo de batalha, bandagens e rações para manter os combatentes da Horda sustentados na ravina.",al={"pacote de suprimentos do pioneiro","pacote de suprimentos de kelm","pacote de suprimentos brado guerreiro"}},{q="Por que o Campo-base Mor'shan é tão importante para os Brado Guerreiro?",a="O Campo-base Mor'shan atua como ponto de concentração fortificado e posto de controle entre os Sertões e o Vale Gris, permitindo que o clã Brado Guerreiro transporte suprimentos, reforços e madeira extraída com segurança para as terras da Horda.",al={"por que o campo-base mor'shan","objetivo de mor'shan","história do campo-base"}},{q="Que tipo de equipamento Kelm Hargunth fornece?",a="Ele equipa guerreiros comprovados com tabardos de batalha do Brado Guerreiro, armas especializadas como a Lâmina do Batedor e a Espada do Legionário, conjuntos de armadura sob medida, anéis e poções de campo de batalha destinadas ao combate a curta distância.",al={"equipamento jxj de kelm","recompensas brado guerreiro","o que kelm vende"}}},fx={bced0f9b={q="A quem Kelm Hargunth está ligado?",a="Kelm responde diretamente aos Pioneiros do Brado Guerreiro, a vanguarda da Horda que contesta as florestas densas de Vale Gris. Operando sob a bandeira do clã Brado Guerreiro e da Horda em geral, ele trabalha em sintonia com as forças de linha de frente que defendem o Campo-base Mor'shan.",al={"afiliação de kelm hargunth","para quem kelm hargunth trabalha","facção de kelm hargunth"}},["1810d113"]={q="Por que Kelm Hargunth está estacionado no Campo-base Mor'shan?",a="Kelm Hargunth serve como oficial de suprimentos dos Pioneiros do Brado Guerreiro bem na fronteira do Vale Gris. Estacionado no Campo-base Mor'shan, ele garante que os campeões da Horda que se dirigem à Ravina Brado Guerreiro estejam devidamente equipados para lutar contra as Sentinelas da Asa de Prata e garantir madeira e território vitais.",al={"por que kelm hargunth está aqui","propósito de kelm hargunth","por que kelm está em mor'shan"}},c16a55e1={q="O que Kelm Hargunth quer?",a="Kelm não quer nada menos que a vitória total da Horda contra os elfos noturnos na Ravina Brado Guerreiro. Como intendente dos Pioneiros, ele exige prova de seu valor no campo de batalha, oferecendo armamentos, suprimentos e pacotes de assistência para aqueles que atacam duramente a Aliança.",al={"o que kelm hargunth quer","objetivo de kelm hargunth","o que kelm quer"}}},fp="13,368,25.422.0,19.376.0,21.229.0,31.145.0,38.150.0,39.217.0,54.220.0,45.216.0"}
P.entries["npc:kerlonian-evershade"] = {n="Kerlonian Perenumbra",s="Kerlonian Perenumbra é um elfo noturno Druid of the Claw descansando no Bosque dos Ancientes, em Costa Negra. Tendo despertado recentemente do longo sono dentro do Sonho Esmeralda, ele precisa de ajuda para navegar pelas terras ermas corrompidas e alcançar a segurança do Entreposto de Maestra.",h="Kerlonian Perenumbra é um elfo noturno Druid of the Claw descansando no Bosque dos Ancientes, em Costa Negra.",kw={"costa negra","druid of the claw","sonho esmeralda","perenumbra","bosque dos ancientes","kerlonian","the sleeper has awakened"},ang={["class:Druid"]="Aventureiros druidas reconhecerão intimamente a provação de Kerlonian, já que todos os discípulos do Círculo Cenariano devem lidar com o pesado tributo da profunda comunhão com o Sonho Esmeralda.",["race:NightElf"]="Para os viajantes elfos noturnos, guiar Kerlonian representa proteger um de seus antigos defensores, recém-retornado a um mundo amplamente transformado desde a Third War."},sec={{t="Despertar em Costa Negra",b="Kerlonian Perenumbra pertence aos Druids of the Claw, seguidores do totem do urso que passaram séculos dormindo em túmulos subterrâneos e em comunhão com o Sonho Esmeralda. Os Druids of the Claw foram chamados de seu sono durante a Third War. Encontrado descansando sob as árvores ancestrais do Bosque dos Ancientes, Kerlonian ainda está se livrando do torpor sobrenatural de seu descanso prolongado. Sua preocupação imediata é viajar em segurança pelas florestas conturbadas de Costa Negra em direção ao Entreposto de Maestra, na fronteira do Vale Gris."},{t="Uma Jornada Traiçoeira",b="A estrada que sai do Bosque dos Ancientes está longe de ser segura. Fúrbolgs Blackwood rondam o Vale do Crepúsculo, e cultistas Dark Strand espreitam ao longo do caminho para o Vale Gris. Enfraquecido pelo sono e lutando contra crises repentinas de exaustão, Kerlonian conta com viajantes solidários da Aliança para protegê-lo enquanto segue para o sul para se reunir aos seus companheiros elfos noturnos."}},faq={{q="Quem é Kerlonian Perenumbra?",a="Kerlonian Perenumbra é um elfo noturno Druid of the Claw situado perto do Bosque dos Ancientes, em Costa Negra. Ele acordou recentemente do Sonho Esmeralda e precisa de ajuda para viajar em segurança pela floresta.",al={"quem é kerlonian","história de kerlonian perenumbra","druida no bosque dos ancientes"}},{q="Por que Kerlonian dorme enquanto caminha?",a="Como muitos Druids of the Claw que dormiram por séculos em covis subterrâneos, Kerlonian ainda sofre com o torpor residual do Sonho Esmeralda. Seu corpo e mente não se ajustaram totalmente à realidade desperta, causando crises repentinas de sonolência.",al={"por que kerlonian está dormindo","druida da missão sleeper has awakened","kerlonian sonolento"}},{q="Para onde ele está tentando ir?",a="Ele busca uma passagem segura para o sul até o Entreposto de Maestra, um posto avançado de elfos noturnos situado na fronteira entre Costa Negra e o Vale Gris, onde ele possa se recuperar em segurança.",al={"destino de kerlonian","para onde kerlonian vai","destino de escolta do bosque dos ancientes"}},{q="O que é um Druid of the Claw?",a="Os Druids of the Claw são druidas elfos noturnos que assumem a forma do grande urso. Eles canalizam força, resiliência e poder feral, tradicionalmente guardando túmulos subterrâneos e terras dos elfos noturnos enquanto passam eras dormindo no Sonho Esmeralda.",al={"o que é druid of the claw","história dos druids of the claw"}}},fx={["62482562"]={q="De que lado Kerlonian Perenumbra está?",a="Kerlonian é um Elfo Noturno, Druid of the Claw, alinhado ao Círculo Cenariano e aos Elfos Noturnos de Darnassus da Aliança. Sua devoção está com a natureza, o Sonho Esmeralda e seus irmãos druidas que protegem os bosques ancestrais por toda Kalimdor.",al={"facção de kerlonian","kerlonian é da aliança","lado de kerlonian perenumbra"}},["9e991c8a"]={q="O que Kerlonian Perenumbra quer?",a="Tendo despertado recentemente de seu longo sono no Sonho Esmeralda, Kerlonian não deseja nada além de uma passagem segura de volta para a companhia de seus companheiros Elfos Noturnos no Entreposto de Maestra. Seu transe profundo o deixa grogue, tornando a simples viagem por Costa Negra perigosa.",al={"objetivo de kerlonian","o que kerlonian perenumbra quer","propósito de kerlonian"}},["4cb7152a"]={q="Por que Kerlonian Perenumbra está aqui?",a="Kerlonian parou no Bosque dos Ancientes para um breve cochilo enquanto viajava para encontrar Liladris Luneflúvia no Entreposto de Maestra. Ele ainda está com sono depois de acordar do Sonho Esmeralda e pede ajuda para chegar até ela em segurança.",al={"por que kerlonian está em costa negra","kerlonian bosque dos ancientes","por que kerlonian está dormindo aqui"}},["0418b012"]={q="A quem Kerlonian Perenumbra está ligado?",a="Kerlonian pertence aos Druids of the Claw, uma ordem dentro do Círculo Cenariano dedicada ao espírito do urso e encarregada de guardar a natureza selvagem. Ele também está ligado por parentesco e dever aos Elfos Noturnos estacionados no Entreposto de Maestra, ao longo da fronteira de Vale Gris.",al={"ordem de kerlonian","ligações de kerlonian","quem kerlonian serve"}}},fp="19,262,22.522.0,21.367.0,27.204.0,45.243.0,25.154.0,28.229.0"}
P.entries["npc:kernobee"] = {n="Kernobill",s="Kernobill é um engenheiro goblin preso nas profundezas dos salões arruinados de Gnomeregan. Após descobrir segredos perigosos envolvendo sabotagem dos anões Ferro Negro, ele foi capturado, espancado até perder a consciência e deixado para morrer entre os troggs nos alojamentos.",h="Kernobill é um engenheiro goblin preso nas profundezas dos salões arruinados de Gnomeregan.",kw={"ferro negro","dormitório","gnomeregan","kernobill","vila catraca","superperfuratriz","tinkerwiz"},ang={["profession:Engineering"]="Engenheiros conseguem reconhecer o perigo absoluto de bisbilhotar maquinários subterrâneos experimentais como as perfuratrizes Ferro Negro quando esquemas rivais estão em jogo.",["race:Gnome"]="Para os gnomos que lutam para recuperar sua terra natal, as informações de Kernobill são a prova alarmante de que sua catástrofe foi impulsionada das sombras pela intromissão dos anões Ferro Negro."},sec={{t="Uma Descoberta Mortal",b="Enquanto conduzia negócios ou recolhia sucata na capital gnômica caída, Kernobill descobriu um segredo grave: os anões Ferro Negro estavam diretamente envolvidos na construção e operação da enorme superperfuratriz cavando sob a cidade. Percebendo o imenso valor — e a letalidade — dessa informação, ele tentou fugir imediatamente para Vila Catraca a fim de avisar seu associado, Tinkerwiz. Infelizmente, os Ferro Negro o capturaram antes que ele pudesse escapar."},{t="Deixado para os Troggs",b="Em vez de matá-lo na hora, seus captores espancaram Kernobill até deixá-lo inconsciente e o jogaram em uma pequena sala ao longo do corredor do dormitório, em frente à Clean Zone. Deixado à própria sorte entre troggs selvagens e a precipitação radioativa, o goblin ferido depende inteiramente de aventureiros que passam por ali para reanimá-lo e protegê-lo até que alcance a segurança."}},faq={{q="Quem é Kernobill?",a="Kernobill é um agente goblin encontrado inconsciente dentro do setor de dormitórios de Gnomeregan. Ele trabalha em estreita colaboração com Tinkerwiz em Vila Catraca e se aventurou nas ruínas antes de sofrer uma emboscada.",al={"quem é este goblin","história de kernobill","sobre kernobill"}},{q="Por que Kernobill foi aprisionado em Gnomeregan?",a="Kernobill descobriu que o clã Ferro Negro estava ajudando secretamente a construir as máquinas de superperfuração subterrâneas dentro da cidade. Para manter sua presença e sabotagem em segredo, os Ferro Negro o incapacitaram e o jogaram no dormitório para morrer.",al={"por que ele está aqui","por que os ferro negro o capturaram","por que no dormitório"}},{q="A quem Kernobill se reporta?",a="Ele se reporta a Tinkerwiz, um engenheiro goblin estabelecido do outro lado do mar, na cidade portuária neutra de Vila Catraca, nos Sertões.",al={"quem é tinkerwiz","para onde ele vai","conexão com vila catraca"}},{q="Onde Kernobill está localizado em Gnomeregan?",a="Ele está caído inconsciente em uma pequena sala lateral no nível inferior do Dormitório, situada no lado oeste, diretamente em frente à Clean Zone.",al={"localização de kernobill","onde fica kernobill","encontrar kernobill"}}},fx={["3c758521"]={q="De que lado Kernobill está?",a="Kernobill é afiliado ao Cartel Bondebico, respondendo a Tinkerwiz no porto neutro de Vila Catraca. Em vez de servir à Aliança ou à Horda, ele opera em negócios goblin — o que o colocou diretamente contra os anões Ferro Negro que espreitavam dentro de Gnomeregan quando ele descobriu seus esquemas.",al={"kernobill é da aliança ou horda","facção de kernobill","para quem kernobill trabalha"}},b63dca8d={q="O que Kernobill quer?",a="Kernobill não quer nada além de escapar de Gnomeregan vivo. Depois de descobrir que os anões Ferro Negro estavam envolvidos na construção da enorme superplataforma, ele precisa urgentemente sair do dormitório e fugir da cidade irradiada para que possa relatar suas descobertas a Tinkerwiz em Vila Catraca.",al={"o que kernobill está tentando fazer","objetivo de kernobill","por que ajudar kernobill"}}},fp="8,253,18.470.0,19.335.0,16.180.0,42.247.0,28.119.0,40.149.0"}
P.entries["npc:keryn-sylvius"] = {n="Anabela Cabreira",s="Anabela Cabreira é uma instrutora de ladinos humana localizada no segundo andar da Estalagem do Leão Orgulhoso de Vila d'Ouro. Escondida na sala de leitura da estalagem, ela ensina a malandros novatos o básico de furtividade e manuseio de lâminas, servindo ao mesmo tempo como um discreto canal de contato com o serviço de inteligência de Ventobravo.",h="Anabela Cabreira é uma instrutora de ladinos humana localizada no segundo andar da Estalagem do Leão...",kw={"floresta de elwynn","vila d'ouro","anabela cabreira","estalagem do leão orgulhoso","instrutor de ladinos","avin"},ang={["class:Rogue"]="Cabreira é a principal mentora de ladinos iniciantes que exploram a Floresta de Elwynn, encaminhando-os eventualmente ao quartel-general da AVIN em Ventobravo.",["faction:Alliance"]="Posicionada acima da encruzilhada de Vila d'Ouro, ela ajuda a manter abertos os olhos secretos da Aliança ao longo das principais vias de Elwynn."},sec={{t="Uma Presença Silenciosa em Vila d'Ouro",b="Enquanto o térreo da Estalagem do Leão Orgulhoso ferve de viajantes barulhentos e guardas cansados da vila, Anabela Cabreira permanece na calma sala de leitura no andar de cima. Aparentemente despretensiosa, ela observa o fluxo constante de fofocas da estrada e atua como a mentora local de ladinos dando seus primeiros passos na Floresta de Elwynn. Quando agentes promissores superam os pequenos furtos locais e as trapaças à beira da estrada, Cabreira os envia discretamente a Ventobravo para fazer contato com a AVIN."}},faq={{q="Onde posso encontrar Anabela Cabreira?",a="Ela está localizada no segundo andar da Estalagem do Leão Orgulhoso em Vila d'Ouro, reservada na pequena sala de leitura.",al={"localização de anabela cabreira","onde fica anabela","localização da instrutora de ladinos de vila d'ouro"}},{q="Quais serviços ela oferece?",a="Anabela Cabreira é uma instrutora de ladinos que ensina novas habilidades, redefine especializações de talentos e dá orientações a ladinos em desenvolvimento.",al={"o que anabela faz","ela pode me treinar","função de anabela cabreira"}},{q="Qual conexão ela tem com a AVIN?",a="Cabreira atua como um ponto inicial de contato para a rede secreta de inteligência de Ventobravo, enviando agentes habilidosos para procurar o Mestre Mathias Shaw e a AVIN na Cidade Velha assim que provam suas capacidades.",al={"anabela avin","ela é da avin","ela trabalha para ventobravo"}}},fx={["74741391"]={q="Quem é Anabela Cabreira?",a="Anabela Cabreira é uma instrutora de Ladino que faz do andar superior da Estalagem do Leão Orgulhoso de Vila d'Ouro sua casa. Escondida na silenciosa sala de leitura, ela observa o movimento da Floresta de Elwynn enquanto transmite as artes sutis de furtividade, arrombamento e subterfúgio para Ladinos promissores sob a bandeira da Aliança.",al={"quem é anabela","lore de anabela cabreira","quem é cabreira"}},["017a68dc"]={q="De que lado Anabela Cabreira está?",a="Anabela está firmemente ao lado do Reino de Ventobravo e da Aliança. Seu ofício serve aos interesses do reino, direcionando discretamente agentes talentosos para a rede de inteligência clandestina de Ventobravo, para que possam ajudar o reino contra a agitação interna e ameaças externas.",al={"anabela cabreira aliança ou horda","lealdade de anabela cabreira","quem anabela cabreira serve"}},["90e34396"]={q="O que Anabela Cabreira quer?",a="Anabela visa observar e instruir talentos brutos no coração tranquilo de Elwynn antes que eles infrinjam a lei ou façam mau uso de suas habilidades mortais. Uma vez que um aprendiz prova ser capaz, seu objetivo é canalizar suas habilidades para um serviço organizado, direcionando-os para a sede da AVIN na Cidade Velha.",al={"o que anabela quer","objetivos de anabela cabreira","por que treinar ladinos"}},f8e496c4={q="Por que Anabela Cabreira está aqui em Vila d'Ouro?",a="A Estalagem do Leão Orgulhoso serve como a movimentada encruzilhada da Floresta de Elwynn, tornando-a um lugar ideal para identificar discretamente Ladinos encontrando seu caminho fora do Vale de Vila Norte. Estacionar-se no andar de cima lhe dá um poleiro discreto para orientar novatos sem atrair atenção indevida dos guardas locais ou habitantes da cidade abaixo.",al={"por que anabela está na estalagem do leão orgulhoso","por que anabela cabreira está em vila d'ouro","anabela vila d'ouro por que"}}},fp="13,279,29.470.0,31.108.0,29.135.0,38.201.0"}
P.entries["npc:khelden-bremen"] = {n="Gaspar Melchior",s="Gaspar Melchior é um mago humano e instrutor localizado no andar superior da Abadia de Vila Norte, na Floresta de Elwynn. Ele supervisiona a instrução inicial de conjuradores novatos que se dedicam às artes arcanas a serviço de Ventobravo.",h="Gaspar Melchior é um mago humano e instrutor localizado no andar superior da Abadia de Vila Norte, na...",kw={"arcano","floresta de elwynn","carta glífica","gaspar melchior","instrutor de magos","abadia de vila norte"},ang={["class:Mage"]="Para magos humanos, Gaspar Melchior representa o primeiro passo formal no estudo arcano antes de darem continuidade ao treinamento avançado nas torres de Ventobravo."},sec={{t="Tutor do Arcano",b="Situado dentro das tranquilas muralhas de pedra da Abadia de Vila Norte, Gaspar Melchior atua como o principal instrutor para magos humanos novatos. Enquanto o clero e os defensores cuidam das atividades marciais e espirituais no andar de baixo, Melchior mantém um gabinete silencioso no andar de cima. Ali, ele apresenta aos novatos a disciplina, o foco e as técnicas fundamentais necessárias para manipular a energia mágica bruta com segurança antes de se aventurarem pela Floresta de Elwynn e além, rumo ao Distrito dos Magos de Ventobravo."}},faq={{q="Quem é Gaspar Melchior?",a="Gaspar Melchior é o instrutor de magos residente na Abadia de Vila Norte, na Floresta de Elwynn. Ele guia magos recém-despertados em seus primeiros feitiços e estudos arcanos fundamentais.",al={"quem é gaspar","melchior","instrutor de magos vila norte"}},{q="Onde posso encontrar Gaspar Melchior?",a="Ele está localizado no segundo andar da Abadia de Vila Norte. Entre na abadia e suba a escada que fica na segunda sala à esquerda.",al={"onde fica gaspar","localização de gaspar melchior","localização do instrutor de magos de vila norte"}},{q="Qual é o papel dele para novos aventureiros?",a="Aspirantes a magos humanos são direcionados a Gaspar ao chegarem a Vila Norte, frequentemente portando uma Carta glífica de recomendação. Ele ensina feitiços iniciais essenciais e ajuda os novatos a dominar sua aptidão mágica.",al={"o que gaspar faz","missões de melchior","destinatário da carta glífica"}}},fx={["7cfd66d2"]={q="De que lado está Gaspar Melchior?",a="Gaspar Melchior apoia firmemente o Reino de Ventobravo e a Aliança. Estacionado dentro da Abadia de Vila Norte, ele serve ao reino instruindo a próxima geração de conjuradores e preparando-os para defender as terras da humanidade contra os perigos crescentes.",al={"facção de gaspar melchior","a quem gaspar serve","gaspar melchior é da aliança"}},["032606f2"]={q="O que Gaspar Melchior deseja?",a="O objetivo de Gaspar é instruir magos novatos nas artes arcanas. Ele busca aprendizes dedicados, prontos para aprender encantamentos básicos, dominar seu intelecto crescente e controlar seu poder de forma responsável para a segurança da Floresta de Elwynn e de Ventobravo.",al={"objetivo de gaspar melchior","o que gaspar quer"}},["8660ec47"]={q="Por que Gaspar Melchior está aqui na Abadia de Vila Norte?",a="A Abadia de Vila Norte atua como um refúgio de recrutamento e treinamento para jovens defensores que atendem ao chamado de Ventobravo. Melchior reside no andar superior da abadia especificamente para receber praticantes humanos iniciantes e guiar seus primeiros passos na magia antes que eles se aventurem mais profundamente pelo reino.",al={"por que gaspar está em vila norte","por que gaspar melchior está aqui"}}},fp="14,225,19.459.0,22.172.0,32.134.0,43.205.0"}
P.entries["npc:kil-hala"] = {n="Kil'hala",s="Kil'hala é um instrutor de alfaiataria troll da selva estabelecido na Encruzilhada, nos Sertões. Habilidoso em trabalhar tanto com tecidos comuns quanto com materiais exóticos tecidos, ele instrui artesãos da Horda que buscam aprimorar sua costura. Além do fio comum, ele tece mantos de renda do éter para jovens magos da Horda que trazem para ele mechas de cabelo das Laughing Sisters de Vale Gris.",h="Kil'hala é um instrutor de alfaiataria troll da selva estabelecido na Encruzilhada, nos Sertões.",kw={"sertões","encruzilhada","kil'hala","laughing sisters","renda do éter","alfaiataria","instrutor"},ang={["faction:Horde"]="Fornecendo artigos têxteis e treinamento profissional na Encruzilhada, Kil'hala ajuda a equipar o bando de guerra e os viajantes que conquistam seu espaço nos Sertões.",["profession:Tailoring"]="Kil'hala é uma parada essencial para alfaiates da Horda de nível profissional que atravessam Kalimdor, ensinando técnicas de artesanato e oferecendo missões para tecer mantos mágicos exóticos."},sec={{t="Alfaiate dos Sertões",b="Posicionado no movimentado centro da Encruzilhada, Kil'hala oferece seus conhecimentos em alfaiataria a viajantes de passagem e a recrutas da Horda. Embora grande parte de seu ofício envolva rolos de tecido comuns e trajes adequados à vida nas planícies áridas, seu conhecimento se estende a têxteis mágicos raros. Como um favor à maga Denya, ele confecciona mantos de renda do éter para jovens magos que trazem para ele cabelos tirados das Laughing Sisters, dríades das florestas de Vale Gris."}},faq={{q="Quem é Kil'hala?",a="Kil'hala é um troll Lançanegra e um instrutor de alfaiataria localizado na Encruzilhada, nos Sertões. Ele ajuda artesãos da Horda a aprender o básico da tecelagem de tecidos e da confecção de trajes.",al={"identidade de kil'hala","quem é kil'hala","alfaiate da encruzilhada"}},{q="Onde posso encontrar Kil'hala?",a="Ele fica localizado nos Sertões, dentro do entreposto central da Encruzilhada, situado junto a outros instrutores de profissão da Horda.",al={"localização de kil'hala","onde fica kil'hala","local de kil'hala"}},{q="Quais tarefas Kil'hala dá aos alfaiates?",a="Ele mesmo não envia alfaiates em tarefas. Jovens magos da Horda enviados por Denya trazem para ele mechas de cabelo das Laughing Sisters, dríades próximas ao Refúgio Bosque Real de Vale Gris, e Kil'hala tece o cabelo em um Nether-lace Garment para eles.",al={"missões de kil'hala","missão das laughing sisters","nether-lace garment"}}},fx={["5b372e18"]={q="De que lado Kil'hala está?",a="Kil'hala é leal à Horda e ao seu povo Troll Lançanegra. Situado no coração da Encruzilhada, ele atua como instrutor de alfaiataria para ajudar a equipar viajantes, guerreiros e aspirantes a artesãos que fazem seu caminho por Kalimdor.",al={"kil'hala horda ou aliança","facção de kil'hala","quem kil'hala serve"}},["218c0279"]={q="Por que Kil'hala está aqui?",a="Kil'hala faz de sua casa a Encruzilhada, um hub vital que conecta Durotar, Mulgore e as terras selvagens do norte. Estar estacionado aqui permite que ele ofereça seu artesanato de agulha e orientação para o fluxo constante de aventureiros da Horda que atravessam os Sertões.",al={"por que kil'hala está na encruzilhada","por que kil'hala está nos sertões","motivo da localização de kil'hala"}},d6c7e4b6={q="O que Kil'hala quer?",a="Kil'hala busca compartilhar sua perícia em tecelagem e trabalho com tecido com outros membros da Horda. Ele treina alfaiates aspirantes e, como um favor à maga Denya, tece finos mantos de éter-renda para jovens magos que lhe trazem o cabelo das Laughing Sisters.",al={"objetivo de kil'hala","propósito de kil'hala","o que kil'hala precisa"}}},fp="8,364,21.428.0,16.189.0,26.124.0,41.228.0"}
P.entries["npc:kin-weelay"] = {n="Kin'weelay",s="Kin'weelay é um renomado curandeiro Lançanegra alocado no Acampamento Grom'gol, na Selva do Espinhaço. Enviado diretamente de Orgrimmar, ele oferece auxílio místico e conselhos à vanguarda da Horda na selva. Sua perícia espiritual é vital para desvendar mojos sombrios e ajudar no resgate do jovem Yenniku.",h="Kin'weelay é um renomado curandeiro Lançanegra alocado no Acampamento Grom'gol, na Selva do Espinhaço.",kw={"lançanegra","grom'gol","kin'weelay","kinweelay","olho da mente","selva do espinhaço","curandeiro","yenniku"},ang={["faction:Horde"]="Kin'weelay demonstra o valor do espiritualismo troll para os esforços de guerra da Horda, fornecendo contraestratégias mágicas contra ameaças que a força bruta não consegue deter.",["race:Troll"]="Para os trolls Lançanegra, Kin'weelay representa uma das autoridades espirituais mais respeitadas da tribo, dedicado a desfazer as maldições cruéis de seus parentes da selva."},sec={{t="Um Mestre do Mojo Lançanegra",b="Reconhecido entre os Lançanegra como um de seus mais poderosos praticantes da feitiçaria tradicional, Kin'weelay domina um profundo conhecimento sobre espíritos, malefícios e magia de almas. Quando surgem assuntos envolvendo espíritos ancestrais ou encantamentos de trolls hostis, os batedores da Horda na Selva do Espinhaço recorrem a ele para dissipar o véu mágico."},{t="A Missão em Grom'gol",b="Kin'weelay foi enviado ao sul, partindo das ruas empoeiradas de Orgrimmar, especificamente para apoiar Nimboya no Acampamento Grom'gol. Seu propósito vai além do simples apoio militar; ele se concentra em quebrar as amarras sinistras colocadas sobre Yenniku, o filho raptado da linhagem de confiança do Chefe Vol'jin. Para desfazer essa magia sombria, Kin'weelay busca reagentes poderosos — mais notavelmente o Olho da Mente — para criar uma gema anímica capaz de libertar espíritos aprisionados."}},faq={{q="Quem é Kin'weelay?",a="Kin'weelay é um estimado curandeiro troll Lançanegra alocado no Acampamento Grom'gol, no norte da Selva do Espinhaço. Conhecido por seu domínio da magia espiritual e de almas, ele foi despachado pela liderança da Horda a partir de Orgrimmar.",al={"história de kinweelay","quem é kin'weelay","curandeiro de gromgol"}},{q="Por que Kin'weelay está na Selva do Espinhaço?",a="Ele foi enviado ao Acampamento Grom'gol para emprestar seus talentos místicos a Nimboya e à expedição Lançanegra local, especialmente para encontrar e resgatar o jovem Yenniku das garras dos trolls da selva hostis.",al={"por que kinweelay está em gromgol","propósito de kinweelay"}},{q="O que Kin'weelay está tentando criar?",a="Kin'weelay busca obter uma relíquia conhecida como o Olho da Mente. Com sua feitiçaria, ele pretende refiná-la em uma gema anímica capaz de capturar e preservar em segurança a alma de Yenniku, rompendo o controle sombrio que domina o jovem.",al={"olho da mente kinweelay","o que kinweelay cria"}},{q="De onde vem Kin'weelay?",a="Ele viajou de Orgrimmar, onde a tribo Lançanegra mantém fortes laços e presença constante desde que se juntou à Horda e se estabeleceu nas Ilhas do Eco.",al={"origem de kinweelay","de onde veio kinweelay"}},{q="Como ele vê as outras tribos de trolls da Selva do Espinhaço?",a="Ele vê as tribos hostis da selva, como os Bloodscalp e os Rachacrânio, como rivais perigosos mergulhados em rituais violentos e corrompidos. Ele usa ativamente sua arte para anular seus encantamentos e recuperar jovens Lançanegra capturados.",al={"kinweelay outros trolls","kinweelay e bloodscalp"}},{q="Que tipo de itens Kin'weelay estuda?",a="Kin'weelay investiga curiosidades locais dotadas de ressonância natural ou amaldiçoada, incluindo os misteriosos cristais cantantes e colares de osso usados por trolls hostis da selva, estudando seu mojo para criar contramedidas.",al={"itens de kinweelay","cristais cantantes kinweelay"}}},fp="10,308,26.324.0,23.444.1,18.227.0,40.201.0,36.222.0,32.146.0,57.216.0,41.219.0"}
P.entries["npc:kindal-moonweaver"] = {n="Kindal Teceluna",s="Kindal Teceluna é uma elfa noturna reclusa em um recanto oculto nas montanhas escarpadas de Feralas, logo ao norte do Complexo do Temível Totem. Profundamente perturbada pelos maus-tratos à vida selvagem na natureza, ela observa a agressiva tribo tauren abaixo enquanto busca ajuda para libertar feras capturadas. Ela é parente de Jer'kai Moonweaver, compartilhando a missão de defender as criaturas inocentes da floresta.",h="Kindal Teceluna é uma elfa noturna reclusa em um recanto oculto nas montanhas escarpadas de Feralas, logo ao...",kw={"gládio cruel","feralas","liberdade para todas as criaturas","complexo do temível totem","caminho oculto","jer'kai moonweaver","kindal teceluna"},ang={["class:Druid"]="Druidas encontrarão pontos em comum com a dedicação singular de Kindal em preservar a vida da floresta e libertar espíritos da natureza aprisionados de cruéis gaiolas de ferro.",["class:Hunter"]="Caçadores sintonizados com as feras de Kalimdor podem respeitar os esforços de Kindal para proteger filhotes selvagens e punir aqueles que capturam animais por esporte ou malícia.",["race:NightElf"]="Kindal personifica a tradicional devoção kaldorei ao mundo natural, posicionando-se como uma guardiã isolada para feras ameaçadas por invasores externos."},sec={{t="Uma Vigilante no Topo dos Penhascos",b="Empoleirada em um caminho de montanha estreito e sinuoso, parcialmente escondido atrás de árvores a leste de Gládio Cruel, Kindal Teceluna mantém uma vigília secreta sobre o vale abaixo. Enquanto grande parte de Feralas é disputada entre a Horda, os elfos noturnos de Feathermoon e as antigas ruínas de Eldre'Thalas, Kindal se concentra em uma crueldade mais localizada e imediata. Abaixo, na depressão, a tribo Grimtotem opera um complexo fortificado, capturando e encurralando a fauna local por razões nada benignas. De seu mirante oculto, Kindal observa à espera de qualquer um disposto a enfrentar o acampamento inimigo e desfazer o sofrimento lá dentro."},{t="Compaixão pela Natureza",b="A principal preocupação de Kindal reside no equilíbrio sagrado e nas criaturas gentis de Feralas que não podem se defender contra captores brutais. Junto com seu parente, Jer'kai Moonweaver, ela busca a libertação de feras enjauladas e cuida de filhotes deixados desamparados pela caça predatória violenta. Em vez de se envolver em uma grande guerra territorial, sua atenção está voltada para a compaixão: libertar sprites enjaulados e encontrar um lar para um dardejante órfão."}},faq={{q="Onde Kindal Teceluna está localizada?",a="Kindal se esconde ao longo dos penhascos do norte de Feralas, logo a leste de Gládio Cruel e acima do Complexo do Temível Totem. Você pode alcançá-la encontrando um caminho de montanha estreito e oculto que sobe sinuoso atrás de um grupo de árvores.",al={"localização de kindal teceluna","como encontrar kindal","onde fica kindal"}},{q="Quem é Kindal Teceluna?",a="Ela é uma elfa noturna solitária dedicada ao bem-estar animal e à preservação natural em Feralas. Ela vigia o Complexo do Temível Totem para interromper a captura da vida selvagem local.",al={"história de kindal","quem é kindal"}},{q="Qual é o objetivo de Kindal em Feralas?",a="Kindal quer libertar criaturas capturadas presas em gaiolas dentro do Complexo do Temível Totem nas proximidades e garantir que feras selvagens órfãs sejam resgatadas e recebam um abrigo seguro.",al={"objetivo da missão de kindal","por que kindal está aqui"}},{q="Kindal Teceluna é parente de Jer'kai Moonweaver?",a="Sim, Kindal é parente de Jer'kai Moonweaver. Ambas compartilham o sobrenome Moonweaver e colaboram no esforço para resgatar criaturas da floresta maltratadas e desabrigadas em Feralas.",al={"relação com jerkai moonweaver","kindal e jerkai"}},{q="Por que Kindal se opõe aos Grimtotem?",a="O clã Grimtotem que ocupa o complexo abaixo de seu mirante na montanha captura e enjaula feras selvagens de Feralas. Kindal busca libertar essas criaturas do cativeiro e punir seus captores.",al={"kindal grimtotem","complexo do temível totem kindal"}},{q="Kindal Teceluna oferece missões para ambas as facções?",a="Não. As missões de Kindal são oferecidas apenas à Aliança, cujos aventureiros ela recruta para libertar as criaturas enjauladas dos Grimtotem.",al={"kindal é amistosa com a horda","a horda pode falar com kindal"}}},fp="17,391,26.598.0,23.447.0,35.210.0,25.182.0,33.174.0,51.175.0,37.191.0,53.131.0"}
P.entries["npc:kirge-sternhorn"] = {n="Kirge Chifre Austero",s="Kirge Chifre Austero é um tauren posicionado na fronteira acidentada dos Sertões. Servindo como uma presença constante para os viajantes que cruzam a região central de Kalimdor, ele orienta os aventureiros novatos da Horda para o norte, em direção ao posto avançado vital da Encruzilhada.",h="Kirge Chifre Austero é um tauren posicionado na fronteira acidentada dos Sertões.",kw={"sertões","a encruzilhada","kirge","sertões meridionais","chifre austero","taurajo","tauren"},ang={["faction:Horde"]="Para os viajantes que chegam das áreas do sul, Kirge atua como um ponto de passagem inicial, direcionando-os para a maior comunidade da Horda na Encruzilhada.",["race:Tauren"]="Kirge representa o espírito acolhedor e sensato dos Shu'halo, guiando parentes tribais e aliados através da fronteira severa de seu lar adotivo."},sec={{t="Um Andarilho nos Sertões",b="As vastas planícies castigadas pelo sol dos Sertões são intimidantes para os andarilhos recém-chegados, e Kirge Chifre Austero atua como um guia prestativo em seu caminho. Estacionado ao sul das trilhas centrais, ele vigia os viajantes que se deslocam entre os acampamentos do sul e o coração de Kalimdor. Compreendendo os perigos dos javatuscos saqueadores e dos predadores ferozes que vagam pela savana, Kirge garante que os jovens aventureiros encontrem seu rumo e busquem a maior presença da Horda que se reúne ao norte."}},faq={{q="Quem é Kirge Chifre Austero?",a="Kirge Chifre Austero é um andarilho e guia tauren estacionado nos trechos ao sul dos Sertões, ajudando os viajantes da Horda que navegam pelas planícies empoeiradas.",al={"história de kirge chifre austero","quem é kirge","pnc kirge"}},{q="Para onde Kirge envia os viajantes?",a="Kirge direciona os viajantes para o norte em direção à Encruzilhada, a junção central nos Sertões onde as forças da Horda coordenam a defesa e a exploração por toda a região.",al={"missão de kirge","jornada para a encruzilhada kirge","para onde kirge envia você"}},{q="A qual facção Kirge Chifre Austero serve?",a="Kirge é leal à Horda e aos seus companheiros taurens, oferecendo orientação e assistência a todos os membros da facção que viajam pelo território.",al={"kirge é da horda","lealdade de kirge"}}},fp="15,248,25.483.0,23.150.0,32.161.0,40.146.0"}
P.entries["npc:klannoc-macleod"] = {n="Klannoc Macleod",s="Klannoc Macleod é um guerreiro humano rústico que reside na Ilha da Peleja, situada na costa leste dos Sertões. Conhecido como um árbitro da proeza marcial, ele testa lutadores aspirantes tanto da Aliança quanto da Horda que buscam dominar posturas de combate. Aqueles que conquistam seu respeito são direcionados para o interior, rumo a provações de força ainda maiores.",h="Klannoc Macleod é um guerreiro humano rústico que reside na Ilha da Peleja, situada na costa leste dos...",kw={"sertões","berserker","ilha da peleja","ilhéu","klannoc","macleod","a contenda","guerreiro"},ang={["class:Warrior"]="Klannoc Macleod é uma figura crucial na jornada de um guerreiro, testando sua resistência e ferocidade na Contenda antes de guiar você no domínio da Postura de Berserker.",["faction:Alliance"]="Guerreiros da Aliança precisam se aventurar pelas águas de Kalimdor, na costa dos Sertões, para encontrar Klannoc e provar sua prontidão para o combate na Ilha da Peleja.",["faction:Horde"]="Embora seja humano, Klannoc permanece indiferente às rivalidades de facção, acolhendo combatentes da Horda que vêm em busca de provação e honra em sua ilha isolada."},sec={{t="O Mestre da Ilha da Peleja",b="Isolado na Ilha da Peleja, ao largo da Costa dos Mercadores nos Sertões, Klannoc Macleod supervisiona um campo de testes brutal para combatentes experientes. Apesar de ser humano, Klannoc se mantém à parte das querelas políticas típicas da Aliança e da Horda, avaliando os competidores unicamente pela garra, habilidade com a lâmina e determinação sob fogo cruzado."},{t="A contenda",b="Os guerreiros direcionados à Ilha da Peleja são submetidos ao teste de Macleod: a Contenda. Os desafiantes sobem em uma grade de ferro elevada para resistir a ondas incessantes de lutadores ansiosos enquanto Klannoc observa. Aqueles que resistem ao massacre e derrotam seu campeão escolhido ganham seu selo de aprovação, provando que possuem o temperamento necessário para o treinamento de berserker."}},faq={{q="Quem é Klannoc Macleod?",a="Klannoc Macleod é um guerreiro humano veterano que habita a Ilha da Peleja, bem perto da costa dos Sertões. Ele atua como instrutor e mestre de provações para guerreiros que se esforçam para testar seus limites e desbloquear novas técnicas.",al={"quem é klannoc","história de klannoc macleod","homem da ilha da peleja"}},{q="Onde posso encontrar Klannoc Macleod?",a="Klannoc fica na Ilha da Peleja, uma ilha rochosa na costa leste dos Sertões, a sudeste da Costa dos Mercadores e de Vila Catraca. Você precisa nadar pelas águas abertas para alcançar o acampamento dele.",al={"localização de klannoc","onde fica a ilha da peleja","como chegar a klannoc"}},{q="Por que um humano fala com jogadores da Horda na Ilha da Peleja?",a="Klannoc opera fora do conflito tradicional entre a Aliança e a Horda. Como um mestre de combate independente, ele se importa apenas com a disciplina marcial e o espírito do guerreiro, testando de bom grado qualquer competidor que chegue com uma recomendação adequada.",al={"klannoc é hostil com a horda","por que klannoc é neutro","klannoc horda"}},{q="O que é a Contenda?",a="A Contenda é uma prova de resistência realizada na Ilha da Peleja. Um guerreiro precisa ficar no topo da plataforma de combate de Klannoc e derrotar ondas de desafiantes, culminando em uma batalha contra Big Will, provando que tem a ferocidade necessária para técnicas avançadas de guerreiro.",al={"missão a contenda","provação da ilha da peleja","provação de klannoc"}},{q="Por que enviar guerreiros para Klannoc Macleod?",a="Instrutores de guerreiros por toda Azeroth indicam seus alunos mais promissores a Klannoc para que passem por uma prova de fortitude marcial, necessária a fim de prepará-los para o foco feroz da Postura de Berserker.",al={"missão de guerreiro ilha da peleja","por que visitar klannoc","missão postura de berserker"}},{q="Para quem Klannoc envia você após a Contenda?",a="Após provar seu valor na Contenda, Klannoc direciona os guerreiros para o norte, rumo às Montanhas de Alterac, perto da Serraria Tarren, para procurar Bath'rah, o Vigia dos Ventos, em busca de mais orientação.",al={"depois de klannoc","missão o vigia dos ventos","quem é o vigia dos ventos"}}},fx={bf19a78f={q="O que Klannoc Macleod quer?",a="Klannoc supervisiona os testes de combate na Ilha da Peleja, buscando apenas brigões capazes dignos de entrar no ringue para The Affray. Ele não se importa com a política das facções ou origens pessoais, exigindo apenas que aqueles que buscam seu conselho provem sua coragem e resistência em batalhas exaustivas antes de direcioná-los para um treinamento marcial maior.",al={"o que klannoc macleod quer","o que klannoc quer","propósito de klannoc"}}},fp="15,346,25.330.0,10.352.0,23.214.0,33.185.0,54.232.0,19.252.0,37.191.0,46.174.1"}
P.entries["npc:kor-ghan"] = {n="Kor'ghan",s="Kor'ghan é um troll da selva Lançanegra que pode ser encontrado perambulando pelas cavernas sombrias do Antro das Sombras, em Orgrimmar. Posicionado logo em frente ao Rekkul's Poisons, ele busca ajuda para preparar remédios contra predadores venenosos da natureza.",h="Kor'ghan é um troll da selva Lançanegra que pode ser encontrado perambulando pelas cavernas sombrias do Antro...",kw={"antídoto","antro das sombras","kor'ghan","korghan","orgrimmar","rekkul's poisons","veneno de escorpídeo","aldeia sen'jin"},ang={["class:Rogue"]="Posicionado diretamente do lado de fora do Rekkul's Poisons no Antro das Sombras, Kor'ghan é uma figura familiar para os ladinos que visitam os subterrâneos de Orgrimmar em busca de reagentes e venenos.",["race:Troll"]="Como muitos de seus irmãos Lançanegra que deixaram a Aldeia Sen'jin, Kor'ghan faz bom uso de seu conhecimento prático sobre os perigos selvagens de Durotar na capital fortificada da Horda."},sec={{t="Um Troll nas Sombras",b="Parado em frente ao Rekkul's Poisons nas profundezas cavernosas do Antro das Sombras, Kor'ghan vigia de perto tanto remédios quanto toxinas. Da capital, ele despacha aventureiros pelos desfiladeiros vermelhos para coletar componentes venenosos dos escorpídeos de Durotar a fim de preparar antídotos vitais."}},faq={{q="Quem é Kor'ghan?",a="Kor'ghan é um troll Lançanegra localizado no Antro das Sombras em Orgrimmar, parado do lado de fora da loja de venenos de Rekkul.",al={"kor'ghan","quem é kor'ghan","npc korghan"}},{q="Onde posso encontrar Kor'ghan?",a="Ele está localizado no Antro das Sombras subterrâneo, sob a região central de Orgrimmar, posicionado diretamente em frente ao Rekkul's Poisons.",al={"localização de kor'ghan","onde fica korghan","encontrar korghan"}},{q="Com o que Kor'ghan precisa de ajuda?",a="Ele recruta viajantes para coletar bolsas de veneno dos escorpídeos caudaveneno que vagam perto da entrada de Orgrimmar, ajudando a formular antídotos.",al={"missão de kor'ghan","missão em busca do antídoto","veneno de korghan"}},{q="Kor'ghan já foi encontrado em Durotar?",a="Ele próprio não. Kor'ghan permanece em seu posto perto dos fornecedores de veneno em Orgrimmar, mas envia aventureiros a Durotar para coletar bolsas de veneno dos escorpídeos caudaveneno perto da entrada da cidade.",al={"kor'ghan sen'jin","antiga localização de korghan"}}},fx={["8434b88c"]={q="De que lado Kor'ghan está?",a="Kor'ghan está alinhado à Horda. Como um Troll Lançanegra da selva que habita profundamente dentro do Antro das Sombras de Orgrimmar, suas lealdades repousam firmemente com seu povo e o novo lar que compartilham sob o comando do Chefe Guerreiro Thrall.",al={"facção de kor'ghan","kor'ghan é da horda","kor'ghan aliança ou horda"}},["041d8a17"]={q="Por que Kor'ghan está aqui?",a="Kor'ghan faz seu lugar logo fora do Rekkul's Poisons nas profundezas sombrias do Antro das Sombras. Permanecendo entre os praticantes de Ladino e alquimistas da cidade, ele busca ajuda especializada e remédios venenosos daqueles que lidam com misturas perigosas.",al={"por que kor'ghan está em orgrimmar","por que kor'ghan está no antro das sombras","o que trouxe kor'ghan aqui"}}},fp="8,246,22.296.0,16.113.0,26.125.0,34.138.0,35.197.0"}
P.entries["npc:korran"] = {n="Korran",s="Korran é um pesquisador troll Lançanegra alocado na Encruzilhada, nos Sertões. Servindo a Belgrom Rockmaul em Orgrimmar, ele monitora acontecimentos estranhos pelas terras áridas e estuda a ameaça emergente dos insetoides silitídeos.",h="Korran é um pesquisador troll Lançanegra alocado na Encruzilhada, nos Sertões.",kw={"sertões","belgrom rockmaul","a encruzilhada","ovo tipo extra","campo dos gigantes","korran","silitídeo"},ang={["faction:Horde"]="Korran representa o olho vigilante da Horda sobre a ecologia em mutação de Kalimdor, garantindo que novas ameaças como os silitídeos não peguem Orgrimmar de surpresa enquanto ela protege suas fronteiras.",["race:Troll"]="Como um troll Lançanegra, Korran traz instintos aguçados de exploração e sobrevivência para os áridos Sertões, aplicando astúcia pragmática para dissecar feras estranhas e alienígenas."},sec={{t="Um batedor na Encruzilhada",b="Enquanto a maioria na Encruzilhada se preocupa com os javatuscos agressivos e os clãs locais de centauros, Korran mantém um olho vigilante sobre ameaças mais sutis e insidiosas. Estacionado por ordens de Belgrom Rockmaul em Orgrimmar, o batedor troll observa as mudanças na terra e coordena a coleta de informações para a liderança da Horda."},{t="A incursão dos silitídeos",b="A principal preocupação de Korran voltou-se para o sul, em direção ao Campo dos Gigantes, onde estranhas criaturas insetoides conhecidas como silitídeos começaram a escavar a terra. Inquieto com sua natureza agressiva e seu avanço acelerado, ele recruta aventureiros que passam pelo local para desenterrar ovos intactos usando sua ferramenta de garra, tentando decifrar de onde o enxame se originou e qual perigo ele representa para a jovem Horda."}},faq={{q="Quem é Korran?",a="Korran é um troll Lançanegra alocado na Encruzilhada, nos Sertões. Ele atua como observador e pesquisador, reportando-se a Belgrom Rockmaul em Orgrimmar.",al={"quem é korran","korran troll","troll da encruzilhada"}},{q="O que Korran está investigando nos Sertões?",a="Ele está investigando as criaturas insetoides estranhas e agressivas conhecidas como silitídeos, que surgiram nos Sertões Meridionais no Campo dos Gigantes, além de enxames semelhantes relatados mais ao sul, em Mil Agulhas.",al={"o que korran estuda","pesquisa de korran","insetos do campo dos gigantes"}},{q="Para quem Korran trabalha?",a="Korran serve a Belgrom Rockmaul, um guerreiro veterano posicionado no Vale da Honra em Orgrimmar, que monitora ameaças emergentes por toda Kalimdor para a Horda.",al={"quem enviou korran","superior de korran","belgrom rockmaul"}},{q="Por que Korran precisa de ovos de silitídeo?",a="Ele precisa de ovos intactos para examinar o ciclo de vida e as origens do enxame de silitídeos. Ao estudar espécimes jovens, Korran espera entender o que são essas criaturas e determinar o tamanho da ameaça que representam para o território da Horda.",al={"por que ovos de silitídeo","missão ovo tipo extra","garra de korran"}}},fx={b07b8377={q="De que lado Korran está?",a="Korran é um batedor leal da Horda estacionado na Encruzilhada. Ele responde diretamente a Belgrom Rockmaul, um oficial proeminente em Orgrimmar, mantendo o comando do chefe guerreiro informado sobre distúrbios estranhos pelos Sertões.",al={"facção de korran","korran é da horda","lealdade de korran"}}},fp="6,229,25.335.0,22.389.0,14.158.0,44.220.0,25.157.0,35.226.0"}
P.entries["npc:kravel-koalbeard"] = {n="Kravel Barbakarvão",s="Kravel Barbakarvão é um conspirador, empresário anão e vigarista estabelecido no Circuito da Ilusão, na Chapada Cintilante. Em vez de torcer apenas pelo amor ao esporte, ele enxerga a feroz rivalidade de corrida entre gnomos e goblins como uma oportunidade de ouro para encher os bolsos. Desde recolher peças mecânicas perdidas até manipular resultados de corridas com chantagem e bebidas alcoólicas, Kravel está sempre à caça do seu próximo esquema lucrativo.",h="Kravel Barbakarvão é um conspirador, empresário anão e vigarista estabelecido no Circuito da Ilusão, na...",kw={"chantagem","barbakarvao","kravel","circuito da ilusão","carro-foguete","sabotagem","chapada cintilante","mil agulhas"},ang={["class:Rogue"]="Ladinos acharão o ramo de trabalho de Kravel familiar: roubo, sabotagem, chantagem e manipulação de alvos gananciosos a partir das sombras.",["race:Dwarf"]="Diferente dos mineradores, garimpeiros e montanheses honestos de Altaforja, Kravel é um patife e trapaceiro descarado que envergonha os valores tradicionais dos anões.",["race:Gnome"]="Gnomos devem ficar bem atentos às suas bebidas e projetos perto de Kravel, que está tão disposto a dopar pilotos gnomos quanto a sabotar suas máquinas."},sec={{t="Um Vigarista na Chapada",b="Enquanto a maioria dos espectadores e membros das equipes no Circuito da Ilusão está absorta em rivalidades mecânicas e no rugido dos motores de foguete, Kravel Barbakarvão mantém os olhos fixos nas bolsas de moedas de todos. Ele é um oportunista que opera nas frestas empoeiradas do acampamento do circuito, sempre pronto para oferecer contratos e favores que raramente têm motivos limpos. Kravel vê o atrito de alto risco entre engenheiros gnomos e goblins não como uma competição inspiradora, mas como um terreno fértil para extorsão, sabotagem e roubo."},{t="Manipulando a Pista",b="As operações de Kravel vão muito além de recolher sucata descartada no deserto de sal. Para manipular as probabilidades e garantir que os resultados favoreçam o seu lado, Kravel costuma enviar aventureiros dispostos em tarefas ilícitas — espalhando boatos, executando esquemas de chantagem e até embebedando equipes dos boxes pouco antes de uma disputa. Seja empanturrando mecânicos goblins com bebidas fortes ou oferecendo drinques pesados a pilotos gnomos, Kravel se rebaixa a qualquer truque sujo necessário para encher os bolsos no dia da corrida."}},faq={{q="Quem é Kravel Barbakarvão?",a="Kravel Barbakarvão é um conspirador e oportunista anão estabelecido no Circuito da Ilusão, na Chapada Cintilante. Ele se aproveita da rivalidade entre gnomos e goblins para encher os bolsos por meio de coleta de sucata, manipulação de corridas e extorsão.",al={"quem e kravel","identidade de kravel barbakarvao","anao do circuito da ilusao"}},{q="O que Kravel Barbakarvão faz no Circuito da Ilusão?",a="Kravel contrata viajantes para realizar tarefas escusas pelo circuito. Seus esquemas incluem coletar Peças de carro-foguete recuperadas, desenterrar material para chantagem e sabotar equipes de corrida embebedando seus mecânicos e pilotos para influenciar os resultados das corridas.",al={"proposito de kravel","o que kravel quer","esquemas de kravel"}},{q="Por que Kravel tenta embebedar as equipes de corrida?",a="Kravel aposta pesado no resultado das corridas de carros-foguete. Ao embebedar os gnomos ou os goblins antes da corrida, ele manipula a disputa para favorecer o resultado que lhe render mais lucro.",al={"missao embebedar os gnomos","embebedar os goblins","sabotagem de kravel"}},{q="Onde Kravel Barbakarvão pode ser encontrado?",a="Ele fica na Chapada Cintilante, em Mil Agulhas, rondando os agitados acampamentos dos boxes do Circuito da Ilusão.",al={"localizacao de kravel","onde fica kravel","kravel mil agulhas"}},{q="Kravel tem contatos fora de Mil Agulhas?",a="Sim. Seus negócios escusos envolvem contatos nos portos goblins de Vila Catraca e Angra do Butim, incluindo negociações ligadas ao Mestre Portuário Caruncho de Vila Catraca, fofoqueiros e bebidas exóticas da Selva do Espinhaço.",al={"kravel angra do butim","conexoes de kravel"}},{q="Kravel trabalha tanto com a Aliança quanto com a Horda?",a="Como muitas figuras que atuam em locais neutros como o Circuito da Ilusão, Kravel está mais interessado em ouro do que em lealdade a facções. Ele contrata de bom grado aventureiros da Aliança e da Horda para realizar seus esquemas.",al={"kravel e apenas da alianca","a horda pode falar com kravel"}}},fx={["33aea695"]={q="O que Kravel Koalbeard quer?",a="Kravel é inteiramente movido pelo lucro e pelo interesse próprio. Ele busca encher seus bolsos através de qualquer esquema disponível na Chapada Cintilante, desde executar peças e vender favores até orquestrar chantagens. Sua ambição mais audaciosa é manipular o resultado do próprio Circuito da Ilusão, planejando sabotar e fraudar as competições mantendo as equipes de pit e os pilotos completamente embriagados.",al={"o que kravel quer","objetivos de kravel koalbeard","motivações de kravel"}},["97572808"]={q="Por que Kravel Koalbeard está em Mil Agulhas?",a="O Circuito da Ilusão na Chapada Cintilante é um covil sem lei de apostas de alto risco, rivalidade feroz e engenharia imprudente, tornando-o um terreno de caça privilegiado para um vigarista. Kravel montou acampamento ao lado dos Gnomos e Goblins competidores porque sua obsessão amarga em vencer uns aos outros os deixa cegos para oportunistas e alvos fáceis para seus esquemas.",al={"por que kravel está aqui","por que kravel está no circuito da ilusão","kravel chapada cintilante"}}},fp="16,424,25.509.0,17.494.1,24.220.0,52.252.0,45.208.0,36.127.0,47.201.0,46.215.0"}
P.entries["npc:kreldig-ungor"] = {n="Kreldig Ungor",s="Kreldig Ungor é um empreendedor operativo anão que representa a Reclaimers Inc., posicionado no alto dos penhascos do Posto do Nijel em Desolação. Encarregado de gerenciar operações de campo na terra devastada e estéril, ele contrata aventureiros da Aliança para recuperar cargas perdidas e proteger reagentes locais valiosos. Seus contratos de resgate e recuperação fazem dele um contato central para viajantes que desbravam a região hostil.",h="Kreldig Ungor é um empreendedor operativo anão que representa a Reclaimers Inc., posicionado no alto dos...",kw={"aliança","desolação","anão","naufrágio de karnitol","kreldig ungor","posto do nijel","reclaimers inc","resgate"},ang={["faction:Alliance"]="Instalado no Posto do Nijel, Kreldig depende inteiramente de viajantes da Aliança para manter seus contratos de resgate em andamento em um território de outra forma hostil.",["race:Dwarf"]="Kreldig demonstra o clássico apetite anão pela exploração de fronteiras acidentadas e pela ambição comercial, estabelecendo-se longe dos salões das montanhas."},sec={{t="Agente de Campo nas Terras Ermas",b="O Posto do Nijel oferece à Aliança um raro refúgio em meio aos desfiladeiros assolados de Desolação, tornando-se uma base ideal para oportunistas comerciais como Kreldig Ungor. Representando a Reclaimers Inc., Kreldig aventurou-se para longe da segurança de Khaz Modan rumo a uma terra selvagem e desolada disputada por clãs de centauros, demônios e pela Horda. Onde outros veem ruína e cinzas, Kreldig enxerga lucros inexplorados e bens perdidos prontos para serem recuperados."},{t="O Contrato de Karnitol",b="Um dos principais empreendimentos que trouxe Kreldig a Desolação envolve a embarcação perdida de Karnitol, que naufragou ao longo da traiçoeira costa oeste. A remessa de Karnitol continha mercadorias valiosas, e Kreldig organiza esforços para rastrear os destroços e resgatar a carga dispersa antes que saqueadores ou gigantes do mar costeiros tomem posse de tudo."},{t="Coleta de Reagentes Locais",b="Além do resgate marítimo, Kreldig supervisiona a obtenção dos estranhos tesouros biológicos e minerais de Desolação para a Reclaimers Inc. O ambiente hostil gera uma fauna e flora únicas, cujas partes alcançam preços elevados entre alquimistas e engenheiros nos Reinos do Leste. Aventureiros dispostos a enfrentar os predadores das terras devastadas encontram pagamento garantido sob o livro-razão de Kreldig."}},faq={{q="Quem é Kreldig Ungor?",a="Kreldig Ungor é um operativo anão associado à Reclaimers Inc., sediado no entreposto da Aliança no Posto do Nijel, em Desolação. Ele coordena missões de resgate e coleta de espécimes por toda a zona.",al={"história de kreldig ungor","quem é kreldig","kreldig ungor"}},{q="O que é a Reclaimers Inc.?",a="A Reclaimers Inc. é um empreendimento voltado para o resgate de cargas perdidas, recuperação de destroços e coleta de reagentes raros em fronteiras perigosas em busca de lucro.",al={"reclaimers inc","quem são a reclaimers inc","negócios da reclaimers"}},{q="Onde Kreldig Ungor pode ser encontrado?",a="Ele está localizado no assentamento da Aliança do Posto do Nijel, situado no alto das montanhas rochosas do nordeste de Desolação.",al={"localização de kreldig ungor","onde fica kreldig","encontrar kreldig ungor"}},{q="O que Kreldig quer com o naufrágio de Karnitol?",a="Um navio que transportava mercadorias valiosas pertencentes a Karnitol naufragou ao longo da costa de Desolação. Kreldig emprega aventureiros para localizar os destroços e proteger a carga perdida antes que seja saqueada ou destruída.",al={"naufrágio de karnitol","kreldig karnitol","naufrágio em desolação"}},{q="Por que Kreldig está coletando reagentes em Desolação?",a="O ambiente inóspito de Desolação abriga criaturas raras e compostos naturais únicos. Kreldig coleta esses espécimes para abastecer alquimistas, artífices e compradores nas principais cidades da Aliança.",al={"reagentes para reclaimers inc","reagentes de desolação","por que coletar reagentes"}},{q="Kreldig trabalha para Altaforja ou para uma empresa privada?",a="Embora opere a partir de um posto avançado da Aliança e contrate exclusivamente andarilhos da Aliança, Kreldig representa a Reclaimers Inc., um empreendimento comercial focado em resgate e comércio, em vez de objetivos militares reais oficiais.",al={"kreldig aliança ou privado","reclaimers inc altaforja"}}},fx={ad7684ca={q="Por que Kreldig Ungor está estacionado no Posto do Nijel?",a="Kreldig Ungor montou sua loja no alto do Posto do Nijel para buscar empreendimentos comerciais para a Reclaimers Inc. por toda a extensão acidentada de Desolação. Deste refúgio fortificado da Aliança, ele supervisiona operações de salvamento e aquisição com relativa segurança, usando-o como base para contratar aventureiros resistentes para empreitadas nas perigosas terras ermas.",al={"por que kreldig ungor está aqui","kreldig ungor posto do nijel","por que kreldig está em desolação"}}},fp="13,399,25.429.0,21.323.0,25.373.0,21.203.0,24.163.0,33.120.0,51.197.0,47.195.0,56.219.0"}
P.entries["npc:krolg"] = {n="Krolg",s="Krolg é um furbolg não corrompido que vive em uma cabana isolada ao sul do Lago Mistral, em Vale Gris. Anteriormente um membro da tribo Foulweald, ele foi expulso por seus parentes, que sucumbiram à loucura demoníaca, e só falará com aqueles que aparecerem diante dele em forma de furbolg.",h="Krolg é um furbolg não corrompido que vive em uma cabana isolada ao sul do Lago Mistral, em Vale Gris.",kw={"furbolg de vale gris","chief murgut","bastão de dartol","foulweald","krolg","cabana de krolg","lago mistral","raene's cleansing"},ang={["class:Druid"]="Druidas que buscam restaurar o equilíbrio em Vale Gris encontram em Krolg uma voz lúcida e inestimável em meio a uma paisagem tomada por animais corrompidos.",["faction:Alliance"]="Batedores da Aliança que auxiliam Raene Correlobos contam com Krolg para desmantelar a liderança dos hostis furbolgs Foulweald.",["race:NightElf"]="Para os elfos noturnos de Astranaar, Krolg representa uma lembrança agridoce de seus antigos aliados furbolgs antes de a corrupção demoníaca despedaçar as tribos."},sec={{t="Uma Mente Intacta",b="Enquanto a maioria dos furbolgs Foulweald em Vale Gris sucumbiu à mácula demoníaca deixada pela Legião Ardente, Krolg permanece lúcido e intocado pela loucura. Residindo em um abrigo isolado ao sul do Lago Mistral, ele mantém uma vigília cautelosa sobre a floresta. Tendo testemunhado a trágica decadência de seus irmãos em uma violência insensata, ele se recusa a interagir com forasteiros à primeira vista, falando apenas com seres que aparentem ser de sua espécie."},{t="O Legado de Dartol",b="Por meio do encanto mágico do Bastão de Transformação de Dartol, viajantes da Aliança conseguem se disfarçar sob a aparência de um furbolg. Ao ver o que parece ser um espírito semelhante e amigável, Krolg se abre e revela percepções cruciais para purificar a terra. Ele direciona heróis contra Ran Bloodtooth e seus guardas, cuja corrupção e ódio ameaçam a floresta."}},faq={{q="Por que Krolg não fala comigo?",a="Krolg desconfia profundamente de forasteiros e tem pavor do caos violento que consome a floresta. Ele ignorará você completamente, a menos que esteja sob a transformação de furbolg concedida pelo Bastão de Transformação de Dartol durante a série de missões Raene's Cleansing.",al={"krolg não fala","não consigo falar com krolg","por que krolg está em silêncio"}},{q="Onde Krolg pode ser encontrado?",a="Ele vive em um pequeno abrigo conhecido como Krolg's Hut, situado logo ao sul do Lago Mistral, no centro-sul de Vale Gris.",al={"localização de krolg","onde fica krolg","cabana de krolg"}},{q="A qual tribo Krolg pertence?",a="Originalmente, Krolg fazia parte da tribo Foulweald. Ao contrário do restante de seus parentes, que sucumbiram à corrupção e ao frenesi demoníaco, ele manteve sua sanidade e foi expulso da tribo.",al={"tribo de krolg","krolg é foulweald"}},{q="Krolg é hostil aos jogadores?",a="Krolg ataca forasteiros que se aproximam dele sem usar a transformação de furbolg. Os aventureiros precisam usar o Bastão de Transformação de Dartol antes de se aproximarem dele.",al={"krolg ataca","krolg é um inimigo"}},{q="Por que Krolg quer Ran Bloodtooth morto?",a="Krolg vê Ran Bloodtooth como sedento por poder e fortalecido pela corrupção. Embora Krolg culpe os elfos noturnos pelo sofrimento de seus parentes, ele não deixará Ran ameaçar seus filhos ou as outras criaturas da floresta.",al={"krolg ran bloodtooth","por que matar ran bloodtooth"}},{q="Quem foi Dartol, cujo bastão permite que os aventureiros falem com Krolg?",a="Dartol era um mago maligno, agora morto, que criou o encantado Bastão de Transformação, o qual permite que seu portador assuma a forma de furbolg. Durante Raene's Cleansing, os aventureiros recuperam as peças perdidas do bastão e o reconstroem para poderem se aproximar de Krolg.",al={"quem é dartol","história do bastão de dartol"}}},fx={["4c25d8d9"]={q="Quem é Krolg?",a="Krolg é um furbolg não corrompido que vive em exílio voluntário ao sul do Lago Mistral, no Vale Gris. Antigamente um membro da tribo Foulweald, ele conseguiu resistir à corrupção sombria que tomou seus irmãos. Agora isolado em sua cabana humilde, ele preserva sua sanidade e sabedoria enquanto lamenta o que seu povo se tornou, disposto a ajudar estranhos que se aproximam dele disfarçados na forma de furbolg.",al={"quem é krolg","identidade de krolg","quem é o furbolg na cabana de krolg"}},["19bbdb38"]={q="De que lado está Krolg?",a="Krolg não jurou lealdade à Aliança ou à Horda; ele permanece sozinho como um dos poucos furbolgs sãos e não corrompidos que restam na região. No entanto, ele só tratará com aventureiros da Aliança que se aproximarem dele disfarçados como um companheiro furbolg usando a Vara de Dartol, oferecendo-lhes orientação e conhecimento ritual em sua luta contra os Foulweald corrompidos.",al={"krolg é da aliança ou horda","facção de krolg","de que lado está krolg"}},["39fdb4f1"]={q="O que Krolg quer?",a="Krolg busca um fim para a loucura que está destruindo seus antigos parentes. Ele pede aos aventureiros transformados que matem Ran Bloodtooth e seus guardas, porque a corrupção deles ameaça os elfos noturnos e as outras criaturas da floresta.",al={"o que krolg quer","motivos de krolg","objetivo de krolg"}},["640007b0"]={q="Por que Krolg está aqui?",a="Krolg foi expulso de sua tribo e se estabeleceu ao sul do Lago Mistral, sendo um dos poucos ursolins intocados pela corrupção que deformou o Foulweald. Viver em isolamento o mantém a salvo de seus antigos irmãos enlouquecidos enquanto ele vigia atentamente o território deles.",al={"por que krolg está aqui","por que krolg deixou o foulweald","por que krolg vive perto do lago mistral"}}},fp="5,258,15.439.0,15.374.1,27.256.0,25.113.0,32.180.0,28.158.0,40.214.1,60.241.0"}
P.entries["npc:krom-stoutarm"] = {n="Krom Braçoforte",s="Krom Braçoforte é um estudioso anão e bruxo encontrado nas profundezas da Library do Hall of Explorers em Altaforja. Ao contrário da maioria de seus parentes, que se dedicam exclusivamente a pedras antigas e relíquias titânicas, Krom estuda textos arcanos mais sombrios e rituais demoníacos. Ele atua como um contato indispensável para bruxos da Aliança em busca de conhecimento esotérico por Kalimdor e pelos Reinos do Leste.",h="Krom Braçoforte é um estudioso anão e bruxo encontrado nas profundezas da Library do Hall of Explorers em...",kw={"hall of explorers","altaforja","krom braçoforte","library","braçoforte","tome of the cabal","bruxo"},ang={["class:Warlock"]="Bruxos da Aliança devem consultar Krom durante sua busca por vínculos sombrios, notadamente na perigosa tarefa de montar o Tome of the Cabal.",["faction:Alliance"]="Krom oferece aos praticantes secretos da Aliança um refúgio intelectual seguro dentro dos imponentes baluartes montanhosos de Altaforja.",["race:Dwarf"]="Os anões geralmente repudiam as artes vis, tornando a posição de Krom entre as reverenciadas estantes do Hall of Explorers uma curiosa raridade."},sec={{t="Um Canto Mais Sombrio do Salão",b="O Hall of Explorers é tipicamente conhecido por arqueólogos anões obcecados por picaretas, pás e artefatos titânicos. Krom Braçoforte destoa deles de forma incomum. Espreitando na Library cercado por tomos gigantescos, ele busca saberes ocultos e os ritos de aprisionamento de invocadores demoníacos. Sua presença em Altaforja demonstra que, embora as artes dos bruxos sejam amplamente vistas com desconfiança, estudiosos-praticantes que estudam as artes proibidas ainda atuam nos salões da cidade montanhosa."},{t="O Tome of the Cabal",b="Quando bruxos da Aliança buscam aprisionar servos demoníacos poderosos como o caçador vil, sua jornada inevitavelmente cruza o caminho de Krom. De posse de conhecimento sobre volumes ocultos dispersos, ele direciona aspirantes a invocadores para muito além dos mares — incluindo perigosas incursões entre os centauros de Mil Agulhas — para recuperar páginas rasgadas e fragmentos do infame Tome of the Cabal."}},faq={{q="Onde posso encontrar Krom Braçoforte?",a="Krom Braçoforte localiza-se dentro da ala da Library do Hall of Explorers, na capital dos anões, Altaforja.",al={"localização de krom braçoforte","onde fica krom braçoforte","krom braçoforte altaforja"}},{q="Qual é o papel de Krom Braçoforte para os jogadores?",a="Krom atua como um contato crucial de missões para bruxos da Aliança que buscam seus rituais demoníacos definidores de classe, orientando-os principalmente na recuperação do Tome of the Cabal.",al={"o que krom faz","propósito de krom braçoforte","missões de krom braçoforte"}},{q="Krom Braçoforte é parente de outros Braçofortes?",a="Vários anões compartilham o sobrenome Braçoforte, mas um parentesco familiar entre Krom e os outros não foi confirmado.",al={"parentes de krom","sten braçoforte parente"}},{q="Por que um bruxo tem permissão para entrar no Hall of Explorers?",a="Krom é um anão de Altaforja que já trabalhou como escavador na escavação de Uldaman. Hoje em dia, ele é um bruxo itinerante que passa o tempo acumulando textos antigos na biblioteca, e não se tem notícia de que alguém o tenha expulsado.",al={"por que krom está no hall of explorers","bruxo permitido em altaforja"}},{q="Por que Krom tem ligação com os Sertões?",a="A busca de Krom pelo Tome of the Cabal termina nos Sertões. Assim que os bruxos recuperam suas metades rasgadas dos centauros de Mil Agulhas e de uma carga perdida na costa a oeste de Costa Sul, ele envia o Tomo Reformado para Strahad Farsan em Vila Catraca.",al={"krom braçoforte sertões","por que missão nos sertões krom"}},{q="Krom Braçoforte treina feitiços?",a="Krom é um distribuidor de missões acadêmico, e não um treinador de classe comum. Ele orienta bruxos em ritos de passagem específicos em vez de ensinar grimórios cotidianos.",al={"krom pode me treinar","krom treinador de bruxos"}}},fx={["6ca19015"]={q="Quem é Krom Braçoforte?",a="Krom Braçoforte é um bruxo anão que estuda conhecimento sombrio dentro da Library do Hall of Explorers em Altaforja. Ao contrário de muitos praticantes das artes vis que se escondem em porões sombreados e covens isolados, Krom opera abertamente entre os estudiosos e escavadores da Liga dos Exploradores, aprofundando-se em relíquias antigas, arcanos obscuros e tomos ocultos.",al={"quem é krom","história de krom braçoforte","quem é krom braçoforte"}},["23fb54c2"]={q="De que lado está Krom Braçoforte?",a="Krom Braçoforte é leal a Altaforja e à Aliança. Embora pratique artes de bruxo que atraem suspeita e inquietação de muitos de seus parentes, ele permanece um estudioso respeitado dentro do Hall of Explorers, oferecendo sua experiência esotérica e conhecimento arcano apenas para ajudar os campeões da Aliança em seus empreendimentos.",al={"facção de krom braçoforte","krom braçoforte é aliança ou horda","a quem krom serve"}}},fp="13,374,27.471.0,21.369.0,31.110.0,46.181.0,44.113.0,56.225.0,37.249.0,32.162.0"}
P.entries["npc:krusk"] = {n="Krusk",s="Krusk é um batedor orc posicionado na Serraria Tarren, no Contraforte de Eira dos Montes. Enviado diretamente sob as ordens do Chefe do Caos Thrall para investigar a Camarilha e recuperar relíquias das ruínas do Forte do Desterro, ele agora coordena esforços de reconhecimento e resgate após sua infiltração inicial ser emboscada.",h="Krusk é um batedor orc posicionado na Serraria Tarren, no Contraforte de Eira dos Montes.",kw={"drull","forte do desterro","gol'dir","eira dos montes","krusk","camarilha","serraria tarren","thrall","tog'thar"},ang={["faction:Horde"]="Krusk representa os interesses diretos do Chefe do Caos Thrall em Lordaeron, concentrando-se em proteger a história do Forte do Desterro e garantir que nenhum orc capturado seja deixado nas mãos da Camarilha.",["race:Orc"]="Ajudar Krusk a resgatar seus companheiros batedores evoca a honra e a história dolorosa dos campos de concentração orcs, especificamente da fortaleza onde Thrall quebrou as correntes de seu povo."},sec={{t="Uma missão que deu errado",b="Quando o Chefe do Caos Thrall voltou sua atenção para as ruínas do Forte do Desterro, enviou Krusk e uma pequena equipe de ataque para espionar a atividade da Camarilha e recuperar relíquias ligadas ao passado sombrio da fortaleza. No entanto, os bandidos humanos se mostraram mais entrincheirados e coordenados do que o previsto. Uma emboscada dentro das muralhas em ruínas do Forte do Desterro subjugou o esquadrão de batedores orcs. Krusk conseguiu lutar para escapar, mas seus companheiros foram feitos prisioneiros: Drull e Tog'thar foram trancafiados nas ruínas, enquanto o líder da expedição, Gol'dir, foi transferido para outro reduto da Camarilha. Reagrupando-se na Serraria Tarren, Krusk agora instrui aventureiros da Horda a invadirem o Forte do Desterro, recuperarem os itens perdidos e libertarem seus companheiros aprisionados."},{t="De olho na Camarilha",b="Além de resgatar seus batedores, Krusk permanece focado em desmantelar o domínio da Camarilha sobre Eira dos Montes. Os nobres caídos de Alterac representam uma ameaça volátil, operando a partir do Forte do Desterro e conspirando tanto contra os postos avançados da Horda quanto contra seus antigos irmãos da Aliança. Trabalhando a partir da Serraria Tarren, Krusk rastreia os movimentos de líderes da Camarilha, como o Lorde Aliden Perenolde, esperando romper sua liderança antes que possam ameaçar a tênue presença da Horda em Lordaeron."}},faq={{q="Quem é Krusk?",a="Krusk é um batedor orc enviado à Serraria Tarren pelo Chefe do Caos Thrall. Ele foi encarregado de investigar as operações da Camarilha nos arredores das ruínas do Forte do Desterro e recuperar relíquias históricas.",al={"krusk","quem é krusk","krusk serraria tarren"}},{q="O que aconteceu com o esquadrão de Krusk?",a="Krusk e sua equipe foram emboscados pela Camarilha dentro do Forte do Desterro. Enquanto Krusk escapou, Drull e Tog'thar foram aprisionados dentro da fortaleza em ruínas, e o líder da expedição, Gol'dir, foi levado para outro reduto da Camarilha.",al={"esquadrão de krusk","o que aconteceu com krusk","emboscada do forte do desterro"}},{q="Por que a Horda tem interesse no Forte do Desterro?",a="O Forte do Desterro possui um profundo significado pessoal e histórico para o Chefe do Caos Thrall, que foi criado lá como um gladiador cativo por Aedelas Blackmoore antes de liderar a rebelião orca que arrasou o forte.",al={"por que forte do desterro","thrall forte do desterro","relíquias do forte do desterro"}},{q="Onde posso encontrar Krusk?",a="Krusk fica ao ar livre no assentamento da Horda da Serraria Tarren, no norte do Contraforte de Eira dos Montes.",al={"localização de krusk","onde fica krusk"}}},fx={["86db3c10"]={q="De que lado está Krusk?",a="Krusk é um agente leal da Horda. Despachado diretamente sob ordens do Chefe Guerreiro Thrall, ele opera a partir da Serraria Tarren para servir aos interesses estratégicos de Orgrimmar por todo o Contraforte de Eira dos Montes.",al={"facção de krusk","krusk é horda","a quem krusk serve"}},["943a1bb4"]={q="O que Krusk quer?",a="Krusk precisa de campeões capazes para resgatar seus companheiros capturados — Gol'dir, Drull e Tog'thar — da Camarilha dentro das ruínas do Forte do Desterro. Ele também busca descobrir as operações da Camarilha e garantir um item de grande importância ligado à história do Forte do Desterro.",al={"o que krusk precisa","objetivos de krusk","o que krusk está procurando"}},["2e7680ba"]={q="Por que Krusk está aqui na Serraria Tarren?",a="O Chefe Guerreiro Thrall enviou pessoalmente Krusk e seu esquadrão para Hillsbrad para investigar as atividades da Camarilha ao redor do Forte do Desterro. Após uma emboscada que deixou seus batedores presos, Krusk recuou para a Serraria Tarren para se reagrupar e recrutar ajuda para terminar a missão.",al={"por que krusk está em hillsbrad","por que krusk está na serraria tarren","por que thrall enviou krusk"}},fe85a88a={q="A quem Krusk está ligado?",a="Krusk responde ao Chefe de Guerra Thrall, que o enviou a Eira dos Montes com uma expedição liderada por Gol'dir, ao lado dos colegas orcs Drull e Tog'thar. De Serraria Tarren, ele coordena seus esforços junto à guarnição local da Horda.",al={"companheiros de krusk","aliados de krusk","com quem krusk trabalha"}}},fp="5,305,20.716.0,21.475.0,13.182.0,31.231.0,46.200.0,23.99.0"}
P.entries["npc:kuray-bin"] = {n="Koray'bin",s="Koray'bin é um batedor troll da selva Lançanegra posicionado em um posto de guarda do lado de fora do Posto Machadada, no Vale Gris. Ele vigia as trilhas florestais ao redor em busca de batedores elfos noturnos que se esgueiram perto do acampamento da Horda.",h="Koray'bin é um batedor troll da selva Lançanegra posicionado em um posto de guarda do lado de fora do Posto...",kw={"ashenvale outrunners","lançanegra","koray'bin","koraybin","sentinelas da asa de prata","posto machadada"},ang={["faction:Horde"]="Koray'bin representa a vigilância na linha de frente necessária para evitar que o Posto Machadada seja cercado e tomado por guerrilheiros elfos noturnos.",["race:Troll"]="Como muitos batedores Lançanegra a serviço da Horda, Koray'bin usa seus instintos de rastreamento na selva para detectar infiltradores elfos noturnos onde outros veem apenas árvores."},sec={{t="Olhos na Borda da Floresta",b="Posicionado logo nos arredores do Posto Machadada, Koray'bin vigia contra infiltrações da Aliança nas profundezas das matas do Vale Gris. As Sentinelas da Asa de Prata patrulham constantemente as copas circundantes, enviando batedores ágeis pela fronteira para coletar informações sobre as operações madeireiras e defesas da Horda. Sabendo que batedores sem monitoramento rapidamente se transformam em forças de emboscada, Koray'bin orienta combatentes capazes da Horda a abaterem os batedores antes que possam relatar ao Posto Avançado Asa de Prata."}},faq={{q="Quem é Koray'bin?",a="Koray'bin é um vigia troll Lançanegra posicionado nos arredores do Posto Machadada, no Vale Gris. Ele incumbe aventureiros da Horda de abater batedores elfos noturnos hostis à espreita nas matas ao redor.",al={"koraybin","quem e koraybin","batedor troll de machadada"}},{q="Onde posso encontrar Koray'bin?",a="Ele está localizado logo do lado de fora dos portões da paliçada do Posto Machadada, guardando os acessos à estrada no centro-leste do Vale Gris.",al={"localizacao de koraybin","onde fica koraybin"}},{q="Por que Koray'bin quer os Ashenvale Outrunners mortos?",a="Os batedores são Sentinelas da Asa de Prata infiltrando-se perto do Posto Machadada. Koray'bin quer que eles sejam eliminados antes de reunirem informações táticas sobre as posições da Horda ou coordenarem ataques-surpresa.",al={"por que matar os outrunners","historia da missao ashenvale outrunners"}},{q="Koray'bin oferece outras tarefas?",a="Não. Seu único dever no perímetro do posto avançado é supervisionar o contrabatedorismo contra os esquivos batedores elfos noturnos.",al={"missoes de koraybin","tarefa de koraybin"}}},fx={["65134a3b"]={q="De que lado está Koray'bin?",a="Koray'bin serve à Horda. Estacionado logo fora do Posto Machadada, ele trabalha para proteger o assentamento contra incursões da Aliança e mantém vigilância sobre as fronteiras disputadas do Vale Gris.",al={"facção de koray'bin","a quem koray'bin serve","koray'bin é horda"}},bfddbb0e={q="Por que Koray'bin está estacionado aqui no Vale Gris?",a="Koray'bin fica de guarda em um posto avançado logo fora do Posto Machadada para monitorar movimentos hostis. Com batedores elfos noturnos invadindo profundamente o território da Horda, seu dever é detectar ameaças antes que atinjam o assentamento.",al={"por que koray'bin está aqui","propósito de koray'bin no vale gris","por que koray'bin está no posto machadada"}},["189aca6f"]={q="Com quem Koray'bin está ligado?",a="Koray'bin está ligado diretamente à guarnição da Horda no Posto Machadada. Como um sentinela troll da selva, ele trabalha em coordenação com os orcs e outros defensores que mantêm essa posição tênue no Vale Gris contra os elfos noturnos.",al={"laços de koray'bin","aliados de koray'bin","com quem koray'bin trabalha"}}},fp="9,211,23.485.0,17.191.0,27.126.0,55.211.0,37.117.0"}
P.entries["npc:kzan-thornslash"] = {n="Kzan Cortarrasga",s="Kzan Cortarrasga é um mercador de armas orc situado no Vale das Provações, em Durotar. Ele fornece armas e suprimentos básicos essenciais para novos recrutas que iniciam seu treinamento sob o comando da Horda.",h="Kzan Cortarrasga é um mercador de armas orc situado no Vale das Provações, em Durotar.",kw={"durotar","horda","kzan","orc","cortarrasga","vale das provações","vendedor de armas","armas"},ang={["class:Warrior"]="Para jovens guerreiros que começam com lâminas lascadas, Kzan oferece uma seleção imediata de armas contundentes e cortantes para atender a diferentes disciplinas de combate.",["faction:Horde"]="O suprimento dos exércitos nascentes de Thrall começa na base de tudo, onde mercadores como Kzan garantem que toda mão capaz tenha aço para empunhar em nome da Horda."},sec={{t="Armeiro dos Recrutas",b="Situado dentro do desfiladeiro vermelho e poeirento do Vale das Provações, Kzan Cortarrasga serve como o principal vendedor de armas para jovens orcs e trolls Lançanegra dando seus primeiros passos como guerreiros da Horda. Oferecendo uma variedade de armamentos básicos — desde machados de mão e espadas curtas rústicos até clavas e cajados —, Kzan garante que os aspirantes recém-despertos estejam adequadamente armados para enfrentar a fauna local e os perigos da região."}},faq={{q="Quem é Kzan Cortarrasga?",a="Kzan Cortarrasga é um mercador orc situado no Vale das Provações. Sua função é suprir os novos recrutas da Horda com armas padrão adequadas para seus testes iniciais de combate.",al={"kzan cortarrasga","quem é kzan","vendedor de armas do vale das provações"}},{q="Onde posso encontrar Kzan Cortarrasga?",a="Ele pode ser encontrado dentro de The Den, a caverna no Vale das Provações, no sudoeste de Durotar, onde aventureiros novatos e seus instrutores de treinamento se reúnem.",al={"localização de kzan","onde fica kzan cortarrasga","mapa de kzan cortarrasga"}},{q="Que tipo de equipamento Kzan vende?",a="Kzan fornece armas básicas iniciais, incluindo machados, espadas, adagas, cajados e maças destinados a recrutas que precisam de ferro confiável antes de adquirir equipamentos forjados ou encontrados.",al={"o que kzan vende","itens de kzan","armas de kzan"}}},fx={feb30cb2={q="De que lado está Kzan Cortarrasga?",a="Kzan Cortarrasga está firmemente ao lado da Horda. Operando dentro do Vale das Provações, ele responde à autoridade de Orgrimmar e da nova nação de Thrall, equipando os jovens orcs e trolls que chegam para provar sua força e lealdade em Durotar.",al={"facção de kzan cortarrasga","a quem kzan serve","kzan é horda"}},["1bbcac80"]={q="Por que Kzan Cortarrasga está no Vale das Provações?",a="Kzan fica no Vale das Provações para armar recrutas e guerreiros aspirantes que embarcam em seus testes iniciais. Em um campo de provas árido e severo, infestado de escorpiões, javalis e Vile Familiars, um lutador inexperiente precisa de aço, clavas e lâminas confiáveis para sobreviver aos seus testes.",al={"por que kzan cortarrasga está aqui","função de kzan no vale das provações","o que kzan faz"}},c4565150={q="O que Kzan Cortarrasga quer?",a="Kzan visa fornecer aos recrutas as armas de que precisam enquanto mantém seu comércio em Durotar. Por meio de suas negociações com jovens guerreiros, ele garante que os defensores novatos da Horda estejam adequadamente equipados com armamento básico para defender suas terras recém-colonizadas.",al={"o que kzan quer","motivo de kzan cortarrasga","objetivo de kzan cortarrasga"}}},fp="15,199,23.424.0,23.172.0,33.152.0,38.176.0"}
P.entries["npc:lady-anacondra"] = {n="Lady Sucurina",s="Lady Sucurina é uma das Fanglords que lideram os Druids of the Fang na Caverna Ululante. Outrora uma das druidas elfas noturnas que seguiram Naralex em seu ambicioso esforço para curar os Sertões, ela se perdeu quando a comunhão de seu mestre com o Sonho Esmeralda se transformou em um pesadelo. Sua mente se partiu, distorcendo sua devoção em um ímpeto de remodelar a terra para corresponder àquele sonho distorcido.",h="Lady Sucurina é uma das Fanglords que lideram os Druids of the Fang na Caverna Ululante.",kw={"anacondra","sertões","druids of the fang","fanglord","gema de sucurina","lady sucurina","naralex","caverna ululante"},ang={["class:Druid"]="Anacondra representa uma tragédia de advertência para os druidas cenarianos: uma acólita dedicada cujo zelo em curar a terra a tornou vulnerável ao pesadelo que distorceu sua comunhão em loucura.",["faction:Horde"]="A Horda não pode permitir que Anacondra e os Fanglords ameacem as delicadas linhas de vida dos Sertões, tornando sua remoção fundamental para proteger a Encruzilhada e os oásis próximos.",["race:NightElf"]="Ver uma irmã de linhagem Kaldorei descartar sua herança e forma em busca de um sonho serpentino distorcido é um lembrete sóbrio dos perigos que espreitam no Sonho Esmeralda."},sec={{t="De Discípula a Serpente",b="Antes de adotar seu título serpentino, Lady Sucurina era uma das druidas de Naralex. Quando o druida ancião Naralex planejou canalizar as nascentes subterrâneas dos Sertões por meio do Sonho Esmeralda, ela o seguiu até as cavernas. Sua lealdade, no entanto, foi sua ruína. Conforme a mente de Naralex era tomada por visões sombrias, o pesadelo vazou do reino dos sonhos e contaminou seus discípulos, despedaçando sua sanidade e remodelando seu devaneio em uma obsessão fria e reptiliana."},{t="Uma Fanglord nas Profundezas",b="Agora se autodenominando Lady Sucurina, ela monta guarda nas primeiras câmaras subterrâneas da Caverna Ululante. Como seus companheiros Fanglords, ela abandonou os preceitos tradicionais do Círculo Cenariano em favor dos aspectos cruéis da víbora. Canalizando relâmpagos, magia da natureza e transes de sono, ela impõe o sono distorcido de Naralex e trabalha para espalhar a corrupção do pesadelo pela terra árida acima."}},faq={{q="Quem era Lady Sucurina originalmente?",a="Ela era originalmente uma das druidas elfas noturnas que seguiram Naralex em sua missão para curar os Sertões, antes que o pesadelo dele corrompesse seus discípulos.",al={"nome verdadeiro de anacondra"}},{q="Por que ela se voltou contra o Círculo Cenariano?",a="Quando Naralex tentou se conectar ao Sonho Esmeralda sob os Sertões, seus pensamentos foram tomados por um pesadelo. Esse mesmo pesadelo infectou a mente de seus acólitos, corrompendo-a e levando-a a servir ao sonho distorcido.",al={"por que anacondra é má","como ela se tornou uma druida of the fang"}},{q="Qual é o papel dela na Caverna Ululante?",a="Ela atua como uma das quatro Fanglords que lideram os Druids of the Fang. Ela guarda os trechos superiores das cavernas, garantindo que Naralex permaneça preso em seu sono corrompido enquanto the Fang procuram remodelar a terra para corresponder ao seu sonho distorcido.",al={"o que anacondra faz","propósito de lady sucurina","por que matar anacondra"}},{q="Onde ela pode ser encontrada dentro das cavernas?",a="Lady Sucurina vagueia pela primeira grande rede de cavernas perto da entrada da Caverna Ululante. Ela patrulha entre os raptores e serpentes da caverna, muitas vezes alternando entre alguns pontos de descanso.",al={"localização de anacondra","onde está lady sucurina","spawn de anacondra"}},{q="Que item é tirado dela para o Círculo Cenariano?",a="Ela carrega a Gema de Sucurina. Matá-la e reivindicar a gema é exigido pela druida Nara Wildmane em Penhasco do Trovão para quebrar o domínio dos Fanglords sobre os Sertões.",al={"gema de sucurina","leaders of the fang anacondra","item de missão de anacondra"}},{q="Quais poderes ela empunha em batalha?",a="Ela se vale da magia da natureza, atingindo seus inimigos de longe com raios abrasadores e conjurando sono mágico para incapacitar invasores enquanto seus aliados reptilianos atacam.",al={"habilidades de anacondra","feitiços de anacondra","ataques de anacondra"}}},fx={["6f9b72fe"]={q="A quem Lady Sucurina está ligada?",a="Lady Sucurina está ligada diretamente a Naralex, o poderoso druida a quem serviu como acólita antes que o pesadelo dele perturbasse a mente dela. Ela também está vinculada aos outros Lordes das Presas — como Cobrahn e Serpentis — que governam o culto distorcido dos Druidas da Presa junto com ela.",al={"quem é o mestre da sucurina","conexão sucurina naralex","quem lidera a sucurina"}},["1a1ef870"]={q="De que lado está Lady Sucurina?",a="Lady Sucurina está ao lado dos Druidas da Presa, tendo abandonado sua antiga lealdade ao Círculo Cenariano. Corrompida pelo Pesadelo Esmeralda que envolveu seu mestre Naralex, ela agora se opõe a seus antigos parentes e defende a loucura que se espalha dentro da Caverna Ululante.",al={"facção de sucurina","a quem lady sucurina serve","lealdade de lady sucurina"}},ec4c22d8={q="O que Lady Sucurina quer?",a="Corrompida juntamente com sua sanidade, Lady Sucurina busca remodelar a terra para corresponder ao sonho distorcido dos Druids of the Fang. Ela guarda o pesadelo que se prolifera na Caverna Ululante e trabalha para espalhá-lo ao lado de seus companheiros Fanglords.",al={"o que anacondra está tentando fazer","objetivo de anacondra","motivações de anacondra"}},f4df78aa={q="Por que Lady Sucurina está aqui?",a="Ela foi uma das druidas que seguiram o druida elfo noturno Naralex em sua missão para restaurar os áridos Sertões. Ela foi com ele para a Caverna Ululante para explorar as nascentes subterrâneas, apenas para ficar presa e corrompida quando o sonho dele se transformou em pesadelo.",al={"por que anacondra está na caverna ululante","como anacondra chegou aqui","missão de anacondra nos sertões"}}},fp="14,375,24.489.0,22.419.0,34.149.0,45.232.0,40.246.0,42.196.0,52.169.0,37.176.0"}
P.entries["npc:lady-sarevess"] = {n="Lady Sarevess",s="Lady Sarevess é uma feiticeira naga perversa que habita as ruínas alagadas de Profundezas Negras, onde se dedica a feitiçarias sombrias.",h="Lady Sarevess é uma feiticeira naga perversa que habita as ruínas alagadas de Profundezas Negras, onde se...",kw={"aku'mai","profundezas negras","lady sarevess","naga","pool of ask'ar","sarevess","bruxa do mar","martelo do crepúsculo"},ang={["class:Mage"]="Sarevess demonstra como as práticas mágicas dos altaneiros se degeneraram em feitiçarias caóticas de marés e relâmpagos brutos sob séculos de corrupção oceânica.",["race:NightElf"]="As ruínas habitadas por Lady Sarevess já foram um templo sagrado de Eluna. Ver seus parentes nagas perversos profanarem as águas de Ask'ar é uma lembrança amarga da Cisão."},sec={{t="Uma Gruta nas Profundezas",b="Dentro do Pool of Ask'ar, Lady Sarevess realiza seus rituais em uma gruta alagada do templo em ruínas. Uma conjuradora extremamente perversa, ela se dedica à magia negra enquanto os cultistas do Martelo do Crepúsculo, que também assombram o templo submerso, praticam sua própria adoração mais a fundo na caverna."},{t="Feitiçaria das Marés",b="Assim como uma bruxa do mar dos oceanos profundos, Sarevess comanda correntes elementais e arcos crepitantes de relâmpagos. Cercada por sentinelas nagas leais e elementais da água evocados, ela defende ferozmente seu santuário contra quaisquer invasores que ameacem seu trabalho sombrio."}},faq={{q="Quem é Lady Sarevess?",a="Lady Sarevess é uma conjuradora naga que se estabeleceu no subterrâneo Pool of Ask'ar, dentro de Profundezas Negras. Ela é uma conjuradora extremamente perversa que se dedica à magia negra.",al={"quem é sarevess","história de sarevess","passado de lady sarevess"}},{q="Onde Lady Sarevess pode ser encontrada?",a="Ela faz seu covil no Pool of Ask'ar, uma câmara alagada situada nas primeiras áreas do complexo de templos de Profundezas Negras, ao longo da costa de Vale Gris.",al={"localização de sarevess","onde fica lady sarevess","pool of askar"}},{q="Quais poderes Lady Sarevess comanda?",a="Inspirando-se nas tradições das bruxas do mar nagas, Sarevess empunha uma poderosa magia de água e elemental, em especial rajadas violentas de relâmpagos bifurcados, para abater qualquer um que entre em sua enseada.",al={"magia de sarevess","habilidades de sarevess"}}},fx={["75d3f337"]={q="De que lado está Lady Sarevess?",a="Lady Sarevess serve aos de sua própria espécie naga, em vez da Aliança ou da Horda. Uma conjuradora muito distorcida, ela faz seu covil na alagada Pool of Ask'ar dentro das Profundezas Negras e defende ferozmente sua gruta contra qualquer intruso.",al={"facção lady sarevess","a quem serve sarevess","lealdade de sarevess"}},["67d48548"]={q="O que Lady Sarevess quer?",a="Sarevess busca expandir seu domínio sobre artes mágicas distorcidas, conduzindo rituais sombrios em sua gruta alagada no fundo das Profundezas Negras e abatendo qualquer intruso que perturbe seu trabalho.",al={"o que a sarevess está fazendo","objetivo de lady sarevess","propósito de sarevess"}},["6008d570"]={q="Por que Lady Sarevess está aqui nas Profundezas Negras?",a="Lady Sarevess reivindicou a Pool of Ask'ar, uma gruta alagada no templo em ruínas das Profundezas Negras, como seu covil. Lá, ela se envolve com magia sombria, protegida por sentinelas naga e elementais da água invocados.",al={"por que lady sarevess está nas profundezas negras","por que sarevess profundezas negras","por que sarevess está aqui"}},d8505f38={q="A quem Lady Sarevess está ligada?",a="Sarevess está ligada aos naga que infestam as ruínas alagadas das Profundezas Negras, comandando sentinelas naga leais e elementais da água invocados em sua gruta. Os cultistas do Martelo do Crepúsculo que também assombram o templo submerso buscam sua própria adoração mais profundamente na caverna.",al={"aliados de sarevess","com quem sarevess trabalha","sarevess martelo do crepúsculo"}}},fp="13,134,21.274.0,20.262.0,21.188.0,33.156.0,39.192.0"}
P.entries["npc:laird"] = {n="Laird",s="Laird é um vendedor de peixes elfo noturno encontrado dentro da estalagem litorânea de Auberdine. Trabalhando ao longo da costa envolta em névoa de Costa Negra, ele fornece mercadorias comerciais e receitas culinárias a viajantes e pescadores que enfrentam o litoral acidentado.",h="Laird é um vendedor de peixes elfo noturno encontrado dentro da estalagem litorânea de Auberdine.",kw={"auberdine","costa negra","filé de farnesim","vendedor de peixe","laird","nessa cantonegro"},ang={["profession:Cooking"]="Viajantes culinários que visitam Costa Negra costumam procurar Laird por sua receita sobre como filetar e cozinhar adequadamente os ferozes peixes farnesins nativos das águas de Kalimdor.",["race:NightElf"]="Laird representa os comerciantes elfos noturnos do cotidiano que se estabeleceram ao longo da costa continental para apoiar a crescente rede costeira de Kalimdor."},sec={{t="Um Comerciante do Porto",b="Situado dentro da movimentada estalagem de Auberdine, Laird vende peixes frescos e suprimentos para marinheiros, habitantes locais e aventureiros em viagem. As águas de Costa Negra são notoriamente turbulentas e cheias de perigos em comparação com as margens abrigadas de Teldrassil, mas Laird sabe bem que o risco traz recompensas. Para os pescadores ousados dispostos a lançar suas linhas ao longo das praias enevoadas, a pesca local rende um belo lucro."},{t="Laços Através da Água",b="Laird permanece intimamente conectado às operações de pesca do outro lado do canal em Teldrassil. Ele atua como um contato essencial para serviços de correio entre os galhos da ilha da Vila de Rut'theran e o porto continental, recebendo remessas de sua colega pescadora Nessa Cantonegro e garantindo que as linhas do comércio costeiro permaneçam abertas."}},faq={{q="Onde posso encontrar Laird?",a="Laird fica no interior, no térreo da estalagem em Auberdine, o principal assentamento da Aliança ao longo da costa de Costa Negra.",al={"localização de laird","onde fica laird","laird auberdine"}},{q="O que Laird vende?",a="Ele vende vários peixes pescados e ingredientes de culinária, bem como a instrução culinária para preparar um Filé de Farnesim.",al={"vendedor laird","o que laird vende","mercadorias de laird"}},{q="Quais missões envolvem Laird?",a="Laird é o destinatário de uma entrega originada de Nessa Cantonegro na Vila de Rut'theran na missão Voo para Auberdine, após a qual ele pede aos aventureiros que levem uma mensagem de volta pelo mar.",al={"missões de laird","missão de pesca auberdine"}},{q="Por que Laird acha que pescar em Costa Negra vale a pena apesar do perigo?",a="Laird observa que, embora o litoral enevoado de Costa Negra abrigue muito mais perigos do que as águas tranquilas de Teldrassil, a vida marinha abundante e exótica torna o comércio muito mais lucrativo para os pescadores empreendedores.",al={"diálogo de laird","costa negra é bom para pesca"}}},fx={["47d7af55"]={q="Quem é Laird?",a="Laird é um pescador e vendedor de peixes elfo noturno que ganha a vida na Costa Negra. Baseado dentro da movimentada estalagem em Auberdine, ele negocia com viajantes e pescadores que navegam pelas águas nebulosas ao longo da costa, oferecendo receitas de culinária e peixe fresco para aqueles que passam pelo local.",al={"quem é laird","laird auberdine","identidade de laird"}},f4a4a12e={q="De que lado está Laird?",a="Laird é aliado dos elfos noturnos e da Aliança. Residindo pacificamente em Auberdine, ele dá as boas-vindas aos aventureiros da Aliança e aos pescadores locais para descansarem na estalagem e conferirem suas mercadorias.",al={"facção de laird","laird é da aliança","a quem laird serve"}},["90f5a883"]={q="Por que Laird está aqui?",a="Laird permanece na estalagem de Auberdine para comprar e vender as capturas da costa. Embora o litoral da Costa Negra traga perigos ausentes em Teldrassil, ele reconhece que pescadores ousados podem obter lucros substanciais das águas locais, tornando o porto um local privilegiado para seu comércio.",al={"por que laird está em auberdine","propósito de laird costa negra"}},d47e4f81={q="O que Laird quer?",a="Laird busca um comércio de peixes litorâneo próspero. Ele incentiva empreendimentos pesqueiros locais apesar dos perigos das praias da Costa Negra e fica feliz em fornecer frutos do mar e receitas culinárias para viajantes famintos.",al={"o que laird quer","objetivos de laird","motivos de laird"}}},fp="5,224,17.404.0,21.323.0,23.128.0,21.123.0,26.193.0,72.215.0"}
P.entries["npc:lakota-windsong"] = {n="Lakota Cantéolo",s="Lakota Cantéolo é uma jovem tauren mantida em cativeiro no alto dos penhascos do Pináculo da Nuvem Negra, em Mil Agulhas. Depois de rejeitar uma proposta indesejada de Arnak Grimtotem, ela foi raptada à força e aguarda o resgate das garras da tribo Grimtotem.",h="Lakota Cantéolo é uma jovem tauren mantida em cativeiro no alto dos penhascos do Pináculo da Nuvem Negra, em...",kw={"arnak grimtotem","pináculo da nuvem negra","liberdade, liberdade","aldeia vento livre","lakota cantéolo","thalia couro âmbar","mil agulhas"},ang={["faction:Horde"]="Resgatar Lakota desfere um golpe contra o domínio dos Grimtotem sobre Mil Agulhas e garante passagem segura para os viajantes que descansam na Aldeia Vento Livre.",["race:Tauren"]="A provação de Lakota é um lembrete contundente da traição que fervilha entre os Grimtotem, cujo desafio à liderança de Caerne Casco Sangrento frequentemente se torna violento."},sec={{t="Uma Corte Mortal",b="Pouco depois da Terceira Guerra, Lakota Cantéolo foi cortejada por Arnak Grimtotem. Sem qualquer desejo de se juntar ao clã dele ou aceitar suas investidas, ela recusou a proposta. Arnak não aceitou a negativa; ele retornou sob o manto da noite, assassinou o irmão de Lakota quando este tentou intervir e a levou à força para as alturas escarpadas de Mil Agulhas. Confinada bem acima do leito do desfiladeiro, no Pináculo da Nuvem Negra, ela permanece presa sob forte vigilância enquanto Arnak ainda insiste em tomá-la como noiva."},{t="Descida para a Segurança",b="Cercada pelos traiçoeiros bandidos Grimtotem, Lakota não consegue lutar sozinha para descer os penhascos. Apenas uma escolta corajosa pode guiá-la pelas pontes suspensas e pelos caminhos sinuosos até a bacia do cânion abaixo. Assim que se liberta do Pináculo da Nuvem Negra, Lakota foge em direção à segurança da Aldeia Vento Livre, levando a notícia de seu resgate a Thalia Couro Âmbar e aos defensores ali estacionados."}},faq={{q="Por que Lakota Cantéolo está presa no Pináculo da Nuvem Negra?",a="Ela recusou uma proposta de casamento de Arnak Grimtotem. Em vez de aceitar a recusa, Arnak assassinou o irmão dela e raptou Lakota, arrastando-a para a fortaleza Grimtotem no Pináculo da Nuvem Negra na esperança de forçá-la a aceitar.",al={"por que lakota foi capturada","quem sequestrou lakota","por que lakota esta no pinaculo da nuvem negra"}},{q="Para onde Lakota vai depois de ser resgatada?",a="Após alcançar a base do Pináculo da Nuvem Negra em segurança, Lakota segue para a Aldeia Vento Livre, onde pode encontrar refúgio entre os defensores da Horda e relatar sua provação a Thalia Couro Âmbar.",al={"para onde lakota foge","para onde ela vai apos a escolta","destino de lakota"}},{q="Quem é Arnak Grimtotem?",a="Arnak é um guerreiro violento do traiçoeiro clã Grimtotem que assassinou o irmão de Lakota e a raptou quando ela se recusou a casar com ele.",al={"quem e arnak","quem a sequestrou","historia de arnak"}}},fx={e2861ac8={q="Quem é Lakota Windsong?",a="Lakota Windsong é uma mulher tauren mantida em cativeiro no topo do Pináculo da Nuvem Negra. Quando Arnak Lâmina-Tenebrosa buscou sua mão em casamento, Lakota recusou. Enfurecido pela rejeição, Arnak assassinou o irmão dela e a arrastou para a fortaleza dos Lâmina-Tenebrosa em Mil Agulhas, com a intenção de forçar a união contra a vontade dela.",al={"quem é lakota windsong","quem é lakota","identidade de lakota"}},["412850e2"]={q="De que lado está Lakota Windsong?",a="Lakota está alinhada aos taurens pacíficos da Horda e busca nos bravos da Aldeia Vento Livre por proteção. Ela nutre profunda inimizade contra o clã Lâmina-Tenebrosa, que tirou brutalmente a vida de seu irmão e a abduziu.",al={"facção de lakota windsong","lakota é da horda","lealdade de lakota"}},["2c16a924"]={q="O que Lakota Windsong quer?",a="Lakota deseja apenas escapar do Pináculo da Nuvem Negra e alcançar a segurança, longe dos bandidos Lâmina-Tenebrosa. Com seu irmão morto ao defendê-la, ela depende de alguém corajoso o suficiente para lutar contra seus captores e guiá-la em segurança pelos caminhos sinuosos em direção à Aldeia Vento Livre.",al={"objetivo de lakota windsong","o que lakota precisa","desejos de lakota"}},["3261173c"]={q="A quem Lakota Windsong está ligada?",a="Lakota era ferozmente protegida pelo seu irmão, que perdeu a vida tentando defendê-la de Arnak Lâmina-Tenebrosa. Ela também deposita sua confiança em Thalia Amberhide e nos defensores estacionados na Aldeia Vento Livre.",al={"família de lakota","conexões de lakota","com quem lakota é relacionada"}}},fp="15,245,18.504.0,17.388.1,56.226.0,41.187.1,23.139.0"}
P.entries["npc:lanka-farshot"] = {n="Lanka Tiro Distante",s="Lanka Tiro Distante é um instrutor de caçadores tauren situado na Aldeia Narache, na Chapada Nuvem Vermelha. Ele orienta caçadores taurens novatos enquanto dão seus primeiros passos em rastreamento, pontaria e sobrevivência nas planícies de Mulgore.",h="Lanka Tiro Distante é um instrutor de caçadores tauren situado na Aldeia Narache, na Chapada Nuvem Vermelha.",kw={"aldeia narache","instrutor de caçadores","lanka tiro distante","mulgore","chapada nuvem vermelha","caçador tauren"},ang={["class:Hunter"]="Para caçadores taurens que iniciam seu treinamento em Mulgore, Lanka Tiro Distante é o primeiríssimo mentor que encontram, ensinando pontaria fundamental e sobrevivência selvagem.",["race:Tauren"]="Lanka personifica a filosofia tradicional de caça dos taurens, encarando a pontaria e o rastreamento como deveres vitais para proteger a tribo e viver em equilíbrio com as planícies."},sec={{t="Mentor da Chapada Nuvem Vermelha",b="Vigiando a Aldeia Narache, Lanka Tiro Distante recebe novos taurens chamados para o caminho do caçador. Novos recrutas chegam carregando um Bilhete cinzelado que os orienta a buscar seus conselhos. Sob seu olhar firme, os aprendizes aprendem os fundamentos do combate à distância, o rastreamento de presas e o respeito às feras selvagens que vagam pelas planícies verdejantes de Mulgore. Seus ensinamentos garantem que cada jovem caçador atue como um batedor capaz e provedor para a tribo."}},faq={{q="Quem é Lanka Tiro Distante?",a="Lanka Tiro Distante é o instrutor de caçadores tauren situado na Aldeia Narache, na Chapada Nuvem Vermelha, em Mulgore. Ele fornece treinamento inicial e orientação aos jovens caçadores que iniciam sua jornada.",al={"quem é lanka","npc lanka tiro distante","caçador da aldeia narache"}},{q="Quais missões Lanka Tiro Distante oferece?",a="Lanka recebe jovens caçadores taurens enviados a ele por meio de um Bilhete cinzelado ao chegarem à Aldeia Narache e os encaminha para O caminho do caçador enquanto aprendem o básico de seu ofício.",al={"missões de lanka tiro distante","missões de caçador da aldeia narache"}},{q="Lanka Tiro Distante é parente de Mixie Farshot?",a="Apesar de compartilharem o mesmo sobrenome, não há evidências de que Lanka Tiro Distante seja parente da goblin Mixie Farshot.",al={"lanka é parente de mixie","relação com mixie farshot"}}},fx={["3509322d"]={q="De que lado está Lanka Tiro Distante?",a="Lanka Tiro Distante é leal às tribos tauren e à Horda. Estacionado dentro do refúgio seguro da Aldeia Narache, ele serve seu povo guiando jovens caçadores tauren enquanto eles aprendem a sobreviver e contribuir para as tribos unidas sob o Alto Chefe Caerne Casco Sangrento.",al={"facção de lanka tiro distante","a quem serve lanka tiro distante","lanka é da horda"}},fd40a21a={q="Por que Lanka Tiro Distante está aqui na Aldeia Narache?",a="Lanka reside na Aldeia Narache para instruir caçadores novatos iniciando seus testes na Chapada Nuvem Vermelha. As planícies de Mulgore exigem sentidos aguçados e pontaria firme, e Lanka está pronto para transmitir as artes essenciais de rastreamento e pontaria para a próxima geração.",al={"por que lanka está aqui","propósito da localização de lanka tiro distante","o que traz lanka à aldeia narache"}},["2df75887"]={q="O que Lanka Tiro Distante quer?",a="Lanka busca garantir que todo aspirante a caçador tauren domine os caminhos da natureza selvagem. Ele quer que você respeite sua presa, aprimore sua pontaria e continue as orgulhosas tradições necessárias para alimentar e defender seu povo pelas pastagens.",al={"objetivo de lanka tiro distante","o que lanka está tentando fazer","propósito de lanka tiro distante"}}},fp="13,220,28.441.0,21.186.0,37.182.0,42.113.0"}
P.entries["npc:lar-prowltusk"] = {n="Larri Presador",s="Larri Presador é um sentinela troll Lançanegra posicionado a sudoeste da Aldeia Sen'jin, em Durotar. De seu posto na fronteira, ele vigia as ameaças iminentes ao jovem assentamento troll, orientando aventureiros a conter o avanço dos inimigos próximos.",h="Larri Presador é um sentinela troll Lançanegra posicionado a sudoeste da Aldeia Sen'jin, em Durotar.",kw={"lançanegra","durotar","kolkar","larri presador","vigília do norte","aldeia sen'jin","troll"},ang={["faction:Horde"]="Larri Presador representa a luta da Horda para proteger as fronteiras de Durotar contra ameaças externas bem aos pés de sua capital recém-nascida.",["race:Troll"]="Para os Lançanegra, batedores como Larri Presador são vitais para proteger o novo e frágil lar da tribo em Durotar contra clãs agressivos de centauros e forças humanas invasoras."},sec={{t="Vigia na Costa",b="Situado a sudoeste da Aldeia Sen'jin, ao longo da costa acidentada de Durotar, Larri Presador atua como um dos sentinelas avançados da tribo Lançanegra. Com os trolls ainda lutando para garantir um lar permanente após fugirem de seu arquipélago submerso, a Aldeia Sen'jin enfrenta constantes ataques de vizinhos hostis. Larri coordena batedores e guerreiros para monitorar movimentos costeiros e conter a agressividade de forças inimigas — em especial os centauros Kolkar —, garantindo que o frágil assentamento tenha espaço para prosperar."}},faq={{q="Quem é Larri Presador?",a="Larri Presador é um troll Lançanegra que concede missões, posicionado logo a sudoeste da Aldeia Sen'jin, em Durotar. Ele ajuda a proteger os arredores do assentamento recrutando viajantes capazes da Horda para atacar ameaças regionais antes que alcancem a aldeia propriamente dita.",al={"larri presador","quem é larri presador","larri presador durotar"}},{q="Em quais ameaças Larri Presador foca?",a="Larri foca nos perigos da fronteira que ameaçam o sul de Durotar, principalmente os bandos saqueadores de centauros Kolkar que avançam sobre o território troll.",al={"missões de larri presador","o que larri presador quer"}},{q="Onde Larri Presador pode ser encontrado?",a="Ele está localizado no sul de Durotar, vigiando as trilhas a sudoeste da Aldeia Sen'jin.",al={"localização de larri presador","onde fica larri presador"}}},fx={["7aeb1fbe"]={q="De que lado está Larri Presador?",a="Larri Presador é leal à tribo Lançanegra e à Horda. Estacionado ao longo da costa inóspita de Durotar, a sudoeste da Aldeia Sen'jin, ele atua na defesa do novo lar de seu povo, atento a inimigos que invadem e ameaçam a segurança dos trolls Lançanegra e de seus aliados orcs.",al={"facção de larri presador","a quem serve larri presador","larri presador horda ou aliança"}},ffd46d6a={q="Por que Larri Presador está aqui?",a="Você encontra Larri Presador mantendo vigília a sudoeste da Aldeia Sen'jin para guardar o assentamento Lançanegra de perigos regionais. As extensões meridionais de Durotar enfrentam pressão constante de vizinhos agressivos, e Larri permanece postado perto da costa selvagem para ajudar a direcionar os defensores contra essas ameaças locais antes que elas ataquem a aldeia.",al={"por que larri presador está em durotar","motivo da localização de larri presador","por que larri está a sudoeste de senjin"}},["9e56c7c1"]={q="A quem Larri Presador está ligado?",a="Larri Presador está estreitamente ligado ao assentamento troll da Aldeia Sen'jin, coordenando-se com os defensores da aldeia e aventureiros errantes da Horda para proteger o território troll.",al={"aliados de larri presador","relações de larri presador","parceiro de larri presador"}}},fp="13,259,20.505.0,21.249.0,41.136.0,33.94.0"}
P.entries["npc:laris-geardawdle"] = {n="Laris Vagarroda",s="Laris Vagarroda é um excêntrico pesquisador gnomo estabelecido na Library do Hall of Explorers em Altaforja. Ele dedica sua vida acadêmica ao estudo da natureza bizarra e das origens dos lodos por toda Azeroth. Aventureiros dispostos a coletar amostras de gosma nociva encontram nele um patrono entusiasmado, ainda que um pouco desequilibrado.",h="Laris Vagarroda é um excêntrico pesquisador gnomo estabelecido na Library do Hall of Explorers em Altaforja.",kw={"gnomo","hall of explorers","altaforja","laris vagarroda","library","lodo","gosma"},ang={["faction:Alliance"]="Posicionado dentro do Hall of Explorers, Laris trabalha sob o amplo escopo da erudição patrocinada pela Aliança, acrescentando ciência natural excêntrica às escavações históricas da Liga.",["race:Gnome"]="Laris exemplifica a quintessência do ímpeto gnômico de buscar conhecimento em lugares que todos os outros ignoram, mesmo que isso envolva mergulhar as mãos na lama fétida do pântano."},sec={{t="Erudito da Gosma",b="Escondido entre as estantes imponentes e as relíquias antigas do Hall of Explorers, Laris Vagarroda se dedica a um nicho nada glamouroso da filosofia natural: a gênese dos lodos. Enquanto seus colegas anões se debruçam sobre tabuletas titânicas e antigas esculturas de pedra, Laris está convencido de que os horrores vis e gelatinosos de Azeroth guardam segredos alquímicos e biológicos fascinantes. Ele incumbe exploradores itinerantes de recolher amostras cáusticas de cantos remotos do mundo, ansioso para testar suas estranhas hipóteses sobre como essas poças irracionais de malícia ganham vida."}},faq={{q="Quem é Laris Vagarroda?",a="Laris Vagarroda é um pesquisador gnomo que reside na Library do Hall of Explorers em Altaforja. Ele concentra seus estudos não convencionais em lodos, gosmas e na mecânica bizarra por trás de sua geração espontânea.",al={"laris","vagarroda","quem é laris"}},{q="Onde posso encontrar Laris Vagarroda?",a="Ele pode ser encontrado na ala norte de Altaforja, dentro do Hall of Explorers, especificamente instalado nos confins tranquilos da Library.",al={"localização de laris","onde fica laris","encontrar laris vagarroda"}},{q="Por que ele está estudando lodos?",a="Laris possui uma mente científica aguçada e excêntrica e desenvolveu teorias distintas a respeito da natureza e da criação de gosma viva. Ele acredita que analisar resíduos cáusticos de diferentes lodos abrirá caminho para uma compreensão mais profunda de como esses organismos bizarros se formam e se replicam.",al={"por que lodos","pesquisa de gosma de laris","estudo de lodos"}},{q="Quais tarefas ele oferece aos aventureiros?",a="Laris recruta viajantes audaciosos para se aventurarem em terras traiçoeiras a fim de coletar amostras puras de lodo. Por meio de sua tarefa, 'A Little Slime Goes a Long Way', ele fornece recipientes vazios para lodo e pede aos aventureiros que recolham amostras dos lodos que abatem em Selva Maleva, enviando-os depois em busca de amostras puras e não corrompidas.",al={"missões de laris","a little slime goes a long way"}}},fx={a960bc4a={q="De que lado está Laris Vagarroda?",a="Laris Vagarroda está firmemente ao lado da Aliança e dos Exilados de Gnomeregan. Operando a partir do Hall of Explorers em Altaforja ao lado de estudiosos e pesquisadores anões, ele contribui com sua mente aguçada e teorias biológicas excêntricas para o avanço do conhecimento e da compreensão da Aliança sobre fenômenos estranhos em todo o mundo.",al={"facção de laris vagarroda","laris vagarroda aliança","laris vagarroda é amigável"}},["114e8ed2"]={q="Por que Laris Vagarroda está em Altaforja?",a="Após a queda de Gnomeregan, muitos gnomos buscaram refúgio entre seus aliados anões em Altaforja. Laris Vagarroda fez sua morada na Library dentro do Hall of Explorers, um santuário ideal onde ele pode prosseguir com sua pesquisa acadêmica excêntrica e catalogar suas teorias sobre a origem das gosmas, com acesso total a extensos arquivos históricos e naturais.",al={"por que laris vagarroda está aqui","laris vagarroda hall of explorers","por que laris está em altaforja"}}},fp="16,316,16.558.0,24.220.0,34.139.0,25.279.0,37.309.0"}
P.entries["npc:lars"] = {n="Lars",s="Lars é um sobrevivente humano acuado acampando na vastidão da Floresta do Crepúsculo. Junto com seu companheiro Noel Figueira, ele luta para manter sua posição na borda norte da Margem Silenciada contra os terrores que espreitam a floresta.",h="Lars é um sobrevivente humano acuado acampando na vastidão da Floresta do Crepúsculo.",kw={"acampamento","floresta do crepúsculo","margem silenciada","lars","noel figueira","lobos","lobos nos nossos calcanhares"},ang={["faction:Alliance"]="Lars é um civil humano acuado sobrevivendo fora do alcance da guarda da cidade, contente em encontrar campeões da Aliança dispostos a abater os lobos que cercam seu acampamento."},sec={{t="Um Refúgio Precário",b="Abrigado em um acampamento modesto na borda norte da Margem Silenciada, Lars leva uma sobrevivência precária longe da segurança questionável de Vila Sombria. A Floresta do Crepúsculo já é traiçoeira nos melhores momentos, mas os bosques ao redor rastejam com feras ferozes, mortos-vivos implacáveis e worgens à espreita. Lars permanece perto de Noel Figueira, esforçando-se simplesmente para se manter vivo em uma natureza cada vez mais hostil."},{t="Ameaça dos Ermos",b="A sobrevivência no acampamento exige vigilância constante contra os predadores locais. Lars se vê duramente pressionado pelas alcateias implacáveis de lobos terríveis famintos que assombram as sombras ao redor de sua fogueira. Incapaz de baixar a guarda ou repeli-los sozinho, ele conta com viajantes capazes para diminuir os predadores famintos antes que seu pequeno acampamento seja completamente invadido."}},faq={{q="Quem é Lars?",a="Lars é um sobrevivente humano acampando nos ermos da Floresta do Crepúsculo. Ele vive ao lado de seu amigo e companheiro Noel Figueira na fronteira norte da Margem Silenciada, fazendo o que pode para sobreviver aos horrores da floresta.",al={"lars floresta do crepúsculo","quem é lars","npc lars"}},{q="Onde Lars pode ser encontrado?",a="Lars está situado em um pequeno acampamento selvagem ao longo da borda norte da Margem Silenciada, localizada no oeste da Floresta do Crepúsculo.",al={"onde fica lars","localização de lars","acampamento de lars"}},{q="Qual problema Lars enfrenta?",a="Lars e Noel são constantemente importunados por lobos famintos e predadores à espreita nos bosques próximos. Por meio da missão 'Lobos nos nossos calcanhares', Lars pede a aventureiros de passagem que cacem os predadores antes que eles destruam seu acampamento.",al={"missão de lars","missão lobos nos nossos calcanhares","por que lars precisa de ajuda"}},{q="Qual é a relação de Lars com Noel Figueira?",a="Lars e Noel Figueira são companheiros sobrevivendo juntos na natureza selvagem. Noel tem sua própria história sombria e vingança na região, enquanto Lars ajuda a manter o posto avançado rústico e isolado deles.",al={"lars e noel","quem é noel para lars"}}},fx={["05f5e77d"]={q="De que lado Lars está?",a="Lars é um sobrevivente humano independente aliado à Aliança. Em vez de servir à The Night Watch ou diretamente ao exército de Ventobravo, ele é apenas um homem comum tentando suportar os perigos da Floresta do Crepúsculo ao lado de seu companheiro, Noel Figueira.",al={"facção de lars","lars é da aliança","a quem lars serve"}},["2eb2df94"]={q="Por que Lars está acampado na Floresta do Crepúsculo?",a="Lars refugiou-se em um acampamento rústico ao longo da margem norte da Margem Silenciada. Ele permanece lá tentando sobreviver à floresta sombria dia após dia na companhia de Noel Figueira, resistindo contra os predadores e horrores invasores da floresta.",al={"por que lars está aqui","motivo de lars na floresta do crepúsculo","por que lars veio para cá"}}},fp="4,232,18.391.0,21.358.0,12.212.0,24.118.0,28.233.0,43.188.0"}
P.entries["npc:laurna-morninglight"] = {n="Laurna Luzalbor",s="Laurna Luzalbor é uma instrutora de sacerdotes elfa noturna que reside no tranquilo assentamento de Dolanaar, em Teldrassil. Devota da Irmandade de Elune, ela orienta os novos acólitos recém-saídos de Umbravale nos ritos espirituais e nas graças curativas da Deusa da Lua. Seus ensinamentos preparam os jovens sacerdotes elfos noturnos para as crescentes ameaças que avançam sobre os galhos da Árvore do Mundo.",h="Laurna Luzalbor é uma instrutora de sacerdotes elfa noturna que reside no tranquilo assentamento de Dolanaar...",kw={"dolanaar","elune","kaldorei","laurna","luzalbor","instrutor de sacerdotes","irmandade de elune","teldrassil"},ang={["class:Priest"]="Para os sacerdotes elfos noturnos que chegam de Umbravale, Laurna Luzalbor é sua primeira grande mentora fora do vale inicial, ensinando feitiços fundamentais e guiando sua devoção inicial a Elune.",["race:NightElf"]="Laurna personifica a devoção tradicional kaldorei à Deusa da Lua, lembrando aos aventureiros que o sacerdócio em Teldrassil provém de Elune, e não da Luz Sagrada."},sec={{t="Uma Guia em Dolanaar",b="Situada entre as ramificações de Dolanaar, Laurna Luzalbor atua como uma das principais mentoras para jovens sacerdotes que concluíram seus ritos iniciais em Umbravale. Conforme novos iniciados avançam pelas regiões mais amplas de Teldrassil, ela os instrui a expandir sua comunhão com Elune, equilibrando a luz da cura com ritos defensivos necessários para sobreviver a uma natureza cada vez mais hostil."},{t="Devoção à Deusa da Lua",b="O sacerdócio entre os kaldorei está profundamente entrelaçado com a adoração a Elune, em vez da abstrata Luz Sagrada venerada por humanos e anões. Laurna encarrega seus alunos de tarefas espirituais, como receber vestes sagradas e curar uma Sentinela ferida. Por meio dessas tradições, os acólitos aprendem que seus poderes são dádivas diretas da Mãe Lua, destinadas a preservar e curar o povo kaldorei."}},faq={{q="Onde posso encontrar Laurna Luzalbor?",a="Laurna Luzalbor fica no vilarejo de Dolanaar, localizado nas regiões centrais de Teldrassil, logo adiante na estrada saindo de Umbravale.",al={"localização de laurna","onde fica laurna","instrutor de sacerdotes dolanaar"}},{q="O que Laurna Luzalbor faz?",a="Ela é uma instrutora de sacerdotes para personagens elfos noturnos. Ela ensina novos feitiços, aprimora graus de habilidades conhecidas e oferece orientação inicial por meio de ritos específicos da classe.",al={"o que ela faz","papel de laurna","laurna instrutora de sacerdotes"}},{q="Que tipo de missões ela oferece?",a="Ela inicia missões de classe para sacerdotes novatos, orientando-os a ajudar aliados feridos e a buscar o favor divino de Elune por meio de vestimentas cerimoniais e preces.",al={"missões de laurna","missões de sacerdote dolanaar"}},{q="Ela treina outras raças?",a="Embora seja culturalmente enraizada na Irmandade de Elune, os instrutores de sacerdote da Aliança ensinam qualquer sacerdote aliado que procure disciplina espiritual.",al={"humanos podem treinar aqui","instrutor de sacerdotes qualquer raça"}},{q="Ela é afiliada ao Templo da Lua?",a="Sim, como uma sacerdotisa kaldorei, seus votos e magia são inteiramente dedicados à Deusa Elune e às tradições mais amplas supervisionadas pelo Templo da Lua em Darnassus.",al={"ela é da irmandade de elune","laurna templo da lua"}},{q="Ela compartilha o sobrenome com outros elfos noturnos?",a="Não há parentes conhecidos de Laurna entre os kaldorei de Teldrassil.",al={"família luzalbor","parentes de laurna"}}},fx={["3c87933c"]={q="Quem é Laurna Luzalbor?",a="Laurna Luzalbor é uma sacerdotisa elfa noturna e mentora que reside na vila de Dolanaar. Devota ao culto de Eluna, ela guia jovens acólitos e iniciantes que dão seus primeiros passos em Teldrassil, ensinando-os a canalizar a radiância calmante da deusa e invocar proteção divina.",al={"quem é laurna luzalbor","quem é laurna","história de laurna luzalbor"}},["5c82db11"]={q="De que lado Laurna Luzalbor está?",a="Ela é firmemente leal aos elfos noturnos de Darnassus, à Irmandade de Eluna e à Aliança. Como acólita da deusa da lua, seu coração está em proteger seu povo e guiar o bem-estar espiritual dos Kaldorei em Teldrassil.",al={"facção de laurna luzalbor","a quem laurna luzalbor serve","laurna luzalbor aliança"}},["6a7a4981"]={q="O que Laurna Luzalbor quer?",a="Sua devoção principal é nutrir sacerdotes noviços nos caminhos de Eluna. Ela quer que acólitos promissores cultivem sua conexão divina, dominem orações de cura e empunhem vestes sagradas para ajudar seus parentes por todos os ramos de Teldrassil.",al={"motivação de laurna luzalbor","o que laurna luzalbor faz"}},["65cf8731"]={q="Por que Laurna Luzalbor está aqui em Dolanaar?",a="Dolanaar é a principal encruzilhada e ponto de encontro para jovens aventureiros que deixam os clareiras isoladas de Umbravale. Laurna está posicionada aqui para garantir que os sacerdotes em desenvolvimento recebam orientação, instrução e ritos sagrados adequados conforme assumem deveres maiores em Teldrassil.",al={"por que laurna está em dolanaar","por que laurna luzalbor está aqui"}}},fp="19,383,19.397.0,28.400.0,37.141.0,33.165.0,35.158.0,27.162.0,46.168.0,52.66.0"}
P.entries["npc:lelanai"] = {n="Lelanai",s="Lelanai é uma tratadora de montarias elfo noturno que reside no Enclave Cenariano de Darnassus. Ela fornece as ferozes montarias felinas dos elfos noturnos a cavaleiros dignos, oferecendo tanto noitigres quanto feras de guerra velozes para o seu povo e aliados de confiança de Darnassus.",h="Lelanai é uma tratadora de montarias elfo noturno que reside no Enclave Cenariano de Darnassus.",kw={"enclave cenariano","darnassus","tigre-do-gelo","jartsam","lelanai","vendedor de montaria","noitigre"},ang={["faction:Alliance"]="Heróis da Aliança que alcançam status de exaltado com Darnassus podem procurar Lelanai para cavalgar os icônicos felinos na batalha ao lado de seus aliados kaldorei.",["race:NightElf"]="Para elfos noturnos, visitar Lelanai é um rito de passagem essencial ao adquirir seus tradicionais corcéis felinos."},sec={{t="Criadora do Enclave Cenariano",b="Estacionada ao lado do instrutor de montaria Jartsam, entre as árvores imponentes do Enclave Cenariano, Lelanai cuida de alguns dos melhores grandes felinos criados em Kalimdor. Os elfos noturnos há muito formaram laços profundos com os predadores ferozes das florestas do norte, treinando noitigres e tigres-do-gelo para carregar sentinelas e batedores por terrenos acidentados com graça predatória. Lelanai serve como a principal fornecedora dessas reverenciadas montarias na capital."},{t="Laços Além do Parentesco",b="Embora as montarias felinas sejam oferecidas livremente a qualquer elfo noturno com a habilidade apropriada, os estrangeiros enfrentam um limite muito mais rígido. Dada a natureza sagrada dos felinos e o distanciamento natural dos kaldorei, Lelanai não confiará uma besta a aventureiros que não sejam elfos noturnos, a menos que tenham conquistado o mais alto grau de respeito e renome com a cidade de Darnassus."}},faq={{q="Onde posso encontrar Lelanai?",a="Lelanai está localizada no Enclave Cenariano em Darnassus, de pé bem ao lado do treinador de montaria de tigres, Jartsam.",al={"localização de lelanai","onde fica lelanai","mapa de lelanai"}},{q="O que Lelanai vende?",a="Ela vende rédeas para várias raças de montarias tigres-do-gelo e noitigres, incluindo variações blindadas velozes para cavaleiros veteranos.",al={"mercadorias de lelanai","quais montarias ela tem","montarias de elfo noturno"}},{q="Jogadores que não são elfos noturnos podem comprar montarias de Lelanai?",a="Sim, mas apenas se tiverem provado lealdade excepcional alcançando reputação exaltada com Darnassus. Caso contrário, ela se recusará a vender suas bestas a estrangeiros.",al={"humanos podem comprar felinos","anões podem cavalgar noitigres","reputação necessária para felinos"}},{q="Jogadores da Horda podem interagir com Lelanai?",a="Não. Lelanai é leal à facção de Darnassus da Aliança. Membros da Horda serão tratados como invasores hostis por ela e pelos guardas do enclave próximos.",al={"horda pode comprar felinos","lelanai é amigável com a horda"}}},fx={["8575cac4"]={q="Quem é Lelanai?",a="Lelanai é uma criadora e vendedora de montarias elfa noturna que reside em Darnassus. Posicionada no exuberante Enclave Cenariano, ela cuida dos majestosos sabres criados para os kaldorei e os oferece a campeões de confiança capazes de lidar com esses ferozes predadores felinos.",al={"quem é lelanai","identidade de lelanai","história de lelanai"}},["4b3049f5"]={q="De que lado Lelanai está?",a="Lelanai é leal a Darnassus e à Aliança maior. Ela confia livremente seus sabres treinados aos seus companheiros elfos noturnos, embora só considere oferecê-los a outros membros da Aliança se eles tiverem conquistado o maior renome e confiança entre seu povo.",al={"facção de lelanai","lelanai é da aliança","a quem lelanai serve"}},["18fb2d04"]={q="Por que Lelanai está aqui em Darnassus?",a="Ela faz sua morada no Enclave Cenariano de Darnassus ao lado de Jartsam, o instrutor de montaria. Lá, em meio aos tranquilos ramos de Teldrassil, ela cria e cuida das montarias de sabre-do-gelo e sabre-da-noite, essenciais para as sentinelas e viajantes kaldorei.",al={"por que lelanai está em darnassus","propósito do enclave cenariano de lelanai","por que lelanai está aqui"}},["14c3da8f"]={q="O que Lelanai quer?",a="Lelanai busca garantir que seus estimados sabres-da-noite e montarias de sabre-do-gelo encontrem cavaleiros dignos. Ela insiste que qualquer um que deseje montar uma de suas feras possua treinamento adequado e demonstre verdadeira dedicação e reverência para com Darnassus.",al={"o que lelanai quer","objetivo de lelanai","motivação de lelanai"}},ec77c23e={q="Com quem Lelanai tem ligação?",a="Lelanai trabalha de perto com Jartsam, o instrutor de montaria elfo noturno no Enclave Cenariano. Enquanto Jartsam ensina aos aspirantes a cavaleiros a delicada arte de montar tigres, Lelanai fornece os sabres vinculados prontos para carregá-los por Kalimdor.",al={"laços de lelanai","com quem lelanai trabalha","lelanai jartsam"}}},fp="7,257,31.437.0,20.352.0,25.112.0,23.126.0,44.160.0,40.150.0"}
P.entries["npc:lieutenant-farren-orinelle"] = {n="Tenente Fárrio Orinelle",s="O Tenente Fárrio Orinelle é um oficial do exército de Ventobravo atualmente estacionado na estalagem de Costa Sul, no Contraforte de Eira dos Montes. Profundamente descontente com seu posto na fronteira, ele passa a maior parte do tempo bebendo enquanto terceiriza suas obrigações para viajantes que passam pelo local. Sua principal incumbência militar é lidar com os murlocs invasores ao longo da costa, uma tarefa que ele delega de bom grado na esperança de garantir uma transferência de volta ao sul.",h="O Tenente Fárrio Orinelle é um oficial do exército de Ventobravo atualmente estacionado na estalagem de Costa...",kw={"fárrio","eira dos montes","delegado trilharrubra","murloc","orinelle","reatribuição","costa sul","ventobravo"},ang={["faction:Alliance"]="Para os campeões da Aliança, Orinelle representa as tropas insatisfeitas do sul mantendo um posto avançado solitário no norte, disposto a oferecer moedas e elogios a qualquer um que cumpra seus deveres.",["race:Human"]="Como soldado de Ventobravo preso longe da Floresta de Elwynn, o desdém de Orinelle pelo serviço na fronteira norte destaca a divisão entre a vida confortável da capital e as duras missões no exterior."},sec={{t="Exílio em Costa Sul",b="O Tenente Fárrio Orinelle não escolheu Costa Sul. Enviado para longe de Ventobravo, o tenente considera a costa úmida e disputada de Eira dos Montes um terrível retrocesso em relação aos confortos civilizados da capital. Em vez de patrulhar os campos ou coordenar as defesas com seu comandante, o Delegado Trilharrubra, Orinelle praticamente fixou residência permanente dentro da estalagem de Costa Sul. Seus dias são gastos amargurando, bebendo e sonhando com uma ordem oficial de transferência que o leve de volta ao sul."},{t="Terceirizando o Dever",b="Apesar de seu assento confortável na taberna, Orinelle ainda responde ao Delegado Trilharrubra, que encarregou o tenente de eliminar os murlocs que infestam o litoral próximo. Relutante em sujar as botas na lama costeira, Orinelle conta com aventureiros errantes para abater as criaturas e coletar provas de sua morte. Ele espera que a apresentação de resultados concretos aos seus superiores mostre que seu dever foi cumprido, acelerando seu eventual retorno a Ventobravo."}},faq={{q="Quem é o Tenente Fárrio Orinelle?",a="Ele é um oficial das forças armadas de Ventobravo estacionado em Costa Sul, uma vila no Contraforte de Eira dos Montes. Ele pode ser encontrado bebendo dentro da estalagem de Costa Sul, resmungando sobre o seu posto.",al={"fárrio orinelle","quem é orinelle","tenente de costa sul"}},{q="Por que ele está em Costa Sul?",a="Ele foi transferido para o norte a partir de Ventobravo para reforçar a guarnição local e apoiar o Delegado Trilharrubra. Ele detesta profundamente a missão e anseia por voltar para casa.",al={"por que fárrio está em costa sul","transferência de orinelle"}},{q="Qual é a sua incumbência oficial?",a="O Delegado Trilharrubra ordenou que ele lidasse com os murlocs hostis que infestam o litoral de Eira dos Montes, embora Orinelle prefira pagar mercenários viajantes para lutar em seu lugar.",al={"dever de fárrio","missão de orinelle","murlocs de fárrio"}},{q="Ele chega a sair da estalagem de Costa Sul?",a="Não. Orinelle passa quase todo o tempo junto ao balcão da estalagem, relutante em encarar as praias lamacentas ou os perigos do lado de fora.",al={"onde encontrar fárrio","localização de fárrio","estalagem de orinelle"}},{q="Qual é o objetivo final de Fárrio?",a="Ele quer apenas garantir uma reatribuição oficial de volta a Ventobravo, longe dos perigos e da desolação da costa de Lordaeron.",al={"o que fárrio quer","reatribuição"}},{q="Quem é o comandante de Orinelle?",a="Ele responde ao Delegado Trilharrubra, que comanda o destacamento militar da Aliança responsável por defender Costa Sul.",al={"superior de fárrio","chefe de fárrio","quem comanda fárrio"}}},fx={["7d023078"]={q="De que lado o Tenente Fárrio Orinelle está?",a="O Tenente Fárrio Orinelle serve à Grande Aliança e responde diretamente às forças militares de Ventobravo. Embora deteste sua missão atual no Contraforte de Eira dos Montes, seu posto sob o comando do Delegado Trilharrubra coloca-o diretamente do lado dos defensores de Costa Sul contra os terrores regionais e a agressão da Horda.",al={"facção de orinelle","fárrio orinelle aliança","a quem fárrio serve"}}},fp="26,423,19.515.0,16.458.0,34.183.0,24.167.0,32.172.0,38.136.0,31.143.0,28.98.0"}
P.entries["npc:lieutenant-haggerdin"] = {n="Tenente Haggerdin",s="O Tenente Haggerdin é um oficial anão posicionado em Headland, nas Montanhas de Alterac. De guarda do lado de fora do portão fortificado para o Vale Alterac, ele atua como o principal oficial de recrutamento e ligação da Guarda de Lançatroz. Ele avalia aspirantes a campeões da Aliança e recompensa aqueles que provam seu valor contra o Clã Lobo do Gelo.",h="O Tenente Haggerdin é um oficial anão posicionado em Headland, nas Montanhas de Alterac.",kw={"alterac","anão","lobo do gelo","haggerdin","headland","altaforja","tenente","proving grounds","lançatroz"},ang={["faction:Alliance"]="O Tenente Haggerdin é o seu principal contato fora do Vale Alterac, oferecendo as credenciais e honras oficiais conquistadas ao combater o Clã Lobo do Gelo.",["faction:Horde"]="Um sentinela convicto guardando o portal da Aliança para o Vale Alterac, Haggerdin direciona os reforços enviados para esmagar os orcs do Lobo do Gelo.",["race:Dwarf"]="Um oficial orgulhoso do clã Lançatroz, Haggerdin personifica a determinação resoluta de Altaforja para descobrir sua herança titânica nos penhascos nevados de Alterac."},sec={{t="Guardião do Portão de Headland",b="Empoleirado nas alturas nevadas de Headland, acima de Contraforte de Eira dos Montes, o Tenente Haggerdin supervisiona o ponto de reunião para a campanha contínua da Aliança no Vale Alterac. Estandartes anões tremulam ao lado do enorme portão de madeira enquanto recrutas e veteranos se reúnem sob seu olhar atento, preparando-se para mergulhar na zona de guerra gélida."},{t="Voz da Guarda de Lançatroz",b="A serviço da Expedição Lançatroz, Haggerdin garante que apenas guerreiros testados representem Altaforja e a Grande Aliança no vale. Por meio de desafios como Proving Grounds, ele incumbe recrutas de recuperar estandartes e relíquias, e concede comendas oficiais, insígnias e reconhecimentos de patente à medida que os soldados sobem nas fileiras da Guarda de Lançatroz."}},faq={{q="Quem é o Tenente Haggerdin?",a="O Tenente Haggerdin é um oficial anão que representa a Guarda de Lançatroz. Posicionado na entrada do Vale Alterac em Headland, nas Montanhas de Alterac, ele supervisiona o recrutamento da Aliança e recompensa honrarias de campo de batalha.",al={"haggerdin","quem é haggerdin","tenente haggerdin alterac"}},{q="Onde posso encontrar o Tenente Haggerdin?",a="Ele está localizado no norte das Montanhas de Alterac em Headland, posicionado do lado de fora do portal e dos portões que levam diretamente ao Vale Alterac.",al={"localização de haggerdin","onde fica o tenente haggerdin","entrada da aliança no vale alterac"}},{q="Qual é o papel de Haggerdin na Guarda de Lançatroz?",a="Ele serve como oficial de ligação de campo e intendente, administrando testes de recrutamento como Proving Grounds e recompensando os combatentes da Aliança com patentes mais altas e insígnias à medida que sua reputação com a Guarda de Lançatroz cresce.",al={"o que haggerdin faz","missões de haggerdin","oficial da guarda de lançatroz"}},{q="Por que a Aliança está lutando no Vale Alterac?",a="A Expedição Lançatroz viajou para o vale para escavar relíquias antigas e a história dos anões, mas sua chegada desencadeou um feroz conflito territorial com os orcs residentes do Lobo do Gelo e seus aliados da Horda.",al={"por que vale alterac","objetivo da expedição lançatroz","conflito de alterac"}},{q="Jogadores da Horda podem interagir com o Tenente Haggerdin?",a="Não. O Tenente Haggerdin é um oficial ativo da Aliança e atacará qualquer campeão da Horda que se aventurar perto do portão de Headland.",al={"haggerdin é hostil à horda","horda haggerdin","a horda pode falar com haggerdin"}},{q="O que é o teste de Proving Grounds?",a="O Proving Grounds é uma tarefa introdutória que Haggerdin dá aos futuros soldados da Aliança para verificar sua competência e determinação antes de se comprometerem totalmente com o esforço de guerra do Vale Alterac.",al={"missão proving grounds","proving grounds alterac","haggerdin proving grounds"}}},fx={["1d45d886"]={q="De que lado o Tenente Haggerdin está?",a="O Tenente Haggerdin é totalmente leal à Aliança, servindo especificamente na Guarda de Lançatroz. Operando na borda norte do contraforte perto do Vale Alterac, ele atua como oficial e agente de recrutamento para as forças da Aliança que se reúnem contra os orcs Lobo do Gelo.",al={"facção de haggerdin","haggerdin é da aliança","lealdade de haggerdin"}},["5fb68a23"]={q="O que o Tenente Haggerdin quer?",a="Haggerdin quer campeões capazes da Aliança para reforçar as fileiras da Guarda de Lançatroz no Vale Alterac. Ele testa novos recrutas para garantir que possam sobreviver à natureza selvagem congelante, reconhece veteranos experientes com patentes e insígnias conforme seus feitos crescem, e busca a derrota de ameaças como o campeão troll de Machado de Inverno, Korrak.",al={"o que haggerdin quer","objetivos de haggerdin","propósito de haggerdin"}},["96f37aaa"]={q="Por que o Tenente Haggerdin está aqui no Contraforte de Alterac?",a="O Tenente Haggerdin está estacionado no Promontório com vista para o portão do Vale Alterac para organizar e avaliar as forças da Aliança que chegam. Como o confronto contínuo entre a Expedição Lançatroz e o Clã Lobo do Gelo exige reforço constante, ele monta guarda no campo de preparação para recrutar e honrar aqueles dispostos a lutar na neve.",al={"por que haggerdin está aqui","por que haggerdin está em alterac","posto de haggerdin"}},["9b7a183a"]={q="Com quem o Tenente Haggerdin tem ligação?",a="Haggerdin tem ligação direta com a Guarda de Lançatroz, o braço militar da Expedição Lançatroz de Altaforja, liderada pelo General Vanndar Lançatroz. Ele atua como um oficial conectando os recrutas da Aliança que chegam pelas Montanhas de Alterac ao regimento que luta nas profundezas do Vale Alterac.",al={"laços de haggerdin","haggerdin guarda de lançatroz","a quem haggerdin serve"}}},fp="20,345,26.335.0,28.362.0,28.224.0,38.145.0,53.231.0,47.211.0,53.126.0,34.195.0"}
P.entries["npc:lieutenant-lisande"] = {n="Tenente Lisande",s="A Tenente Lisande é uma emissária da Aurora Argêntea posicionada nos altos platôs do Penhasco do Trovão. Como uma humana que atua abertamente em terras dos taurens, ela serve como uma intermediária contra a ameaça existencial compartilhada do Flagelo.",h="A Tenente Lisande é uma emissária da Aurora Argêntea posicionada nos altos platôs do Penhasco do Trovão.",kw={"aurora argêntea","tenente lisande","lisande","mulgore","flagelo","invasão do flagelo","penhasco do trovão"},ang={["faction:Horde"]="Lisande serve como um lembrete de que a guerra contra o Flagelo exige pragmatismo e cooperação ocasional com ordens humanas neutras.",["race:Tauren"]="Embora Lisande seja uma forasteira, os taurens respeitam a dedicação da Aurora Argêntea em purificar a terra da vil corrupção dos mortos-vivos."},sec={{t="Uma Enviada Improvável",b="Embora rostos humanos sejam raros pelas alturas varridas pelo vento do Penhasco do Trovão, a Aurora Argêntea transcende as inimizades tradicionais entre facções. A Tenente Lisande serve à ordem sagrada vigiando sinais da corrupção do Lich Rei mesmo na remota Kalimdor. Quando forças dos mortos-vivos se agitam nas planícies abaixo, ela reúne bravos campeões da Horda para cavalgar e investigar a ameaça invasora antes que ela possa profanar a terra sagrada."}},faq={{q="Por que há uma humana no Penhasco do Trovão?",a="Lisande representa a Aurora Argêntea, uma organização neutra dedicada unicamente a eliminar o Flagelo. Como a Aurora acolhe tanto raças da Aliança quanto da Horda em suas fileiras, seus intermediários têm entrada diplomática concedida nas capitais para coordenar as defesas contra os mortos-vivos.",al={"humana no penhasco do trovão","por que lisande está aqui","ela é hostil"}},{q="Qual é o interesse da Aurora Argêntea em Mulgore?",a="O alcance do Lich Rei ameaça todos os cantos de Azeroth, não apenas os Reinos do Leste. Lisande monitora qualquer sinal de atividade necromântica ou forças invasoras do Flagelo que ameacem a paz de Mulgore, garantindo que os defensores locais fiquem alertas ao perigo.",al={"flagelo em mulgore","por que penhasco do trovão","mortos-vivos em terras taurens"}},{q="Quais tarefas a Tenente Lisande oferece?",a="Lisande orienta os aventureiros a descerem dos penhascos para investigar incursões do Flagelo avistadas pelo território ao redor, incumbindo-os de relatar o que viram para que a Aurora possa avaliar a escala da ameaça.",al={"missão de lisande","o que lisande faz","missão de investigação"}}},fx={["986453a4"]={q="Quem é a Tenente Lisande?",a="A Tenente Lisande é uma oficial servindo à Aurora Argêntea. Apesar de ser humana no coração do território da Horda, ela permanece abertamente em Penhasco do Trovão para reunir defensores corajosos contra uma ameaça que coloca em risco todos os seres vivos.",al={"quem é lisande","identidade da tenente lisande","quem é a tenente lisande"}},b5328b2a={q="De que lado a Tenente Lisande está?",a="Lisande é leal à Aurora Argêntea, e não à Aliança. A Aurora é uma coalizão neutra dedicada inteiramente a lutar contra o Flagelo, o que lhe permite trabalhar diretamente ao lado dos tauren e dos campeões da Horda sem hostilidade faccional.",al={"lisande aliança ou horda","a quem lisande serve","lisande é da aliança"}},["9158bc2a"]={q="O que a Tenente Lisande quer?",a="Lisande quer que aventureiros vigilantes investiguem e confrontem as forças do Flagelo que invadem as terras fora de Penhasco do Trovão. Seu objetivo é conter a ameaça morta-viva antes que ela possa invadir as planícies de Mulgore.",al={"o que lisande quer","objetivos de lisande","por que lisande precisa de ajuda"}},["0fde76ad"]={q="A quem a Tenente Lisande está ligada?",a="Ela está diretamente ligada à Aurora Argêntea, uma ordem independente de guerreiros sagrados, magos e batedores vindos de diversas raças para combater o Flagelo onde quer que a ameaça dos mortos-vivos apareça.",al={"facção da lisande","com quem a lisande trabalha","conexões da lisande"}}},fp="18,223,17.412.0,41.280.0,46.253.0,44.211.0"}
P.entries["npc:lieutenant-nevell"] = {n="Tenente Neves",s="O Tenente Neves é um oficial da Aurora Argêntea posicionado do lado de fora dos portões de Altaforja, em Dun Morogh. Servindo como um baluarte contra a escuridão crescente do Flagelo, ele coordena os defensores locais e alerta os aventureiros recém-chegados sobre as ameaças de mortos-vivos que sondam as fronteiras do reino dos anões.",h="O Tenente Neves é um oficial da Aurora Argêntea posicionado do lado de fora dos portões de Altaforja, em Dun...",kw={"aurora argêntea","dun morogh","altaforja","tenente neves","neves","flagelo"},ang={["faction:Alliance"]="Para os campeões da Aliança a caminho de Altaforja, Neves serve como um lembrete de que a guerra contra o Flagelo não está confinada ao norte.",["race:Dwarf"]="Os anões valorizam os olhos vigilantes da Aurora Argêntea do lado de fora de seu lar nas montanhas, sabendo que a vigília contra a necromancia é necessária até mesmo nas encostas frias de Dun Morogh."},sec={{t="Uma Vigília na Neve",b="Embora a Aurora Argêntea seja mais conhecida por manter a linha de frente nas devastadas Terras Pestilentas de Lordaeron, sua vigilância se estende até o sul. Posicionado em meio aos ventos congelantes do lado de fora de Altaforja, o Tenente Neves representa a defesa proativa da ordem contra incursões necromânticas. Quando atividades do Flagelo surgem nas passagens montanhosas de Dun Morogh, Neves direciona recrutas e aventureiros capazes para as linhas de frente a fim de garantir que a entrada nevada de Altaforja permaneça segura."}},faq={{q="Quem é o Tenente Neves?",a="O Tenente Neves é um oficial da Aurora Argêntea estacionado perto de Altaforja, em Dun Morogh. Sua missão é reunir defensores locais e investigar sinais da presença do Flagelo avançando sobre o reino dos anões.",al={"função de neves","quem é neves","tenente neves"}},{q="Por que a Aurora Argêntea está do lado de fora de Altaforja?",a="Embora sediada principalmente em Lordaeron, a Aurora Argêntea monitora todo o continente contra incursões de mortos-vivos. Se o Lich Rei tentar atacar profundamente territórios aliados como Dun Morogh, oficiais como Neves são enviados para coordenar as defesas da cidade e patrulhar as movimentações inimigas.",al={"aurora argêntea em dun morogh","aurora argêntea altaforja"}},{q="O que o Tenente Neves pede para os aventureiros fazerem?",a="Neves encarrega heróis capazes de se aventurarem além dos portões de Altaforja para patrulhar e repelir as forças próximas do Flagelo, neutralizando a ameaça dos mortos-vivos antes que consigam estabelecer uma posição nas passagens da montanha.",al={"missões de neves","investigar o flagelo"}}},fx={["4853a4a6"]={q="De que lado está o Tenente Neves?",a="O Tenente Neves serve à Aurora Argêntea, uma ordem neutra dedicada a proteger Azeroth do Flagelo. Embora seja humano, ele permanece do lado de fora dos portões de Altaforja como um aliado de todos que se opõem à ameaça dos mortos-vivos, coordenando defesas junto aos anões em vez de servir diretamente ao exército da Aliança.",al={"facção do tenente neves","por quem o tenente neves luta","o neves é aurora argêntea"}},["5e43a7a7"]={q="A quem o Tenente Neves está ligado?",a="Neves responde diretamente à liderança da Aurora Argêntea. Posicionado nas encostas de Dun Morogh, ele atua como um elo entre a ordem e os defensores de Altaforja, reunindo aventureiros locais e guardas das montanhas para enfrentar qualquer ameaça crescente do Flagelo na região.",al={"conexões do neves","laços do tenente neves com a aurora argêntea","a quem o neves responde"}}},fp="17,292,19.476.0,25.208.0,41.278.0,50.205.0"}
P.entries["npc:lieutenant-orrin"] = {n="Tenente Orrin",s="O Tenente Orrin é um oficial da Aurora Argêntea posicionado nos portões de Ventobravo. Alocado no Vale dos Heróis, ele coordena a defesa local contra incursões do Flagelo e direciona novos recrutas para investigar ameaças de mortos-vivos fora dos muros da capital.",h="O Tenente Orrin é um oficial da Aurora Argêntea posicionado nos portões de Ventobravo.",kw={"aurora argêntea","tenente orrin","cristal necrótico","orrin","flagelo","ventobravo","mortos-vivos","vale dos heróis"},ang={["class:Paladin"]="Paladinos que defendem a Luz costumam encontrar uma causa comum natural com os esforços da Aurora Argêntea para expurgar a necromancia onde quer que ela se prolifere.",["faction:Alliance"]="Para os campeões da Aliança que retornam à capital, Orrin serve como um lembrete austero de que nem mesmo as terras centrais do sul estão totalmente a salvo do alcance do Lich Rei."},sec={{t="Um Sentinela nos Portões",b="Embora a Aurora Argêntea seja conhecida principalmente por manter as linhas de frente no norte arruinado, sua presença se estende ao sul para proteger fortalezas vitais como Ventobravo. O Tenente Orrin vigia perto das imponentes estátuas do Vale dos Heróis, atento à estrada em busca de sinais de corrupção. Quando a magia necromântica se agita fora da capital, sua tarefa é soar o alarme e reunir aventureiros antes que forças nefastas possam ameaçar a população."},{t="Olhos nos Não Vivos",b="Orrin atua como o principal intermediário entre a ordem independente e os voluntários no reino do sul. Quando surgem sinais do Flagelo além dos portões da cidade, ele reúne batedores capacitados e os envia para obter informações e proteger artefatos perigosos, como cristais necróticos rachados, para entender e repelir melhor a ameaça dos mortos-vivos."}},faq={{q="Quem é o Tenente Orrin?",a="O Tenente Orrin é um oficial humano a serviço da Aurora Argêntea. Ele está posicionado no Vale dos Heróis, na entrada de Ventobravo, encarregado de coordenar defesas e alistar batedores sempre que o Flagelo ameaçar as terras vizinhas.",al={"quem é orrin","história do tenente orrin","quem é o oficial da aurora argêntea"}},{q="Por que a Aurora Argêntea está em Ventobravo?",a="Embora a Aurora Argêntea lute principalmente contra o Flagelo nas Plaguelands, ela mantém postos avançados e contatos nos principais centros da Aliança e da Horda. Posicionados nos portões da capital, oficiais como Orrin vigiam contra incursões necromânticas e recrutam combatentes capazes para conter o avanço dos mortos-vivos.",al={"por que a aurora argêntea está em ventobravo","aurora argêntea ventobravo","o que a aurora argêntea está fazendo aqui"}},{q="O que o Tenente Orrin pede que os aventureiros façam?",a="Orrin orienta os recrutas a patrulharem o perímetro fora de Ventobravo, investigarem sinais de atividade do Flagelo e recuperarem artefatos como cristais necróticos rachados para estudar a magia profana por trás das incursões.",al={"missões de orrin","investigação do flagelo em ventobravo","o que orrin quer"}}},fx={["3ede5d84"]={q="De que lado está o Tenente Orrin?",a="O Tenente Orrin serve à Aurora Argêntea, uma coalizão neutra dedicada formada para lutar contra o Flagelo onde quer que ele ameace Azeroth. Embora esteja posicionado dentro do Vale dos Heróis de Ventobravo entre os defensores humanos, sua lealdade principal permanece com a missão sagrada da Aurora, e não com a política da Aliança.",al={"facção do tenente orrin","a quem o orrin serve","o tenente orrin é da aliança"}}},fp="16,276,23.446.0,20.352.0,24.244.0,41.313.0,49.210.0"}
P.entries["npc:loganaar"] = {n="Loganaar",s="Loganaar é um instrutor druídico elfo noturno que reside no refúgio de Refúgio Noturno, em Clareira da Lua. Dedicado a guiar iniciados tanto da Aliança quanto da Horda, ele instrui jovens druidas à medida que se sintonizam com a natureza e se preparam para o chamado do Sonho Esmeralda.",h="Loganaar é um instrutor druídico elfo noturno que reside no refúgio de Refúgio Noturno, em Clareira da Lua.",kw={"círculo cenariano","instrutor de druidas","sonho esmeralda","loganaar","clareira da lua","refúgio noturno"},ang={["class:Druid"]="Tanto para druidas de Darnassus quanto de Penhasco do Trovão, Loganaar é um dos primeiros mentores encontrados ao se teletransportar para Clareira da Lua, oferecendo treinamento avançado e aconselhamento espiritual.",["race:NightElf"]="Loganaar reflete as tradições antigas dos druidas Kaldorei que passaram milênios comungando com a natureza e entrando no Sonho Esmeralda sob a liderança de Malfurion Tempesfúria."},sec={{t="Guardião da Arte Sagrada",b="Situado em meio aos galhos serenos de Refúgio Noturno, Loganaar atua como o principal mentor para os druidas recém-iniciados que viajam para Clareira da Lua. Independentemente de um iniciado vir de Darnassus ou de Penhasco do Trovão, Loganaar oferece orientação sobre equilíbrio, metamorfose e reverência à natureza. Ele lembra a seus alunos que, mesmo em meio à pedra fria e terras desconhecidas, a verdadeira tranquilidade deve ser encontrada dentro de si mesmo. Ele também atua como um guia acolhedor para aqueles que se aprofundam nos assuntos do Círculo Cenariano, enviando alunos promissores a andarilhos como Torwa Mateiro na Cratera Un'Goro ou mais a fundo nos antigos ritos florestais."},{t="O Chamado do Sonho",b="Além das magias fundamentais, Loganaar prepara os alunos para o destino supremo compartilhado pelos protetores tradicionais de Kalimdor: o sono profundo do Sonho Esmeralda. Ele instrui os iniciados sobre a conexão sagrada entre o reino espiritual primevo de Azeroth e o mundo desperto, lembrando-lhes de que a verdadeira maestria um dia exigirá hibernar por séculos para caminhar entre as formas mais puras e imaculadas da natureza sob a orientação dos semideuses."}},faq={{q="Quem é Loganaar?",a="Loganaar é um instrutor de druidas elfo noturno estabelecido em Refúgio Noturno, o assentamento central de Clareira da Lua. Ele recebe druidas de todas as origens para treinarem suas artes e os apresenta às tradições mais profundas do Círculo Cenariano.",al={"pnc loganaar","quem é loganaar","história de loganaar"}},{q="Loganaar treina druidas da Horda?",a="Sim. Clareira da Lua é um solo sagrado e neutro supervisionado pelo Círculo Cenariano. Como membro do Círculo, Loganaar deixa de lado o conflito entre a Aliança e a Horda para instruir druidas taurens e elfos noturnos da mesma forma.",al={"taurens podem treinar com loganaar","loganaar horda","instrutor de druidas clareira da lua horda"}},{q="O que Loganaar ensina sobre o Sonho Esmeralda?",a="Loganaar ensina que todo druida verdadeiro sentirá, com o tempo, o chamado do Sonho Esmeralda. Ele explica que caminhar entre suas formas imaculadas durante uma hibernação longa e profunda é onde ocorre o treinamento supremo de um druida.",al={"sonho de loganaar","citação sonho esmeralda"}},{q="Para onde Loganaar envia druidas experientes?",a="Conforme os druidas ganham experiência, Loganaar os direciona para o mundo para observar e restaurar os ecossistemas primitivos de Azeroth. Entre suas tarefas, ele envia discípulos experientes para ajudar naturalistas como Torwa Mateiro nas selvas selvagens da Cratera Un'Goro.",al={"missões de loganaar","missão torwa mateiro loganaar"}}},fp="8,261,24.626.0,21.439.0,16.225.0,33.211.0,49.225.0,41.245.0"}
P.entries["npc:lomac-gearstrip"] = {n="Lomac Motopista",s="Lomac Motopista é um ambicioso inventor gnomo baseado em Beco da Gambiarra, em Altaforja. Renomado por formular o devastador explosivo NG-5, ele mantém contato com outros pesquisadores gnomos que operam por toda Kalimdor.",h="Lomac Motopista é um ambicioso inventor gnomo baseado em Beco da Gambiarra, em Altaforja.",kw={"um velho colega","engenheiro gnomo","inaptidão + reagentes = diversão","altaforja","lomac motopista","explosivo ng-5","cordilheira das torres de pedra","beco da gambiarra"},ang={["faction:Alliance"]="Agentes da Aliança que transitam entre Altaforja e postos avançados de expedição em Kalimdor frequentemente transportam munições delicadas e fórmulas voláteis a pedido de Lomac.",["profession:Engineering"]="O explosivo NG-5 de Lomac representa a vanguarda da pirotecnia gnômica, servindo de inspiração para engenhoqueiros interessados em compostos explosivos de alto rendimento.",["race:Gnome"]="Lomac personifica a determinação resiliente dos gnomos de Beco da Gambiarra, mantendo pesquisas técnicas de alto risco mesmo vivendo no exílio de Gnomeregan."},sec={{t="Uma Faísca em Beco da Gambiarra",b="Entre as engrenagens barulhentas e os canos sibilantes de Beco da Gambiarra, em Altaforja, Lomac Motopista aprimora os detalhes da artilharia gnômica. Como muitos gnomos exilados que fugiram da tragédia em Gnomeregan, Lomac integrou suas operações de engenharia diretamente à capital dos anões. Sua oficina concentra-se em misturas químicas voláteis e munições especializadas, projetadas para superar fortalezas inimigas fortemente defendidas."},{t="O Explosivo NG-5",b="A contribuição da qual Lomac mais se orgulha para a engenharia de combate moderna é o explosivo NG-5. Formulado para obter o máximo rendimento destrutivo, o composto exige manuseio preciso e reagentes químicos raros. Para refinar e utilizar invenções tão perigosas em campo, Lomac mantém contato com velhos colegas posicionados em teatros distantes, trocando pedidos técnicos e suprimentos perigosos através d'O Grande Oceano."}},faq={{q="Onde posso encontrar Lomac Motopista?",a="Lomac Motopista reside em Beco da Gambiarra, o bairro dos gnomos localizado na porção leste da cidade montanhosa de Altaforja.",al={"localização de lomac motopista","onde fica lomac","encontrar lomac motopista"}},{q="Pelo que Lomac Motopista é famoso por inventar?",a="Lomac é mais conhecido como o criador do explosivo NG-5, uma potente fórmula de artilharia projetada para fornecer um poder de fogo devastador aos empreendimentos dos gnomos.",al={"o que lomac criou","invenção de lomac","criador do explosivo ng-5"}},{q="Por que Lomac faz negócios com contatos em Kalimdor?",a="Lomac mantém contato com antigos colegas de pesquisa que trabalham em regiões de fronteira, como a Cordilheira das Torres de Pedra, coordenando a obtenção de ingredientes químicos perigosos e testando seus explosivos de alto rendimento em operações ativas.",al={"lomac cordilheira das torres de pedra","por que missão cordilheira das torres de pedra","colegas de lomac"}},{q="Que tipo de tarefas Lomac oferece aos aventureiros?",a="Lomac encarrega mensageiros de confiança da Aliança de transportar pedidos de compra e reagentes químicos voláteis entre Altaforja e pesquisadores posicionados no exterior, frequentemente envolvendo seus experimentos com o explosivo NG-5.",al={"missões de lomac","ineptitude chemicals fun","missão um velho colega"}},{q="O que é o Purchase Order Receipt vinculado a Lomac?",a="Lomac criou o Purchase Order Receipt, um manifesto usado para organizar e documentar remessas de equipamentos especializados e reagentes voláteis perigosos entre engenhoqueiros.",al={"purchase order receipt","recibo de lomac"}},{q="Lomac é afiliado aos refugiados de Gnomeregan?",a="Sim. Como o restante dos moradores de Beco da Gambiarra, Lomac faz parte da comunidade deslocada de Gnomeregan que vive sob a hospitalidade dos anões de Altaforja enquanto continua seu trabalho de engenharia.",al={"lomac é de gnomeregan","facção de lomac"}}},fx={e46167fb={q="Quem é Lomac Motopista?",a="Lomac Motopista é um ambicioso inventor e engenheiro gnomo que opera no Beco da Gambiarra, dentro da fortaleza anã de Altaforja. Profundamente envolvido em experimentação volátil e engenharia química, ele é mais conhecido por desenvolver artefatos potentes como o explosivo NG-5. Apesar da distância através do Grande Oceano, ele mantém contatos e acordos comerciais que se estendem até Kalimdor para adquirir os materiais raros e os testes de campo de que precisa.",al={"quem é lomac","quem é motopista","história de lomac motopista"}},["6618560a"]={q="O que Lomac Motopista quer?",a="Lomac Motopista é movido por seus projetos de engenharia explosiva, notadamente o refinamento de sua valiosa carga NG-5. Para manter seus testes químicos avançando, ele precisa de mensageiros, compostos voláteis e testes de campo realizados com suas misturas. Ele conta com viajantes e velhos conhecidos ao redor do mundo para cumprir pedidos de compra e obter os reagentes raros necessários para aperfeiçoar suas invenções voláteis.",al={"o que lomac quer","objetivos de lomac motopista","por que lomac precisa de ajuda"}},ca50cdb6={q="A quem Lomac Motopista está ligado?",a="Lomac mantém laços com associados distantes e outros engenheiros, incluindo um velho colega baseado no exterior que ajuda com pedidos e testes especializados. Trabalhando a partir do Beco da Gambiarra, ele opera confortavelmente ao lado dos Exilados de Gnomeregan e dos artesãos residentes de Altaforja, direcionando mensageiros e aventureiros para atuar como elos entre sua bancada de trabalho nos Reinos do Leste e os campos de testes em Kalimdor.",al={"com quem o lomac trabalha","associados de lomac motopista","velho colega de lomac"}}},fp="15,212,22.406.0,18.398.0,33.125.0,45.148.0,46.240.0,51.206.0,49.169.0,47.196.0"}
P.entries["npc:longbraid-the-grim"] = {n="Trançalonga, o Austero",s="Trançalonga, o Austero é um comandante anão de Altaforja posicionado nos arredores da fortaleza caída de Dun Modr, no norte do Pantanal. De luto pela perda de seu irmão e pela invasão da Ponte Thandol, ele coordena as forças anãs sobreviventes contra o clã invasor Ferro Negro.",h="Trançalonga, o Austero é um comandante anão de Altaforja posicionado nos arredores da fortaleza caída de Dun...",kw={"ferro negro","dun modr","trançalonga","ponte thandol","o austero","os pântanos","whelgar"},ang={["faction:Alliance"]="Trançalonga mantém a tênue linha que protege o portão norte de Khaz Modan, lutando para reabrir a crucial rota terrestre através da Ponte Thandol até Arathi.",["race:Dwarf"]="Para os anões de Altaforja, Trançalonga personifica a feroz e duradoura rixa de sangue contra seus primos traiçoeiros do clã Ferro Negro, que atacaram diretamente o seu portal norte."},sec={{t="Uma Vigília Amarga",b="Posicionado à vista da ponte para o Planalto Arathi, Trançalonga, o Austero reúne o que restou da guarnição anã depois que o clã Ferro Negro tomou Dun Modr. O ataque repentino devastou os defensores regionais e resultou na morte do próprio irmão de Trançalonga durante o cerco à Ponte Thandol. Consumido pela dor e pelo ódio, Trançalonga se recusa a abandonar a fronteira norte, orientando viajantes e montanhistas sobreviventes em ataques cirúrgicos para conter o avanço do Ferro Negro."},{t="Mantendo a Posição",b="Além de defender o acesso à ponte, Trançalonga supervisiona operações anãs mais amplas por todo o Pantanal. Ele enviou soldados vitais para escoltar o Prospector Whelgar pelos pântanos e trabalha incansavelmente para recuperar as fortificações perdidas de Dun Modr, jurando vingança contra os sabotadores Ferro Negro."}},faq={{q="Quem é Trançalonga, o Austero?",a="Trançalonga, o Austero é um comandante anão posicionado nos arredores de Dun Modr, no norte do Pantanal. Ele lidera a resistência local da Aliança contra os anões Ferro Negro que invadiram a região.",al={"quem é trançalonga","identidade de trançalonga","anão de dun modr"}},{q="Por que Trançalonga é chamado de 'o Austero'?",a="Ele adquiriu sua postura austera após seu irmão ser morto durante o devastador ataque do Ferro Negro à Ponte Thandol. Desde então, ele é consumido pelo desejo de vingar seu parente caído.",al={"por que ele é austero","irmão de trançalonga","história de trançalonga"}},{q="O que aconteceu com Dun Modr?",a="Dun Modr foi invadida e ocupada pelo clã Ferro Negro, que emboscou a guarnição anã e tentou destruir a Ponte Thandol, cortando a principal rota entre o Pantanal e o Planalto Arathi.",al={"queda de dun modr","o que aconteceu com a ponte","ataque à ponte thandol"}},{q="Qual é a ligação de Trançalonga com o Prospector Whelgar?",a="Trançalonga designou soldados de suas forças para acompanhar e proteger o Prospector Whelgar enquanto a equipe de escavação anã avançava pelo perigoso Pantanal.",al={"whelgar trançalonga","carta de merrin"}}},fx={d54d2b61={q="De que lado está Trançalonga, o Austero?",a="Trançalonga, o Austero, serve a Altaforja e à Aliança. Posicionado no norte do Pantanal, ele comanda as forças anãs que tentam manter a linha contra o clã Ferro Negro que tomou Dun Modr e danificou a The Thandol Span.",al={"facção de trançalonga","a quem trançalonga serve","trançalonga aliança"}},["40b05609"]={q="O que Trançalonga, o Austero, quer?",a="Trançalonga busca vingança contra os anões Ferro Negro que invadiram Dun Modr e mataram seu irmão durante o ataque à The Thandol Span. Ele quer que as forças deles sejam derrotadas e que a fronteira norte seja garantida para Altaforja.",al={"objetivo de trançalonga, o austero","o que trançalonga quer","motivos de trançalonga"}},["0c91256b"]={q="Por que Trançalonga, o Austero, está aqui?",a="Trançalonga está acampado logo fora de Dun Modr, no extremo norte do Pantanal, para monitorar as ruínas e coordenar a defesa. Após a brutal invasão Ferro Negro que destruiu a cidade e a ponte, ele permanece na linha de frente para direcionar contra-ataques contra o inimigo invasor.",al={"por que trançalonga está no pantanal","por que trançalonga está fora de dun modr","motivo da localização de trançalonga"}}},fp="18,280,14.492.0,16.312.0,26.184.0,35.189.0,26.205.0,53.161.0"}
P.entries["npc:loramus-thalipedes"] = {n="Loramus Talípedes",s="Loramus Talípedes é um caçador de demônios elfo noturno recluso, isolado em uma ilha remota na costa de Azshara. Flanqueado por leais cães vis, ele dedica sua existência a destruir Razelikh, o Profanador, orientando campeões experientes por meio de rituais para abater o senhor do terror.",h="Loramus Talípedes é um caçador de demônios elfo noturno recluso, isolado em uma ilha remota na costa de...",kw={"azshara","caçador de demônios","felbane","cão vil","ninho de hetaera","loramus","razelikh","talípedes"},ang={["class:Warlock"]="Bruxos reconhecerão seus cães vis controlados como prova de uma subjugação demoníaca excepcional, embora Loramus aprisione demônios estritamente para massacrar sua própria espécie.",["race:NightElf"]="Os elfos noturnos tradicionalmente veem os caçadores de demônios com profundo horror e desconfiança, encarando sua automutilação ritualística e seus pactos demoníacos como um caminho imperdoável que reflete a traição de Illidan."},sec={{t="O Caçador Cego das Ilhas",b="Empoleirado em uma ilha solitária e fustigada por tempestades a sudeste do Ninho de Hetaera, Loramus Talípedes vive afastado do restante de seu povo. Ele é um caçador de demônios — um exilado que passou pelo agonizante ritual de cegar a si mesmo para obter a visão espectral. Cercado por três imponentes cães vis chamados Raytaf, Shahiar e Zaman, Loramus vigia as correntes invisíveis da corrupção demoníaca por toda Azeroth, enquanto mantém uma vigília atenta sobre as ruínas despedaçadas de Azshara."},{t="Uma Vingança Através dos Continentes",b="A obsessão de Loramus fica do outro lado do mar, na Barreira do Inferno, voltada inteiramente para o senhor do terror Razelikh, o Profanador. Sabendo que o aço convencional não pode dar fim permanente a um demônio astuto, Loramus guia viajantes por rituais ancestrais, exigindo que coletem azsharita e o verdadeiro nome do demônio para que armas Felbane possam ser forjadas contra ele. Por meio desses preparativos esotéricos, ele busca remover as proteções de Razelikh, aprisionar o verdadeiro nome do demônio e encerrar a vingança de uma vez por todas."}},faq={{q="Quem é Loramus Talípedes?",a="Loramus Talípedes é um caçador de demônios elfo noturno que reside em uma ilha isolada na costa de Azshara. Ele se dedica a combater demônios poderosos, notadamente o senhor do terror Razelikh, o Profanador.",al={"identidade de loramus","quem é o caçador de demônios em azshara","quem é loramus"}},{q="Por que Loramus usa uma venda?",a="Assim como outros caçadores de demônios, Loramus abriu mão dos próprios olhos. Em troca da visão mortal comum, esse ritual lhe concedeu a visão espectral necessária para detectar energias demoníacas.",al={"por que loramus não tem olhos","loramus cego","venda de caçador de demônios"}},{q="Por que há cães vis guardando-o?",a="Loramus dominou e subjugou três poderosos cães vis — Raytaf, Shahiar e Zaman —, voltando os próprios instintos predadores deles para servir às suas caçadas demoníacas em vez de servirem à Legião Ardente.",al={"cães vis de loramus","por que loramus tem demônios","raytaf shahiar zaman"}},{q="Qual é a ligação dele com a Barreira do Inferno?",a="Ele orquestra a campanha para matar o senhor do terror Razelikh, o Profanador, que comanda as alturas da Barreira do Inferno. Loramus fornece o conhecimento crucial, os ritos e as armas necessárias para perfurar as proteções de Razelikh.",al={"loramus barreira do inferno","missão de razelikh","por que ele se importa com a barreira do inferno"}}},fp="18,274,29.456.0,28.498.1,26.193.0,27.176.0,37.189.0,44.216.0"}
P.entries["npc:lord-arkkoroc"] = {n="Lorde Arkkoroc",s="Lorde Arkkoroc é um gigante do mar ancestral e imponente que habita as ruínas do Templo de Arkkoran ao longo da costa escarpada de Azshara. Descrito pelo caçador de demônios Loramus Talípedes como uma divindade menor, ele domina as águas ao redor e comanda gigantes do mar inferiores que servem como seus filhos.",h="Lorde Arkkoroc é um gigante do mar ancestral e imponente que habita as ruínas do Templo de Arkkoran ao longo...",kw={"arkkoran","arkkoroc","azshara","hetaera","loramus","lorde arkkoroc","gigante do mar"},ang={["race:NightElf"]="As ruínas do Templo de Arkkoran erguem-se sobre antigas terras dos Altaneiros, onde uma ancestral entidade marinha agora reina suprema sobre a majestade decaída da velha Kalimdor."},sec={{t="Senhor da Costa Submersa",b="Repousando entre as ruínas incrustadas de salitre do Templo de Arkkoran, Lorde Arkkoroc é muito mais do que um gigante do mar comum. Para eremitas como Loramus Talípedes, esse ser colossal é considerado uma divindade menor cuja vontade divina molda as águas circundantes. Seus filhos patrulham os penhascos e baixios ao redor do santuário, impondo seu domínio silencioso sobre as margens tempestuosas de Azshara."},{t="Vingança Contra as Profundezas",b="Apesar de seu imenso poder divino, Arkkoroc sofre perdas pessoais sob as marés. Uma temível hidra de múltiplas cabeças chamada Hetaera caçou e massacrou muitos de seus filhos ao longo dos penhascos. Incapaz ou relutante em caçar a fera diretamente, Arkkoroc troca conhecimento valioso e auxílio oculto com qualquer aventureiro errante forte o suficiente para lhe apresentar as cabeças do assassino de sua prole."}},faq={{q="Quem é Lorde Arkkoroc?",a="Lorde Arkkoroc é um gigantesco gigante do mar que reside no Templo de Arkkoran em Azshara. Ele é reverenciado como uma divindade menor dos mares e governa uma ninhada de gigantes do mar a quem considera seus filhos.",al={"quem e arkkoroc","historia de arkkoroc","gigante do mar do templo"}},{q="Onde posso encontrar Lorde Arkkoroc?",a="Você pode encontrá-lo empoleirado entre as ruínas do Templo de Arkkoran, localizado na costa leste e nos recifes rochosos de Azshara.",al={"localizacao de arkkoroc","onde fica arkkoroc","encontrar arkkoroc"}},{q="Por que Loramus Talípedes envia aventureiros a Arkkoroc?",a="Loramus Talípedes orienta os viajantes a irem até Arkkoroc para buscar conhecimentos arcanos sobre um demônio poderoso. Como uma divindade marinha menor, Arkkoroc detém saberes ancestrais, mas exige que os aventureiros matem a hidra Hetaera antes de compartilhar seus segredos.",al={"missao de loramus arkkoroc","nome da fera"}},{q="Por que Arkkoroc está furioso com a hidra Hetaera?",a="A fera marinha selvagem Hetaera massacrou vários dos filhos de Arkkoroc que patrulhavam a costa. Buscando vingança por seus parentes mortos, o gigante do mar exige as cabeças dela.",al={"por que matar hetaera","rancor de arkkoroc contra hidra"}}},fp="13,294,24.378.0,26.398.1,21.195.0,31.129.0,57.247.0,45.170.0"}
P.entries["npc:lord-baurles-k-wishock"] = {n="Lorde Baurles K. Wishock",s="Lorde Baurles K. Wishock é um nobre que reside na Petitioner's Chamber de Bastilha Ventobravo. Conhecido entre os taberneiros por suas contas não pagas e pelo apreço por bebidas fortes, ele se deparou com assuntos muito mais sombrios do que mera embriaguez nos cantos escusos da cidade.",h="Lorde Baurles K.",kw={"baurles","casa dos nobres","petitioner's chamber","slaughtered lamb","bastilha ventobravo","wishock","malvino"},ang={["class:Warlock"]="A investigação intrometida de Wishock sobre O Cordeiro Imolado representa uma ameaça imediata ao conciliábulo sombrio de Ventobravo, tornando sua morte discreta uma prioridade máxima para os bruxos praticantes.",["race:Human"]="Sua presença na Petitioner's Chamber reflete a reputação decadente e interesseira da Casa dos Nobres durante os primeiros anos de reinado do jovem rei Anduin."},sec={{t="A Curiosidade Perigosa de um Nobre",b="Fazendo-se presente entre os peticionários e dignitários dentro de Bastilha Ventobravo, Lorde Baurles K. Wishock é um membro da influente Casa dos Nobres. Apesar de sua posição elevada, Wishock desenvolveu o hábito de frequentar as tavernas decadentes do Distrito dos Magos, especialmente O Cordeiro Imolado, deixando para trás contas substanciais sem pagar. Enquanto bebia por lá, no entanto, ele ouviu rumores sobre o conciliábulo de bruxos que praticava artes sombrias nos porões sob o assoalho. Determinado a fechar a taverna, Wishock começou a fazer petições a outros nobres por uma investigação formal — sem saber que descobrir cabalas demoníacas em Ventobravo raramente fica impune."},{t="Um Cálice Envenenado",b="A pressão política de Wishock o colocou diretamente na mira dos bruxos ocultos da cidade. Em vez de arriscar a atenção real ou uma inquisição em seu santuário subterrâneo, o bruxo Malvino da Garra Preta orquestrou a eliminação silenciosa do nobre. Aproveitando-se da notória sede de Wishock por safras luxuosas, o conciliábulo preparou uma mistura letal disfarçada de cerveja fina, providenciando para que um aventureiro contratado entregasse a bebida fatal bem debaixo dos narizes dos guardas da Fortaleza."}},faq={{q="Quem é Lorde Baurles K. Wishock?",a="Lorde Baurles K. Wishock é um aristocrata ligado à Casa dos Nobres. Ele passa seus dias na Petitioner's Chamber dentro de Bastilha Ventobravo, embora seja infame no Distrito dos Magos por acumular contas de bebida grandes e não pagas.",al={"baurles wishock","quem é wishock","nobre peticionário"}},{q="Onde Lorde Wishock pode ser encontrado?",a="Ele pode ser encontrado de pé dentro da Petitioner's Chamber, no lado leste de Bastilha Ventobravo, cercado por outros cortesãos, diplomatas e suplicantes aguardando a atenção real.",al={"localização de wishock","onde fica wishock","encontrar lorde wishock"}},{q="Por que os bruxos sob O Cordeiro Imolado o querem morto?",a="Durante suas noitadas de bebedeira n'O Cordeiro Imolado, Wishock descobriu que um conciliábulo de bruxos operava sob a taverna. Ele começou a pressionar a Casa dos Nobres para abrir um inquérito formal e fechar o estabelecimento, ameaçando expor suas operações secretas.",al={"por que matar wishock","malvino wishock","por que envenenar wishock"}},{q="Como ele é assassinado?",a="Malvino da Garra Preta prepara um veneno mortal e o disfarça de bebida requintada. Sabendo da fraqueza de Wishock por álcool refinado e bebidas grátis, um agente entrega o barril envenenado diretamente a ele em Bastilha Ventobravo.",al={"como wishock morre","veneno de wishock","uma bebida para poucos"}}},fx={["255656dc"]={q="De que lado está o Lorde Baurles K. Wishock?",a="O Lorde Wishock serve ao Reino de Ventobravo como membro da Casa dos Nobres. Ele atua estritamente dentro da aristocracia real, usando sua influência política para defender a autoridade civil e nobre contra elementos subversivos que espreitam dentro das fronteiras da cidade.",al={"lado do lorde wishock","facção do lorde wishock","a quem wishock serve"}},["59c1fa27"]={q="O que o Lorde Baurles K. Wishock quer?",a="O Lorde Wishock está determinado a expor e acabar com o coven sombrio que opera no porão abaixo do The Slaughtered Lamb. Tendo descoberto seus ritos vis, ele está ativamente fazendo lobby com seus pares na Casa dos Nobres para lançar uma investigação oficial em grande escala sobre a taverna e expurgar os Bruxos de Ventobravo.",al={"objetivo de wishock","o que wishock quer","plano do lorde wishock"}},["3d37be28"]={q="Por que o Lorde Baurles K. Wishock está na Bastilha Ventobravo?",a="Você encontrará o Lorde Wishock na Petitioner's Chamber dentro da Bastilha Ventobravo, onde ele atende aos seus deveres aristocráticos. Como membro da Casa dos Nobres, ele frequenta a bastilha para conferenciar com outros lordes e peticionar à corte real.",al={"por que wishock está na bastilha ventobravo","por que o lorde wishock está aqui","wishock petitioner's chamber"}},["83d2fff3"]={q="A quem o Lorde Baurles K. Wishock está ligado?",a="O Lorde Wishock pertence à Casa dos Nobres, a influente assembleia governante da aristocracia de Ventobravo. Fora da corte, ele era um cliente habitual do The Slaughtered Lamb no Distrito dos Magos — onde acumulou uma enorme conta não paga antes de descobrir o coven de Bruxos praticando artes das trevas em suas criptas escondidas.",al={"ligações de wishock","conexões do lorde wishock","wishock casa dos nobres"}}},fp="23,241,32.635.0,14.479.1,31.233.0,32.179.0,63.276.1,23.222.1"}
P.entries["npc:lord-cobrahn"] = {n="Lorde Cobrahn",s="Lorde Cobrahn é um dos quatro líderes dos corrompidos Druids of the Fang à espreita nas profundezas da Caverna Ululante. Outrora um druida elfo noturno da nobre ordem de Naralex, que esperava curar os Sertões, ele sucumbiu ao pesadelo que infectava as nascentes da caverna. Assumindo a forma letal de uma serpente, Cobrahn agora comanda ninhadas de serpentes desvirtuadas e defende o labirinto retorcido.",h="Lorde Cobrahn é um dos quatro líderes dos corrompidos Druids of the Fang à espreita nas profundezas da...",kw={"cobrahn","píton desvirtuada","druids of the fang","fanglord","gema de cobrahn","lorde cobrahn","caverna ululante"},ang={["class:Druid"]="Cobrahn serve como um aviso sombrio de como a metamorfose druídica pode ser pervertida quando conectada ao pesadelo em vez do equilíbrio natural.",["faction:Horde"]="Aventureiros da Horda buscam Cobrahn para pôr fim à vil corrupção que se infiltra nos Sertões e proteger o frágil ecossistema das planícies de Kalimdor.",["race:NightElf"]="Para os elfos noturnos, a queda de Cobrahn é uma tragédia amarga, ao ver um habilidoso irmão do Círculo Cenariano abandonar sua herança para liderar monstros nas profundezas subterrâneas."},sec={{t="Um Druida Corrompido",b="Antes de sua queda, Cobrahn era um dos nobres druidas que seguiam Naralex. Quando Naralex se aventurou na Caverna Ululante sob os Sertões esperando canalizar suas nascentes subterrâneas e restaurar a vida exuberante aos ermos áridos, Cobrahn o acompanhou. No entanto, quando a comunhão de Naralex com o Sonho Esmeralda se degenerou em um pesadelo retorcido, a mente de Cobrahn se despedaçou junto com a de seus irmãos."},{t="O Abraço da Serpente",b="Em vez de canalizar as tradicionais feras totêmicas da tradição cenariana, o pesadelo distorceu a metamorfose de Cobrahn em algo predatório e reptiliano. Ele agora domina uma forma serpentina mortal que liberta em batalha. Flanqueado por venenosas pítons desvirtuadas e ostentando uma garra perversa na mão direita, ele vigia sua seção das grutas, expurgando violentamente qualquer um que tente quebrar o domínio do pesadelo sobre as cavernas."}},faq={{q="Quem era Lorde Cobrahn antes de se tornar maligno?",a="Antes que o pesadelo o tomasse, Cobrahn era um druida elfo noturno da nobre ordem de Naralex, que entrou na Caverna Ululante na esperança de usar suas nascentes para curar os Sertões.",al={"nome verdadeiro de cobrahn","quem é cobrahn"}},{q="Por que ele é chamado de Lorde Cobrahn?",a="Nenhum relato explica o nome, mas ele combina com ele. Deformado pelo pesadelo na Caverna Ululante, ele assume uma forma letal de serpente e mantém pítons desvirtuadas ao seu lado, e seus companheiros líderes Fang Anacondra, Pythas e Serpentis ostentam nomes similarmente serpentinos.",al={"por que cobrahn","significado do nome lorde cobrahn"}},{q="Onde Lorde Cobrahn pode ser encontrado?",a="Lorde Cobrahn reside nas profundezas da Caverna Ululante, uma rede subterrânea sinuosa localizada no centro dos Sertões, cercado por pítons desvirtuadas e outras feras corrompidas pelo pesadelo.",al={"localização de cobrahn","onde fica lorde cobrahn","sala de cobrahn"}},{q="Por que os aventureiros precisam derrotá-lo?",a="Ele é um dos principais Fanglords que lideram os Druids of the Fang. Ele carrega a Gema de Cobrahn, que a druida Nara Wildmane do Penhasco do Trovão busca para quebrar o domínio dos líderes Fang sobre os Sertões.",al={"por que matar cobrahn","leaders of the fang cobrahn"}},{q="Quais traços físicos únicos ele possui?",a="Ao contrário dos elfos noturnos comuns, Cobrahn tem uma estatura visivelmente maior, empunha uma garra afiada na mão direita e pode se transformar completamente em uma serpente venenosa gigante durante o combate.",al={"como é a aparência de cobrahn","aparência de cobrahn"}},{q="Qual é a sua ligação com os outros Druids of the Fang?",a="Cobrahn é um dos quatro principais Fanglords ao lado de Lady Sucurina e seus semelhantes. Eles são antigos druidas da nobre ordem de Naralex que entraram nas cavernas com Naralex e sucumbiram conjuntamente à corrupção retorcida do pesadelo.",al={"líderes dos druids of the fang","cobrahn e anacondra"}}},fx={["3feb6d50"]={q="De que lado está Lorde Cobrahn?",a="Lorde Cobrahn serve aos Druidas da Presa e ao pesadelo que se espalha dentro da Caverna Ululante. Ele rompeu toda lealdade ao Círculo Cenariano e ao povo dos elfos noturnos, mantendo-se ao lado dos discípulos caídos de Naralex contra qualquer um que ouse entrar para purificar a corrupção.",al={"facção de cobrahn","a quem cobrahn serve","lealdades de lorde cobrahn"}},ffd3d503={q="Quem é Lorde Cobrahn?",a="Lorde Cobrahn é um dos quatro líderes corrompidos dos Druids of the Fang à espreita nas profundezas da Caverna Ululante. Outrora um druida elfo noturno da nobre ordem de Naralex, que esperava curar os Sertões, ele foi vítima do pesadelo sombrio que consumiu as cavernas. Deformado por sua corrupção, ele agora empunha magia venenosa e assume a forma de uma enorme fera serpentina.",al={"quem é cobrahn","história de lorde cobrahn","jarlaxla"}},["7ca4c072"]={q="Por que Lorde Cobrahn está aqui?",a="Ele entrou originalmente na Caverna Ululante ao lado de Naralex, com a intenção de explorar as águas subterrâneas e restaurar os Sertões em um paraíso exuberante. Quando a conexão de Naralex com o Sonho Esmeralda se distorceu em um pesadelo, as energias envenenaram as mentes de seus discípulos. Cobrahn sucumbiu completamente, permanecendo nas cavernas para guardar o arquidruida adormecido e nutrir a cria venenosa do pesadelo.",al={"por que cobrahn está na caverna ululante","por que cobrahn veio para cá"}}},fp="12,372,17.380.0,21.427.0,43.169.0,30.258.0,32.184.0,38.209.0,44.186.0,55.227.0"}
P.entries["npc:lord-ello-ebonlocke"] = {n="Lorde Malaquias Ebanez",s="Lorde Malaquias Ebanez é o prefeito de Vila Sombria e o líder de seu conselho administrativo, estabelecido dentro da Prefeitura de Vila Sombria. Cercado pela escuridão e por horrores rastejantes, ele luta diariamente para manter a ordem e proteger seus cidadãos sitiados, apesar de receber pouca ajuda de Ventobravo.",h="Lorde Malaquias Ebanez é o prefeito de Vila Sombria e o líder de seu conselho administrativo, estabelecido...",kw={"abercrombie","althea","conselho","vila sombria","floresta do crepúsculo","ebanez","malaquias","vila plácida","prefeito"},ang={["faction:Alliance"]="Lorde Ebanez representa os confins esquecidos da Aliança, onde prefeitos isolados precisam liderar seu povo em meio a condições de pesadelo sem ajuda imperial.",["race:Human"]="Para os humanos que viajam a partir de Ventobravo, falar com Lorde Ebanez é um lembrete austero de como as províncias do sul caíram na ruína e no abandono."},sec={{t="Um Prefeito Sitiado",b="Sentado na penumbra da Prefeitura de Vila Sombria, Lorde Malaquias Ebanez carrega o pesado fardo de governar um assentamento à beira da ruína. Outrora parte do próspero refúgio rural conhecido como Grand Hamlet, Vila Sombria agora está sufocada por sombras perpétuas e cercada por carniçais vorazes, abominações esqueléticas e feras selvagens. Malaquias preside o Conselho de Vila Sombria, lutando contra probabilidades impossíveis para manter os resquícios da civilização funcionando enquanto Ventobravo fecha os olhos para a sua desgraça."},{t="Uma Fronteira Dividida",b="Como a guarnição de Ventobravo se recusa a ceder soldados para as terras fronteiriças, Vila Sombria depende quase inteiramente de milícias voluntárias locais, como A Vigília Noturna, comandada por sua parente, Althea Ebonlocke. Quando líderes vizinhos, como o Magistrado Salomão de Vila Plácida, imploram por reforços para combater os orcs Rocha Negra, Lorde Ebanez é forçado a fazer escolhas agonizantes. Como ele solenemente explica aos mensageiros de Cristarrubra, Vila Sombria não pode poupar uma única lâmina: enviar seus guardas além da Boca da Mata deixaria seus próprios lares vulneráveis a uma invasão imediata pelos males que os cercam."},{t="Cego aos Desígnios do Eremita",b="Além de patrulhar as estradas, Lorde Ebanez depende frequentemente de aventureiros errantes para lidar com assuntos peculiares pela floresta. Em seu sincero desejo de ajudar todos os residentes da Floresta do Crepúsculo, ele coordena comunicações com figuras solitárias como o eremita Abercrombie. Infelizmente, a falta de discernimento de Ebanez em relação aos escritos enigmáticos do eremita o cega para o pesadelo macabro e costurado que se desenvolve logo além dos limites da cidade até que seja tarde demais."}},faq={{q="Quem é Lorde Malaquias Ebanez?",a="Lorde Malaquias Ebanez é o prefeito de Vila Sombria e o líder do Conselho de Vila Sombria. De seu assento na prefeitura, ele supervisiona a defesa, os assuntos civis e a sobrevivência da população humana remanescente da Floresta do Crepúsculo.",al={"quem é malaquias","prefeito de vila sombria","história de malaquias ebanez"}},{q="Qual é o parentesco dele com a Comandante Aldora Ebanez?",a="A Comandante Aldora Ebanez, a líder resoluta da Vigília Noturna, é parente próxima de Lorde Malaquias. Enquanto ele governa os assuntos civis e diplomáticos de Vila Sombria, ela comanda a milícia que protege ativamente o povoado.",al={"parentesco althea ebonlocke","althea é filha de malaquias"}},{q="Por que Lorde Ebanez se recusa a enviar tropas para Vila Plácida?",a="Quando o Magistrado Salomão pede ajuda contra os orcs Rocha Negra em Cristarrubra, Lorde Ebanez é forçado a recusar. Vila Sombria está tão pressionada por mortos-vivos e monstruosidades que privar a cidade de seus guardas faria com que ela fosse completamente devastada antes mesmo de a milícia alcançar os limites da floresta.",al={"por que não há ajuda para cristarrubra","mensagem para vila sombria","magistrado salomão lord malaquias ebanez"}},{q="Onde Lorde Malaquias Ebanez pode ser encontrado?",a="Ele está localizado dentro da Prefeitura de Vila Sombria, que fica no centro de Vila Sombria, na parte leste da Floresta do Crepúsculo.",al={"localização de malaquias ebanez","onde fica o prefeito ebanez"}},{q="Por que Ventobravo não envia tropas para ajudar Lorde Ebanez?",a="Ventobravo está envolvida em conflitos políticos internos após o desaparecimento do Rei Varian Wrynn. Com os recursos do reino limitados, a Casa dos Nobres praticamente abandonou as regiões ao sul, forçando líderes locais como Lorde Ebanez a organizar suas próprias defesas.",al={"por que ventobravo não ajuda a floresta do crepúsculo","negligência de ventobravo"}},{q="Qual é o envolvimento de Lorde Ebanez com Abercrombie?",a="Lorde Ebanez auxilia na comunicação com o eremita Abercrombie, ajudando a providenciar traduções de bilhetes estranhos.",al={"malaquias bilhete de abercrombie","tradução da carta de abercrombie"}}},fx={["0007fc63"]={q="De que lado está Lorde Malaquias Ebanez?",a="Lorde Malaquias Ebanez é leal à Grande Aliança e serve como prefeito de Vila Sombria, liderando seu conselho. Embora tenha jurado lealdade ao reino de Ventobravo, ele deve priorizar a sobrevivência de seus próprios cidadãos aterrorizados em vez de apelos regionais mais amplos por ajuda.",al={"facção de lorde ebanez","a quem malaquias ebanez serve","o ebanez é aliança"}},["48b49947"]={q="O que Lorde Malaquias Ebanez quer?",a="O prefeito Ebanez quer, acima de tudo, evitar que a cidade sitiada de Vila Sombria caia diante da escuridão invasora. Abandonado pela coroa, seu foco exclusivo é preservar seu povo e manter a Patrulha Noturna local tripulada contra os horrores circundantes.",al={"o que o lorde malaquias quer","objetivo de ebanez","propósito de malaquias ebanez"}},["26db90ba"]={q="Por que Lorde Malaquias Ebanez está em Vila Sombria?",a="Lorde Malaquias Ebanez preside Vila Sombria a partir da Prefeitura porque ele é o chefe do Conselho de Vila Sombria. Como líder cívico do último bastião de civilização sobrevivente da Floresta do Crepúsculo, ele supervisiona a defesa e o governo local do coração do assentamento.",al={"por que lorde ebanez está na floresta do crepúsculo","por que ebanez está em vila sombria","por que malaquias ebanez está nessa localização"}}},fp="19,289,19.500.0,18.576.0,29.465.1,27.208.0,48.218.0,59.294.0,39.106.0,57.276.0,54.125.1"}
P.entries["npc:lord-grayson-shadowbreaker"] = {n="Lorde Grayson Quebrassombra",s="O Lorde Grayson Quebrassombra é um veterano comandante paladino dos Cavaleiros do Punho de Prata estacionado na Catedral da Luz de Ventobravo. Um dos principais paladinos da Aliança, ele treina campeões da Luz em ascensão e supervisiona os provadores sagrados e árduos necessários para que paladinos veteranos reivindiquem seus corcéis sagrados.",h="O Lorde Grayson Quebrassombra é um veterano comandante paladino dos Cavaleiros do Punho de Prata estacionado...",kw={"catedral da luz","corcel","grayson","grimand elmore","paladino","scolomântia","quebrassombra","punho de prata"},ang={["class:Paladin"]="Grayson atua como um dos seus mentores espirituais mais elevados na Aliança, guiando seu caminho contra o Flagelo em Lordaeron e conduzindo os testes exigentes necessários para invocar um verdadeiro corcel.",["faction:Alliance"]="Um veterano estoico do Punho de Prata, Lorde Grayson ajuda a reforçar a defesa de Ventobravo e fortalece o apoio expedicionário aos reinos do norte disputados."},sec={{t="Mestre do Punho de Prata",b="O Lorde Grayson Quebrassombra está entre os principais defensores da Aliança, ancorando a presença da ordem em Ventobravo. Veterano do Punho de Prata, Grayson não apenas instrui os recrutas na habilidade marcial; ele testa sua convicção espiritual. Quando cavaleiros promissores demonstram sua prontidão, Grayson os envia ao norte em direção às linhas de frente disputadas das Terras Pestilentas Ocidentais para ajudar o Comandante Ashlam Valorfist no Acampamento Ventogelante."},{t="Os Testes do Corcel Sagrado",b="Para os paladinos que buscam seu cavalo de guerra sagrado, Quebrassombra exige um sacrifício profundo e virtude inquestionável. Suas provações exigem atos humildes de caridade — como ajudar os empobrecidos de Altaforja por meio do Sumo Sacerdote Rohan —, bem como jornadas perigosas para exorcizar a Várzea do Medo e purificar espíritos antigos dentro de Gládio Cruel. A provação culmina nas profundezas sombrias de Scolomântia, onde um iniciado deve confrontar o cavaleiro da morte Darkreaver e redimir uma montaria profana da servidão por meio da Luz."}},faq={{q="Onde posso encontrar o Lorde Grayson Quebrassombra?",a="O Lorde Grayson Quebrassombra reside dentro da Catedral da Luz, situada na Praça da Catedral em Ventobravo. Ele fica dentro dos salões principais supervisionando os paladinos do Punho de Prata.",al={"onde fica grayson quebrassombra","localização de quebrassombra","onde fica o lorde grayson"}},{q="Qual é o papel do Lorde Grayson para os paladinos?",a="Ele atua como um instrutor de paladinos de alto escalão da Aliança. Além de direcionar jovens cavaleiros para o combate na linha de frente contra o Flagelo em Lordaeron, ele organiza a sagrada cadeia de missões rituais necessária para forjar a barda sagrada e reivindicar um corcel de paladino.",al={"o que grayson faz","propósito de grayson quebrassombra","por que visitar o lorde grayson"}},{q="O Lorde Grayson perdeu um olho?",a="Nenhum relato dos dias de hoje conta como, ou mesmo se, Grayson perdeu um olho. Ele é conhecido simplesmente como um lorde veterano do Punho de Prata e um dos principais paladinos da Aliança.",al={"como grayson perdeu o olho","por que grayson não tem um olho","tapa-olho de grayson"}},{q="Qual é a sua ligação com os Renegados?",a="Nenhuma conhecida. Grayson é um paladino do Punho de Prata que envia seus cavaleiros para combater o Flagelo em Lordaeron, e nenhum relato dos dias de hoje o vincula ou vincula sua família aos Renegados.",al={"irmã de grayson","grayson tem família morta-viva"}},{q="Por que Grayson envia paladinos a Grimand Elmore?",a="Grimand Elmore forjou a barda do próprio corcel de Grayson anos atrás. Como um corcel sagrado exige um trabalho artesanal impecável que equilibre a resistência física com a harmonia espiritual, Grayson envia todos os iniciados dignos a Grimand para forjar sua Barda de Arcanita.",al={"grayson e grimand elmore","quem faz a barda de paladino","missão da barda de arcanita"}}},fx={["2db8c97e"]={q="De que lado está Lorde Grayson Quebrassombra?",a="Lorde Grayson permanece firmemente com a Grande Aliança, o reino de Ventobravo e a Ordem do Punho de Prata. Ele é dedicado completamente à Luz Sagrada e à defesa dos vivos contra o Flagelo e outras ameaças sombrias.",al={"facção de grayson quebrassombra","a quem grayson serve","o grayson é aliança"}},["88e74201"]={q="O que Lorde Grayson Quebrassombra quer?",a="Lorde Grayson busca forjar a próxima geração de guerreiros sagrados para repelir a escuridão que consome Azeroth. Ele testa paladinos através de árduos julgamentos espirituais e marciais, enviando-os para lutar contra o Flagelo nas Terras Pestilentas e provando seu valor para ganhar um corcel abençoado.",al={"objetivos de grayson quebrassombra","o que grayson quer","motivo de grayson"}},a5a2c568={q="Por que Lorde Grayson Quebrassombra está na Catedral da Luz?",a="Ele está posicionado dentro da Catedral da Luz de Ventobravo para supervisionar o desenvolvimento dos paladinos da cidade. Deste bastião central de fé, ele coordena missões contra o Flagelo e guia campeões seniores através dos exigentes julgamentos necessários para convocar seus cavalos de guerra sagrados.",al={"por que grayson está em ventobravo","por que grayson está aqui","grayson catedral da luz"}},c41cec02={q="A quem o Lorde Grayson Quebrassombra está ligado?",a="Grayson trabalha em estreita colaboração com o Sumo Sacerdote Rohan de Altaforja, com o ferreiro Grimand Elmore e com comandantes que lutam contra o Flagelo no norte, como Ashlam Valorfist.",al={"aliados de grayson quebrassombra","quem grayson conhece","escudeiros de grayson"}},["70324968"]={q="Quem é Lorde Grayson Quebrassombra?",a="Lorde Grayson Quebrassombra é um dos principais paladinos de Ventobravo e da Aliança. Um veterano calejado de batalha dos Knights of the Silver Hand, ele serve como um mestre veterano da ordem sagrada, treinando e guiando cavaleiros promissores nos caminhos da Luz.",al={"quem é grayson quebrassombra","quem é lorde grayson","sobre grayson quebrassombra"}}},fp="26,321,25.451.0,30.494.1,44.193.0,41.263.0,29.175.0,39.187.0,49.261.0"}
P.entries["npc:lord-jorach-ravenholdt"] = {n="Lorde Jorach Corvoforte",s="Lorde Jorach Corvoforte é o mestre de Corvoforte, uma guilda de elite de ladinos e assassinos que opera a partir de uma propriedade isolada nas Montanhas de Alterac. Ele lidera as operações clandestinas da liga, treinando agentes promissores enquanto trava uma guerra ferrenha contra os bandidos regionais da Camarilha.",h="Lorde Jorach Corvoforte é o mestre de Corvoforte, uma guilda de elite de ladinos e assassinos que opera a...",kw={"alterac","liga dos assassinos","chave lazúli","jorach","corvoforte","ladino","camarilha","tauriel"},ang={["class:Rogue"]="Lorde Corvoforte é o principal patrono dos mestres ladinos por toda Azeroth, oferecendo treinamento de elite, venenos e contratos prestigiados àqueles que conquistam sua confiança."},sec={{t="Mestre da Liga dos Assassinos",b="Lorde Jorach Corvoforte comanda a Liga dos Assassinos a partir de sua mansão oculta, situada nos penhascos entre Alterac e Eira dos Montes. Um nobre de linhagem misteriosa, ele abre seus salões para foras da lei, batedores de carteira e assassinos, independentemente de lealdade, contanto que demonstrem perícia excepcional e respeitem sua autoridade. Sob seu comando, a liga atua tanto como uma irmandade para mestres ladrões quanto como um sindicato independente para trabalho sujo e espionagem. Corvoforte nutre um ódio feroz pela Camarilha — o bando de nobres caídos em desgraça de Alterac que viraram foras da lei — e frequentemente orienta seus subordinados e mercenários visitantes a sabotarem seus acampamentos e saquearem seus bens."},{t="Segredos nas Sombras",b="Embora ostensivamente preocupado com escaramuças locais, Lorde Corvoforte comanda operações de grande alcance por toda Azeroth. Ladinos que provam sua lealdade são recrutados para missões complexas que cobrem continentes inteiros para recuperar artefatos guardados. Entre elas estava a recuperação de um misterioso Saco Lazúli Lacrado, roubado dele e levado para fúrbolgs em Azshara, o que exigiu a decodificação arcana do Arquimago Tauriel e uma Chave Lazúli arrancada do Templo Submerso. Corvoforte também coordena o desenvolvimento de novos compostos letais, enviando seus batedores para coletar venenos mortais de horrores ancestrais por todo o reino."}},faq={{q="Quem é Lorde Jorach Corvoforte?",a="Ele é o líder aristocrático da Liga dos Assassinos, uma sociedade secreta de ladinos sediada na Mansão de Corvoforte, nas montanhas acima do Contraforte de Eira dos Montes. Ele treina mestres de operações furtivas e coordena assassinatos discretos e coleta de informações.",al={"quem é jorach","líder de corvoforte","história de jorach"}},{q="Por que Corvoforte odeia a Camarilha?",a="A propriedade de Corvoforte fica diretamente em território disputado pela Camarilha, uma rede de antigos nobres de Alterac que se tornaram foras da lei implacáveis. Ele vê o banditismo tosco deles como uma praga pelas terras altas e usa os assassinos de sua guilda para expurgar ativamente suas fortalezas.",al={"por que camarilha é inimigo","corvoforte vs camarilha","rivalidade com a camarilha"}},{q="Lorde Corvoforte é afiliado à Aliança ou à Horda?",a="Corvoforte opera estritamente como uma organização independente. Lorde Jorach aceita ladinos tanto da Aliança quanto da Horda em sua mansão, importando-se apenas com a destreza profissional, a disciplina furtiva e a discrição absoluta, em vez de políticas raciais.",al={"corvoforte é aliança","jorach é horda","facção de corvoforte"}},{q="O que há dentro do Saco Lazúli Lacrado que Jorach procura?",a="O conteúdo permanece um segredo profundamente guardado. Ao receber a Chave Lazúli para finalmente abrir a bolsa encantada, Lorde Jorach foi banhado por uma estranha luz dourada, olhando para dentro com espanto antes de guardá-la rapidamente.",al={"conteúdo do saco lazúli lacrado","mistério do saco lazúli","o que jorach conseguiu"}}},fp="22,302,31.670.0,22.600.1,30.264.0,39.273.0,57.249.0,49.237.1"}
P.entries["npc:lord-maxwell-tyrosus"] = {n="Lorde Maximiliano Tyrosus",s="Lorde Maximiliano Tyrosus é o comandante supremo da Aurora Argêntea, aquartelado em seu reduto avançado na Capela Esperança da Luz, nas Terras Pestilentas Orientais. Um paladino veterano do Punho de Prata da Terceira Guerra, ele lidera a cruzada da coalizão contra o Flagelo e orquestra ataques a fortalezas assoladas como Stratholme.",h="Lorde Maximiliano Tyrosus é o comandante supremo da Aurora Argêntea, aquartelado em seu reduto avançado na...",kw={"aurora argêntea","capela esperança da luz","paladino","flagelo","punho de prata","stratholme","tyrosus"},ang={["class:Paladin"]="Tyrosus representa o espírito inabalável do Punho de Prata, preservando as virtudes da compaixão, unidade e disciplina após a morte de Uther e a trágica corrupção das facções dissidentes da ordem.",["faction:Alliance"]="Embora tenha nascido nobre de Lordaeron e herói da Aliança, Tyrosus agora dedica suas forças a uma ordem independente que acolhe qualquer um disposto a combater o Flagelo.",["faction:Horde"]="Ao contrário dos fanáticos de Amparo e do Monastério Escarlate, Tyrosus há muito defende a cooperação com não humanos, assegurando que guerreiros e xamãs da Horda sejam aceitos como iguais na Capela Esperança da Luz."},sec={{t="Um Veterano de Lordaeron",b="Maximiliano Tyrosus cavalgou ao lado de Uther, o Arauto da Luz durante a catastrófica Terceira Guerra, vigiando as saídas de Andorhal quando o Flagelo assolou o reino. Após a queda de Lordaeron, uniu seu destino à Aurora Argêntea, uma ordem que acolhe qualquer um disposto a resistir ao Flagelo, em nítido contraste com o fanatismo exclusivo para humanos da Cruzada Escarlate."},{t="Comandante da Aurora",b="Tyrosus agora lidera a Aurora Argêntea e supervisiona as defesas da Capela Esperança da Luz. De seu posto de comando no interior da capela, ele coordena amplas operações militares pelas Terras Pestilentas, incluindo investidas táticas lideradas pelo Duque Nicholas Zverenhoff contra o Barão Rivendare dentro das ruínas de Stratholme."}},faq={{q="Quem é Lorde Maximiliano Tyrosus?",a="Lorde Maximiliano Tyrosus é um experiente paladino humano e líder supremo da Aurora Argêntea. Tendo lutado sob o comando de Uther, o Arauto da Luz durante a Terceira Guerra, ele agora comanda a defesa da Capela Esperança da Luz e dirige a campanha da coalizão para purificar as Terras Pestilentas.",al={"quem é maxwell tyrosus","história de tyrosus","líder da aurora argêntea","chefe da aurora argêntea"}},{q="Por que Tyrosus deixou a Cruzada Escarlate?",a="Nenhum registro coloca Tyrosus entre os membros da Cruzada Escarlate. Ele lidera a Aurora Argêntea, uma ordem que aceita qualquer raça disposta a combater o Flagelo, enquanto os fanáticos da Cruzada não confiam em ninguém que não seja humano e puro de fé.",al={"por que tyrosus deixou a cruzada escarlate","tyrosus cruzada escarlate","tyrosus é da cruzada escarlate"}},{q="Onde Maximiliano Tyrosus pode ser encontrado?",a="Ele se encontra no interior do santuário da Capela Esperança da Luz, a fortaleza fortificada da Aurora Argêntea situada nos confins orientais das Terras Pestilentas Orientais.",al={"localização de tyrosus","onde fica maxwell tyrosus","mapa de tyrosus"}},{q="Qual é o papel de Tyrosus na guerra contra Stratholme?",a="Tyrosus coordena uma ampla estratégia militar com o Duque Nicholas Zverenhoff, encarregando aventureiros comprovados e grupos de ataque de invadir a cidade caída de Stratholme e eliminar o Barão Rivendare, o comandante do Lich Rei na região.",al={"tyrosus stratholme","tyrosus rivendare"}},{q="Tyrosus concede audiência a qualquer pessoa?",a="Tyrosus raramente concede audiências a forasteiros, tendo passado anos recluso em conselhos de guerra direcionando os esforços no fronte. Os aventureiros normalmente precisam conquistar o profundo respeito da Aurora Argêntea ou apresentar relatórios cruciais de inteligência para obter sua atenção.",al={"posso falar com tyrosus","audiência com tyrosus"}}},fp="20,330,22.366.0,21.302.0,28.271.0,42.215.0,35.161.0,53.230.0,43.245.0"}
P.entries["npc:lord-pythas"] = {n="Lorde Pítias",s="Lorde Pítias, outrora um guerreiro elfo noturno, é um dos quatro líderes corrompidos dos Druidas da Presa na Caverna Ululante. Originalmente um dos guardas pessoais do druida Naralex, ele foi vítima do pesadelo que corrompeu o oásis subterrâneo. Agora ele empunha tanto o poderio marcial quanto a magia serpenteante distorcida contra qualquer um que tente alcançar seu mestre adormecido.",h="Lorde Pítias, outrora um guerreiro elfo noturno, é um dos quatro líderes corrompidos dos Druidas da Presa na...",kw={"druidas da presa","gema de pítias","leaders of the fang","lorde pítias","naralex","pítias","caverna ululante"},ang={["class:Druid"]="Pítias representa o destino trágico de um acólito promissor que abraçou a magia da natureza por devoção, apenas para ter os ensinamentos distorcidos em uma heresia viperina pela corrupção do Sonho Esmeralda.",["class:Warrior"]="Antes de ser corrompido em um cultista serpente, Pítias era um disciplinado guerreiro elfo noturno e protetor pessoal — um lembrete sombrio de que a proeza marcial por si só não pode conter a loucura mental.",["race:NightElf"]="Ver um protetor respeitado como Pítias sucumbir à loucura sombria é uma tristeza amarga para qualquer elfo noturno que busca restaurar o equilíbrio aos solos marcados de Kalimdor."},sec={{t="A Queda de um Guardião",b="Antes de sua corrupção, Pítias era um experiente guerreiro elfo noturno que servia na guarda pessoal do druida Naralex quando a expedição se aventurou pelos ermos secos dos Sertões. Ao lado de seu treinamento marcial, ele adotou as artes druídicas a serviço do sonho de Naralex de restaurar a vida exuberante ao reino árido. No entanto, a disciplina física e a bravura marcial não ofereceram abrigo contra a insidiosa corrupção à espreita nas profundezas das fissuras subterrâneas."},{t="O Sentinela Letal",b="Quando a conexão de Naralex com o Sonho Esmeralda foi usurpada por pesadelos sombrios, a mente de Pítias sucumbiu junto com a de seus companheiros acólitos. Abandonando sua antiga lealdade, ele se tornou um dos líderes dos Druidas da Presa. Enquanto seus companheiros lordes serpentes favorecem lançamentos de feitiços astutos ou formas de feras, Pítias mescla perfeitamente uma destreza de combate letal com magia da natureza. Agora ele ronda os túneis sinuosos das cavernas, determinado a defender o domínio distorcido do pesadelo sobre a nascente da caverna."}},faq={{q="Quem é Lorde Pítias?",a="Lorde Pítias era originalmente um guerreiro elfo noturno que servia como um dos guardas pessoais de Naralex e também estudava o druidismo para auxiliar o trabalho de seu mestre nos Sertões.",al={"quem é pítias","história do lorde pítias"}},{q="Por que ele se voltou contra Naralex?",a="Pítias não traiu Naralex por vontade própria. Quando Naralex tentou se conectar ao Sonho Esmeralda para curar os Sertões, um pesadelo tomou conta dos pensamentos do arquidruida. O sonho corruptor infiltrou-se nas mentes de seus acólitos, despojando Pítias de sua sanidade e transformando-o em um lorde serpente.",al={"por que pítias é mau","como pítias enlouqueceu","por que ele se tornou um druida da presa"}},{q="O que torna Pítias diferente dos outros líderes da Presa?",a="Ao contrário dos outros líderes, que dependem puramente de magia da natureza e formas de feras, Pítias era um guerreiro experiente antes de treinar como druida. Ele combina habilidades de combate marcial com magia druídica, tornando-se um dos defensores fisicamente mais formidáveis nas cavernas.",al={"estilo de combate de pítias","pítias versus outros líderes"}},{q="Por que os aventureiros precisam derrotá-lo?",a="Pítias carrega uma das quatro gemas encantadas necessárias para completar a missão Leaders of the Fang. A missão é concedida pela druida Nara Wildmane em Penhasco do Trovão, que exige as gemas de todos os quatro líderes da Presa para libertar os Sertões de seus sonhos distorcidos.",al={"missão leaders of the fang","gema de pítias"}},{q="Onde Lorde Pítias pode ser encontrado?",a="Lorde Pítias espreita nas câmaras interiores profundas da Caverna Ululante, cercado por feras corrompidas e outros cultistas da Presa.",al={"localização de pítias","onde fica pítias"}},{q="O que acontece com a gema dele?",a="Após sua derrota, a Gema de Pítias é recuperada de seus restos mortais. Os aventureiros a levam, junto com as gemas dos outros três lordes serpentes, para Nara Wildmane em Penhasco do Trovão para provar que a liderança da Presa foi derrotada.",al={"uso da gema de pítias","o que é a gema de pítias"}}},fx={be91010a={q="De que lado está o Lorde Pítias?",a="O Lorde Pítias serve aos Druidas da Presa. Outrora um devoto protetor e acólito de Naralex, o pesadelo tomou conta de sua mente e corrompeu sua lealdade. Agora, ele está totalmente alinhado com a seita renegada, empunhando sua lâmina e magia da natureza para proteger o pesadelo em vez de defender o mestre que jurou proteger.",al={"facção de pítias","pítias aliança","quem pítias serve"}},a058df7c={q="O que o Lorde Pítias quer?",a="Enlouquecido pelo pesadelo que infecta o sono de Naralex, Pítias busca defender a Caverna Ululante de qualquer pessoa que tente purificá-la. Despojado de sua sanidade, ele deseja apenas derrotar os intrusos que ameaçam o domínio do pesadelo, voltando sua disciplina marcial e poder druídico inteiramente para preservar o domínio corrompido.",al={"objetivos de pítias","o que pítias está tentando fazer","motivo de pítias"}},eb0bbb13={q="Por que o Lorde Pítias é temido?",a="O Lorde Pítias é considerado o mais formidável dos Leaders of the Fang. Ao contrário de muitos acólitos que confiam apenas em feitiços da natureza, Pítias era um guerreiro experiente antes de adotar o druidismo. Sua combinação de destreza letal em combate corpo a corpo, pura resiliência física e magia druídica sombria o torna excepcionalmente letal para qualquer expedição.",al={"pítias é perigoso","por que pítias é durão","força de pítias"}},d8d94386={q="Por que Lorde Pítias está na Caverna Ululante?",a="Pítias viajou originalmente para as cavernas como um dos guardas pessoais de Naralex durante o esforço para restaurar os Sertões. Quando o transe de Naralex se transformou em um pesadelo inescapável, Pítias sucumbiu ao lado dos outros discípulos, permanecendo nas profundezas das cavernas como um guardião corrompido da Presa.",al={"por que pítias está na caverna ululante","razão da localização de pítias","como pítias chegou aqui"}},d87430fd={q="A quem Lorde Pítias está ligado?",a="Antes de sua descida à loucura, Pítias era um dos guardas pessoais do druida Naralex. Ele viajou para as nascentes subterrâneas para manter Naralex seguro enquanto aprendia o druidismo, embora a corrupção generalizada tenha destruído sua mente e o tenha vinculado aos demais Leaders of the Fang corrompidos.",al={"pítias naralex","conexões de pítias","quem pítias conhece"}}},fp="11,360,16.457.0,19.492.0,19.163.0,32.288.0,56.259.0,38.253.0,31.132.0,24.228.0"}
P.entries["npc:lord-serpentis"] = {n="Lorde Serpentis",s="Lorde Serpentis é um druida elfo noturno corrompido que se destaca como um dos quatro líderes dos rebeldes Druidas da Presa dentro da Caverna Ululante. Outrora um druida de grande poder e prestígio na ordem de Naralex, ele foi distorcido pela loucura quando o sonho de Naralex se transformou em um pesadelo dentro das fontes subterrâneas. Agora, ele ajuda a comandar a seita que adora serpentes nas profundezas das cavernas, onde o corrompido Naralex jaz adormecido.",h="Lorde Serpentis é um druida elfo noturno corrompido que se destaca como um dos quatro líderes dos rebeldes...",kw={"druidas da presa","gema de serpentis","líderes da presa","lorde serpentis","naralex","serpentis","caverna ululante"},ang={["class:Druid"]="Serpentis representa o perigo trágico que espreita dentro do Sonho Esmeralda, mostrando como até mesmo um druida de grande poder pode ser distorcido quando uma visão nobre se transforma em pesadelo.",["race:NightElf"]="Para os elfos noturnos, Serpentis e seus seguidores são uma vergonha dolorosa: eruditos kaldorei de grande renome que jogaram fora seu dever sagrado para com a natureza para se tornarem monstruosos senhores das serpentes.",["race:Tauren"]="Os taurens veem a corrupção de Serpentis como uma profanação terrível do equilíbrio da Mãe Terra, ameaçando o frágil ecossistema dos Sertões com uma loucura antinatural."},sec={{t="De Druida Nobre a Senhor das Serpentes",b="Antes que a escuridão tomasse as fontes da caverna, Serpentis era um druida de grande poder e prestígio, membro da nobre ordem liderada por Naralex que esperava usar as fontes das cavernas e o Sonho Esmeralda para curar os Sertões. No entanto, quando a visão de Naralex se transformou em um pesadelo corruptor, Serpentis foi um dos druidas cujas mentes sucumbiram à loucura emergente."},{t="Um Senhor da Presa",b="Sucumbindo completamente à corrupção que irradiava dos sonhos distorcidos de Naralex, Serpentis e seus companheiros druidas se tornaram os Druidas da Presa. Abandonando o equilíbrio cenariano tradicional e os animais totêmicos do passado, eles agora buscam remodelar os Sertões para corresponder aos seus próprios sonhos distorcidos, em vez de curá-los. Serpentis governa a seita como um de seus quatro líderes, ao lado de Lady Sucurina, Lorde Cobrahn e Lorde Pítias."},{t="O Obstáculo Final",b="Instalado nas profundezas das cavernas tortuosas, Lorde Serpentis é um dos quatro líderes da seita renegada, cada um dos quais carrega uma gema do sonho. Aqueles que buscam despertar o mestre aprisionado ou recuperar as águas do Oásis devem abater Serpentis e reivindicar a gema que ele carrega, quebrando o domínio da serpente sobre o labirinto."}},faq={{q="Quem é Lorde Serpentis?",a="Lorde Serpentis é um dos quatro líderes dos Druidas da Presa, localizado nas profundezas da Caverna Ululante. Outrora um druida elfo noturno de grande poder e prestígio na ordem de Naralex, ele foi corrompido pelo pesadelo de Naralex junto com seus companheiros druidas.",al={"quem é serpentis","história de lorde serpentis","origem de serpentis"}},{q="Por que Serpentis se tornou maligno?",a="Quando a tentativa de Naralex de curar os Sertões através do Sonho Esmeralda se transformou em um pesadelo, sua corrupção se espalhou para os druidas que o seguiam, levando a mente de Serpentis à loucura e à adoração de serpentes.",al={"por que serpentis mudou de lado","corrupção de serpentis","por que serpentis é mau"}},{q="Qual é a relação dele com Naralex?",a="Serpentis já foi um dos nobres druidas que seguiram Naralex até as cavernas. Em vez de ajudar na recuperação de seu mestre, ele se tornou um líder dos Druidas da Presa, que agora buscam remodelar os Sertões para corresponder aos seus próprios sonhos distorcidos.",al={"serpentis e naralex","serpentis é parente de naralex","aprendiz de naralex"}},{q="Por que os jogadores precisam matá-lo?",a="Serpentis é um dos quatro líderes dos Druidas da Presa. Eliminá-lo é essencial para quebrar o domínio da seita sobre a Caverna Ululante, obter sua gema para a missão Líderes da Presa e abrir caminho para despertar Naralex.",al={"por que matar serpentis","líderes da presa serpentis","gema de serpentis"}},{q="Quem são os Druidas da Presa?",a="Eles são uma facção renegada de druidas elfos noturnos que seguiram Naralex até a Caverna Ululante. Corrompidos pelo Pesadelo Esmeralda, abandonaram as formas druídicas tradicionais para adotar os aspectos, venenos e comportamentos das serpentes sob o comando de Serpentis e de seus outros senhores da presa.",al={"história dos druidas da presa","o que são os druidas da presa","druidas da presa"}}},fx={["1f07cf4d"]={q="De que lado está o Lorde Serpentis?",a="O Lorde Serpentis é o líder dos Druidas da Presa. Corrompido pelo pesadelo que consome seu mentor Naralex, ele abandonou o Círculo Cenariano e os ideais dos elfos noturnos, tornando-se totalmente hostil a todos que entram nas cavernas.",al={"facção de lorde serpentis","quem serpentis serve","lealdade de serpentis"}}},fp="14,426,32.350.0,18.412.0,18.316.1,22.250.0,28.208.0,36.242.0,32.234.0,31.285.0"}
P.entries["npc:lord-shalzaru"] = {n="Lorde Shalzaru",s="Lorde Shalzaru é o líder tirânico dos nagas Hatecrest que operam a partir da Ilha do Medo, na costa de Feralas. Governando seus seguidores serpentinos com absoluta crueldade, ele supervisiona extensas escavações entre os assentamentos élficos submersos e em ruínas. Sua recente descoberta de uma relíquia antiga e estranha chamou a atenção de investigadores externos ansiosos por arrancá-la de seu alcance.",h="Lorde Shalzaru é o líder tirânico dos nagas Hatecrest que operam a partir da Ilha do Medo, na costa de...",kw={"feralas","hatecrest","ilha do medo","lorde shalzaru","relíquia misteriosa","naga","shalzaru"},ang={["faction:Alliance"]="Proteger a relíquia de Shalzaru e neutralizar o senhor da guerra Hatecrest ajuda a resguardar os postos avançados remotos da Aliança na costa selvagem de Feralas.",["faction:Horde"]="Batedores da Horda mantêm um olho vigilante sobre as ameaças costeiras em Feralas, e abater o senhor naga remove um perigo imprevisível próximo à esfera de interesse da Aldeia Mojache.",["race:NightElf"]="Os nagas Hatecrest violam as ruínas antigas da antiga Kalimdor; recuperar relíquias de Shalzaru impede que o legado sombrio dos Altaneiros fortaleça seus parentes serpentinos."},sec={{t="Mestre dos Hatecrest",b="Lorde Shalzaru comanda os nagas Hatecrest, direcionando sua presença ao longo da costa sul de Feralas. De seu covil subterrâneo dentro de uma caverna na Ilha do Medo, ele impõe seu domínio por meio de crueldade e autoridade implacável. Sob seu comando, os Hatecrest vasculham as ruínas antigas da antiga Kalimdor, em busca de tesouros esquecidos e relíquias poderosas deixadas para trás pela Cisão."},{t="A Relíquia Misteriosa",b="Durante escavações ao sul das ruínas principais na Ilha do Medo, Shalzaru descobriu pessoalmente uma relíquia antiga e estranha. O propósito e o poder deste artefato permanecem um mistério, mas sua recuperação por um senhor da guerra naga tão poderoso representa uma ameaça clara. Agentes no continente procuram campeões corajosos para se aventurarem no covil da serpente, pôr fim ao comando de Shalzaru e proteger a estranha relíquia antes que os Hatecrest possam usá-la para fins mais sombrios."}},faq={{q="Quem é Lorde Shalzaru?",a="Lorde Shalzaru é o cruel líder real dos nagas Hatecrest. Ele supervisiona as forças nagas e as escavações na Ilha do Medo, situada na costa de Feralas.",al={"história de lorde shalzaru","shalzaru","quem é shalzaru"}},{q="Onde Lorde Shalzaru pode ser encontrado?",a="Ele habita em uma caverna localizada ao sul das principais ruínas élficas através das águas na Ilha do Medo, na costa sudoeste de Feralas.",al={"localização de shalzaru","onde fica lorde shalzaru","caverna da ilha do medo"}},{q="O que são os Hatecrest?",a="Os Hatecrest são uma tribo hostil de nagas que ocupa o litoral e as ilhas de Feralas, conhecidos por vasculhar ruínas antigas e aterrorizar as águas costeiras sob o comando de Shalzaru.",al={"nagas hatecrest","tribo hatecrest"}},{q="Qual relíquia Lorde Shalzaru possui?",a="Durante uma escavação recente na Ilha do Medo, Shalzaru descobriu uma relíquia misteriosa e antiga de origem e poder desconhecidos, levando facções do continente a enviar aventureiros para reivindicá-la.",al={"relíquia de shalzaru","relíquia misteriosa feralas"}},{q="Por que Lorde Shalzaru deve ser derrotado?",a="Eliminar Shalzaru quebra a liderança dos Hatecrest na Ilha do Medo e permite que os aventureiros recuperem a relíquia misteriosa que ele escavou recentemente antes que os nagas possam aproveitá-la.",al={"contra lorde shalzaru","matar lorde shalzaru"}},{q="O que os Hatecrest estão procurando em Feralas?",a="Os Hatecrest escavam os assentamentos arruinados dos Elfos Noturnos despedaçados durante a Grande Cisão, procurando relíquias mágicas poderosas e vestígios da história dos Altaneiros escondidos sob o solo e as ondas.",al={"escavação hatecrest","por que há nagas em feralas"}}},fp="13,392,23.394.0,20.439.0,21.159.0,33.135.0,22.183.0,38.189.0,35.182.0,46.194.0"}
P.entries["npc:lorekeeper-raintotem"] = {n="Erudito Totem da Chuva",s="O Erudito Totem da Chuva é um ancião tauren posicionado no norte de Mulgore, logo ao sul do Rochedo Vermelho. Ele cuida dos cemitérios sagrados e pede aos aventureiros que expulsem os javalins Espinhaventa que os estão perturbando.",h="O Erudito Totem da Chuva é um ancião tauren posicionado no norte de Mulgore, logo ao sul do Rochedo Vermelho.",kw={"erudito totem da chuva","mulgore","totem da chuva","rochedo vermelho","enterro sagrado"},ang={["class:Shaman"]="A vigilância do Totem da Chuva sobre os mortos inquietos no Rochedo Vermelho diz respeito diretamente ao dever xamânico, garantindo que os espíritos ancestrais recebam a paz e a reverência adequadas.",["race:Tauren"]="Ajudar o Totem da Chuva a defender o Rochedo Vermelho honra os ancestrais e preserva as tradições funerárias do seu povo."},sec={{t="Sentinela do Rochedo Vermelho",b="Posicionado perto das falésias sagradas do Rochedo Vermelho em Mulgore, o Erudito Totem da Chuva cuida das obrigações espirituais de seu povo. Ele pede aos aventureiros que expulsem os Intrusos Espinhaventa do cemitério, restaurando a paz ao local de descanso dos ancestrais."},{t="Defensor dos Terrenos Ancestrais",b="Além de testar heróis iniciantes, o Erudito Totem da Chuva vigia os cemitérios sagrados no Rochedo Vermelho. Quando os intrusos javalins Espinhaventa perturbam os locais de descanso santificados de chefes e xamãs tauren falecidos, Totem da Chuva recruta viajantes para restaurar a dignidade e acalmar os mortos perturbados."}},faq={{q="Onde posso encontrar o Erudito Totem da Chuva?",a="O Erudito Totem da Chuva está posicionado no norte de Mulgore, localizado logo ao sul do Rochedo Vermelho, ao longo do caminho que sobe em direção às falésias ancestrais.",al={"localização de totem da chuva","onde fica o erudito totem da chuva","encontrar totem da chuva mulgore"}},{q="Por que o Totem da Chuva pede ajuda com os cemitérios?",a="Ele pede aos aventureiros que expulsem os Intrusos Espinhaventa do Rochedo Vermelho, onde os javalins estão devastando o cemitério sagrado tauren.",al={"totem da chuva enterro sagrado","por que ajudar o totem da chuva","cemitérios do rochedo vermelho"}},{q="Por que o Totem da Chuva precisa de ajuda no Rochedo Vermelho?",a="O Rochedo Vermelho serve como um cemitério sagrado tauren, mas intrusos javalins Espinhaventa estão devastando o local da sepultura. Totem da Chuva encarrega aventureiros capazes de colocar os terrenos ancestrais desonrados de volta em ordem.",al={"problema do rochedo vermelho","por que missão de enterro sagrado"}}},fx={["4ada6d87"]={q="Quem é o Erudito Totem da Chuva?",a="O Erudito Totem da Chuva serve sua comunidade tauren, preservando tradições ancestrais e garantindo que os caídos recebam sepultamento sagrado.",al={"quem é totem da chuva","informações sobre o erudito totem da chuva","sobre totem da chuva"}},["29f679b7"]={q="De que lado está o Erudito Totem da Chuva?",a="O Erudito Totem da Chuva é totalmente leal às tribos tauren de Mulgore e à Horda sob o Alto Chefe Caerne Casco Sangrento. Ele serve como um honrado ancião cultural, auxiliando qualquer aventureiro da Horda que demonstre respeito aos ritos sagrados e aos ancestrais de seu povo.",al={"facção de totem da chuva","totem da chuva é horda","lealdade de totem da chuva"}},["6a12fd3c"]={q="Por que o Erudito Totem da Chuva está aqui?",a="Totem da Chuva mantém vigilância ao sul do Rochedo Vermelho porque este é o cemitério ancestral sagrado das tribos tauren. Ele permanece estacionado nas proximidades para proteger o solo sagrado, guiar peregrinos que buscam bênçãos ancestrais e enfrentar ameaças que perturbam os espíritos que descansam dentro dos penhascos de pedra vermelha.",al={"por que totem da chuva está no rochedo vermelho","motivo da localização de totem da chuva","por que o erudito totem da chuva está em mulgore"}},["88640b34"]={q="O que o Erudito Totem da Chuva quer?",a="Ele cuida do cemitério ancestral no Rochedo Vermelho e pede aos aventureiros que expulsem os Intrusos Javali que os estão perturbando.",al={"o que totem da chuva quer","objetivos de totem da chuva","o que totem da chuva está pedindo"}}},fp="20,207,20.255.0,29.302.0,38.141.0,53.133.0,42.213.0"}
P.entries["npc:lorgus-jett"] = {n="Lorgus Jett",s="Lorgus Jett é um membro humano do Martelo do Crepúsculo que opera nos corredores inundados das Profundezas Negras. Vagando pelas Moonshrine Ruins, ele atua como um comandante implacável a serviço dos Deuses Antigos. Os líderes da Horda o escolheram como alvo principal para interromper a presença invasora do culto ao longo da costa do Vale Gris.",h="Lorgus Jett é um membro humano do Martelo do Crepúsculo que opera nos corredores inundados das Profundezas...",kw={"allegiance to the old gods","profundezas negras","lorgus jett","moonshrine ruins","martelo do crepúsculo"},ang={["class:Shaman"]="Jett comanda os elementos não em harmonia ou reverência, mas através dos métodos corrompidos e violentos ensinados pelo Martelo do Crepúsculo.",["faction:Horde"]="Abater Lorgus Jett cumpre um pedido urgente para interromper a liderança do Martelo do Crepúsculo que prolifera sob a costa do Vale Gris.",["race:Human"]="Ver um humano tão a oeste em Kalimdor servindo a terrores cósmicos é um lembrete arrepiante de quão longe chegou a corrupção do Martelo do Crepúsculo."},sec={{t="Um Profanador nas Ruínas",b="Embora muitos membros do Martelo do Crepúsculo operando sob as Profundezas Negras venham de linhagens órcicas ou taurens, Lorgus Jett se destaca como um humano nas profundezas de antigas ruínas de elfos noturnos. Vagando por qualquer lugar entre as Moonshrine Ruins superiores e os túneis cavernosos além do profanador murloc Gelihast, Jett coordena os rituais sombrios e as ambições violentas do culto."}},faq={{q="Quem é Lorgus Jett?",a="Lorgus Jett é um agente humano do Martelo do Crepúsculo posicionado dentro das Profundezas Negras. Ele supervisiona as atividades do culto dentro das Moonshrine Ruins e serve aos Deuses Antigos.",al={"história de lorgus jett","quem é lorgus","passado de lorgus jett"}},{q="Onde Lorgus Jett pode ser encontrado nas Profundezas Negras?",a="Lorgus Jett tem uma área de patrulha variável dentro das Moonshrine Ruins. Ele pode aparecer perto dos primeiros grupos de cultistas do Crepúsculo ou mais adiante nas passagens inundadas logo após o santuário de Gelihast.",al={"localização de lorgus jett","onde fica lorgus jett","encontrar lorgus jett"}},{q="Por que a Horda quer Lorgus Jett morto?",a="A Horda busca sua morte através da missão \\\"Allegiance to the Old Gods\\\". Sua presença no Vale Gris ameaça a estabilidade regional e representa uma aliança insidiosa dedicada a libertar entidades ancestrais que trarão o fim do mundo.",al={"por que matar lorgus","missão allegiance to the old gods"}},{q="Por que um humano usa poderes xamânicos?",a="O Martelo do Crepúsculo comunga diretamente com forças elementais caóticas e Deuses Antigos em vez dos espíritos ancestrais tradicionais, permitindo que raças não tradicionais, como os humanos, utilizem a devastação elemental.",al={"magia de lorgus jett","xamã humano lorgus"}},{q="Qual é a conexão de Lorgus Jett com Gelihast?",a="Ambos habitam as Moonshrine Ruins nas Profundezas Negras, unidos na servidão aos poderes sombrios que dormem sob o mar, com Jett patrulhando frequentemente os corredores além do altar de Gelihast.",al={"lorgus e gelihast","conexão com gelihast"}}},fx={["647bfdae"]={q="De que lado está Lorgus Jett?",a="Lorgus Jett serve ao Martelo do Crepúsculo, o culto apocalíptico dedicado aos Deuses Antigos. Embora seja um humano, ele abandonou seu povo para se alinhar aos ritualistas sombrios e forças elementais que se congregam nas profundezas esquecidas do Vale Gris.",al={"facção de lorgus jett","quem lorgus jett serve","qual a facção de lorgus jett"}},ba0235c4={q="Por que Lorgus Jett está nas Profundezas Negras?",a="Ele espreita dentro das Moonshrine Ruins subterrâneas ao lado de seus companheiros cultistas, cumprindo a vontade do Martelo do Crepúsculo. Nas profundezas do antigo templo élfico, o culto cuida de horrores sombrios e venera os poderes ancestrais que se agitam sob as águas.",al={"por que lorgus jett está nas profundezas negras","propósito de lorgus jett nas profundezas negras","por que lorgus jett está aqui"}}},fp="11,350,22.373.0,19.179.0,52.199.0,41.223.0,40.200.0,45.198.0"}
P.entries["npc:loslor-rudge"] = {n="Loslor Rudge",s="Loslor Rudge é um empreendedor fornecedor de engenharia anão baseado na Garagem do Gradaço, em Dun Morogh. Ele fornece peças mecânicas, ferramentas e munições para engenhoqueiros por todas as cristas montanhosas nevadas, mantendo conexões cruciais com armeiros como Hegnar Estremetiro.",h="Loslor Rudge é um empreendedor fornecedor de engenharia anão baseado na Garagem do Gradaço, em Dun Morogh.",kw={"munição","dun morogh","engenharia","covil cinzento","hegnar estremetiro","loslor rudge","garagem do gradaço"},ang={["profession:Engineering"]="Loslor estoca suprimentos essenciais para criação inicial — como fundentes, pólvoras, tubos e kits de engenhoqueiro —, tornando seu posto na garagem uma parada conveniente para qualquer aspirante a engenheiro viajando por Dun Morogh.",["race:Dwarf"]="Como muitos artesãos de Dun Morogh, o sustento de Loslor depende de rotas de carga confiáveis entre os acampamentos anões dispersos, mostrando como predadores locais, como wendigos, podem interromper o comércio nas montanhas."},sec={{t="Um Fornecedor na Neve",b="Operando a partir da Garagem do Gradaço, logo adiante na estrada de Kharanos, Loslor Rudge mantém um estoque constante de itens essenciais de engenharia — variando de moduladores de cobre e tubos de bronze a pólvora e chaves de boca. O clima severo de Dun Morogh e as extensas operações de engenhoqueiros fazem com que peças práticas tenham grande demanda, e Loslor se orgulha de manter abastecidos os entusiastas de engrenagens locais. No entanto, a vastidão selvagem entre os entrepostos é traiçoeira; quando um mensageiro que pegou um atalho perto d'O Covil Cinzento foi afugentado por wendigos, uma remessa essencial de munição destinada ao seu valioso cliente, o armeiro Hegnar Estremetiro, foi deixada para trás na neve."}},faq={{q="Quem é Loslor Rudge?",a="Loslor Rudge é um fornecedor anão de engenharia que administra sua loja na Garagem do Gradaço, em Dun Morogh. Ele vende ferramentas de engenhoqueiro, peças e munições para aventureiros e artesãos por toda a região.",al={"loslor rudge","quem é rudge","engenheiro da garagem do gradaço"}},{q="Com qual problema Loslor precisa de ajuda?",a="Recentemente, ele enviou um mensageiro para levar uma remessa de munição ao armeiro Hegnar Estremetiro. O mensageiro pegou um atalho pelo Covil Cinzento, cruzou com wendigos selvagens e fugiu, abandonando o caixote na neve. Loslor precisa de alguém para recuperar a carga antes que ele perca seu cliente valioso.",al={"missão sem munição não tem negócio","o que rudge quer","mensageiro de rudge"}},{q="Onde fica a Garagem do Gradaço?",a="A Garagem do Gradaço é uma movimentada base de operações e oficina de máquinas anã localizada logo a leste de Kharanos, ao longo da estrada principal em direção a Loch Modan.",al={"onde fica a garagem do gradaço","localização de gradaço"}},{q="Quem é Hegnar Estremetiro?",a="Hegnar Estremetiro é um armeiro anão estabelecido em um acampamento em Dun Morogh que depende de Loslor Rudge para receber novas remessas de munição e componentes mecânicos.",al={"quem é hegnar","estremetiro"}}},fx={["774accc1"]={q="De que lado está Loslor Rudge?",a="Loslor Rudge é um membro leal da comunidade anã de Altaforja e da Aliança. Baseado na Garagem do Gradaço, ele conduz negócios apoiando diretamente atiradores, artesãos anões e assentamentos próximos em Dun Morogh.",al={"facção de loslor rudge","loslor rudge é aliança","quem loslor rudge serve"}},["1a06e65e"]={q="Por que Loslor Rudge está na Garagem do Gradaço?",a="Loslor opera a partir da Garagem do Gradaço como fornecedor de engenharia e comerciante. O depósito serve como um movimentado centro de máquinas, reparos e indústria anã fora de Altaforja, tornando-o um local ideal para ele vender peças de inventores, pólvora e munição artesanal para armeiros da região.",al={"por que loslor rudge está aqui","papel de loslor rudge na garagem","por que loslor está no depósito"}}},fp="12,278,22.653.0,20.204.0,40.304.0,28.141.0,25.162.0"}
P.entries["npc:lotwil-veriatus"] = {n="Lotwil Viriato",s="Lotwil Viriato é um excêntrico estudioso gnômico que conduz perigosos experimentos elementais nos desertos poeirentos de Ermos. Instalado a leste de Karrath com seu aprendiz sarcástico Lucien Tosselwrench e um servo mecânico chamado Servo, ele se dedica a fundir a teoria arcana, a alquimia e a engenharia em uma única disciplina.",h="Lotwil Viriato é um excêntrico estudioso gnômico que conduz perigosos experimentos elementais nos desertos...",kw={"ermos","elemental","fam'retor","karrath","lotwil","lucien","servo","viriato"},ang={["profession:Engineering"]="Os engenheiros reconhecerão a ambição de Lotwil de integrar giroscópios e engrenagens mecânicas a campos de contenção arcanos, bem como a clássica armadilha da engenharia de falhas súbitas e violentas.",["race:Gnome"]="Lotwil sintetiza a ambição intelectual gnômica levada a extremos imprudentes, buscando unir a engenharia e o arcano a despeito dos riscos catastróficos."},sec={{t="Um Campo Unificado de Caos",b="Originário de Kharanos, em Dun Morogh, Lotwil idealiza uma grande Universidade para a sua Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences. Ele acredita que essas três disciplinas não deveriam ser praticadas isoladamente, mas harmonizadas. Em busca desse sonho, escolheu as duras terras de Ermos como laboratório para estudar elementais da rocha nativos e construir grilhões vinculantes capazes de dominar as forças elementais. Embora seja um pesquisador talentoso — tendo estudado máquinas elementais e derrotado constructos de ferro negro no passado —, seu foco obsessivo muitas vezes o cega para os perigos explosivos de seu trabalho de campo."},{t="Os Grilhões Elementais",b="A grande ambição de Lotwil em Ermos gira em torno de testar seus grilhões de vinculação elemental. Ao encarregar aventureiros de coletar núcleos de elementais da rocha, refrigerante e girogronátomos, ele prepara um ritual elaborado para subjugar um servo elemental. No entanto, quando o dispositivo vinculante é finalmente ativado, a convergência de magia volátil, engenharia errática e reagentes alquímicos instáveis dá terrivelmente errado, conjurando uma monstruosidade elemental imensa e enfurecida chamada Fam'retor, que se volta contra seu criador."}},faq={{q="Quem é Lotwil Viriato?",a="Lotwil Viriato é um sábio gnômico que reside em um acampamento isolado a leste de Karrath, em Ermos. Ele é um membro fundador da Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences, buscando unir todas as três áreas em uma única disciplina acadêmica.",al={"quem é lotwil","história de lotwil viriato","gnomo em ermos"}},{q="Por que Lotwil está em Ermos?",a="Lotwil foi para Ermos para estudar a densa concentração de elementais da rocha selvagens da região. O deserto aberto oferece tanto material elemental bruto quanto espaço suficiente para conduzir experimentos voláteis de vinculação sem colocar em perigo grandes centros populacionais.",al={"por que lotwil está em ermos","acampamento de lotwil em ermos","o que lotwil está fazendo"}},{q="Quem é Lucien Tosselwrench?",a="Lucien Tosselwrench é o resignado assistente gnômico de Lotwil. Completamente cínico e exausto dos devaneios excêntricos de seu mestre, Lucien cuida da logística, conserta o servo mecânico Servo e rotineiramente alerta os transeuntes sobre o descuido perigoso de Lotwil.",al={"lucien tosselwrench","assistente de lotwil","aprendiz de lotwil"}},{q="O que acontece quando Lotwil conclui seu experimento?",a="Lotwil tenta usar seus grilhões de vinculação elemental personalizados para escravizar um constructo elemental. A tecnologia híbrida falha espetacularmente, invocando um gigantesco e enfurecido elemental da rocha chamado Fam'retor, que precisa ser derrotado antes de destruir o acampamento.",al={"experimento de lotwil falha","grilhões de vinculação elemental","fam'retor"}}},fp="15,338,24.619.0,22.526.1,23.268.0,34.248.0,27.269.0,49.259.1"}
P.entries["npc:lucius"] = {n="Lucius",s="Lucius é um agente anão encontrado perto das docas de Vila Plácida, nas Montanhas Cristarrubra. Atuando como contato de campo disfarçado para o serviço de inteligência da AVIN de Ventobravo, ele auxilia agentes com reconhecimento especializado e perícias práticas.",h="Lucius é um agente anão encontrado perto das docas de Vila Plácida, nas Montanhas Cristarrubra.",kw={"docas","anão","vila plácida","arrombamento","lucius","cristarrubra","ladino","avin"},ang={["class:Rogue"]="Para os ladinos enviados em campo a partir de Ventobravo, Lucius atua como um contato e instrutor essencial para aperfeiçoar habilidades de arrombamento e reconhecimento.",["race:Dwarf"]="Lucius é uma lembrança de que os talentos dos anões vão muito além da forja e da linha de frente, encontrando seu espaço dentro das operações secretas de Ventobravo."},sec={{t="Olhos nas Montanhas",b="Embora Lucius se apresente de forma casual na orla de Vila Plácida, ele é, na verdade, um agente clandestino ligado diretamente ao aparato de inteligência de Ventobravo, a AVIN. De seu posto nas docas, ele monitora o comércio, o tráfego incomum e as ameaças regionais que avançam sobre Cristarrubra. Agentes enviados para o leste a partir de Ventobravo são direcionados a ele para coordenar tarefas secretas e aprimorar técnicas práticas de campo, como arrombamento de fechaduras, garantindo que a Coroa mantenha seu alcance oculto muito além da Floresta de Elwynn."}},faq={{q="Quem é Lucius?",a="Lucius é um agente anão estabelecido em Vila Plácida que trabalha em nome da AVIN, o braço de inteligência do Reino de Ventobravo.",al={"identidade de lucius","quem é o anão nas docas","npc lucius"}},{q="O que Lucius faz em Vila Plácida?",a="Ele atua como contato de campo para agentes secretos, oferecendo instrução local em ladroagem e arrombamento, enquanto vigia os movimentos regionais nas Montanhas Cristarrubra.",al={"o que lucius está fazendo aqui","propósito de lucius","por que lucius está nas docas"}},{q="Quais missões envolvem Lucius?",a="Lucius é o contato para a missão da AVIN 'Encontro em Cristarrubra' e envia jovens ladinos para arrombar os baús na Serraria Alther a fim de obterem seu Certificado de Ladroagem.",al={"missões de lucius","missão encontro em cristarrubra","serraria alther"}}},fx={f414b59e={q="De que lado está Lucius?",a="Lucius está firmemente ao lado da Aliança e responde especificamente à AVIN, a agência de inteligência e operações secretas de elite de Ventobravo. Embora mantenha um perfil humilde trabalhando perto do píer em Vila Plácida, sua lealdade reside diretamente com os mestres espiões na capital.",al={"facção de lucius","lealdade de lucius","quem lucius serve"}},db7d3191={q="O que Lucius quer?",a="Lucius serve como um agente de campo despretensioso da AVIN. Ele mantém um olhar atento sobre as atividades em torno do Lago Plácido e na fronteira das Montanhas Cristarrubra, fazendo a ligação com agentes visitantes e orientando operadores promissores enviados para realizar tarefas confidenciais por todas as montanhas.",al={"o que lucius está fazendo","do que lucius precisa","objetivos de lucius"}},["2f7f1e59"]={q="A quem Lucius está ligado?",a="Lucius está diretamente ligado à AVIN, a rede de inteligência sediada em Ventobravo. Ele atua como seu contato local discreto em Montanhas Cristarrubra, trabalhando ao lado de outros agentes despachados para a região para lidar com reconhecimento secreto e operações especializadas.",al={"com quem lucius é afiliado","conexões de lucius","lucius avin"}}},fp="6,244,21.490.0,14.127.0,33.178.0,28.171.0"}
P.entries["npc:lyria-du-lac"] = {n="Lyria Du Lac",s="Lyria Du Lac é uma instrutora de guerreiros humana estacionada na Vila d'Ouro, dentro da Floresta de Elwynn. Escondida logo atrás da forja da vila, ela treina combatentes novatos e orienta jovens guerreiros enquanto eles começam a dominar suas posturas e armas.",h="Lyria Du Lac é uma instrutora de guerreiros humana estacionada na Vila d'Ouro, dentro da Floresta de Elwynn.",kw={"a warrior's training","ferreiro","floresta de elwynn","vila d'ouro","lyria du lac","instrutor de guerreiros"},ang={["class:Warrior"]="Para guerreiros recém-saídos da Abadia de Vila Norte, Lyria Du Lac é a primeira grande instrutora que você encontra na Floresta de Elwynn, ajudando-o a aprimorar seu domínio de postura e táticas de combate corpo a corpo.",["faction:Alliance"]="Posicionada atrás da forja da Vila d'Ouro, Lyria garante que os recrutas locais sejam capazes de defender o coração de Ventobravo dos bandidos da Defias e dos invasores gnolls."},sec={{t="Instrutora de Guerreiros da Vila d'Ouro",b="Enquanto a Estalagem do Leão Orgulhoso na Vila d'Ouro fervilha com viajantes e seu ferreiro trabalha em produtos comerciais locais, Lyria Du Lac mantém-se no pátio atrás da forja. Experiente em disciplina marcial, ela serve à Aliança instruindo guerreiros novatos recém-saídos da Abadia de Vila Norte. Ela avalia sua prontidão e os introduz a técnicas de combate especializadas, garantindo que aqueles que pegam em escudo e espada por Ventobravo possam se defender contra as ameaças crescentes da Floresta de Elwynn."}},faq={{q="Onde posso encontrar Lyria Du Lac?",a="Lyria Du Lac fica do lado de fora, diretamente atrás da oficina do ferreiro na Vila d'Ouro, logo a oeste da Estalagem do Leão Orgulhoso na Floresta de Elwynn.",al={"localização de lyria du lac","onde fica lyria","instrutor de guerreiros vila d'ouro"}},{q="Qual serviço Lyria Du Lac oferece?",a="Ela é uma instrutora de guerreiros. Ela ensina manobras de combate essenciais, fundamentos de postura e disciplinas de batalha para guerreiros novatos à medida que avançam em suas habilidades.",al={"o que lyria faz","papel de lyria du lac","o que lyria ensina"}},{q="Quais missões envolvem Lyria Du Lac?",a="Lyria dá aos guerreiros em desenvolvimento a missão 'A Warrior's Training', enviando-os ao veterano Ari Barbotina na taverna Pig and Whistle, na Cidade Velha de Ventobravo.",al={"missões de lyria du lac","missão de guerreiro vila d'ouro"}}},fx={f698c0e4={q="Quem é Lyria Du Lac?",a="Lyria Du Lac é uma guerreira humana veterana que serve como instrutora de combate na Floresta de Elwynn. Estacionada atrás da ferraria em Vila d'Ouro, ela avalia e instrui lutadores novatos que estão entrando no reino mais amplo, ensinando-os a aproveitar sua proeza marcial e a sobreviver às ameaças que invadem as fronteiras de Ventobravo.",al={"quem é lyria","história de lyria du lac","quem é lyria du lac"}},["34434421"]={q="De que lado está Lyria Du Lac?",a="Lyria está firmemente ao lado do Reino de Ventobravo e da Aliança. Ao preparar novos recrutas para defender a Floresta de Elwynn de perigos locais como bandidos e gnolls, ela ajuda a reforçar a prontidão militar do reino durante um período em que as forças regulares da guarnição estão sobrecarregadas.",al={"facção de lyria du lac","lealdade de lyria du lac","a quem lyria serve"}},afd6a9c2={q="Por que Lyria Du Lac está aqui em Vila d'Ouro?",a="Vila d'Ouro é o ponto de partida natural para viajantes que deixam o Vale de Vila Norte, tornando-o o posto ideal para treinar aventureiros promissores na arte do combate. Estacionada logo atrás do ferreiro, Lyria garante que qualquer guerreiro novato que chegue à cidade esteja devidamente condicionado e disciplinado antes de enfrentar perigos maiores.",al={"por que lyria está em vila d'ouro","propósito da localização de lyria du lac","o que trouxe lyria para cá"}},["277e5774"]={q="O que Lyria Du Lac quer?",a="Lyria busca alunos capazes e prontos para dominar a arte do combate. Ela quer ver jovens guerreiros aprimorarem sua disciplina, dominarem as posturas e técnicas de batalha e usarem seu treinamento para defender o reino de qualquer caos que ameace sua paz.",al={"o que lyria quer","objetivo de lyria du lac","motivo de lyria du lac"}}},fp="12,231,28.500.0,30.129.0,39.154.0,33.164.0"}
P.entries["npc:ma-stonefield"] = {n="Mama Campedra",s="Mama Campedra é uma matriarca humana que reside na Fazenda dos Campedra, no oeste da Floresta de Elwynn. Sempre do lado de fora da casa da família junto com \"Titia\" Berenice Campedra, ela lida com as dificuldades diárias da vida rural em meio a rivalidades com vizinhos e problemas com pragas.",h="Mama Campedra é uma matriarca humana que reside na Fazenda dos Campedra, no oeste da Floresta de Elwynn.",kw={"berenice campedra","floresta de elwynn","mama campedra","princesa","a princesa tem que morrer","fazenda dos campedra"},ang={["faction:Alliance"]="Para aventureiros da Aliança que exploram a Floresta de Elwynn, ajudar colonos dedicados como Mama Campedra ajuda a preservar a base agrícola de Ventobravo."},sec={{t="Problemas na Propriedade",b="Perto da cabana de sua família no sudoeste da Floresta de Elwynn, Mama Campedra vigia a propriedade rural ao lado de \"Titia\" Berenice Campedra. A vida entre a propriedade vizinha dos Maclure e as plantações de abóboras próximas raramente é pacífica. Javalis selvagens locais ameaçam constantemente as plantações da família, e nenhum causa mais transtornos do que Princesa, uma enorme porca premiada notória por pisotear os campos e devorar colheitas suadas."}},faq={{q="Quem é Mama Campedra?",a="Mama Campedra é uma das anciãs residentes da família Campedra, vivendo na propriedade rural no sudoeste da Floresta de Elwynn ao lado de parentes como \"Titia\" Berenice Campedra.",al={"quem é mama campedra","mama campedra","mãe campedra"}},{q="Onde posso encontrar Mama Campedra?",a="Ela pode ser encontrada do lado de fora, bem em frente à casa principal na Fazenda dos Campedra, localizada a oeste de Vila d'Ouro, na Floresta de Elwynn.",al={"localização de mama campedra","onde fica mama campedra","localização fazenda dos campedra"}},{q="Que problema Mama Campedra precisa resolver?",a="Mama Campedra procura aventureiros para dar um fim à Princesa, uma enorme porca premiada que repetidamente invade os campos ao redor e devora as plantações locais.",al={"missão mama campedra","missão porca princesa","quem dá a missão a princesa tem que morrer"}}},fx={["51af3003"]={q="De que lado está Mama Campedra?",a="Mama Campedra é uma súdita leal do Reino de Ventobravo e um membro da Aliança. Como a maioria das pessoas do campo que vivem no coração da Floresta de Elwynn, seu foco permanece diretamente na fazenda de sua família, embora ela dependa de aventureiros da Aliança para intervir quando os problemas locais se tornam grandes demais para simples agricultores lidarem.",al={"mama campedra é da aliança","facção de mama campedra"}},["02537c40"]={q="Por que Mama Campedra está aqui?",a="A Fazenda dos Campedra é o lar de toda a vida de Mama Campedra. Ela vive e trabalha a terra na Floresta de Elwynn ao lado de seus parentes, cuidando das tarefas diárias da vida rural logo fora da propriedade da família, perto de \"Titia\" Berenice Campedra.",al={"por que mama campedra está na fazenda","o que mama campedra faz aqui"}},ae4d5db0={q="A quem Mama Campedra está ligada?",a="Mama Campedra é uma matriarca do clã Campedra, vivendo ao lado de parentes como \"Titia\" Berenice Campedra em sua propriedade na Floresta de Elwynn. Sua família tem raízes de longa data no vale, embora eles também compartilhem uma amarga e duradoura rivalidade com seus vizinhos, os Maclure.",al={"família de mama campedra","quem são os parentes de mama campedra"}}},fp="13,264,18.438.0,21.166.0,31.138.0,44.163.0"}
P.entries["npc:mad-magus-tirth"] = {n="Magus Tirth",s="Magus Tirth é um excêntrico mago humano que vive nas salinas do Circuito da Ilusão em Mil Agulhas. Conhecido localmente por criar galinhas e atormentar seu aprendiz polimorfado, ele também é um estudioso de formidável conhecimento arcano que esbanjou tomos valiosos em apostas de corrida.",h="Magus Tirth é um excêntrico mago humano que vive nas salinas do Circuito da Ilusão em Mil Agulhas.",kw={"ancona chicken","magus tirth","circuito da ilusão","plucky","plucky johnson","rituais do poder","chapada cintilante","mil agulhas","tirth"},ang={["class:Mage"]="Tirth é uma figura importante para magos que buscam aprofundar sua compreensão do poder arcano, pois foi o autor do tratado vital \\\"Rituais do Poder\\\"."},sec={{t="Um Mago na Poeira",b="Enquanto a maioria dos magos de seu calibre estuda nas bibliotecas de Dalaran ou Ventobravo, Magus Tirth fixou residência em meio à graxa e ao rugido da Chapada Cintilante. Cercado por carros-foguete em alta velocidade, Tirth vende galinhas para transeuntes, bebe, aposta e há muito tempo amaldiçoou seu infeliz aprendiz, \\\"Plucky\\\" Johnson, transformando-o em ave. Apesar dessa postura excêntrica, Tirth possui verdadeiro domínio arcano, tendo escrito textos esotéricos sobre poder mágico antes de perdê-los em apostas imprudentes na pista de corrida."},{t="Rituais e Dívidas",b="O legado acadêmico de Tirth inclui \\\"Rituais do Poder\\\", um manual arcano procurado por magos praticantes. Infelizmente para os aspirantes a conjuradores, Tirth não é mais dono de sua própria obra-prima. Esmagado sob dívidas de jogo acumuladas no Circuito da Ilusão, o mago vendeu o tomo a um agente da Cruzada Escarlate para quitar suas perdas, forçando aprendizes e buscadores de conhecimento a rastrearem o livro em território hostil."}},faq={{q="Por que Magus Tirth está no deserto?",a="Tirth vive na Chapada Cintilante ao lado do Circuito da Ilusão, atraído pelo espetáculo e pelo jogo. Em vez de seguir a vida acadêmica em uma cidade grande, ele observa os corredores gnomos e goblins, vende galinhas e se entrega a seus vícios.",al={"por que tirth está aqui","magus tirth chapada cintilante","localização de tirth"}},{q="Quem é a galinha ao lado dele?",a="A galinha que vagueia pelo circuito de corridas é \\\"Plucky\\\" Johnson, o aprendiz de Magus Tirth. Tirth lançou uma maldição sobre Johnson que o transformou em uma galinha e nem consegue mais se lembrar do porquê, embora tenha certeza de que foi bem merecido para o ingrato.",al={"quem é plucky","plucky johnson","aprendiz galinha de tirth"}},{q="O que é o livro Rituais do Poder?",a="Rituais do Poder é um tratado avançado sobre energia arcana de autoria de Magus Tirth. É um texto essencial para magos que buscam aprimorar sua arte, embora Tirth tenha se desfeito dele para pagar suas crescentes dívidas de corrida.",al={"rituais do poder","livro de tirth","livro de missão de mago"}},{q="Por que o livro dele é difícil de obter?",a="Tirth não tem mais sua cópia de Rituais do Poder. Os magos que o procuram devem seguir seu relato sobre como ele se desfez do tomo.",al={"quem tem rituais do poder","dívidas de tirth","livro da cruzada escarlate"}}},fx={f085518f={q="De que lado está Mad Magus Tirth?",a="Mad Magus Tirth permanece estritamente neutro. Ele ganha a vida nas planícies de sal da Chapada Cintilante ao lado de engenheiros goblins e Gnomos, oferecendo alegremente suas mercadorias e conselhos mágicos a viajantes tanto da Aliança quanto da Horda, sem tomar parte na guerra mais ampla deles.",al={"magus tirth é da aliança ou horda","facção de tirth","magus tirth é neutro"}},["8056ee12"]={q="Quem é Magus Tirth?",a="Magus Tirth é um conjurador humano excêntrico que reside no Circuito da Ilusão, lá na Chapada Cintilante. Embora claramente conhecedor do saber arcano esotérico — tendo escrito um notável tomo mágico intitulado Rituais do Poder —, ele agora passa seus dias vendendo galinhas de Ancona, bebendo e apostando nas corridas.",al={"quem é o magus tirth louco","quem é tirth","história de magus tirth"}},["3482f0bf"]={q="O que Magus Tirth quer?",a="Além de juntar moedas dos espectadores das corridas vendendo galinhas de Ancona, Tirth quer principalmente uma caneca fresca de cerveja e dicas quentes sobre a próxima corrida. Certa vez, ele buscou dinheiro rápido para pagar suas pesadas dívidas de jogo, o que o levou a vender sua própria pesquisa acadêmica.",al={"o que tirth quer","motivos de magus tirth","por que tirth está vendendo galinhas"}}},fp="11,290,20.521.0,17.418.1,37.236.0,31.235.0,34.214.0,36.128.0"}
P.entries["npc:madame-eva"] = {n="Madame Eva",s="Madame Eva é uma reverenciada vidente e matriarca que vive em Vila Sombria, na floresta sombria da Floresta do Crepúsculo. Praticando artes místicas e mais antigas de adivinhação e cartomancia, ela costuma ser a primeira habitante da cidade a pressentir perturbações não naturais pela floresta. Viajantes frequentemente a procuram para desvendar mistérios sombrios ou obter amuletos ocultos contra as trevas rastejantes.",h="Madame Eva é uma reverenciada vidente e matriarca que vive em Vila Sombria, na floresta sombria da Floresta...",kw={"alyssa eva","cartomancia","vila sombria","floresta do crepúsculo","vidente","linha de cabelo de fantasma","madame eva","galvão"},ang={["class:Priest"]="Enquanto a Luz Sagrada traz consolo aos vivos, os sacerdotes acharão a dependência de Eva na cartomancia e em restos de espíritos um curioso contraponto terreno à liturgia tradicional da igreja.",["faction:Alliance"]="Para os campeões da Aliança que adentram a sombra opressiva da Floresta do Crepúsculo, Madame Eva é uma guia indispensável cujas premonições dissipam a confusão mortal da floresta.",["profession:Tailoring"]="Alfaiates apreciarão o conhecimento de Eva sobre materiais de tecelagem bizarros, especificamente sua habilidade de trabalhar com fios espectrais colhidos diretamente dos fantasmas da região."},sec={{t="A Vidente de Vila Sombria",b="Vivendo tranquilamente em meio à escuridão de Vila Sombria, Madame Eva pratica cartomancia e antigos rituais populares que muitos na catedral de Ventobravo veriam com desconfiança. Em uma região abandonada e assolada por feras selvagens, pelos mortos-vivos e por horrores mais sombrios, suas percepções misteriosas são toleradas e procuradas tanto por habitantes desesperados quanto por aventureiros que passam pelo local."},{t="Laços de Sangue e Profecia",b="Além de seu papel como leitora do oculto, Madame Eva é profundamente dedicada à sua família, atuando como avó de Alyssa Eva e do jovem Lohgan. Quando sua cartomancia revela presságios sombrios ameaçando sua neta, Eva não hesita em recorrer à ajuda de andarilhos que passam por ali para vasculhar a floresta, desenterrando tragédias há muito enterradas antes que a história possa se repetir."},{t="Tecendo Proteção Contra a Noite",b="O conhecimento de Eva se estende além da leitura de cartas para a criação de rituais e proteção. Desde fiar Linha de Cabelo de Fantasma a partir do cabelo de um espírito até criar relíquias populares bizarras como o Totem do Castigo, ela compreende a lógica estranha e crepuscular que governa os espíritos inquietos da Floresta do Crepúsculo melhor do que quase qualquer outra pessoa na cidade."}},faq={{q="Quem é Madame Eva?",a="Madame Eva é uma idosa vidente e adivinha humana que reside em Vila Sombria. Ela pratica cartomancia e antigos ofícios populares para vislumbrar os perigos invisíveis que espreitam a Floresta do Crepúsculo.",al={"madame eva","quem é eva","vidente de vila sombria"}},{q="Qual é o papel de Madame Eva no mistério de Galvão?",a="Madame Eva lê as cartas e pressente um perigo sobrenatural iminente cercando sua neta Alyssa. Suas leituras guiam aventureiros a investigar documentos e pistas esquecidos que desvendam a sombria história de Galvão Brumanto.",al={"eva galvão","lenda de galvão eva","por que eva se importa com galvão"}},{q="Madame Eva é uma bruxa ou uma maga?",a="Eva é principalmente uma vidente e praticante de artes místicas mais antigas, como cartomancia, tecelagem com fios de espíritos e efígies populares. Sua magia é mais semelhante à adivinhação tradicional e ao saber oculto do que ao arcano estruturado de Dalaran ou à Luz Sagrada.",al={"eva é uma bruxa","tipo de magia de eva","qual magia eva usa"}},{q="Quem é parente de Madame Eva em Vila Sombria?",a="Ela é a avó de Alyssa Eva e Lohgan Eva. A Guarda Noturna da cidade também inclui a Vigia Eva, que acredita-se compartilhar laços com sua família.",al={"família de eva","netos de madame eva","avó de alyssa eva"}},{q="Para que serve a Linha de Cabelo de Fantasma?",a="Madame Eva fia Linha de Cabelo de Fantasma a partir do cabelo de um espírito inquieto. Como ela mesma diz, a linha tem mil utilidades, desde aprisionar espíritos malignos até costurar vida em objetos inanimados, e ela a produz para aqueles que lhe trazem o cabelo de fantasma de que precisa.",al={"linha de cabelo de fantasma","missão da linha de eva"}},{q="Por que Madame Eva cria o Totem do Castigo?",a="Madame Eva cria o Totem do Castigo como uma efígie simpática e sombria. Ao vincular materiais específicos de criaturas a ele, o totem direciona maldições e danos de volta às feras terríveis que aterrorizam a floresta.",al={"totem do castigo","totem de eva"}}},fx={b3bc0c21={q="De que lado está Madame Eva?",a="Madame Eva está firmemente ao lado do povo de Vila Sombria e da Aliança. Embora ela se aventure na cartomancia e nas obscuras 'artes antigas', suas lealdades permanecem com seus vizinhos sitiados e sua família, usando sua adivinhação e rituais para proteger a cidade contra os perigos sombrios que se arrastam pela Floresta do Crepúsculo.",al={"lealdade de madame eva","a quem eva serve","madame eva é da aliança"}},d6f73346={q="O que Madame Eva quer?",a="Madame Eva busca proteger sua comunidade e seus parentes das forças sombrias que assombram a Floresta do Crepúsculo. Usando sua cartomancia, ela prevê ameaças ocultas — como a desgraça à espreita em torno do mistério de Galvão Brumanto — e orienta viajantes a reunir reagentes rituais para afastar o mal e proteger sua família.",al={"o que eva está tentando fazer","objetivos de eva","por que madame eva precisa de ajuda"}},["6bf59259"]={q="Por que Madame Eva está aqui em Vila Sombria?",a="Vila Sombria é o lar ancestral de Madame Eva. Ela reside em sua cabana como uma matriarca para seus netos, Alyssa e Lohgan Eva, oferecendo orientação, adivinhação e ajuda mística ao povo assustado que tenta suportar a vida em meio aos bosques sombrios.",al={"por que eva vive na floresta do crepúsculo","por que madame eva está em vila sombria","lar de madame eva"}}},fp="10,372,31.351.0,26.353.0,36.317.0,18.177.0,52.237.0,32.252.0,42.149.0,35.250.0,50.201.0"}
P.entries["npc:magatha-grimtotem"] = {n="Magatha Temível Totem",s="Magatha Temível Totem é a matriarca da tribo Temível Totem e a Elder Crone do Penhasco do Trovão. Uma xamã formidável e conspiradora política, ela reside no Platô dos Anciãos enquanto desafia continuamente a visão de Caerne Casco Sangrento para a nação tauren.",h="Magatha Temível Totem é a matriarca da tribo Temível Totem e a Elder Crone do Penhasco do Trovão.",kw={"arikara","casco sangrento","caerne","elder crone","platô dos anciãos","temível totem","magatha","cavernas ígneas","penhasco do trovão","zamah"},ang={["class:Shaman"]="Magatha é inegavelmente uma das xamãs mais poderosas de Kalimdor, comandando elementos primordiais com uma autoridade que poucos taurens vivos conseguem rivalizar.",["faction:Horde"]="Embora Magatha ofereça ajuda valiosa e conselhos contra ameaças regionais, sua lealdade feroz ao clã e seu desprezo aberto por outras raças fazem dela uma camarada indigna de confiança.",["race:Tauren"]="Todo tauren conhece a reputação sombria dos Temível Totem, tornando a presença de Magatha no Platô dos Anciãos uma lembrança incômoda da divisão ideológica que ameaça suas tribos unidas.",["race:Undead"]="Viajantes Renegados encontram uma recepção surpreendentemente calorosa por parte da Elder Crone, que consulta ativamente a Sociedade Real dos Boticários nos Poços das Visões."},sec={{t="A Matriarca do Platô dos Anciãos",b="Magatha ascendeu à autoridade absoluta sobre os Temível Totem por meio de uma união arranjada, seguida pelo repentino e fatal acidente de escalada de seu companheiro. Operando a partir do Platô dos Anciãos com sua comitiva pessoal e guarda-costas, ela se destaca como a líder política e espiritual incontestável de sua tribo reclusa. Ao contrário de Caerne Casco Sangrento, Magatha prega a dominância dos taurens, vendo as outras raças mortais como intrusas em Kalimdor que deveriam ser erradicadas ou deixadas de lado."},{t="Uma Aliança Curiosa",b="Apesar de seu desdém aberto por aqueles que não são taurens, Magatha esteve entre os primeiros defensores da admissão dos Renegados na Horda. Ela afirma que os taurens podem ensinar aos mortos-vivos o equilíbrio espiritual e guiá-los para recuperar sua humanidade. Na prática, porém, Magatha colabora diretamente com a Sociedade Real dos Boticários sob o Penhasco do Trovão, consultando figuras como Apothecary Zamah sobre alquimia prática e estudos de relíquias arcanas."},{t="Maquinações Políticas",b="Por trás de uma fachada de conselhos sábios, Magatha trabalha ativamente para enfraquecer a autoridade de Caerne enquanto testa as defesas de ameaças em potencial. Ela envia aventureiros a perigos profundos — desde sondar as forças troggs nas Cavernas Ígneas até caçar o espírito vingativo Arikara. Cada tarefa atribuída por ela serve para consolidar a influência dos Temível Totem ou para preparar o dia em que poderá suplantar inteiramente a dinastia Casco Sangrento."}},faq={{q="Quem é Magatha Temível Totem?",a="Magatha é a anciã e matriarca da tribo Temível Totem. Uma xamã talentosa desde a infância, ela assumiu o domínio total de seu clã após seu parceiro morrer em um acidente de escalada. Ela reside no Platô dos Anciãos no Penhasco do Trovão, onde atua como a principal rival política de Caerne Casco Sangrento.",al={"história de magatha","quem é a elder crone","elder crone penhasco do trovão"}},{q="Por que Magatha apoia os Renegados?",a="Aparentemente, Magatha acredita que as tradições taurens e a compreensão xamânica podem guiar os Renegados de volta à humanidade. No entanto, muitos suspeitam que sua amizade com a Sociedade Real dos Boticários seja movida pelo desejo de segredos alquímicos esotéricos e de aliados políticos fora do círculo interno leal a Caerne.",al={"magatha e mortos-vivos","por que magatha gosta dos renegados","magatha apothecary zamah"}},{q="Qual é a relação de Magatha com Caerne Casco Sangrento?",a="Magatha vê Caerne como brando, ingênuo e incapaz de liderar os taurens unidos. Enquanto Caerne defende a coexistência dentro da Horda e a paz em Kalimdor, Magatha acredita que os Temível Totem devem recuperar as terras ancestrais pela força e eliminar os invasores estrangeiros.",al={"magatha vs caerne","magatha odeia caerne","caerne e magatha"}},{q="Qual foi a missão nas Cavernas Ígneas?",a="Magatha enviou um emissário chamado Maur para as Cavernas Ígneas sob Orgrimmar a fim de negociar com os troggs que vivem ali. Em vez disso, os troggs mataram Maur, levando Magatha a enviar aventureiros da Horda para dentro da caverna a fim de recuperar a bolsa de Maur e massacrar os troggs em retaliação.",al={"missão de magatha cavernas ígneas","por que magatha enviou maur","bolsa perdida magatha"}},{q="Quem é Arikara?",a="Arikara é um espírito vingativo de serpente alada que supostamente busca retaliação contra o povo tauren. Magatha afirma que Arikara busca vingança diretamente contra Caerne Casco Sangrento e encarrega campeões capazes de usar agave encantada para invocar e abater a criatura.",al={"serpente da vingança","missão arikara","magatha arikara"}},{q="Onde Magatha Temível Totem pode ser encontrada?",a="Magatha reside dentro da grande tenda principal no topo do Platô dos Anciãos no Penhasco do Trovão, acompanhada por seu servo Rahauro e dois guardas estóicos dos Temível Totem.",al={"localização de magatha","onde fica magatha","magatha platô dos anciãos"}}},fx={ebac2d3c={q="De que lado está Magatha Temível Totem?",a="Magatha serve a si mesma e à tribo Temível Totem acima de tudo. Embora ela ocupe um assento honrado no Platô dos Anciãos de Penhasco do Trovão e pertença formalmente à Horda, sua lealdade é puramente transacional. Ela desafia abertamente a visão do Grão-Chefe Caerne Casco Sangrento para seu povo, favorecendo o domínio impiedoso dos tauren sobre a paz, e busca alianças privadas — mais notavelmente com os Renegados — para expandir o alcance de sua própria facção.",al={"lealdades de magatha","a quem magatha serve","magatha é leal à horda"}},b26ae613={q="O que Magatha Temível Totem quer?",a="Magatha acredita que apenas ela é capaz de liderar os tauren. Ela busca arrancar a autoridade de Caerne Casco Sangrento, expulsar todas as raças inferiores de Kalimdor e recuperar as propriedades ancestrais de seu povo. Para acumular o poder necessário para alcançar isso, ela constantemente reúne relíquias antigas, testa potenciais inimigos e cultiva relacionamentos controversos que Caerne e os outros anciãos jamais aprovariam.",al={"objetivos de magatha","o que magatha está planejando","motivações de magatha"}},["0cc6173c"]={q="Por que Magatha Temível Totem está aqui?",a="Como a anciã e matriarca dos Temível Totem, Magatha reside no Platô dos Anciãos para representar sua tribo feroz dentro da nação tauren unida. Deste ponto de vantagem elevado, ela aconselha viajantes, aconselha a cidade e mantém um olhar atento sobre o governo de Caerne Casco Sangrento, garantindo que seu clã mantenha uma voz poderosa na governança de Penhasco do Trovão.",al={"por que magatha está em penhasco do trovão","por que magatha está aqui"}},["4e6ef5c4"]={q="A quem Magatha Temível Totem está ligada?",a="Magatha comanda os guerreiros ferozes da tribo Temível Totem, flanqueada constantemente por seus guardas e servos pessoais. Fora de seu clã, ela mantém uma parceria atípica e ativa com os Renegados — trabalhando ao lado de figuras da Real Sociedade de Boticários como Apothecary Zamah — e mantém conexões privadas com videntes e agentes por toda Kalimdor que operam fora do círculo interno de Caerne.",al={"aliados de magatha","com quem magatha se associa","conexões de magatha"}},["92d0808b"]={q="Por que Magatha Temível Totem é famosa ou temida?",a="Magatha foi abençoada com um imenso talento xamânico desde a infância e passou a vida traduzindo esse poder em autoridade absoluta sobre os Temível Totem. Muitos em Penhasco do Trovão temem sua ambição impiedosa, sussurrando que ela arranjou seu próprio casamento para ganhar a liderança de seu clã. Sua disposição em empregar remédios sombrios, intrometer-se com espíritos vingativos e desafiar Caerne faz dela uma das figuras mais intimidantes em Mulgore.",al={"por que magatha é temida","magatha é poderosa","reputação de magatha"}}},fp="17,243,27.449.0,18.431.0,22.412.1,25.284.0,38.301.0,53.256.0,39.270.0,15.251.0,37.140.0"}
P.entries["npc:magga"] = {n="Magga",s="Magga é uma orc residente que vive no Vale das Provações em Durotar. Posicionada perto de The Den, ela serve como um rosto acolhedor para aventureiros da Horda recém-chegados que iniciam sua jornada no vale.",h="Magga é uma orc residente que vive no Vale das Provações em Durotar.",kw={"durotar","horda","estalajadeiro grosk","magga","orc","vale das provações","welcome"},ang={["faction:Horde"]="Para os novos recrutas que chegam ao severo Vale das Provações, Magga oferece uma acolhida tranquilizadora a Durotar."},sec={{t="Um Rosto Acolhedor no Vale das Provações",b="O Vale das Provações é o primeiro contato com o mundo para jovens orcs e trolls Lançanegra. Posicionada perto de The Den, Magga cumprimenta os recém-chegados ao vale. Embora mantenha a discrição entre os instrutores e recrutas atarefados do vale, ela ajuda a unir o pequeno acampamento."}},faq={{q="Quem é Magga?",a="Magga é uma civil orc posicionada no Vale das Provações, Durotar. Ela fica perto de The Den, dando as boas-vindas aos novos viajantes da Horda.",al={"magga durotar","magga vale das provações","quem é magga"}},{q="Qual é a ligação de Magga com o Estalajadeiro Grosk?",a="Nenhum vínculo especial entre eles é registrado. Magga permanece no Vale das Provações, enquanto o Estalajadeiro Grosk administra a estalagem em Monte Navalha, oferecendo aos viajantes comida, bebida e um lugar para vincular suas pedras de regresso.",al={"magga e grosk","magga estalajadeiro"}},{q="Magga oferece alguma missão?",a="Magga recebe a tarefa 'Welcome!': aventureiros que carregam um Vale-brinde do Vale das Provações entregam-no a ela, e ela lhes dá as boas-vindas a Azeroth com um pequeno companheiro de presente.",al={"missões de magga","missão welcome"}}},fx={["7d8c5102"]={q="De que lado Magga está?",a="Magga é uma membra leal da Horda, habitando ao lado de seus companheiros orcs no Vale das Provações. Ela recebe os recém-chegados que chegam ao vale, apoiando com orgulho o povo e a defesa de Durotar sob a liderança de Thrall.",al={"facção de magga","magga é da horda","lealdade de magga"}}},fp="5,201,40.272.0,13.124.0,46.199.0,28.174.0"}
P.entries["npc:maggran-earthbinder"] = {n="Maggran Ata Terra",s="Maggran Ata Terra é um veterano tauren calejado, nomeado pelo Grande Chefe Caerne Casco Sangrento para liderar o acampamento da Horda no Retiro Rocha do Sol. Endurecido por uma vida inteira de conflitos brutais, ele supervisiona a defesa dos vales escarpados das Torres de Pedra contra feras vorazes e harpias agressivas. Embora desgastado por inúmeras batalhas, ele permanece como um guardião inabalável do assentamento.",h="Maggran Ata Terra é um veterano tauren calejado, nomeado pelo Grande Chefe Caerne Casco Sangrento para...",kw={"besseleth","bloodfury","caerne casco sangrento","ata terra","harpias","maggran","cordilheira das torres de pedra","retiro rocha do sol"},ang={["faction:Horde"]="Para viajantes que percorrem as subidas íngremes das Torres de Pedra, Maggran é a principal autoridade coordenando patrulhas locais da Horda e mantendo rotas de suprimentos livres de feras e harpias.",["race:Tauren"]="Maggran personifica o pesado fardo que a guerra impõe ao espírito dos shu'halo, servindo como um lembrete de como o conflito pode endurecer até mesmo os filhos mais serenos da Mãe Terra."},sec={{t="O Refúgio de um Veterano",b="Maggran Ata Terra foi enviado para a Cordilheira das Torres de Pedra pelo próprio Grande Chefe Caerne Casco Sangrento. Veterano de incontáveis escaramuças e campanhas sangrentas, Maggran admite que a idade e a violência endureceram seu coração, despojando-o da gentileza natural típica de seu povo. O Retiro Rocha do Sol deveria ser tanto um posto avançado sob seu comando firme quanto um lugar de descanso, onde os ventos quentes e o sol da montanha pudessem acalmar seu espírito castigado pelas batalhas."},{t="Ameaças nos Penhascos",b="Mesmo nas Torres de Pedra, Maggran encontra pouca paz. Como supervisor do Retiro Rocha do Sol, ele coordena os esforços de defesa contra as harpias Bloodfury que nidificam nos picos e mobiliza combatentes para enfrentar os perigos predatórios por todos os penhascos. Tendo sobrevivido certa vez a uma emboscada da aranha gigante Besseleth em pessoa, Maggran não tem ilusões sobre a selva mortal ao redor deles e frequentemente recruta viajantes para eliminar predadores regionais letais antes que eles invadam o posto avançado."}},faq={{q="Quem é Maggran Ata Terra?",a="Maggran Ata Terra é o ancião tauren comandante no Retiro Rocha do Sol, na Cordilheira das Torres de Pedra. Endurecido por inúmeras batalhas, ele foi posicionado aqui por Caerne Casco Sangrento para vigiar o assentamento e manter seguras as estradas de suprimentos e as fronteiras.",al={"maggran","quem é maggran","líder do retiro rocha do sol"}},{q="Por que Maggran foi enviado para o Retiro Rocha do Sol?",a="Caerne Casco Sangrento o nomeou para liderar o Retiro Rocha do Sol em parte por sua liderança militar experiente e em parte como um refúgio. O corpo e a alma de Maggran foram profundamente desgastados por uma vida inteira de combate, e o sol sereno da montanha oferece a ele um pouco de cura.",al={"por que maggran está aqui","história de maggran","caerne e maggran"}},{q="Com quais ameaças Maggran pede que os aventureiros lidem?",a="Maggran comanda as defesas contra as ferozes harpias Bloodfury que infestam as montanhas e envia guerreiros para eliminar a aranha gigante matriarca Besseleth, uma predadora aterrorizante de quem ele escapou por pouco no passado durante suas viagens.",al={"missões de maggran","o que maggran quer","harpias cordilheira das torres de pedra"}},{q="O que aconteceu entre Maggran e Besseleth?",a="Maggran foi mordido no passado pela colossal aranha Besseleth. Embora tenha conseguido repelir a criatura e escapar com vida, ele envia aventureiros capazes para abater a fera, para que ninguém mais caia em sua teia.",al={"maggran besseleth","missão da aranha maggran","aracnofobia história"}},{q="Maggran tem algum papel no Penhasco do Trovão?",a="Maggran serve diretamente sob as ordens do Grande Chefe do Penhasco do Trovão, Caerne Casco Sangrento. Embora esteja destacado em campo no Retiro Rocha do Sol, sua autoridade e ordens vêm diretamente da capital.",al={"maggran penhasco do trovão","maggran caerne"}},{q="Maggran Ata Terra é amigável com jogadores da Aliança?",a="Não. Maggran é um líder convicto da Horda e permanece totalmente hostil a quaisquer aventureiros da Aliança que entrem no Retiro Rocha do Sol.",al={"aliança pode falar com maggran","maggran hostil"}}},fp="19,387,17.455.0,20.472.0,27.247.0,41.256.0,55.228.0,44.210.0,42.201.0,52.133.0"}
P.entries["npc:magis-sparkmantle"] = {n="Magis Fagulhamanto",s="Magis Fagulhamanto é um instrutor de magos gnomo localizado dentro da Destilaria Cervaforte, em Kharanos. Ele oferece orientação e treinamento para conjuradores novatos que se aventuram do Vale Cristálgida em direção ao coração de Dun Morogh.",h="Magis Fagulhamanto é um instrutor de magos gnomo localizado dentro da Destilaria Cervaforte, em Kharanos.",kw={"dun morogh","mago gnomo","kharanos","instrutor de magos","magis","magis fagulhamanto","fagulhamanto","destilaria cervaforte"},ang={["class:Mage"]="Para os magos da Aliança que cruzam Dun Morogh, Fagulhamanto é um contato local essencial para treinamento de feitiços e recomendações para redes arcanas mais amplas.",["race:Gnome"]="Gnomos exilados de Gnomeregan costumam recorrer a mentores como Fagulhamanto para manter suas tradições acadêmicas e arcanas florescendo enquanto vivem entre os anões."},sec={{t="Um Conjurador na Destilaria",b="Enquanto os anões se reúnem na Destilaria Cervaforte para apreciar cervejas encorpadas, Magis Fagulhamanto oferece uma presença arcana entre os barris e tonéis de Kharanos. Os magos gnomos frequentemente se integram de perto com seus aliados anões por toda Dun Morogh, e Fagulhamanto atua como um mentor fundamental para conjuradores novatos prontos para expandir sua compreensão teórica e prática das artes arcanas."},{t="Orientando Jovens Arcanistas",b="Além de instruir novatos em encantamentos básicos, Magis garante que estudantes promissores se conectem com círculos mágicos mais amplos. Quando os magos superam as instruções locais iniciais ou necessitam de orientação especializada, Fagulhamanto os encaminha para locais mais distantes, enviando-os para colegas praticantes como Bink ou para mentores posicionados nos principais centros da Aliança."}},faq={{q="Quem é Magis Fagulhamanto?",a="Magis Fagulhamanto é um instrutor de magos gnomo que reside em Kharanos, Dun Morogh. Ele instrui conjuradores novatos nos fundamentos arcanos.",al={"magis fagulhamanto","quem é magis","instrutor de magos de kharanos"}},{q="Onde Magis Fagulhamanto pode ser encontrado?",a="Ele pode ser encontrado dentro da Destilaria Cervaforte, a principal estalagem e ponto de encontro da cidade de Kharanos.",al={"localização de magis","onde fica magis","encontrar fagulhamanto"}},{q="Por que um instrutor de magos gnomo está em uma destilaria anã?",a="Após a queda de Gnomeregan, muitos gnomos se estabeleceram entre seus primos anões em Dun Morogh. A Destilaria Cervaforte atua como o ponto central de Kharanos, tornando-se um posto ideal para orientar conjuradores viajantes.",al={"por que na destilaria","gnomo na destilaria","por que destilaria cervaforte"}},{q="Magis Fagulhamanto oferece alguma missão?",a="Magis encaminha magos em desenvolvimento para outros mentores arcanos conforme progridem, inclusive enviando praticantes para falar com Bink ou se apresentar a instrutores em territórios humanos.",al={"missões de fagulhamanto","missões de magis"}}},fx={e3e37731={q="O que Magis Fagulhamanto deseja?",a="Magis dedica-se a instruir magos principiantes nas artes arcanas. Enquanto está hospedado na destilaria, ele prepara conjuradores novatos para a estrada que têm pela frente, ensinando-lhes os fundamentos da magia antes de encaminhá-los a mestres seniores, como Jana Catão, em Ventobravo.",al={"o que magis deseja","objetivos de magis fagulhamanto","por que treinar magos magis"}},["318a77dd"]={q="A quem Magis Fagulhamanto está ligado?",a="Como parte da rede mais ampla de magos da Aliança, Magis mantém conexões com colegas treinadores por todo o reino, incluindo Bink nas terras anãs e Jana Catão no Mage Quarter de Ventobravo, garantindo que alunos promissores encontrem instrução avançada.",al={"aliados de magis fagulhamanto","a quem fagulhamanto está ligado","conexões de fagulhamanto"}},["1189c3a2"]={q="De que lado está Magis Fagulhamanto?",a="Magis Fagulhamanto está firmemente ao lado de Gnomeregan e da Grande Aliança. Como muitos gnomos exilados que fugiram da catástrofe em sua cidade natal, ele vive e trabalha ao lado dos anões de Altaforja, oferecendo seu conhecimento arcano aos defensores da Aliança.",al={"facção de magis fagulhamanto","magis é da aliança","a quem fagulhamanto serve"}}},fp="17,224,31.369.0,25.350.0,25.132.0,37.107.0,60.222.0,40.173.0"}
P.entries["npc:magistrate-henry-maleb"] = {n="Magistrado Henrique Maleb",s="O Magistrado Henrique Maleb supervisiona a administração civil na cidade portuária de Costa Sul, o principal reduto costeiro da Aliança no Contraforte de Eira dos Montes. Encarregado de manter a ordem em meio a ameaças constantes, ele concentra grande parte de sua autoridade na caça aos conspiradores da Camarilha que têm como alvo a liderança da cidade.",h="O Magistrado Henrique Maleb supervisiona a administração civil na cidade portuária de Costa Sul, o principal...",kw={"alterac","assassinos","henrique maleb","eira dos montes","magistrado maleb","costa sul","camarilha"},ang={["class:Rogue"]="Os ladinos encontrarão Maleb profundamente preocupado com as artes do subterfúgio e do assassinato, dependendo de operativos de olhos aguçados para superar os assassinos ocultos da Camarilha.",["faction:Alliance"]="Para os campeões da Aliança que chegam a Eira dos Montes, o Magistrado Maleb representa a autoridade civil legítima em uma fronteira sem lei, oferecendo recompensas pelos degoladores da Camarilha que desestabilizam a cidade."},sec={{t="Guardião da Ordem de Costa Sul",b="Operando a partir da prefeitura de Costa Sul, o Magistrado Henrique Maleb cuida da governança civil de um dos últimos assentamentos verdadeiros da Aliança em Lordaeron. A cidade vive sob constante cerco dos Renegados ao norte e a oeste, enquanto salteadores impiedosos rondam os contrafortes. Maleb assumiu seu posto atual após o misterioso assassinato do magistrado anterior, um ato que ele atribui diretamente à Camarilha. Determinado a não sofrer o mesmo destino, ele coordena investigações ativas para erradicar assassinos ocultos, desmantelar as redes de suprimentos da Camarilha e desmascarar os nobres renegados que manipulam os cordéis a partir das Ruínas de Alterac."},{t="Uma Teia de Traição Nobre",b="As investigações de Maleb sobre a Camarilha revelam um amargo conflito regional. Os assassinos que rastejam pelos pomares nos arredores de Costa Sul não são meros bandidos, mas operativos pagos que aceitam contratos de aristocratas caídos de Alterac. Maleb orienta batedores de confiança da Aliança a interceptar seus planos codificados e eliminar seus líderes, trabalhando incansavelmente para quebrar o domínio da Camarilha antes que suas tramas possam paralisar por completo as defesas da cidade."}},faq={{q="Quem é o Magistrado Henrique Maleb?",a="Ele é o principal magistrado civil de Costa Sul, no Contraforte de Eira dos Montes, responsável por manter a ordem civil e proteger o refúgio costeiro da Aliança contra ameaças internas.",al={"henrique maleb","magistrado de costa sul","quem é maleb"}},{q="Por que Maleb está investigando a Camarilha?",a="Maleb assumiu o cargo após o assassinato do magistrado anterior de Costa Sul. Suas investigações apontam para assassinos contratados da Camarilha enviados por nobres caídos de Alterac, e ele ativamente comissiona aventureiros da Aliança para impedir outro atentado contra a sua vida.",al={"por que camarilha","maleb camarilha","assassinos de costa sul"}},{q="Onde o Magistrado Maleb pode ser encontrado?",a="Ele pode ser encontrado dentro do prédio da prefeitura em Costa Sul, situado nas regiões ao sul do Contraforte de Eira dos Montes.",al={"localização de maleb","onde fica henrique maleb","encontrar magistrado maleb"}},{q="Quais ameaças Maleb enfrenta em Eira dos Montes?",a="Além da ameaça constante da expansão dos Renegados pelo norte e oeste, Maleb é especificamente ameaçado pelos assassinos sombrios da Camarilha que espreitam o perímetro da cidade e conspiram para derrubar o governo de Costa Sul.",al={"ameaças a costa sul","inimigos de maleb"}}},fx={["078ca783"]={q="De que lado está o Magistrado Henrique Maleb?",a="O Magistrado Henrique Maleb é inteiramente devotado à Aliança. Como magistrado civil da Costa Sul, ele serve ao município local e responde às autoridades da Aliança, trabalhando para manter os humanos livres restantes de Eira dos Montes unidos e seguros contra os hostis ao redor.",al={"facção do magistrado maleb","maleb aliança ou horda","henrique maleb é aliança"}},b9806b6f={q="O que o Magistrado Henrique Maleb deseja?",a="Maleb quer proteger a Costa Sul da destruição e dar um fim à predação da Camarilha. Tendo assumido o cargo após o assassinato de seu predecessor, ele está determinado a identificar os conspiradores, rastrear seus assassinos sombrios e punir os nobres alteraci que direcionam os planos contra a cidade.",al={"objetivos de henrique maleb","do que maleb precisa","objetivo do magistrado maleb"}},a611609c={q="Por que o Magistrado Henrique Maleb está na Costa Sul?",a="Maleb foi recentemente designado como magistrado da Costa Sul após o assassinato do líder anterior da cidade. Ele preside na Prefeitura da Costa Sul para governar o assentamento, supervisionar a defesa da cidade e coordenar as investigações da Aliança sobre as ameaças que espreitam pelo Contraforte de Eira dos Montes.",al={"por que maleb está na costa sul","razão de maleb na costa sul","prefeitura do magistrado maleb"}}},fp="22,313,30.640.0,24.434.1,30.175.0,41.278.0,36.121.0,42.222.0"}
P.entries["npc:magistrate-sevren"] = {n="Magistrado Sevren",s="O Magistrado Sevren é a principal autoridade administrativa que preside o assentamento de Montalvo nas Clareiras de Tirisfal. Posicionado dentro da prefeitura, ele organiza as defesas iniciais dos Renegados e orienta os campeões recém-chegados a estabilizar o território ao redor de Cidade Baixa.",h="O Magistrado Sevren é a principal autoridade administrativa que preside o assentamento de Montalvo nas...",kw={"agamand","montalvo","renegados","magistrado","sevren","tirisfal","prefeitura","cidade baixa"},ang={["faction:Horde"]="Aliados da Horda que chegarem a Tirisfal encontrarão Sevren coordenando a pacificação na linha de frente das Clareiras de Tirisfal contra bandidos, remanescentes do Flagelo e facções rebeldes.",["race:Undead"]="Para os Renegados recém-libertos que partem de Plangemortis, o Magistrado Sevren representa a face cívica do reino de Sylvanas, fornecendo suas primeiras grandes tarefas para proteger sua terra natal."},sec={{t="Magistrado da Cidade de Montalvo",b="Operando a partir da prefeitura de Montalvo, o Magistrado Sevren coordena a autoridade civil e os esforços estratégicos nas terras logo ao norte de Cidade Baixa. Conforme novos Renegados avançam rumo às Clareiras de Tirisfal, Sevren avalia crises locais e envia aventureiros para restaurar a ordem, proteger infraestruturas em ruínas e reprimir ameaças persistentes que ainda assolam as colinas ao redor."},{t="Protegendo as Sepulturas",b="As principais preocupações de Sevren concentram-se na preservação e recuperação dos mortos de Tirisfal. Ladrões de túmulos locais, peles podres e mortos-vivos renegados perturbam os cemitérios, ameaçando o domínio emergente de Sylvana Correventos. Sevren assegura que tumbas ancestrais — como a Cripta da Família Agamand — sejam recuperadas e que desertores ou forças rebeldes não enfraqueçam a autoridade dos Renegados na região."}},faq={{q="Quem é o Magistrado Sevren?",a="O Magistrado Sevren é o líder administrativo de Montalvo, estabelecido na prefeitura. Ele atua como supervisor da gestão territorial dos Renegados, distribuindo tarefas aos aventureiros que chegam de Plangemortis para ajudar o reino recém-formado.",al={"magistrado sevren","quem é sevren","magistrado de montalvo"}},{q="Onde o Magistrado Sevren pode ser encontrado?",a="Ele fica dentro da Prefeitura no centro de Montalvo, nas Clareiras de Tirisfal.",al={"localização de sevren","onde fica o magistrado sevren","encontrar sevren"}},{q="Com quais ameaças o Magistrado Sevren lida?",a="Sevren lida com ameaças locais nas Clareiras de Tirisfal, incluindo gnolls Pele Podre alinhados ao Flagelo saqueando túmulos, remanescentes do Flagelo profanando criptas locais e figuras mortas-vivas renegadas que se recusam a jurar lealdade a Lady Sylvanas.",al={"missões de sevren","o que sevren quer","problemas de montalvo"}},{q="Qual é a lealdade do Magistrado Sevren?",a="Ele é leal aos Renegados e governa Montalvo em nome da Grande Dama Sylvana Correventos e de Cidade Baixa.",al={"facção de sevren","a quem sevren serve"}},{q="Por que Sevren envia aventureiros para a cripta da família?",a="As criptas pertencentes à antiga dinastia Agamand estão infestadas de mortos-vivos e ameaças carniceiras. Sevren exige que os aventureiros protejam os locais de descanso ancestrais para evitar que os inimigos se aproveitem deles.",al={"cripta agamand","missão da cripta de sevren"}},{q="Sevren tem laços com a liderança de Cidade Baixa?",a="Sim. Como magistrado local, ele frequentemente faz a ponte com agentes e autoridades de Cidade Baixa, enviando mensageiros e encaminhando aventureiros mais para o interior da capital assim que sua competência em Montalvo é comprovada.",al={"sevren cidade baixa","sevren raleigh"}}},fx={["54ff886a"]={q="O que o Magistrado Sevren deseja?",a="Como principal autoridade civil de Montalvo, Sevren quer assegurar as Clareiras de Tirisfal para os Renegados. Ele coordena esforços para erradicar o Flagelo remanescente, deter ladrões de túmulos que profanam os locais de descanso dos Renegados e manter linhas claras de comando e suprimentos indo mais fundo no reino.",al={"objetivos do magistrado sevren","motivos de sevren","o que sevren quer"}},["2465c638"]={q="Por que o Magistrado Sevren está em Montalvo?",a="Sevren preside a Prefeitura de Montalvo para supervisionar a administração e a lei local logo do lado de fora dos portões da Cidade Baixa. Ele serve como a principal autoridade municipal, direcionando os Renegados recém-despertados e recém-chegados ao serviço para proteger e organizar o reino.",al={"por que sevren está em montalvo","prefeitura do magistrado sevren","propósito da localização de sevren"}}},fp="17,260,24.369.0,19.396.0,25.236.0,37.78.0,46.220.0,39.102.0,53.204.0,50.212.0"}
P.entries["npc:magistrate-solomon"] = {n="Magistrado Salomão",s="O Magistrado Salomão é o magistrado-chefe de Vila Plácida, presidindo os assuntos locais a partir da prefeitura. Cercado por orcs Blackrock e clãs implacáveis de gnolls, ele passa os dias implorando freneticamente por ajuda militar a uma Ventobravo indiferente e distraída.",h="O Magistrado Salomão é o magistrado-chefe de Vila Plácida, presidindo os assuntos locais a partir da...",kw={"rocha negra","bolvar","vila plácida","magistrado salomão","marris","prestor","montanhas cristarrubra","salomão","prefeitura"},ang={["faction:Alliance"]="O abandono político de Salomão ilustra as profundas fraturas dentro da Aliança de Ventobravo, mostrando como as províncias periféricas são deixadas inteiramente à mercê de heróis independentes.",["race:Dwarf"]="Visitantes anões podem encontrar uma ligação trágica na história de Salomão, já que o esforço de Altaforja para responder ao seu pedido de socorro resultou na emboscada e captura da Princesa Moira Bronzebeard.",["race:Human"]="Para viajantes humanos, falar com Salomão revela a situação sombria do reino fora da segurança das fronteiras interiores da Floresta de Elwynn."},sec={{t="Uma cidade sitiada",b="O Magistrado Salomão governa Vila Plácida durante o momento mais sombrio de sua história recente. O tranquilo assentamento à beira do lago está cercado de hostilidade: gnolls de Montanhas Cristarrubra e Shadowhide rondam as colinas ao redor, enquanto orcs Blackrock descem do norte em bandos de guerra organizados. Salomão trabalha ao lado do Oficial Marris para manter a ordem civil e organizar uma defesa, mas a milícia e os guardas locais de Vila Plácida estão esticados até seu limite absoluto."},{t="Apelos ignorados",b="Desesperado para obter reforços, Salomão enviou mensageiros por todo o reino — implorando por ajuda a Cerro Oeste, Vila Sombria e à própria capital de Ventobravo. Suas petições resultaram em amarga decepção. Cerro Oeste luta sob o jugo da Irmandade Défias, a Floresta do Crepúsculo é consumida por seus próprios terrores rastejantes e Ventobravo se recusa a enviar tropas para a fronteira leste, deixando Vila Plácida inteiramente entregue à própria sorte."},{t="A recusa da corte",b="Quando surgem evidências de que os orcs Blackrock estão aliados à revoada dragônica negra, Salomão encaminha o aviso diretamente ao Grão-lorde Bolvar Fordragon. Apesar da magnitude da ameaça, a conselheira real Lady Katrana Prestor descarta os apelos de Salomão como mero exagero desmedido. Limitado pelo conselho dela e pelas forças dispersas de Ventobravo, Bolvar recusa-se a comprometer o Exército de Ventobravo, concedendo a Salomão apenas autorização real para nomear mercenários independentes."}},faq={{q="Quem é o Magistrado Salomão?",a="O Magistrado Salomão é o líder civil de Vila Plácida e juiz presidente da corte de Vila Plácida. Operando a partir da prefeitura, ele supervisiona assuntos administrativos locais e coordena a defesa desesperada da cidade contra gnolls e orcs invasores.",al={"história do magistrado salomão","quem é salomão","líder de vila plácida"}},{q="Por que Ventobravo não pode enviar tropas para ajudá-lo?",a="As forças militares de Ventobravo já estão sobrecarregadas em várias regiões conturbadas. Quando Salomão apela por ajuda, o Grão-lorde Bolvar Fordragon é fortemente influenciado pela conselheira real Lady Katrana Prestor, que questiona os relatórios de Salomão e desaconselha ativamente o envio de tropas regulares do reino para as Montanhas Cristarrubra.",al={"por que não há exército de ventobravo","por que ventobravo não ajuda vila plácida","ajuda de bolvar a montanhas cristarrubra"}},{q="Altaforja tentou enviar ajuda?",a="Sim. Atendendo ao apelo de Salomão, o Rei Magni Barbabronze enviou um contingente de socorro liderado pela Princesa Moira Bronzebeard. No entanto, a expedição nunca chegou às Montanhas Cristarrubra, tendo sido emboscada e capturada nas Estepes Ardentes.",al={"reforços anões vila plácida","altaforja ajuda montanhas cristarrubra","moira bronzebeard vila plácida"}},{q="Quais ameaças estão afligindo Vila Plácida?",a="Vila Plácida enfrenta pressão simultânea dos gnolls de Montanhas Cristarrubra e Shadowhide, que aterrorizam as colinas e estradas, bem como dos agressivos orcs Blackrock, que realizam incursões ao sul vindos da Bastilha Mirante de Pedra e das Estepes Ardentes.",al={"o que está atacando vila plácida","inimigos de montanhas cristarrubra","por que salomão está preocupado"}},{q="Quem trabalha com Salomão para defender a cidade?",a="Salomão coordena principalmente com o Oficial Marris, que comanda a guarda local da cidade. Como reforços regulares nunca chegam, os dois oficiais são forçados a recrutar e nomear aventureiros viajantes para conter as ameaças invasoras.",al={"defensores de vila plácida","oficial marris e salomão"}},{q="Por que Salomão envia mensageiros para Vila Sombria e Cerro Oeste?",a="Sabendo que a corte de Ventobravo está paralisada, Salomão tenta formar pactos de ajuda mútua com assentamentos vizinhos da Aliança. Infelizmente, Cerro Oeste está paralisada pela Irmandade Défias e Vila Sombria está sobrecarregada pelos mortos-vivos e feras ferozes, impossibilitando que qualquer uma delas ceda um único defensor.",al={"messenger to darkshire","messenger to westfall","salomão ajuda outras cidades"}}},fx={["85afa026"]={q="De que lado está o Magistrado Salomão?",a="Salomão é leal ao Reino de Ventobravo e à Grande Aliança. Como autoridade civil em Vila Plácida, ele responde à corte real na Cidade de Ventobravo, solicitando apoio militar ao Grão-lorde Bolvar Fordragon para proteger seu povo.",al={"facção do magistrado salomão","a quem salomão serve","fidelidade de salomão"}},c7aa651d={q="O que o Magistrado Salomão deseja?",a="Salomão busca desesperadamente ajuda militar e recursos para defender Vila Plácida da destruição iminente. Cercado por matilhas agressivas de gnolls e pelos orcs Rocha Negra que avançam, ele quer reforços de Ventobravo e assentamentos vizinhos — ou aventureiros capazes dispostos a levar a luta ao inimigo.",al={"objetivo de salomão","do que salomão precisa","motivação do magistrado salomão"}},dc9ff3b9={q="Por que o Magistrado Salomão está aqui em Vila Plácida?",a="Salomão preside na prefeitura de Vila Plácida porque é o magistrado da cidade e o juiz do Tribunal de Vila Plácida. Ele permanece em seu posto apesar do perigo crescente, gerenciando os assuntos locais e organizando a defesa das Montanhas Cristarrubra.",al={"por que solomão está em cristarrubra","papel de solomão em vila plácida","trabalho do magistrado solomão"}}},fp="18,263,18.445.0,20.447.0,19.458.1,26.249.0,44.300.1,31.224.1,37.213.0,42.241.0,57.292.0"}
P.entries["npc:magni-bronzebeard"] = {n="Magni Barbabronze",s="Magni Barbabronze é o Senhor de Altaforja, Thane do clã Barbabronze e governante de Khaz Modan. Um comandante veterano da Segunda Guerra, ele lidera seu reino montanhoso em meio ao luto e à tensão política, enquanto defende a arqueologia dos anões por toda Azeroth.",h="Magni Barbabronze é o Senhor de Altaforja, Thane do clã Barbabronze e governante de Khaz Modan.",kw={"brann","barbabronze","liga dos exploradores","altaforja","khaz modan","magni","moira","muradin"},ang={["faction:Alliance"]="Um fundador leal da Grande Aliança ao lado de Lordaeron e Ventobravo, Magni fornece força marcial, proeza de engenharia e lealdade inabalável à coalizão.",["profession:Blacksmithing"]="A Grande Bigorna queima no coração da cidade de Magni, e os ferreiros que trabalham sob o governo do rei estão entre os melhores da Aliança.",["race:Dwarf"]="Magni é o seu soberano indiscutível e o protetor de Khaz Modan, liderando o clã Barbabronze através de guerras externas e da busca interna pela herança ancestral de sua raça.",["race:Gnome"]="O Rei Magni ofereceu sua cidade como refúgio para os sobreviventes de Gnomeregan, mantendo uma estreita amizade e aliança tecnológica com o Grão-geringoncheiro Mekkatorque."},sec={{t="Senhor da Montanha",b="O mais velho de três irmãos, Magni cresceu profundamente ciente do peso que o aguardava sob a montanha. Quando a Horda invadiu durante a Segunda Guerra, ele manteve Altaforja atrás de seus portões impenetráveis, emergindo para comprometer Khaz Modan com a Aliança de Lordaeron assim que o cerco foi quebrado. Nos anos de paz que se seguiram, Magni acolheu seus aliados gnomos na cidade após a queda de Gnomeregan, concedendo refúgio ao Grão-geringoncheiro Gelbin Mekkatorque e aos seus refugiados no interior da montanha. Para unir os reinos fraturados do sul e do norte, Magni solicitou a Mekkatorque que projetasse uma maravilha subterrânea sem precedentes: o Metrô Correfundo, conectando Altaforja diretamente a Ventobravo."},{t="Um Irmão Perdido",b="Sob o porte régio de Magni repousa uma profunda tragédia pessoal. Durante a Terceira Guerra, chegaram notícias de Northrend de que seu amado irmão mais novo, Muradin, havia perecido na expedição do Príncipe Arthas Menethil. Magni foi tomado pelo luto, mas ele e seu irmão caçula, Brann, permaneceram firmes em seu dever para com o povo anão, e o rei ainda governa com sabedoria com essa tristeza pesando sobre ele."},{t="Escavando o Passado",b="Sob o decreto de Magni, a sociedade dos anões desviou grande parte de seu foco da mineração comercial tradicional para a revelação da história antiga. Estimulado por descobertas de estranhas relíquias dos titãs nas profundezas da terra, Magni cofundou a Liga dos Exploradores ao lado de seu irmão sobrevivente, Brann Barbabronze. Locais de escavação dos anões agora pontilham os continentes, de Dun Morogh a Kalimdor, lutando para desvendar o mistério das origens lendárias dos anões. No entanto, a paz doméstica permanece frágil: a filha de Magni, a Princesa Moira, desapareceu, e acredita-se que tenha sido sequestrada pelo odiado clã Ferro Negro."}},faq={{q="Quem é Magni Barbabronze?",a="Magni Barbabronze é o Rei de Khaz Modan, Thane de Altaforja e chefe do clã Barbabronze. Ele governa o reino da montanha a partir d'A Sala do Trono em Altaforja e é um dos pilares firmes da Grande Aliança.",al={"rei de altaforja","rei anão","quem é magni"}},{q="Quem forjou A Crematória?",a="Nenhum relato sobre a forja da lâmina é mantido nos registros de Altaforja. A Crematória é lembrada como a espada do Alto-senhor Alexandros Mograine do Punho de Prata, e nada registrado vincula sua confecção ao Rei Magni.",al={"magni criou a crematória","criador da crematória","quem criou a crematória"}},{q="O que aconteceu com os irmãos de Magni?",a="Magni é o mais velho de três irmãos. Seu irmão Muradin serviu como embaixador da Aliança em Lordaeron e foi dado como morto pelo Príncipe Arthas em Northrend. Seu irmão mais novo, Brann, é um renomado explorador que viaja pelos cantos mais distantes do mundo liderando a Liga dos Exploradores.",al={"muradin e brann","irmãos de magni","destino de muradin barbabronze"}},{q="Onde está a Princesa Moira?",a="A Princesa Moira Barbabronze, a única filha de Magni, desapareceu de Altaforja. Relatos oficiais dentro da montanha sustentam que ela foi sequestrada pelos hostis anões Ferro Negro e está sendo mantida em cativeiro nas profundezas da Montanha Rocha Negra.",al={"filha de magni","onde está moira","o que aconteceu com moira barbabronze"}},{q="Por que os gnomos estão vivendo em Altaforja?",a="Após a invasão dos troggs e a terrível irradiação de Gnomeregan, o Rei Magni abriu os portões de Altaforja para o Grão-geringoncheiro Gelbin Mekkatorque e os sobreviventes gnomos. Magni concedeu a eles um distrito inteiro da cidade, hoje conhecido como Beco da Gambiarra.",al={"beco da gambiarra","por que há gnomos na cidade dos anões","refugiados gnomos altaforja"}},{q="O que é a Liga dos Exploradores?",a="A Liga dos Exploradores é uma organização arqueológica fundada pelo Rei Magni e seu irmão Brann. Após descobrir antigas ruínas titânicas, Magni direcionou as indústrias dos anões para desvendar a verdade por trás das origens de sua raça, enviando equipes de prospecção por toda Azeroth.",al={"guilda dos exploradores","arqueólogos anões","por que os anões estão escavando"}}},fp="17,261,20.683.0,14.398.0,19.585.0,25.222.0,26.212.0,34.283.0,24.239.0,35.242.0,30.267.0"}
P.entries["npc:magus-rimtori"] = {n="Maga Rimtori",s="A Maga Rimtori é uma feiticeira elfa sangrenta renegada que lidera uma expedição em meio às antigas ruínas de Azshara. Conhecida por sua traição implacável, ela manipulou a Horda para garantir sua passagem por Kalimdor antes de massacrar sua escolta órquica.",h="A Maga Rimtori é uma feiticeira elfa sangrenta renegada que lidera uma expedição em meio às antigas ruínas de...",kw={"azshara","belgrom","elfo sangrento","hawkhelm","kim'jael","maga rimtori","rimtori","base darnassiana"},ang={["class:Mage"]="Rimtori demonstra os extremos a que os magos thalassianos chegam em sua busca desesperada por poder arcano, vasculhando as ruínas e relíquias demoníacas de Kalimdor.",["faction:Horde"]="Rimtori manipulou Belgrom e massacrou a guarda orc destacada para escoltá-la, tornando seu assassinato uma prioridade máxima para guerreiros da Horda que buscam vingar seus irmãos caídos."},sec={{t="Um Engano Mortal",b="A Maga Rimtori liderou uma expedição de elfos sangrentos nobres através do mar até as antigas costas de Azshara. Para garantir que seu grupo sobrevivesse aos perigos de Kalimdor, ela manipulou o orc Belgrom, encantando-o e enganando-o até que ele concordasse em fornecer uma escolta armada. Assim que os soldados a entregaram em segurança ao seu destino, Rimtori revelou suas verdadeiras intenções, voltando-se contra seus protetores e massacrando toda a guarnição. Estabelecendo suas forças na Base Darnassiana, ela se aventurou pelas terras ermas costeiras acompanhada por guarda-costas de elite para caçar artefatos mágicos esquecidos."},{t="Segredos das Ruínas",b="O verdadeiro motivo que impulsiona a expedição de Rimtori permanece envolto em mistério, embora seus métodos implacáveis tenham lhe rendido incontáveis inimigos. Além de trair a Horda, ela também enganou mercenários locais, incluindo o topógrafo goblin Kim'jael, que afirma que ela estava obcecada em desenterrar uma runa antiga. Cercada por relíquias como um tomo de evocação demoníaca deixado para trás em seu acampamento, a busca de Rimtori por poder atraiu a feroz retaliação da Horda que ela tão friamente traiu."}},faq={{q="Por que a Horda quer Rimtori morta?",a="Rimtori encantou e manipulou o orc Belgrom para fornecer à sua expedição uma escolta militar através de Kalimdor. Uma vez que chegaram em segurança a Azshara, ela traiu e massacrou cada um dos soldados orcs sob o comando de Belgrom.",al={"por que matar rimtori","história de belgrom e rimtori","o que rimtori fez com a horda"}},{q="Onde a Maga Rimtori pode ser encontrada?",a="Enquanto sua expedição estabeleceu a Base Darnassiana, a própria Rimtori vagueia pelas terras ermas de Azshara acompanhada por seus guarda-costas pessoais elfos sangrentos enquanto procura por relíquias antigas.",al={"localização de rimtori","onde fica a maga rimtori","localização de rimtori em azshara"}},{q="O que Rimtori estava procurando em Azshara?",a="De acordo com o goblin Kim'jael, a quem ela contratou e depois traiu, Rimtori estava obsessivamente caçando uma misteriosa runa antiga, além de outras relíquias potentes, como um tomo de invocação Kaldorei.",al={"o que rimtori quer","objetivo de rimtori em azshara","runa de rimtori"}},{q="Quem é o Magister Hawkhelm?",a="O Magister Hawkhelm é um oficial elfo sangrento encarregado pela Maga Rimtori de comandar e supervisionar a Base Darnassiana enquanto ela investiga as ruínas vizinhas.",al={"hawkhelm","líder do acampamento thalassiano","magister hawkhelm rimtori"}}},fp="13,241,18.585.0,20.485.1,37.236.0,33.191.0,42.198.0,25.163.0"}
P.entries["npc:mai-ah"] = {n="Mai'ah",s="Mai'ah é uma instrutora de magos troll da selva posicionada na bacia escaldante do Vale das Provações em Durotar. Ela orienta conjuradores iniciantes entre os Trolls Lançanegra que entram nos cânions vermelhos para aprimorar seu domínio do arcano. Para jovens trolls que iniciam o caminho da feitiçaria, ela oferece orientação inicial e instrução nas artes fundamentais da magia.",h="Mai'ah é uma instrutora de magos troll da selva posicionada na bacia escaldante do Vale das Provações em...",kw={"lançanegra","durotar","instrutor de mago","mai'ah","maiah","troll","vale das provações"},ang={["class:Mage"]="Para os conjuradores dos Trolls Lançanegra, Mai'ah representa o início de sua jornada mágica, ensinando a disciplina necessária para tecer fogo, gelo e energia arcana sob o sol forte de Durotar.",["race:Troll"]="Mai'ah fornece aos jovens dos Trolls Lançanegra no Vale das Provações mentoria cultural em uma arte raramente praticada por seus aliados orcs."},sec={{t="Mentora Arcana do Covil",b="Embora os orcs prefiram esmagadoramente o chamado primal dos elementos ou o domínio físico do guerreiro, os Trolls Lançanegra possuem uma rara afinidade pelo estudo arcano. Posicionada no Vale das Provações, Mai'ah atua como instrutora para jovens magos troll que chegam para realizar seus ritos de idade adulta. Ela recebe candidatos portando inscrições glíficas e começa a moldar seu poder bruto e caótico em encantamentos disciplinados, garantindo que eles aprendam o controle necessário para sobreviver aos perigos de Durotar."}},faq={{q="Quem é Mai'ah?",a="Mai'ah é uma instrutora de magos dos Trolls Lançanegra situada no Vale das Provações em Durotar. Ela fornece orientação inicial, treinamento e feitiços fundamentais para conjuradores troll recém-chegados antes que eles se aventurem pelas terras mais amplas da Horda.",al={"quem é maiah","história de maiah","instrutor de mago troll"}},{q="Por que há uma instrutora de magos troll em uma área inicial orc?",a="Depois que os Trolls Lançanegra fugiram de sua ilha natal submersa e se reassentaram em Durotar junto aos orcs de Thrall, os jovens Trolls Lançanegra realizam seus julgamentos de maioridade junto aos jovens orcs. Como a cultura orc evita amplamente a magia arcana devido à corrupção demoníaca do passado, magos troll como Mai'ah intervêm para guiar os da sua própria espécie.",al={"por que mago troll aqui","instrutor troll do vale das provações","mago troll durotar"}},{q="Qual papel ela desempenha no treinamento de novos magos?",a="Mai'ah recebe novos magos troll que trazem instruções escritas, como Glyphic Parchment. Ela inicia seu treinamento formal, ensinando os fundamentos da conjuração para que eles possam defender o Vale das Provações das feras locais e dos infiltrados renegados da Lâmina Ardente.",al={"o que maiah faz","glyphic parchment maiah","missões de maiah"}}},fx={["4a36b72a"]={q="De que lado Mai'ah está?",a="Mai'ah é leal à tribo Lançanegra e à Horda. Estacionada no Vale das Provações, ela trabalha sob o novo regime do Chefe Guerreiro Thrall para promover os futuros conjuradores da Horda, dedicando seu conhecimento arcano a fortalecer jovens magos trolls e aliados.",al={"fidelidade de mai'ah","a quem mai'ah serve","mai'ah é horda"}},["648de549"]={q="O que Mai'ah deseja?",a="Mai'ah deseja treinar aspirantes a praticantes nos fundamentos do arcano. Ela busca guiar jovens novatos através de seus feitiços e glifos introdutórios, garantindo que eles possuam a disciplina e o poder mágico necessários para sobreviver em Durotar e servir à Horda.",al={"do que mai'ah precisa","objetivos de mai'ah","por que mai'ah ensina"}}},fp="6,368,24.501.0,14.245.0,58.314.0,46.263.0"}
P.entries["npc:major-mattingly"] = {n="Major Valadão",s="O Major Valadão é um oficial veterano do Exército de Ventobravo posicionado nos grandes portões no Vale dos Heróis. Servindo sob o comando do General Marcus Jonas, ele ajuda a proteger a entrada principal da capital e orienta artesãos habilidosos sobre como proteger heróis contra ameaças dracônicas.",h="O Major Valadão é um oficial veterano do Exército de Ventobravo posicionado nos grandes portões no Vale dos...",kw={"manto de escama de dragão","marcus jonas","major valadão","valadão","exército de ventobravo","vale dos heróis"},ang={["class:Warrior"]="Como um veterano disciplinado empunhando sua espada longa nos portões da cidade, Valadão representa a determinação inabalável dos oficiais de infantaria do Exército de Ventobravo.",["faction:Alliance"]="Para os campeões da Aliança que buscam desafiar grandes dragões como Onyxia, o Major Valadão fornece a orientação crucial necessária para confeccionar mantos defensivos a partir de escamas de dragão."},sec={{t="Sentinela dos Portões da Capital",b="Montando guarda no Vale dos Heróis, o Major Valadão é um dos oficiais de alta patente diretamente responsáveis pela principal defesa terrestre de Ventobravo. Um soldado veterano e grisalho, cujo rosto traz as marcas de uma experiência conquistada a duras penas, ele serve sob o comando do General Marcus Jonas ao lado da guarnição permanente da cidade. Além de seus deveres diários de supervisionar as patrulhas dos portões e os viajantes que chegam, Valadão possui conhecimento tático especializado sobre a natureza letal dos dragões. Ele é reconhecido por aventureiros experientes como um contato vital para aprender a criar equipamentos protetores de escama de dragão, necessários para desbravar os covis mais mortais do reino."}},faq={{q="Onde o Major Valadão pode ser encontrado?",a="O Major Valadão está posicionado perto da entrada de Ventobravo, no Vale dos Heróis, montando guarda ao lado de outros soldados da guarnição logo na parte interna dos portões principais.",al={"localização de valadão","onde fica o major valadão","encontrar major valadão"}},{q="Qual é a patente e o papel do Major Valadão em Ventobravo?",a="Ele é um oficial do Exército de Ventobravo que serve sob o comando do General Marcus Jonas. Ele ajuda a supervisionar a defesa dos portões da cidade e oferece orientação militar aos aventureiros.",al={"quem é valadão","função de valadão","o que faz valadão"}},{q="Por que os coureiros procuram o Major Valadão?",a="Valadão possui instruções sobre como tratar e confeccionar mantos de escamas a partir de couro de dragão negro, orientando artesãos habilidosos que desejam proteger seus aliados das chamas dracônicas.",al={"manto de escama da onyxia valadão","missão de valadão","a jornada está apenas começando valadão"}},{q="O Major Valadão está envolvido em conflitos mais amplos?",a="Ele é um veterano calejado de batalha do Reino de Ventobravo, dedicado à defesa do reino enquanto o Rei Varian Wrynn permanece desaparecido e o reino lida com ameaças persistentes.",al={"história de valadão","lore de valadão"}}},fx={["3133ea98"]={q="De que lado está o Major Valadão?",a="O Major Valadão é totalmente devotado ao Reino de Ventobravo e à Aliança. Como oficial do Exército de Ventobravo, ele responde diretamente ao General Marcus Jonas e vigia a grande entrada da capital, leal ao trono e à defesa do reino.",al={"facção de valadão","a quem valadão serve","fidelidade do major valadão"}},["3a90c3f3"]={q="Por que o Major Valadão está estacionado no Vale dos Heróis?",a="Ele está estacionado nos portões dentro do Vale dos Heróis para supervisionar a principal linha de defesa da capital. Abaixo dos monumentos imponentes aos heróis da Segunda Guerra, Valadão ajuda a comandar a guarda da guarita, garantindo que nenhuma força hostil marche através dos portões sem ser desafiada.",al={"por que valadão está aqui","valadão vale dos heróis por que","o que valadão está fazendo em ventobravo"}},["728996ed"]={q="A quem o Major Valadão está ligado?",a="O Major Valadão serve diretamente sob o General Marcus Jonas dentro da cadeia de comando do Exército de Ventobravo. Ele também compartilha o sobrenome com Janice Mattingly, uma residente da cidade, embora seus deveres diários permaneçam estritamente ligados ao seu posto militar e oficial comandante.",al={"comandante de valadão","a quem valadão responde","conexões do major valadão"}}},fp="15,284,29.642.0,35.165.0,53.173.0,47.173.0,53.187.0"}
P.entries["npc:major-samuelson"] = {n="Major Samuelson",s="O Major Samuelson é um oficial de alta patente da Guarda de Ventobravo posicionado na sala do trono de Bastilha Ventobravo. Como um comandante militar experiente, ele supervisiona assuntos cruciais de pessoal e anteriormente foi mentor de oficiais subalternos, como o Tenente Fárrio Orinelle.",h="O Major Samuelson é um oficial de alta patente da Guarda de Ventobravo posicionado na sala do trono de...",kw={"fárrio orinelle","major samuelson","transferência","samuelson","costa sul","guarda de ventobravo","bastilha ventobravo"},ang={["faction:Alliance"]="Servindo na sala do trono real, o Major Samuelson representa a espinha dorsal administrativa das forças armadas de Ventobravo, direcionando o pessoal por territórios disputados como Eira dos Montes."},sec={{t="Um Pilar da Guarda de Ventobravo",b="Posicionado dentro de Bastilha Ventobravo diante da corte real, o Major Samuelson representa a liderança da Guarda de Ventobravo. Ele supervisiona alocações de oficiais e ordens militares administrativas por todo o reino. Notavelmente, ele foi mentor do Tenente Fárrio Orinelle, um oficial destacado bem ao norte, em Costa Sul, no Contraforte de Eira dos Montes. Quando comandantes subalternos se veem sobrecarregados ou buscam transferência de guarnições distantes na fronteira, seus pedidos e relatórios oficiais viajam diretamente pelo reino até a mesa do Major Samuelson na capital."}},faq={{q="Quem é o Major Samuelson?",a="O Major Samuelson é um oficial da Guarda de Ventobravo posicionado na sala do trono de Bastilha Ventobravo. Ele atua como um comandante administrativo lidando com destacamentos de oficiais e pessoal.",al={"samuelson","identidade de major samuelson","quem é o major na fortaleza"}},{q="Onde o Major Samuelson pode ser encontrado?",a="Ele fica dentro de Bastilha Ventobravo, em Ventobravo, na sala do trono, perto do jovem rei Anduin Wrynn e do Grão-lorde Bolvar Fordragon.",al={"localização de samuelson","onde fica major samuelson","encontrar samuelson"}},{q="Qual é a ligação dele com Costa Sul?",a="O Major Samuelson serviu como mentor do Tenente Fárrio Orinelle, um oficial alocado em Costa Sul, no Contraforte de Eira dos Montes. Orinelle tenta obter uma transferência desse estressante posto no norte por meio de Samuelson.",al={"samuelson costa sul","mentor do tenente fárrio orinelle","samuelson eira dos montes"}},{q="Por que os aventureiros procuram por ele?",a="Aventureiros vindos do fronte norte em Eira dos Montes levam o pedido oficial de transferência do Tenente Fárrio Orinelle para o Major Samuelson em Bastilha Ventobravo.",al={"entrega de missão ventobravo","missão de transferência","por que falar com samuelson"}}},fx={["75428c69"]={q="De que lado o Major Samuelson está?",a="O Major Samuelson serve ao Reino de Ventobravo e à Aliança. Como oficial da Guarda da Cidade de Ventobravo estacionado diretamente dentro da Bastilha Ventobravo, seu dever é defender a capital, manter a ordem militar e cumprir os comandos da liderança da cidade.",al={"facção de samuelson","a quem o major samuelson serve","samuelson é aliança"}}},fp="15,271,29.546.0,23.190.0,35.148.0,37.215.0,32.165.0"}
P.entries["npc:makaba-flathoof"] = {n="Makaba Casco Chato",s="Makaba Casco Chato é um sobrevivente tauren originário da Aldeia Apareje, na Cordilheira das Torres de Pedra. Tendo testemunhado a devastação de seu lar e de seu povo pelas mãos do clã Grimtotem, ele busca bravos campeões da Horda para vingar-se dos atacantes e garantir a segurança de sua família.",h="Makaba Casco Chato é um sobrevivente tauren originário da Aldeia Apareje, na Cordilheira das Torres de Pedra.",kw={"aldeia apareje","flathoof","grimtotem","grundig darkcloud","kaya","makaba","cordilheira das torres de pedra"},ang={["faction:Horde"]="Os apelos de ajuda de Makaba permitem que os campeões da Horda provem sua lealdade aos seus aliados taurens, punindo aqueles que massacram acampamentos pacíficos.",["race:Tauren"]="Para os heróis taurens, o sofrimento de Makaba destaca a amarga traição dos Grimtotem, servindo como um lembrete de que nem todos os seus semelhantes honram os caminhos da paz e da união."},sec={{t="Tragédia na Aldeia Apareje",b="Makaba Casco Chato representa o custo trágico do conflito interno entre os taurens. Seu lar, a Aldeia Apareje, na Cordilheira das Torres de Pedra, foi vítima de um ataque surpresa impiedoso do clã Grimtotem. Enquanto muitos taurens buscam a paz e a união sob a liderança de Caerne Casco Sangrento, os traiçoeiros Grimtotem semeiam continuamente discórdia e violência, deixando sobreviventes como Makaba desabrigados e em luto."},{t="Um Apelo por Vingança",b="Incapaz de retomar seu assentamento destruído sozinho, Makaba conclama os viajantes da Horda a contra-atacar. Ele orienta uma retaliação feroz contra os renegados Grimtotem que invadiram seu lar, exigindo justiça pelo massacre de seus parentes. Sua preocupação mais urgente é o senhor da guerra responsável, Grundig Darkcloud; sua filha, Kaya, ele acredita ter se perdido no ataque."}},faq={{q="Quem é Makaba Casco Chato?",a="Makaba Casco Chato é um refugiado tauren da Aldeia Apareje, na Cordilheira das Torres de Pedra. Sua aldeia foi invadida e saqueada pelo clã Grimtotem, levando-o a buscar ajuda de aventureiros da Horda.",al={"makaba","quem é makaba casco chato","história de makaba casco chato"}},{q="De onde veio Makaba?",a="Makaba é originário da Aldeia Apareje, um pequeno assentamento tauren localizado na Cordilheira das Torres de Pedra que foi atacado e devastado pelos Grimtotem.",al={"origem de makaba","de onde é makaba","aldeia apareje makaba"}},{q="Quem atacou a aldeia de Makaba?",a="A Aldeia Apareje foi saqueada pelo clã Grimtotem, uma facção agressiva e traiçoeira de taurens liderada localmente por figuras como Grundig Darkcloud.",al={"quem atacou a aldeia apareje","inimigos de makaba","quem saqueou apareje"}},{q="O que Makaba quer que os aventureiros da Horda façam?",a="Makaba busca vingança por seu lar destruído, pedindo a guerreiros capazes que abatam as forças Grimtotem na Aldeia Apareje e eliminem seu líder, Grundig Darkcloud.",al={"missões de makaba","o que makaba pede","tarefas de makaba"}},{q="Quem é Kaya para Makaba?",a="Kaya Casco Chato é filha de Makaba. Ela desapareceu durante o ataque à Aldeia Apareje, e sua família acredita que ela tenha se perdido no ataque.",al={"kaya casco chato","quem é kaya","parente de makaba kaya"}},{q="Makaba é parente de Dim Flathoof?",a="Makaba e Dim compartilham o sobrenome Flathoof, mas um parentesco familiar entre eles não está confirmado.",al={"dim flathoof","makaba e dim","família flathoof"}}},fx={["586aa360"]={q="De que lado Makaba Casco Chato está?",a="Makaba Casco Chato é um membro leal da Horda e do povo tauren. Fugindo da violência que atingiu seu lar, ele busca assistência exclusivamente de viajantes e campeões da Horda para proteger seus parentes e contra-atacar seus agressores.",al={"facção de makaba casco chato","makaba é horda","a quem makaba serve"}},["6e0e5223"]={q="Por que Makaba Casco Chato está aqui?",a="Makaba refugiou-se na Cordilheira das Torres de Pedra depois que a tragédia atingiu seu lar na Aldeia Apareje. Expulso de seu assentamento por invasores violentos, ele agora permanece aqui buscando ajuda para vingar seus parentes caídos e garantir a segurança dos sobreviventes como Kaya.",al={"por que makaba casco chato está aqui","por que makaba está em torres de pedra","propósito de makaba casco chato"}}},fp="15,291,23.401.0,20.357.1,23.189.0,27.144.0,30.141.0,46.163.0,22.136.0,34.97.0"}
P.entries["npc:malfurion-stormrage"] = {n="Malfurion Tempesfúria",s="Malfurion Tempesfúria é o primeiro druida mortal e o reverenciado líder dos elfos noturnos ao lado da Alta-sacerdotisa Tyrande Murmuréolo. Reconhecido por derrotar a Legião Ardente tanto na Guerra dos Antigos quanto na Terceira Guerra, ele é venerado como o Shan'do, ou professor honrado. Atualmente, jaz preso em um sono comatoso dentro do Sonho Esmeralda, deixando os kaldorei sem sua liderança desperta.",h="Malfurion Tempesfúria é o primeiro druida mortal e o reverenciado líder dos elfos noturnos ao lado da...",kw={"arquidruida","cenarius","sonho esmeralda","furion","hyjal","illidan","malfurion","shan'do","tempesfúria","tyrande"},ang={["class:Druid"]="Todos os druidas traçam seus ensinamentos até Malfurion, que aprendeu diretamente com Cenarius. Sua ausência no Sonho Esmeralda lança uma pesada sombra sobre o Círculo Cenariano.",["class:Priest"]="Malfurion é o amado parceiro da Alta-sacerdotisa Tyrande Murmuréolo, unindo a devoção espiritual de Eluna à sagrada tutela da natureza.",["race:NightElf"]="Malfurion é reverenciado como o antigo protetor e salvador do seu povo, embora seu sono contínuo deixe o governo inteiramente a cargo de Tyrande e do Arquidruida Fandral Guenelmo."},sec={{t="O Primeiro Druida",b="Dez mil anos atrás, antes de a Grande Cisão despedaçar a antiga Kalimdor, Malfurion estudou com o semideus Cenarius. Enquanto a Rainha Azshara e sua casta de Altaneiros se aprofundavam perigosamente nas energias arcanas da Nascente da Eternidade, Malfurion voltou-se para as forças primordiais da natureza, tornando-se o primeiro druida mortal de Azeroth. Suas suspeitas sobre os Altaneiros provaram-se tragicamente corretas quando a feitiçaria imprudente de Azshara rompeu o véu e invocou Sargeras e a Legião Ardente para Azeroth, desencadeando a catastrófica Guerra dos Antigos."},{t="Salvador de Kalimdor",b="Ao lado de Cenarius, Tyrande Murmuréolo e seu irmão gêmeo Illidan, Malfurion liderou a resistência que conteve a investida demoníaca e fechou o portal sobre a Nascente da Eternidade. Após o despedaçamento do mundo, Malfurion comprometeu os druidas com o Sonho Esmeralda para reconstruir e proteger a tapeçaria viva de Azeroth. Dez milênios depois, Tyrande o despertou de seu longo sono nos túmulos para enfrentar Arquimonde durante a Terceira Guerra, quando ele reuniu os espíritos da floresta no Monte Hyjal para estilhaçar a Legião Ardente mais uma vez."},{t="Perdido no Sonho",b="Após a Terceira Guerra, Malfurion retornou ao seu sono na Clareira da Lua para comungar com o Sonho Esmeralda e reabastecer seu poder exaurido. No entanto, seu espírito não conseguiu retornar ao seu corpo físico, mergulhando-o em um estado comatoso e antinatural. Em Darnassus, o Arquidruida Fandral Guenelmo assumiu os deveres temporais de liderança no Círculo Cenariano, enquanto Tyrande e a irmandade vigiam ansiosamente por sinais do despertar de seu grande Shan'do."}},faq={{q="Onde está Malfurion Tempesfúria agora?",a="Malfurion está fisicamente adormecido nos refúgios subterrâneos da Clareira da Lua, enquanto sua consciência permanece presa nas profundezas do reino espiritual do Sonho Esmeralda. Ele não pode ser visitado como um PNJ ativo em Darnassus, já que seu corpo jaz comatoso e inacessível para a maioria dos aventureiros.",al={"onde está malfurion","onde encontrar malfurion","localização de malfurion","malfurion está no jogo"}},{q="Por que Malfurion está dormindo?",a="Os druidas hibernam com frequência dentro do Sonho Esmeralda para comungar com a natureza, sustentar a flora e a fauna do mundo e restaurar sua força espiritual. Após o imenso desgaste mágico para derrotar Arquimonde no Monte Hyjal, Malfurion entrou no Sonho para se recuperar, mas um mal-estar antinatural separou seu espírito de seu corpo.",al={"por que malfurion está dormindo","por que ele está em coma","o que aconteceu com malfurion"}},{q="Quem governa os elfos noturnos enquanto Malfurion dorme?",a="A Alta-sacerdotisa Tyrande Murmuréolo governa a nação kaldorei a partir d'O Templo da Lua em Darnassus, liderando as Sentinelas e a Irmandade de Eluna. Enquanto isso, o Círculo Cenariano e os assuntos druídicos são supervisionados pelo Arquidruida Fandral Guenelmo.",al={"quem lidera os elfos noturnos","quem é o líder dos elfos noturnos","governante dos elfos noturnos"}},{q="O que significa 'Shan'do'?",a="Em darnassiano, 'Shan'do' traduz-se como 'professor honrado'. É um título de suprema reverência reservado a mestres druidas, mais notavelmente Malfurion Tempesfúria, que introduziu pela primeira vez o druidismo às raças mortais sob a tutela de Cenarius.",al={"significado de shando","o que é shando","shan'do"}},{q="Quem é o irmão de Malfurion?",a="O irmão gêmeo de Malfurion é Illidan Tempesfúria. Apesar de terem compartilhado a juventude em Suramar, a obsessão de Illidan pela magia arcana e sua busca imprudente por poder demoníaco causaram uma amarga ruptura entre eles durante a Guerra dos Antigos, levando Malfurion a aprisioná-lo por milênios.",al={"irmão de malfurion","quem é illidan para malfurion","irmãos tempesfúria"}},{q="O que Malfurion fez na Batalha do Monte Hyjal?",a="Durante o clímax da Terceira Guerra, Malfurion tocou a Trompa de Cenarius na Árvore do Mundo Nordrassil, convocando milhares de espíritos ancestrais da floresta (fispas). Esses espíritos cercaram o lorde demônio Arquimonde e detonaram, destruindo o demônio e imolando a Árvore do Mundo para salvar Kalimdor.",al={"malfurion hyjal","batalha do monte hyjal malfurion","como malfurion derrotou arquimonde"}}},fx={["65d9a7b2"]={q="Quem é Malfurion Tempesfúria?",a="Malfurion Tempesfúria é o primeiro druida mortal em Azeroth e o arquidruida supremo dos elfos noturnos. Treinado dez mil anos atrás pelo semideus Cenarius, ele guiou seu povo através da cataclísmica Guerra dos Antigos contra a Rainha Azshara e a Legião Ardente. Ao lado de sua amada, a Alta Sacerdotisa Tyrande Murmuréolo, ele liderou os kaldorei por milênios, servindo como seu guia espiritual e o maior defensor do mundo natural.",al={"quem é malfurion","quem é furion","lore de malfurion tempesfúria"}},af86ea6f={q="De que lado Malfurion Tempesfúria está?",a="Malfurion está, acima de tudo, ao lado de seu povo, os kaldorei, e do Círculo Cenariano, dedicado a preservar a ordem natural de Azeroth. Através dos pactos recentes dos elfos noturnos, seu povo está alinhado com a Grande Aliança, embora a devoção final de Malfurion transcenda disputas políticas mesquinhas — seu dever vitalício é proteger o equilíbrio da natureza e salvaguardar o Sonho Esmeralda da corrupção.",al={"facção de malfurion","malfurion é aliança","qual facção é malfurion"}},["1592db0d"]={q="O que Malfurion Tempesfúria deseja?",a="Acima de tudo, Malfurion busca proteger o delicado equilíbrio natural de Azeroth e manter o Sonho Esmeralda a salvo de forças sombrias. Tendo sacrificado tanto ao longo de dez mil anos para curar a terra marcada e subjugar incursões demoníacas, sua vida está ligada à preservação da natureza selvagem, ao cuidado com a Árvore do Mundo e a guiar os elfos noturnos por um caminho em harmonia com a natureza.",al={"objetivo de malfurion","quais são os objetivos de malfurion","propósito de malfurion"}}},fp="19,403,15.549.0,18.530.0,17.461.0,39.270.0,24.330.0,49.248.0,25.229.0,27.276.0,51.294.0"}
P.entries["npc:mangletooth"] = {n="Denterroto",s="Denterroto é um javatusco Razormane aprisionado pela Horda dentro do Acampamento Taurajo. Diante da execução, ele negocia informações estratégicas sobre seus rivais e o conhecimento ancestral de Agamaggan com aventureiros dispostos a cumprir suas ordens.",h="Denterroto é um javatusco Razormane aprisionado pela Horda dentro do Acampamento Taurajo.",kw={"agamaggan","sertões","blood shards","bristleback","acampamento taurajo","denterroto","javatusco","razormane"},ang={["faction:Horde"]="Os guardas do Acampamento Taurajo mantêm Denterroto engaiolado sob vigilância constante, mas a Horda está disposta a explorar os profundos ressentimentos do prisioneiro para esmagar os bastiões de javatuscos por todos os Sertões.",["race:Tauren"]="Caçadores taurins entram em conflito constante com os javatuscos por território pelas planícies, fazendo com que a disposição de Denterroto de se voltar contra a própria espécie seja um recurso militar valioso, ainda que inquietante."},sec={{t="Um refém acorrentado",b="Mantido em uma jaula no Acampamento Taurajo por caçadores taurins e sentinelas orcs, Denterroto é um javatusco Razormane capturado que aguarda a execução. Em vez de se resignar à morte, ele tenta manipular seus captores e os aventureiros da Horda que visitam o local para abater os inimigos de sua tribo, na esperança de que sua astúcia prove seu valor ou garanta seu resgate."},{t="Traição intestina",b="Denterroto inicialmente planeja conquistar a gratidão de seu clã direcionando a força da Horda contra a tribo rival Bristleback. No entanto, ele logo percebe que seus companheiros líderes Razormane — Nak, Kuz e Lok Orcbane — o abandonaram completamente para apodrecer. Furioso com a traição deles, o javatusco cativo volta sua vingança contra a própria espécie, orientando aventureiros a executar seus antigos aliados."},{t="O poder dos Blood Shards",b="Profundo conhecedor da história religiosa de seu povo, Denterroto sabe que os espinhos colossais espalhados pelos Sertões brotaram do sangue derramado de Agamaggan durante a antiga Guerra dos Antigos. Ao coletar Blood Shards de cristal vermelho deixados por Bristlebacks derrotados, Denterroto canaliza a energia divina residual do deus javali caído, concedendo bênçãos ancestrais formidáveis àqueles que o ajudam."}},faq={{q="Quem é Denterroto?",a="Denterroto é um javatusco Razormane capturado e mantido em uma jaula no Acampamento Taurajo. Diante da execução iminente pela Horda, ele barganha com aventureiros, oferecendo orientações e dádivas ancestrais em troca da eliminação de seus rivais.",al={"denterroto","quem é denterroto","javatusco engaiolado taurajo"}},{q="Por que Denterroto está em uma jaula?",a="Ele foi capturado durante confrontos entre a Horda e os javatuscos nos Sertões Meridionais. Os taurins e orcs no Acampamento Taurajo o mantêm engaiolado enquanto ele aguarda sua execução.",al={"por que denterroto é cativo","por que na jaula","por que prisioneiro taurajo"}},{q="Por que Denterroto pede para você atacar outros javatuscos Razormane?",a="Denterroto percebeu que seus companheiros de clã — Nak, Kuz e Lok Orcbane — o deixaram para morrer em vez de organizar um resgate. Enfurecido com a traição, ele encarrega viajantes de executá-los por pura vingança.",al={"por que atacar razormane","história de traição intestina","por que matar nak kuz"}},{q="O que são Blood Shards?",a="Blood Shards são minerais cristalinos que se formaram onde o sangue do Grande Javali Ancião, Agamaggan, ensopou a terra quando ele caiu durante a Guerra dos Antigos. Os javatuscos Bristleback costumam carregá-los.",al={"blood shards","história dos blood shards","sangue de agamaggan"}},{q="O que você pode fazer com Blood Shards junto a Denterroto?",a="Se você fornecer Blood Shards a Denterroto, ele canalizará o poder sagrado de Agamaggan em bênçãos temporárias, concedendo aumento de força, agilidade, resiliência, espírito ou velocidade.",al={"bônus de blood shard","entregar blood shard","o que denterroto concede"}},{q="Onde Denterroto diz que Agamaggan morreu?",a="Denterroto relata que Agamaggan caiu em batalha durante a Guerra dos Antigos. Seu sangue derramado deu origem aos imensos espirais de espinhos, e seu crânio colossal repousa consagrando uma caverna ao sul.",al={"história de agamaggan","onde agamaggan caiu","crânio do deus javali"}}},fx={d88e6e26={q="De que lado está Denterroto?",a="Denterroto serve apenas a si mesmo. Embora nascido dos javilhos Presaríspida, ele não nutre verdadeiro amor pela Horda que o aprisionou, nem lealdade duradoura à sua própria tribo depois de perceber que seus companheiros de clã o abandonaram. Ele coopera com aventureiros da Horda apenas como um acordo desesperado para sobreviver e atacar seus rivais.",al={"lado de denterroto","a quem denterroto é leal","denterroto é da horda"}},["7791b01e"]={q="O que Denterroto quer?",a="Enfrentando a execução no Acampamento Taurajo, Denterroto almeja inicialmente sobreviver e provar a supremacia de sua tribo sobre seus rivais, os Cerdepico, esperando que seu povo o resgate. Quando percebe que seus líderes Presaríspida — Nak, Kuz e Lok Orcbane — o abandonaram, seus desejos se voltam para uma vingança amarga e para reunir o poder sagrado dos Estilhaços de Sangue.",al={"o que denterroto quer","objetivo de denterroto","o que denterroto está tentando fazer"}},["1234667b"]={q="A quem Denterroto está ligado?",a="Denterroto pertence aos javilhos Presaríspida dos Sertões Meridionais. Seu destino está entrelaçado com seus rivais tribais Nak, Kuz e Lok Orcbane, cuja traição impulsiona sua raiva. Ele também reverencia o antigo deus javali Agamaggan, cuja essência espalhada permite que Denterroto conceda bênçãos àqueles que lhe trazem relíquias do sangue do deus caído.",al={"conexões de denterroto","quem denterroto conhece","tribo de denterroto"}}},fp="11,237,19.339.0,20.389.1,25.399.0,19.213.0,29.171.0,64.201.1,22.209.0,49.182.0,42.201.0"}
P.entries["npc:mankrik"] = {n="Mankrik",s="Mankrik é um guerreiro orc consumido pelo luto, estacionado na Encruzilhada, nos Sertões. Após uma emboscada brutal de javatuscos separá-lo de sua esposa, Olgra, ele dedicou sua vida a vingá-la e a abater cada fera espinhosa que conseguir encontrar.",h="Mankrik é um guerreiro orc consumido pelo luto, estacionado na Encruzilhada, nos Sertões.",kw={"sertões","a encruzilhada","estrada do ouro","mankrik","olgra","javatusco","thork"},ang={["faction:Horde"]="Para os viajantes que chegam à Encruzilhada, a situação de Mankrik serve como uma dura apresentação à ameaça implacável representada pelos bandos de javatuscos pelos Sertões.",["race:Orc"]="Mankrik personifica o custo devastador de colonizar as fronteiras selvagens de Kalimdor, onde a família e a honra são constantemente testadas contra ameaças nativas brutais."},sec={{t="Emboscada na Poeira",b="Enquanto viajavam pelas matas dos Sertões, Mankrik e sua esposa Olgra foram subjugados por enxames de javatuscos durante uma escaramuça em um pequeno assentamento tauren. Separado no caos e na luta frenética, Mankrik viu Olgra desaparecer sob uma maré de presas e armas entrelaçadas em espinhos. Tomado pela fúria, ele lutou imprudentemente até cair inconsciente. Ele sobreviveu apenas porque um druida tauren que passava o descobriu sangrando ao longo da Estrada do Ouro e tratou de seus ferimentos."},{t="Consumido pela Vingança",b="Recuperando-se na Encruzilhada, Mankrik se viu paralisado pela dor e por uma sede de sangue implacável. Embora líderes locais como Thork avisem que seu ódio cego obscurece seu discernimento e se recusem a organizar grupos de guerra oficiais, Mankrik se recusa a seguir em frente. Assombrado pela incerteza sobre o destino de Olgra, ele recruta quaisquer viajantes da Horda dispostos a vasculhar os Sertões em busca de sinais de sua companheira perdida e a massacrar qualquer javatusco que cruzar seu caminho."}},faq={{q="Quem é Mankrik?",a="Mankrik é um guerreiro orc que reside na Encruzilhada, nos Sertões. Ele sobreviveu a uma emboscada brutal de javatuscos que o separou de sua esposa, deixando-o consumido pela raiva e obstinado em vingá-la.",al={"história de mankrik","quem é mankrik","conto de mankrik"}},{q="O que aconteceu com a esposa de Mankrik?",a="Durante um confronto em um assentamento tauren, Mankrik e Olgra foram separados pelo número avassalador de javatuscos. Mankrik foi subjugado no caos, e Olgra se perdeu em meio ao combate.",al={"esposa de mankrik","onde está a esposa de mankrik","o que aconteceu com olgra","destino de olgra"}},{q="Como Mankrik sobreviveu à batalha?",a="Após cair inconsciente sob enxames de javatuscos, Mankrik foi encontrado desmaiado na Estrada do Ouro por um druida tauren errante, que cuidou de seus ferimentos graves e o levou para a segurança.",al={"como mankrik sobreviveu","quem salvou mankrik"}},{q="Por que Thork se recusa a ajudar Mankrik?",a="Thork, o líder da Encruzilhada, acredita que a raiva intensa de Mankrik e sua sede de vingança nublaram completamente seu julgamento, impedindo-o de agir racionalmente.",al={"por que thork não ajuda","thork e mankrik"}}},fx={["63979fed"]={q="De que lado está Mankrik?",a="Mankrik é leal à Horda. Operando a partir da Encruzilhada nos Sertões, ele conta com viajantes e aventureiros da Horda para ajudá-lo em sua busca desesperada e para contra-atacar os javilhos que ameaçam suas terras.",al={"facção de mankrik","mankrik é da horda","mankrik é aliança ou horda"}},["20b8339c"]={q="O que Mankrik quer?",a="Mankrik quer descobrir o destino de sua esposa perdida, Olgra, e massacrar tantos javilhos quanto possível. Após ser separado dela durante uma emboscada, ele é consumido pelo luto, pela raiva e por uma necessidade de vingança contra os saqueadores eriçados.",al={"o que mankrik está procurando","objetivo de mankrik","o que mankrik precisa"}},["5eb75604"]={q="Por que Mankrik está aqui na Encruzilhada?",a="Após um ataque de javilhos que o deixou gravemente ferido, um druida tauren que passava arrastou Mankrik ao longo da Estrada do Ouro para um local seguro. Mankrik agora permanece na Encruzilhada porque seus ferimentos e a incerteza persistente o mantêm ancorado perto de onde viu sua esposa pela última vez.",al={"por que mankrik está na encruzilhada","motivo da localização de mankrik","por que mankrik está nos sertões"}},d34d6f35={q="A quem Mankrik está ligado?",a="Mankrik está ligado por amor e tristeza à sua esposa, Olgra, com quem lutou lado a lado antes de serem dominados pelos javilhos. Ele também deve sua vida ao druida tauren errante que cuidou de seus ferimentos na Estrada do Ouro.",al={"relacionamentos de mankrik","quem está conectado a mankrik","família de mankrik"}}},fp="7,244,18.488.0,21.432.0,15.194.0,32.198.0,35.186.0,38.175.0"}
P.entries["npc:marcus-redpath"] = {n="Marcus Redpath",s="O Delegado Trilharrubra Marcus Redpath é a autoridade militar sênior que defende a cidade da Aliança de Costa Sul, no Contraforte de Eira dos Montes. Ele organiza patrulhas e contratos de recompensa para conter ogros, murlocs e nagas ao redor. Sua liderança é essencial para manter o último bastião meridional de Lordaeron no litoral.",h="O Delegado Trilharrubra Marcus Redpath é a autoridade militar sênior que defende a cidade da Aliança de Costa...",kw={"crushridge","eira dos montes","marcus redpath","delegado","costa sul"},ang={["faction:Alliance"]="O Delegado Trilharrubra oferece aos campeões da Aliança tarefas vitais para proteger Eira dos Montes contra ogros que avançam e perigos costeiros.",["race:Human"]="Redpath mantém um dos últimos pontos de apoio da humanidade em Lordaeron, mantendo Costa Sul de pé enquanto o reino ao redor jaz em ruínas."},sec={{t="Um Sentinela de Costa Sul",b="Marcus Redpath é o delegado de Costa Sul, o porto da Aliança no litoral sul do Contraforte de Eira dos Montes. Costa Sul resistiu à queda da capital de Lordaeron e à devastadora invasão do Flagelo, e Redpath agora lidera sua defesa, guardando os sobreviventes sitiados do porto."},{t="Segurando o Litoral",b="Após a Terceira Guerra, Costa Sul se encontra praticamente sozinha contra forças hostis pressionando de todos os lados. O Delegado Trilharrubra coordena operações de defesa ao longo do Contraforte de Eira dos Montes, recrutando aventureiros experientes para repelir os ogros Crushridge que descem de Alterac e purgar perigosos acampamentos de nagas e murlocs ao longo da costa. Com os Renegados ocupando o norte e Serraria Tarren fortemente fortificada nas proximidades, a vigilância de Redpath é uma das poucas barreiras que impedem o colapso total da presença da Aliança na região."}},faq={{q="Quem é Marcus Redpath?",a="Marcus Redpath é o delegado e comandante militar de Costa Sul, no Contraforte de Eira dos Montes. Ele supervisiona a defesa local contra as ameaças selvagens ao redor e vizinhos hostis.",al={"marcus redpath história","quem é o delegado em costa sul","marcus redpath informações"}},{q="Qual foi o papel dele na Segunda Guerra?",a="Nenhum relato da Segunda Guerra registra a participação de Redpath nela. Ele é conhecido hoje como o delegado de Costa Sul, defendendo a cidade contra os ogros, murlocs e nagas do Contraforte de Eira dos Montes.",al={"marcus na segunda guerra","marcus redpath conheceu lothar"}},{q="Em quais ameaças ele se concentra no combate?",a="Redpath organiza esforços militares contra predadores e invasores locais que avançam sobre Costa Sul. Ele emite recompensas e missões voltadas para a tribo de ogros Crushridge nas colinas de Alterac, murlocs costeiros e nagas invasores.",al={"missões de marcus redpath","o que redpath quer que matem"}},{q="Ele é parente dos Redpath de Vila das Flechas?",a="Embora compartilhe o sobrenome Redpath que ficou famoso pelo Capitão Joseph Redpath de Vila das Flechas nas Terras Pestilentas Orientais, nenhum parentesco direto foi formalmente estabelecido além da herança compartilhada no Reino de Lordaeron.",al={"família redpath","marcus é parente de joseph redpath","parentes de redpath"}},{q="Onde Marcus Redpath pode ser encontrado?",a="O Delegado Trilharrubra está posicionado no centro de Costa Sul, um refúgio da Aliança situado no litoral sul do Contraforte de Eira dos Montes.",al={"onde fica marcus redpath","localização de marcus redpath"}}},fx={["0aeeadbf"]={q="De que lado está Marcus Redpath?",a="O marechal Marcus Redpath serve à Aliança e aos sobreviventes de Lordaeron que se reuniram sob a bandeira da Costa Sul. Como marechal da cidade da Costa Sul, ele permanece firmemente com os defensores humanos mantendo a linha de Eira dos Montes contra ameaças hostis nos contrafortes.",al={"facção de marcus redpath","de qual facção é marcus redpath","a quem redpath serve"}},["43107ef7"]={q="O que Marcus Redpath quer?",a="Redpath quer proteger a Costa Sul e as terras circundantes de perigos crescentes. Ele direciona ativamente soldados e aventureiros para eliminar perigos regionais, repelindo as tribos de ogros Esmaga-Cume das montanhas do norte e erradicando as infestações de murlocs e nagas que assolam a costa.",al={"objetivos de marcus redpath","o que redpath precisa","propósito de marcus redpath"}},["402d4dad"]={q="Por que Marcus Redpath está aqui?",a="Marcus Redpath serve como marechal de Costa Sul. Desde a queda de Lordaeron na Terceira Guerra, a cidade tem sido um dos últimos redutos da Aliança na região, e ele organiza suas defesas e mantém a ordem lá.",al={"por que marcus redpath está em costa sul","razão de redpath em costa sul","o que redpath está fazendo aqui"}}},fp="14,308,24.295.0,17.550.0,22.182.0,40.182.0,39.227.0,45.222.0,34.134.0"}
P.entries["npc:mardant-strongoak"] = {n="Mardant Carvalhaço",s="Mardant Carvalhaço é um instrutor de druidas elfo noturno que reside em Aldrassil, no coração de Teldrassil. Ele guia druidas iniciantes a comungar com os espíritos da natureza e os introduz aos mistérios do Sonho Esmeralda.",h="Mardant Carvalhaço é um instrutor de druidas elfo noturno que reside em Aldrassil, no coração de Teldrassil.",kw={"aldrassil","druida","sonho esmeralda","mardant","umbravale","carvalhaço","teldrassil","instrutor"},ang={["class:Druid"]="Para jovens druidas elfos noturnos, Mardant Carvalhaço é a primeira ponte entre a existência mundana e os deveres sagrados do Círculo Cenariano.",["race:NightElf"]="Posicionado no centro de Aldrassil, Mardant exemplifica a devoção kaldorei em harmonizar com o ecossistema florescente de Teldrassil."},sec={{t="Instrutor dos Ermos",b="Sob a copa de Aldrassil, jovens elfos noturnos que sentem o chamado da natureza procuram Mardant Carvalhaço. Sua principal tarefa é ensinar os novatos a abrirem seus sentidos aos espíritos da natureza, interpretarem seus sussurros e canalizarem magias rejuvenescedoras. Para aqueles que dão seus passos iniciais como protetores dos ermos, ele costuma ser o primeiro mestre a desvendar as vastas complexidades e os antigos perigos do Sonho Esmeralda."}},faq={{q="Quem é Mardant Carvalhaço?",a="Mardant Carvalhaço é um instrutor de druidas elfo noturno situado em Umbravale, no interior de Aldrassil. Ele orienta druidas recém-despertos em Teldrassil nas artes básicas de comunhão e feitiçaria.",al={"história de mardant carvalhaço","quem é mardant","mardant aldrassil"}},{q="O que ele ensina aos novos druidas?",a="Ele ensina os novatos a decifrarem as mensagens dos espíritos selvagens, a lançarem feitiços rudimentares como Fogo Lunar e artes de cura, e a compreenderem a natureza do Sonho Esmeralda.",al={"o que mardant ensina","habilidades de mardant","instrutor de druidas umbravale"}},{q="Onde posso encontrar Mardant Carvalhaço?",a="Ele fica dentro ou perto de Aldrassil, em Umbravale, o vale inicial para aventureiros elfos noturnos em Teldrassil.",al={"localização de mardant","onde fica mardant carvalhaço"}},{q="O que é O selo verdejante?",a="O selo verdejante é um símbolo instrutivo entregue a druidas elfos noturnos novatos em Umbravale, orientando-os a procurar Mardant Carvalhaço para o treinamento inicial.",al={"missão o selo verdejante","selo para mardant"}}},fx={a3bbc1b2={q="De que lado está Mardant Carvalhaço?",a="Mardant Carvalhaço é devotado aos elfos noturnos, à Aliança e aos princípios sagrados do Círculo Cenariano. Ele permanece firmemente dentro de Umbravale para proteger a incipiente Árvore do Mundo e garantir que as tradições dos druidas kaldorei perdurem nestes tempos incertos.",al={"facção de mardant carvalhaço","a quem mardant serve","mardant é aliança"}},ff8559f4={q="O que Mardant Carvalhaço quer?",a="Mardant quer que os jovens iniciados elfos noturnos aprofundem sua comunhão com a natureza. Ele busca guiar novos druidas através de suas provações iniciais, ajudando-os a decifrar os sussurros dos espíritos e a navegar pelos mistérios profundos e perigos do Sonho Esmeralda.",al={"o que mardant quer","objetivos de mardant carvalhaço","qual é o objetivo de mardant"}},b78651d9={q="Por que Mardant Carvalhaço está aqui?",a="Estacionado dentro dos galhos ocos de Aldrassil, Mardant serve como mentor para druidas recém-despertos que estão dando seus primeiros passos em Teldrassil. Ele permanece em Umbravale para cuidar dos novatos, instruí-los em seus poderes inatos e direcioná-los para aqueles que precisam de ajuda por toda a clareira.",al={"por que mardant está em aldrassil","por que mardant carvalhaço está aqui","motivo da localização de mardant carvalhaço"}},dec3bef7={q="A quem Mardant Carvalhaço está ligado?",a="Mardant está intimamente ligado ao Círculo Cenariano e a seus colegas professores em Aldrassil, como as sacerdotisas de Eluna e as sentinelas que guardam o santuário. Juntos, eles guiam e nutrem os jovens defensores dos elfos noturnos.",al={"aliados de mardant carvalhaço","com quem mardant é afiliado","conexões de mardant"}}},fp="17,222,23.414.0,25.182.0,30.166.0,35.112.0,26.169.0"}
P.entries["npc:marek-ironheart"] = {n="Marek Ferrocordis",s="Marek Ferrocordis é um caçador anão veterano estacionado no Pavilhão dos Andarilhos, no sudeste de Loch Modan. Dedicado às tradições da natureza, ele testa viajantes errantes e atiradores antes de recebê-los nas fileiras dos caçadores honrados do pavilhão.",h="Marek Ferrocordis é um caçador anão veterano estacionado no Pavilhão dos Andarilhos, no sudeste de Loch Modan.",kw={"crocolisk hunting","pavilhão dos andarilhos","caçador","caça","ironheart","loch modan","marek ferrocordis"},ang={["class:Hunter"]="Para patrulheiros e perseguidores de feras, Marek Ferrocordis representa as tradições rústicas do Pavilhão dos Andarilhos, desafiando caçadores a provar sua precisão e habilidades de rastreamento contra a fauna local.",["race:Dwarf"]="Marek exemplifica a cultura de mateiro apreciada por muitos anões de Khaz Modan, escolhendo a vigília silenciosa das montanhas em vez das barulhentas forjas de Altaforja."},sec={{t="Mestre da Caçada",b="Situado na cumeada cênica que domina o lago, o Pavilhão dos Andarilhos serve como um posto avançado para os melhores atiradores e rastreadores das terras dos anões. Marek Ferrocordis personifica esse espírito de fronteira. Não se impressionando com títulos ou conversas, Marek exige que qualquer um que busque o respeito do pavilhão demonstre sua proeza prática contra as variadas feras que vagam por Loch Modan, provando que possuem a paciência e a coragem exigidas de um verdadeiro perseguidor da vida selvagem."}},faq={{q="Quem é Marek Ferrocordis?",a="Marek Ferrocordis é um caçador anão que reside no Pavilhão dos Andarilhos em Loch Modan. Ele testa visitantes que buscam aprovação na comunidade de rastreadores e mateiros do pavilhão.",al={"marek ferrocordis","quem é marek"}},{q="Onde posso encontrar Marek Ferrocordis?",a="Ele está localizado no Pavilhão dos Andarilhos, aninhado nas colinas ao longo da costa sudeste de Loch Modan.",al={"localização de marek ferrocordis","onde está marek"}},{q="Que tipo de tarefas Marek oferece?",a="Marek orienta os caçadores a rastrear e abater várias criaturas selvagens locais ao redor do Loch, testando suas habilidades de sobrevivência contra crocoliscos perigosos.",al={"missões de marek ferrocordis","missões de marek"}},{q="Marek tem parentesco com outros anões conhecidos?",a="Compartilhando um sobrenome anão notável, ele pode ser parente do Arqueólogo Adamant Ironheart e de Imme Ironheart, embora Marek dedique sua vida à caça em vez de escavar relíquias.",al={"família ironheart","parentes de marek"}}},fx={ac3880c9={q="De que lado está Marek Ferrocordis?",a="Marek está com a Aliança e os clãs anões de Altaforja. Operando a partir do Pavilhão dos Andarilhos nas terras selvagens do sudeste de Loch Modan, ele convida seus companheiros de viagem da Aliança a provar seu valor dominando a natureza circundante.",al={"facção de marek ferrocordis","marek ferrocordis é aliança","marek ferrocordis é da aliança"}},["2928b65a"]={q="O que Marek Ferrocordis quer?",a="Marek trabalha no Pavilhão dos Andarilhos em Loch Modan, onde convida caçadores a perseguirem os crocoliscos ao redor do Loch.",al={"o que marek quer","objetivos de marek ferrocordis","por que falar com marek ferrocordis"}},ddec60fb={q="Por que Marek Ferrocordis está no Pavilhão dos Andarilhos?",a="Marek faz do Pavilhão dos Andarilhos seu lar para testar e treinar mateiros nas colinas indomadas de Loch Modan. Deste posto remoto, ele observa a vida selvagem local e guia os caçadores que buscam aprimorar suas habilidades de campo na natureza selvagem das terras altas.",al={"por que marek está em loch modan","propósito de marek ferrocordis no pavilhão dos andarilhos","por que marek está aqui"}}},fp="15,264,18.444.0,23.177.0,33.104.0,36.144.0,44.176.0"}
P.entries["npc:marisa-du-paige"] = {n="Marisa du'Paige",s="Marisa du'Paige é uma conjuradora humana renegada rara encontrada à espreita na vasta rede de cavernas do lado de fora da entrada das Minas Mortas, no sudoeste de Cerro Oeste. Aliada aos foras da lei que operam sob Arroio da Lua, ela empunha magia arcana ao lado dos trabalhadores e salteadores que guardam os túneis.",h="Marisa du'Paige é uma conjuradora humana renegada rara encontrada à espreita na vasta rede de cavernas do...",kw={"minas mortas","humano","mago","marisa du'paige","marisa dupaige","arroio da lua","raro","cerro oeste"},ang={["class:Mage"]="Marisa du'Paige é uma lembrança de que o treinamento arcano no reino não se limita às torres do Kirin Tor ou ao santuário dos magos de Ventobravo; conjuradores renegados vendem prontamente seus talentos para redes criminosas.",["faction:Alliance"]="Aventureiros da Aliança que exploram os túneis sob Arroio da Lua devem ficar atentos a du'Paige, pois uma conjuradora inesperada em meio a hordas de batedores de carteira pode transformar rapidamente um confronto em algo mortal."},sec={{t="Talento Arcano nos Túneis",b="Nas profundezas das cavernas sinuosas que levam às Minas Mortas sob Arroio da Lua, a maioria dos defensores é composta por batedores de carteira rudes, mineradores renegados e capangas. Marisa du'Paige se destaca entre eles como uma maga humana habilidosa. Enquanto a maioria dos conjuradores do reino treina nos salões autorizados do Distrito dos Magos de Ventobravo ou serve ao Kirin Tor, du'Paige uniu seu destino aos foras da lei e bandidos escondidos nas profundezas subterrâneas de Cerro Oeste."}},faq={{q="Quem é Marisa du'Paige?",a="Marisa du'Paige é uma maga humana rara à espreita no sistema de cavernas externo que conduz às Minas Mortas. Diferente dos ladrões comuns e trabalhadores típicos encontrados patrulhando essas passagens, ela lança feitiços arcanos na defesa da rede subterrânea.",al={"marisa dupaige","quem é marisa","raro na caverna das minas mortas"}},{q="Onde ela pode ser encontrada?",a="Ela surge raramente dentro do sistema público de cavernas sob Arroio da Lua, em Cerro Oeste, nos túneis situados logo antes do portal de entrada da masmorra Minas Mortas.",al={"localização de marisa du'paige","onde fica marisa dupaige","ressurgimento de marisa"}},{q="Por que uma maga humana está escondida nas cavernas das Minas Mortas?",a="Nem todos os praticantes do arcano permanecem leais às altas torres de Ventobravo. Desertores, renegados e plebeus simpatizantes juntaram-se à causa dos foras da lei por toda Cerro Oeste, oferecendo tanto aço quanto feitiçaria às suas fortificações sob Arroio da Lua.",al={"por que ela está aqui","história de marisa","facção de marisa dupaige"}}},fx={["5e8e0d23"]={q="De que lado Marisa du'Paige está?",a="Marisa du'Paige veste as roupas e caminha pelos corredores subterrâneos da The Defias Brotherhood. Espreitando profundamente nas cavernas de Arroio da Lua que levam às Minas Mortas, ela apoia a irmandade rebelde de Edwin VanCleef, lançando seus feitiços arcanos contra quaisquer intrusos que ameacem sua fortaleza.",al={"facção de marisa dupaige","marisa dupaige é da defias","para quem marisa dupaige trabalha"}}},fp="15,299,28.436.0,23.241.0,23.162.0,50.248.0"}
P.entries["npc:marleth-barleybrew"] = {n="Marleth Cervevada",s="Marleth Cervevada é uma ambiciosa cervejeira anã estabelecida na Aldeia da Cevada. Frustrada com o domínio do clã Cervaforte sobre o mercado local de cerveja, ela arquiteta planos constantemente para provar que a bebida de sua família é superior à famosa Cerveja do Trovão de Kharanos.",h="Marleth Cervevada é uma ambiciosa cervejeira anã estabelecida na Aldeia da Cevada.",kw={"a guerra das cervejas","aldeia da cevada","cervejeira anã","kharanos","marleth cervevada","cerveja do trovão","cervaforte"},ang={["race:Dwarf"]="Para os anões, fabricar cerveja é uma forma de arte intimamente ligada ao prestígio do clã, tornando a rivalidade de Marleth com os Cervaforte uma questão de feroz orgulho familiar."},sec={{t="A rivalidade cervejeira",b="Em Dun Morogh, o álcool é levado tão a sério quanto o aço, e a rivalidade entre as famílias Cervevada e Cervaforte é lendária. Marleth Cervevada se ressente do quase monopólio que Ragnar Cervaforte e seus parentes mantêm a partir da Destilaria Cervaforte em Kharanos. Convencida de que sua própria produção é tão encorpada quanto a deles, ela busca maneiras engenhosas de colocar barris dos Cervevada nas mãos dos frequentadores das tavernas. Em vez de entrar em conflito aberto, ela opta por subterfúgios mesquinhos, recrutando viajantes que passam pelo local para trocar secretamente os preciosos barris de cerveja de Kharanos pelos seus."}},faq={{q="Quem é Marleth Cervevada?",a="Marleth é uma mestre-cervejeira anã que reside na Aldeia da Cevada, no oeste de Dun Morogh. Ela representa a família Cervevada e trabalha ativamente para desafiar o domínio que a rival família Cervaforte tem sobre o cenário etílico local.",al={"quem é marleth","história de marleth","marleth cervevada"}},{q="Onde posso encontrar Marleth Cervevada?",a="Ela pode ser encontrada na Aldeia da Cevada, localizada nos limites ocidentais de Dun Morogh, perto do Lago Nevado.",al={"localização de marleth","onde fica marleth","encontrar marleth"}},{q="Por que Marleth quer trocar a cerveja dos Cervaforte?",a="Marleth acredita que a cerveja de sua família é tão boa quanto, se não melhor que, a Cerveja do Trovão. Como os Cervaforte dominam o comércio em Kharanos, ela contrata aventureiros para substituir secretamente os barris da taverna pelo estoque dos Cervevada, para que os bebedores provem seu produto, trazendo também uma amostra da Cerveja do Trovão para ela analisar.",al={"por que trocar a cerveja","motivo da missão a guerra das cervejas","por que odeia os cervaforte"}},{q="Quem são os outros membros da família Cervevada?",a="Seu clã estendido inclui outros cervejeiros e comerciantes renomados, como Malgin, Rejold, Wellart e Yorus Cervevada, todos dedicados à arte da fabricação de cerveja anã tradicional.",al={"família cervevada","parentes de marleth"}}},fx={c401045b={q="De que lado está Marleth Cervevada?",a="Marleth é uma orgulhosa anã de Altaforja e leal à Aliança, embora seu foco diário imediato seja inteiramente comercial. Ela pertence à família cervejeira Cervevada e defende ferozmente seu ofício contra seus rivais locais.",al={"lealdade de marleth cervevada","a quem marleth cervevada serve","facção de marleth"}},["716c9dd7"]={q="Por que Marleth Cervevada está na Aldeia da Cevada?",a="A Aldeia da Cevada serve como um posto avançado regional de fabricação de cerveja nas colinas nevadas de Dun Morogh. Marleth opera a partir daqui para produzir sua cerveja artesanal e planejar maneiras de entrar nos mercados maiores monopolizados pelos Thunderbrews.",al={"por que marleth está aqui","marleth cervevada aldeia da cevada","por que marleth cervevada está em dun morogh"}}},fp="18,255,19.559.0,26.223.0,36.101.0,49.325.0,51.174.0"}
P.entries["npc:marryk-nurribit"] = {n="Marryk Nurribit",s="Marryk Nurribit é o instrutor de magos gnomo residente em Sidermar, no Vale Cristálgida. Um pouco mais apegado às bebidas locais do que à pedagogia disciplinada, ele apresenta os arcanistas gnomos novatos ao seu ofício enquanto frequentemente pede moedas trocadas para tomar um trago.",h="Marryk Nurribit é o instrutor de magos gnomo residente em Sidermar, no Vale Cristálgida.",kw={"sidermar","cerveja","cristálgida","gnomo","mago","marryk","nurribit","instrutor"},ang={["class:Mage"]="Para magos gnomos novatos que iniciam sua jornada no Vale Cristálgida, Marryk é o primeiro professor a quem você recorre para obter feitiços fundamentais e seu Memorando Glífico.",["race:Gnome"]="Refugiados abrigados em Dun Morogh conhecem Marryk como um exemplo de estudioso gnomo que se adaptou um pouco bem demais à hospitalidade das tavernas anãs."},sec={{t="Estudos Arcanos e Cerveja",b="Abrigado no calor da lareira de Sidermar, Marryk Nurribit oferece orientação arcana a jovens gnomos dando seus primeiros passos na magia. Embora conhecedor das artes arcanas, seu comportamento é decididamente descontraído — parecendo muitas vezes muito mais interessado em bebericar uma caneca de cerveja anã e arranjar uns trocados com seus novos pupilos do que em treiná-los em teoremas complexos. Apesar de seus vícios, Marryk permanece plenamente ciente dos perigos fora do Vale Cristálgida, alertando regularmente os aspirantes a conjuradores sobre os horrores radioativos e infestados de troggs da caída Gnomeregan."}},faq={{q="Quem é Marryk Nurribit?",a="Marryk Nurribit é um instrutor de magos gnomo situado no interior de Sidermar, no Vale Cristálgida de Dun Morogh. Ele instrui magos gnomos recém-chegados nos fundamentos da magia arcana.",al={"marryk nurribit","quem é marryk","instrutor de magos de sidermar"}},{q="Por que Marryk vive pedindo dinheiro para cerveja?",a="Marryk é conhecido por apreciar bebidas locais muito mais do que manter o estrito decoro profissional. Ele incomoda seus alunos regularmente por moedas para sustentar seus hábitos de bebedeira na taverna.",al={"marryk bebendo","cerveja de marryk","por que ele pede moedas"}},{q="O que Marryk diz sobre Gnomeregan?",a="Apesar de sua atitude relaxada com o treinamento, Marryk reconhece o perigo real e adverte repetidamente os novos magos a não subestimarem as ameaças à espreita nas ruínas irradiadas de Gnomeregan.",al={"marryk gnomeregan","aviso sobre gnomeregan"}}},fx={["42f80152"]={q="De que lado está Marryk Nurribit?",a="Marryk é leal aos Exilados de Gnomeregan e está totalmente ao lado da Aliança. Abrigando-se com seus anfitriões anões em Dun Morogh, ele oferece sua instrução arcana aos gnomos novatos que dão seus primeiros passos no Vale Cristálgida.",al={"facção de marryk nurribit","a quem marryk serve","lealdade de marryk"}},["241b0acf"]={q="Por que Marryk Nurribit está em Sidermar?",a="Após a trágica queda de Gnomeregan devido à infestação de trogs e à radiação tóxica, Marryk e seus parentes sobreviventes fugiram para Dun Morogh. Ele agora permanece em Sidermar, no Vale Cristálgida, nominalmente encarregado de instruir gnomos magos novatos nas artes arcanas.",al={"por que marryk está aqui","marryk nurribit sidermar","propósito de marryk em dun morogh"}}},fp="15,261,22.589.0,23.175.0,47.191.0,38.197.0"}
P.entries["npc:marshal-dughan"] = {n="Delegado Durão",s="O Delegado Durão é o oficial comandante do destacamento do Exército de Ventobravo estacionado em Vila d'Ouro. Encarregado de proteger o coração da Floresta de Elwynn, ele vê sua guarnição local sobrecarregada contra as crescentes incursões de kobolds, gnolls e bandidos. Para manter a cidade da encruzilhada e as fazendas ao redor seguras, ele depende fortemente de aventureiros independentes.",h="O Delegado Durão é o oficial comandante do destacamento do Exército de Ventobravo estacionado em Vila d'Ouro.",kw={"floresta de elwynn","vailafundo","vila d'ouro","hogger","jaspe","delegado durão","exército de ventobravo","guarnição da ribeira d'oeste"},ang={["class:Warrior"]="Para combatentes marciais, Durão personifica a disciplina padrão e o desgaste logístico dos soldados de infantaria de Ventobravo mantendo a linha contra probabilidades impossíveis.",["faction:Alliance"]="O Delegado Durão representa a autoridade administrativa da linha de frente para a Aliança em Elwynn, fornecendo aos recrutas recém-chegados suas primeiras missões militares em nome de Ventobravo."},sec={{t="Comandante da Encruzilhada",b="Posicionado com destaque em Vila d'Ouro em frente à Estalagem do Leão Orgulhoso, o Delegado Durão carrega o pesado fardo de manter a Floresta de Elwynn segura enquanto os recursos militares de Ventobravo estão ocupados em outros lugares. Os bosques ao redor estão se deteriorando progressivamente: pragas sufocam as minas, gnolls se aglomeram ao longo das margens dos rios e salteadores hostilizam viajantes pela Estrada do Rei. Com poucos soldados rasos sob seu comando direto, Durão organiza a defesa local orientando novos recrutas a reforçar postos avançados e patrulhar terrenos contestados."},{t="Ameaças em Todas as Fronteiras",b="As preocupações imediatas de Durão residem nas infestações de kobolds que assolam a Mina Vailafundo e a Mina de Jaspe, ameaçando a produção mineral vital de Vila d'Ouro. A oeste, gnolls Patarrubra liderados pelo infame Hogger pressionam fortemente contra a Guarnição da Ribeira d'Oeste. A leste, Durão é forçado a lidar com relatórios do Guarda Tomás sobre murlocs ferozes massacrando patrulhas ao longo do rio. Gerenciar essas crises simultâneas com efetivo limitado mantém o delegado em constante necessidade de mercenários competentes."}},faq={{q="Quem é o Delegado Durão?",a="O Delegado Durão é um oficial do Exército de Ventobravo estacionado em Vila d'Ouro. Ele supervisiona a segurança militar da parte central da Floresta de Elwynn, coordenando esforços defensivos contra ameaças locais como ladrões, gnolls e kobolds.",al={"dughan","história do delegado durão","delegado de vila d'ouro"}},{q="Por que Durão não envia mais guardas para ajudar a Guarnição da Ribeira d'Oeste ou o leste?",a="O Exército de Ventobravo está com seu efetivo espalhado, deixando Durão com apenas guardas suficientes para mal manter a ordem na própria Vila d'Ouro. Como não dispõe do contingente fixo necessário para guarnecer cada fazenda afastada e posto fronteiriço, ele conta com aventureiros de passagem para sondar pontos críticos, entregar despachos e eliminar perigos regionais.",al={"por que não há guardas","força da guarnição de vila d'ouro","tropas de durão"}},{q="Qual é a visão de Durão sobre a ameaça dos murlocs em Elwynn?",a="Inicialmente, Durão desconsiderou os avisos de Remy 'Dois Tempos' de que os murlocs eram uma ameaça séria para a região. Ele só reconheceu o verdadeiro perigo depois que o Guarda Tomás enviou relatórios trágicos confirmando as mortes dos guardas Rolf Hartford e Malakai Stone ao longo dos cursos d'água orientais.",al={"durão murlocs","remy duas-vezes murloc","durão homens-peixe"}},{q="Como Durão lida com o crime local e civis arruaceiros?",a="Manter a paz em Vila d'Ouro e nas terras vizinhas é dever de Durão, embora, segundo seu próprio relato, já seja difícil o bastante manter a ordem sem todos os novos problemas que surgem por toda Elwynn. A maior parte de sua atenção vai para os kobolds ao norte e para os gnolls e ladrões a oeste.",al={"durão crime","lei em vila d'ouro","ameaça do cárcere"}},{q="Por que Durão está preocupado com as minas?",a="A Mina Vailafundo e a Mina de Jaspe são fontes essenciais de ouro e minério para Ventobravo. Kobolds invadiram ambos os complexos subterrâneos, expulsando os mineradores e ameaçando expandir seus túneis diretamente sob os povoados de Elwynn.",al={"mina vailafundo durão","mina de jaspe durão","infestação de kobolds"}},{q="O Delegado Durão se coordena com Cerro Oeste?",a="Sim. Assim que um aventureiro prova sua capacidade na Floresta de Elwynn, o Delegado Durão o direciona a Cerro Oeste para Report to Gryan Stoutmantle no Morro da Sentinela, onde The People's Militia precisa desesperadamente de ajuda veterana contra a Irmandade Défias.",al={"durão gryan","apresentar-se em cerro oeste","durão morro da sentinela"}}},fx={["72888056"]={q="De que lado está o Delegado Durão?",a="O Delegado Durão serve ao Reino de Ventobravo e à Aliança. Como oficial do Exército de Ventobravo, ele responde diretamente à hierarquia militar do reino, cumprindo as ordens da coroa para manter a ordem e proteger o coração do reino, apesar da escassez de reforços reais.",al={"facção de durão","a quem durão serve","lealdade do delegado durão"}},["9141816c"]={q="O que o Delegado Durão quer?",a="Durão visa garantir a segurança da Floresta de Elwynn e proteger Vila d'Ouro contra ameaças crescentes. Com sua guarnição reduzida, ele busca aventureiros capazes para explorar as infestadas minas da Serra do Eco e Jasperlode, conter os bandidos da Defias e os gnolls no oeste, e avaliar o perigo crescente ao longo das margens dos rios.",al={"objetivo de durão","o que durão precisa","objetivos de durão"}},["8808e7de"]={q="Por que o Delegado Durão está estacionado em Vila d'Ouro?",a="Durão está estacionado em Vila d'Ouro como comandante do destacamento local do Exército de Ventobravo. Encarregado da defesa do centro de Elwynn, ele supervisiona a manutenção da paz na cidade, coordena postos avançados como a Guarnição da Ribeira d'Oeste e gerencia a defesa contra bestas invasoras, kobolds e criminosos que ameaçam o celeiro da capital.",al={"por que durão está em vila d'ouro","propósito do delegado durão aqui","posto de durão"}},["156c33b1"]={q="A quem o Delegado Durão está ligado?",a="Durão trabalha em estreita colaboração com comandantes de postos avançados locais por toda Elwynn, como o Delegado Ranieri na Guarnição da Ribeira d'Oeste e o Guarda Tomás ao longo das pontes orientais. Fora de Elwynn, ele mantém comunicação com colegas militares como Gryan Stoutmantle em Cerro Oeste, compartilhando informações sobre atividades criminosas regionais.",al={"conexões de durão","com quem durão trabalha","aliados de durão"}}},fp="14,358,27.516.0,23.494.0,22.220.0,75.308.0,53.277.1,55.284.0,40.237.0,45.244.0"}
P.entries["npc:marshal-marris"] = {n="Oficial Marris",s="O Oficial Marris é o sobrecarregado oficial militar no comando da guarda de Vila Plácida. Estacionado perto da ponte do vilarejo, ele coordena operações de defesa contra a massiva invasão de orcs Rocha Negra que desce das alturas das Montanhas Cristarrubra. Com a ausência do exército de Ventobravo, ele conta com aventureiros de passagem para conter os avanços da horda.",h="O Oficial Marris é o sobrecarregado oficial militar no comando da guarda de Vila Plácida.",kw={"rocha negra","ponte","vila plácida","marris","oficial marris","cristarrubra","mirante de pedra","tharil'zun"},ang={["class:Warrior"]="Marris valoriza a disciplina marcial direta, enviando combatentes de linha de frente capazes para as garras de Mirante de Pedra a fim de enfrentar os veteranos experientes de Rocha Negra.",["faction:Alliance"]="O Oficial Marris personifica a difícil situação dos territórios rurais da Aliança, deixados vulneráveis pela paralisia política de Ventobravo e forçados a lutar pela própria sobrevivência.",["race:Human"]="Para os humanos do reino, Marris representa o estoico e sobrecarregado guarda de fronteira que mantém a linha contra os remanescentes da Velha Horda."},sec={{t="Um Vilarejo Sob Cerco",b="Vila Plácida está à beira do colapso, encurralada entre os gnolls a oeste e o aterrador poder militar do clã Rocha Negra a leste. O Oficial Marris supervisiona a linha de guardas na ponte principal da cidade, mas seus recursos estão esgotados e seus soldados estão dispersos além do limite. Com o reino de Ventobravo retendo reforços reais, Marris carrega o pesado fardo de evitar que o povoado seja subjugado pela força bruta."},{t="Rompendo a Vanguarda Rocha Negra",b="Reconhecendo que apenas a defesa não salvará Cristarrubra, Marris orquestra ataques ofensivos decisivos contra os acampamentos dos orcs. Ele instrui mercenários a abater os guerreiros Rocha Negra, desmantelar seus conjuradores de sombras e, por fim, caçar Tharil'zun, o temível comandante entrincheirado dentro das ruínas da Bastilha Mirante de Pedra. Suas ordens visam quebrar a estrutura de comando dos orcs antes que um ataque total destrua Vila Plácida por completo."}},faq={{q="Quem é o Oficial Marris?",a="O Oficial Marris é o comandante militar sênior encarregado de defender Vila Plácida. Ele pode ser encontrado vigiando perto da extremidade oeste da ponte do vilarejo, tentando manter o assentamento fortificado contra incursões hostis.",al={"marris","história oficial marris","quem é o guarda na ponte de vila plácida"}},{q="Por que o Oficial Marris está contratando aventureiros independentes?",a="O Reino de Ventobravo não enviou reforços de guarnição adequados para as Montanhas Cristarrubra, deixando a guarda local de Vila Plácida em grande desvantagem numérica. Enfrentando bandos de guerra gnolls e uma invasão entrincheirada de orcs Rocha Negra, Marris é forçado a recrutar heróis mercenários para realizar ataques críticos.",al={"por que marris precisa de ajuda","por que não há exército de ventobravo"}},{q="Contra quais ameaças o Oficial Marris está lutando?",a="Embora os gnolls assolem os arredores, Marris está focado principalmente nos orcs Rocha Negra que tomaram a Bastilha Mirante de Pedra. Esses orcs, comandados por Tharil'zun e fortalecidos por Magia Sombria, representam uma ameaça existencial iminente para Vila Plácida e para todo o reino.",al={"inimigos de marris","quem está atacando vila plácida"}},{q="O Oficial Marris é parente de Nathanos Marris?",a="Eles compartilham um sobrenome comum aos reinos humanos de Lordaeron e Ventobravo, mas nenhum registro oficial confirma uma relação familiar direta entre o Oficial Marris em Cristarrubra e o famoso patrulheiro Nathanos Marris do norte.",al={"marris é parente de nathanos","família marris"}},{q="Qual é o plano de Marris para derrotar o clã Rocha Negra?",a="Marris implementa uma estratégia de atrito e decapitação da liderança. Ele instrui combatentes a abater a infantaria Rocha Negra, coletar componentes mágicos de seus usuários de Magia Sombria e invadir a Bastilha Mirante de Pedra para executar seu líder, Tharil'zun.",al={"plano de marris","como derrotar orcs rocha negra"}},{q="Onde encontrar o Oficial Marris?",a="Marris está posicionado em Vila Plácida, nas Montanhas Cristarrubra, localizado em destaque ao longo da ponte, perto do centro do vilarejo.",al={"localização de marris","onde fica o oficial marris"}}},fx={["4fad023e"]={q="De que lado está o Oficial Marris?",a="O Oficial Marris é um oficial leal do Reino de Ventobravo e da Aliança. Estacionado na linha de frente em Vila Plácida, ele representa a autoridade militar local tentando desesperadamente proteger as Montanhas Cristarrubra e seus cidadãos de inimigos invasores.",al={"facção do oficial marris","a quem marris serve","marris aliança ou ventobravo"}},["4230d686"]={q="Por que o Oficial Marris está aqui em Vila Plácida?",a="O Oficial Marris está postado perto da ponte de Vila Plácida para coordenar as defesas contra os orcs Rocha Negra que surgem das montanhas. Com os reforços oficiais de Ventobravo escassos, ele permanece de guarda em Cristarrubra para reunir quaisquer aventureiros capazes dispostos a levar a luta até a fortaleza inimiga.",al={"por que o oficial marris está em cristarrubra","por que marris está aqui","motivo da localização do oficial marris"}}},fp="14,354,18.453.0,31.438.0,22.223.0,53.302.0,48.263.0,45.228.0,51.229.0,34.128.0"}
P.entries["npc:marshal-maxwell"] = {n="Oficial Maxwell",s="O Oficial Maxwell é um oficial de alta patente do exército de Ventobravo alocado na Vigia de Morgan, nas Estepes Ardentes. Encarregado de manter a crista fortificada mais ao norte da Aliança acima das Montanhas Cristarrubra contra o clã Rocha Negra e os anões Ferro Negro, ele coordena missões de reconhecimento nos penhascos hostis abaixo. Ele também desempenha um papel crucial na coordenação de esforços para descobrir o destino de seu camarada capturado, o Marechal Reginald Windsor.",h="O Oficial Maxwell é um oficial de alta patente do exército de Ventobravo alocado na Vigia de Morgan, nas...",kw={"abismo rocha negra","estepes ardentes","general drakkisath","oficial maxwell","maxwell","vigia de morgan","reginald windsor","exército de ventobravo"},ang={["class:Warrior"]="Maxwell personifica a disciplina militar da linha de frente de Ventobravo, mantendo-se firme em meio às cinzas vulcânicas e coordenando investidas profundas atrás das linhas inimigas.",["faction:Alliance"]="Para os campeões da Aliança que enfrentam o calor escaldante das Estepes Ardentes, o Oficial Maxwell representa a autoridade de Ventobravo e a ponta de lança da campanha contra a Montanha Rocha Negra."},sec={{t="Um Posto Solitário nas Estepes",b="A Vigia de Morgan ergue-se como um posto avançado precário na borda sul das Estepes Ardentes, com vista para uma terra devastada e sufocada por cinzas, draconídeos e orcs Rocha Negra. O Oficial Maxwell comanda o destacamento militar de Ventobravo ali posicionado, oferecendo uma visão amigável e rara para viajantes que enfrentam os penhascos ardentes. A partir deste bastião rochoso, ele supervisiona manobras defensivas para manter contidas as forças hostis da montanha antes que possam avançar para o sul, em direção a Cristarrubra e Elwynn."},{t="Revelando a Verdade na Montanha",b="Além da contenção de rotina, Maxwell atua como o principal elo em campo para operações voltadas ao coração do Pico da Rocha Negra e do Abismo Rocha Negra. Quando surgem rumores de que o Marechal Reginald Windsor, capturado, ainda pode estar vivo nas masmorras dos anões Ferro Negro, é Maxwell quem recebe as informações, analisa os relatórios e direciona campeões de confiança para organizar um resgate. Seu posto avançado constitui a ponte essencial que conecta o reconhecimento da fronteira à turbulência política que se desenrola dentro dos portões de Ventobravo."}},faq={{q="Quem é o Oficial Maxwell?",a="O Oficial Maxwell é um comandante do exército de Ventobravo posicionado na Vigia de Morgan, nas Estepes Ardentes. Ele lidera as forças locais da Aliança que vigiam os orcs Rocha Negra, dragões negros e anões Ferro Negro.",al={"história do oficial maxwell","quem é maxwell"}},{q="Por que o Oficial Maxwell está posicionado na Vigia de Morgan?",a="A Vigia de Morgan é o acampamento de linha de frente da Aliança que faz fronteira com as Estepes Ardentes. Maxwell está alocado ali para proteger a passagem na montanha que desce para as Montanhas Cristarrubra e monitorar as ameaças que emergem da Montanha Rocha Negra.",al={"por que maxwell está nas estepes ardentes","comandante da vigia de morgan"}},{q="Qual é a ligação de Maxwell com o Marechal Windsor?",a="Maxwell é o comandante essencial que ajuda na busca pelo Marechal Reginald Windsor, que foi capturado e arrastado para o Abismo Rocha Negra. Maxwell ajuda a coordenar os esforços de resgate e encaminha informações cruciais sobre Windsor de volta a Ventobravo.",al={"maxwell e windsor","história da missão esperança abandonada"}},{q="O Oficial Maxwell ajuda a organizar ataques contra o Pico da Rocha Negra?",a="Sim. Maxwell direciona campeões veteranos da Aliança para desmantelar os altos escalões do clã Rocha Negra, emitindo diretrizes com foco no General Drakkisath e em suas forças que dominam as alturas do Pico da Rocha Negra.",al={"maxwell drakkisath","missão de maxwell"}}},fp="15,446,28.475.0,36.518.1,23.216.0,51.231.0,48.243.0,67.205.0"}
P.entries["npc:marshal-mcbride"] = {n="Major Belmonte",s="O Major Douglas Belmonte é o comandante da guarnição de Ventobravo posicionada na Abadia de Vila Norte. Encarregado da defesa do Vale de Vila Norte, ele comanda recrutas recém-chegados contra a crescente infestação de kobolds que ameaça as fazendas e minas locais. Ele atua como a principal autoridade militar para novatos que iniciam seu serviço ao reino de Ventobravo.",h="O Major Douglas Belmonte é o comandante da guarnição de Ventobravo posicionada na Abadia de Vila Norte.",kw={"douglas belmonte","serra do eco","elwynn","kobold","major belmonte","vila norte","abadia de vila norte"},ang={["class:Warrior"]="Belmonte busca ativamente guerreiros robustos para servir ao reino, contando com combatentes de linha de frente para desobstruir os túneis da Serra do Eco.",["faction:Alliance"]="Belmonte representa a fronteira inicial da Grande Aliança no coração da humanidade, introduzindo recrutas a serviço da Coroa.",["race:Human"]="Para os humanos que começam suas aventuras em Vila Norte, o Major Belmonte é o primeiro representante da autoridade real de Ventobravo com quem entram em contato."},sec={{t="Comandante de Vila Norte",b="Estacionado nos arredores da Abadia de Vila Norte, o Major Douglas Belmonte representa a autoridade direta do Exército de Ventobravo neste vale tranquilo. Embora a abadia em si seja um enclave de fé e aprendizado, a crescente instabilidade por todo o reino dispersou e sobrecarregou as guarnições militares. Belmonte precisa manter a paz e proteger os suprimentos de alimentos e recursos do vale com apenas um punhado de guardas juramentados e um fluxo de recrutas inexperientes que buscam treinamento com os mestres da abadia."},{t="A Incursão Kobold",b="A principal dor de cabeça de Belmonte é a súbita agressividade das pragas locais. Os kobolds, antes apenas um incômodo, invadiram as florestas ao redor e tomaram a Mina da Serra do Eco — um recurso local vital. Sem soldados regulares suficientes para eliminá-los, Belmonte mobiliza paladinos, guerreiros e outros novatos para repelir as pragas escavadoras e descobrir a extensão da infestação antes que o vale fique completamente encurralado."}},faq={{q="Quem é o Major Belmonte?",a="O Major Douglas Belmonte é um oficial do Exército de Ventobravo que atua como comandante da guarnição na Abadia de Vila Norte. Ele é responsável por defender o Vale de Vila Norte e encaminhar novos recrutas para o serviço.",al={"major belmonte","quem é belmonte","comandante de vila norte"}},{q="Por que Belmonte faz os recrutas enfrentarem kobolds?",a="Os kobolds infestaram as florestas ao redor de Vila Norte e tomaram o controle da Mina da Serra do Eco. Com as forças armadas de Ventobravo sobrecarregadas, Belmonte depende de aventureiros recém-chegados para eliminar as pragas e proteger a área.",al={"por que matar kobolds","problema dos kobolds","problema da serra do eco"}},{q="Para onde Belmonte envia os recrutas em seguida?",a="Assim que o recruta demonstra sua capacidade lidando com as ameaças no Vale de Vila Norte, Belmonte o envia pela estrada do sul até a Vila d'Ouro para ajudar o Delegado Durão.",al={"para onde ir depois do belmonte","depois de vila norte","próxima vila"}},{q="O que é a Mina da Serra do Eco?",a="A Mina da Serra do Eco é uma caverna rica em minérios localizada no extremo norte do Vale de Vila Norte. Recentemente, foi invadida por kobolds escavadores, o que levou Belmonte a ordenar diversas operações para retomá-la.",al={"serra do eco","a mina em vila norte"}},{q="Belmonte comanda a abadia em si?",a="Não. A Abadia de Vila Norte é mantida pelas ordens sagradas e pelos sacerdotes da Luz. Belmonte supervisiona a guarnição militar encarregada de defender a abadia e o vale ao redor.",al={"belmonte lidera a abadia de vila norte","quem comanda a abadia"}},{q="Belmonte se preocupa com ameaças além dos kobolds?",a="Embora os kobolds sejam o incômodo mais imediato, Belmonte vigia indícios de uma instabilidade mais profunda. Bandidos e foras da lei rondam os limites do vale, indicando uma agitação mais ampla que se forma por toda a Floresta de Elwynn.",al={"defias em vila norte","vila norte é segura"}}},fx={["05ea779e"]={q="De que lado está o Major Belmonte?",a="O Major Belmonte é um oficial leal do Exército de Ventobravo e da Grande Aliança. Ele responde à coroa de Ventobravo e mantém vigilância sobre o Vale de Vila Norte para garantir a segurança dos cidadãos do reino e treinar recrutas.",al={"a quem belmonte serve","lealdade de belmonte","qual a facção de belmonte"}},b6028054={q="O que o Major Belmonte quer?",a="Belmonte quer garantir a segurança do Vale de Vila Norte contra ameaças locais crescentes. Com o Exército de Ventobravo operando no limite, ele busca mobilizar novos recrutas, paladinos e voluntários para eliminar os agressivos kobolds que infestam o vale e retomar a Mina da Serra do Eco.",al={"objetivo de belmonte","o que belmonte está tentando fazer","planos de belmonte"}},cc66b2df={q="Por que o Major Belmonte está aqui?",a="Belmonte está estacionado fora da Abadia de Vila Norte como comandante da guarnição militar do vale. Ventobravo o encarregou de manter a ordem, organizar as defesas e treinar recém-chegados antes de enviar soldados provados para a Floresta de Elwynn e além.",al={"por que belmonte está em vila norte","posto de belmonte","por que o major belmonte está na abadia"}},["307fdf7d"]={q="A quem o Major Belmonte está ligado?",a="Belmonte está ligado ao alto comando do Exército de Ventobravo e coordena com autoridades locais por toda Elwynn, eventualmente direcionando combatentes capazes para o Delegado Durão em Vila d'Ouro. Ele trabalha ao lado do clero e dos instrutores da abadia para preparar novos defensores para o reino.",al={"conexões de belmonte","a quem belmonte se reporta","exército de ventobravo de belmonte"}}},fp="15,363,23.465.0,20.415.0,23.204.0,45.217.0,38.181.0,24.203.0,38.178.0,50.197.0"}
P.entries["npc:martie-jainrose"] = {n="Martie Jainrose",s="Martie Jainrose é a herborista local de Vila Plácida, cuidando de seu jardim à beira do Lago Plácido nas Montanhas Cristarrubra. Além de cultivar remédios e flores para a cidade assolada, ela lida com feras selvagens pisoteando seus canteiros e nutre uma afeição discreta pelo Guarda Parker.",h="Martie Jainrose é a herborista local de Vila Plácida, cuidando de seu jardim à beira do Lago Plácido nas...",kw={"bellygrub","narcisos","guarda parker","herborista","vila plácida","martie jainrose","montanhas cristarrubra"},ang={["faction:Alliance"]="A perseverança de Martie em Vila Plácida reflete a resiliência do povo das Montanhas Cristarrubra, esforçando-se para manter uma vida doméstica comum mesmo enquanto Ventobravo deixa a cidade amplamente entregue à própria sorte.",["profession:Herbalism"]="Para herboristas praticantes que viajam pelas Montanhas Cristarrubra, Martie representa uma afinidade familiar, cuidando de uma flora frágil apesar das predações implacáveis de javalis selvagens e da invasão de inimigos."},sec={{t="Um Jardim à Beira do Lago",b="Residindo em Vila Plácida, Martie Jainrose trabalha diligentemente como a herborista residente do assentamento. Mesmo enquanto orcs Rocha Negra, gnolls e bandidos locais ameaçam a região, Martie se concentra em manter a cidade abastecida com ervas frescas e arranjos florais. Seus afazeres diários são frequentemente interrompidos pela fauna local — mais notavelmente pelo monstruoso javali Bellygrub, que com frequência assola seus preciosos canteiros de jardim. Além de suas atividades com ervas, Martie parece nutrir um carinho pelo Guarda Parker, embora Parker esteja cortejando Darcy, que chama Martie de rival ciumenta."}},faq={{q="Quem é Martie Jainrose?",a="Martie Jainrose é uma herborista humana que vive em Vila Plácida, nas Montanhas Cristarrubra. Ela cuida de um jardim ao lado do Lago Plácido, cultivando a flora e preparando remédios de ervas para os moradores locais.",al={"martie jainrose","quem é martie","herborista de vila plácida"}},{q="Que problemas Martie tem com a fauna local?",a="Um javali selvagem enorme e notoriamente teimoso chamado Bellygrub passou a atacar os canteiros de seu jardim, pisoteando suas plantações delicadas e comendo suas ervas antes que ela possa colhê-las.",al={"problema de martie com javali","jardim de bellygrub","quem está destruindo o jardim dela"}},{q="De quem Martie gosta em Vila Plácida?",a="Martie parece ter uma queda pelo Guarda Parker, um dos guardas da cidade. Parker, no entanto, está cortejando Darcy e, ao enviar a Darcy um buquê de narcisos de Martie, ele pede que não contem a Martie para quem se destina.",al={"paixão de martie","martie guarda parker","romance em delivering daffodils"}}},fx={["4d2b4277"]={q="De que lado está Martie Jainrose?",a="Martie é uma cidadã leal da Aliança que vive pacificamente em Vila Plácida. Embora ela não lute nas linhas de frente nem carregue armas, ela apoia a cidade e seus defensores através de seu comércio como herborista.",al={"facção de martie jainrose","martie é da aliança"}},e745a8a7={q="O que Martie Jainrose quer?",a="Martie quer cuidar de seu jardim em paz e dedicar-se ao seu ofício de herborista sem interferências. Seu incômodo imediato é um javali enorme chamado Panzagordo que continua pisoteando suas colheitas preciosas, e ela recebe de bom grado qualquer viajante disposto a afastar a besta.",al={"objetivo de martie jainrose","o que martie precisa"}},["6d429f48"]={q="Por que Martie Jainrose está em Vila Plácida?",a="Vila Plácida é o lar de Martie, onde ela ganha a vida cultivando ervas e cuidando de seu jardim ao longo das margens tranquilas do Lago Plácido, apesar dos crescentes problemas que afligem as Montanhas Cristarrubra circundantes.",al={"por que martie está em cristarrubra","por que martie jainrose está aqui"}}},fp="15,293,20.545.0,23.202.0,54.182.0,35.199.0"}
P.entries["npc:marukai"] = {n="Marukai",s="Marukai é uma troll da selva Lançanegra posicionada no Assentamento Zoram'gar, ao longo da costa enevoada do noroeste de Vale Gris. Dedicada a manter essa remota cabeça de ponte para a Horda, ela coordena esforços para abater os nagas Wrathtail invasores que ameaçam o assentamento.",h="Marukai é uma troll da selva Lançanegra posicionada no Assentamento Zoram'gar, ao longo da costa enevoada do...",kw={"vale gris","lançanegra","troll da selva","marukai","naga","wrathtail","praia de zoram","assentamento zoram'gar"},ang={["faction:Horde"]="Marukai sustenta um dos acampamentos costeiros mais precários da Horda em território de elfos noturnos, contando com campeões aliados para impedir que os nagas locais dominem sua posição.",["race:Troll"]="Longe dos ecos acolhedores da Aldeia Sen'jin, Marukai representa a resiliência da tribo Lançanegra enquanto eles constroem pontos de apoio fortificados para a Horda por toda Kalimdor."},sec={{t="Defendendo a Praia",b="O Assentamento Zoram'gar fica isolado na extremidade norte da Praia de Zoram, cercado por ruínas antigas, território hostil de elfos noturnos e o mar agitado. À medida que os nagas Wrathtail emergem em peso das águas e das antigas ruínas élficas para reivindicar o litoral, Marukai trabalha para evitar que o acampamento seja subjugado. Ela orienta os campeões da Horda a empurrar o povo-serpente de volta para a maré e coletar suas cabeças, garantindo que o entreposto continue sendo uma fortaleza costeira viável."}},faq={{q="Quem é Marukai?",a="Marukai é uma troll da selva distribuidora de missões que defende o Assentamento Zoram'gar, o acampamento costeiro isolado da Horda nas margens noroeste de Vale Gris.",al={"marukai história","quem é marukai","marukai npc"}},{q="Por que Marukai está lutando contra os nagas?",a="Os nagas Wrathtail infestaram a vizinha Praia de Zoram e as ruínas ao redor. Para proteger as fronteiras do posto e garantir a sobrevivência da Horda na costa, Marukai recruta aventureiros para reduzir o número deles caçando-os diretamente.",al={"por que matar naga","marukai missão de naga","praia de zoram naga"}},{q="Onde Marukai fica?",a="Ela pode ser encontrada ao lado de seus parentes no Assentamento Zoram'gar, situado na foz da Praia de Zoram, no noroeste de Vale Gris, logo ao sul das ruínas submersas de Profundezas Negras.",al={"onde fica marukai","localização de marukai","encontrar marukai"}}},fx={["53dc13db"]={q="De que lado está Marukai?",a="Marukai é leal à Horda. Operando a partir do Assentamento Zoram'gar ao longo da costa de Vale Gris, ela mantém guarda sobre os interesses da Horda e conta com viajantes da Horda para defender o assentamento contra perigos locais.",al={"facção de marukai","marukai é da horda","a quem marukai serve"}},["1bf5ddde"]={q="Por que Marukai está aqui no Assentamento Zoram'gar?",a="Marukai está estacionada no Assentamento Zoram'gar para defender a posição da Horda em The Zoram Strand. Com os agressivos naga Cauda-de-cólera retornando às praias e ameaçando as fronteiras do acampamento, ela coordena esforços para garantir o perímetro e manter o posto avançado seguro.",al={"por que marukai está em vale gris","propósito de marukai","o que traz marukai aqui"}}},fp="7,259,18.471.0,15.146.0,33.230.0,25.190.0"}
P.entries["npc:master-apothecary-faranell"] = {n="Mestre-boticário Faranello",s="O Mestre-boticário Faranello é o líder da Real Sociedade de Boticários, estabelecido nas profundezas do Boticarium na Cidade Baixa. Em vida, um respeitado erudito de Dalaran, na morte-vida ele comanda a busca dos Renegados por Uma nova peste devastadora para erradicar tanto o Flagelo quanto os vivos.",h="O Mestre-boticário Faranello é o líder da Real Sociedade de Boticários, estabelecido nas profundezas do...",kw={"abominação","boticarium","praga","faranello","mestre-boticário faranello","nova peste","renferrel","sociedade dos boticários reais","sylvanas","cidade baixa"},ang={["faction:Horde"]="Embora aliados orcs, trolls e taurens possam ficar desconfortáveis com o lodo verde e as cobaias enjauladas do Boticarium, a pesquisa de Faranello é tolerada como uma guerra essencial contra a ameaça comum do Flagelo.",["profession:Herbalism"]="Os tanques de Faranello consomem quantidades infindáveis de plantas raras, musgos e extratos fúngicos, servindo como uma demonstração sombria de estudo botânico transformado em arma de destruição.",["race:Undead"]="Para os Renegados, Faranello representa a vanguarda da soberania biológica, trabalhando na escuridão para garantir que seu povo possua armas capazes de destruir o Lich Rei."},sec={{t="Uma Mente Perturbada pela Morte",b="Antes da Terceira Guerra, Faranello era um alquimista estimado que passou décadas estudando ao lado dos sábios magos de Dalaran. Ele dedicou seus dias mortais à busca por curas, remédios e poções para melhorar a saúde dos mortais. Quando a peste do Flagelo ceifou sua vida e ele ressurgiu como um Renegado de livre arbítrio, sua antiga curiosidade científica azedou em crueldade. Mantendo seu intelecto enciclopédico, ele trocou bálsamos de cura por reagentes catastróficos, tornando-se rapidamente um dos pesquisadores mais valorizados pela Rainha Sylvana Correventos nas entranhas da capital caída de Lordaeron."},{t="O Mestre do Boticarium",b="Operando a partir dos laboratórios nocivos do Boticarium, Faranello coordena as vastas pesquisas da Real Sociedade de Boticários. Ele supervisiona a construção de abominações pesadas e orienta boticários subordinados posicionados por toda Lordaeron e além. Cada lote de veneno estranho, sangue maculado e flora amaldiçoada coletado por pesquisadores de campo pelos continentes passa, em última análise, por seus tanques para destilação e aprimoramento."},{t="Criando a Nova Peste",b="A única e obsessiva meta de Faranello é cumprir o mandato da Dama Sombria: conceber a Nova Peste. Para preparar um contágio capaz de destruir Arthas e suas legiões acéfalas do Flagelo, Faranello coordena uma extensiva coleta de reagentes. Ele envia aventureiros para recuperar as notas de pesquisa de seu falecido colega, o Boticário Berard, do Vilarejo Lenhardente, obtém guano de morcego das profundas tocas do Urzal dos Tuscos e testa coloides ácidos nos órgãos de fanáticos do Monastério Escarlate."}},faq={{q="Quem é o Mestre-boticário Faranello?",a="Faranello é o líder da Real Sociedade de Boticários, a guilda alquímica a serviço de Grande Dama Sylvana Correventos na Cidade Baixa. Ele supervisiona todas as pesquisas relacionadas a toxinas, abominações costuradas e o desenvolvimento da Nova Peste.",al={"quem é faranello","história de faranello","líder dos boticários"}},{q="Onde Faranello pode ser encontrado?",a="Ele reside no Boticarium, o bairro alquímico localizado no setor oeste da Cidade Baixa, cercado por caldeirões borbulhantes, jaulas de teste e seus boticários subordinados.",al={"localização de faranello","onde fica o mestre-boticário faranello","encontrar faranello"}},{q="Qual era a história de Faranello antes de morrer?",a="Em vida, Faranello era um aclamado alquimista e médico que estudou com os magos de Dalaran. Ele passou seus anos como mortal inventando remédios para curar doenças antes que a peste o matasse e distorcesse sua curiosidade em direção a toxinas letais.",al={"passado de faranello","faranello esteve em dalaran","vida mortal de faranello"}},{q="O que a Real Sociedade de Boticários está tentando criar?",a="Sob as ordens da Rainha Sylvanas, a sociedade está fabricando Uma nova peste. O objetivo deles é forjar uma arma virulenta o bastante para destruir o Flagelo e obter vingança contra o Lich Rei, além de defender os Renegados de inimigos mortais.",al={"o que é a nova peste","o que os boticários estão criando","objetivos dos boticários"}},{q="Por que Faranello envia aventureiros ao Vilarejo Lenhardente?",a="Ele busca o diário de pesquisa de seu antigo colega, o Boticário Berard, que enlouqueceu e sucumbiu à maldição dos worgens em Lenhardente. As notas de campo de Berard contêm dados vitais sobre agentes tóxicos necessários para aprimorar os experimentos com a peste.",al={"missão receita para a morte faranello","por que vilarejo lenhardente","diário do boticário berard"}},{q="Por que ele precisa de reagentes do Urzal dos Tuscos e do Monastério Escarlate?",a="Faranello testa como compostos voláteis opostos interagem. Ele utiliza guano do urzal coletado nas tocas dos javatuscos de espinheiro junto aos corações recém-extraídos de fanáticos da Cruzada Escarlate para testar coloides ácidos e contaminação biológica.",al={"guano do urzal faranello","corações de fervor","corações do monastério escarlate"}}},fx={["90cc21c1"]={q="De que lado está o Mestre-boticário Faranello?",a="Faranello é totalmente devotado à Grande Dama Sylvana Correventos e aos Renegados. Como Mestre da Real Sociedade de Boticários, ele alinha suas pesquisas diretamente com as ambições da Dama Sombria, mobilizando seus alquimistas para erradicar seus inimigos e garantir a sobrevivência da nação de mortos-vivos, independentemente do custo moral.",al={"lealdade de faranello","a quem faranello serve","faranello é leal a sylvana"}},b168fd3d={q="Por que o Mestre-boticário Faranello está na Cidade Baixa?",a="Faranello supervisiona o Boticarium, o coração alquímico da Cidade Baixa. Deste vasto laboratório de cubas borbulhantes e vapores tóxicos, ele dirige a pesquisa da Real Sociedade de Boticários, testando misturas perigosas e coordenando a síntese de novas pragas e abominações poderosas para os Renegados.",al={"por que faranello está aqui","boticarium de faranello","por que faranello está na cidade baixa"}},["79d7ca05"]={q="A quem o Mestre-boticário Faranello está ligado?",a="Faranello serve diretamente à Rainha Sylvana Correventos e lidera a Real Sociedade de Boticários, direcionando pesquisadores subordinados como o Boticário Renferrel na Floresta de Pinhaprata e o Boticário Lindolfo no Contraforte de Eira dos Montes. Ele também mantém laços com outros pesquisadores, reunindo o trabalho de antigos colegas como o Boticário Berardo.",al={"conexões de faranello","quem trabalha com faranello","aliados de faranello"}},d3e005f3={q="Por que o Mestre-boticário Faranello é temido?",a="Outrora um estudioso conceituado em Dalaran, o brilhantismo intelectual de Faranello transformou-se em um sadismo profundo após sua ascensão na morte-vida. Ele é notório como o arquiteto sombrio por trás dos venenos e pragas mais letais dos Renegados, testando novas misturas horríveis tanto em vivos quanto em mortos sem qualquer remorso.",al={"por que faranello é famoso","reputação de faranello","faranello é perigoso"}}},fp="26,293,24.557.0,30.456.0,23.496.1,34.230.0,28.184.0,46.234.0,54.242.0,55.235.0,72.238.0"}
P.entries["npc:master-apothecary-lydon"] = {n="Boticário Lindolfo",s="O Boticário Lindolfo é um pesquisador mórbido da Real Sociedade de Boticários alocado na Serraria Tarren. Cronicamente deprimido e intensamente entediado, ele encontra alegria apenas em refinar misturas letais e assistir ao sofrimento dos vivos. Ele lidera as pesquisas sobre novas toxinas potentes com o objetivo de assegurar Eira dos Montes para os Renegados e promover a Nova Praga de Sylvanas.",h="O Boticário Lindolfo é um pesquisador mórbido da Real Sociedade de Boticários alocado na Serraria Tarren.",kw={"boticário","elixir of agony","faranello","eira dos montes","lindolfo","real sociedade de boticários","serraria tarren","umpi"},ang={["faction:Alliance"]="Para os humanos de Costa Sul, Lindolfo é um monstro horrível que prepara doenças letais e as testa indiscriminadamente em animais selvagens e fazendeiros cativos de Eira dos Montes.",["profession:Herbalism"]="A oficina de Lindolfo é repleta de reagentes, caldeirões e flora em decomposição, demonstrando como as artes tradicionais de coleta são transformadas em armas pela Sociedade dos Boticários.",["race:Undead"]="Lindolfo personifica a missão singular da Real Sociedade de Boticários: desenvolver a Nova Praga para assegurar um futuro para os Renegados e erradicar os vivos."},sec={{t="O Recluso da Serraria Tarren",b="Alocado dentro da capela transformada em laboratório na Serraria Tarren, o Boticário Lindolfo representa o espírito frio e calculista da Real Sociedade de Boticários. Acometido por uma melancolia profunda e lânguida, ele sente aversão pelas flores desabrochando e pelo ar puro de Contraforte de Eira dos Montes. O único passatempo que alivia sua perpétua tristeza é a arte de produzir a morte. Quando não está ocupado, passa o tempo envenenando, dissecando e reanimando seu desafortunado sapo de estimação, Umpi, esperando repetidamente a chegada de novos reagentes."},{t="Misturas de Agonia",b="Trabalhando em coordenação com o Mestre-boticário Faranello na Cidade Baixa, Lindolfo realiza extensos experimentos de campo por toda Eira dos Montes. Seu trabalho progride do Elixir do Sofrimento para o virulento Elixir of Agony. Para comprovar a potência deles, Lindolfo envia aventureiros para testar as poções em alvos locais, variando de animais selvagens inocentes e domesticados a fazendeiros humanos capturados. Sua lealdade máxima pertence inteiramente à Dama Sombria, ansiando pelo dia em que a Nova Praga finalizada purificará o mundo dos vivos."},{t="Veneno do Orixá",b="Além de suas misturas padrão, a curiosidade intelectual de Lindolfo se estende a venenos esotéricos. Quando frascos de veneno misterioso surgem na região, ele consulta místicos trolls como o Mestre Gadrin para rastrear sua origem. Essa investigação revela um rastro que conduz diretamente à deusa aranha Shadra, nas Terras Agrestes. Uma vez garantido, esse veneno primordial é enviado diretamente ao Boticarium na Cidade Baixa para avançar ainda mais a iniciativa da praga dos Renegados."}},faq={{q="Quem é o Boticário Lindolfo?",a="Ele é um alquimista da Real Sociedade de Boticários que atua a partir da Serraria Tarren, em Contraforte de Eira dos Montes. Ele supervisiona o desenvolvimento de várias pragas e toxinas experimentais em nome da Grande Dama Sylvana Correventos.",al={"quem é lindolfo","lindolfo serraria tarren","história do boticário lindolfo"}},{q="Por que Lindolfo é tão deprimido?",a="Lindolfo sofre de profunda melancolia e considera repulsivos a beleza natural e o ar fresco de Eira dos Montes. As únicas coisas que levantam seu ânimo são experimentos cruéis, o sofrimento dos vivos e o aroma dos fluidos alquímicos de embalsamamento.",al={"por que ele é triste","depressão de lindolfo","por que lindolfo é melancólico"}},{q="Quem é Umpi?",a="Umpi é uma sapa que Lindolfo mantém em sua oficina, referindo-se a ela ironicamente como sua assistente. Na realidade, ele alivia seu tédio extremo envenenando, matando e reanimando repetidamente a anfíbia indefesa.",al={"sapo de lindolfo","quem é o sapo","história de umpi"}},{q="O que é o Elixir of Agony?",a="É um potente veneno experimental que Lindolfo prepara a partir de Cogumelos Fuçalama, refinado com o colóide de decomposição do Mestre-boticário Faranello e ativado com uma forte poção de sangue de troll, daggerspine scales e torn fin eyes. Ele então batiza um barril de cerveja preta roubado dos anões de Dun Garok com o veneno e o testa em fazendeiros cativos em Eira dos Montes.",al={"missão elixir of agony","o que é elixir of agony","elixir de lindolfo"}},{q="Como Lindolfo se tornou um Renegado?",a="Nenhum registro relata como o próprio Lindolfo morreu ou renasceu. Como os outros Renegados, ele se libertou do controle do Lich Rei sob o comando de Sylvanas, e agora dedica sua existência de morto-vivo à Dama Sombria e à sua Nova Praga.",al={"passado de lindolfo","lindolfo era humano","lindolfo terceira guerra"}},{q="O que Lindolfo envia para a Cidade Baixa?",a="Após descobrir recipientes de veneno antigo nas Terras Agrestes e coordenar a queda da deusa aranha troll Shadra, Lindolfo coleta seu veneno divino e concentrado e o despacha diretamente para o Mestre-boticário Faranello para fortalecer a pesquisa de pragas da Sociedade.",al={"veneno de lindolfo para cidade baixa","missão veneno de shadra"}}},fx={["4ad88718"]={q="De que lado está o Boticário Lindolfo?",a="O Boticário Lindolfo é ferozmente leal à Grande Dama Sylvana Correventos, aos Renegados e à Horda. Ele é um pesquisador graduado da Real Sociedade de Boticários, recebendo orientação direta do Mestre-boticário Faranello na Cidade Baixa. Tudo o que ele prepara serve aos grandes planos de Sylvana para garantir o reino para os mortos-vivos.",al={"facção de lindolfo","quem lindolfo serve","lindolfo é renegado"}},["64f2c0db"]={q="O que o Boticário Lindolfo quer?",a="Lindolfo é consumido pela criação e aperfeiçoamento da Nova Praga para a Dama Sombria. Ele busca toxinas potentes, sangue de predadores e venenos letais por toda a região para refinar suas poções — incluindo o Elixir do Sofrimento e o Elixir of Agony — visando trazer miséria e morte aos vivos.",al={"o que lindolfo está tentando fazer","objetivo de lindolfo","por que lindolfo quer venenos"}},["26e1a5a5"]={q="Por que o Boticário Lindolfo está na Serraria Tarren?",a="Lindolfo está posicionado no laboratório de boticários da Serraria Tarren para reunir reagentes regionais e testar fórmulas alquímicas letais próximo ao território inimigo. O Contraforte de Eira dos Montes oferece campos de teste férteis contra a vida selvagem local, incursões hostis de anões e a cidade humana de Costa Sul, logo adiante.",al={"por que lindolfo está em eira dos montes","propósito de lindolfo na serraria tarren","por que o boticário lindolfo está aqui"}},["19c08bcd"]={q="A quem o Boticário Lindolfo está ligado?",a="Lindolfo responde diretamente ao Mestre-boticário Faranello e à Real Sociedade de Boticários. Ele colabora com colegas por toda Azeroth, ajudando Apothecary Zamah de Penhasco do Trovão a preparar uma toxina para os problemas da Horda na Cordilheira das Torres de Pedra, e coordenando pesquisas com outros boticários Renegados estacionados por toda Lordaeron.",al={"conexões de lindolfo","quem trabalha com lindolfo","aliados de lindolfo"}}},fp="16,354,26.508.0,20.517.1,16.465.1,24.213.0,26.245.0,12.207.0,28.337.1,30.208.0,38.260.1"}
P.entries["npc:master-gadrin"] = {n="Mestre Gadrin",s="Mestre Gadrin é um troll da selva idoso e um venerável curandeiro da tribo Lançanegra, atualmente residindo na Aldeia Sen'jin. Tendo outrora treinado os sacerdotes e magos da tribo ao lado do renegado curandeiro Zalazane, agora ele coordena esforços para ajudar seu povo desabrigado e quebrar a terrível maldição que assola seu lar roubado nas Ilhas do Eco.",h="Mestre Gadrin é um troll da selva idoso e um venerável curandeiro da tribo Lançanegra, atualmente residindo...",kw={"lançanegra","durotar","ilhas do eco","gadrin","mestre gadrin","minshina","aldeia sen'jin","vol'jin","curandeiro","zalazane"},ang={["class:Mage"]="Gadrin inovou ao instruir Trolls Lançanegra nas artes arcanas após a Terceira Guerra, provando que a magia troll podia ir muito além do mero mojo ritualístico.",["class:Priest"]="Como o ancião que instruiu os sacerdotes Lançanegra a comungar com os espíritos e os loas, Gadrin personifica as tradições de sombra e fé dos trolls da selva.",["faction:Horde"]="Mestre Gadrin é um dos conselheiros mais confiáveis de Vol'jin, mantendo olhos atentos na costa de Durotar e alertando Monte Navalha quando cultos sombrios ameaçam a jovem nação de Durotar.",["race:Troll"]="Para os Trolls Lançanegra, Mestre Gadrin é uma conexão viva com seu lar ancestral e com as tradições de Sen'jin. Ele moldou a liderança espiritual de sua tribo por gerações e sente um pesar paternal pela tragédia das Ilhas do Eco."},sec={{t="Mentor dos Lançanegra",b="Muito antes de os Lançanegra chegarem a Kalimdor, Mestre Gadrin serviu como curandeiro de sua tribo em suas ilhas ancestrais nos Mares do Sul, onde orientou o treinamento místico de gerações de Trolls Lançanegra."},{t="A Traição de Zalazane",b="Quando os Lançanegra se estabeleceram nas Ilhas do Eco ao lado da Horda, Gadrin e o jovem curandeiro Zalazane lideraram juntos o treinamento místico dos sacerdotes e magos da tribo. Tragicamente, Zalazane sucumbiu à loucura, embriagado pelas forças sombrias do vodu que buscava controlar. O praticante rebelde escravizou as mentes de seus irmãos e expulsou Vol'jin e os Lançanegra não corrompidos para o continente de Durotar. Agora estabelecido na Aldeia Sen'jin, Gadrin carrega a dor pessoal de ver um antigo companheiro se transformar em um monstro tirânico, trabalhando incansavelmente para conceder descanso aos membros da tribo mortos e pôr fim ao domínio de Zalazane."},{t="Guardião do Conhecimento Antigo",b="Além da crise nas Ilhas do Eco, Gadrin se destaca como uma das maiores autoridades vivas da Horda em espiritualismo troll e conhecimento sobre os loas. Eruditos, xamãs e até mesmo a Sociedade Real dos Boticários buscam suas percepções sobre mistérios arcanos e alquímicos. Quando ameaças estranhas como a Lâmina Ardente rondam Durotar, ou pesquisadores distantes necessitam de rituais esquecidos — como decifrar tabuletas antigas em Zul'Farrak para invocar Shadra, a loa aranha —, é Gadrin quem possui o conhecimento para criar as amarras necessárias."}},faq={{q="Quem é Mestre Gadrin?",a="Mestre Gadrin é um curandeiro e um líder espiritual ancião dos Trolls Lançanegra. Localizado na Aldeia Sen'jin, na costa de Durotar, ele atua como um conselheiro sênior do Chefe Vol'jin.",al={"história de mestre gadrin","quem é gadrin","npc gadrin"}},{q="Qual é a história de Gadrin com Zalazane?",a="Nas Ilhas do Eco, Gadrin e o jovem curandeiro Zalazane lideraram juntos o treinamento místico dos sacerdotes e magos dos Lançanegra, apenas para Gadrin assistir com horror Zalazane sucumbir à magia sombria, enlouquecer e expulsar os Lançanegra de seu lar insular.",al={"gadrin e zalazane","como gadrin conhece zalazane","mentor de zalazane"}},{q="Por que Gadrin está na Aldeia Sen'jin?",a="Quando a maldição de Zalazane expulsou os Lançanegra das Ilhas do Eco, os sobreviventes estabeleceram a Aldeia Sen'jin na costa sul de Durotar como refúgio. Gadrin permanece na aldeia para aconselhar refugiados, monitorar ameaças locais e direcionar ataques contra as forças de Zalazane.",al={"por que gadrin está aqui","o que gadrin está fazendo na aldeia senjin"}},{q="Quem é Minshina?",a="Minshina era irmão de Mestre Gadrin. Ele pereceu durante a turbulência nas Ilhas do Eco, e seu espírito inquieto começou a chamar por Gadrin em sonhos. Gadrin pede a aventureiros de confiança que recuperem o crânio de seu irmão para que sua alma possa finalmente encontrar a paz.",al={"irmão de minshina","história da missão crânio de minshina","quem foi minshina"}},{q="Gadrin ajuda contra o culto da Lâmina Ardente?",a="Sim. Após receber notícias de Zureta Vista-longa sobre a infiltração da Lâmina Ardente no Vale das Provações, Gadrin monitora a presença do culto perto da Aldeia Sen'jin. Vendo o perigo maior para Durotar, ele envia recrutas para o norte para se apresentarem a Orgnil Chaganalma em Monte Navalha.",al={"lâmina ardente durotar gadrin","orgnil chaganalma gadrin"}},{q="O que Gadrin sabe sobre a loa Shadra?",a="Gadrin é um mestre da antiga teologia troll. Quando o Renegado Boticário Lindolfo busca um veneno potente usado pelos trolls Casca-seca das Terras Agrestes, Gadrin o identifica como uma dádiva de Shadra, a loa aranha, direcionando aventureiros a Zul'Farrak para ler a tabuleta com seu verdadeiro nome, do qual ele precisa para escrever um feitiço de invocação.",al={"loa aranha shadra gadrin","deusa aranha gadrin"}}},fx={["48c543c3"]={q="De que lado está o Mestre Gadrin?",a="O Mestre Gadrin é leal à tribo Lançanegra e à Horda. Tendo viajado das Ilhas Lançanegra depois que Thrall salvou seu povo da Bruxa do Mar, ele serve como um ancião sênior, professor místico e conselheiro de confiança do Chefe Vol'jin.",al={"facção de gadrin","gadrin é da horda","quem gadrin serve"}},d3faca51={q="O que o Mestre Gadrin quer?",a="O Mestre Gadrin busca a morte do traiçoeiro bruxo Zalazane e a libertação das Ilhas do Eco. Ele deseja libertar seus parentes amaldiçoados do controle mental de Zalazane, recuperar o Crânio de Minshina, de seu falecido irmão, para que os espíritos possam descansar, e proteger a Aldeia Sen'jin dos perigos emergentes por toda Durotar.",al={"o que gadrin quer","objetivo de gadrin","motivo do mestre gadrin"}}},fp="13,354,23.211.0,24.606.0,22.522.0,21.190.0,39.259.0,41.267.0,16.245.0,45.268.0,43.327.0"}
P.entries["npc:master-vornal"] = {n="Mestre Vornal",s="O Mestre Vornal é um idoso troll da selva Lançanegra que reside na Aldeia Sen'jin, ao longo da costa sul de Durotar. Apesar de sua idade avançada e amplo conhecimento de misturas alquímicas, ele se recusa obstinadamente a aceitar qualquer aprendiz.",h="O Mestre Vornal é um idoso troll da selva Lançanegra que reside na Aldeia Sen'jin, ao longo da costa sul de...",kw={"a solvent spirit","lançanegra","durotar","mestre vornal","aldeia sen'jin","troll","vornal"},ang={["profession:Herbalism"]="Aqueles habilidosos com a flora bruta reconhecerão o olhar aguçado de Vornal para catalisadores raros e reagentes naturais severos necessários para seus solventes.",["race:Troll"]="Para os trolls Lançanegra, o Mestre Vornal representa os artesãos idosos e obstinados que ajudaram a fundar a Aldeia Sen'jin depois que a tribo fugiu de seu lar nas ilhas."},sec={{t="O Cervejeiro Obstinado de Sen'jin",b="O Mestre Vornal é uma figura constante da Aldeia Sen'jin, conhecido por preparar poções e destilados potentes para seus companheiros trolls Lançanegra. Embora a idade esteja visivelmente pesando sobre ele, Vornal permanece intensamente independente e se recusa obstinadamente a treinar qualquer aprendiz, preferindo misturar seus remédios e misturas voláteis inteiramente com suas próprias mãos."},{t="A Solvent Spirit",b="De tempos em tempos, Vornal encarrega jovens aventureiros de coletar ingredientes agressivos ou peculiares das terras vizinhas, como materiais potentes necessários para solventes e misturas. Embora esteja disposto a recompensar aqueles que o ajudam, ele mantém seus métodos e receitas precisos sob segredo, tratando seu ofício como uma busca solitária."}},faq={{q="Quem é o Mestre Vornal?",a="O Mestre Vornal é um idoso troll da selva Lançanegra que reside na Aldeia Sen'jin. Ele prepara destilados e remédios potentes para a tribo, mas insiste em trabalhar sem um aprendiz.",al={"mestre vornal","vornal","mestre vornal de sen'jin","quem é vornal"}},{q="Onde posso encontrar o Mestre Vornal?",a="Ele pode ser encontrado de pé entre as cabanas na Aldeia Sen'jin, situada ao longo da costa sul de Durotar, logo ao norte das Ilhas do Eco.",al={"localização de vornal","onde fica o mestre vornal","encontrar o mestre vornal"}},{q="Por que o Mestre Vornal se recusa a aceitar aprendizes?",a="Vornal diz que nenhum troll ou orc digno o suficiente jamais se apresentou. Embora seus olhos estejam falhando e ele dependa mais de sua alquimia, ele prefere trabalhar sozinho a ensinar alguém indigno.",al={"aprendiz de vornal","por que nenhum aprendiz","alunos de vornal"}},{q="Quais tarefas ele oferece aos aventureiros?",a="Vornal envia viajantes para coletar componentes brutos por toda a região para suas misturas de solventes, dependendo de viajantes para obter materiais enquanto mantém o processo de preparo estritamente para si mesmo.",al={"missão do mestre vornal","a solvent spirit","missão de vornal"}}},fx={e0bd334a={q="De que lado está o Mestre Vornal?",a="O Mestre Vornal é leal à tribo Lançanegra e à Horda. Ele faz da Aldeia Sen'jin seu lar, dedicando seu ofício e experiência para ajudar a proteger o jovem assentamento contra os perigos ao redor.",al={"lealdade de vornal","quem o mestre vornal serve","facção do mestre vornal"}},["27223be8"]={q="Por que o Mestre Vornal está na Aldeia Sen'jin?",a="O Mestre Vornal reside ao longo da costa de Durotar para ajudar seus parentes enquanto eles constroem uma nova existência no exílio. De sua casa na Aldeia Sen'jin, ele pratica seu comércio e incumbe viajantes de coletar os potentes reagentes de que necessita.",al={"por que o mestre vornal está aqui","por que vornal está na aldeia sen'jin","propósito de vornal em durotar"}},faf3afd9={q="O que o Mestre Vornal quer?",a="Embora esteja envelhecendo, o Mestre Vornal prefere trabalhar de forma independente e se recusa a se sobrecarregar com aprendizes. Em vez disso, ele recorre a aventureiros capazes para realizar suas tarefas e coletar destilados e solventes raros por toda Durotar.",al={"o que vornal quer","objetivo do mestre vornal","o que vornal está procurando"}}},fp="13,247,30.334.0,16.319.0,21.176.0,31.134.0,50.182.0,37.181.0"}
P.entries["npc:mastok-wrilehiss"] = {n="Mastok Wrilehiss",s="Mastok Wrilehiss é um oficial orc posicionado no Posto Machadada, na parte leste de Vale Gris. Atuando como um coordenador defensivo crucial para a Horda na floresta disputada, ele orienta batedores e guerreiros para proteger as fronteiras próximas e lidar com ameaças elementais corruptoras. Sua presença é vital para manter a posição precária que a Horda ocupa em meio à constante hostilidade dos elfos noturnos.",h="Mastok Wrilehiss é um oficial orc posicionado no Posto Machadada, na parte leste de Vale Gris.",kw={"vale gris","harmonia telúrica","mastok","orc","posto machadada","torres de pedra","wrilehiss"},ang={["class:Shaman"]="A preocupação de Mastok com os elementais corrompidos na floresta frequentemente direciona os aventureiros a buscarem orientação com a Harmonia Telúrica no Zoram'gar Strand.",["faction:Alliance"]="Mastok Wrilehiss representa a presença militar orca consolidada em Vale Gris, defendendo o assentamento fortificado de Posto Machadada contra as sentinelas elfas noturnas.",["faction:Horde"]="Para os campeões da Horda que lutam para manter um ponto de apoio nessa fronteira de Vale Gris, Mastok é um comandante fundamental que pode direcionar você a tarefas cruciais por toda a região."},sec={{t="Um Bastião nos Bosques Ancestrais",b="O Posto Machadada ergue-se sob a sombra densa das copas imponentes de Vale Gris, completamente cercado por território hostil de elfos noturnos. Mastok Wrilehiss atua como um dos principais defensores do posto, monitorando rotas de suprimentos e a movimentação na floresta. A posição é perigosa; qualquer sinal de fraqueza atrai investidas rápidas das Sentinelas, que consideram o assentamento uma intrusão espoliadora."},{t="Coordenando o Fronte",b="De seu posto de observação no cárcere, Mastok encarrega ativamente os aventureiros que passam por ali de cumprir missões estratégicas críticas. Ele vigia com atenção as fronteiras que levam a territórios vizinhos, como a Cordilheira das Torres de Pedra, e envia batedores para consultar xamãs como Je'neu Sancrea, da Harmonia Telúrica, no Zoram'gar Strand. Suas funções conectam a defesa militar ao monitoramento das forças estranhas e corruptoras que afligem os elementais locais."}},faq={{q="Quem é Mastok Wrilehiss?",a="Mastok Wrilehiss é um orc de elite posicionado no Posto Machadada, em Vale Gris. Ele atua como oficial e concedente de missões, encarregado de defender o entreposto contra incursões de elfos noturnos e investigar ameaças regionais próximas.",al={"quem é mastok","função de mastok wrilehiss","quem é este orc"}},{q="Onde Mastok Wrilehiss pode ser encontrado?",a="Ele fica dentro do Posto Machadada, um entreposto fortificado da Horda situado no centro-leste de Vale Gris, ao longo da estrada florestal principal.",al={"localização de mastok","onde fica mastok wrilehiss","mapa de mastok"}},{q="Quais tarefas Mastok atribui aos aventureiros?",a="Mastok encarrega aventureiros da Horda de missões estratégicas, incluindo investigar ameaças elementais corrompidas na floresta, proteger passagens em direção a Torres de Pedra e encaminhar emissários a Je'neu Sancrea, da Harmonia Telúrica.",al={"missões de mastok","missões com mastok"}},{q="Por que o Posto Machadada sofre pressão constante?",a="O entreposto serve como um centro de extração de madeira e fortaleza crucial da Horda em Vale Gris. Os elfos noturnos nativos veem a presença dos orcs e a extração de madeira como uma profanação severa de terras sagradas, resultando em confrontos intermináveis.",al={"por que elfos noturnos atacam posto machadada","conflito no posto machadada"}},{q="Por que Mastok envia viajantes a Je'neu Sancrea?",a="Os xamãs da Harmonia Telúrica, incluindo Je'neu no Zoram'gar Strand, estudam e curam a instabilidade elemental que assola Vale Gris. Mastok conecta os combatentes da linha de frente ao conhecimento espiritual deles para lidar com elementais da água maculados e perturbações estranhas.",al={"por que contatar harmonia telúrica","mastok e jeneu"}},{q="Mastok Wrilehiss é hostil a jogadores da Aliança?",a="Sim. Mastok é um membro leal da Horda e um defensor de elite do Posto Machadada, o que significa que atacará jogadores da Aliança assim que eles se aproximarem do acampamento.",al={"aliança pode falar com mastok","mastok pode ser morto"}}},fx={["414a3ea9"]={q="Por que Mastok Wrilehiss está no Vale Gris?",a="Mastok Wrilehiss está posicionado no Posto Machadada para ajudar a garantir a presença da Horda nas florestas disputadas do Vale Gris. Como um defensor experiente entre as forças do Brado Guerreiro, ele supervisiona os esforços de defesa locais, rastreia distúrbios que afetam as áreas selvagens ao redor e recruta viajantes capazes para lidar com ameaças elementais corruptoras e hostilidades dos elfos noturnos vizinhos.",al={"por que mastok está aqui","mastok wrilehiss posto machadada","por que mastok está no posto machadada"}}},fp="16,381,30.377.0,22.436.0,24.219.0,36.129.0,45.216.0,49.238.0,49.251.0,48.172.0"}
P.entries["npc:mathias-shaw"] = {n="Mathias Shaw",s="O Mestre Mathias Shaw é o líder da AVIN, a agência secreta de inteligência do Reino de Ventobravo. Operando a partir das sombras da Cidade Velha, ele comanda espiões e batedores para proteger o reino tanto de conspirações internas quanto de horrores externos.",h="O Mestre Mathias Shaw é o líder da AVIN, a agência secreta de inteligência do Reino de Ventobravo.",kw={"assassino","blightcaller","kearnen","mathias shaw","cidade velha","avin","mestre de espionagem","ventobravo","vancleef"},ang={["class:Rogue"]="Mathias Shaw representa o ápice absoluto da perícia ladina humana. Ladinos da Aliança são frequentemente enviados a ele para missões táticas avançadas e venenos especiais.",["faction:Alliance"]="Como mestre de espionagem do reino, Shaw atua como a primeira linha de defesa contra a subversão, reunindo informações militares vitais para o Grão-lorde Bolvar Fordragon e o menino-rei Anduin.",["race:Human"]="A guerra de Shaw contra a Irmandade Défias reflete a divisão mais ampla e amarga dentro do Reino de Ventobravo após sua reconstrução."},sec={{t="Mestre da AVIN",b="Mathias Shaw é o principal mestre de espionagem e assassino de Ventobravo. A partir do discreto quartel-general da AVIN, escondido atrás do quartel na Cidade Velha, Shaw coordena uma rede secreta que se estende pelos Reinos do Leste e além. Pragmático, calculista e ferozmente leal à House of Wrynn, ele opera sob a filosofia de que a segurança de Ventobravo depende tanto de adagas invisíveis e cartas roubadas quanto de armaduras reluzentes e guarnições palacianas."},{t="Sombra de VanCleef",b="Shaw compartilha uma história profundamente pessoal com Edwin VanCleef, líder da rebelde Irmandade Défias. Os dois eram companheiros de infância, e Shaw treinou pessoalmente VanCleef nas artes da furtividade e do assassinato, esperando um dia que o talentoso pedreiro usasse seus dons para servir ao reino ao seu lado. Em vez disso, quando a Stonemasons Guild foi expulsa após a reconstrução de Ventobravo, VanCleef voltou essas lições letais contra a coroa. Hoje, Shaw comanda as operações de vigilância e infiltração destinadas a desmantelar a insurreição de seu velho amigo por todo o Cerro Oeste."},{t="Olhos Pelos Reinos",b="Enquanto a insurreição interna consome Cerro Oeste e Elwynn, a atenção de Shaw é constantemente atraída para fora, em direção a perigos letais desconhecidos. Quando chegaram até ele relatos de operações bizarras dos Renegados nas Terras Pestilentas Orientais, ele enviou cinco de seus melhores agentes para investigar. Apenas um retornou vivo — balbuciando de terror sobre \"Nathanos\" e um \"Blightcaller\" antes de morrer durante o sono. Shaw confia em campeões independentes para se aventurarem onde seus batedores desaparecem, buscando dissipar a escuridão que se acumula nas fronteiras do reino."}},faq={{q="Quem é Mathias Shaw?",a="Mathias Shaw é o líder da AVIN, o serviço de inteligência e guilda de assassinos de Ventobravo. Operando a partir da Cidade Velha, ele coordena a espionagem e a defesa secreta do reino sob a autoridade do trono.",al={"quem é shaw","líder da avin","história de mathias shaw","mestre de espionagem de ventobravo"}},{q="Onde Mathias Shaw pode ser encontrado?",a="Ele está localizado dentro do quartel-general da AVIN, no distrito da Cidade Velha em Ventobravo, reservado atrás do quartel militar.",al={"localização de shaw","onde está mathias shaw","encontrar mathias shaw"}},{q="Qual é a ligação dele com Edwin VanCleef?",a="Essa história é um dos segredos de Cerro Oeste. Shaw relata o que a AVIN sabe sobre a Stonemasons Guild em um relatório para Gryan Stoutmantle, e aqueles que seguirem a Irmandade Défias até o fim descobrirão o quão estreitamente os dois estão ligados.",al={"shaw e vancleef","amigo de vancleef","mathias e edwin"}},{q="O que significa AVIN?",a="A AVIN é a principal organização de inteligência de Ventobravo, especializada em vigilância, reconhecimento, espionagem e assassinatos secretos para proteger os interesses do reino e da Aliança.",al={"o que é a avin","o que significa avin","inteligência de ventobravo"}},{q="Por que Mathias Shaw está interessado em Cerro Oeste?",a="Cerro Oeste é o reduto da Irmandade Défias. Shaw mantém agentes ativos na região para espionar as atividades rebeldes e frustrar suas conspirações contra Ventobravo.",al={"shaw cerro oeste","avin cerro oeste","klaven's tower"}},{q="O que aconteceu com os agentes que Shaw enviou para as Plaguelands?",a="Shaw enviou cinco agentes para patrulhar movimentações suspeitas dos Renegados nas Terras Pestilentas Orientais. Quatro nunca retornaram, e o único sobrevivente voltou balbuciando sobre \"Nathanos\" e um \"Blightcaller\" antes de morrer durante o sono dias depois.",al={"missão de shaw em plaguelands","cinco batedores shaw","batedores do sítio dos marris"}}},fx={ad27d291={q="De que lado está Mathias Shaw?",a="O Mestre Mathias Shaw serve à Aliança, à Casa Wrynn e ao Reino de Ventobravo com lealdade inabalável. Como líder da agência de inteligência do reino, cada missão secreta que ele supervisiona e cada espião que ele dirige é dedicado a proteger Ventobravo contra subversão interna e ameaças estrangeiras.",al={"facção de mathias shaw","quem shaw serve","mathias shaw é leal"}},["14719004"]={q="O que Mathias Shaw quer?",a="A principal preocupação de Shaw é eliminar ameaças existenciais a Ventobravo antes que elas ataquem. Ele direciona a rede secreta da AVIN para desmantelar as conspirações da The Defias Brotherhood, monitorar movimentos perigosos dos Renegados no norte e reunir a inteligência necessária para preservar a segurança do reino durante uma era de profunda vulnerabilidade política.",al={"objetivo de mathias shaw","o que shaw quer","motivos de shaw"}},a0b783f7={q="Por que Mathias Shaw é famoso ou temido?",a="Shaw é conhecido por todo o reino como o mestre dos espiões e mestre dos assassinos. Renomado por sua habilidade suprema em furtividade, infiltração e letalidade silenciosa, sua rede de inteligência de longo alcance significa que muito pouco acontece no reino sem o seu conhecimento — ou a intervenção de suas lâminas.",al={"por que mathias shaw é famoso","por que shaw é temido","mestre dos assassinos"}}},fp="12,246,14.449.0,18.587.1,24.517.0,20.212.0,32.125.0,41.233.0,25.191.0,43.166.0,57.235.0"}
P.entries["npc:mathredis-firestar"] = {n="Mathredis Estelígnea",s="Mathredis Estelígnea é um excêntrico mago elfo sangrento que reside no Monte Candente, nas Estepes Ardentes. Ele cria encantamentos poderosos conhecidos como Arcanos Inferiores, baseando-se nas pesquisas arcanas de seu falecido mestre. Ao fazer isso, ele se alimenta das energias residuais liberadas durante o processo de vinculação para saciar seu vício em magia.",h="Mathredis Estelígnea é um excêntrico mago elfo sangrento que reside no Monte Candente, nas Estepes Ardentes.",kw={"arcano","estepes ardentes","dreamseeker","estelígnea","monte candente","compêndio","mathredis","telmius"},ang={["class:Mage"]="Os magos reconhecerão a síntese de arcanos de Mathredis como um método desesperado e volátil de extrair nutrição mágica bruta do processo de vinculação de itens."},sec={{t="O legado de um mestre e o vício em magia",b="Mathredis Estelígnea aprendeu o ofício de criar arcanos — gemas concentradas de fortalecimento arcano — com seu mentor, Telmius Dreamseeker. Telmius encontrou um fim trágico nas antigas ruínas de Gládio Cruel enquanto tentava arrancar segredos mágicos dos Shen'dralar. Embora Telmius tenha inventado essas vinculações mágicas, Mathredis não possui o domínio necessário para produzir os mais poderosos dentre eles. Em vez disso, ele se especializa em Arcanos Inferiores. Para Mathredis, esse trabalho é muito mais do que um exercício acadêmico: como todos os elfos sangrentos após a queda da Nascente do Sol, ele sofre de uma fome voraz por poder arcano. Vincular materiais a compêndios antigos libera descargas violentas de energia mágica, as quais Mathredis absorve para se sustentar."},{t="A arte do Arcano",b="Aventureiros que levarem a Mathredis os tomos adequados — como os Compêndios de Constituição, Resiliência, Ruminação, Tenacidade ou Voracidade — acompanhados de reagentes raros o encontrarão ansioso para trocar seus serviços. O processo vincula reagentes mágicos voláteis diretamente ao texto, concentrando sua essência em um arcano capaz de encantar permanentemente elmos ou perneiras. Contanto que os aventureiros forneçam os componentes, Mathredis obtém tanto o pagamento quanto o sustento arcano ambiente de que necessita desesperadamente."}},faq={{q="Quem é Mathredis Estelígnea?",a="Mathredis Estelígnea é um mago elfo sangrento instalado no entreposto neutro do Monte Candente, nas Estepes Ardentes. Ele é um arcanista capaz de forjar Arcanos Inferiores para encantar armaduras.",al={"história de mathredis","quem é mathredis estelígnea","estelígnea elfo sangrento"}},{q="Por que Mathredis cria arcanos?",a="Após a destruição da Nascente do Sol, os elfos sangrentos sofrem de uma abstinência mágica severa. Mathredis se alimenta das energias mágicas residuais e brutas liberadas durante a criação e a vinculação dos arcanos para aplacar seu vício racial.",al={"por que criar arcanos","motivação de mathredis","por que compêndios"}},{q="Quem foi Telmius Dreamseeker?",a="Telmius Dreamseeker foi o falecido mestre de Mathredis e o inventor original dos arcanos. Telmius aventurou-se pelas ruínas de Gládio Cruel para extrair conhecimento dos Shen'dralar, mas foi assassinado lá antes de conseguir transmitir todo o seu conhecimento.",al={"telmius","mestre de mathredis","quem era o mestre dele"}},{q="Que tipos de arcanos Mathredis pode fabricar?",a="Mathredis pode forjar Arcanos Inferiores de Constituição, Resiliência, Ruminação, Tenacidade e Voracidade. Os arcanos mais potentes eram conhecidos apenas por seu mestre Telmius e continuam além do alcance de Mathredis.",al={"quais arcanos","arcanos inferiores","lista de compêndios"}}},fp="18,330,37.709.0,22.497.0,26.181.0,35.233.0,28.245.0,42.200.0"}
P.entries["npc:mathrengyl-bearwalker"] = {n="Mathrengyl Ursivagus",s="Mathrengyl Ursivagus é um mestre instrutor de druidas e um respeitado ancião do Círculo Cenariano que reside no Enclave Cenariano de Darnassus. Tendo servido outrora como assistente direto do Arquidruida Fandral Guenelmo, ele orienta jovens druidas da Aliança através de suas provações espirituais, ritos de metamorfose e deveres por toda Kalimdor.",h="Mathrengyl Ursivagus é um mestre instrutor de druidas e um respeitado ancião do Círculo Cenariano que reside...",kw={"aquatic form","forma de urso","ursivagus","círculo cenariano","enclave cenariano","darnassus","druid of the claw","instrutor de druidas","fandral guenelmo","mathrengyl ursivagus","morrowgrain","teldrassil"},ang={["class:Druid"]="Para os druidas da Aliança, Mathrengyl é um mentor essencial que une Darnassus à Clareira da Lua, revelando os segredos da Forma de Urso, da Aquatic Form e de curas herbais para venenos mortais.",["faction:Alliance"]="Mathrengyl representa a liderança firme e tradicional do Círculo Cenariano em Darnassus, oferecendo um contraste sereno à postura agressiva de Fandral Guenelmo.",["race:NightElf"]="Um modelo do druidismo kaldorei, Mathrengyl personifica a devoção à natureza e ao equilíbrio após a Terceira Guerra e o crescimento de Teldrassil."},sec={{t="Mentor do Enclave Cenariano",b="Situado nos limites verdejantes do Enclave Cenariano em Darnassus, Mathrengyl Ursivagus destaca-se como um dos druidas mais veneráveis e equilibrados de Teldrassil. Ele atua como o principal guia para os jovens druidas da Aliança, supervisionando sua comunhão com a Clareira da Lua e testando sua prontidão para dominar formas animais primitivas. Tendo passado pela intensa e desconcertante comunhão com o Grande Espírito do Urso em sua própria juventude, Mathrengyl compreende o peso desses ritos, incumbindo pessoalmente os iniciados de provar seu espírito contra o sagrado noctélfico Lunaclaw antes de admiti-los no caminho do Druid of the Claw."},{t="A Serviço do Arquidruida",b="Mathrengyl atuou por muito tempo como o braço direito de Fandral Guenelmo, administrando os assuntos cotidianos do círculo e cuidando do recrutamento para os ambiciosos empreendimentos do Arquidruida. Quando Fandral exigiu vastas quantidades de morrowgrain, Mathrengyl organizou sua coleta com os aventureiros que retornavam, apesar de confidenciar reservadamente um silencioso mal-estar em relação à essência antinatural da estranha planta. Ele também coordena as respostas da Aliança aos chamados da Clareira da Lua, navegando pela delicada política do Círculo Cenariano enquanto Fandral volta seu olhar para o sul de Kalimdor."},{t="Uma Perspectiva Mais Ampla",b="Enquanto Guenelmo é infame por seu orgulho ferrenho e desdém por outras raças, Mathrengyl frequentemente demonstra uma mente mais contemplativa e aberta. Quando relíquias chegaram a Darnassus vindas do finado druida Mulgris Deepriver — que tombou combatendo o Flagelo nas Terras Pestilentas Ocidentais —, Mathrengyl ficou profundamente emocionado ao descobrir que o investigador era um tauren. Refletindo sobre a missão compartilhada do Círculo Cenariano, ele ponderou em silêncio que os taurens talvez não tenham se afastado tanto dos ensinamentos de Cenarius quanto o Arquidruida insiste."}},faq={{q="Quem é Mathrengyl Ursivagus?",a="Mathrengyl Ursivagus é um veterano instrutor de druidas elfo noturno baseado no Enclave Cenariano, em Darnassus. Reverenciado como um dos sábios mais equilibrados de Teldrassil, ele instrui iniciados em metamorfose, purificação de venenos e deveres em prol do Círculo Cenariano.",al={"quem é mathrengyl","papel de mathrengyl","ursivagus"}},{q="Qual é a sua relação com Fandral Guenelmo?",a="Mathrengyl serviu como assistente direto e braço direito do Arquidruida Fandral Guenelmo. Embora atenda obedientemente aos pedidos de Fandral — incluindo a coleta de morrowgrain e a delegação de missões —, Mathrengyl nutre sutis dúvidas em relação a alguns dos pontos de vista rígidos e projetos excêntricos de Fandral.",al={"assistente de fandral","guenelmo e mathrengyl"}},{q="Quais formas Mathrengyl ajuda os druidas a aprender?",a="Mathrengyl instrui jovens druidas após suas peregrinações espirituais à Clareira da Lua, supervisionando sua comunhão com Lunaclaw para obter a Forma de Urso, além de concluir suas provações na Costa Negra e em Cerro Oeste para dominar a Aquatic Form.",al={"missão da forma de urso darnassus","missão de aquatic form darnassus","formas de druida mathrengyl"}},{q="Por que Mathrengyl está coletando morrowgrain?",a="Ele ajuda o Arquidruida Fandral Guenelmo em pesquisas botânicas contínuas em Teldrassil, coletando morrowgrain cultivado por aventureiros. Mesmo assim, Mathrengyl admitiu sentir um profundo mal-estar sempre que está na presença da planta.",al={"missão de morrowgrain","por que morrowgrain darnassus"}},{q="O que Mathrengyl acha dos druidas taurens?",a="Diferente de Fandral Guenelmo, que vê os druidas taurens com ceticismo aberto, Mathrengyl é mais ponderado. Após analisar o sacrifício de um druida tauren que lutava contra o Flagelo nas Terras Pestilentas Ocidentais, ele admitiu que os taurens podem seguir os ensinamentos de Cenarius mais de perto do que Fandral admite.",al={"druidas taurens","mathrengyl tauren"}},{q="O que ele faz com a Lasca de Pesadelo?",a="Quando aventureiros trazem uma Lasca de Pesadelo corrompida para Falla Vento Sábio, ela os envia a Mathrengyl, que a inspeciona com grande alarme, pressentindo a corrupção rastejante que ameaça o Sonho Esmeralda.",al={"lasca de pesadelo mathrengyl","missão in nightmares"}}},fx={d00fa4f6={q="De que lado está Mathrengyl Ursivagus?",a="Mathrengyl é leal ao Círculo Cenariano e aos elfos noturnos de Darnassus. Como um druida proeminente dos Druid of the Claw residindo no Enclave Cenariano, ele serve tanto aos Kaldorei quanto à ordem druídica mais ampla, esforçando-se para manter o equilíbrio da natureza por toda Kalimdor.",al={"facção de mathrengyl","quem mathrengyl serve","mathrengyl é da aliança"}},["88f66b3d"]={q="Por que Mathrengyl Ursivagus está em Darnassus?",a="Mathrengyl reside no Enclave Cenariano para orientar e instruir jovens druidas elfos noturnos em seus deveres sagrados. Postado no coração da sociedade Kaldorei em Teldrassil, ele ajuda os iniciados a aprender formas animais, conectar-se com os espíritos da natureza e enfrentar crises naturais que ameaçam o reino.",al={"por que mathrengyl está aqui","motivo de mathrengyl em darnassus","o que traz mathrengyl a darnassus"}}},fp="21,314,30.623.0,24.546.0,21.521.0,29.262.0,47.285.0,45.226.0,40.234.0,45.289.0,41.199.0"}
P.entries["npc:maur-grimtotem"] = {n="Mauren Temível Totem",s="Mauren Temível Totem foi um emissário enviado pela The Elder Crone Magatha Temível Totem para as profundezas das Cavernas Ígneas. Despachado em uma missão diplomática fadada ao fracasso aos troggs que infestam os túneis subterrâneos abaixo de Orgrimmar, ele teve um fim brutal pelas mãos deles. Hoje, apenas seus restos mortais e sua sacola pessoal permanecem na escuridão como evidência da missão insensata.",h="Mauren Temível Totem foi um emissário enviado pela The Elder Crone Magatha Temível Totem para as profundezas...",kw={"temível totem","magatha","mauren","pederneiro","orgrimmar","cavernas ígneas","sacola","trogg"},ang={["faction:Horde"]="Ter uma caverna subterrânea mortal bem debaixo de Orgrimmar já é ruim o suficiente; enviar emissários solitários para negociar com troggs provou ser totalmente desastroso para a segurança da Horda.",["race:Tauren"]="O clã Temível Totem tem um relacionamento tenso com o restante das tribos no Penhasco do Trovão, e a bizarra e fatal missão de Mauren nos túneis dos troggs apenas aprofunda a suspeita sobre a verdadeira agenda de Magatha."},sec={{t="Uma Diplomacia Condenada",b="Embora a maioria na Horda veja os troggs como brutos irracionais e selvagens indignos de negociação, a The Elder Crone Magatha Temível Totem pensava diferente — ou pelo menos alegou isso. Ela despachou Mauren Temível Totem profundamente nas cavernas sinuosas das Cavernas Ígneas abaixo de Orgrimmar para tentar uma aproximação pacífica com as feras subterrâneas. Previsivelmente, a diplomacia falhou. Mauren foi rapidamente morto, seu cadáver deixado nas cavernas sob o olhar atento do chefe trogg Pederneiro."},{t="Os Interesses da The Elder Crone",b="Após a morte de Mauren, Magatha procurou aventureiros não apenas para vingá-lo, mas para recuperar a sacola pessoal que ele carregava nas profundezas. Se Mauren acreditava genuinamente que a paz com os troggs era possível ou se era apenas um peão descartável nos planos sombrios da matriarca dos Temível Totem permanece uma questão em aberto para aqueles que recuperam seus pertences."}},faq={{q="Quem era Mauren Temível Totem?",a="Mauren era um tauren pertencente ao clã Temível Totem. Agindo sob as ordens de Magatha Temível Totem, ele se aventurou nas cavernas das Cavernas Ígneas abaixo de Orgrimmar como emissário para os troggs, onde foi morto.",al={"quem é mauren","sabedoria sobre mauren temível totem","o que mauren estava fazendo"}},{q="Por que ele tentou negociar com os troggs?",a="A The Elder Crone Magatha alegou que o enviou para buscar a paz e testar a força desses inimigos subterrâneos. Dada a natureza feral dos troggs, muitos suspeitam que Magatha tinha segundas intenções ou simplesmente usou Mauren para investigar as profundezas das Cavernas Ígneas.",al={"por que fazer paz com troggs","diplomacia trogg","por que falar com troggs"}},{q="Quem matou Mauren Temível Totem?",a="Mauren foi morto pela tribo de troggs que vive nas Cavernas Ígneas. Seu cadáver foi encontrado guardado de perto por Pederneiro, o chefe dos troggs das Cavernas Ígneas.",al={"como mauren morreu","quem o matou","morte de mauren"}},{q="O que aconteceu com seu corpo e seus pertences?",a="O corpo de Mauren foi abandonado nas Cavernas Ígneas perto de Pederneiro. Aventureiros são incumbidos por Rahauro no Penhasco do Trovão de recuperar a sacola perdida de Mauren e trazê-la de volta para ele no Platô dos Anciãos para Magatha Temível Totem.",al={"cadáver de mauren","sacola perdida","sacola de mauren"}}},fx={c7d44e51={q="De que lado Mauren Temível Totem estava?",a="Mauren respondia diretamente à Anciã Magatha Temível Totem e servia aos interesses do clã Temível Totem. Embora os Temível Totem sejam tecnicamente contados entre a Horda devido à sua presença inquieta no Platô dos Anciãos em Penhasco do Trovão, as lealdades e a missão secreta de Mauren pertenciam exclusivamente ao seu clã.",al={"facção de mauren temível totem","quem mauren temível totem serve","mauren temível totem aliança horda"}},["565aa8ac"]={q="O que Mauren Temível Totem queria?",a="Mauren buscava forjar uma aliança ou acordo de paz com os troggs que infestavam as cavernas abaixo de Orgrimmar. Seguindo as instruções de Magatha Temível Totem, ele se aventurou nas Cavernas Ígneas esperando negociar com as criaturas, sem saber que sua natureza selvagem e violenta tornava qualquer entendimento diplomático impossível.",al={"o que mauren temível totem estava fazendo","missão de mauren temível totem","objetivo de mauren temível totem"}},bfc0472b={q="A quem Mauren Temível Totem estava ligado?",a="Mauren era um emissário enviado por Magatha Temível Totem, a matriarca do clã Temível Totem que atualmente reside no Platô dos Anciãos em Penhasco do Trovão. Ele executou seus planos privados abaixo de Orgrimmar, mantendo sua missão separada da liderança padrão da Horda.",al={"quem enviou mauren temível totem","conexões de mauren temível totem","mauren temível totem magatha"}}},fp="14,352,18.458.0,27.345.1,23.209.0,40.232.0,26.149.0,41.208.0"}
P.entries["npc:maur-raincaller"] = {n="Maur Clamachuva",s="Maur Clamachuva é um morador tauren encontrado na Aldeia Casco Sangrento, em Mulgore. Conectado à vida natural e espiritual das planícies, ele auxilia os anciãos da aldeia e cuida de assuntos locais que afetam as manadas e as feras selvagens.",h="Maur Clamachuva é um morador tauren encontrado na Aldeia Casco Sangrento, em Mulgore.",kw={"aldeia casco sangrento","maur clamachuva","mazzranache","mulgore","moa-das-planícies","tauren"},ang={["class:Hunter"]="Maur oferece um teste inicial de caça, enviando você atrás de lobos, pumas, moas-das-planícies e planadores dos campos abertos para obter as partes necessárias para curar a mordida venenosa de Mazzranache.",["race:Tauren"]="Para os jovens taurens que saem da Aldeia Narache, Maur oferece a oportunidade de proteger as terras ancestrais do seu povo contra predadores errantes e feras perturbadoras."},sec={{t="Um Morador da Aldeia Casco Sangrento",b="Situado perto do coração da Aldeia Casco Sangrento, às margens do Lake Stonebull, Maur Clamachuva serve à sua comunidade cuidando de questões ecológicas regionais e relativas às feras. Como muitos que carregam o título de Clamachuva, ele presta muita atenção ao equilíbrio dos elementos e da vida selvagem pelas planícies férteis de Mulgore. Após a mordida do temível moa Mazzranache infeccionar seu ferimento, Maur recorre a jovens viajantes capazes para reunir as partes de animais necessárias para um remédio."}},faq={{q="Quem é Maur Clamachuva?",a="Maur Clamachuva é um tauren que vive na Aldeia Casco Sangrento, nos verdejantes campos de Mulgore. Ele atua como um fornecedor local de missões, incumbindo aventureiros de lidar com a fauna descontrolada na região ao redor.",al={"função de maur clamachuva","quem é maur","história de maur clamachuva"}},{q="Onde posso encontrar Maur Clamachuva?",a="Ele pode ser encontrado ao ar livre entre as tendas e fogueiras da Aldeia Casco Sangrento, situada logo ao sul do Penhasco do Trovão, ao longo da margem leste do Lake Stonebull.",al={"localização de maur clamachuva","onde fica maur","coordenadas de maur"}},{q="Que problema Maur está enfrentando?",a="Maur foi mordido por Mazzranache, um temível moa das histórias de seu avô, e a ferida infeccionou. Ele pede aos aventureiros que tragam partes de lobos, pumas, moas-das-planícies e planadores de Mulgore para que possa preparar um remédio.",al={"missão de maur clamachuva","problema de mazzranache","o que maur quer"}}},fx={fd24c378={q="De que lado está Maur Clamachuva?",a="Maur Clamachuva é um tauren leal à tribo Casco Sangrento e um adepto da Horda. Vivendo na Aldeia Casco Sangrento, sua lealdade reside firmemente com o Alto Chefe Caerne Casco Sangrento e a segurança das planícies de Mulgore.",al={"facção de maur clamachuva","maur clamachuva é da horda","quem maur serve"}}},fp="15,241,31.493.0,23.204.0,33.168.0,34.243.0"}
P.entries["npc:maurin-bonesplitter"] = {n="Maurin Rachaosso",s="Maurin Rachaosso é um estudioso e conjurador Renegado estacionado no Entreposto do Espírito que Anda, em Desolação. Nomeado por Keldran para monitorar a atividade do culto demoníaco, ele aproveita sua profunda compreensão da história antiga para desmantelar a Lâmina Ardente. Maurin vê os cultistas com absoluto desprezo, considerando-os tolos cegos às entidades sombrias que puxam seus cordões.",h="Maurin Rachaosso é um estudioso e conjurador Renegado estacionado no Entreposto do Espírito que Anda, em...",kw={"lâmina ardente","corruptor","desolação","renegados","entreposto do espírito que anda","keldran","maurin rachaosso"},ang={["class:Mage"]="Magos que visitam o Entreposto do Espírito que Anda podem apreciar a abordagem calculada e intelectual de Maurin para desvendar rituais sombrios com contramedidas especializadas.",["class:Warlock"]="Bruxos reconhecerão a compreensão perspicaz de Maurin sobre pactos demoníacos, embora seu desdém sirva como um lembrete severo do perigo que vem ao servir a criaturas malignas superiores.",["faction:Horde"]="Maurin representa o apoio especializado da Cidade Baixa aos postos avançados ocidentais da Horda, trazendo conhecimento acadêmico sombrio para ajudar os aliados taurens contra a corrupção demoníaca.",["race:Undead"]="Maurin demonstra que a força dos Renegados depende tanto de pesquisas arcanas astutas e da exploração das fraquezas inimigas quanto do mero poder necromântico."},sec={{t="Um Estudioso Entre Exilados",b="Embora o Entreposto do Espírito que Anda sirva primariamente como um posto avançado de taurens e da Horda em meio aos ermos áridos de Desolação, Maurin Rachaosso se destaca como um de seus poucos ocupantes mortos-vivos. Em vez de um soldado brutal, Maurin é um conjurador erudito possuidor de amplo conhecimento sobre histórias proibidas e forças ocultas. Sua aptidão arcana e intelecto aguçado chamaram a atenção de Keldran, que o enviou para a região para observar a crescente presença demoníaca e coordenar ataques direcionados contra ela."},{t="Desprezo pela Lâmina Ardente",b="Maurin direciona a maior parte de sua malícia ao culto da Lâmina Ardente entrincheirado por toda Desolação. Ele nutre total aversão por sua ambição imprudente, zombando dos cultistas por não entenderem que seu poder emprestado meramente os prende como servos aos seus mestres demoníacos. Por meio de feitiços de vidência e conhecimento ritualístico, Maurin recruta aventureiros da Horda para interromper sistematicamente as invocações do culto e minar suas operações pela paisagem estéril."}},faq={{q="Quem é Maurin Rachaosso?",a="Maurin Rachaosso é um Bruxo e estudioso Renegado que reside no Entreposto do Espírito que Anda, em Desolação. Nomeado por Keldran, ele usa seu conhecimento de histórias antigas e magia sombria para erradicar o culto da Lâmina Ardente que opera na região.",al={"história de maurin rachaosso","quem é maurin","maurin desolação"}},{q="Por que um morto-vivo está hospedado em um posto tauren?",a="O Entreposto do Espírito que Anda atua como um assentamento fundamental da Horda em Desolação. Maurin foi destacado para lá por Keldran especificamente porque o posto avançado oferece uma base de operações ideal para observar e combater os cultistas da Lâmina Ardente que infestam as terras ermas ao redor.",al={"por que maurin está no entreposto do espírito que anda","morto-vivo em desolação"}},{q="Qual é a opinião de Maurin sobre a Lâmina Ardente?",a="Maurin vê a Lâmina Ardente com profundo desprezo. Ele os considera peões patéticos e ignorantes que acreditam ilusoriamente empunhar o verdadeiro poder, completamente alheios à realidade de que são meras marionetes de mestres demoníacos.",al={"maurin lâmina ardente","por que maurin odeia a lâmina ardente"}},{q="Quem enviou Maurin Rachaosso para Desolação?",a="Maurin foi designado para sua função em Desolação por Keldran. Reconhecendo o amplo conhecimento de Maurin sobre práticas de cultos e histórias antigas, Keldran o incumbiu de atrapalhar ativamente e, por fim, eliminar a Lâmina Ardente da zona.",al={"quem enviou maurin","maurin keldran","chefe de maurin"}},{q="Que tipo de tarefas Maurin dá aos aventureiros?",a="Maurin pede aos aventureiros que investiguem a Lâmina Ardente e obtenham um escalpo de Hatefury Shadowstalker e um Cristal de Oráculo naga. Ele usa esses reagentes para quebrar proteções de vidência e localizar o lorde demônio por trás do culto.",al={"missões de maurin","o que maurin quer"}},{q="Maurin é afiliado ao Círculo Cenariano ou à Horda?",a="Maurin é um membro leal dos Renegados e serve à Horda. Ele opera estritamente a partir do acampamento da Horda no Entreposto do Espírito que Anda, ajudando os campeões da Horda a purificar os ermos da atividade dos cultistas.",al={"maurin é da horda","facção de maurin"}}},fp="19,361,24.495.0,30.459.0,27.231.0,42.252.0,46.222.0,41.236.0,48.214.0,59.199.0"}
P.entries["npc:maxan-anvol"] = {n="Maxan Begurno",s="Maxan Begurno é um instrutor de sacerdotes anão situado dentro da Destilaria Cervaforte em Kharanos. Dedicado à Luz Sagrada, ele orienta sacerdotes anões novatos enquanto eles aprendem a canalizar o poder divino em meio aos climas gélidos de Dun Morogh. Ele testa jovens acólitos para garantir que sejam dignos de vestir as vestes da igreja.",h="Maxan Begurno é um instrutor de sacerdotes anão situado dentro da Destilaria Cervaforte em Kharanos.",kw={"desperate prayer","dun morogh","garments of the light","luz sagrada","kharanos","maxan begurno","instrutor de sacerdotes","destilaria cervaforte"},ang={["class:Priest"]="Maxan serve como seu guia inicial em Dun Morogh, concedendo acesso à disciplina sagrada fundamental, ensinando preces raciais como Desperate Prayer e concedendo suas primeiras vestes formais da igreja.",["faction:Alliance"]="Maxan cuida da prontidão física e espiritual dos montanheses e batedores da Aliança que guardam Dun Morogh contra troggs, trolls do gelo e feras selvagens.",["race:Dwarf"]="Personificando a piedade pragmática de Altaforja, Maxan ancora a fé dos anões onde o povo realmente se congrega: bem ao lado dos barris de cerveja de Kharanos."},sec={{t="Um Sacerdote no Pub",b="Embora possa parecer estranho encontrar um ministro ordenado da Luz Sagrada estabelecido dentro da Destilaria Cervaforte, isso se adapta bem à cultura dos anões. Kharanos serve como o principal ponto de encontro entre o Vale Cristálgida e Altaforja, e a estalagem local é onde viajantes, montanheses e acólitos naturalmente se reúnem. Maxan cuida do bem-estar espiritual do vilarejo ao lado de canecas de cerveja preta, oferecendo orações e conselhos a qualquer pessoa que passe pelas portas."},{t="Testando os Fiéis",b="Maxan Begurno é responsável por avaliar sacerdotes novatos antes que eles se aventurem pelo mundo afora. Ele encarrega os iniciados de demonstrar domínio sobre preces curativas fundamentais em defensores feridos de Dun Morogh. Aqueles que provam sua devoção e competência prática recebem suas primeiras vestes sacerdotais adequadas, marcando formalmente sua posição reconhecida dentro da Church of the Holy Light."}},faq={{q="Onde posso encontrar Maxan Begurno?",a="Maxan Begurno está localizado dentro da Destilaria Cervaforte, a principal estalagem e ponto de encontro na cidade de Kharanos, aninhada nos bancos de neve centrais de Dun Morogh.",al={"localização de maxan begurno","onde fica maxan","instrutor de sacerdotes de kharanos"}},{q="O que Maxan Begurno ensina?",a="Ele é um instrutor de sacerdotes que instrui sacerdotes novatos e experientes em feitiços de cura sagrada, controle das sombras e proteção divina. Ele também instrui sacerdotes anões em súplicas especializadas como Desperate Prayer.",al={"o que ele ensina","feitiços de maxan begurno"}},{q="Por que um sacerdote sagrado frequenta uma destilaria?",a="Na sociedade dos anões, a vida, a comunhão e a celebração giram em torno da fabricação de cerveja e das tavernas. A Destilaria Cervaforte funciona como fórum público, prefeitura e descanso dos viajantes de Kharanos. Maxan permanece onde pode alcançar o povo comum, guardas e viajantes que passam precisando de conforto espiritual.",al={"por que a destilaria","sacerdote em um bar"}},{q="Maxan Begurno oferece tarefas especiais?",a="Sim. Ele testa aspirantes a sacerdote com provações como 'In Favor of the Light' e 'Garments of the Light', enviando-os para curar montanheses feridos na neve. Concluir essas tarefas com sucesso rende ao iniciado suas vestes oficiais de acólito.",al={"missões de maxan","garments of the light"}},{q="O que ele diz aos que não são sacerdotes?",a="Ele adverte outros aventureiros a nunca darem as costas à Luz Sagrada, lembrando-os de que a graça divina pode muito bem ser a única coisa que salvará a vida deles em batalha algum dia.",al={"diálogo de maxan","fala de maxan"}},{q="Gnomos podem aprender com Maxan Begurno?",a="Sim. Gnomos também treinam como sacerdotes, e Maxan acolhe qualquer membro da Aliança que tenha se comprometido com a Luz.",al={"gnomos podem falar com ele","instrutor de sacerdotes gnomo"}}},fx={["32034ea0"]={q="Quem é Maxan Begurno?",a="Maxan Begurno é um sacerdote anão da Luz Sagrada estacionado em Kharanos. Ele serve como instrutor para devotos iniciantes em Dun Morogh, testando jovens acólitos quanto à sua disciplina e comunhão com a Luz antes de conceder-lhes vestimentas adequadas ao seu posto na igreja.",al={"quem é maxan","lore de maxan begurno","instrutor de sacerdote em kharanos"}},["310c3ecc"]={q="De que lado está Maxan Begurno?",a="Ele está lealmente ao lado do Reino de Altaforja, da Luz Sagrada e da Grande Aliança. Ele dedica seu serviço a proteger a população local de Dun Morogh e a preparar novos sacerdotes para defender a fé por todas as terras da Aliança.",al={"facção de maxan","maxan é da aliança","lealdade de maxan begurno"}},["1141108e"]={q="O que Maxan Begurno quer?",a="Maxan busca promover a devoção à Luz Sagrada e garantir que os sacerdotes noviços estejam totalmente preparados para as provações do mundo. Ele testa estudantes aspirantes para garantir que sejam dignos de suas vestes sagradas, enquanto lembra a todos que passam para nunca abandonarem a graça da Luz.",al={"objetivo de maxan begurno","o que maxan quer","motivo de maxan begurno"}}},fp="11,322,19.445.0,20.399.0,29.164.0,28.218.0,49.282.0,41.243.0,32.178.0,34.120.0"}
P.entries["npc:maybell-maclure"] = {n="Mabel Madruga",s="Mabel Madruga é uma jovem que vive nos Vinhedos dos Madruga, na Floresta de Elwynn. Apesar de uma rixa antiga e amarga entre sua família e os vizinhos Campedra, ela se apaixonou secretamente por Tomasino Campedra.",h="Mabel Madruga é uma jovem que vive nos Vinhedos dos Madruga, na Floresta de Elwynn.",kw={"amantes","madruga","mabel","campedra","tomasino campedra","vinhedos"},ang={["faction:Alliance"]="Para os aventureiros da Aliança que passam pela Floresta de Elwynn, o romance de Mabel é um lembrete de que problemas pessoais e velhos rancores persistem até mesmo no coração do reino."},sec={{t="Amores Desafortunados nos Vinhedos",b="A vida nos Vinhedos dos Madruga é marcada pelo trabalho interminável e por um rancor duradouro contra a família vizinha Campedra. No meio desse conflito está Mabel Madruga, que se apaixonou profundamente por Tomasino Campedra, o jovem herdeiro da fazenda rival. Separada dele pela vigilância dos parentes e pelo antigo ressentimento familiar, Mabel busca desesperadamente qualquer oportunidade de se comunicar com Tomasino longe dos olhos atentos de seus familiares."},{t="Uma Poção para o Amor Verdadeiro",b="Incapaz de cruzar abertamente os limites entre as fazendas, Mabel depende de viajantes solidários e da orientação da Vovó Campedra. Com a ajuda do alquimista local de Vila d'Ouro, Durval Pilão, um Elixir de Invisibilidade é preparado. Ao beber essa poção ilícita, Mabel consegue escapar da propriedade dos Madruga sem ser vista e aproveitar momentos preciosos com Tomasino às margens do rio."}},faq={{q="Por que Mabel e Tomasino não podem se ver?",a="As famílias Madruga e Campedra mantêm uma rivalidade ferrenha há anos. Como ambos os lares proíbem qualquer contato entre os clãs, Mabel e Tomasino precisam manter seu romance em absoluto segredo ou enfrentar a ira de seus parentes.",al={"por que a rixa familiar","rixa madruga campedra","por que nao podem ficar juntos"}},{q="O que impede Mabel de sair do vinhedo?",a="Sua família a vigia de perto por causa da rixa com os Campedra. Ela precisa de ajuda para encontrar uma maneira de se encontrar com Tomasino sem chamar a atenção deles.",al={"como mabel sai escondida","pocao de invisibilidade elwynn","como ela se encontra com tomasino"}},{q="Onde Mabel se encontra com Tomasino?",a="Tomasino espera na margem do rio, na fronteira entre os Vinhedos dos Madruga e a Fazenda dos Campedra, escondido da vista direta de ambas as propriedades.",al={"ponto de encontro","onde eles estao se encontrando","onde esta tomasino campedra"}},{q="Quem ajuda Mabel em seu romance?",a="A Vovó Campedra se mostra solidária ao dilema dos amantes e encaminha aventureiros dispostos a Durval Pilão, o alquimista de Vila d'Ouro, que providencia os meios para o encontro clandestino.",al={"quem ajuda mabel","ajudantes dos campedra"}}},fx={c4338ded={q="Quem é Mabel Madruga?",a="Mabel Madruga é uma jovem humana que vive nos Vinhedos dos Madruga na Floresta de Elwynn. Ela está presa no meio de uma amarga e longa rivalidade entre sua família e seus vizinhos, os Campedra, após se apaixonar profundamente por Tomasino Campedra.",al={"quem é mabel madruga","lore de mabel madruga"}},["9f94442c"]={q="De que lado está Mabel Madruga?",a="Ela é uma súdita leal da Aliança e filha da família Madruga. No entanto, quando se trata da pequena e amarga rivalidade entre os Madruga e os Campedra, ela rejeita o ódio completamente, escolhendo seu amor por Tomasino Campedra em vez do rancor de sua família.",al={"mabel é da aliança","de que lado está mabel","facção de mabel"}},cbd5fa72={q="O que Mabel Madruga quer?",a="Mabel não quer nada além de ficar com Tomasino Campedra. Como suas famílias nutrem um intenso ódio mútuo, ela busca a ajuda de viajantes compreensivos e confidentes de confiança para encontrar maneiras de encontrá-lo em segredo sem ser pega.",al={"o que mabel quer","objetivo de mabel madruga","por que mabel precisa de ajuda"}},b079e731={q="Por que Mabel Madruga está aqui?",a="Mabel reside nos Vinhedos dos Madruga, a propriedade de sua família no sul da Floresta de Elwynn. Ela permanece confinada aos terrenos do vinhedo sob os olhos atentos de seus parentes, esperando por uma chance de escapar para ver seu amado.",al={"por que mabel madruga está aqui","por que mabel está nos vinhedos"}},["26be6d7a"]={q="A quem Mabel Madruga está ligada?",a="Mabel faz parte da família Madruga, proprietária de vinhedos. Ela está romanticamente envolvida com Tomasino Campedra, o herdeiro da fazenda rival dos Campedra, e mantém laços secretos com a Vovó Campedra, que apoia o romance clandestino do jovem casal.",al={"relacionamentos de mabel madruga","parentes de mabel","laços de mabel"}}},fp="15,230,29.425.0,26.383.1,47.236.0,48.155.1,34.152.0,35.189.1"}
P.entries["npc:mebok-mizzyrix"] = {n="Cáliper Porcatraca",s="Cáliper Porcatraca é um empreendedor goblin engenhoso que reside na cidade portuária de Vila Catraca. Sempre ansioso por transformar reagentes bizarros da natureza em lucro, ele contrata aventureiros que passam pelo local para coletar espécimes incomuns da fauna e da flora de todos os Sertões e além. Seu projeto mais notório envolve preparar uma bebida comercial que aprimora o intelecto a partir de chifres de raptor.",h="Cáliper Porcatraca é um empreendedor goblin engenhoso que reside na cidade portuária de Vila Catraca.",kw={"sertões","tubérculos folhazul","cáliper","porcatraca","chifres de raptor","vila catraca","bebidas inteligentes","cartel bondebico"},ang={["faction:Alliance"]="Desembarcar do barco de Angra do Butim na neutra Vila Catraca concede aos exploradores da Aliança acesso às tarefas de Cáliper sem medo de guardas hostis.",["faction:Horde"]="Passar por Vila Catraca a caminho dos Sertões oferece aos viajantes da Horda uma fonte fácil de moedas ao eliminar feras perigosas nas proximidades.",["profession:Cooking"]="Aventureiros culinários acharão as receitas de culinária e bebidas de Cáliper questionáveis, na melhor das hipóteses, dada a sua insistência em misturar chifre de raptor moído.",["profession:Herbalism"]="O fascínio de Cáliper por espécimes estranhos, como os tubérculos Folhazul, mostra o lado mais selvagem e comercial da colheita da flora única de Kalimdor."},sec={{t="Um Alquimista Empreendedor",b="Operando a partir do movimentado e neutro porto de Vila Catraca, Cáliper Porcatraca personifica o espírito clássico do Cartel Bondebico de puro oportunismo. Enquanto Vila Catraca atende marinheiros, piratas e comerciantes de todos os tipos, Cáliper foca seu olhar atento na natureza selvagem de Kalimdor. Em vez de minerar minérios comuns ou comercializar tecidos corriqueiros, ele procura curiosidades biológicas raras que acredita poderem ser refinadas em misturas e mercadorias altamente lucrativas."},{t="A Busca pelas Bebidas Inteligentes",b="O principal empreendimento comercial de Cáliper é uma \"bebida inteligente\" própria destinada a aumentar artificialmente o intelecto de quem a consome. Convencido de que a astúcia e a ferocidade naturais dos raptores locais vêm dos chifres que coroam seus focinhos, Cáliper encomenda caçadores para colher chifres intactos pelos Sertões. Para ele, ética e sabor ficam em segundo plano diante do potencial bruto de mercado, contanto que os clientes pagantes acreditem que a poção traga resultados."},{t="Reagentes Exóticos e Flora",b="Além de elixires derivados de raptores, Cáliper mantém uma demanda constante por outros espécimes bizarros. Desde coletar ovos voláteis de aranha de Fundolimo até encomendar a recuperação de raros tubérculos Folhazul enterrados nas profundezas dos espinheiros do Urzal dos Tuscos, suas buscas sempre empurram mercenários intrépidos para territórios perigosos. Se um organismo possui propriedades estranhas, Cáliper tem certeza de que há uma maneira de engarrafá-lo e vendê-lo."}},faq={{q="Quem é Cáliper Porcatraca?",a="Cáliper Porcatraca é um comerciante goblin e articulador alquímico localizado na cidade portuária neutra de Vila Catraca, nos Sertões. Ele contrata aventureiros para coletar partes estranhas de animais selvagens e plantas para abastecer seus projetos comerciais.",al={"quem é cáliper","história de cáliper porcatraca","goblin cáliper de vila catraca"}},{q="O que são Bebidas Inteligentes?",a="Bebidas inteligentes são tônicos experimentais que aprimoram o intelecto que Cáliper Porcatraca espera preparar e vender. Ele acredita que moer os chifres dos espertos raptores dos Sertões transmitirá seus instintos aguçados e astúcia a quem beber.",al={"bebida inteligente","missão bebidas inteligentes","poção de chifre de raptor"}},{q="Onde Cáliper Porcatraca pode ser encontrado?",a="Ele pode ser encontrado entre os edifícios na cidade portuária de Vila Catraca, na costa leste dos Sertões, acessível a viajantes tanto da Horda quanto da Aliança.",al={"localização de cáliper","onde fica cáliper","encontrar cáliper porcatraca"}},{q="Por que Cáliper quer chifres de raptor?",a="Cáliper levanta a hipótese de que a astuta inteligência dos raptores que vagam pelos Sertões está concentrada dentro de seus chifres. Ele planeja pulverizá-los como o principal ingrediente ativo em suas bebidas de aprimoramento de intelecto.",al={"por que chifres de raptor","utilidade do chifre de raptor","o que cáliper faz com chifres"}},{q="Por que Cáliper envia pessoas para o Urzal dos Tuscos?",a="Ele recruta aventureiros para entrar no Urzal dos Tuscos e desenterrar tubérculos Folhazul usando um farejador treinado, buscando a planta rara por suas propriedades botânicas valiosas e incomuns.",al={"por que urzal dos tuscos","missão de cáliper no urzal dos tuscos","tubérculos folhazul urzal dos tuscos"}},{q="Cáliper trabalha para a Horda ou para a Aliança?",a="Cáliper é um membro independente do Cartel Bondebico na neutra Vila Catraca. Ele é leal ao dinheiro e negociará e fará contratos com prazer com membros de qualquer uma das facções.",al={"cáliper é da horda","cáliper é da aliança","facção de cáliper"}}},fx={["55f078f0"]={q="O que Cáliper Porcatraca quer?",a="Cáliper é movido pela criação de estranhas novas alquimias — mais notavelmente sua \"bebida inteligente\" experimental. Para aperfeiçoar suas receitas bizarras, ele envia aventureiros para vasculhar os Sertões e suas profundezas perigosas em busca de ingredientes peculiares, variando de Raptor Horns intactos a amostras raras de raízes e ovos de aranha.",al={"o que cáliper quer","do que cáliper precisa","objetivo de cáliper porcatraca"}},c521482b={q="Por que Cáliper Porcatraca está em Vila Catraca?",a="Vila Catraca é a principal cidade portuária para goblins ambiciosos que precisam de acesso rápido aos recursos selvagens de Kalimdor. A partir de sua base aqui, Cáliper pode facilmente contratar mercenários que chegam de qualquer facção para se aventurar na perigosa savana e coletar os espécimes selvagens de que ele precisa para seus experimentos.",al={"por que cáliper está aqui","por que cáliper está em vila catraca","cáliper porcatraca nos sertões"}}},fp="14,360,25.445.0,26.443.0,25.422.0,22.219.0,22.218.0,34.159.0,33.217.0,45.176.0,46.165.0"}
P.entries["npc:melithar-staghelm"] = {n="Melithar Guenelmo",s="Melithar Guenelmo é um elfo noturno posicionado do lado de fora de Aldrassil em Umbravale, a clareira inicial de Teldrassil. Ele ajuda jovens aventureiros elfos noturnos ao iniciarem seu treinamento inicial, enviando-os para descobrir o que trouxe a dríade Tarindrella de volta à clareira. Embora compartilhe o proeminente sobrenome Guenelmo com o Arquidruida Fandral Guenelmo, sua ligação exata com o druida governante permanece não confirmada.",h="Melithar Guenelmo é um elfo noturno posicionado do lado de fora de Aldrassil em Umbravale, a clareira inicial...",kw={"aldrassil","melithar","umbravale","guenelmo","teldrassil","instrutor"},ang={["race:NightElf"]="Para elfos noturnos que iniciam sua jornada em Umbravale, Melithar é um dos primeiros rostos encontrados após deixar o abrigo de Aldrassil."},sec={{t="Um Guia em Aldrassil",b="Posicionado diretamente do lado de fora da entrada da grande ramagem de Aldrassil, Melithar serve como um ponto de contato inicial para os elfos noturnos que adentram o mundo. Um druida que escuta os sussurros dos espíritos da floresta, ele descobriu que a misteriosa protetora dos bosques Tarindrella retornou a Umbravale após anos afastada. Sentindo que algo está errado, Melithar envia os recém-chegados para procurar a dríade a sudoeste de Aldrassil e descobrir quais assuntos a trazem ao bosque."},{t="O Nome Guenelmo",b="Carregar o sobrenome Guenelmo inevitavelmente chama a atenção, já que o Arquidruida Fandral Guenelmo atualmente lidera o Círculo Cenariano em Darnassus após o desaparecimento de Malfurion Tempesfúria no Sonho Esmeralda. No entanto, Melithar não se vangloria abertamente de uma grande herança, nem fala ativamente de sua linhagem. Seja ele um parente distante da venerável linhagem familiar do Arquidruida ou simplesmente compartilhe um antigo nome de família Kaldorei, Melithar permanece satisfeito cumprindo deveres humildes junto às raízes de Aldrassil."}},faq={{q="Quem é Melithar Guenelmo?",a="Melithar Guenelmo é um elfo noturno concedente de missões posicionado no caminho do lado de fora da ramagem de Aldrassil em Umbravale. Ele ajuda aventureiros elfos noturnos recém-chegados a se orientarem e os envia para encontrar a dríade Tarindrella.",al={"melithar","quem é melithar","melithar umbravale"}},{q="Melithar é parente do Arquidruida Fandral Guenelmo?",a="O parentesco exato deles é desconhecido. Embora compartilhem o nome Guenelmo, Melithar nunca comenta sobre ser parente do Arquidruida Fandral Guenelmo ou de seu falecido filho Valstann. Permanece incerto se ele é um parente distante ou simplesmente compartilha um sobrenome Kaldorei comum.",al={"parente de fandral","irmão de fandral","família guenelmo"}},{q="Qual papel Melithar desempenha para novos aventureiros?",a="Melithar ouviu através dos sussurros dos espíritos da floresta que a dríade Tarindrella, a protetora dos bosques, retornou a Umbravale após anos afastada. Ele envia noviços para encontrá-la a sudoeste de Aldrassil e descobrir quais assuntos a trazem ao bosque.",al={"missões de melithar","o que melithar faz"}},{q="Onde posso encontrar Melithar Guenelmo?",a="Ele fica bem na rampa de madeira do lado de fora da entrada de Aldrassil, no centro de Umbravale em Teldrassil.",al={"localização de melithar","onde fica melithar","encontrar melithar guenelmo"}}},fx={de95e555={q="De que lado está Melithar Guenelmo?",a="Melithar está ao lado dos elfos noturnos de Darnassus e da Aliança. Estacionado em Umbravale, logo fora de Aldrassil, ele auxilia jovens defensores e recrutas elfos noturnos enquanto eles dão seus primeiros passos na proteção da Árvore do Mundo.",al={"facção de melithar","a quem melithar serve","lealdade de melithar"}},f95cde78={q="Por que Melithar Guenelmo está aqui?",a="Melithar está estacionado logo fora de Aldrassil, em Umbravale, para vigiar os galhos e orientar os jovens aventureiros elfos noturnos. Ele fornece orientação inicial, encarregando novos defensores de conter a corrupção local e manter a harmonia no berçário sagrado de Teldrassil.",al={"por que melithar está em umbravale","motivo da localização de melithar"}},["67f605fc"]={q="O que Melithar Guenelmo quer?",a="Melithar trabalha para proteger Umbravale e purificar Teldrassil de ameaças crescentes. Preocupado com relatos dos espíritos da floresta de que a dríade Tarindrella retornou à clareira após anos afastada, ele pede aos aventureiros que chegam que a procurem e descubram o que está errado.",al={"objetivo de melithar","o que melithar está fazendo","propósito de melithar"}}},fp="17,410,20.482.0,17.508.0,25.225.0,50.260.0,49.262.0,35.115.0"}
P.entries["npc:melor-stonehoof"] = {n="Melor Casco de Pedra",s="Melor Casco de Pedra é um caçador tauren veterano situado no topo do Platô dos Caçadores no Penhasco do Trovão. Como mentor nos caminhos da caça, ele testa a proeza de rastreamento e a coragem dos caçadores da Horda enviando-os atrás das feras predadoras mais perigosas pelos Sertões e Mil Agulhas.",h="Melor Casco de Pedra é um caçador tauren veterano situado no topo do Platô dos Caçadores no Penhasco do...",kw={"deadmire","frostmaw","platô dos caçadores","the hunter's way","melor","sergra darkthorn","steelsnap","casco de pedra","penhasco do trovão"},ang={["class:Hunter"]="Melor é um dos concedentes de missões por excelência para caçadores da Horda, guiando você através de ritos de rastreamento que incorporam o caminho sagrado do caçador.",["faction:Horde"]="Melor garante que guerreiros e perseguidores de toda a Horda sejam endurecidos contra as feras selvagens que ameaçam povoados de Mulgore a Mil Agulhas.",["race:Tauren"]="Situado no alto do Platô dos Caçadores, Melor exemplifica a profunda reverência do seu povo pela caça tanto como uma prova de força quanto como um ato de equilíbrio com a Mãe Terra."},sec={{t="Um Mentor das Selvas",b="Empoleirado na extensão arejada do Platô dos Caçadores, Melor Casco de Pedra observa as planícies abaixo com um olhar experiente. A arte da caça é sagrada para os taurens, entrelaçada com a sobrevivência, o equilíbrio espiritual e o respeito aos maiores predadores da natureza. Melor garante que aqueles que empunham arco e lâmina em nome da Horda compreendam esse equilíbrio, direcionando perseguidores promissores a dominar seu ofício por meio de provações contra feras lendárias."},{t="Provações da Caça",b="Melor desafia caçadores a procurarem feras lendárias e esquivas que aterrorizam a natureza. Ele orienta rastreadores pelas planícies dos Sertões, desde ajudar a caçadora Sergra Darkthorn na Encruzilhada até perseguir Steelsnap, uma hiena astuta e feroz em Mil Agulhas. Por meio dessas provações, os caçadores provam que podem ser mais espertos e lutar melhor do que as criaturas mais mortíferas da região central de Kalimdor."},{t="Os Monstros de Terras Distantes",b="Para aqueles cujas habilidades superam os Sertões, Melor aponta em direção a terras distantes. Ele encarrega caçadores experientes de abater feras de força aterrorizante, incluindo Deadmire, um crocolisco ancestral à espreita nos pântanos do Pântano Vadeoso, e o feroz ieti Frostmaw das Montanhas de Alterac. Cada caçada serve para testar se um perseguidor realmente dominou The Hunter's Way."}},faq={{q="Onde posso encontrar Melor Casco de Pedra?",a="Melor Casco de Pedra está localizado no Platô dos Caçadores na cidade do Penhasco do Trovão. O Platô dos Caçadores é a meseta ao sul da elevação principal da capital dos taurens, alcançada por pontes de corda.",al={"localização de melor casco de pedra","onde fica melor","coordenadas de melor casco de pedra"}},{q="Quais missões Melor Casco de Pedra oferece?",a="Melor oferece uma série de desafios de caça voltados para aventureiros de nível intermediário. Isso inclui direcionar jogadores para Sergra Darkthorn nos Sertões, caçar a hiena feroz Steelsnap e rastrear feras formidáveis mais distantes, como o crocolisco Deadmire no Pântano Vadeoso e o ieti Frostmaw nas Montanhas de Alterac.",al={"missões de melor","o que melor faz","série de missões de melor casco de pedra"}},{q="Por que Melor envia caçadores atrás de Steelsnap?",a="Steelsnap é uma hiena notoriamente perversa e astuta que espreita em Mil Agulhas. Melor envia caçadores capazes para rastreá-lo e matá-lo como um teste de perícia, resistência e coragem na natureza.",al={"por que matar steelsnap","história da missão de steelsnap"}},{q="O que é Deadmire?",a="Deadmire é um crocolisco invulgarmente grande e agressivo que ronda os pântanos do Pântano Vadeoso. Melor desafia caçadores a derrotá-lo como um rito de proeza.",al={"quem é deadmire","história de deadmire","fera deadmire"}},{q="Você precisa ser da classe caçador para aceitar as missões dele?",a="Não. Embora seus testes representem a filosofia do caminho do caçador e sejam temáticos para a classe caçador, Melor oferece seus contratos de caça a qualquer aventureiro capaz que lute pela Horda.",al={"melor apenas caçadores","outras classes podem fazer missões de melor"}},{q="Quem é Sergra Darkthorn e por que Melor envia você até ela?",a="Sergra Darkthorn é uma caçadora orc situada na Encruzilhada nos Sertões. Melor direciona caçadores promissores até ela para que possam ajudar a subjugar os predadores rebeldes das planícies e aprender com outra veterana da natureza.",al={"conexão melor e sergra","missão de sergra darkthorn"}}},fx={c4d46d44={q="Quem é Melor Casco de Pedra?",a="Melor Casco de Pedra é um respeitado caçador tauren estacionado no Platô dos Caçadores em Penhasco do Trovão. Dedicado às tradições da caça e à preservação do equilíbrio, ele guia rastreadores promissores por Kalimdor, testando sua força e astúcia contra os predadores mais ferozes da terra.",al={"quem é melor casco de pedra","lore de melor casco de pedra","quem é melor"}},d59647ad={q="De que lado está Melor Casco de Pedra?",a="Melor é leal às tribos tauren e à Horda. De seu poleiro no alto do Penhasco do Trovão, ele serve seu povo orientando caçadores da Horda e coordenando esforços contra feras perigosas que ameaçam viajantes e assentamentos pelos Sertões e além.",al={"facção de melor casco de pedra","melor é da horda","lealdade de melor casco de pedra"}},["2962cc83"]={q="O que Melor Casco de Pedra quer?",a="Melor busca instruir os caçadores nos antigos caminhos de perseguir, rastrear e honrar sua presa. Ele quer que rastreadores habilidosos provem seu valor caçando feras notórias como Steelsnap, Deadmire e Frostmaw, e ele trabalha com aliados como Sergra Darkthorn para testar sua coragem.",al={"objetivo de melor casco de pedra","o que melor quer","propósito de melor casco de pedra"}},["6e964c49"]={q="Por que Melor Casco de Pedra está aqui no Penhasco do Trovão?",a="Melor faz sua casa no Platô dos Caçadores, o ponto de encontro natural para os atiradores, caçadores e rastreadores tauren. Deste ponto de vantagem, ele pode observar os caçadores que chegam, oferecer conselhos e despachar guerreiros testados para a vida selvagem para proteger a terra.",al={"por que melor está no platô dos caçadores","por que melor está no penhasco do trovão","motivo da localização de melor casco de pedra"}}},fp="15,283,21.435.0,18.388.0,29.374.0,33.167.0,39.333.0,44.185.0,17.157.0,52.189.0,60.225.0"}
P.entries["npc:menara-voidrender"] = {n="Menara Nihila",s="Menara Nihila é uma bruxa humana que reside no porto góbico de Vila Catraca. Ela atua como mentora de praticantes ambiciosos das artes das trevas tanto da Aliança quanto da Horda, compartilhando seu profundo conhecimento sobre artefatos de aprisionamento de demônios e técnicas arcanas. Sua localização isolada em Kalimdor a mantém longe dos olhos vigilantes das autoridades ortodoxas.",h="Menara Nihila é uma bruxa humana que reside no porto góbico de Vila Catraca.",kw={"sertões","robessangre","demonologia","menara","orahil","vila catraca","tabetha","nihila","bruxo"},ang={["class:Warlock"]="Menara é uma mentora fundamental em Kalimdor, ensinando praticantes de ambas as facções a forjar suas vestes encantadas características e a prender demônios em orbes de foco.",["profession:Tailoring"]="Menara combina materiais avançados de alfaiataria com reagentes vis para tecer vestimentas duráveis e encantadas, capazes de canalizar o poder demoníaco.",["race:Human"]="Longe das catacumbas de Ventobravo, Menara representa os bruxos humanos que deixaram de lado a lealdade aos reinos para seguir as artes das trevas sem impedimentos em territórios neutros."},sec={{t="Um refúgio em Vila Catraca",b="Enquanto a maioria dos bruxos nos Reinos do Leste pratica em porões úmidos ou matadouros isolados sob suas cidades natais, Menara Nihila escolheu o porto góbico neutro de Vila Catraca, nos Sertões. Operando longe do escrutínio do Kirin Tor, dos guardas de Ventobravo ou dos feitores de Orgrimmar, ela é livre para seguir seus estudos ocultos a céu aberto. Sua disposição para negociar com qualquer aprendiz competente, independentemente da facção, torna-a um raro ponto em comum entre praticantes das artes das trevas."},{t="Mestra dos aprisionamentos",b="Menara é renomada entre conjuradores veteranos como uma autoridade na criação de orbes que aprisionam e canalizam espíritos demoníacos. Ela trabalha de perto com reagentes complexos, guiando aprendizes através de rituais exigentes para forjar trajes encantados e instrumentos de aprisionamento. A fama de sua perícia chega até Altaforja e a Cidade Baixa, levando bruxos veteranos de toda Azeroth a enviar seus alunos mais promissores através do mar em busca de seus conselhos."},{t="Laços com o pântano",b="Entre os conhecidos distantes de Menara está a maga eremita Tabetha, que vive em profundo isolamento nos pântanos do Pântano Vadeoso. Embora Tabetha se dedique ao arcano e Menara se aprofunde em vínculos vis e demonologia, as duas mulheres compartilham uma longa história. Quando relíquias poderosas como o Orbe de Orahil exigem restauração ou conhecimentos especializados, o passado em comum delas se torna uma ponte inesperada pelas terras ermas de Kalimdor."}},faq={{q="Quem é Menara Nihila?",a="Menara Nihila é uma bruxa humana estabelecida na cidade portuária neutra de Vila Catraca, nos Sertões. Ela atua como instrutora e artífice para bruxos em desenvolvimento, guiando-os em rituais de criação e na feitiçaria de aprisionamento de demônios.",al={"quem é menara","história de menara nihila","quem é o bruxo em vila catraca"}},{q="Por que uma bruxa humana vive nos Sertões?",a="Vila Catraca oferece neutralidade e distância dos olhos atentos dos grandes governos. Ao se estabelecer em um porto administrado por gnomos e goblins, Menara pode praticar artes proibidas e instruir alunos tanto da Aliança quanto da Horda sem a interferência de paladinos, magos ou guardas da cidade.",al={"por que menara está em vila catraca","por que ela está nos sertões","por que bruxo em vila catraca"}},{q="Em que tipo de magia Menara é especializada?",a="Menara é especializada em demonologia, no encantamento de tecidos sombrios e na confecção de recipientes destinados a aprisionar entidades demoníacas. Ela é conhecida especialmente pelo domínio na criação e restauração de orbes que prendem demônios, como o Orbe de Orahil.",al={"o que menara ensina","poderes de menara nihila","em que menara é boa"}},{q="Qual é a relação de Menara com Tabetha?",a="Menara e a reclusa feiticeira Tabetha compartilham uma ligação do passado. Apesar de Tabetha viver isolada no Pântano Vadeoso e praticar magia tradicional, os bruxos que buscam conhecimento sobre o Orbe de Orahil descobrem que as duas conhecem bem os talentos uma da outra.",al={"menara e tabetha","como ela conhece tabetha","conexão com tabetha"}},{q="Menara favorece a Aliança ou a Horda?",a="Menara atua de forma neutra a partir de Vila Catraca. Ela oferece sua tutela e tarefas de criação a qualquer bruxo que se mostre competente e ambicioso o suficiente para lidar com energias vis, acolhendo praticantes tanto da Aliança quanto da Horda.",al={"menara é da aliança ou da horda","facção de menara","para quem menara trabalha"}},{q="Quais artefatos importantes ela ajuda a criar?",a="Menara orienta aprendizes a tecer o Robessangre Dourado Encantado, um traje imbuído de poder demoníaco, e ajuda praticantes avançados a recuperar e reunir componentes para o Orbe de Orahil.",al={"missões de menara","o que ela cria","menara robessangre dourado encantado"}}},fx={["63c53201"]={q="O que Menara Nihila quer?",a="Menara busca tutelar aspirantes a bruxos que mostrem promessa e ambição suficientes para procurá-la. Ela se dedica a criar e aperfeiçoar artefatos sombrios especializados, como orbes de ligação e vestes encantadas, e conta com praticantes capazes para reunir os reagentes raros e perigosos necessários para completá-los.",al={"objetivos de menara nihila","o que menara quer","propósito de menara nihila"}}},fp="17,347,19.503.0,19.441.0,17.416.1,25.230.0,45.276.0,45.232.0,39.275.0,44.214.0,42.202.0"}
P.entries["npc:merissa-stilwell"] = {n="Melissa Calmafonte",s="Melissa Calmafonte é uma jovem cidadã humana que reside na Abadia de Vila Norte, na Floresta de Elwynn. Perto da abadia, ela oferece uma calorosa saudação e uma mão amiga aos recém-chegados que treinam no Vale de Vila Norte.",h="Melissa Calmafonte é uma jovem cidadã humana que reside na Abadia de Vila Norte, na Floresta de Elwynn.",kw={"elwynn","melissa","vila norte","calmafonte"},ang={["faction:Alliance"]="Para os recrutas da Aliança que deixam o claustro protegido de Vila Norte, Melissa representa a calorosa hospitalidade de Elwynn antes que as duras realidades da ameaça Defias se instalem."},sec={{t="Um Rosto Acolhedor em Vila Norte",b="Junto à Abadia de Vila Norte, Melissa Calmafonte cumprimenta os novos recrutas que chegam ao Vale de Vila Norte. Para os novatos errantes, ela oferece uma hospitalidade simples e conselhos práticos sobre como descansar e se orientar. Compartilhando o sobrenome com artesãos e colonos notáveis pelo reino — como o ferreiro Jardel Calmafonte e a defensora de Cerro Oeste Dafne Calmafonte —, ela permanece um rosto pacífico local em meio às crescentes tensões do reino."}},faq={{q="Quem é Melissa Calmafonte?",a="Melissa é uma habitante humana amigável da Abadia de Vila Norte, na Floresta de Elwynn, que oferece conselhos e boas-vindas calorosas aos viajantes que chegam ao local.",al={"melissa calmafonte","quem é melissa","garota calmafonte vila norte"}},{q="Onde posso encontrar Melissa Calmafonte?",a="Ela está localizada na Abadia de Vila Norte, no Vale de Vila Norte, na Floresta de Elwynn.",al={"localização de melissa calmafonte","onde está melissa","encontrar melissa"}},{q="Melissa é parente dos outros Calmafonte no reino?",a="Embora compartilhe o sobrenome com figuras proeminentes como o ferreiro Jardel Calmafonte e Dafne Calmafonte em Cerro Oeste, ela leva uma vida tranquila na Abadia de Vila Norte, acolhendo viajantes em vez de lutar contra bandidos ou forjar lâminas.",al={"família calmafonte","parente de dafne calmafonte","parente de jardel calmafonte"}},{q="Melissa Calmafonte oferece alguma missão?",a="Não. Ela não tem nenhuma tarefa própria para os viajantes; ela apenas recebe os recém-chegados que passam por Vila Norte.",al={"missões de melissa","missão de melissa calmafonte"}}},fx={["57a6fac4"]={q="Por que Melissa Calmafonte está em Vila Norte?",a="Melissa passa seus dias ao redor da Abadia de Vila Norte. Como muitos cidadãos comuns do reino, ela vive sua vida na Floresta de Elwynn e dá as boas-vindas aos recém-chegados que chegam ao vale.",al={"por que melissa calmafonte está aqui","o que melissa está fazendo em vila norte"}},a071eba0={q="De que lado está Melissa Calmafonte?",a="Melissa Calmafonte é uma súdita leal da Grande Aliança e do Reino de Ventobravo. Residindo pacificamente na Abadia de Vila Norte, ela dá as boas-vindas aos viajantes e recrutas que chegam ao vale.",al={"facção de melissa calmafonte","melissa calmafonte é da aliança"}}},fp="16,219,30.449.0,24.144.0,34.74.0,57.222.0,39.106.0"}
P.entries["npc:merrin-rockweaver"] = {n="Marina Tecepedra",s="Marina Tecepedra é uma pesquisadora anã que representa a Liga dos Exploradores nos Pantanais. Após uma violenta infestação de raptores tomar o Sítio de Escavação de Whelgar, ela se refugiou ao lado do Prospector Whelgar em uma colina com vista para o local.",h="Marina Tecepedra é uma pesquisadora anã que representa a Liga dos Exploradores nos Pantanais.",kw={"liga dos exploradores","marina tecepedra","raptores","ferramentas úteis","pantanais","sítio de escavação de whelgar","refúgio de whelgar"},ang={["faction:Alliance"]="Marina representa a presença acadêmica de Altaforja nos Pantanais, e proteger sua pesquisa ajuda a manter o tênue domínio da Aliança sobre a área pantanosa selvagem.",["race:Dwarf"]="Para os aventureiros anões, ajudar Marina é uma questão de herança nacional, protegendo as preciosas relíquias dos Titãs e os registros históricos que a Liga dos Exploradores arriscou a própria vida para desenterrar."},sec={{t="Desalojada pela Escavação",b="Marina Tecepedra viajou até os Pantanais em nome da Liga dos Exploradores de Altaforja para desenterrar segredos antigos dos Titãs sob o lodo. A expedição terminou em desastre quando os grandes ossos que desenterraram atraíram raptores para a escavação. Feras pré-históricas cruéis invadiram as trincheiras, forçando Marina e a equipe sobrevivente a abandonar seus equipamentos, anotações e progresso. Ela agora está presa com os poucos sobreviventes em um penhasco com vista para as ruínas tomadas."},{t="Resgatando a Operação",b="Presos no penhasco, os sobreviventes se recusam a deixar a expedição se transformar em um fracasso total. Enquanto Ormer Trançaferro planeja vingança contra as feras e o Prospector Whelgar busca os fragmentos de tabuleta deixados para trás nas trincheiras infestadas de raptores, os pensamentos de Marina se voltam para seu marido Tarrel, que não tem notícias dela há semanas. Ela confia no batedor enviado por Longbraid para encontrar a equipe e levar notícias da difícil situação deles de volta para ele."}},faq={{q="Quem é Marina Tecepedra?",a="Marina Tecepedra é uma arqueóloga anã afiliada à Liga dos Exploradores de Altaforja. Ela estava alocada no Sítio de Escavação de Whelgar nos Pantanais antes de os raptores tomarem a operação.",al={"história de marina tecepedra","quem é marina","anã dos pantanais marina"}},{q="Por que ela está presa acima do sítio de escavação?",a="Raptores sarapintados, atraídos pelos ossos grandes que a equipe desenterrou, dominaram o sítio de escavação abaixo e muitas vidas foram perdidas. Ormer Trançaferro defendeu Marina e o Prospector Whelgar enquanto fugiam para o penhasco próximo, onde permanecem encurralados.",al={"por que marina está no retiro","marina no refúgio de whelgar","o que aconteceu com o acampamento dela"}},{q="Com o que Marina precisa de ajuda?",a="Marina precisa de alguém para levar uma carta explicando o desastre de volta ao seu marido Tarrel, que está morto de preocupação desde que as cartas dela pararam de chegar.",al={"missões de marina","tarefas de marina tecepedra","história de ferramentas úteis"}},{q="O que a expedição estava tentando encontrar?",a="Como a maioria das operações da Liga dos Exploradores, a escavação nos Pantanais foi comissionada para desenterrar artefatos antigos relacionados à ancestralidade dos anões e às misteriosas relíquias dos Titãs escondidas por toda Khaz Modan.",al={"o que eles estão escavando","propósito do sítio de escavação"}}},fx={["86a5e24a"]={q="De que lado está Marina Tecepedra?",a="Marina Tecepedra está firmemente alinhada com os anões de Altaforja e a Aliança. Como uma topógrafa ativa e membro da Liga dos Exploradores, sua lealdade está com os estudiosos e escavadores enviados de Altaforja para descobrir as antigas origens de seu povo por todo o Khaz Modan.",al={"facção de marina tecepedra","lealdade de marina tecepedra","a quem marina serve"}},f33c6ea8={q="A quem Marina Tecepedra está ligada?",a="Marina acompanha a expedição do Prospector Whelgar no local de escavação no Pantanal. Ormer Trançaferro ajuda a defender o acampamento dos raptores que o cercam.",al={"conexões de marina tecepedra","associados de marina tecepedra","com quem marina está trabalhando"}}},fp="17,250,20.459.0,23.426.0,25.195.0,38.234.0,32.152.0,39.192.0"}
P.entries["npc:miles-welsh"] = {n="Milo Gálico",s="Milo Gálico é um instrutor de sacerdotes Renegado que reside nas profundezas dos Poços das Visões, sob o Penhasco do Trovão. Ele oferece instrução espiritual e disciplina sombria aos sacerdotes que atravessam a capital tauren.",h="Milo Gálico é um instrutor de sacerdotes Renegado que reside nas profundezas dos Poços das Visões, sob o...",kw={"devouring plague","renegados","milo gálico","poços das visões","instrutor de sacerdotes","platô dos espíritos","penhasco do trovão"},ang={["class:Priest"]="Para sacerdotes que viajam por Kalimdor, Milo Gálico é um dos poucos lugares nos territórios centrais da Horda para estudar novos feitiços e avançar no treinamento espiritual.",["race:Undead"]="Milo proporciona um rosto familiar e frio de Lordaeron em uma capital tauren que, de outro modo, é campestre e ensolarada."},sec={{t="Uma Sombra nas Cavernas",b="Milo Gálico permanece longe das ruínas de Lordaeron devastadas pela peste, fazendo seu lar na gruta úmida e repleta de espíritos sob o Penhasco do Trovão conhecida como Poços das Visões. Como sacerdote Renegado, ele instrui viajantes que canalizam energias divinas e sombrias. Sua presença no coração de Mulgore reflete os tênues laços diplomáticos que unem os Renegados à Horda, compartilhando santuário com místicos e xamãs taurens enquanto orienta acólitos nas artes da sombra e da fé."}},faq={{q="Quem é Milo Gálico?",a="Milo Gálico é um instrutor de sacerdotes morto-vivo situado nos Poços das Visões, sob o Penhasco do Trovão, auxiliando sacerdotes da Horda em seu treinamento e disciplinas especializadas.",al={"papel de milo gálico","quem é milo gálico","instrutor de sacerdotes milo gálico"}},{q="Onde posso encontrar Milo Gálico?",a="Ele está localizado nos Poços das Visões, um sistema de cavernas subterrâneas sob o Platô dos Espíritos no Penhasco do Trovão, acessado através de uma entrada de caverna no platô.",al={"localização de milo gálico","onde fica milo gálico","como encontrar milo gálico"}},{q="Por que há um instrutor de sacerdotes morto-vivo no Penhasco do Trovão?",a="Os Renegados e os taurens são aliados dentro da Horda. Os taurens, especialmente Magatha Temível Totem, defenderam a admissão dos Renegados na facção, permitindo que emissários e instrutores como Milo Gálico ofereçam seus serviços em Mulgore.",al={"por que renegados no penhasco do trovão","sacerdote morto-vivo na cidade tauren"}},{q="Quais habilidades ele ensina?",a="Milo Gálico ensina feitiços gerais de sacerdote e auxilia acólitos Renegados e trolls que buscam ensinamentos raciais especializados, como Touch of Weakness ou Shadowguard.",al={"feitiços de sacerdote penhasco do trovão","o que milo gálico ensina"}}},fx={c3aae6f3={q="De que lado está Milo Gálico?",a="Milo Gálico está com os Renegados e a Horda em geral. Embora os tauren sigam um caminho espiritual inteiramente diferente enraizado na Mãe Terra, Milo reside abaixo de sua mesa entre seus aliados para oferecer seu conhecimento do sacerdócio aos viajantes da Horda que o procuram.",al={"facção de milo gálico","milo gálico horda ou aliança","a quem milo gálico serve"}},["9239b409"]={q="O que Milo Gálico quer?",a="Milo Gálico serve como instrutor para outros sacerdotes que visitam o Penhasco do Trovão. Lá embaixo, nos isolados Poços das Visões, ele compartilha sua disciplina e artes sombrias com aqueles que percorrem o caminho da sombra e da fé, garantindo que os discípulos da Horda tenham orientação mesmo longe de Lordaeron.",al={"o que milo gálico faz","propósito de milo gálico","objetivos de milo gálico"}},["03472250"]={q="A quem Milo Gálico está ligado?",a="Milo Gálico está ligado aos Renegados da Cidade Baixa. Sua presença no Penhasco do Trovão o coloca ao lado dos emissários e viajantes Renegados acolhidos na capital tauren através do pacto incipiente entre o povo de Caerne Casco Sangrento e os seguidores da Grande Dama Sylvana Correventos.",al={"aliados de milo gálico","para quem milo gálico trabalha","conexões de milo gálico"}}},fp="11,200,23.469.0,19.166.0,29.154.0,49.236.0,29.160.0"}
P.entries["npc:milli-featherwhistle"] = {n="Milli Penapita",s="Milli Penapita é uma mestre engenheira gnomo de mecanorrestrutzes lotada na Garagem do Gradaço, em Dun Morogh. Após a queda de Gnomeregan, ela constrói e mantém meticulosamente à mão as montarias de corda preferidas por seu povo. Ela vende suas valiosas criações mecânicas a outros gnomos e a aliados de confiança dos sobreviventes exilados de Gnomeregan.",h="Milli Penapita é uma mestre engenheira gnomo de mecanorrestrutzes lotada na Garagem do Gradaço, em Dun Morogh.",kw={"dun morogh","gnomeregan","kharanos","mecanorrestrutz","mekkatorque","milli penapita","vendedor de montarias","garagem do gradaço"},ang={["faction:Alliance"]="Heróis da Aliança que conquistarem o mais alto respeito dos Exilados de Gnomeregan podem procurar Milli para comandar uma das montarias mecânicas mais velozes de Azeroth.",["profession:Engineering"]="Os mecanorrestrutzes de Milli representam o ápice da locomoção gnômica em larga escala, combinando unidades de equilíbrio giroscópico com membros mecânicos de alto torque.",["race:Gnome"]="Milli Penapita é a principal engenheira de montarias do seu povo, dando continuidade à genialidade tecnológica do Grão-mecânico Mekkatorque mesmo no exílio de seu lar subterrâneo."},sec={{t="Mestre dos Mecanorrestrutzes",b="Trabalhando ao ar livre no frio cortante da Garagem do Gradaço, a leste de Kharanos, Milli Penapita supervisiona o fornecimento de corcéis de corda para a população deslocada de Gnomeregan. Diferente das feras biológicas preferidas por anões e elfos noturnos, Milli constrói todo o seu inventário pessoalmente, calibrando engrenagens, pistões e giroscópios de equilíbrio para garantir que cada ave mecânica funcione com eficiência máxima pelos penhascos nevados de Dun Morogh."},{t="O Legado de Mekkatorque",b="Cada estrutura e mola na oficina de Milli tem raízes nos diagramas originalmente traçados pelo Grão-mecânico Gelbin Mekkatorque. Embora Milli tenha integrado melhorias modernas de desempenho ao longo dos anos — otimizando o peso dos chassis e aprimorando as saídas de escape —, ela segue fielmente os esquemas fundamentais do Grão-mecânico. Suas maravilhas mecânicas provam que, mesmo no exílio, a ambição tecnológica dos gnomos permanece totalmente inabalada."}},faq={{q="Quem é Milli Penapita?",a="Milli Penapita é a principal criadora e engenheira de mecanorrestrutzes dos gnomos de Gnomeregan. Estabelecida na Garagem do Gradaço, em Dun Morogh, ela constrói à mão e vende mecanorrestrutzes de corda a montadores qualificados.",al={"milli penapita","quem é milli","vendedor de mecanorrestrutz"}},{q="Onde posso encontrar Milli Penapita?",a="Ela fica na Garagem do Gradaço, um entreposto de engenharia localizado a uma curta caminhada a leste pela estrada a partir da vila de Kharanos, em Dun Morogh.",al={"localização de milli","onde fica milli penapita","encontrar milli"}},{q="Quem tem permissão para comprar montarias dela?",a="Por padrão, apenas aventureiros gnomos têm a autorização imediata e a aptidão para comprar suas criações. Integrantes de outras raças da Aliança precisam conquistar a máxima confiança e o status de exaltado com os Exilados de Gnomeregan antes que ela lhes confie um mecanorrestrutz.",al={"posso comprar um mecanorrestrutz","requisitos para mecanorrestrutz","quem pode montar mecanorrestrutz"}},{q="Como os mecanorrestrutzes são feitos?",a="Milli Penapita fabrica cada mecanorrestrutz pessoalmente, baseando sua construção nos emblemáticos diagramas projetados pelo Grão-mecânico Gelbin Mekkatorque, ao mesmo tempo em que implementa aprimoramentos personalizados de motor e equilíbrio.",al={"como mecanorrestrutzes são construídos","quem fabrica mecanorrestrutzes","origem dos mecanorrestrutzes"}},{q="Quais variedades de montaria ela oferece?",a="Ela fornece diversos modelos calibrados, variando de estruturas padrão sem pintura, azuis, verdes e vermelhas a variantes velozes ajustadas com precisão, com acabamentos em revestimentos brancos, verdes e amarelos.",al={"cores das montarias de milli","modelos de mecanorrestrutz","quais montarias milli vende"}},{q="Por que ela está trabalhando na neve na Garagem do Gradaço?",a="Após a catástrofe radioativa e a invasão dos troggs expulsarem os gnomos de Gnomeregan, os refugiados se reuniram onde puderam. A Garagem do Gradaço serve como um ponto de encontro natural fora de Kharanos para testes veiculares e manutenção mecânica ao lado de engenheiros anões.",al={"por que milli está em dun morogh","por que garagem do gradaço"}}},fx={["2267a2b3"]={q="De que lado está Milli Penapita?",a="Milli Penapita é dedicada a Gnomeregan e à Grande Aliança. Trabalhando na Garagem do Gradaço ao lado de artesãos anões, ela fornece mecanostruídos diretamente para seus colegas gnomos e para os campeões da Aliança de confiança que conquistaram o total respeito dos Exilados de Gnomeregan.",al={"facção de milli penapita","a quem milli penapita serve","milli é da aliança"}},f07f7c95={q="O que Milli Penapita quer?",a="Milli quer construir e manter os melhores mecanostruídos de Dun Morogh. Baseando suas criações nos esquemas originais do High Tinker Mekkatorque, ela refina continuamente sua engenharia para que montarias mecanizadas confiáveis permaneçam facilmente disponíveis para viajantes gnomos e aliados comprovados.",al={"o que milli penapita faz","objetivo de milli penapita","o que milli está tentando fazer"}}},fp="20,342,25.441.0,21.432.0,28.220.0,38.147.0,43.262.0,29.206.0,36.178.0,57.271.0"}
P.entries["npc:milton-sheaf"] = {n="Milton Resma",s="Milton Resma é o bibliotecário-chefe da Royal Library dentro de Bastilha Ventobravo. Dedicado a preservar a história do reino, ele supervisiona a coleção de tomos antigos e crônicas históricas do reino. Ele frequentemente recruta viajantes da Aliança para recuperar volumes perdidos, rastrear registros dispersos e restaurar manuscritos negligenciados.",h="Milton Resma é o bibliotecário-chefe da Royal Library dentro de Bastilha Ventobravo.",kw={"livros","história","bibliotecário","milton resma","royal library","bastilha ventobravo","tomos"},ang={["faction:Alliance"]="Como o principal bibliotecário do reino, Milton Resma ajuda a preservar o patrimônio registrado dos reinos humanos e de toda a Aliança.",["race:Human"]="Milton protege séculos de história humana, salvaguardando crônicas que sobreviveram à queda e à reconstrução de Ventobravo."},sec={{t="O Guardião da História de Ventobravo",b="Acomodado nos corredores tranquilos da Royal Library em Bastilha Ventobravo, Milton Resma cuida da memória coletiva do reino. Enquanto a corte no andar de cima ferve com política, disputas entre nobres e preocupações militares, Resma se concentra na preservação da palavra escrita. Ele considera a manutenção de relatos históricos precisos da Aliança e dos Reinos do Leste um dever sagrado, especialmente em uma era repleta de guerras, perdas e instabilidade."},{t="Recuperando Tomos Perdidos",b="Preservar a coleção da biblioteca exige esforço constante. Os livros sofrem desgaste com o tempo, e registros valiosos frequentemente se espalham pelo reino em arquivos monásticos, postos avançados distantes ou ruínas esquecidas. Milton envia aventureiros regularmente por toda a terra — da Abadia de Vila Norte ao distante assentamento nortenho de Costa Sul — para resgatar volumes perdidos, investigar textos antigos e garantir que manuscritos raros retornem em segurança às prateleiras da fortaleza."}},faq={{q="Quem é Milton Resma?",a="Milton Resma é um estudioso humano e o guardião-chefe da Royal Library, localizada dentro de Bastilha Ventobravo em Ventobravo. Ele gerencia as coleções de livros e as crônicas do reino.",al={"quem é milton resma","papel de milton resma","bibliotecário de ventobravo"}},{q="Onde posso encontrar Milton Resma?",a="Você pode encontrar Milton Resma dentro da ala da Royal Library em Bastilha Ventobravo, situada logo ao lado dos corredores principais do palácio.",al={"localização de milton resma","onde fica milton resma","localização da biblioteca de ventobravo"}},{q="Por que Milton Resma precisa de aventureiros?",a="Milton frequentemente conta com aventureiros da Aliança em viagem para rastrear manuscritos históricos, substituir livros danificados e coordenar com estudiosos e sacerdotes de todo o reino para expandir os arquivos da Royal Library.",al={"missões de milton resma","o que milton quer","por que dá missões"}},{q="Milton Resma interage com outros estudiosos do reino?",a="Sim. Ele mantém laços com arquivistas monásticos e estudiosos religiosos, incluindo o Irmão Paxeco no Vale de Vila Norte, para preservar ensinamentos sagrados e registros históricos.",al={"milton vila norte","milton irmão paxeco","conexões de milton"}}},fx={["440d1fb9"]={q="De que lado está Milton Resma?",a="Milton Resma serve ao Reino de Ventobravo e à Aliança. Estacionado dentro da própria Bastilha Ventobravo, ele trabalha diretamente em nome dos arquivos reais da coroa, catalogando a história e preservando o conhecimento para os estudiosos e a liderança do reino.",al={"facção de milton resma","a quem milton resma serve","milton resma aliança"}},["1fad6188"]={q="Por que Milton Resma está aqui na Bastilha Ventobravo?",a="Milton está encarregado da administração e manutenção da Royal Library. Ele cuida da vasta coleção de pergaminhos, tomos e registros históricos do reino, garantindo que contas vitais do passado de Azeroth permaneçam protegidas e acessíveis à corte.",al={"por que milton resma está na royal library","propósito de milton resma aqui","por que milton está em ventobravo"}}},fp="12,335,36.437.0,21.461.0,20.184.0,30.119.0,39.214.0,62.171.0"}
P.entries["npc:miner-johnson"] = {n="Mineiro Johnson",s="O Mineiro Johnson é um minerador veterano e elusivo afiliado à Irmandade Défias nas profundezas das Minas Mortas. Escondido em uma alcova lateral ao lado de trabalhadores comuns, esse perigoso garimpeiro supervisiona os esforços de escavação antes da maquinaria pesada encontrada mais abaixo na terra. Como vaga erraticamente pelos túneis subterrâneos, aventureiros só cruzam seu caminho ocasionalmente.",h="O Mineiro Johnson é um minerador veterano e elusivo afiliado à Irmandade Défias nas profundezas das Minas...",kw={"alcova","minas mortas","défias","elite","mineiro johnson","arroio da lua","raro","triturador","cerro oeste"},ang={["faction:Alliance"]="Derrotar João interrompe o fluxo constante de minério fundível que abastece a máquina de guerra Défias escondida sob Arroio da Lua.",["profession:Mining"]="Para os garimpeiros, João representa o lado rústico e sem lei do trabalho subterrâneo, protegendo ricos depósitos minerais nas profundezas de Cerro Oeste com sangue e picareta."},sec={{t="Um Rosto Raro nas Profundezas",b="Enquanto centenas de trabalhadores picam as jazidas subterrâneas das Minas Mortas para abastecer a fortaleza oculta de Edwin VanCleef, o Mineiro Johnson se destaca como uma figura incomumente formidável entre eles. Espreitando em uma alcova sombria à esquerda antes dos trituradores pesados da Mast Room, ele é muito mais resistente e agressivo do que a mão de obra comum. Sua presença imprevisível faz dele um alvo lendário para exploradores que atravessam os túneis Défias."},{t="Abastecendo a Máquina de Guerra Défias",b="A operação clandestina da Irmandade Défias sob Arroio da Lua exige grandes quantidades de minério bruto para forjar armas, reforçar poços e montar engenhocas mecânicas. Mineradores como João fornecem a força motriz por trás do metal, golpeando os ricos veios minerais sob Cerro Oeste. Qualquer um que entrar sem querer no espaço de trabalho de João descobrirá rapidamente que ele defende sua escavação com fervor letal."}},faq={{q="Quem é o Mineiro Johnson?",a="O Mineiro Johnson é um minerador humano raro e de elite aliado à Irmandade Défias. Ele trabalha nas profundezas das Minas Mortas, situado em uma alcova lateral com outros trabalhadores logo antes do triturador goblínico.",al={"história do minerador joão","quem é o minerador joão","minerador joão minas mortas"}},{q="Onde exatamente fica o Mineiro Johnson?",a="Ele pode ser encontrado nos poços superiores das Minas Mortas antes de chegar à sala que abriga Sneed e seu triturador. Procure uma pequena alcova de escavação à esquerda, onde um grupo de mineradores está quebrando a rocha ativamente.",al={"localização do minerador joão","onde fica o minerador joão","como encontrar o minerador joão"}},{q="Por que o Mineiro Johnson nem sempre está lá?",a="O Mineiro Johnson é uma aparição rara, o que significa que ele só surge ocasionalmente quando uma expedição entra nas Minas Mortas. A maioria dos grupos que atravessam os poços da mina encontrará um minerador comum em seu lugar.",al={"minerador joão não aparece","o minerador joão é raro","taxa de aparição do minerador joão"}},{q="O Mineiro Johnson faz parte de alguma missão?",a="O Mineiro Johnson não está associado a nenhuma recompensa de missão formal. Ele é simplesmente um encontro de oportunidade para grupos de masmorra sortudos o suficiente para encontrá-lo trabalhando na jazida.",al={"missão do minerador joão","o minerador joão tem missão"}},{q="Qual é o papel do Mineiro Johnson nas Minas Mortas?",a="Ele é um capataz experiente ou mestre escavador que ajuda a Irmandade Défias a extrair metal precioso, pedra e recursos necessários para construir sua enorme base subterrânea e o colosso oculto.",al={"o que o minerador joão faz","papel do minerador joão"}},{q="O Mineiro Johnson é perigoso em comparação com outros mineradores?",a="Sim. Enquanto os escavadores comuns por todas as Minas Mortas são relativamente frágeis, o Mineiro Johnson é um combatente de elite com muito mais vitalidade e poder de ataque, exigindo um grupo coordenado para ser derrotado em segurança.",al={"quão difícil é o minerador joão","o minerador joão é elite"}}},fx={["3a6e6cc9"]={q="De que lado está o Mineiro Johnson?",a="Ele está com a The Defias Brotherhood e sua força de trabalho. Trabalhando arduamente nas profundezas das Minas Mortas ao lado dos outros trabalhadores, o Mineiro Johnson compartilha a lealdade deles com a revolta de Edwin VanCleef, empunhando sua picareta contra quaisquer intrusos que rompam seu reduto subterrâneo.",al={"facção do mineiro johnson","para quem o mineiro johnson trabalha","o mineiro johnson é da defias"}}},fp="13,379,23.446.0,30.398.0,21.192.0,39.225.0,37.202.0,35.170.0,46.198.0,52.221.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="Manifestação Menor de Terra",s="Uma Manifestação Menor de Terra é um espírito elemental localizado e vinculado a pedras sagradas em Mulgore e Durotar. Invisível à visão comum, ela se revela apenas a xamãs novatos que bebem a sagrada Sapta da Terra, concedendo o Quartzo Grosseiro necessário para esculpir seu primeiro Totem da Terra.",h="Uma Manifestação Menor de Terra é um espírito elemental localizado e vinculado a pedras sagradas em Mulgore e...",kw={"clamor da terra","sapta da terra","totem da terra","rocha dos kodos","manifestação menor de terra","quartzo grosseiro","rocha dos espíritos"},ang={["class:Shaman"]="Todo jovem xamã da Horda deve comungar com uma Manifestação Menor de Terra sob a influência da Sapta da Terra para conquistar seu primeiro totem.",["race:Tauren"]="Os jovens taurens viajam para o leste através de Mulgore até a Rocha dos Kodos para buscar comunhão com esta manifestação como parte de seus testes espirituais ancestrais."},sec={{t="Voz da Pedra",b="Os espíritos da terra habitam por toda parte sob o solo e a rocha, mas a comunicação com eles exige um ritual específico. Em marcos sagrados como a Rocha dos Kodos em Mulgore e a Rocha dos Espíritos em Durotar, Manifestações Menores de Terra aguardam no reino invisível, cercadas por presenças elementais ainda menores. Apenas os iniciados que beberam a Sapta da Terra — uma poção ritual preparada por mentores xamânicos — conseguem erguer o véu entre o mundo físico e os elementos. Uma vez reconhecido, o espírito concede as bênçãos da terra juntamente com um pedaço de Quartzo Grosseiro, garantindo ao novato o foco espiritual necessário para criar um Totem da Terra."}},faq={{q="Por que não consigo ver a Manifestação Menor de Terra?",a="A manifestação existe no plano elemental e permanece invisível a olho nu. Você deve beber uma Sapta da Terra, fornecida pelo seu instrutor de xamãs, para entrar no estado alterado de percepção necessário para enxergar e falar com espíritos elementais.",al={"não consigo ver a manifestação","onde fica o espírito da terra","manifestação da terra invisível"}},{q="Onde esses espíritos da terra podem ser encontrados?",a="Eles aparecem na Rocha dos Kodos, nos Morros Ondulantes de Mulgore, e na Rocha dos Espíritos, nos desfiladeiros áridos de Durotar. Ambos os locais servem como tradicionais campos de testes para jovens xamãs taurens, orcs e trolls.",al={"localização da manifestação menor","onde encontrar manifestação de terra"}},{q="Qual é o propósito do espírito durante o rito?",a="A manifestação testa e reconhece formalmente a conexão do iniciado com o elemento terra. Ao conversar com o xamã, ela concede um pedaço de Quartzo Grosseiro, que é levado de volta a um instrutor de xamãs para forjar o Totem da Terra.",al={"o que a manifestação faz","propósito da missão da manifestação"}},{q="O que são as criaturas menores ao redor dela?",a="Ao redor do espírito central há manifestações menores de terra. Elas são ecos sutis do elemento atraídos para os terrenos sagrados, existindo puramente como parte da comunhão natural, e não é possível interagir diretamente com elas.",al={"manifestações menores","pequenos elementais da terra ao redor"}}},fx={["40387732"]={q="Quem é a Manifestação Menor de Terra?",a="A Manifestação Menor de Terra é um espírito elemental da terra invocado e reverenciado em solos sagrados como a Rocha dos Kodos em Mulgore e a Rocha dos Espíritos em Durotar. Invisível à visão comum, ela se revela apenas aos xamãs que expandiram sua consciência espiritual através de bebidas cerimoniais como a Earth Sapta.",al={"o que é a manifestação menor de terra","quem é a manifestação de terra","história da manifestação menor de terra"}},f34b34da={q="De que lado está a Manifestação Menor de Terra?",a="Ela não serve nem à Horda nem à Aliança. Como uma personificação dos elementos, ela se alinha ao equilíbrio do mundo natural e atende às petições dos iniciados que demonstram o respeito e a clareza espiritual necessários para comungar com a terra.",al={"facção da manifestação menor de terra","a manifestação menor de terra é amigável","de que lado está a manifestação de terra"}},["95a7d1ef"]={q="O que a Manifestação Menor de Terra quer?",a="Ela deseja comunhão com aqueles que caminham pelo caminho do xamã. Quando abordada por um iniciado que consumiu a Earth Sapta, ela busca testar sua determinação e conceder um pedaço de Quartzo Grosseiro para formar a base de seu primeiro totem.",al={"o que a manifestação de terra quer","desejo da manifestação de terra","o que a manifestação menor busca"}},["17161102"]={q="Por que a Manifestação Menor de Terra está aqui?",a="Ela reside em lugares sagrados de poder elemental, como a Rocha dos Kodos em Mulgore e a Rocha dos Espíritos em Durotar, para servir como uma ponte entre a terra viva e os possíveis xamãs que estão passando pelo Call of Earth.",al={"por que a manifestação menor de terra está na rocha dos kodos","por que a manifestação de terra está aqui","por que o espírito da terra está aqui"}}},fp="28,291,18.638.0,49.247.0,39.198.0,45.234.0,46.221.0"}
P.entries["npc:minor-manifestation-of-water"] = {n="Manifestação Menor da Água",s="A Manifestação Menor da Água é um espírito elemental encontrado ao longo da Costa da Maré do Norte, no litoral da Floresta de Pinhaprata. Ela serve como uma provação vital para xamãs da Horda que buscam comungar com o elemento da água e dominá-lo. Antes que este espírito pacífico possa ser consultado, os iniciados precisam purificar sua contraparte corrompida.",h="A Manifestação Menor da Água é um espírito elemental encontrado ao longo da Costa da Maré do Norte, no...",kw={"clamor da água","elemental","manifestação menor da água","costa da maré do norte","missão de xamã","floresta de pinhaprata","totem da água"},ang={["class:Shaman"]="Purificar a corrupção deste elemental e receber sua bênção é o marco final na sintonização com as marés e na forja do seu Totem da Água.",["faction:Horde"]="Xamãs trolls, orcs e taurens viajam desde Kalimdor até a costa de Lordaeron para comungar com este espírito."},sec={{t="Um Espírito das Marés Ocidentais",b="Espreitando pelas margens envoltas em névoa da Costa da Maré do Norte, a oeste de O Sepulcro na Floresta de Pinhaprata, a Manifestação Menor da Água representa um rito de passagem essencial para xamãs em desenvolvimento. Os elementais da água personificam a vida, a renovação e a fluidez, mas podem facilmente sucumbir a pestes malévolas. Um iniciado precisa enfrentar e derrotar uma manifestação corrompida deste elemental antes que a pura Manifestação Menor da Água possa se revelar. Uma vez purificado, o espírito oferece orientação aos xamãs que concluem sua sagrada jornada para moldar um Totem da Água."}},faq={{q="Onde posso encontrar a Manifestação Menor da Água?",a="A Manifestação Menor da Água surge ao longo da Costa da Maré do Norte, na costa oeste da Floresta de Pinhaprata, logo a oeste de O Sepulcro.",al={"localização da manifestação menor da água","onde fica a manifestação da água","elemental da costa da maré do norte"}},{q="Por que o elemental fica hostil quando me aproximo pela primeira vez?",a="Um xamã deve primeiro evocar e destruir a Corrupt Minor Manifestation of Water. Somente após derrotar a presença corrompida a manifestação pacífica aparece para conversar com você.",al={"manifestação menor corrompida","por que a manifestação da água está com raiva","manifestação me atacando"}},{q="Qual missão envolve este elemental?",a="Este espírito é um contato crucial na série de missões de xamã 'Clamor da água', por meio da qual os xamãs finalmente adquirem a habilidade de evocar seu Totem da Água.",al={"missão clamor da água","missão totem da água floresta de pinhaprata","para qual missão serve isso"}},{q="Pessoas que não são xamãs podem interagir com este espírito?",a="A Manifestação Menor da Água existe especificamente para guiar xamãs que concluem suas provações espirituais. Outros aventureiros encontrarão pouca razão para interagir com ela.",al={"isto é apenas para xamã","qualquer um pode falar com a manifestação","quem fala com a manifestação menor"}}},fx={["8e58f5e5"]={q="Quem é a Manifestação Menor da Água?",a="A Manifestação Menor da Água é um espírito das águas elementais invocado para testar e guiar aspirantes a xamãs. Uma vez limpo da corrupção, este elemental serve como um conduto do fluxo natural e da sabedoria da água, auxiliando aqueles que aprendem a atender ao chamado dos elementos.",al={"quem é a manifestação menor da água","o que é a manifestação menor da água","quem é este elemental"}},c7703042={q="De que lado está a Manifestação Menor da Água?",a="A manifestação não pertence nem à Horda nem à Aliança. Ela serve ao próprio equilíbrio dos elementos, atendendo ao chamado dos xamãs que buscam comunhão com a água e demonstrando se um suplicante possui a força e a pureza de espírito para exercer seus poderes.",al={"facção da manifestação menor da água","a quem a manifestação da água serve","a manifestação menor da água é da horda"}},["9e575f56"]={q="O que a Manifestação Menor da Água quer?",a="Este espírito busca testar qualquer xamã que busque o domínio sobre a água. Ele exige que você prove ser capaz de superar forças corruptoras antes de compartilhar sua essência pura e conceder sua bênção.",al={"objetivo da manifestação menor da água","o que a manifestação da água deseja","propósito da manifestação da água"}},["05f89621"]={q="Por que a Manifestação Menor da Água está aqui?",a="A manifestação é atraída para lugares onde o poder da água se acumula e aguarda os rituais dos xamãs que respondem ao Call of Water. Ela se manifesta especificamente para comungar com aqueles guiados à sua presença por seus mentores elementais.",al={"por que a manifestação da água está aqui","razão da localização da manifestação da água"}}},fp="28,323,29.559.0,50.134.0,51.182.0,35.152.0,42.167.0"}
P.entries["npc:misha"] = {n="Misha",s="Misha é a leal ursa companheira de Rexxar, o Campeão da Horda. Ela vaga fielmente por Kalimdor ao lado do mestre das feras meio-ogro.",h="Misha é a leal ursa companheira de Rexxar, o Campeão da Horda.",kw={"urso","mestre das feras","desolação","feralas","misha","rexxar","cordilheira das torres de pedra"},ang={["class:Hunter"]="Para os caçadores, Misha representa o ideal supremo de um animal companheiro: uma parceria inquebrável para a vida toda, forjada pelo respeito mútuo em vez de mero domínio.",["faction:Horde"]="Misha lutou ao lado de Rexxar para garantir a liberdade da jovem Horda na Ilha Theramore, conquistando o respeito silencioso dos veteranos por toda Durotar."},sec={{t="Um Vínculo Ilimitado",b="Misha é uma ursa marrom que caminha ao lado do errante Rexxar, um espírito solitário que confia mais em feras do que em pessoas. Juntos, eles forjaram uma parceria feroz e protetora que sobreviveu a inúmeras terras ermas e batalhas sangrentas."},{t="Defensora de Durotar",b="Misha é muito mais do que um animal de estimação domesticado; ela é uma Guerreira veterana. Ela lutou ao lado de Rexxar no conflito brutal contra o Grande Almirante Daelin Proudmore na Ilha Theramore, ajudando a garantir a sobrevivência da jovem Horda. Quando não está em batalha, seus sentidos aguçados e sua força servem como uma extensão da vontade de Rexxar."},{t="Ermos de Kalimdor",b="Atualmente, viajantes que se aventuram pelas longas trilhas através da Cordilheira das Torres de Pedra, Desolação e Feralas podem avistar Misha caminhando silenciosamente ao lado de Rexxar. Embora feroz o suficiente para despedaçar qualquer predador tolo o bastante para ameaçá-los, ela continua sendo o porto seguro inabalável de Rexxar em um mundo nada confiável."}},faq={{q="Quem é Misha?",a="Misha é uma feroz ursa marrom e a companheira de toda a vida de Rexxar, o Campeão da Horda. Ela percorre as terras ermas ao lado dele pelo centro de Kalimdor.",al={"urso de rexxar","quem é o urso com rexxar","misha urso"}},{q="Onde Misha pode ser encontrada no momento?",a="Misha perambula pelos longos caminhos de patrulha da Cordilheira das Torres de Pedra, Desolação e Feralas, caminhando fielmente ao lado de Rexxar em suas andanças sem fim.",al={"localização de misha","onde está misha","encontrar misha"}},{q="Misha participou da fundação de Durotar?",a="Sim. Após a Terceira Guerra, Misha acompanhou Rexxar na batalha contra as forças do Grande Almirante Daelin Proudmore na Ilha Theramore para defender a jovem Horda.",al={"misha theramore","misha lutou contra daelin","misha terceira guerra"}},{q="Misha é hostil aos jogadores da Aliança?",a="Sim. Como companheira do Campeão da Horda, Misha defenderá Rexxar ferozmente e atacará quaisquer invasores da Aliança que se aproximarem demais.",al={"aliança pode atacar misha","misha é agressiva"}},{q="Por que Rexxar prefere feras como Misha a pessoas?",a="Desiludido com o engano e as guerras das raças humanoides, Rexxar escolheu a solidão da natureza selvagem. Ele acredita que as feras são diretas e honestas, encontrando em Misha uma companheira isenta de traição.",al={"por que rexxar mantém feras","rexxar companheiro urso"}}},fp="5,140,16.243.0,19.303.0,17.310.0,13.157.0,35.154.0,47.164.0,37.141.0,51.194.0"}
P.entries["npc:misha-tor-kren"] = {n="Misha Tor'kren",s="Misha Tor'kren é uma mãe orc que vive na Fazenda Tor'kren no oeste de Durotar, a sudeste do Desfiladeiro do Trovão. Atormentada pela angústia devido ao desaparecimento de seu filho, Kron, ela apela aos viajantes que passam por ali por ajuda para descobrir seu destino.",h="Misha Tor'kren é uma mãe orc que vive na Fazenda Tor'kren no oeste de Durotar, a sudeste do Desfiladeiro do...",kw={"crocodiliano","kron","lost but not forgotten","misha","misha tor'kren","rio furiaustral","desfiladeiro do trovão","fazenda tor'kren"},ang={["class:Hunter"]="O destino do filho de Misha mostra o perigo de subestimar os predadores do rio antes que um caçador tenha realmente dominado a natureza selvagem.",["race:Orc"]="O desejo imprudente de Kron de provar sua proeza guerreira contra a vida selvagem de Durotar serve como um lembrete sombrio do alto preço do orgulho juvenil."},sec={{t="A Vigília de uma Mãe",b="Escondida perto da borda do Desfiladeiro do Trovão, Misha Tor'kren trabalha em sua fazenda isolada enquanto suporta o pior medo de um pai. Seu filho, Kron, aventurou-se para o oeste, em direção ao Rio Furiaustral, para caçar crocodilianos e provar seu valor, mas nunca retornou. Com os perigos da fronteira de Durotar deixando as torres de vigia orcs com pouca guarnição, Misha fica sozinha esperando por notícias sobre seu paradeiro, desesperada por alguém disposto a procurar nas margens do rio por sinais de seu filho."},{t="Um Sinal Cruel",b="O Rio Furiaustral é implacável com jovens caçadores. Aqueles que vasculham as margens lodosas inevitavelmente descobrem que Kron foi vítima dos ferozes crocodilianos do rio. Devolver o amuleto recuperado é o único consolo que Misha pode receber — um lembrete amargo dos testes brutais que os jovens orcs enfrentam para provar sua força na natureza selvagem e inóspita de Kalimdor."}},faq={{q="Quem é Misha Tor'kren?",a="Misha Tor'kren é uma colonizadora orc que reside na Fazenda Tor'kren no oeste de Durotar, situada logo a sudeste do Desfiladeiro do Trovão.",al={"misha torkren","quem é misha","dona da fazenda torkren"}},{q="Para onde o filho dela, Kron, foi?",a="Kron viajou para o oeste, em direção ao Rio Furiaustral, para caçar crocodilianos do rio, ansioso para provar ser um caçador capaz, mas não conseguiu voltar para casa.",al={"onde está kron","o que aconteceu com kron","filho de misha"}},{q="O que acontece quando você procura por Kron?",a="Misha envia aventureiros para procurar por Kron ao longo do rio. O desaparecimento dele pesa muito sobre ela, e ela precisa de alguém para investigar a área.",al={"kron está morto","encontrar kron","lost but not forgotten"}},{q="Ela tem relação com a ursa Misha de Rexxar?",a="Não. Embora compartilhem o nome Misha, ela é uma fazendeira orc que vive em Durotar, totalmente distinta da fiel ursa companheira de Rexxar.",al={"ursa misha","misha ursa de rexxar","ela é a ursa"}}},fx={["971252e3"]={q="De que lado está Misha Tor'kren?",a="Misha Tor'kren é um membro leal da Horda, vivendo como uma humilde colonizadora orc em Durotar. Ela vive na Fazenda Tor'kren, cultivando o solo vermelho árido e contando com viajantes da Horda e campeões locais para ajudar sua família em momentos de crise.",al={"facção de misha tor'kren","a quem serve misha tor'kren","misha torkren horda"}},b9e15925={q="O que Misha Tor'kren quer?",a="Misha quer desesperadamente encontrar seu filho perdido, Kron. O jovem orc desapareceu enquanto caçava ao longo das margens perigosas do Rio Furiaustral, e ela implora aos aventureiros que passam para que procurem nas águas, descubram o que aconteceu com ele e tragam qualquer sinal de seu destino.",al={"o que misha quer","objetivo de misha tor'kren","por que misha precisa de ajuda"}},["8e838196"]={q="A quem Misha Tor'kren está ligada?",a="Misha está profundamente ligada à sua família, principalmente ao seu filho desaparecido, Kron. Ela administra a propriedade Tor'kren a sudeste do Desfiladeiro do Trovão, onde seus meios de subsistência dependem da sobrevivência aos perigos da região selvagem de Durotar.",al={"família de misha tor'kren","com quem misha tem parentesco","filho de misha torkren"}}},fp="14,221,16.444.0,12.345.1,22.124.0,26.140.0,36.147.1,38.130.0"}
P.entries["npc:mitsuwa"] = {n="Mitsuwa",s="Mitsuwa é um troll Lançanegra alocado no Assentamento Zoram'gar ao longo da costa enevoada de Vale Gris. Profundamente abalado pela emboscada contra seus parentes viajantes, ele recruta campeões da Horda para vingar os caídos e recuperar talismãs espirituais roubados.",h="Mitsuwa é um troll Lançanegra alocado no Assentamento Zoram'gar ao longo da costa enevoada de Vale Gris.",kw={"vale gris","lançanegra","furborg","marukai","mitsuwa","pelocardo","troll","patuá troll","zoram'gar"},ang={["faction:Horde"]="O Assentamento Zoram'gar é uma guarnição isolada e cercada; ajudar Mitsuwa fortalece a presença precária da Horda contra feras selvagens e batedores da Aliança nos limites ocidentais de Kalimdor.",["race:Troll"]="O chamado às armas de Mitsuwa toca profundamente os aventureiros Lançanegra, pois recuperar patuás ancestrais sagrados de saqueadores furborgs rudes restaura a paz de seus irmãos e irmãs assassinados."},sec={{t="Vingando os parentes caídos",b="Situado no remoto Assentamento Zoram'gar na costa da Praia de Zoram, Mitsuwa serve à Horda ao lado de seu companheiro Marukai. Quando um grupo de trolls viajantes a caminho do acampamento foi emboscado e massacrado pelos agressivos furborgs Pelocardo do norte de Vale Gris, Mitsuwa encarou a perda como uma grave ofensa. Movido pelo dever e pela raiva, ele direciona guerreiros valorosos aos covis dos Pelocardo para recuperar os patuás trolls roubados, garantindo que os espíritos de seus parentes sejam honrados e seus pertences sagrados resgatados das feras."}},faq={{q="Quem é Mitsuwa?",a="Mitsuwa é um troll da selva Lançanegra que reside no Assentamento Zoram'gar, no noroeste de Vale Gris. Ele vigia o posto de fronteira ao lado de seu companheiro Marukai e coordena represálias contra ameaças regionais hostis.",al={"mitsuwa","quem é mitsuwa","mitsuwa história"}},{q="O que aconteceu com os trolls que viajavam para Zoram'gar?",a="Um grupo de trolls que viajava por Vale Gris para reforçar ou visitar o Assentamento Zoram'gar foi emboscado e massacrado pelos furborgs Pelocardo nativos, que saquearam os pertences pessoais dos viajantes caídos.",al={"trolls mortos vale gris","pelocardo atacam trolls"}},{q="Por que os patuás trolls são tão importantes para Mitsuwa?",a="Os patuás têm significado espiritual e cultural para a tribo Lançanegra. Deixar relíquias sagradas nas mãos dos furborgs Pelocardo após um massacre brutal é uma profunda desonra aos espíritos dos mortos.",al={"por que patuás trolls","motivo da missão do patuá troll"}},{q="Onde os patuás estão localizados?",a="Os patuás foram levados pelos furborgs Pelocardo para sua aldeia e covil imundo, situados no norte de Vale Gris, a leste da Praia de Zoram.",al={"onde encontrar patuás trolls","localização da aldeia dos pelocardo"}}},fx={["24ae2c07"]={q="De que lado está Mitsuwa?",a="Mitsuwa é leal à Horda e reside entre seus semelhantes no Assentamento Zoram'gar, ao longo da costa de Vale Gris. Ele trabalha em estreita colaboração com outros viajantes da Horda e busca aventureiros da Horda para vingar os camaradas caídos.",al={"facção de mitsuwa","mitsuwa é da horda","a quem serve mitsuwa"}},ec72a5f0={q="O que Mitsuwa quer?",a="Mitsuwa busca justiça para um grupo de outros trolls massacrados a caminho do Assentamento Zoram'gar. Os agressivos furbolgs Cardo-de-espinhos emboscaram os viajantes e roubaram seus amuletos troll sagrados, e Mitsuwa quer que essas relíquias roubadas sejam recuperadas das feras.",al={"objetivo de mitsuwa","o que mitsuwa precisa","missão de mitsuwa"}},b936450a={q="Por que Mitsuwa está aqui no Assentamento Zoram'gar?",a="Mitsuwa está posicionado no Assentamento Zoram'gar, um acampamento remoto da Horda na costa oeste de Vale Gris. De lá, ele monitora as áreas selvagens ao redor e cuida dos viajantes que enfrentam as estradas traiçoeiras através do território dos furbolgs e dos elfos noturnos.",al={"por que mitsuwa está em zoramgar","propósito de mitsuwa em vale gris","por que mitsuwa está aqui"}}},fp="7,235,23.547.0,15.220.0,51.214.0,49.215.0,29.141.0"}
P.entries["npc:monte-gazlowe"] = {n="Monte Gazlowe",s="Gasganete é o pragmático engenheiro e feitor goblin que fundou e governa a cidade portuária de Vila Catraca. Após servir como o engenheiro-chefe da Horda durante a fundação de Durotar e Orgrimmar, ele usou seus ganhos substanciais para construir um movimentado entreposto comercial neutro para o Cartel Bondebico.",h="Gasganete é o pragmático engenheiro e feitor goblin que fundou e governa a cidade portuária de Vila Catraca.",kw={"sertões","durotar","freebooters","gasganete","monte","orgrimmar","pozzik","vila catraca","bondebico"},ang={["faction:Alliance"]="Gasganete não se importa com quem se senta no trono de Ventobravo ou quais desavenças você traz dos Reinos do Leste; contanto que seu ouro seja real e sua lâmina permaneça na bainha, Vila Catraca recebe você.",["faction:Horde"]="Embora exija suas moedas como qualquer bom goblin, Gasganete tem sido um aliado inabalável de Thrall desde que a poeira baixou após a Third War, tendo ajudado a cavar as próprias fundações da sua capital.",["profession:Engineering"]="Gasganete é uma das mentes mais brilhantes da engenharia goblin em Kalimdor, coordenando desde redes de abastecimento de água de cidades até veículos de corrida de alta velocidade no Circuito da Ilusão.",["race:Orc"]="Os orcs devem seu abastecimento de água em Orgrimmar diretamente aos sapadores de Gasganete, e ele ainda mantém seus mecânicos goblins em Durotar para ajudar nas construções pesadas."},sec={{t="O Cérebro de Vila Catraca",b="Após garantir um belo pagamento por seu trabalho de engenharia com a New Horde, Gasganete investiu diretamente na costa árida, fundando o porto de Vila Catraca. Operando sob o Cartel Bondebico, ele comanda a cidade portuária como um porto estritamente neutro, onde comerciantes da Horda, da Aliança e independentes podem negociar livremente — desde que mantenham suas armas embainhadas e suas bolsas pesadas."},{t="Engenheiro da Horda",b="Após a Third War, o Chefe de Guerra Thrall contratou Gasganete como engenheiro-chefe de Durotar para resolver desafios críticos de infraestrutura para a nascente capital orc. Gasganete assumiu o perigoso trabalho de garantir o abastecimento de água potável para Orgrimmar, cavando extensos túneis que inadvertidamente romperam tocas subterrâneas de kobolds. Com a ajuda oportuna do mestre das feras errante Rexxar, Gasganete conseguiu detonar as cavernas para fechá-las e concluir suas tarefas. Ele continua sendo um prestador de serviços favorito e amigo de Thrall, inclusive enviando seu próprio feitor, Rezlak, para continuar ajudando nos esforços de construção dos orcs por toda Durotar."},{t="Problemas na Costa dos Mercadores",b="Embora os negócios em Vila Catraca sejam lucrativos, Gasganete enfrenta constantes dores de cabeça devido à concorrência marítima e aos roubos. Os Southsea Freebooters estabeleceram acampamentos ao longo da vizinha Costa dos Mercadores, interceptando cargas destinadas a Vila Catraca e roubando de tudo, desde minério bruto até as botas sob encomenda de Gasganete. Para proteger seus lucros, o chefe do porto frequentemente contrata mercenários de passagem de qualquer lealdade para limpar acampamentos piratas, recuperar carregamentos roubados e acertar contas com baderneiros das docas."}},faq={{q="Quem é Gasganete?",a="Gasganete é o chefe goblin e feitor de Vila Catraca, o principal porto comercial na costa dos Sertões. Ele fez fortuna como o engenheiro-chefe que supervisionou a construção de Orgrimmar antes de estabelecer Vila Catraca como um porto aberto e neutro sob o Cartel Bondebico.",al={"quem é monte gazlowe","história de gasganete","chefe de vila catraca"}},{q="Gasganete é leal à Horda ou à Aliança?",a="Oficialmente, Gasganete é totalmente neutro, operando Vila Catraca sob o Cartel Bondebico e abrindo suas docas para viajantes tanto da Aliança quanto da Horda. No entanto, ele compartilha um vínculo pessoal próximo e uma história lucrativa com o Chefe de Guerra Thrall, tendo projetado pessoalmente partes essenciais dos assentamentos de Durotar.",al={"gasganete é da horda","vila catraca é neutra","facção de gasganete"}},{q="O que Gasganete construiu em Durotar?",a="Durante a fundação de Durotar, o Chefe de Guerra Thrall contratou Gasganete como seu engenheiro-chefe. Gasganete supervisionou as expedições de escavação de túneis para localizar um reservatório subterrâneo de água para Orgrimmar. Quando os mineradores libertaram acidentalmente um enxame de kobolds hostis, Gasganete contratou Rexxar para ajudar os sapadores a selar os túneis.",al={"gasganete orgrimmar","gasganete thal","abastecimento de água de gasganete"}},{q="Por que Gasganete está contratando aventureiros em Vila Catraca?",a="Gasganete frequentemente precisa de força bruta particular para lidar com os Southsea Freebooters, que acamparam ao longo da Costa dos Mercadores e saqueiam rotineiramente cargas destinadas às docas de Vila Catraca. Ele paga caçadores de recompensas para eliminar os piratas, recuperar manifestos de carga roubados e resgatar remessas desaparecidas.",al={"missões de gasganete","southsea freebooters vila catraca","problemas de gasganete"}},{q="Qual é a ligação de Gasganete com o Circuito da Ilusão?",a="Gasganete é um ávido entusiasta de engenharia e velocidade. Ele patrocina equipes goblins que competem contra gnomos na Chapada Cintilante de Mil Agulhas, tendo ajudado a construir o veículo de corrida deles e tentando obter protótipos de reguladores de combustível.",al={"gasganete chapada cintilante","gasganete mil agulhas","corridas de gasganete"}}},fx={cabfa558={q="Por que Gasganete está em Vila Catraca?",a="Após ganhar uma fortuna ajudando Thrall a construir Orgrimmar, Gasganete investiu seus lucros na fundação de Vila Catraca. Situada na foz do Rio Furiaustral, na costa dos Sertões, ela serve como o principal porto comercial neutro em Kalimdor para o Cartel Bondebico, permitindo que ele supervisione o comércio marítimo, empreendimentos de engenharia regionais e contratos lucrativos por todo o continente.",al={"por que gasganete veio para vila catraca","por que gasganete está aqui","propósito de gasganete em vila catraca"}},["0afdf6f5"]={q="Quem são os principais aliados e parceiros comerciais de Gasganete?",a="Gasganete mantém laços estreitos com o Chefe de Guerra Thrall e a Horda, tendo servido como engenheiro-chefe durante a fundação de Durotar. Dentro do Cartel Bondebico, ele lida com o Barão Rezingada de Angra do Butim. Ele também patrocina a equipe de corrida de goblins no Circuito da Ilusão, na Chapada Cintilante.",al={"aliados de gasganete","a quem gasganete está ligado","conexões de gasganete","parceiros de gasganete"}}},fp="13,298,25.387.0,22.613.0,29.508.0,15.275.0,46.298.0,34.309.0,45.286.0,51.236.0"}
P.entries["npc:moon-priestess-amara"] = {n="Sacerdotisa da Lua Amara",s="A Sacerdotisa da Lua Amara é uma sacerdotisa elfa noturna posicionada ao longo da estrada principal a oeste de Dolanaar, em Teldrassil. Flanqueada por leais guardas caçadoras, ela vigia as trilhas arborizadas que conectam o coração dos galhos à capital, Darnassus.",h="A Sacerdotisa da Lua Amara é uma sacerdotisa elfa noturna posicionada ao longo da estrada principal a oeste...",kw={"amara nightwalker","dolanaar","elanaria","sacerdotisa da lua amara","nhemai","teldrassil","a estrada para darnassus","yaeliura"},ang={["class:Priest"]="Como membra da Irmandade de Eluna, a Sacerdotisa Amara personifica a devoção dos elfos noturnos à Deusa da Lua, servindo como guia pastoral e espiritual para jovens acólitos que se aventuram para fora de Umbravale.",["race:NightElf"]="Amara marca um marco importante em sua jornada ao deixar Dolanaar, oferecendo orientação e tarefas que conduzem à grande cidade de Darnassus."},sec={{t="Guardiã dos Caminhos dos Galhos",b="Posicionada em um posto tranquilo à beira do caminho a oeste de Dolanaar, a Sacerdotisa da Lua Amara representa tanto a autoridade espiritual da Irmandade de Eluna quanto a vigilância prática necessária para manter seguras as estradas de Teldrassil. Ela viaja e vigia com duas companheiras caçadoras, Nhemai e Yaeliura. Para os viajantes que seguem rumo ao oeste, Amara atua como um guia, direcionando aventureiros ao longo da estrada em direção a Darnassus e incumbindo aqueles de espírito sobrecarregado a buscar caminhos de redenção."}},faq={{q="Quem é a Sacerdotisa da Lua Amara?",a="A Sacerdotisa da Lua Amara, também conhecida em deveres de sentinela como Amara Nightwalker, é uma sacerdotisa da Irmandade de Eluna posicionada na estrada entre Dolanaar e Darnassus, em Teldrassil. Ela supervisiona a segurança e a saúde espiritual dos viajantes que cruzam o grande galho.",al={"quem é amara","sacerdotisa amara","sentinela amara nightwalker"}},{q="Onde posso encontrar a Sacerdotisa da Lua Amara?",a="Ela está localizada ao longo da estrada pavimentada logo a oeste de Dolanaar, em Teldrassil, vigiando ao lado de duas sentinelas caçadoras.",al={"onde fica amara","localização de amara","mapa da sacerdotisa amara"}},{q="Quem são as caçadoras que estão com ela?",a="Ela é guardada e acompanhada pela Caçadora Nhemai e pela Caçadora Yaeliura, duas sentinelas elfas noturnas que ajudam a proteger a via contra feras e corrupção hostil.",al={"companheiras de amara","nhemai e yaeliura","guardas de amara"}}},fx={["3d569ab2"]={q="De que lado está a Sacerdotisa da Lua Amara?",a="A Sacerdotisa da Lua Amara serve ao Sacerdócio de Eluna e à Aliança, vigiando os ramos sagrados de Teldrassil. Ao lado de suas companheiras Sentinelas, ela dedica-se a guiar os viajantes e defender o coração dos kaldorei da corrupção que ameaça suas florestas tranquilas.",al={"facção de amara","lealdade de amara","a quem serve amara"}},["75dde252"]={q="Por que a Sacerdotisa da Lua Amara está posicionada aqui?",a="Amara está posicionada ao longo da estrada principal a oeste de Dolanaar para proteger os viajantes que fazem a jornada em direção a Darnassus. Os caminhos de Teldrassil estão cada vez mais cercados por feras corrompidas e timberlings à espreita, tornando sua presença vital para manter os caminhos da floresta seguros.",al={"por que amara está aqui","propósito da localização de amara","por que a sacerdotisa da lua amara está na estrada"}},["74974fcb"]={q="O que a Sacerdotisa da Lua Amara quer?",a="Ela procura aventureiros capazes para ajudar a proteger a estrada para a capital, Darnassus. Amara encarrega os viajantes de eliminar os vis furbolgs Gnarlpine e as criaturas ferozes da floresta que perturbam aqueles que viajam para o oeste sob os ramos da Árvore do Mundo.",al={"o que amara precisa","motivo da missão de amara","por que amara envia você em missões"}}},fp="20,252,25.480.0,28.270.0,38.122.0,41.174.0"}
P.entries["npc:mor-rogal"] = {n="Mor'rogal",s="Mor'rogal é um tauren residente do Retiro Rocha do Sol, na Cordilheira das Torres de Pedra. Ele serve como conselheiro e guia para viajantes que buscam glória e perigo nas profundezas subterrâneas acidentadas dos rochedos.",h="Mor'rogal é um tauren residente do Retiro Rocha do Sol, na Cordilheira das Torres de Pedra.",kw={"ravina da avalanche","o terrano se ergue","mor'rogal","morrogal","cordilheira das torres de pedra","retiro rocha do sol","tauren"},ang={["faction:Horde"]="Para viajantes que chegam ao refúgio do Retiro Rocha do Sol, Mor'rogal fornece informações cruciais sobre as ameaças que espreitam nos rochedos além das fronteiras do assentamento.",["race:Tauren"]="Mor'rogal personifica o respeito tauren por testes físicos e espirituais, vendo as profundezas rochosas de Kalimdor como solo sagrado para provar o próprio valor."},sec={{t="Sentinela dos Rochedos",b="Empoleirado no refúgio do Retiro Rocha do Sol, Mor'rogal tem um interesse profundo nas fendas e cavernas que cortam a Cordilheira das Torres de Pedra. Reconhecendo que as passagens subterrâneas sinuosas da região oferecem tanto grandes riquezas quanto perigos letais, ele orienta aventureiros da Horda corajosos a investigar áreas problemáticas como a Ravina da Avalanche. Para Mor'rogal, aventurar-se nessas profundezas traiçoeiras não é apenas uma questão de sobrevivência, mas um teste de espírito para aqueles que seguem seus corações e almas em busca de glória."}},faq={{q="Quem é Mor'rogal?",a="Mor'rogal é um tauren emissor de missões que reside no Retiro Rocha do Sol, na Cordilheira das Torres de Pedra. Ele atua como um guia local, incentivando aventureiros da Horda a testar sua coragem nas cavernas e ravinas perigosas espalhadas pela cordilheira rochosa.",al={"morrogal","quem é mor'rogal","história de mor rogal"}},{q="Onde posso encontrar Mor'rogal?",a="Ele pode ser encontrado no Retiro Rocha do Sol, o posto avançado principal da Horda escondido entre os picos da parte central da Cordilheira das Torres de Pedra.",al={"localização de mor'rogal","onde está mor'rogal","local do morrogal"}},{q="Que tarefas Mor'rogal oferece?",a="Mor'rogal recruta campeões capazes para se aventurarem na caverna da Ravina da Avalanche, onde kobolds estão minerando freneticamente cristais de Resonita, e então para derrotar Goggeroc, um Terrâneo adormecido que os kobolds desenterraram.",al={"missões de mor'rogal","o que mor'rogal quer"}},{q="Por que Mor'rogal está focado em cavernas e ravinas?",a="Mor'rogal acredita que as cavernas subterrâneas perigosas de Cordilheira das Torres de Pedra guardam verdadeiras aventuras e testes de determinação espiritual, oferecendo glória e riquezas àqueles dispostos a arriscar suas vidas.",al={"por que cavernas","cavernas de mor'rogal"}}},fx={["9b06cf83"]={q="De que lado está Mor'rogal?",a="Mor'rogal está alinhado com a Horda e seus companheiros tauren. Posicionado dentro do Retiro Rocha do Sol, um posto avançado isolado da Horda nas alturas da Cordilheira das Torres de Pedra, ele oferece orientação e tarefas aos aventureiros que servem aos interesses da Horda na região.",al={"facção de mor'rogal","mor'rogal é horda ou aliança","lealdade de mor'rogal"}},["27de9984"]={q="O que Mor'rogal quer?",a="Mor'rogal procura aventureiros corajosos dispostos a enfrentar as cavernas e ravinas perigosas da Cordilheira das Torres de Pedra. Ele direciona batedores para lugares hostis como a Ravina da Avalanche, incentivando espíritos corajosos a confrontar os perigos terrestres à espreita no subsolo em troca de honra e riquezas.",al={"objetivos de mor'rogal","o que mor'rogal está fazendo","propósito das missões de mor'rogal"}}},fp="9,204,20.521.0,17.246.0,27.130.0,32.208.0,46.188.0"}
P.entries["npc:morgan-pestle"] = {n="Morgado Pilão",s="Morgado Pilão é um alquimista humano e comerciante que administra a Botica dos Pilão no Distrito Comercial de Ventobravo. Trabalhando em estreita colaboração com seu irmão Durval Pilão em Vila d'Ouro, ele cuida de suprimentos e pesquisas alquímicas para a capital.",h="Morgado Pilão é um alquimista humano e comerciante que administra a Botica dos Pilão no Distrito Comercial de...",kw={"alquimista","morgado pilão","botica dos pilão","shipment to stormwind","ventobravo","distrito comercial","durval pilão"},ang={["faction:Alliance"]="Para os aventureiros da Aliança que chegam a Ventobravo vindos de Elwynn, a loja de Morgado é uma parada essencial para necessidades alquímicas práticas e entregas urbanas locais.",["profession:Herbalism"]="Morgado depende muito de ingredientes frescos coletados pela Floresta de Elwynn e além para abastecer sua botica no Distrito Comercial."},sec={{t="O Boticário da Cidade",b="Operando a partir da Botica dos Pilão ao longo das vias movimentadas do Distrito Comercial de Ventobravo, Morgado Pilão fornece artigos alquímicos, reagentes e remédios práticos para residentes da cidade e viajantes de passagem. Enquanto seu irmão Durval mantém uma oficina na Estalagem do Leão Orgulhoso em Vila d'Ouro, Morgado mantém o comércio da família enraizado no coração da capital do reino, recebendo remessas, como as velas de seu irmão, das regiões rurais."}},faq={{q="Onde posso encontrar Morgado Pilão?",a="Morgado Pilão está localizado dentro da Botica dos Pilão, uma loja no Distrito Comercial de Ventobravo.",al={"localização de morgado pilão","onde fica morgado pilão","botica dos pilão ventobravo"}},{q="Qual é o parentesco entre Morgado Pilão e Durval Pilão?",a="Morgado e Durval Pilão são irmãos. Ambos trabalham como alquimistas em Elwynn, com Morgado administrando a loja deles em Ventobravo e Durval trabalhando em Vila d'Ouro.",al={"irmão de durval pilão","durval e morgado são parentes","irmãos pilão"}},{q="Qual papel ele desempenha nas missões de Elwynn?",a="Morgado é o destinatário da remessa de velas que seu irmão Durval envia do sul de Vila d'Ouro para a loja deles, a Botica dos Pilão, e ele paga bem o mensageiro pela entrega.",al={"shipment to stormwind morgado","missão de morgado pilão"}}},fx={["2e5b0856"]={q="Quem é Morgado Pilão?",a="Morgado Pilão é um alquimista humano e lojista que trabalha no Distrito Comercial em Ventobravo. Ele possui e administra a Boticário do Pilão, negociando reagentes, remédios e várias misturas alquímicas para os habitantes da cidade.",al={"quem é morgado pilão","história de morgado pilão","quem é pilão"}},ae642a6d={q="De que lado está Morgado Pilão?",a="Morgado Pilão é um cidadão leal da Aliança. Baseado no coração do Distrito Comercial de Ventobravo, seu comércio apoia a população local e o reino como um todo.",al={"facção de morgado pilão","morgado pilão é da aliança","lealdade de morgado pilão"}},["2ef8a55a"]={q="Por que Morgado Pilão está aqui?",a="Morgado Pilão reside em Ventobravo para gerenciar sua loja, a Botica de Pilão. Da fachada de sua loja no movimentado Distrito Comercial, ele vende poções e berloques e recebe remessas de seu irmão William, que trabalha em Vila d'Ouro.",al={"por que morgado pilão está em ventobravo","morgado pilão distrito comercial"}}},fp="13,242,19.451.0,31.100.0,47.156.0,40.181.0"}
P.entries["npc:morgan-the-collector"] = {n="Morgan, o Coletor",s="Morgan, o Coletor é um agente de alto escalão da Défias que supervisiona as atividades de extorsão e arrecadação da Irmandade por toda a Floresta de Elwynn. Estabelecido na tomada Plantação de Abóboras dos Braga, ele coordena os roubos locais bem debaixo do nariz da guarda de Vila d'Ouro.",h="Morgan, o Coletor é um agente de alto escalão da Défias que supervisiona as atividades de extorsão e...",kw={"braga","irmandade","défias","durão","manhunt","morgan","plantação de abóboras","sinete","the collector"},ang={["class:Rogue"]="Morgan demonstra como a disciplina criminosa organizada transforma ladrões desarticulados em uma camarilha clandestina funcional, capaz de financiar uma insurgência.",["race:Human"]="Eliminar Morgan é revidar contra os traidores que transformaram as pacatas fazendas de Ventobravo em covis fortificados de bandidos."},sec={{t="O Dízimo de Elwynn",b="Morgan ganhou seu epíteto desviando ouro das minas da Floresta de Elwynn em benefício da Irmandade Défias. Enquanto bandidos comuns atacam viajantes pelas estradas, Morgan comanda extorsões organizadas e recolhe moedas e suprimentos roubados para encaminhá-los para as entranhas da rede da Irmandade. Ele estabeleceu seu quartel-general dentro da casa da fazenda na Plantação de Abóboras dos Braga, cercado por executores leais, incluindo Surena Caledon e Erlan Drudgemoor."},{t="Um Sinete do Passado",b="As operações de Morgan não são apenas simples crimes de rua; ele carrega um distinto anel de sinete que atesta sua autoridade. Para os investigadores de Vila d'Ouro, esse anel oferece provas cabais que ligam os ladrões mascarados que aterrorizam o coração do reino à desgraçada Guilda dos Pedreiros, que reconstruiu Ventobravo após a Segunda Guerra. Recuperar seu anel desvenda o mistério por trás de quem realmente comanda os bandidos nos bosques."}},faq={{q="Quem é Morgan, o Coletor?",a="Ele é um oficial da Irmandade Défias responsável por recolher o ouro retirado das minas da Floresta de Elwynn e por coordenar a atividade dos bandidos na região.",al={"quem é morgan","história de morgan","coletor na floresta de elwynn"}},{q="Onde Morgan é encontrado?",a="Ele acumula seus bens roubados dentro da casa de fazenda abandonada na Plantação de Abóboras dos Braga, localizada na parte leste da Floresta de Elwynn.",al={"localização de morgan","onde fica morgan, o coletor","casa da plantação de abóboras dos braga"}},{q="Por que Ventobravo está caçando ele?",a="O Delegado Durão e as autoridades locais querem Morgan eliminado para romper a liderança Défias em Elwynn e recuperar provas de quem está organizando as revoltas rurais.",al={"por que matar morgan","alvo de manhunt"}},{q="O que o anel que ele carrega tem de especial?",a="Morgan carrega um anel de sinete que serve de prova para as autoridades que investigam suas atividades na Floresta de Elwynn.",al={"anel do coletor","anel de sinete do coletor","história do anel de morgan"}}},fx={["8321821e"]={q="De que lado está Morgan, o Coletor?",a="Morgan, o Coletor, é um agente dedicado da The Defias Brotherhood. Em vez de um simples salteador de estradas, ele serve como oficial dentro da organização criminosa, trabalhando diretamente contra o Reino de Ventobravo e orquestrando a atividade da irmandade por todo o coração da Floresta de Elwynn.",al={"facção de morgan, o coletor","de que facção é morgan","morgan é da defias"}},["5f1d52ce"]={q="O que Morgan, o Coletor, quer?",a="Morgan atua como o líder que supervisiona as operações da Defias por toda a Floresta de Elwynn. Usando a alcunha de 'o Coletor', seu objetivo é reunir riqueza, recursos e influência para o levante da Irmandade, estabelecendo um ponto de apoio fortificado na plantação de abóboras bem debaixo do nariz dos guardas de Ventobravo.",al={"o que morgan está tentando fazer","objetivo de morgan, o coletor","motivo de morgan, o coletor"}},["2a29f808"]={q="Por que Morgan, o Coletor, está na Floresta de Elwynn?",a="Morgan estabeleceu-se na Plantação de Abóboras dos Braga para dirigir pessoalmente as operações locais da The Defias Brotherhood. Ao se refugiar na casa de fazenda ao lado dos tenentes Surena Caledon e Erlan Drudgemoor, ele mantém uma coordenação rígida sobre os bandidos que se espalham por toda a região.",al={"por que morgan está na plantação de abóboras dos braga","o que trouxe morgan aqui"}},ceb85f69={q="A quem Morgan, o Coletor, está ligado?",a="Seu anel de sinete torna-se prova em uma investigação sobre os fora da lei que perturbam a Floresta de Elwynn e suas conexões.",al={"com quem morgan trabalha","associados de morgan, o coletor","morgan pedreiros"}}},fp="20,262,19.448.0,20.411.1,28.155.0,22.123.0,29.156.0,42.119.1"}
P.entries["npc:morin-cloudstalker"] = {n="Morin Espreita Nuvem",s="Morin Espreita Nuvem é um batedor tauren que vigia a estrada que leva a leste da Aldeia Casco Sangrento em direção aos Sertões em Mulgore. Em vigília pelas planícies, ele monitora as rotas comerciais locais e investiga as ameaças invasoras que colocam em risco os viajantes tauren.",h="Morin Espreita Nuvem é um batedor tauren que vigia a estrada que leva a leste da Aldeia Casco Sangrento em...",kw={"aldeia casco sangrento","grande portão","morin espreita nuvem","mulgore","caravana devastada","supervisor geringonça","empreendimentos s.a."},ang={["faction:Horde"]="Morin oferece aos campeões da Horda uma oportunidade inicial de proteger os suprimentos e as terras sagradas de seus novos aliados tauren.",["race:Tauren"]="Para os tauren que viajam para fora da Aldeia Casco Sangrento, Morin representa a defesa vigilante da sua terra natal contra bandidos oportunistas e profanadores corporativos."},sec={{t="Observador da Trilha Sul",b="Posicionado ao lado da trilha de terra que serpenteia a leste em direção aos Sertões, Morin Espreita Nuvem atua como batedor e guardião dos viajantes em Mulgore. As planícies gramadas aqui são geralmente pacíficas, mas a abertura de rotas comerciais e as mudanças territoriais atraíram oportunistas e bandidos perigosamente para perto do coração da terra natal dos tauren."},{t="Investigando a Caravana",b="Os batedores de Morin atacaram e queimaram recentemente uma caravana da Empreendimentos S.A. na margem norte do Lago da Ferradura. Quando saqueadores goblins foram vistos perto das carroças queimadas, ele enviou aventureiros para examinar os engradados de suprimentos sobreviventes e descobrir o que a Empreendimentos S.A. estava transportando."},{t="Defendendo contra a Empreendimentos S.A.",b="Além dos bandidos comuns, Morin está profundamente preocupado com a presença industrial da Empreendimentos S.A., que está estabelecendo operações em Mulgore. Ele direciona os aventureiros da Horda que passam pelo local a atacar seus postos avançados de extração de madeira e mineração, visando líderes importantes como o Supervisor Geringonça para conter a devastação ambiental que ameaça as planícies sagradas."}},faq={{q="Onde posso encontrar Morin Espreita Nuvem?",a="Morin Espreita Nuvem fica na trilha de terra a leste da Aldeia Casco Sangrento em Mulgore, ao longo da estrada que leva aos Sertões.",al={"localização de morin","onde está morin","mapa de morin espreita nuvem"}},{q="Qual é o papel de Morin em Mulgore?",a="Ele é um batedor tauren atento responsável por monitorar as viagens pelo sul de Mulgore e organizar a defesa contra bandidos e intrusos corporativos.",al={"quem é morin espreita nuvem","papel de morin"}},{q="Por que Morin está investigando a caravana arruinada?",a="Os batedores de Morin atacaram e queimaram uma caravana da Empreendimentos S.A. perto do Lago da Ferradura. Quando saqueadores goblins foram vistos em torno dos destroços, ele pediu a aventureiros que examinassem os engradados de suprimentos sobreviventes para descobrir o que a Empreendimentos S.A. estava transportando.",al={"missão caravana devastada","ataque à caravana em mulgore"}},{q="Por que Morin quer que a Empreendimentos S.A. seja parada?",a="A Empreendimentos S.A. está extraindo os recursos naturais de Mulgore com maquinário e desmatamento. Morin busca interromper o empreendimento destrutivo deles eliminando seus supervisores, incluindo o Supervisor Geringonça.",al={"empreendimentos s.a. em mulgore","por que matar geringonça"}},{q="A quem Morin se reporta?",a="Morin opera em nome dos anciões e chefes da Aldeia Casco Sangrento e da liderança tauren mais ampla em toda Mulgore.",al={"lealdade de morin","quem enviou morin"}},{q="Morin oferece missões para jogadores da Aliança?",a="Não. Morin é um PNJ leal estritamente à Horda e interagirá apenas com aventureiros da Horda.",al={"a aliança pode falar com morin","facção de morin"}}},fx={["2ee6eb23"]={q="Quem é Morin Espreita Nuvem?",a="Morin Espreita Nuvem é um batedor e protetor tauren que vigia Mulgore. Posicionado ao longo da estrada que leva ao leste da Aldeia Casco Sangrento em direção aos Sertões, ele mantém um olhar atento sobre as ameaças que surgem nas terras ancestrais dos taurens, despachando aventureiros capazes da Horda para proteger as planícies de saqueadores e exploradores.",al={"morin espreita nuvem quem é ele","quem é morin","lore de morin"}},b362fb80={q="De que lado Morin Espreita Nuvem está?",a="Morin é ferozmente leal ao Penhasco do Trovão e à Horda. Ele protege o coração do povo tauren e apenas oferece sua orientação e tarefas a viajantes da Horda dispostos a defender a frágil paz de Mulgore.",al={"facção de morin espreita nuvem","morin aliança ou horda","morin é da horda"}},["7047ff15"]={q="O que Morin Espreita Nuvem quer?",a="Morin busca proteger as estradas e os recursos naturais de Mulgore. Ele envia aventureiros para revistar a caravana da Venture Company que seus batedores queimaram e para deter as operações destrutivas da Empreendimentos S.A., exigindo particularmente o fim da mineração exploratória do Supervisor Fizsprocket nas colinas.",al={"o que morin quer","objetivos de morin","tarefas de morin"}},["9ad7af70"]={q="Por que Morin Espreita Nuvem está posicionado aqui?",a="Morin está posicionado ao longo da estrada a leste da Aldeia Casco Sangrento para vigiar o tráfego em Mulgore. Este entroncamento crítico permite que ele monitore caravanas viajantes e intercepte perigos iminentes — como os profanadores da Empreendimentos S.A. — antes que cheguem à Aldeia Casco Sangrento.",al={"por que morin está aqui","por que morin está na estrada","razão da localização de morin"}}},fp="18,266,29.343.0,25.268.0,29.346.1,36.128.0,32.152.0,46.232.0,48.212.0,25.124.0,44.94.0"}
P.entries["npc:motega-firemane"] = {n="Motega Firemane",s="Motega Firemane é um erudito tauren baseado no Posto Confinalvo, em Mil Agulhas. Dedicado a catalogar a perigosa vida selvagem do desfiladeiro, ele vê seus estudos perturbados por um vingativo espírito de serpente alada e pelas imprudentes desventuras de seu jovem assistente.",h="Motega Firemane é um erudito tauren baseado no Posto Confinalvo, em Mil Agulhas.",kw={"arikara","caerne casco sangrento","kanati greycloud","magatha temível totem","motega firemane","pao'ka swiftmountain","mil agulhas","posto confinalvo"},ang={["class:Hunter"]="Caçadores encontram pontos em comum com Motega, que conta com rastreadores habilidosos para colher a flora do desfiladeiro, rastrear mantícoras em Alcândora e espreitar o poderoso espírito Arikara.",["faction:Horde"]="Motega representa a expansão da Horda pelas regiões indomadas de Kalimdor, mantendo um posto de pesquisa precário enquanto protege o Grande Chefe Caerne Casco Sangrento de ameaças espirituais.",["race:Tauren"]="Por meio de sua reverência pela natureza e de sua leal devoção a Caerne Casco Sangrento, Motega personifica o ethos tauren de estudar as criaturas da Mãe Terra enquanto defende a tribo contra espíritos ancestrais."},sec={{t="Erudito dos Desfiladeiros",b="Quatro anos após a Terceira Guerra, Motega Firemane viajou para o sul até Mil Agulhas para observar e registrar as feras distintas que sobreviviam entre os altos platôs. Acompanhado por seu jovem assistente, Pao'ka Swiftmountain — cujo pai protetor relutava em deixá-lo sair de Mulgore —, Motega montou acampamento ao lado de Kanati Greycloud no Posto Confinalvo. Embora sua vocação original fosse a tranquila observação natural, os perigos implacáveis do fundo do desfiladeiro exigem continuamente uma abordagem mais marcial para a sobrevivência."},{t="A Ira de Arikara",b="A pacífica pesquisa de Motega foi virada do avesso quando chegou a notícia da Aldeia Vento Livre de que Arikara, um feroz e lendário espírito de serpente alada, havia retornado aos desfiladeiros em busca de vingança contra Caerne Casco Sangrento. Perplexo sobre o porquê de tal criatura ter uma rixa contra o Grande Chefe, Motega agiu com rapidez para proteger a Horda. Ele instruiu batedores a colher agave Incendia da bacia do desfiladeiro e levá-lo à Anciã Magatha Temível Totem no Penhasco do Trovão para ser encantado e transformado em um pó sagrado. Usando essa preparação, caçadores invocaram e abateram o espírito da serpente, retornando sua pele ao Posto Confinalvo como prova de que Caerne estava a salvo."},{t="Guardião de Confinalvo",b="Arikara não foi o único perigo a desafiar a estada de Motega no Posto Confinalvo. Centauros Galak locais sondavam continuamente o acampamento, planejando até mesmo um plano de assassinato contra Kanati Greycloud e seus seguidores. Para piorar a situação, o jovem Pao'ka se afastou da segurança da fogueira e desapareceu nas alturas infestadas de mantícoras de Alcândora. Embora frustrado com a insensatez do jovem bravo, Motega ficou imensamente aliviado quando viajantes da Horda escoltaram o jovem de volta com vida."}},faq={{q="Quem é Motega Firemane?",a="Motega Firemane é um pesquisador tauren baseado no Posto Confinalvo, em Mil Agulhas. Ele foi aos desfiladeiros para estudar a vida selvagem local ao lado de outros bravos e de seu assistente, Pao'ka Swiftmountain.",al={"história de motega firemane","quem é motega","motega de confinalvo"}},{q="Onde Motega Firemane pode ser encontrado?",a="Ele está localizado no Posto Confinalvo, um pequeno acampamento da Horda em Mil Agulhas, ao longo da estrada no noroeste da zona, perto da Aldeia E'thok.",al={"localização de motega","onde fica motega firemane","mapa de motega firemane"}},{q="Por que Motega está preocupado com Arikara?",a="Arikara é um espírito de serpente vingativo que se manifestou em Mil Agulhas visando Caerne Casco Sangrento. Embora perplexo quanto ao motivo de o espírito guardar rancor contra o Grande Chefe, Motega leva a ameaça a sério e orienta caçadores a invocar e eliminar a criatura.",al={"quem é arikara","por que matar arikara","arikara cairne"}},{q="Qual é o papel de Magatha Temível Totem nos planos de Motega?",a="Motega incumbe aventureiros de coletar agave Incendia e levá-lo a Magatha Temível Totem no Platô dos Anciãos, no Penhasco do Trovão. Magatha usa seu conhecimento xamânico para encantar a planta e transformá-la em um pó sagrado capaz de invocar a evasiva Arikara.",al={"pó de incendia de magatha","motega e magatha","história da missão sacred fire"}},{q="O que aconteceu com o companheiro de Motega, Pao'ka?",a="Pao'ka Swiftmountain desviou-se para os perigosos ninhos de mantícoras de Alcândora e se perdeu. Motega ficou ansioso quanto ao destino do jovem, especialmente devido à relutância que o pai de Pao'ka tivera em permitir a viagem, mas viajantes o escoltaram com sucesso de volta ao Posto Confinalvo.",al={"pao'ka swiftmountain","tauren desaparecido em alcândora","missão homeward bound"}},{q="Quais outros perigos o Posto Confinalvo enfrenta?",a="Além de predadores e espíritos desgarrados, o acampamento é ativamente visado pelos centauros Galak das proximidades, que organizam emboscadas e tramam assassinatos contra Kanati Greycloud e os outros taurens estacionados no posto.",al={"ameaças ao posto confinalvo","centauros no posto confinalvo","complô dos centauros galak"}}},fx={ca68f68f={q="De que lado Motega Firemane está?",a="Motega Firemane é leal aos taurens e à Horda. Posicionado no Posto Confinalvo ao lado de Kanati Greycloud, ele coopera estreitamente com viajantes da Horda e zela pelos interesses de Caerne Casco Sangrento e das tribos sob a bandeira do Penhasco do Trovão.",al={"facção de motega firemane","motega firemane horda ou aliança","motega é da horda"}},["8b7dc2d8"]={q="O que Motega Firemane quer?",a="Motega está focado principalmente no estudo da vida selvagem única das Mil Agulhas, enquanto mantém um olho em seu jovem companheiro, Pao'ka Swiftmountain. No entanto, ameaças ao Penhasco do Trovão rapidamente se tornam prioridade. Quando avisado sobre a vingativa serpente do vento Arikara, ele busca invocar e destruir a besta antes que ela possa colocar Caerne Casco Sangrento em perigo.",al={"o que motega quer","objetivos de motega firemane","o que motega está tentando fazer"}},["12cba981"]={q="Por que Motega Firemane está aqui?",a="Motega viajou para as Mil Agulhas para observar e estudar as bestas exóticas nativas do chão do cânion e das mesas ao redor. O Posto Confinalvo serve como um acampamento base para sua pesquisa, embora problemas locais — de companheiros perdidos a serpentes míticas ameaçadoras — muitas vezes o afastem de suas atividades acadêmicas.",al={"por que motega está nas mil agulhas","o que trouxe motega ao posto confinalvo","propósito de motega firemane"}}},fp="15,267,22.511.0,20.632.1,22.483.1,23.204.0,35.140.0,38.275.1,56.248.1,44.276.1,45.212.0"}
P.entries["npc:mountaineer-barleybrew"] = {n="Montanhista Cervevada",s="O Montanhista Cervevada é um montanhista de Altaforja destacado no Posto de Guarda do Portão Sul em Dun Morogh. Guardando a passagem que segue a leste em direção a Loch Modan, ele conta com as encorpadas bebidas anãs para manter as sentinelas alertas no frio cortante.",h="O Montanhista Cervevada é um montanhista de Altaforja destacado no Posto de Guarda do Portão Sul em Dun...",kw={"cervevada","dun morogh","montanhista","cerveja tremeluz","posto de guarda do portão sul","wellart"},ang={["race:Dwarf"]="Para os anões, Cervevada personifica o equilíbrio essencial entre o dever de fronteira e o alívio de alto teor alcoólico que mantém Khaz Modan segura."},sec={{t="Uma Vigília na Passagem Oriental",b="Posicionado no Posto de Guarda do Portão Sul, vigiando a estrada nevada em direção a Loch Modan, o Montanhista Wellart Cervevada atua como parte da vigilância de fronteira de Altaforja. Como muitos montanhistas que servem sob os ventos gélidos de Dun Morogh, ele aprecia as qualidades revigorantes de uma boa bebida anã. Carregando o nome do renomado clã Cervevada, ele ajuda a garantir que carregamentos da potente Cerveja Tremeluz cheguem aos companheiros de vigia que precisam de calor e vigor durante os longos turnos pelas passagens da montanha."}},faq={{q="Onde posso encontrar o Montanhista Cervevada?",a="O Montanhista Cervevada está destacado no Posto de Guarda do Portão Sul, a fortificação anã que protege a passagem oriental entre Dun Morogh e Loch Modan.",al={"localização do cervevada","onde fica o montanhista cervevada","npc cervevada"}},{q="Qual é a função dele no Posto de Guarda do Portão Sul?",a="Ele atua como sentinela da montanha protegendo a estrada e ajuda a coordenar suprimentos, incluindo a Cerveja Tremeluz para os companheiros montanhistas posicionados pelas passagens.",al={"função do cervevada","o que o cervevada faz"}},{q="Ele é parente dos outros Cervevadas?",a="Sim. Seu irmão é o mestre-cervejeiro Rejold Cervevada, e ele também pode ser parente de Marleth, Malgin e Yorus Cervevada.",al={"família cervevada","parente de yorus cervevada"}}},fx={["583559ff"]={q="Quem é o Montanhista Cervevada?",a="O Montanhista Wellart Cervevada é um sentinela anão posicionado para defender as fronteiras orientais de Dun Morogh. Como todos os montanhistas de Altaforja, ele permanece vigilante contra as bestas, troggs e saqueadores trolls de gelo que ameaçam as estradas da montanha, equilibrando seu rigoroso dever de fronteira com uma distinta predileção anã por uma boa cerveja.",al={"quem é o montanhista cervevada","quem é cervevada","lore do montanhista cervevada"}},["399d0350"]={q="De que lado o Montanhista Cervevada está?",a="Ele é um soldado fiel de Altaforja e leal à Aliança. Ele segue os comandos do clã Barbabronze e do Rei Magni Barbabronze, garantindo a segurança dos viajantes e dos principais desfiladeiros da montanha em todo o reino.",al={"facção do montanhista cervevada","a quem cervevada serve","cervevada é da aliança"}},fc186c57={q="O que o Montanhista Cervevada quer?",a="Além de manter a estrada protegida de intrusos, o Montanhista Cervevada aprecia uma bebida forte para enfrentar o ar gelado da montanha. Ele depende de viajantes que passam para levar notícias e suprimentos — incluindo um gole de uma potente Shimmer Stout — entre seu posto e aliados próximos.",al={"o que cervevada quer","o que o wellart cervevada precisa","o que cervevada está procurando"}},b2269341={q="Por que o Montanhista Cervevada está aqui?",a="Ele está postado ao longo do desfiladeiro do Posto de Guarda do Portão Sul para vigiar a via essencial que conecta Dun Morogh a Loch Modan. As passagens altas enfrentam perigo constante de vida selvagem errante e bandos de guerra de troggs agressivos, exigindo montanhistas disciplinados para manter os portões fortificados e seguros.",al={"por que cervevada está no portão sul","por que o montanhista cervevada está posicionado aqui","razão da localização de cervevada"}}},fp="22,232,27.499.0,40.145.0,39.165.0,39.118.0"}
P.entries["npc:mountaineer-kadrell"] = {n="Montanhista Kadrell",s="O Montanhista Kadrell é uma sentinela anã convicta posicionada em frente à Estalagem Pilsen, em Thelsamar. Atuando como uma ligação crucial dentro dos Montanhistas de Loch Modan, ele coordena o reconhecimento, as entregas de suprimentos e a defesa das fronteiras em toda a região.",h="O Montanhista Kadrell é uma sentinela anã convicta posicionada em frente à Estalagem Pilsen, em Thelsamar.",kw={"kadrell","loch modan","montanhista","rochapeixe","lançatroz","estalagem pilsen","thelsamar"},ang={["faction:Alliance"]="Kadrell conta com viajantes da Aliança que passam por Thelsamar para levar mensagens e ajudar postos avançados de montanhistas distantes que lutam contra as ameaças regionais.",["race:Dwarf"]="Como parte da renomada corporação de Montanhistas, Kadrell representa a guarda da linha de frente que mantém os territórios orientais de Altaforja a salvo dos perigos iminentes da natureza selvagem."},sec={{t="A Sentinela de Thelsamar",b="Montando guarda no movimentado assentamento de Thelsamar, o Montanhista Kadrell serve como um pilar para as defesas dos anões por todo Loch Modan. Enquanto postos avançados nas margens do vale enfrentam pressão constante de troggs, gnolls e feras nativas, Kadrell permanece no centro da cidade para organizar reforços, transmitir ordens e avaliar os relatórios de campo recebidos de batedores itinerantes."},{t="Mantendo as Linhas Abertas",b="Os deveres de Kadrell frequentemente envolvem manter contato entre Thelsamar e posições avançadas remotas. Seja coordenando com o Montanhista Lançatroz ou enviando aventureiros para se reportarem a sentinelas como o Montanhista Rochapeixe, Kadrell garante que os postos avançados isolados que guardam as passagens das montanhas recebam suprimentos vitais, reforços e informações defensivas cruciais."}},faq={{q="Onde o Montanhista Kadrell pode ser encontrado?",a="Kadrell está posicionado bem do outro lado da estrada em frente à Estalagem Pilsen, na cidade de Thelsamar, situada entre as colinas ondulantes de Loch Modan.",al={"localização de kadrell","onde fica kadrell","encontrar kadrell"}},{q="Qual é a função de Kadrell em Loch Modan?",a="Ele é um membro dos Montanhistas anões encarregado de fazer a ponte entre a liderança local de Thelsamar e os postos de guarda remotos espalhados pela região, coordenando patrulhas, suprimentos e relatórios fronteiriços.",al={"o que kadrell faz","propósito de kadrell","função de kadrell"}},{q="Por que outros montanhistas enviam mensageiros a Kadrell?",a="Devido à sua posição central logo ao lado da estalagem e da via principal de Thelsamar, Kadrell serve como o ponto central para comunicados de campo, garantindo que relatórios urgentes de batedores distantes cheguem à rede de defesa do assentamento.",al={"reportar a kadrell","por que reportar a kadrell"}},{q="Com quem Kadrell se coordena?",a="Kadrell trabalha frequentemente com outros montanhistas em campo, incluindo o Montanhista Lançatroz e o Montanhista Rochapeixe, gerenciando atualizações de reconhecimento e missões de defesa contra ameaças locais.",al={"contatos de kadrell","quem kadrell conhece"}}},fx={fc9aa592={q="Quem é o Montanhista Kadrell?",a="O Montanhista Kadrell é um defensor anão posicionado em Thelsamar. Como membro dos Montanhistas, a guarda territorial dedicada de Altaforja, ele ajuda a supervisionar a defesa da região de Loch Modan, organizando esforços locais de batedores e mantendo as linhas de suprimento e postos avançados seguros.",al={"quem é kadrell","montanhista kadrell","identidade de kadrell"}},["24c7e32d"]={q="De que lado o Montanhista Kadrell está?",a="Kadrell está firmemente ao lado do Reino de Altaforja e da Aliança. Seus deveres o colocam a serviço do Rei Magni Barbabronze, trabalhando ao lado de outros montanhistas, marechais da cidade e anões locais para manter as fronteiras de Khaz Modan contra ameaças iminentes.",al={"facção de kadrell","kadrell é da aliança","lealdade de kadrell"}},["56ea1ebe"]={q="Por que o Montanhista Kadrell está em Thelsamar?",a="Kadrell está posicionado diretamente em frente à Estalagem Pilsen para atuar como um ponto de contato central em Thelsamar. Como a cidade é o principal centro de Loch Modan, permanecer aqui permite que ele receba relatórios de postos de guarda remotos e despache viajantes para onde a ajuda é mais necessária.",al={"por que kadrell está em thelsamar","por que kadrell está aqui","posto de kadrell"}},f9923f59={q="Com quem o Montanhista Kadrell está ligado?",a="Kadrell está intimamente conectado à rede de Montanhistas de Altaforja que patrulham o vale, incluindo o Montanhista Lançatroz e o Montanhista Rochapeixe. Ele coordena com batedores de postos avançados por todo Loch Modan para canalizar informações e reforços sempre que as estações de fronteira estão sob pressão.",al={"conexões de kadrell","com quem kadrell trabalha","laços de kadrell"}}},fp="19,256,23.378.0,22.362.0,39.143.0,37.208.0,50.221.0,33.192.0"}
P.entries["npc:mountaineer-stormpike"] = {n="Montanhista Lançatroz",s="O Montanhista Lançatroz é um montanhista de Altaforja alocado na Estação Algaz, no norte de Loch Modan. Vigiando o desfiladeiro que leva aos Pantanais, ele trabalha incansavelmente para manter rotas de suprimentos vitais a salvo de troggs e kobolds à espreita. Como um orgulhoso membro do clã Lançatroz, sua lealdade repousa firmemente com Altaforja e a segurança das terras dos anões.",h="O Montanhista Lançatroz é um montanhista de Altaforja alocado na Estação Algaz, no norte de Loch Modan.",kw={"algaz","dun","kobold","loch","modan","montanhista","estação","lançatroz","pantanais"},ang={["faction:Alliance"]="A Estação Algaz ancora a principal via terrestre que liga Altaforja ao Porto de Menethil nos Pantanais, tornando a vigilância de Lançatroz essencial para a logística da Aliança.",["race:Dwarf"]="Para um anão de Altaforja, ajudar um colega montanhista como Lançatroz é um dever honrado para proteger as fronteiras interiores de Khaz Modan de pestes saqueadoras."},sec={{t="Guardião da Estação Algaz",b="Erguida ao longo da fronteira norte de Loch Modan, a Estação Algaz serve como um posto de controle crucial antes da descida perigosa para os Pantanais. O Montanhista Lançatroz está estacionado aqui, em meio a penhascos rochosos e constantes ameaças selvagens. Seu principal dever é manter a linha de comunicação e manter as estradas abertas para viajantes e comboios de suprimentos que atravessam Dun Algaz."},{t="Enfrentando Ameaças Locais",b="Os confins ao norte de Loch Modan são atormentados por pragas implacáveis, desde kobolds infestando escavações próximas até troggs subterrâneos. Lançatroz recruta rotineiramente aventureiros que passam pelo local para deter essas ameaças, tendo como alvo principalmente os kobolds que ocuparam a Mina da Prata e puseram suas patas nojentas nas ferramentas dos anões estocadas pela Miners' League."}},faq={{q="Onde posso encontrar o Montanhista Lançatroz?",a="Ele está estacionado na Estação Algaz, situada no norte de Loch Modan ao longo da estrada de montanha que segue para o norte em direção ao desfiladeiro de Dun Algaz e aos Pantanais.",al={"localização lançatroz","onde fica lançatroz","localização montanhista lançatroz"}},{q="Quem é o Montanhista Lançatroz?",a="Ele é um montanhista de Altaforja pertencente ao renomado clã Lançatroz. Atua como sentinela de posto avançado e batedor, encarregado de proteger o desfiladeiro ao norte de Loch Modan contra os perigos dos ermos ao redor.",al={"quem é lançatroz","história montanhista lançatroz","quem é o montanhista lançatroz"}},{q="Quais ameaças ele enfrenta na Estação Algaz?",a="O posto avançado enfrenta problemas frequentes com incursões de troggs e kobolds infestando as encostas e pedreiras. Lançatroz trabalha para eliminar essas ameaças para que linhas de mensageiros e caravanas possam passar em segurança.",al={"perigos na estação algaz","o que está atacando a estação algaz","ameaças ao norte de loch modan"}},{q="Qual é a finalidade da Estação Algaz?",a="A Estação Algaz atua como um posto avançado de Altaforja que monitora a fronteira entre Loch Modan e os túneis acidentados de Dun Algaz. Ela serve como ponto de apoio para montanhistas patrulhando a fronteira e mantendo a estrada de comércio desimpedida.",al={"o que é a estação algaz","história da estação algaz","objetivo da estação algaz"}},{q="Ele tem relação com a Guarda de Lançatroz no Vale Alterac?",a="Ele carrega o nome do proeminente clã Lançatroz, uma linhagem de anões bastante conhecida em Altaforja por seus guerreiros e prospectores ferozes, embora suas ordens imediatas o mantenham mobilizado ao longo dos desfiladeiros de Loch Modan.",al={"lançatroz alterac","ligação com o clã lançatroz","ele faz parte da guarda de lançatroz"}},{q="Quais tarefas o Montanhista Lançatroz passa para os aventureiros?",a="Ele orienta os aventureiros a recuperar os equipamentos da Miners' League na Mina da Prata, tomada por kobolds, e a levar seu pedido de um novo escudo até o armeiro anão Furen Barbalonga em Ventobravo.",al={"missões de lançatroz","tarefas do montanhista lançatroz","missão patas nojentas"}}},fx={["21d9c7b3"]={q="De que lado o Montanhista Lançatroz está?",a="O Montanhista Lançatroz é ferozmente leal a Altaforja e ao clã Barbabronze, servindo como um orgulhoso membro dos Montanhistas anões. Ele guarda o desfiladeiro da montanha em nome do Rei Magni Barbabronze e está firmemente ao lado da Aliança, nutrindo profunda desconfiança em relação ao clã Ferro Negro.",al={"facção do montanhista lançatroz","a quem o montanhista lançatroz serve","lealdade de lançatroz"}},["1b65a761"]={q="O que o Montanhista Lançatroz quer?",a="Posicionado ao longo da estrada norte acidentada, Lançatroz quer manter o desfiladeiro seguro de troggs, kobolds e outras ameaças que descem das colinas. Ele procura mensageiros confiáveis e combatentes capazes para realizar entregas, eliminar pragas invasoras e manter as comunicações entre a Estação Algaz e o restante de Loch Modan.",al={"o que lançatroz quer","objetivo de lançatroz","propósito do montanhista lançatroz"}},["60d9a34d"]={q="Por que o Montanhista Lançatroz está aqui na Estação Algaz?",a="A Estação Algaz guarda a rota norte vital que conecta Loch Modan ao Pantanal. Lançatroz está posicionado aqui para vigiar o desfiladeiro, coordenar patrulhas e garantir que suprimentos e relatórios circulem com segurança entre os postos avançados de montanha espalhados e a rede de defesa mais ampla de Altaforja.",al={"por que o montanhista lançatroz está aqui","por que lançatroz está na estação algaz","razão da localização de lançatroz"}}},fp="21,362,25.379.0,29.350.0,39.151.0,29.207.0,48.204.0,32.221.0,55.217.0,58.211.0"}
P.entries["npc:mountaineer-thalos"] = {n="Montanhista Thalos",s="O Montanhista Thalos é um sentinela anão posicionado na entrada do Vale Cristálgida no Caminho de Cristálgida. Incumbido de proteger a rota, ele alerta os viajantes sobre a repentina infestação de troggs que está bloqueando o túnel. Aventureiros que transportam relatórios urgentes do vale dependem dele para indicar o caminho seguro em direção a Kharanos.",h="O Montanhista Thalos é um sentinela anão posicionado na entrada do Vale Cristálgida no Caminho de Cristálgida.",kw={"caminho de cristálgida","vale cristálgida","dun morogh","montanhista de altaforja","kharanos","montanhista thalos","senir barbabranca","troggs"},ang={["faction:Alliance"]="Thalos mantém a comunicação ao longo do canal vital da montanha que liga as forças defensivas do vale ao comando central de Altaforja.",["race:Dwarf"]="Para os jovens anões que deixam o berço de sua terra natal, Thalos é o lembrete solene de que a ameaça trogg não é um mero exercício de treinamento, mas sim um cerco que pressiona duramente os limites de Altaforja.",["race:Gnome"]="Gnomos que partem dos abrigos de refugiados de Gnomeregan encontram Thalos montando guarda ao longo da principal rota terrestre que desce em direção a Kharanos e Altaforja."},sec={{t="Guardião do Caminho de Cristálgida",b="Posicionado na fronteira nevada onde o Vale Cristálgida se abre para os desfiladeiros mais profundos de Dun Morogh, o Montanhista Thalos atua como a primeira linha de defesa para os viajantes que deixam os campos de treinamento dos anões. O Caminho de Cristálgida tornou-se um ponto de estrangulamento traiçoeiro, infestado por troggs hostis que cavaram seus caminhos das profundezas subterrâneas. Thalos permanece em vigília no frio, alertando os despreparados para que retornem e avaliando se os mensageiros destemidos possuem a coragem necessária para abrir caminho pelo reino afora."},{t="Um Ponto de Checagem para Mensageiros",b="Quando Grolin Barbabranca conclui seu relatório sobre os movimentos dos trolls Jubafria no vale isolado, o mensageiro encarregado de levá-lo ao seu irmão Senir em Kharanos é orientado a falar com o Montanhista Thalos antes de entrar no túnel. Após constatar que o aventureiro tem a capacidade de encarar a passagem infestada, Thalos o encaminha até Kharanos, onde os comandantes regionais coordenam a defesa de Dun Morogh. Sua presença vigilante assegura que informações vitais cheguem aos líderes militares de Altaforja em vez de se perderem na neve."}},faq={{q="Quem é o Montanhista Thalos?",a="O Montanhista Thalos é um montanhista de Altaforja posicionado na abertura sul do Caminho de Cristálgida. Seu posto guarda o limiar entre o Vale Cristálgida e as extensões mais amplas de Dun Morogh.",al={"história de thalos","quem é thalos","montanhista thalos"}},{q="Por que o Montanhista Thalos está alertando os viajantes a se afastarem?",a="Uma perigosa infestação de troggs Queixocerro tomou conta do Caminho de Cristálgida. Thalos alerta civis e combatentes novatos para não tentarem a travessia, permitindo apenas que mensageiros capacitados e guerreiros endurecidos se aventurem em seu interior.",al={"por que o caminho está fechado","troggs no caminho","perigo no caminho de cristálgida"}},{q="Para onde o Montanhista Thalos envia os aventureiros?",a="Após analisar os relatórios urgentes de campo que chegam do Vale Cristálgida, Thalos orienta os viajantes a seguirem pela passagem em direção a Kharanos, o assentamento mais próximo no caminho para Altaforja.",al={"onde ir depois de thalos","destino de thalos","próxima cidade"}},{q="Qual relatório Thalos recebe de Senir Barbabranca?",a="Nenhum vindo diretamente de Senir. O relatório que passa por Thalos é o relato de Grolin Barbabranca sobre a ameaça dos trolls Jubafria no Vale Cristálgida, levado por um mensageiro com destino ao irmão de Grolin, Senir, em Kharanos. Thalos alerta o mensageiro sobre os troggs e o envia através do túnel.",al={"observações de senir","despacho de senir","o que thalos lê"}},{q="A qual facção pertence o Montanhista Thalos?",a="Thalos é um membro juramentado dos Montanhistas de Altaforja, os rústicos patrulheiros da fronteira encarregados de patrulhar as fronteiras, os túneis e as trilhas montanhosas varridas pela neve de Dun Morogh para a Aliança.",al={"facção de thalos","thalos é de altaforja","montanhistas aliança"}},{q="O Caminho de Cristálgida é intransitável sem falar com Thalos?",a="A passagem está fisicamente aberta para quem tiver a coragem de entrar nela, mas falar com Thalos garante que o aventureiro entregue um reconhecimento vital em Kharanos e fique ciente dos perigos adiante.",al={"preciso falar com thalos","ignorar thalos"}}},fx={["37207617"]={q="O que o Montanhista Thalos quer?",a="O Montanhista Thalos quer manter os viajantes seguros, alertando-os sobre o traiçoeiro Caminho de Cristálgida. O túnel foi invadido por troggs hostis, tornando a passagem perigosa para qualquer um despreparado. Quando ele encontra aventureiros com negócios urgentes, ele os incentiva a caminhar com cautela pelo túnel e levar o relatório de Grolin Barbabranca em segurança até seu irmão Senir na cidade anã de Kharanos.",al={"o que thalos quer","objetivo de thalos","propósito do montanhista thalos"}},ae07b8df={q="Com quem o Montanhista Thalos está vinculado?",a="Thalos serve como sentinela para os montanhistas de Altaforja, guardando o caminho que sai do Vale Cristálgida. Correios que levam o relatório de Grolin Barbabranca sobre os trolls Presa-de-Gelo para o irmão de Grolin, Senir Barbabranca em Kharanos, são enviados para falar com Thalos antes de enfrentar o túnel infestado de troggs.",al={"aliados de thalos","com quem thalos trabalha","thalos senir barbabranca"}}},fp="18,308,26.499.0,22.529.0,26.194.0,49.215.0,47.175.0,54.285.0,47.186.0,56.191.0"}
P.entries["npc:mr-smite"] = {n="Sr. Castiga",s="O Sr. Castiga é o imponente imediato tauren que serve a bordo da nau-capitânia da Irmandade Défias nas profundezas das Minas Mortas. Um mestre de armas especialista sob o comando do Capitão Peleverde, ele comanda a aproximação das docas ao colossal navio de guerra oculto com disciplina implacável. Invasores que o enfrentam precisam lidar com seu arsenal mutável e sua devastadora força física.",h="O Sr.",kw={"capitão peleverde","minas mortas","imediato","covil encouraçado","sr. castiga","martelo poderoso do castiga","sulcador do castiga","tauren pirata","lâmina do ladrão"},ang={["class:Warrior"]="Castiga demonstra uma notável disciplina marcial, alternando perfeitamente entre golpes rápidos com uma mão, machados de empunhadura dupla e punitivos golpes de martelo com as duas mãos.",["faction:Alliance"]="Castiga atua como a principal barreira impedindo que agentes da Aliança invadam a prancha de embarque para alcançar o Capitão Peleverde e Edwin VanCleef.",["race:Tauren"]="Ver um companheiro tauren servindo como um imediato sanguinário entre foras da lei navegantes nos Reinos do Leste é uma visão desconcertante para qualquer viajante de Mulgore."},sec={{t="Imediato do Covil",b="Guardando as docas do Covil Encouraçado, o Sr. Castiga serve como imediato do capitão goblin Capitão Peleverde. Enquanto a Irmandade Défias é predominantemente composta por humanos marginalizados e engenhoqueiros goblins aliados, Castiga se destaca como uma impressionante anomalia: um tauren maciço, calejado por batalhas, longe das planícies de Kalimdor. Encarregado de manter uma ordem estrita em meio a uma tripulação pirata turbulenta, ele garante que os trabalhos de armamento do encouraçado secreto de Edwin VanCleef prossigam sem interrupções."},{t="Um Mestre de Armas Letal",b="Castiga não é meramente um capanga brutal; ele é um mestre de armas teatral e versátil. Ele se diverte em brincar com pretensos heróis, prolongando deliberadamente o combate para oferecer aos oponentes uma falsa sensação de esperança. Quando pressionado, ele desfere um pisão desconcertante e destruidor, que deixa os inimigos atordoados enquanto ele vasculha seu baú de armas próximo. Começando o combate com uma ágil lâmina de duelo, ele passa a usar devastadores machados duplos e, finalmente, recorre ao seu colossal martelo de guerra de duas mãos quando profundamente provocado."}},faq={{q="Por que um tauren está trabalhando com bandidos humanos em Cerro Oeste?",a="Embora a grande maioria dos taurens viva em Kalimdor ao lado de seus aliados da Horda, párias mercenários e viajantes ocasionalmente encontram o caminho para o leste. Castiga serve à Irmandade Défias como imediato do Capitão Peleverde, mantendo a tripulação na linha no covil enquanto o encouraçado é preparado para o mar.",al={"por que tauren em minas mortas","história do sr. castiga","tauren pirata"}},{q="Quem é o superior do Sr. Castiga?",a="Castiga responde diretamente ao Capitão Peleverde, o mestre goblin da embarcação pirata ancorada no Covil Encouraçado. Acima de ambos na conspiração geral está Edwin VanCleef, o grande líder da Irmandade Défias.",al={"quem é o chefe do castiga","para quem o sr. castiga trabalha"}},{q="Quais armas o Sr. Castiga usa durante a luta?",a="Castiga inicia a batalha com uma Thief's Blade. Conforme o combate se volta contra ele, ele recua até o seu baú para equipar um par de Smite's Reavers e, por fim, saca o Smite's Mighty Hammer ao ser levado aos seus limites.",al={"armas do castiga","o que o castiga tira do baú"}},{q="Onde o Sr. Castiga pode ser encontrado?",a="O Sr. Castiga vigia os píeres de madeira do Covil Encouraçado, a caverna final dentro das Minas Mortas, guardando a prancha de embarque que leva ao gigantesco encouraçado Défias.",al={"localização do sr. castiga","onde fica o castiga"}},{q="O Sr. Castiga luta sozinho?",a="Castiga mantém dois ladinos Défias furtivos ocultos ao seu lado, prontos para emboscar quaisquer invasores que avancem pelo píer em direção ao navio.",al={"ajudantes do castiga","guarda-costas do castiga"}},{q="O que torna o Sr. Castiga tão perigoso em combate corpo a corpo?",a="Sua característica War Stomp de tauren envia ondas de choque pela doca de madeira, atordoando grupos inteiros de aventureiros por tempo suficiente para que ele se rearme em seu baú e retome o ataque com armas mais pesadas.",al={"atordoamento do castiga","pisada de guerra do castiga"}}},fx={ecfcf591={q="Quem é o Sr. Castiga?",a="O Sr. Castiga é um formidável mestre de armas tauren que serve como imediato a bordo do colosso escondido nas profundezas das Minas Mortas. Trabalhando diretamente sob o Capitão Peleverde, ele comanda as defesas do cais da Irmandade Défias e mantém seus canalhas na linha com mão de ferro e um arsenal de armas mortais.",al={"quem é castiga","identidade sr castiga","o que é o sr castiga"}},["8cad5068"]={q="De que lado está o Sr. Castiga?",a="Apesar de ser um tauren, o Sr. Castiga não deve lealdade à Horda ou ao seu povo em Kalimdor. Ele está firmemente alinhado à Irmandade Défias de Edwin VanCleef, servindo como segundo no comando do comandante naval goblin deles, o Capitão Peleverde.",al={"facção do sr castiga","para quem castiga trabalha","castiga é horda ou défias"}},["1c026e95"]={q="Por que o Sr. Castiga é famoso ou temido?",a="Castiga é temido por sua brutalidade física pura e domínio de combate errático. Ele é notório por brincar com suas vítimas, deixando-as acreditar que ganharam vantagem antes de atordoá-las com um pisão que faz a terra tremer e sacar armas cada vez mais letais de seu peito para acabar com elas.",al={"por que o sr castiga é temido","reputação sr castiga","por que castiga é famoso"}}},fp="9,349,22.480.0,21.512.0,55.298.0,28.219.0,49.205.0,29.166.0,27.133.0,52.214.0"}
P.entries["npc:mull-thunderhorn"] = {n="Mull Chifre Troante",s="Mull Chifre Troante é um ancião tauren que reside na Aldeia Casco Sangrento, em Mulgore. Profundamente devotado à Mãe Terra e ao equilíbrio da terra, ele vigia os poços de água sagrados espalhados pelas planícies. Conforme exploradores externos ameaçam as águas vitais da região, Mull guia os jovens taurens através dos rituais necessários para purificar as fontes ancestrais.",h="Mull Chifre Troante é um ancião tauren que reside na Aldeia Casco Sangrento, em Mulgore.",kw={"aldeia casco sangrento","mulgore","mull chifre troante","poison water","thunderhorn totem","empreendimentos s.a.","poços de água","wildmane cleansing","winterhoof cleansing"},ang={["class:Druid"]="Druidas compartilham da urgência de Mull, testemunhando em primeira mão como os poços de água corrompidos envenenam o equilíbrio da vida selvagem de Mulgore.",["class:Shaman"]="Xamãs reconhecerão a confiança de Mull na harmonia elemental, já que seus totens de purificação utilizam espíritos ancestrais para restaurar águas dilaceradas pela ganância mecânica.",["faction:Horde"]="A luta de Mull enfatiza o atrito da Horda com organizações exploradoras e sem alinhamento, como a Empreendimentos S.A., que pilham as riquezas de Kalimdor sem consentimento.",["race:Tauren"]="Para os taurens, Mull Chifre Troante representa a memória tribal e o dever ancestral, guiando jovens bravos na proteção das planícies sagradas contra invasores estrangeiros gananciosos."},sec={{t="Guardião das Águas Sagradas",b="Montando guarda na Aldeia Casco Sangrento, Mull Chifre Troante carrega o peso do bem-estar espiritual de Mulgore. As tribos nômades se reuniram sob a liderança do Grande Chefe Caerne Casco Sangrento para estabelecer um lar permanente, mas suas terras já estão sob cerco pela ganância e pela expansão inconsequente. Mull atua como um esteio espiritual para os jovens bravos que saem da Aldeia Narache, convocando-os a proteger os recursos vitais de seus ancestrais."},{t="Poços Contaminados e a Empreendimentos S.A.",b="A principal crise enfrentada por Mull é a súbita enfermidade que se espalha pelas fontes de água de Mulgore: os poços de água Winterhoof, Thunderhorn e Wildmane. Essa aflição imunda é atribuída aos goblins da Empreendimentos S.A., uma organização comercial inescrupulosa que instala operações nas colinas circundantes e despeja venenos no lençol freático local. Mull orienta os jovens taurens a preparar totens de purificação específicos e a realizar ritos de purificação em cada poço ancestral antes que a corrupção se espalhe irrevogavelmente pela terra e por sua vida selvagem."}},faq={{q="Quem é Mull Chifre Troante?",a="Mull Chifre Troante é um doador de missões tauren situado na Aldeia Casco Sangrento, em Mulgore. Ele atua como guardião dos poços de água sagrados da região, oferecendo ritos e rituais para manter a terra e suas águas puras da contaminação externa.",al={"história de mull chifre troante","quem é mull","aldeia casco sangrento mull"}},{q="Por que Mull Chifre Troante está preocupado com os poços de água?",a="Os poços de água ancestrais — como os poços Winterhoof, Thunderhorn e Wildmane — são fontes vitais para as tribos e para a vida selvagem de Mulgore. Operações invasivas nas proximidades contaminaram essas fontes sagradas com efluentes nocivos e poluição, ameaçando o equilíbrio natural das planícies.",al={"por que os poços estão envenenados","poços de água mulgore","poço winterhoof envenenado"}},{q="Quem está poluindo os poços de água em Mulgore?",a="A poluição é causada pela Empreendimentos S.A., uma empresa goblin inconsequente que estabelece postos avançados de mineração e exploração madeireira industrial nas bordas de Mulgore. Suas operações não mostram consideração alguma pela paisagem sagrada, derramando toxinas industriais no lençol freático local.",al={"quem envenenou a água","empreendimentos s.a. em mulgore","quem contaminou os poços"}},{q="Por que as missões de purificação de Mull envolvem apenas taurens?",a="Os poços de água possuem profundo significado ancestral e espiritual, ligado às linhagens fundadoras das tribos taurens — incluindo os clãs Thunderhorn, Winterhoof e Wildmane. Purificá-los é visto como um sagrado rito de passagem e um dever cultural para os taurens que chegam à maturidade.",al={"missões exclusivas de tauren","por que apenas taurens","requisitos de mull chifre troante"}},{q="Como os poços de água são purificados?",a="Mull instrui os viajantes a montar totens especialmente consagrados e imbricados com oferendas da terra, como patas, garras e dentes das feras de Mulgore. Uma vez consagrados, esses totens são levados diretamente aos poços corrompidos para canalizar a purificação espiritual e lavar as toxinas não naturais.",al={"como purificar poços","totens de purificação","purificando a água"}},{q="O que é o Rite of Vision?",a="O Rite of Vision é uma jornada espiritual fundamental realizada por jovens taurens para comungar com seus ancestrais e espíritos animais. Os iniciados são enviados a Zarlman Duas Luas, na Aldeia Casco Sangrento, para realizar essa provação visionária como um dos Rites of the Earthmother.",al={"missão do rite of vision","o que é rite of vision"}}},fx={["7b9ffdeb"]={q="De que lado está Mull Chifre Troante?",a="Mull mantém-se leal ao seu povo e à Horda, devotado às tribos que habitam Mulgore. Como um membro respeitado da Aldeia Casco Sangrento, ele vigia as planícies ancestrais e atende ao chamado espiritual para proteger seu povo e suas terras sagradas da corrupção externa.",al={"facção de mull chifre troante","mull é horda","a quem mull serve"}},be00c091={q="O que Mull Chifre Troante quer?",a="Mull quer restaurar e purificar os poços de água sagrados de Mulgore, incluindo as fontes Casco-de-Inverno, Chifre Troante e Juba Selvagem. Ele busca taurens confiáveis para criar totens tradicionais e realizar os ritos de purificação vitais necessários para desfazer a contaminação vil que ameaça a força vital da terra.",al={"o que mull quer","objetivo de mull chifre troante","por que mull precisa de ajuda"}}},fp="16,359,29.438.0,37.540.1,24.237.0,54.293.0,44.271.0,54.266.0,33.307.0,27.268.0"}
